def _appframe_v10_base_profile_target(
    target_id: str,
    manifest_path: str,
    target: Any,
) -> Any:
    """Validate and retain the exact reviewed AppFrame base compile context.

    The v9 STL queue define suppressed two authored bodies from the registered
    one-TU population, so it is not a valid target-wide compile projection.
    This finite validator keeps the live manifest target unchanged and rejects
    target, population, profile, flag, or queue-define drift before compile.
    """

    if target_id != APPFRAME_V9_TARGET_ID:
        return target

    label = "AppFrame v10 base call-contract compile profile"
    if (
        manifest_path != APPFRAME_V9_MANIFEST_PATH
        or "\\" in manifest_path
        or getattr(target, "name", "") != APPFRAME_V9_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or Path(getattr(target, "manifest_path", "")).resolve()
        != (REPO_ROOT / APPFRAME_V9_MANIFEST_PATH).resolve()
        or getattr(target, "source_from", "") != APPFRAME_V9_SOURCE_PATH
        or getattr(target, "source_filename", "") != "RecoilApp.cpp"
        or tuple(getattr(target, "source_files", ())) != ()
        or not getattr(target, "check_translation_unit_function_order", False)
    ):
        raise ProgressError(
            f"{label} rejects target, manifest, source, or TU registration drift"
        )

    entries = tuple(getattr(target, "translation_unit_function_order", ()))
    functions = tuple(getattr(entries[0], "functions", ())) if len(entries) == 1 else ()
    if (
        len(entries) != 1
        or getattr(entries[0], "source_from", "") != APPFRAME_V9_SOURCE_PATH
        or getattr(entries[0], "order_scope", "") != "authored"
        or tuple(getattr(function, "address", "") for function in functions)
        != APPFRAME_V9_ADDRESSES
        or tuple(getattr(function, "symbol", "") for function in functions)
        != APPFRAME_V9_SYMBOLS
        or tuple(getattr(function, "pipeline_class", "") for function in functions)
        != ("non-authored", "non-authored") + ("authored",) * 17
        or tuple(
            getattr(function, "authored_order_role", "") for function in functions
        )
        != ("non-authored", "non-authored") + ("authored-body",) * 17
        or len(set(APPFRAME_V9_ADDRESSES)) != len(APPFRAME_V9_ADDRESSES)
    ):
        raise ProgressError(
            f"{label} rejects translation-unit or complete address population drift"
        )

    profile, flags = effective_source_compile_context(
        target, APPFRAME_V9_SOURCE_PATH
    )
    flags = tuple(str(flag) for flag in flags)
    folded = tuple(flag.upper() for flag in flags)
    queue_define_name = APPFRAME_V9_QUEUE_DEFINE[2:].upper()
    queue_defines = tuple(
        flag
        for flag in flags
        if flag.upper().startswith("/D")
        and flag[2:].partition("=")[0].upper() == queue_define_name
    )
    if (
        profile != APPFRAME_V9_PROFILE_NAME
        or flags != APPFRAME_V9_BASE_FLAGS
        or queue_defines
        or folded.count("/TP") != 1
        or folded.count("/MD") != 1
        or folded.count("/O2") != 1
        or folded.count("/OB1") != 1
        or folded.count("/GX") != 1
        or folded.count("/GR") != 1
        or folded.count("/ZP4") != 1
        or folded.count("/FACS") != 1
        or folded[-1] != "/FACS"
    ):
        raise ProgressError(
            f"{label} rejects effective profile, flag, define, or duplicate drift"
        )

    source_key = canonical_source_key(APPFRAME_V9_SOURCE_PATH)
    profile_rows = tuple(getattr(target, "source_compile_profiles", ()))
    flag_rows = tuple(getattr(target, "source_compile_flags", ()))
    if (
        [key for key, _value in profile_rows].count(source_key) != 1
        or [key for key, _value in flag_rows].count(source_key) != 1
    ):
        raise ProgressError(
            f"{label} requires one exact source-specific compile context"
        )
    return target


def _call_contract_slice_targets(
    document: ProgressDocument,
    slice_row: Mapping[str, Any],
    *,
    repository_path_inventory: RepositoryPathInventory | None = None,
) -> dict[str, Any]:
    """Load the exact selected target manifests without compiling them."""

    inventory = repository_path_inventory or load_repository_path_inventory(
        REPO_ROOT
    )
    result: dict[str, Any] = {}
    for target_id, _registration, manifest_path in (
        _call_contract_target_registrations(document, slice_row)
    ):
        try:
            repository_manifest = resolve_repository_file(
                manifest_path,
                repository_root=inventory.repository_root,
                inventory=inventory,
                context=f"call-contract target {target_id} manifest",
                allowed_suffixes={".json"},
            )
        except RepositoryPathError as exc:
            raise ProgressError(str(exc)) from exc
        target = load_manifest(
            repository_manifest.physical_path,
            repository_path_inventory=inventory,
        )
        require_clean_target_source_fragments(target)
        result[target_id] = _appframe_v10_base_profile_target(
            target_id,
            manifest_path,
            target,
        )
    return result


def _call_contract_repository_include_roots() -> tuple[tuple[str, Path], ...]:
    try:
        config = json.loads(
            DEFAULT_FINAL_BUILD_MANIFEST.read_text(encoding="utf-8")
        )
    except (OSError, json.JSONDecodeError) as exc:
        raise ProgressError(
            "call-contract include closure cannot read the final-build "
            f"include-root contract: {exc}"
        ) from exc
    raw_include_dirs = config.get("include_dirs")
    if not isinstance(raw_include_dirs, list):
        raise ProgressError(
            "call-contract final-build include_dirs must be a list"
        )

    root = REPO_ROOT.resolve()
    result: list[tuple[str, Path]] = []
    seen: set[str] = set()
    for index, raw_value in enumerate(raw_include_dirs):
        if not isinstance(raw_value, str) or not raw_value:
            raise ProgressError(
                "call-contract final-build include_dirs entries must be "
                f"non-empty strings: index {index}"
            )
        include_dir = Path(raw_value)
        candidate = (
            include_dir.resolve()
            if include_dir.is_absolute()
            else (root / include_dir).resolve()
        )
        try:
            candidate.relative_to(root)
        except ValueError:
            # External compiler/SDK roots are deliberately outside the
            # repository-local editable dependency closure.
            continue
        if include_dir.is_absolute():
            # An absolute repository include root is a physical configuration
            # defect, not a route for manufacturing a current logical path.
            raise ProgressError(
                "call-contract repository include root must use a "
                f"repository-relative spelling: {raw_value}"
            )
        try:
            logical_root = validate_repository_relative_path(
                raw_value,
                context="call-contract repository include root",
            )
        except RepositoryPathError as exc:
            raise ProgressError(str(exc)) from exc
        if not candidate.is_dir() and logical_root.startswith("support/"):
            canonical_support_candidate = (
                DEFAULT_REFERENCE.parents[1] / Path(logical_root)
            ).resolve()
            if canonical_support_candidate.is_dir():
                candidate = canonical_support_candidate
        if not candidate.is_dir():
            raise ProgressError(
                "call-contract repository include root does not exist or is "
                f"not a directory: {raw_value}"
            )
        key = str(candidate).casefold()
        if key not in seen:
            seen.add(key)
            result.append((logical_root, candidate))
    return tuple(result)


def _call_contract_final_build_source_map(
    config: Any,
    *,
    inventory: RepositoryPathInventory | None = None,
) -> tuple[
    dict[str, list[tuple[str, Path]]],
    tuple[dict[str, Any], ...],
]:
    """Project final-build source rows through exact current repository identities.

    The checked-in final-build configuration may retain historical case-only
    spellings.  Those spellings are diagnosed as stale and never become the
    current logical result; the returned map is keyed by exact current repository
    paths and uses their separately authenticated physical files.
    """

    repository_inventory = inventory or load_repository_path_inventory(REPO_ROOT)
    explicit_repository_paths = getattr(config, "source_repository_paths", None)
    if explicit_repository_paths is not None:
        if (
            not isinstance(explicit_repository_paths, (tuple, list))
            or len(explicit_repository_paths) != len(tuple(getattr(config, "sources", ())))
            or any(not isinstance(path, str) or not path for path in explicit_repository_paths)
        ):
            raise ProgressError(
                "call-contract explicit final-build source registry is malformed"
            )
        result: dict[str, list[tuple[str, Path]]] = {}
        for repository_path, configured_path in zip(explicit_repository_paths, config.sources):
            try:
                tracked = resolve_repository_file(
                    repository_path,
                    repository_root=repository_inventory.repository_root,
                    inventory=repository_inventory,
                    context="call-contract explicit final-build source",
                    allowed_suffixes=CALL_CONTRACT_SOURCE_SUFFIXES,
                )
            except RepositoryPathError as exc:
                raise ProgressError(str(exc)) from exc
            if os.path.normcase(str(Path(configured_path).resolve())) != os.path.normcase(
                str(tracked.physical_path)
            ):
                raise ProgressError(
                    "call-contract explicit final-build source does not match "
                    f"its exact repository file: {repository_path}"
                )
            result.setdefault(tracked.repository_path.casefold(), []).append(
                (tracked.repository_path, tracked.physical_path)
            )
        return result, ()
    try:
        repository_manifest = resolve_repository_file(
            _call_contract_final_build_manifest_logical_path(),
            repository_root=repository_inventory.repository_root,
            inventory=repository_inventory,
            context="call-contract final-build manifest",
            allowed_suffixes={".json"},
        )
        raw = json.loads(
            repository_manifest.physical_path.read_text(encoding="utf-8")
        )
    except (RepositoryPathError, OSError, json.JSONDecodeError) as exc:
        raise ProgressError(
            f"call-contract final-build source registry cannot be read: {exc}"
        ) from exc
    raw_sources = raw.get("sources") if isinstance(raw, Mapping) else None
    if (
        not isinstance(raw_sources, list)
        or any(not isinstance(path, str) or not path for path in raw_sources)
        or len(raw_sources) != len(tuple(getattr(config, "sources", ())))
    ):
        raise ProgressError(
            "call-contract final-build source registry is malformed or does "
            "not match the parsed configuration"
        )

    result: dict[str, list[tuple[str, Path]]] = {}
    diagnostics: list[dict[str, Any]] = []
    for raw_path, configured_path in zip(raw_sources, config.sources):
        try:
            diagnosis = diagnose_historical_repository_path(
                raw_path,
                inventory=repository_inventory,
            )
        except RepositoryPathError as exc:
            raise ProgressError(str(exc)) from exc
        if diagnosis.status not in {
            "exact-historical",
            "historical-case-alias",
        } or not diagnosis.current_repository_path:
            raise ProgressError(
                "call-contract final-build source has no unique current repository "
                f"identity: {raw_path} ({diagnosis.status})"
            )
        try:
            tracked = resolve_repository_file(
                diagnosis.current_repository_path,
                repository_root=repository_inventory.repository_root,
                inventory=repository_inventory,
                context="call-contract final-build current source",
                allowed_suffixes=CALL_CONTRACT_SOURCE_SUFFIXES,
            )
        except RepositoryPathError as exc:
            raise ProgressError(str(exc)) from exc
        if os.path.normcase(str(Path(configured_path).resolve())) != os.path.normcase(
            str(tracked.physical_path)
        ):
            raise ProgressError(
                "call-contract parsed final-build source does not match its "
                f"current repository file: {raw_path}"
            )
        result.setdefault(tracked.repository_path.casefold(), []).append(
            (tracked.repository_path, tracked.physical_path)
        )
        if diagnosis.status == "historical-case-alias":
            diagnostics.append(
                {
                    "status": diagnosis.status,
                    "historical_path": diagnosis.historical_path,
                    "current_repository_path": diagnosis.current_repository_path,
                    "current": diagnosis.current,
                    "tracker_mutated": diagnosis.tracker_mutated,
                }
            )
    return result, tuple(diagnostics)


def _call_contract_vc5_preprocessor_defines(
    config: Any,
    source: Path,
) -> tuple[str, ...]:
    """Return the governed VC5 macro context for one final-build TU."""

    values: dict[str, str] = {}
    for raw in getattr(config, "defines", ()):
        name, separator, value = str(raw).partition("=")
        values[name] = value if separator and value else "1"
    flags = tuple(final_build_effective_compile_flags(config, source))
    upper_flags = tuple(flag.upper() for flag in flags)
    values.update({"_MSC_VER": "1100", "_WIN32": "1"})
    architecture = "300"
    for generation in (3, 4, 5, 6):
        if f"/G{generation}" in upper_flags:
            architecture = str(generation * 100)
    values["_M_IX86"] = architecture
    if any(flag in {"/MD", "/MDD", "/MT", "/MTD"} for flag in upper_flags):
        values["_MT"] = "1"
    if any(flag in {"/MD", "/MDD"} for flag in upper_flags):
        values["_DLL"] = "1"
    if any(flag in {"/MDD", "/MTD", "/LDd".upper()} for flag in upper_flags):
        values["_DEBUG"] = "1"
    if "/GX" in upper_flags and "/GX-" not in upper_flags:
        values["_CPPUNWIND"] = "1"
    for raw_flag in flags:
        if raw_flag.upper().startswith("/D") and len(raw_flag) > 2:
            name, separator, value = raw_flag[2:].partition("=")
            if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
                raise ProgressError(
                    f"call-contract final-build compile flag has invalid /D macro: {raw_flag}"
                )
            values[name] = value if separator and value else "1"
    return tuple(
        f"{name}={value}"
        for name, value in sorted(values.items())
    )


def _call_contract_cached_manifest(
    document: ProgressDocument,
    manifest_path: Path,
    *,
    repository_path_inventory: Any | None = None,
) -> Any:
    """Reuse one unchanged governed target manifest within this request."""

    canonical = manifest_path.resolve()
    try:
        before = canonical.stat()
    except OSError as exc:
        raise ProgressError(
            f"call-contract target manifest cannot be read: {manifest_path}: {exc}"
        ) from exc
    signature = (True, int(before.st_size), int(before.st_mtime_ns))
    cache_name = "_call_contract_target_manifest_cache_v1"
    cache = getattr(document, cache_name, None)
    if not isinstance(cache, dict):
        cache = {}
        setattr(document, cache_name, cache)
    cache_key = (canonical.as_posix(), signature)
    if cache_key in cache:
        return cache[cache_key]
    target = load_manifest(
        canonical,
        enforce_source_policy=False,
        repository_path_inventory=repository_path_inventory,
    )
    try:
        after = canonical.stat()
    except OSError as exc:
        raise ProgressError(
            "call-contract target manifest changed while loading: "
            f"{manifest_path}: {exc}"
        ) from exc
    if (True, int(after.st_size), int(after.st_mtime_ns)) != signature:
        raise ProgressError(
            "call-contract target manifest changed while loading: "
            f"{manifest_path}"
        )
    for stale_key in tuple(cache):
        if (
            isinstance(stale_key, tuple)
            and len(stale_key) == 2
            and stale_key[0] == cache_key[0]
            and stale_key != cache_key
        ):
            del cache[stale_key]
    cache[cache_key] = target
    return target


def _call_contract_callable_inventory_resolver(
    document: ProgressDocument,
    *,
    root: Path | None = None,
) -> Callable[[str, tuple[str, ...]], CallableInventory]:
    """Return a request-local, document-bound callable inventory resolver.

    Reuse is valid only for the same canonical file, exact governed define
    tuple, and current existence/size/mtime signature.  A file changing during
    the read or parse fails closed; nothing is persisted or shared with another
    ``ProgressDocument``.
    """

    repository_root = (root or REPO_ROOT).resolve()
    cache_name = "_call_contract_callable_inventory_cache_v1"
    cache = getattr(document, cache_name, None)
    if not isinstance(cache, dict):
        cache = {}
        setattr(document, cache_name, cache)
    path_cache_name = "_call_contract_callable_inventory_paths_v1"
    path_cache = getattr(document, path_cache_name, None)
    if not isinstance(path_cache, dict):
        path_cache = {}
        setattr(document, path_cache_name, path_cache)

    def signature(path: Path) -> tuple[bool, int, int]:
        try:
            stat = path.stat()
        except FileNotFoundError:
            return (False, 0, 0)
        except OSError as exc:
            raise ProgressError(
                "call-contract definition closure cannot stat "
                f"{path}: {exc}"
            ) from exc
        return (True, int(stat.st_size), int(stat.st_mtime_ns))

    def resolve(
        canonical_relative: str,
        defines: tuple[str, ...],
    ) -> CallableInventory:
        candidate = path_cache.get(canonical_relative)
        if not isinstance(candidate, Path):
            candidate = (repository_root / canonical_relative).resolve()
            try:
                candidate.relative_to(repository_root)
            except ValueError as exc:
                raise ProgressError(
                    "call-contract inventory path leaves the repository: "
                    f"{canonical_relative}"
                ) from exc
            path_cache[canonical_relative] = candidate
        canonical_path = candidate.as_posix()
        context = tuple(str(value) for value in defines)
        before = signature(candidate)
        cache_key = (canonical_path, context, before)
        cached = cache.get(cache_key)
        if isinstance(cached, CallableInventory):
            return cached
        if not before[0]:
            raise ProgressError(
                "call-contract definition closure source disappeared: "
                f"{canonical_relative}"
            )
        try:
            text = candidate.read_text(encoding="utf-8", errors="ignore")
        except OSError as exc:
            raise ProgressError(
                "call-contract definition closure cannot read "
                f"{canonical_relative}: {exc}"
            ) from exc
        after_read = signature(candidate)
        if after_read != before:
            raise ProgressError(
                "call-contract definition closure source changed while reading: "
                f"{canonical_relative}"
            )
        inventory = callable_inventory(text, defines=context)
        after_parse = signature(candidate)
        if after_parse != before:
            raise ProgressError(
                "call-contract definition closure source changed while parsing: "
                f"{canonical_relative}"
            )
        for stale_key in tuple(cache):
            if (
                isinstance(stale_key, tuple)
                and len(stale_key) == 3
                and stale_key[0] == canonical_path
                and stale_key[1] == context
                and stale_key != cache_key
            ):
                del cache[stale_key]
        cache[cache_key] = inventory
        return inventory

    return resolve


def _call_contract_source_closure_uncached(
    document: ProgressDocument,
    slice_row: Mapping[str, Any],
    *,
    repository_path_inventory: RepositoryPathInventory | None = None,
) -> CallContractSourceClosure:
    """Return exact registered/header/definition paths for one slice.

    Registered C/C++ implementation paths are the only traversal roots.
    Repository-local headers enter the closure only through a transitive quoted
    include from one of those roots. Matching implementation TUs are then
    derived from qualified declaration/definition keys under their governed
    final-build preprocessor contexts; callee identity alone grants no path.
    """

    repository_inventory = (
        repository_path_inventory
        or load_repository_path_inventory(REPO_ROOT)
    )
    root = repository_inventory.repository_root

    def canonical_existing_file(
        candidate: Path,
        *,
        context: str,
        required: bool,
    ) -> tuple[Path, str] | None:
        # This helper is used only for include traversal candidates assembled
        # from a current exact repository path plus a lexical quoted include.  Use the
        # inventory for the logical result; physical spelling is never
        # projected back into that result.
        try:
            lexical_relative = candidate.relative_to(root).as_posix()
        except ValueError as exc:
            raise ProgressError(
                f"{context} leaves the repository: {candidate}"
            ) from exc
        matches = repository_inventory.casefolded_paths.get(
            lexical_relative.casefold(), ()
        )
        if lexical_relative in repository_inventory.exact_paths:
            repository_path = lexical_relative
        elif not matches and not required:
            return None
        elif len(matches) == 1:
            # A quoted include operand is relative to compiler include roots,
            # not itself a repository-relative identity.  Resolve the unique
            # repository candidate for traversal while retaining only its exact
            # repository spelling in the public closure.
            repository_path = matches[0]
        elif not matches:
            raise ProgressError(f"{context} is outside the repository inventory: {candidate}")
        else:
            raise ProgressError(
                f"{context} has ambiguous repository casing: {candidate}"
            )
        try:
            tracked = resolve_repository_file(
                repository_path,
                context=context,
                repository_root=root,
                inventory=repository_inventory,
            )
        except RepositoryPathError as exc:
            if not required and exc.kind in {"unknown-path", "repository-file-missing"}:
                return None
            raise ProgressError(str(exc)) from exc
        return tracked.physical_path, tracked.repository_path

    def normalized_source_roots(
        value: Any,
        *,
        context: str,
        include_headers: bool = False,
    ) -> tuple[str, ...]:
        """Filter path metadata to exact C/C++ traversal/edit roots.

        Headers are validated as repo-local C/C++ metadata but enter only
        through the transitive quoted-include closure. Exact ``semantic:``
        no-suffix placement labels are ignored; every other non-C/C++ value
        fails closed. Source-looking values still pass through existence and
        exact-casing validation before becoming roots.
        """

        if value is None:
            return ()
        if not isinstance(value, list):
            raise ProgressError(f"{context}: order_edit_paths must be a list")
        selected: list[str] = []
        permitted_suffixes = (
            CALL_CONTRACT_SOURCE_SUFFIXES | CALL_CONTRACT_HEADER_SUFFIXES
        )
        for index, item in enumerate(value):
            if not isinstance(item, str) or not item:
                raise ProgressError(
                    f"{context}: order_edit_paths[{index}] must be a non-empty string"
                )
            suffix = Path(item).suffix.casefold()
            if item.startswith("semantic:") and not suffix:
                continue
            if suffix not in permitted_suffixes:
                raise ProgressError(
                    f"{context}: order_edit_paths[{index}] is not a C/C++ source or header: {item}"
                )
            if suffix in CALL_CONTRACT_SOURCE_SUFFIXES or include_headers:
                selected.append(item)
        try:
            return normalize_order_edit_paths(
                selected,
                context=context,
                repository_root=root,
                inventory=repository_inventory,
            )
        except ValueError as exc:
            raise ProgressError(str(exc)) from exc

    registered_paths: list[str] = []
    source_edit_paths: list[str] = []
    # Original slice source_paths are historical scheduling evidence.  They
    # must not override the current tracked target manifests or become current
    # merely through case-fold reconciliation.
    raw_overrides = slice_row.get("source_edit_paths_override", {})
    if raw_overrides is None:
        raw_overrides = {}
    if not isinstance(raw_overrides, Mapping):
        raise ProgressError(
            "call-contract internal source_edit_paths_override must be an object"
        )

    for target_id, registration, manifest_value in (
        _call_contract_target_registrations(document, slice_row)
    ):
        try:
            repository_manifest = resolve_repository_file(
                manifest_value,
                repository_root=root,
                inventory=repository_inventory,
                context=f"call-contract target {target_id} manifest",
                allowed_suffixes={".json"},
            )
        except RepositoryPathError as exc:
            raise ProgressError(str(exc)) from exc
        manifest = _call_contract_cached_manifest(
            document,
            repository_manifest.physical_path,
            repository_path_inventory=repository_inventory,
        )
        raw_order_edit_paths = _call_contract_target_source_edit_roots(
            target_id=target_id,
            registration=registration,
            manifest=manifest,
            override_paths=raw_overrides.get(target_id),
            strict_internal_scope=(
                slice_row.get("selection_mode")
                in {
                    "target-all-authored-bodies",
                    "phase-all-authored-bodies",
                }
            ),
            repository_path_inventory=repository_inventory,
        )
        target_edit_paths = normalized_source_roots(
            raw_order_edit_paths,
            context=f"call-contract target {target_id}",
            include_headers=True,
        )
        source_edit_paths.extend(target_edit_paths)
        registered_paths.extend(
            path
            for path in target_edit_paths
            if Path(path).suffix.casefold() in CALL_CONTRACT_SOURCE_SUFFIXES
        )

    editable: dict[str, str] = {}
    included_paths: dict[str, str] = {}
    registered_sources: dict[str, str] = {}
    pending: list[tuple[str, Path]] = []
    for edit_path in source_edit_paths:
        try:
            tracked = resolve_repository_file(
                edit_path,
                repository_root=root,
                inventory=repository_inventory,
                context="call-contract registered source-edit path",
                allowed_suffixes=(
                    CALL_CONTRACT_SOURCE_SUFFIXES
                    | CALL_CONTRACT_HEADER_SUFFIXES
                ),
            )
        except RepositoryPathError as exc:
            raise ProgressError(str(exc)) from exc
        editable.setdefault(tracked.repository_path.casefold(), tracked.repository_path)
    for registered_path in registered_paths:
        if Path(registered_path).suffix.casefold() not in (
            CALL_CONTRACT_SOURCE_SUFFIXES
        ):
            continue
        try:
            tracked = resolve_repository_file(
                registered_path,
                repository_root=root,
                inventory=repository_inventory,
                context="call-contract registered source path",
                allowed_suffixes=CALL_CONTRACT_SOURCE_SUFFIXES,
            )
        except RepositoryPathError as exc:
            raise ProgressError(str(exc)) from exc
        key = tracked.repository_path.casefold()
        if key not in registered_sources:
            registered_sources[key] = tracked.repository_path
            included_paths[key] = tracked.repository_path
            pending.append((tracked.repository_path, tracked.physical_path))
    if not pending:
        raise ProgressError(
            "call-contract slice has no registered C/C++ source files"
        )

    include_roots = _call_contract_repository_include_roots()
    scanned: set[str] = set()
    while pending:
        source_repository_path, source_path = pending.pop(0)
        source_key = source_repository_path.casefold()
        if source_key in scanned:
            continue
        scanned.add(source_key)
        try:
            text = source_path.read_text(encoding="utf-8", errors="ignore")
        except OSError as exc:
            raise ProgressError(
                f"call-contract include closure cannot read {source_path}: {exc}"
            ) from exc
        for match in CALL_CONTRACT_INCLUDE_DIRECTIVE_RE.finditer(text):
            operand = match.group("operand").strip()
            if operand.startswith("<"):
                continue
            if not operand.startswith('"'):
                # Macro/system selection is outside the repository-local quoted
                # include contract.
                continue
            quoted = CALL_CONTRACT_QUOTED_INCLUDE_OPERAND_RE.fullmatch(
                operand
            )
            if quoted is None:
                raise ProgressError(
                    "call-contract source has a malformed quoted include at "
                    f"{source_repository_path}:"
                    f"{text.count(chr(10), 0, match.start()) + 1}"
                )
            include_text = quoted.group("path")
            include_posix = PurePosixPath(include_text)
            include_components = include_text.split("/")
            if (
                "\\" in include_text
                or include_posix.is_absolute()
                or re.match(r"^[A-Za-z]:", include_text)
                or ":" in include_text
                or any(
                    component in {"", ".", ".."}
                    for component in include_components
                )
            ):
                raise ProgressError(
                    "call-contract source has a malformed or escaping quoted "
                    f"include {include_text!r} in "
                    f"{source_repository_path}"
                )
            if include_posix.suffix.casefold() not in (
                CALL_CONTRACT_HEADER_SUFFIXES
            ):
                continue

            resolved_include: tuple[Path, str] | None = None
            source_parent = PurePosixPath(source_repository_path).parent.as_posix()
            candidate_roots = (
                (source_parent, source_path.parent),
                *include_roots,
            )
            seen_candidates: set[str] = set()
            for logical_root, include_root in candidate_roots:
                logical_candidate = (
                    f"{logical_root}/{include_text}"
                    if logical_root not in {"", "."}
                    else include_text
                )
                candidate = root.joinpath(*logical_candidate.split("/"))
                candidate_key = logical_candidate.casefold()
                if candidate_key in seen_candidates:
                    continue
                seen_candidates.add(candidate_key)
                resolved_include = canonical_existing_file(
                    candidate,
                    context=(
                        "call-contract quoted include "
                        f"{include_text!r} from "
                        f"{source_repository_path}"
                    ),
                    required=False,
                )
                if resolved_include is not None:
                    break
            if resolved_include is None:
                continue
            resolved, canonical_relative = resolved_include
            key = canonical_relative.casefold()
            if key not in included_paths:
                included_paths[key] = canonical_relative
                pending.append((canonical_relative, resolved))

    header_paths = tuple(
        sorted(
            (
                path
                for path in included_paths.values()
                if Path(path).suffix.casefold() in CALL_CONTRACT_HEADER_SUFFIXES
            ),
            key=lambda path: (path.casefold(), path),
        )
    )
    final_config = load_final_build_config(DEFAULT_FINAL_BUILD_MANIFEST)
    context_by_source: dict[str, tuple[str, ...]] = {}
    source_texts: list[tuple[str, str, tuple[str, ...]]] = []
    for source in final_config.sources:
        canonical = canonical_existing_file(
            source,
            context="call-contract final-build source",
            required=True,
        )
        assert canonical is not None
        resolved, canonical_relative = canonical
        context = _call_contract_vc5_preprocessor_defines(
            final_config,
            resolved,
        )
        context_by_source[canonical_relative.casefold()] = context
        source_texts.append((canonical_relative, "", context))

    header_contexts = tuple(sorted(set(context_by_source.values())))
    header_texts: list[tuple[str, str, tuple[str, ...]]] = []
    for header_path in header_paths:
        header_texts.extend(
            (header_path, "", context) for context in header_contexts
        )
    inventory_resolver = _call_contract_callable_inventory_resolver(
        document, root=root
    )
    try:
        definition_resolution_result = resolve_reviewed_definition_sources(
            reviewed_callables=(),
            header_texts=header_texts,
            source_texts=source_texts,
            inventory_resolver=inventory_resolver,
        )
    except ValueError as exc:
        raise ProgressError(str(exc)) from exc
    definition_sources = definition_resolution_result.source_paths
    editable_header_paths = tuple(
        sorted(
            (
                path
                for path in editable.values()
                if Path(path).suffix.casefold()
                in CALL_CONTRACT_HEADER_SUFFIXES
            ),
            key=lambda path: (path.casefold(), path),
        )
    )
    source_atomic_header_routes: list[dict[str, Any]] = []
    source_atomic_definition_paths: set[str] = set()
    for header_path in editable_header_paths:
        try:
            header_resolution = resolve_reviewed_definition_sources(
                reviewed_callables=(),
                header_texts=tuple(
                    (header_path, "", context)
                    for context in header_contexts
                ),
                source_texts=source_texts,
                inventory_resolver=inventory_resolver,
            )
        except ValueError as exc:
            raise ProgressError(
                "call-contract writable header definition ownership is "
                f"ambiguous for {header_path}: {exc}"
            ) from exc
        route_definitions = tuple(header_resolution.source_paths)
        source_atomic_definition_paths.update(route_definitions)
        source_atomic_header_routes.append(
            {
                "header_path": header_path,
                "definition_source_paths": list(route_definitions),
                "resolution_mode": header_resolution.mode,
                "candidate_independent": (
                    header_resolution.candidate_independent
                ),
                "ambiguity_policy": header_resolution.ambiguity_policy,
            }
        )
    if not source_atomic_definition_paths.issubset(
        set(definition_sources)
    ):
        raise ProgressError(
            "call-contract writable header definition closure escapes the "
            "complete signed definition closure"
        )
    ordered_source_atomic_definitions = tuple(
        sorted(
            source_atomic_definition_paths,
            key=lambda path: (path.casefold(), path),
        )
    )
    final_build_manifest_logical = (
        _call_contract_final_build_manifest_logical_path()
    )
    try:
        final_build_manifest_tracked = resolve_repository_file(
            final_build_manifest_logical,
            repository_root=root,
            inventory=repository_inventory,
            context="call-contract final-build manifest",
            allowed_suffixes={".json"},
        )
    except RepositoryPathError as exc:
        raise ProgressError(str(exc)) from exc
    dependency_paths = {
        *editable.values(),
        *included_paths.values(),
        *definition_sources,
        final_build_manifest_tracked.repository_path,
        *(
            manifest_path.replace("\\", "/")
            for _target_id, _registration, manifest_path in (
                _call_contract_target_registrations(document, slice_row)
            )
        ),
    }
    definition_resolution = {
        **definition_resolution_result.as_dict(),
        "reason": (
            "the pre-build evidence has no durable reviewed call-edge identity "
            "list; use the complete uniquely resolved header declaration closure"
        ),
        "source_atomic_header_definition_resolution": {
            "kind": (
                "call-contract-writable-header-definition-resolution"
            ),
            "contract_version": 1,
            "mode": "governed-writable-header-definition-closure",
            "candidate_independent": True,
            "ambiguity_policy": "fail-closed",
            "header_routes": source_atomic_header_routes,
            "definition_source_paths": list(
                ordered_source_atomic_definitions
            ),
        },
    }

    return CallContractSourceClosure(
        source_edit_paths=tuple(
            sorted(
                editable.values(), key=lambda path: (path.casefold(), path)
            )
        ),
        registered_source_paths=tuple(
            sorted(
                registered_sources.values(),
                key=lambda path: (path.casefold(), path),
            )
        ),
        header_paths=header_paths,
        definition_source_paths=definition_sources,
        dependency_paths=tuple(
            sorted(dependency_paths, key=lambda path: (path.casefold(), path))
        ),
        definition_resolution=definition_resolution,
    )


def call_contract_source_closure(
    document: ProgressDocument,
    slice_row: Mapping[str, Any],
    *,
    repository_path_inventory: RepositoryPathInventory | None = None,
) -> CallContractSourceClosure:
    """Derive the exact source closure without persistent reuse."""

    return _call_contract_source_closure_uncached(
        document,
        slice_row,
        repository_path_inventory=repository_path_inventory,
    )

def _candidate_dependent_owner_provenance(
    document: ProgressDocument,
    closure: CallContractSourceClosure,
    *,
    caller_symbol_id: str,
    caller_address: str,
    caller_end_exclusive: str,
    caller_target_id: str,
    caller_source_edit_paths: Sequence[str],
    error: CandidateCallTargetBridgeError,
) -> dict[str, Any]:
    """Resolve a candidate-observed callee to one bounded source owner.

    The decorated identity and ABI are candidate observations used only for
    routing.  They never become retail expected truth or acceptance evidence.
    """

    decoded_identity = error.decoded_identity
    non_source_class = _R4564_NON_SOURCE_DEPENDENT_IDENTITIES.get(
        error.decorated_identity
    )
    resolution_error = ""
    resolution = None
    if decoded_identity is not None and non_source_class is None:
        try:
            repository_inventory = load_repository_path_inventory(REPO_ROOT)
            root = repository_inventory.repository_root
            config = load_final_build_config(DEFAULT_FINAL_BUILD_MANIFEST)
            context_by_source: dict[str, tuple[str, ...]] = {}
            canonical_source_by_key: dict[str, str] = {}
            configured_sources, _stale_diagnostics = (
                _call_contract_final_build_source_map(
                    config,
                    inventory=repository_inventory,
                )
            )
            for rows in configured_sources.values():
                if len(rows) != 1:
                    raise ProgressError(
                        "call-contract dependent-owner final-build source "
                        "population has a duplicate or case collision"
                    )
                relative, resolved = rows[0]
                source_key = relative.casefold()
                prior_source = canonical_source_by_key.get(source_key)
                if prior_source is not None:
                    raise ProgressError(
                        "call-contract dependent-owner final-build source "
                        "population has a duplicate or case collision: "
                        f"{prior_source}, {relative}"
                    )
                canonical_source_by_key[source_key] = relative
                context_by_source[source_key] = (
                    _call_contract_vc5_preprocessor_defines(config, resolved)
                )
            source_texts: list[tuple[str, str, tuple[str, ...]]] = []
            definition_source_by_key: dict[str, str] = {}
            for path in closure.definition_source_paths:
                source_key = path.casefold()
                prior_source = definition_source_by_key.get(source_key)
                if prior_source is not None:
                    raise ProgressError(
                        "call-contract dependent-owner definition source "
                        "population has a duplicate or case collision: "
                        f"{prior_source}, {path}"
                    )
                definition_source_by_key[source_key] = path
                context = context_by_source.get(source_key)
                if context is None:
                    raise ProgressError(
                        "call-contract dependent-owner definition source lacks "
                        f"an exact final-build preprocessor context: {path}"
                    )
                source_texts.append((path, "", context))
            inventory_resolver = _call_contract_callable_inventory_resolver(
                document, root=root
            )
            definition_probe = resolve_dependent_callable_owner(
                callable_key=decoded_identity.callable_key,
                header_texts=(),
                source_texts=source_texts,
                inventory_resolver=inventory_resolver,
            )
            definition_contexts: set[tuple[str, ...]] = set()
            for path in definition_probe.definition_paths:
                source_key = path.casefold()
                context = context_by_source.get(source_key)
                if context is None or source_key not in definition_source_by_key:
                    raise ProgressError(
                        "call-contract dependent-owner definition probe escaped "
                        f"the exact source closure: {path}"
                    )
                definition_contexts.add(context)
            # First scan every exact definition source under its own governed
            # context.  A header declaration can own the observed callable
            # only under a context belonging to one of the matching definition
            # sources.  This retains complete definition/ambiguity detection
            # without materializing every header under every unrelated context
            # in the closure.
            header_contexts = tuple(sorted(definition_contexts))
            header_texts = tuple(
                (path, "", context)
                for path in closure.header_paths
                for context in header_contexts
            )
            resolution = resolve_dependent_callable_owner(
                callable_key=decoded_identity.callable_key,
                header_texts=header_texts,
                source_texts=source_texts,
                inventory_resolver=inventory_resolver,
            )
        except (OSError, ValueError, ProgressError) as exc:
            resolution_error = str(exc)
    caller_paths = set(caller_source_edit_paths)
    owner_paths = set(resolution.source_edit_paths if resolution else ())
    call_site_in_extent = bool(
        error.call_site_address is not None
        and address_value(caller_address)
        <= address_value(error.call_site_address)
        < address_value(caller_end_exclusive)
    )
    if not call_site_in_extent or not error.call_site_unique:
        relation = "non-source-ambiguity"
    elif resolution is None or resolution.mode != "exact":
        relation = "non-source-ambiguity"
    elif owner_paths.isdisjoint(caller_paths):
        relation = "exact-dependent-owner"
    elif owner_paths.issubset(caller_paths):
        relation = "caller-owned"
    else:
        relation = "non-source-ambiguity"
    if non_source_class is not None:
        resolution_payload = {
            "kind": "call-contract-dependent-owner-resolution",
            "contract_version": 1,
            "mode": non_source_class,
            "declaration_paths": [],
            "definition_paths": [],
            "source_edit_paths": [],
            "candidate_independent": False,
            "ambiguity_policy": "fail-closed",
            "resolution_basis": "exact-reviewed-r4564-non-source-identity",
        }
    elif resolution is not None:
        resolution_payload = resolution.as_dict()
    else:
        resolution_payload = {
            "kind": "call-contract-dependent-owner-resolution",
            "contract_version": 1,
            "mode": (
                "unsupported-identity"
                if decoded_identity is None
                else "resolver-error"
            ),
            "declaration_paths": [],
            "definition_paths": [],
            "source_edit_paths": [],
            "candidate_independent": False,
            "ambiguity_policy": "fail-closed",
        }
        if resolution_error:
            resolution_payload["error"] = resolution_error
    identity_payload = (
        decoded_identity.as_dict()
        if decoded_identity is not None
        else {
            "decorated_identity": error.decorated_identity,
            "decode_status": (
                "exact-non-source" if non_source_class else "unsupported"
            ),
            **(
                {"non_source_class": non_source_class}
                if non_source_class
                else {}
            ),
        }
    )
    return {
        "kind": "call-contract-candidate-target-dependency",
        "contract_version": 1,
        "candidate_expected_truth": False,
        "provenance": "candidate-cod-decorated-call-target",
        "observation_role": "candidate-observed-abi-routing-only",
        "caller_symbol_id": caller_symbol_id,
        "caller_address": caller_address,
        "caller_end_exclusive": caller_end_exclusive,
        "caller_target_id": caller_target_id,
        "caller_target_source_edit_paths": sorted(
            caller_paths, key=lambda path: (path.casefold(), path)
        ),
        "candidate_call_site_address": error.call_site_address,
        "candidate_call_site_unique": error.call_site_unique,
        "candidate_call_site_in_caller_extent": call_site_in_extent,
        "identity": identity_payload,
        "owner_relation": relation,
        "owner_resolution": resolution_payload,
    }


_CANDIDATE_BODY_ZERO_ARGUMENT_IDENTITY_RE = re.compile(
    r"^\?(?P<body>[A-Za-z_][A-Za-z0-9_]*(?:@[A-Za-z_][A-Za-z0-9_]*)*)"
    r"@@Y(?P<calling>[AGI])(?P<return>[A-Za-z0-9_?$@]+)XZ$"
)


def _decode_candidate_body_zero_argument_identity(
    decorated_identity: str,
) -> DecodedCallableIdentity | None:
    """Decode the narrow VC5 global/static body ABI used for repair routing."""

    match = _CANDIDATE_BODY_ZERO_ARGUMENT_IDENTITY_RE.fullmatch(
        str(decorated_identity)
    )
    if match is None:
        return None
    parts = match.group("body").split("@")
    return DecodedCallableIdentity(
        decorated_identity=str(decorated_identity),
        callable_key=CallableKey(
            "::".join((*reversed(parts[1:]), parts[0])),
            (),
        ),
        calling_convention={
            "A": "__cdecl",
            "G": "__stdcall",
            "I": "__fastcall",
        }[match.group("calling")],
        parameter_bytes=0,
        return_shape=(
            f"msvc-type-code:{match.group('return')}"
            if len(match.group("return")) == 1
            else f"msvc-type-encoding:{match.group('return')}"
        ),
        identity_format="msvc-cpp-global-zero-argument-body",
    )


def _selected_target_compile_diagnostic_route(
    document: ProgressDocument,
    closure: CallContractSourceClosure,
    *,
    target_id: str,
    selected_target: Any,
    symbol_id: str,
    address: str,
    expected_identity: str,
) -> dict[str, Any] | None:
    """Resolve one compiler-diagnostic identity to one header and target TU.

    The registered target identity is candidate-independent authority.  This
    route is intentionally narrower than candidate COFF/COD recovery: it
    accepts only one selected translation unit, one exact registered body,
    one declaration header, and one definition in that selected TU.  It does
    not make the declaration writable or infer expected truth from diagnostic
    text.
    """

    expected = _decode_candidate_body_zero_argument_identity(
        expected_identity
    )
    if expected is None or expected.calling_convention != "__cdecl":
        return None
    route: dict[str, Any] = {
        "kind": "call-contract-selected-target-compile-diagnostic-route",
        "contract_version": 1,
        "target_id": target_id,
        "symbol_id": symbol_id,
        "address": address,
        "expected_identity": expected.as_dict(),
        "declaration_paths": [],
        "definition_paths": [],
        "source_edit_paths": [],
        "routing_mode": "blocked",
        "candidate_expected_truth": False,
        "ambiguity_policy": "fail-closed",
    }
    target_name = str(getattr(selected_target, "name", ""))
    translation_units = tuple(
        getattr(selected_target, "translation_unit_function_order", ())
    )
    if (
        target_id != f"recoil:vc5-target:{target_name}"
        or str(getattr(selected_target, "target_binary", "")) != "recoil"
        or not bool(
            getattr(
                selected_target,
                "check_translation_unit_function_order",
                False,
            )
        )
        or len(translation_units) != 1
    ):
        route["blocker_reason"] = (
            "selected-target-definition-authority-mismatch"
        )
        return route
    selected_unit = translation_units[0]
    definition_path = str(getattr(selected_unit, "source_from", ""))
    try:
        matching_rows = [
            row
            for row in tuple(getattr(selected_unit, "functions", ()))
            if normalize_address(str(getattr(row, "address", "")))
            == address
        ]
    except (TypeError, ValueError, ProgressError):
        matching_rows = []
    if (
        not definition_path
        or len(matching_rows) != 1
        or str(getattr(matching_rows[0], "symbol", ""))
        != expected_identity
        or getattr(matching_rows[0], "symbol_regex", None) is not None
        or closure.registered_source_paths.count(definition_path) != 1
        or closure.source_edit_paths.count(definition_path) != 1
        or closure.dependency_paths.count(definition_path) != 1
    ):
        route["blocker_reason"] = (
            "selected-target-definition-authority-mismatch"
        )
        return route

    repository_inventory = load_repository_path_inventory(REPO_ROOT)
    root = repository_inventory.repository_root
    try:
        config = load_final_build_config(DEFAULT_FINAL_BUILD_MANIFEST)
        configured_sources, _stale_diagnostics = (
            _call_contract_final_build_source_map(
                config,
                inventory=repository_inventory,
            )
        )
        configured_definition = configured_sources.get(
            definition_path.casefold(), []
        )
        if (
            len(configured_definition) != 1
            or configured_definition[0][0] != definition_path
        ):
            route["blocker_reason"] = (
                "selected-target-definition-unsupported-or-aliased"
            )
            return route
        compile_flags = tuple(
            final_build_effective_compile_flags(
                config, configured_definition[0][1]
            )
        )
        calling_convention_flags = [
            flag
            for flag in compile_flags
            if flag in {"/Gd", "/Gr", "/Gz"}
        ]
        if (
            not calling_convention_flags
            or calling_convention_flags[-1] != "/Gr"
        ):
            route["blocker_reason"] = (
                "selected-target-default-callconv-not-fastcall"
            )
            return route
        context = _call_contract_vc5_preprocessor_defines(
            config, configured_definition[0][1]
        )
        resolver = _call_contract_callable_inventory_resolver(
            document, root=root
        )
        declaration_paths = sorted(
            {
                path
                for path in closure.header_paths
                if expected.callable_key
                in resolver(path, context).declarations
            },
            key=lambda path: (path.casefold(), path),
        )
        definition_matches = bool(
            expected.callable_key
            in resolver(definition_path, context).definitions
        )
    except (OSError, RuntimeError, ValueError, ProgressError) as exc:
        route["blocker_reason"] = (
            "declaration-header-definition-resolution-error"
        )
        route["resolution_error"] = str(exc)
        return route
    route["declaration_paths"] = declaration_paths
    if len(declaration_paths) != 1:
        route["blocker_reason"] = (
            "declaration-header-missing"
            if not declaration_paths
            else "declaration-header-ambiguous"
        )
        return route
    route["definition_paths"] = (
        [definition_path] if definition_matches else []
    )
    if not definition_matches:
        route["blocker_reason"] = "selected-target-definition-missing"
        return route

    declaration_path = declaration_paths[0]
    for routed_path, suffixes, authority_paths, label in (
        (
            declaration_path,
            CALL_CONTRACT_HEADER_SUFFIXES,
            closure.header_paths,
            "declaration-header",
        ),
        (
            definition_path,
            CALL_CONTRACT_SOURCE_SUFFIXES,
            closure.registered_source_paths,
            "selected-target-definition",
        ),
    ):
        try:
            repository_routed = resolve_repository_file(
                routed_path,
                repository_root=root,
                inventory=repository_inventory,
                context=f"call-contract {label}",
                allowed_suffixes=suffixes,
            )
        except RepositoryPathError:
            route["blocker_reason"] = f"{label}-escaping"
            return route
        if (
            repository_routed.repository_path != routed_path
            or [path.casefold() for path in authority_paths].count(
                routed_path.casefold()
            )
            != 1
            or routed_path not in closure.dependency_paths
        ):
            route["blocker_reason"] = f"{label}-unsupported-or-aliased"
            return route
    route["routing_mode"] = "exact"
    route["source_edit_paths"] = [definition_path]
    return route


def _candidate_artifact_path(path: Path) -> str:
    resolved = path.resolve()
    try:
        return resolved.relative_to(REPO_ROOT.resolve()).as_posix()
    except ValueError:
        return str(resolved)


INTENTIONALLY_INLINED_ABSENCE_PROOF_KIND = (
    "call-contract-intentionally-inlined-empty-authored-body"
)
INTENTIONALLY_INLINED_ABSENCE_PROOF_MODE = (
    "exact-inline-empty-lifecycle-linked-absence"
)
_VC5_VIRTUAL_DESTRUCTOR_IDENTITY_RE = re.compile(
    r"^\?\?1(?P<class_name>[A-Za-z_][A-Za-z0-9_]*"
    r"(?:@[A-Za-z_][A-Za-z0-9_]*)*)@@UAE@XZ$"
)


def _decode_vc5_virtual_destructor_absence_identity(
    decorated_identity: str,
) -> dict[str, Any] | None:
    """Decode the one VC5 virtual-destructor family safe for absence proof."""

    match = _VC5_VIRTUAL_DESTRUCTOR_IDENTITY_RE.fullmatch(
        str(decorated_identity)
    )
    if match is None:
        return None
    encoded_class = match.group("class_name")
    parts = encoded_class.split("@")
    terminal = parts[0]
    qualified_class = "::".join((*reversed(parts[1:]), terminal))
    return {
        "callable_key": CallableKey(
            f"{qualified_class}::~{terminal}", ()
        ),
        "qualified_class": qualified_class,
        "ordinary_destructor": str(decorated_identity),
        "scalar_deleting_destructor": (
            f"??_G{encoded_class}@@UAEPAXI@Z"
        ),
        "vector_deleting_destructor": (
            f"??_E{encoded_class}@@UAEPAXI@Z"
        ),
        "vftable": f"??_7{encoded_class}@@6B@",
    }


def _callable_definition_body_token_counts(
    text: str,
    *,
    defines: Iterable[str],
    callable_key: CallableKey,
) -> tuple[int, ...]:
    """Return active token counts for every exact callable definition body.

    This deliberately reuses the conservative definition-closure lexer and
    declarator parser.  Comments, literals, directives, and inactive
    preprocessor branches therefore cannot manufacture an empty definition.
    A body is proven empty only when its matching braces contain zero active
    C/C++ tokens.
    """

    tokens = _CPP_DEFINITION_TOKEN_RE.findall(
        _mask_cpp_definition_non_code(text, tuple(defines))
    )
    frames: list[tuple[str, str]] = []
    segment: list[str] = []
    counts: list[int] = []

    def in_function() -> bool:
        return any(kind == "function" for kind, _name in frames)

    def scope_names() -> tuple[str, ...]:
        return tuple(
            name
            for kind, name in frames
            if kind in {"namespace", "class"} and name
        )

    for index, token in enumerate(tokens):
        if token == ";":
            segment = []
            continue
        if token == "{":
            if in_function():
                frames.append(("other", ""))
            else:
                key = _cpp_definition_callable_key(segment, scope_names())
                if key is not None:
                    if key == callable_key:
                        depth = 1
                        cursor = index + 1
                        while cursor < len(tokens) and depth:
                            if tokens[cursor] == "{":
                                depth += 1
                            elif tokens[cursor] == "}":
                                depth -= 1
                            cursor += 1
                        if depth:
                            raise ValueError(
                                "unterminated callable definition in inline-absence proof"
                            )
                        counts.append(cursor - index - 2)
                    frames.append(("function", key.qualified_name))
                elif "namespace" in segment:
                    namespace_index = (
                        len(segment)
                        - 1
                        - segment[::-1].index("namespace")
                    )
                    name = (
                        segment[namespace_index + 1]
                        if namespace_index + 1 < len(segment)
                        and re.fullmatch(
                            r"[A-Za-z_][A-Za-z0-9_]*",
                            segment[namespace_index + 1],
                        )
                        else ""
                    )
                    frames.append(("namespace", name))
                elif any(
                    keyword in segment
                    for keyword in ("class", "struct", "union")
                ):
                    class_indexes = [
                        item
                        for item, value in enumerate(segment)
                        if value in {"class", "struct", "union"}
                    ]
                    class_index = class_indexes[-1]
                    name = (
                        segment[class_index + 1]
                        if class_index + 1 < len(segment)
                        and re.fullmatch(
                            r"[A-Za-z_][A-Za-z0-9_]*",
                            segment[class_index + 1],
                        )
                        else ""
                    )
                    frames.append(("class", name))
                else:
                    frames.append(("other", ""))
            segment = []
            continue
        if token == "}":
            if frames:
                frames.pop()
            segment = []
            continue
        segment.append(token)
    return tuple(counts)


def _coff_exact_named_symbols(
    coff_object: CoffObject,
    name: str,
) -> list[Any]:
    folded = name.casefold()
    rows = [
        symbol
        for symbol in coff_object.symbols
        if str(getattr(symbol, "name", "")).casefold() == folded
    ]
    if any(str(getattr(symbol, "name", "")) != name for symbol in rows):
        return []
    return rows


def _coff_exact_comdat_selection(
    coff_object: CoffObject,
    section_number: int,
) -> bool:
    definitions = [
        symbol
        for symbol in coff_object.symbols
        if getattr(symbol, "section_number", 0) == section_number
        and getattr(symbol, "section_definition_selection", None) is not None
    ]
    return bool(
        len(definitions) == 1
        and getattr(definitions[0], "section_definition_selection", None) == 2
    )


def _prove_intentionally_inlined_empty_authored_candidate(
    document: ProgressDocument,
    closure: CallContractSourceClosure,
    *,
    target_id: str,
    selected_target: Any,
    compiled_entry: Any | None,
    symbol_id: str,
    address: str,
    expected_identity: str,
    cod_path: Path,
    coff_object: CoffObject,
) -> dict[str, Any] | None:
    """Prove one empty inline authored destructor with no candidate body.

    The accommodation is intentionally conjunctive.  Retail/registration and
    current source select the identity; current VC5 output may prove only that
    the exact body is absent and that the corresponding deleting-destructor /
    vftable linkage family remains emitted.  Any missing, duplicated, aliased,
    differently optimized, non-empty, out-of-line, or malformed fact returns
    ``None`` so ordinary candidate-body acquisition remains fail-closed.
    """

    decoded = _decode_vc5_virtual_destructor_absence_identity(
        expected_identity
    )
    if decoded is None:
        return None
    target_name = str(getattr(selected_target, "name", ""))
    target_binary = str(getattr(selected_target, "target_binary", ""))
    units = tuple(
        getattr(selected_target, "translation_unit_function_order", ())
    )
    target_rows = tuple(getattr(compiled_entry, "functions", ()))
    try:
        matching_rows = [
            row
            for row in target_rows
            if normalize_address(str(getattr(row, "address", ""))) == address
        ]
    except (TypeError, ValueError, ProgressError):
        return None
    definition_path = str(getattr(compiled_entry, "source_from", ""))
    if (
        target_id != f"recoil:vc5-target:{target_name}"
        or target_binary != "recoil"
        or not bool(
            getattr(
                selected_target,
                "check_translation_unit_function_order",
                False,
            )
        )
        or len(units) != 1
        # Convergence loads the phase document and its manifest cache
        # independently from the parent census document.  Bind the compiled
        # entry to the registered unit by its complete parsed value, not by
        # Python object identity; any field drift still fails closed.
        or compiled_entry != units[0]
        or len(matching_rows) != 1
        or str(getattr(matching_rows[0], "symbol", ""))
        != expected_identity
        or getattr(matching_rows[0], "symbol_regex", None) is not None
        or str(getattr(matching_rows[0], "pipeline_class", ""))
        != "authored"
        or str(getattr(matching_rows[0], "authored_order_role", ""))
        != "authored-body"
        or getattr(matching_rows[0], "required_presence", None) is not True
        or not definition_path
        or closure.registered_source_paths.count(definition_path) != 1
        or closure.dependency_paths.count(definition_path) != 1
    ):
        return None

    symbols = document.collection("symbols")
    blocks = document.collection("physical_blocks")
    symbol = symbols.get(symbol_id)
    block_id = (
        str(symbol.get("physical_block_id", ""))
        if isinstance(symbol, Mapping)
        else ""
    )
    block = blocks.get(block_id)
    accepted = (
        block.get("accepted_order_facts")
        if isinstance(block, Mapping)
        else None
    )
    authored_order = (
        block.get("order", {}).get("authored", {})
        if isinstance(block, Mapping)
        and isinstance(block.get("order"), Mapping)
        and isinstance(block.get("order", {}).get("authored"), Mapping)
        else {}
    )
    if (
        not isinstance(symbol, Mapping)
        or symbol_id != f"recoil:function:{address}"
        or symbol.get("kind") != "function"
        or symbol.get("binary") != "recoil"
        or normalize_address(str(symbol.get("address", ""))) != address
        or symbol.get("pipeline_class") != "authored"
        or symbol.get("extent_state") != "known"
        or symbol.get("output_section_id") != "recoil:section:.text"
        or target_id not in symbol.get("verification_target_ids", [])
        or not block_id
        or not isinstance(accepted, Mapping)
        or accepted.get("target_id") != target_id
        or accepted.get("phase") != "authored-function-order"
        or accepted.get("validation_mode") != "live"
        or list(accepted.get("matched_identities", [])).count(symbol_id) != 1
        or any(
            not is_current_accepted_state(authored_order.get(dimension))
            for dimension in (
                "authored_linked_order",
                "authored_object_order",
                "block_precedence",
                "linked_identity_presence",
                "object_identity_presence",
            )
        )
    ):
        return None

    repository_inventory = load_repository_path_inventory(REPO_ROOT)
    root = repository_inventory.repository_root
    try:
        config = load_final_build_config(DEFAULT_FINAL_BUILD_MANIFEST)
        configured_sources, _stale_diagnostics = (
            _call_contract_final_build_source_map(
                config,
                inventory=repository_inventory,
            )
        )
        configured_definition = configured_sources.get(
            definition_path.casefold(), []
        )
        if (
            len(configured_definition) != 1
            or configured_definition[0][0] != definition_path
            or str(getattr(selected_target, "compile_context_from", ""))
            != _call_contract_final_build_manifest_logical_path()
        ):
            return None
        source_path = configured_definition[0][1]
        final_flags = (
            *final_build_effective_compile_flags(config, source_path),
            *(f"/D{value}" for value in config.defines),
            "/FAcs",
        )
        profile, target_flags = effective_source_compile_context(
            selected_target, definition_path
        )
        upper_flags = tuple(flag.upper() for flag in target_flags)
        if (
            not profile
            or tuple(target_flags) != final_flags
            or [
                flag
                for flag in upper_flags
                if flag in {"/OD", "/O1", "/O2", "/OX"}
            ]
            != ["/O2"]
            or [
                flag
                for flag in upper_flags
                if flag in {"/OB0", "/OB1", "/OB2"}
            ]
            != ["/OB1"]
            or "/FACS" not in upper_flags
            or "/TP" not in upper_flags
        ):
            return None
        defines = _call_contract_vc5_preprocessor_defines(
            config, source_path
        )
        resolver = _call_contract_callable_inventory_resolver(
            document, root=root
        )
        header_matches: list[tuple[str, tuple[int, ...]]] = []
        for header_path in closure.header_paths:
            inventory = resolver(header_path, defines)
            if decoded["callable_key"] not in inventory.definitions:
                continue
            header_text = (root / header_path).read_text(
                encoding="utf-8", errors="ignore"
            )
            header_matches.append(
                (
                    header_path,
                    _callable_definition_body_token_counts(
                        header_text,
                        defines=defines,
                        callable_key=decoded["callable_key"],
                    ),
                )
            )
        if len(header_matches) != 1 or header_matches[0][1] != (0,):
            return None
        header_path = header_matches[0][0]
        source_definition_matches: list[str] = []
        for candidate_path in sorted(
            {
                *closure.registered_source_paths,
                *closure.definition_source_paths,
            },
            key=lambda value: (value.casefold(), value),
        ):
            configured = configured_sources.get(candidate_path.casefold(), [])
            if len(configured) != 1 or configured[0][0] != candidate_path:
                return None
            candidate_defines = _call_contract_vc5_preprocessor_defines(
                config, configured[0][1]
            )
            if decoded["callable_key"] in resolver(
                candidate_path, candidate_defines
            ).definitions:
                source_definition_matches.append(candidate_path)
        if source_definition_matches:
            return None
    except (OSError, RuntimeError, ValueError, ProgressError):
        return None

    ordinary = str(decoded["ordinary_destructor"])
    scalar = str(decoded["scalar_deleting_destructor"])
    vector = str(decoded["vector_deleting_destructor"])
    vftable = str(decoded["vftable"])
    if _coff_exact_named_symbols(coff_object, ordinary):
        return None
    try:
        cod_text = _read_cod_text(cod_path, errors="ignore")
    except OSError:
        return None
    proc_re = re.compile(r"^\s*(\S+)\s+PROC\b", re.IGNORECASE | re.MULTILINE)
    endp_re = re.compile(r"^\s*(\S+)\s+ENDP\b", re.IGNORECASE | re.MULTILINE)
    ordinary_proc_rows = [
        name for name in proc_re.findall(cod_text) if name.casefold() == ordinary.casefold()
    ]
    ordinary_endp_rows = [
        name for name in endp_re.findall(cod_text) if name.casefold() == ordinary.casefold()
    ]
    ordinary_comdat_rows = re.findall(
        rf"^\s*;\s*COMDAT\s+{re.escape(ordinary)}\s*$",
        cod_text,
        re.IGNORECASE | re.MULTILINE,
    )
    if ordinary_proc_rows or ordinary_endp_rows or len(ordinary_comdat_rows) != 1:
        return None

    scalar_rows = _coff_exact_named_symbols(coff_object, scalar)
    vector_rows = _coff_exact_named_symbols(coff_object, vector)
    vftable_rows = _coff_exact_named_symbols(coff_object, vftable)
    scalar_undefined = [
        row
        for row in scalar_rows
        if row.section_number == 0
        and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
        and row.type == 0x20
    ]
    scalar_defined = [
        row
        for row in scalar_rows
        if row.section_number > 0
        and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
        and row.type == 0x20
    ]
    vector_weak = [
        row
        for row in vector_rows
        if row.section_number == 0
        and row.storage_class == 105
        and row.type == 0x20
    ]
    vftable_defined = [
        row
        for row in vftable_rows
        if row.section_number > 0
        and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
        and row.type == 0
    ]
    if (
        len(scalar_rows) != 2
        or len(scalar_undefined) != 1
        or len(scalar_defined) != 1
        or len(vector_rows) != 1
        or len(vector_weak) != 1
        or len(vftable_rows) != 1
        or len(vftable_defined) != 1
        or getattr(vector_weak[0], "weak_external_tag_index", None)
        != scalar_undefined[0].index
        or getattr(vector_weak[0], "weak_external_characteristics", None) != 2
    ):
        return None
    scalar_symbol = scalar_defined[0]
    vftable_symbol = vftable_defined[0]
    try:
        scalar_section = coff_object.section(scalar_symbol.section_number)
        vftable_section = coff_object.section(vftable_symbol.section_number)
        scalar_body = coff_object.function_bytes(scalar)
        scalar_listing = _extract_cod_proc_with_local_switches(cod_path, scalar)
    except (OSError, RuntimeError, ValueError):
        return None
    if (
        scalar_section.name != ".text"
        or not scalar_section.raw_data
        or not (scalar_section.characteristics & IMAGE_SCN_CNT_CODE)
        or not (scalar_section.characteristics & IMAGE_SCN_LNK_COMDAT)
        or not _coff_exact_comdat_selection(
            coff_object, scalar_symbol.section_number
        )
        or not scalar_body.data
        or not scalar_listing.instructions
        or vftable_section.name != ".rdata"
        or not (vftable_section.characteristics & IMAGE_SCN_LNK_COMDAT)
        or not _coff_exact_comdat_selection(
            coff_object, vftable_symbol.section_number
        )
        or vftable_symbol.value != 0
        or len(vftable_section.raw_data) < 4
        or vftable_section.raw_data[:4] != b"\x00\x00\x00\x00"
    ):
        return None
    vftable_slot_relocations = [
        relocation
        for relocation in coff_object.relocations_by_section.get(
            vftable_symbol.section_number, ()
        )
        if relocation.offset == vftable_symbol.value
    ]
    scalar_vftable_relocations = [
        relocation
        for relocation in coff_object.relocations_by_section.get(
            scalar_symbol.section_number, ()
        )
        if relocation.symbol_name == vftable
    ]
    ordinary_relocations = [
        relocation
        for rows in coff_object.relocations_by_section.values()
        for relocation in rows
        if relocation.symbol_name.casefold() == ordinary.casefold()
    ]
    if (
        len(vftable_slot_relocations) != 1
        or vftable_slot_relocations[0].type != IMAGE_REL_I386_DIR32
        or vftable_slot_relocations[0].symbol_name != vector
        or vftable_slot_relocations[0].symbol_index != vector_weak[0].index
        or len(scalar_vftable_relocations) != 1
        or scalar_vftable_relocations[0].type != IMAGE_REL_I386_DIR32
        or ordinary_relocations
    ):
        return None

    return {
        "kind": INTENTIONALLY_INLINED_ABSENCE_PROOF_KIND,
        "contract_version": 1,
        "proof_mode": INTENTIONALLY_INLINED_ABSENCE_PROOF_MODE,
        "candidate_expected_truth": False,
        "symbol_id": symbol_id,
        "address": address,
        "target_id": target_id,
        "registered_identity": ordinary,
        "source_definition": {
            "header_path": header_path,
            "translation_unit_path": definition_path,
            "callable_key": str(decoded["callable_key"]),
            "active_definition_count": 1,
            "active_body_token_count": 0,
            "out_of_line_definition_count": 0,
        },
        "compiler": {
            "profile": profile,
            "effective_flags": list(target_flags),
            "required_optimization": "/O2",
            "required_inline_expansion": "/Ob1",
            "assembly_listing": "/FAcs",
        },
        "candidate_absence": {
            "object_path": _candidate_artifact_path(cod_path.with_suffix(".obj")),
            "cod_path": _candidate_artifact_path(cod_path),
            "coff_identity_count": 0,
            "cod_proc_count": 0,
            "cod_endp_count": 0,
            "cod_comdat_declaration_count": 1,
            "ordinary_relocation_count": 0,
        },
        "lifecycle_linkage": {
            "scalar_deleting_destructor": scalar,
            "vector_deleting_destructor": vector,
            "vftable": vftable,
            "vector_weak_aliases_scalar": True,
            "vftable_slot_zero_targets_vector": True,
            "scalar_references_vftable": True,
        },
        "retail_linkage_authority": {
            "physical_block_id": block_id,
            "accepted_order_target_id": target_id,
            "matched_identity_count": 1,
            "authored_order_dimensions_current": True,
        },
    }


def _valid_intentionally_inlined_absence_proof(
    proof: Any,
    *,
    symbol_id: str,
    address: str,
    target_id: str,
) -> bool:
    if not isinstance(proof, Mapping):
        return False
    source = proof.get("source_definition")
    compiler = proof.get("compiler")
    absence = proof.get("candidate_absence")
    lifecycle = proof.get("lifecycle_linkage")
    retail = proof.get("retail_linkage_authority")
    decoded = _decode_vc5_virtual_destructor_absence_identity(
        str(proof.get("registered_identity", ""))
    )
    effective_flags = (
        compiler.get("effective_flags")
        if isinstance(compiler, Mapping)
        else None
    )
    folded_flags = (
        [str(flag).upper() for flag in effective_flags]
        if isinstance(effective_flags, list)
        else []
    )
    return bool(
        proof.get("kind") == INTENTIONALLY_INLINED_ABSENCE_PROOF_KIND
        and proof.get("contract_version") == 1
        and proof.get("proof_mode") == INTENTIONALLY_INLINED_ABSENCE_PROOF_MODE
        and proof.get("candidate_expected_truth") is False
        and proof.get("symbol_id") == symbol_id
        and proof.get("address") == address
        and proof.get("target_id") == target_id
        and isinstance(proof.get("registered_identity"), str)
        and decoded is not None
        and isinstance(source, Mapping)
        and source.get("active_definition_count") == 1
        and source.get("active_body_token_count") == 0
        and source.get("out_of_line_definition_count") == 0
        and isinstance(source.get("header_path"), str)
        and isinstance(source.get("translation_unit_path"), str)
        and isinstance(source.get("callable_key"), str)
        and isinstance(compiler, Mapping)
        and isinstance(compiler.get("profile"), str)
        and bool(compiler.get("profile"))
        and isinstance(compiler.get("effective_flags"), list)
        and folded_flags.count("/O2") == 1
        and folded_flags.count("/OB1") == 1
        and folded_flags.count("/FACS") == 1
        and compiler.get("required_optimization") == "/O2"
        and compiler.get("required_inline_expansion") == "/Ob1"
        and compiler.get("assembly_listing") == "/FAcs"
        and isinstance(absence, Mapping)
        and isinstance(absence.get("object_path"), str)
        and bool(absence.get("object_path"))
        and isinstance(absence.get("cod_path"), str)
        and bool(absence.get("cod_path"))
        and absence.get("coff_identity_count") == 0
        and absence.get("cod_proc_count") == 0
        and absence.get("cod_endp_count") == 0
        and absence.get("cod_comdat_declaration_count") == 1
        and absence.get("ordinary_relocation_count") == 0
        and isinstance(lifecycle, Mapping)
        and lifecycle.get("scalar_deleting_destructor")
        == decoded.get("scalar_deleting_destructor")
        and lifecycle.get("vector_deleting_destructor")
        == decoded.get("vector_deleting_destructor")
        and lifecycle.get("vftable") == decoded.get("vftable")
        and lifecycle.get("vector_weak_aliases_scalar") is True
        and lifecycle.get("vftable_slot_zero_targets_vector") is True
        and lifecycle.get("scalar_references_vftable") is True
        and isinstance(retail, Mapping)
        and isinstance(retail.get("physical_block_id"), str)
        and bool(retail.get("physical_block_id"))
        and retail.get("accepted_order_target_id") == target_id
        and retail.get("matched_identity_count") == 1
        and retail.get("authored_order_dimensions_current") is True
    )


def _candidate_body_declaration_header_route(
    document: ProgressDocument,
    closure: CallContractSourceClosure,
    *,
    target_id: str,
    selected_target: Any,
    compiled_entry: Any | None,
    symbol_id: str,
    address: str,
    expected_identity: str,
    cod_path: Path,
    coff_object: CoffObject,
) -> dict[str, Any] | None:
    """Prove one current ABI alternative and its declaration/definition pair.

    The registered target spelling is candidate-independent expected identity.
    Current COFF/COD and source declarations are repair provenance only.  No
    diagnostic-text parsing or source-path guessing is permitted.
    """

    expected = _decode_candidate_body_zero_argument_identity(expected_identity)
    if expected is None:
        return None
    symbol_names = [
        str(getattr(item, "name", ""))
        for item in coff_object.symbols
        if str(getattr(item, "name", ""))
    ]
    candidate_names: list[str] = []
    duplicate_candidate_names: set[str] = set()
    for name in sorted(set(symbol_names)):
        observed = _decode_candidate_body_zero_argument_identity(name)
        if (
            observed is None
            or observed.callable_key != expected.callable_key
            or observed.return_shape != expected.return_shape
            or observed.calling_convention == expected.calling_convention
        ):
            continue
        try:
            coff_object.function_bytes(name)
            _extract_cod_proc_with_local_switches(cod_path, name)
        except (OSError, RuntimeError, ValueError):
            continue
        candidate_names.append(name)
        if symbol_names.count(name) != 1:
            duplicate_candidate_names.add(name)
    candidate_names = sorted(set(candidate_names))
    route: dict[str, Any] = {
        "kind": "call-contract-candidate-body-declaration-header-route",
        "contract_version": 1,
        "target_id": target_id,
        "symbol_id": symbol_id,
        "address": address,
        "expected_identity": expected.as_dict(),
        "candidate_identities": [
            _decode_candidate_body_zero_argument_identity(name).as_dict()
            for name in candidate_names
        ],
        "candidate_cod_path": _candidate_artifact_path(cod_path),
        "candidate_object_path": _candidate_artifact_path(
            cod_path.with_suffix(".obj")
        ),
        "declaration_paths": [],
        "definition_paths": [],
        "source_edit_paths": [],
        "routing_mode": "blocked",
        "candidate_expected_truth": False,
        "ambiguity_policy": "fail-closed",
    }
    if len(candidate_names) != 1 or duplicate_candidate_names:
        route["blocker_reason"] = (
            "candidate-body-identity-missing"
            if not candidate_names
            else "candidate-body-identity-ambiguous"
        )
        return route

    target_name = str(getattr(selected_target, "name", ""))
    target_binary = str(getattr(selected_target, "target_binary", ""))
    target_rows = (
        tuple(getattr(compiled_entry, "functions", ()))
        if compiled_entry is not None
        else tuple(getattr(selected_target, "functions", ()))
    )
    try:
        matching_target_rows = [
            row
            for row in target_rows
            if normalize_address(str(getattr(row, "address", "")))
            == address
        ]
    except (TypeError, ValueError, ProgressError):
        route["blocker_reason"] = (
            "selected-target-definition-authority-mismatch"
        )
        return route
    translation_units = tuple(
        getattr(selected_target, "translation_unit_function_order", ())
    )
    uses_translation_units = bool(
        getattr(
            selected_target,
            "check_translation_unit_function_order",
            False,
        )
    )
    definition_path = str(
        getattr(
            compiled_entry,
            "source_from",
            getattr(selected_target, "source_from", ""),
        )
    )
    target_definition_paths = (
        tuple(
            str(getattr(entry, "source_from", ""))
            for entry in translation_units
        )
        if uses_translation_units
        else (str(getattr(selected_target, "source_from", "")),)
    )
    if (
        target_id != f"recoil:vc5-target:{target_name}"
        or target_binary != "recoil"
        or len(matching_target_rows) != 1
        or str(getattr(matching_target_rows[0], "symbol", ""))
        != expected_identity
        or getattr(matching_target_rows[0], "symbol_regex", None) is not None
        or (uses_translation_units and compiled_entry not in translation_units)
        or (uses_translation_units and compiled_entry is None)
        or (not uses_translation_units and compiled_entry is not None)
        or not definition_path
        or any(not path for path in target_definition_paths)
        or len(
            {path.casefold() for path in target_definition_paths}
        )
        != len(target_definition_paths)
        or target_definition_paths.count(definition_path) != 1
    ):
        route["blocker_reason"] = "selected-target-definition-authority-mismatch"
        return route

    repository_inventory = load_repository_path_inventory(REPO_ROOT)
    root = repository_inventory.repository_root
    try:
        config = load_final_build_config(DEFAULT_FINAL_BUILD_MANIFEST)
        configured_sources, _stale_diagnostics = (
            _call_contract_final_build_source_map(
                config,
                inventory=repository_inventory,
            )
        )
        resolver = _call_contract_callable_inventory_resolver(
            document, root=root
        )
        target_source_contexts: dict[str, tuple[str, ...]] = {}
        for target_path in target_definition_paths:
            configured_target_sources = configured_sources.get(
                target_path.casefold(), []
            )
            if (
                len(configured_target_sources) != 1
                or configured_target_sources[0][0] != target_path
            ):
                route["blocker_reason"] = (
                    "selected-target-definition-unsupported-or-aliased"
                )
                return route
            target_source_contexts[target_path] = (
                _call_contract_vc5_preprocessor_defines(
                    config, configured_target_sources[0][1]
                )
            )
        definition_context = target_source_contexts[definition_path]
        declaration_paths = sorted(
            {
                path
                for path in closure.header_paths
                if expected.callable_key
                in resolver(path, definition_context).declarations
            },
            key=lambda path: (path.casefold(), path),
        )
        definition_matches = [
            target_path
            for target_path, context in target_source_contexts.items()
            if expected.callable_key
            in resolver(target_path, context).definitions
        ]
    except (OSError, RuntimeError, ValueError, ProgressError) as exc:
        route["blocker_reason"] = (
            "declaration-header-definition-resolution-error"
        )
        route["resolution_error"] = str(exc)
        return route

    route["declaration_paths"] = declaration_paths
    if len(declaration_paths) != 1:
        route["blocker_reason"] = (
            "declaration-header-missing"
            if not declaration_paths
            else "declaration-header-ambiguous"
        )
        return route
    route["definition_paths"] = definition_matches
    if definition_matches != [definition_path]:
        route["blocker_reason"] = (
            "selected-target-definition-missing"
            if not definition_matches
            else "selected-target-definition-ambiguous-or-mismatched"
        )
        return route
    declaration_path = declaration_paths[0]
    routed_path_specs = (
        (
            declaration_path,
            CALL_CONTRACT_HEADER_SUFFIXES,
            closure.header_paths,
            "declaration-header",
        ),
        (
            definition_path,
            CALL_CONTRACT_SOURCE_SUFFIXES,
            closure.registered_source_paths,
            "selected-target-definition",
        ),
    )
    for routed_path, suffixes, authority_paths, label in routed_path_specs:
        try:
            repository_routed = resolve_repository_file(
                routed_path,
                repository_root=root,
                inventory=repository_inventory,
                context=f"call-contract {label}",
                allowed_suffixes=suffixes,
            )
        except RepositoryPathError:
            route["blocker_reason"] = f"{label}-escaping"
            return route
        authority_casefolds = [
            path.casefold() for path in authority_paths
        ]
        if (
            repository_routed.repository_path != routed_path
            or authority_casefolds.count(routed_path.casefold()) != 1
            or (
                label == "selected-target-definition"
                and routed_path not in closure.source_edit_paths
            )
            or routed_path not in closure.dependency_paths
        ):
            route["blocker_reason"] = f"{label}-unsupported-or-aliased"
            return route
    route["routing_mode"] = "exact"
    route["candidate_identity"] = route["candidate_identities"][0]
    route["source_edit_paths"] = sorted(
        {declaration_path, definition_path},
        key=lambda path: (path.casefold(), path),
    )
    return route


def _candidate_body_compiled_unit_blocker_route(
    *,
    target_id: str,
    symbol_id: str,
    address: str,
    expected_identity: str,
    unit_count: int,
) -> dict[str, Any] | None:
    """Return a typed non-repairable route when TU authority is not unique."""

    expected = _decode_candidate_body_zero_argument_identity(
        expected_identity
    )
    if expected is None:
        return None
    return {
        "kind": "call-contract-candidate-body-declaration-header-route",
        "contract_version": 1,
        "target_id": target_id,
        "symbol_id": symbol_id,
        "address": address,
        "expected_identity": expected.as_dict(),
        "candidate_identities": [],
        "candidate_cod_path": "",
        "candidate_object_path": "",
        "declaration_paths": [],
        "definition_paths": [],
        "source_edit_paths": [],
        "routing_mode": "blocked",
        "blocker_reason": (
            "selected-target-compiled-unit-missing"
            if unit_count == 0
            else "selected-target-compiled-unit-ambiguous"
        ),
        "candidate_expected_truth": False,
        "ambiguity_policy": "fail-closed",
    }


def call_contract_source_write_paths(
    document: ProgressDocument,
    slice_row: Mapping[str, Any],
) -> list[str]:
    """Return the exact target-authorized writable source/header closure."""

    return list(
        call_contract_source_closure(document, slice_row).source_edit_paths
    )


def _compile_call_contract_definition_sources(
    closure: CallContractSourceClosure,
    *,
    build_root: Path,
    vc5_env: Path,
) -> tuple[dict[str, Any], ...]:
    """Compile exact out-of-root definition TUs with final-build profiles."""

    registered = {
        path.casefold() for path in closure.registered_source_paths
    }
    additional = tuple(
        path
        for path in closure.definition_source_paths
        if path.casefold() not in registered
    )
    if not additional:
        return ()

    config = load_final_build_config(DEFAULT_FINAL_BUILD_MANIFEST)
    config = replace(config, vc5_env=vc5_env)
    requested_build_dir = (
        build_root.resolve() / "call-contract-definition-closure"
    )
    try:
        requested_build_dir_relative = requested_build_dir.relative_to(
            REPO_ROOT.resolve()
        )
    except ValueError as exc:
        raise ValueError(
            "call-contract definition-closure build root must remain inside "
            "the repository"
        ) from exc
    config = with_final_build_dir(config, requested_build_dir_relative)
    prepare_clean_build_dir(build_root, "call-contract-definition-closure")
    paths = final_build_paths(config)
    repository_inventory = load_repository_path_inventory(REPO_ROOT)
    configured_rows, _stale_diagnostics = _call_contract_final_build_source_map(
        config,
        inventory=repository_inventory,
    )
    configured = {
        key: rows[0][1]
        for key, rows in configured_rows.items()
        if len(rows) == 1
    }
    rows: list[dict[str, Any]] = []
    for relative in additional:
        source = configured.get(relative.casefold())
        if source is None:
            raise ValueError(
                "call-contract definition source is not configured by the "
                f"final build: {relative}"
            )
        command, object_path = make_final_build_compile_command(
            config,
            paths,
            source,
        )
        result = run_final_build_command(command)
        row = {
            "source": relative,
            "returncode": result.returncode,
            "object_path": object_path.resolve()
            .relative_to(REPO_ROOT.resolve())
            .as_posix(),
            "stdout_log": result.stdout_log.resolve()
            .relative_to(REPO_ROOT.resolve())
            .as_posix(),
            "stderr_log": result.stderr_log.resolve()
            .relative_to(REPO_ROOT.resolve())
            .as_posix(),
        }
        rows.append(row)
        if result.returncode != 0:
            tail = [
                *read_final_build_log_tail(result.stdout_log),
                *read_final_build_log_tail(result.stderr_log),
            ]
            detail = " | ".join(tail) if tail else "no compiler diagnostic"
            raise ValueError(
                "call-contract definition-closure VC5 compile failed for "
                f"{relative} with exit code {result.returncode}: {detail}; "
                f"logs: {row['stdout_log']}, {row['stderr_log']}"
            )
    return tuple(rows)


def _compile_definition_closure_after_comparison(
    first_divergence: Mapping[str, Any] | None,
    closure: CallContractSourceClosure,
    *,
    build_root: Path,
    vc5_env: Path,
) -> tuple[dict[str, Any], ...]:
    """Compile the complete definition closure only for a semantic PASS."""

    if first_divergence is not None:
        return ()
    return _compile_call_contract_definition_sources(
        closure,
        build_root=build_root,
        vc5_env=vc5_env,
    )


def _source_signature_recheck(
    first_divergence: dict[str, Any] | None,
    signatures_before: list[dict[str, Any]],
    signatures_after: list[dict[str, Any]],
) -> tuple[dict[str, Any] | None, bool]:
    """Apply the existing fail-closed signature rule without changing priority."""

    changed = signatures_before != signatures_after
    if changed and first_divergence is None:
        first_divergence = {
            "kind": "source-dependency-changed-during-validation",
            "before": signatures_before,
            "after": signatures_after,
        }
    return first_divergence, changed


def source_dependency_paths(
    document: ProgressDocument,
    slice_row: Mapping[str, Any],
    *,
    source_write_paths: Sequence[str] | None = None,
    source_closure: CallContractSourceClosure | None = None,
    repository_path_inventory: RepositoryPathInventory | None = None,
) -> list[str]:
    closure = source_closure or call_contract_source_closure(
        document,
        slice_row,
        repository_path_inventory=repository_path_inventory,
    )
    paths = set(closure.dependency_paths)
    if source_write_paths is not None:
        paths.update(source_write_paths)
    return sorted(paths, key=lambda path: (path.casefold(), path))


def _symbol_identity(symbol_id: str, symbol: Mapping[str, Any]) -> str:
    if (
        symbol.get("kind") in {"provider-function", "compiler-function"}
        or symbol.get("pipeline_class") == "non-authored"
    ):
        return f"provider:{symbol_id}"
    return f"symbol:{symbol_id}"


def _decorated_coff_name(name: str) -> bool:
    if (
        not name
        or any(character.isspace() for character in name)
        or any(character in ",]" for character in name)
    ):
        return False
    if name.startswith("?"):
        return len(name) > 1
    if name.startswith("__imp_"):
        return len(name) > len("__imp_")
    if name[0] not in {"_", "@"} or len(name) < 2:
        return False
    first = name[1]
    if not (("A" <= first <= "Z") or ("a" <= first <= "z")):
        return False
    return all(
        ("A" <= character <= "Z")
        or ("a" <= character <= "z")
        or ("0" <= character <= "9")
        or character in "_@$?"
        for character in name[2:]
    )


def _finite_literal_symbol_regex_alternatives(
    symbol_regex: Any,
) -> tuple[str, ...] | None:
    """Enumerate one deliberately tiny regex language without executing regex."""
    if (
        not isinstance(symbol_regex, str)
        or len(symbol_regex) > FINITE_SYMBOL_REGEX_MAX_ENCODED_LENGTH
        or not symbol_regex.startswith("^(?:")
        or not symbol_regex.endswith(")$")
    ):
        return None
    encoded = symbol_regex[4:-2]
    alternatives: list[str] = []
    decoded: list[str] = []
    index = 0
    while index < len(encoded):
        character = encoded[index]
        if character == "|":
            name = "".join(decoded)
            if not name:
                return None
            alternatives.append(name)
            if len(alternatives) > FINITE_SYMBOL_REGEX_MAX_ALTERNATIVES:
                return None
            decoded = []
            index += 1
            continue
        if character == "\\":
            index += 1
            if index >= len(encoded):
                return None
            escaped = encoded[index]
            if escaped not in FINITE_SYMBOL_REGEX_LITERAL_METACHARACTERS:
                return None
            decoded.append(escaped)
        elif character in FINITE_SYMBOL_REGEX_LITERAL_METACHARACTERS:
            return None
        else:
            decoded.append(character)
        if len(decoded) > FINITE_SYMBOL_REGEX_MAX_DECODED_NAME_LENGTH:
            return None
        index += 1
    name = "".join(decoded)
    if not name:
        return None
    alternatives.append(name)
    if (
        len(alternatives) < 2
        or len(alternatives) > FINITE_SYMBOL_REGEX_MAX_ALTERNATIVES
        or len(set(alternatives)) != len(alternatives)
        or any(not _decorated_coff_name(item) for item in alternatives)
    ):
        return None
    return tuple(alternatives)


def _mapping_target_function_rows(
    target: Mapping[str, Any],
) -> tuple[Mapping[str, Any], ...]:
    return tuple(
        row for _view, row in _mapping_target_function_rows_with_views(target)
    )


def _mapping_target_function_rows_with_views(
    target: Mapping[str, Any],
) -> tuple[tuple[str, Mapping[str, Any]], ...]:
    registration = target.get("registration")
    if not isinstance(registration, Mapping):
        return ()
    rows: list[tuple[str, Mapping[str, Any]]] = [
        ("functions", row)
        for row in registration.get("functions", [])
        if isinstance(row, Mapping)
    ]
    for collection_name in (
        "translation_unit_function_order",
        "linked_function_intervals",
    ):
        for entry in registration.get(collection_name, []):
            if not isinstance(entry, Mapping):
                continue
            rows.extend(
                (collection_name, row)
                for row in entry.get("functions", [])
                if isinstance(row, Mapping)
            )
    return tuple(rows)


def _synchronized_finite_symbol_regex_target(
    target_id: str,
    target: Mapping[str, Any],
    *,
    address: str,
    row: Mapping[str, Any],
) -> None:
    registration = target.get("registration")
    if not isinstance(registration, Mapping):
        raise ValueError(
            f"finite symbol-regex authority target {target_id!r} has no registration"
        )
    manifest_value = registration.get("manifest_path")
    if not isinstance(manifest_value, str) or not manifest_value:
        raise ValueError(
            f"finite symbol-regex authority target {target_id!r} has no manifest path"
        )
    manifest_path = Path(manifest_value)
    if not manifest_path.is_absolute():
        manifest_path = REPO_ROOT / manifest_path
    try:
        manifest_path = manifest_path.resolve()
        manifest_path.relative_to(
            (REPO_ROOT / "tools" / "vc5_verify_targets").resolve()
        )
    except ValueError as exc:
        raise ValueError(
            f"finite symbol-regex authority target {target_id!r} manifest is outside "
            "tools/vc5_verify_targets"
        ) from exc
    if not manifest_path.is_file():
        raise ValueError(
            f"finite symbol-regex authority target {target_id!r} manifest is missing"
        )
    from _recoil.lib.verification_targets import vc5_target_registration

    try:
        current_id, current = vc5_target_registration(manifest_path)
    except (OSError, ValueError) as exc:
        raise ValueError(
            f"finite symbol-regex authority target {target_id!r} cannot be synchronized: {exc}"
        ) from exc
    current_registration = current.get("registration")
    stable_target_identity = (
        current_id == target_id
        and target.get("binary") == current.get("binary") == "recoil"
        and target.get("kind") == current.get("kind") == "vc5"
        and target.get("name") == current.get("name")
        and isinstance(current_registration, Mapping)
        and current_registration.get("manifest_path") == manifest_value
    )
    if not stable_target_identity:
        raise ValueError(
            f"finite symbol-regex authority target {target_id!r} is stale or conflicting"
        )
    current_registered = current.get("registered_addresses")
    if (
        not isinstance(current_registered, list)
        or sum(
            1
            for item in current_registered
            if isinstance(item, str)
            and normalize_address(item) == address
        )
        != 1
    ):
        raise ValueError(
            f"finite symbol-regex authority target {target_id!r} current "
            f"registration has missing or duplicate address {address}"
        )
    current_rows = [
        (view, current_row)
        for view, current_row in _mapping_target_function_rows_with_views(current)
        if isinstance(current_row.get("address"), str)
        and normalize_address(current_row["address"]) == address
    ]
    synchronized_fields = (
        "address",
        "pipeline_class",
        "authored_order_role",
        "authored_order_gate",
        "authored_relative_order_gate",
        "required_presence",
        "full_order_gate",
        "logical_identity_key",
        "icf_fold_status",
    )
    authority_rows = [
        current_row
        for _view, current_row in current_rows
        if any(
            isinstance(current_row.get(key), str)
            and bool(current_row.get(key))
            for key in ("symbol", "symbol_regex", "name")
        )
    ]
    if (
        not current_rows
        or len({view for view, _row in current_rows}) != len(current_rows)
        or any(
            tuple(current_row.get(field) for field in synchronized_fields)
            != tuple(row.get(field) for field in synchronized_fields)
            for _view, current_row in current_rows
        )
        or not authority_rows
        or any(dict(current_row) != dict(row) for current_row in authority_rows)
    ):
        raise ValueError(
            f"finite symbol-regex authority target {target_id!r} exact row at "
            f"{address} is stale, duplicated, or conflicting"
        )


def _index_finite_symbol_regex_names(
    document: ProgressDocument,
    *,
    by_address: Mapping[str, str],
    by_candidate_name: dict[str, str],
) -> None:
    symbols = document.collection("symbols")
    blocks = document.collection("physical_blocks")
    evidence = document.collection("evidence")
    symbol_rows_by_address: dict[
        str, list[tuple[str, Mapping[str, Any]]]
    ] = {}
    for symbol_id, symbol in symbols.items():
        if (
            not isinstance(symbol, Mapping)
            or symbol.get("kind")
            not in {"function", "provider-function", "compiler-function"}
        ):
            continue
        raw_address = symbol.get("address", symbol.get("start"))
        if not isinstance(raw_address, str):
            continue
        try:
            address = normalize_address(raw_address)
        except ProgressError:
            continue
        symbol_rows_by_address.setdefault(address, []).append(
            (str(symbol_id), symbol)
        )

    finite_names: dict[str, tuple[str, str, str]] = {}
    for target_id, target in document.collection("verification_targets").items():
        if not isinstance(target, Mapping):
            continue
        finite_rows: list[
            tuple[str, Mapping[str, Any], tuple[str, ...]]
        ] = []
        for view, row in _mapping_target_function_rows_with_views(target):
            alternatives = _finite_literal_symbol_regex_alternatives(
                row.get("symbol_regex")
            )
            if alternatives is not None:
                finite_rows.append((view, row, alternatives))
        if not finite_rows:
            continue

        seen_row_addresses: set[str] = set()
        for _view, row, alternatives in finite_rows:
            raw_address = row.get("address")
            if not isinstance(raw_address, str):
                continue
            try:
                address = normalize_address(raw_address)
            except ProgressError:
                continue
            if (
                row.get("required_presence") is not True
                or row.get("pipeline_class")
                not in {"authored", "authored-lifecycle"}
                or row.get("authored_order_role")
                not in {"authored-body", "authored-lifecycle-body"}
                or row.get("authored_order_gate") is not True
                or row.get("authored_relative_order_gate") is not True
                or row.get("logical_identity_key") not in {None, ""}
                or row.get("icf_fold_status") not in {None, ""}
            ):
                # Only physical authored gating rows can grant finite-name
                # authority. Inventory, provider, and logical-alias rows are
                # deliberately invisible to this candidate index.
                continue
            same_address_rows: list[
                tuple[str, Mapping[str, Any]]
            ] = []
            for (
                candidate_view,
                candidate_row,
                _candidate_alternatives,
            ) in finite_rows:
                candidate_raw_address = candidate_row.get("address")
                if not isinstance(candidate_raw_address, str):
                    continue
                try:
                    candidate_address = normalize_address(
                        candidate_raw_address
                    )
                except ProgressError:
                    continue
                if candidate_address == address:
                    same_address_rows.append(
                        (candidate_view, candidate_row)
                    )
            if (
                len(
                    {
                        candidate_view
                        for candidate_view, _candidate_row in same_address_rows
                    }
                )
                != len(same_address_rows)
            ):
                raise ValueError(
                    f"finite symbol-regex authority target {target_id!r} has "
                    f"duplicate rows for {address}"
                )
            if normalize_address(address) != "0x4b9850" and any(
                dict(candidate_row) != dict(row)
                for _candidate_view, candidate_row in same_address_rows
            ):
                raise ValueError(
                    f"finite symbol-regex authority target {target_id!r} has "
                    f"conflicting rows for {address}"
                )
            if address in seen_row_addresses:
                continue
            seen_row_addresses.add(address)
            physical_rows = symbol_rows_by_address.get(address, [])
            if len(physical_rows) != 1:
                raise ValueError(
                    f"finite symbol-regex row {target_id}:{address} has ambiguous "
                    "physical symbol population"
                )
            symbol_id, symbol = physical_rows[0]
            identity = by_address.get(address, "")
            if identity != f"symbol:{symbol_id}":
                raise ValueError(
                    f"finite symbol-regex row {target_id}:{address} has unresolved "
                    "or aliased physical identity"
                )
            block_id = str(symbol.get("physical_block_id") or "")
            block = blocks.get(block_id)
            facts = (
                block.get("accepted_order_facts")
                if isinstance(block, Mapping)
                else None
            )
            if (
                not isinstance(facts, Mapping)
                or facts.get("target_id") != target_id
            ):
                # Historical or non-accepted target rows are not authority.
                continue
            registered = target.get("registered_addresses")
            if (
                not isinstance(registered, list)
                or sum(
                    1
                    for item in registered
                    if isinstance(item, str)
                    and normalize_address(item) == address
                )
                != 1
            ):
                raise ValueError(
                    f"finite symbol-regex authority target {target_id!r} has "
                    f"missing or duplicate registered address {address}"
                )
            _synchronized_finite_symbol_regex_target(
                str(target_id),
                target,
                address=address,
                row=row,
            )
            if (
                facts.get("phase") != "authored-function-order"
                or facts.get("validation_mode") != "live"
                or not isinstance(facts.get("covered_block_ids"), list)
                or facts["covered_block_ids"].count(block_id) != 1
                or not isinstance(facts.get("matched_identities"), list)
                or facts["matched_identities"].count(symbol_id) != 1
            ):
                raise ValueError(
                    f"finite symbol-regex row {target_id}:{address} lacks exact "
                    "accepted authored-order block facts"
                )
            authored = block.get("order", {}).get("authored", {})
            if not isinstance(authored, Mapping):
                raise ValueError(
                    f"finite symbol-regex row {target_id}:{address} lacks authored-order state"
                )
            evidence_ids: set[str] = set()
            for dimension in AUTHORED_ORDER_DIMENSIONS:
                state = authored.get(dimension)
                if not is_current_accepted_state(state):
                    raise ValueError(
                        f"finite symbol-regex row {target_id}:{address} has stale "
                        f"authored-order state {dimension}"
                    )
                raw_evidence_ids = state.get("evidence_ids")
                if (
                    not isinstance(raw_evidence_ids, list)
                    or not raw_evidence_ids
                    or any(
                        not isinstance(item, str) or not item
                        for item in raw_evidence_ids
                    )
                ):
                    raise ValueError(
                        f"finite symbol-regex row {target_id}:{address} lacks "
                        f"accepted evidence for {dimension}"
                    )
                evidence_ids.update(raw_evidence_ids)
            for evidence_id in evidence_ids:
                evidence_row = evidence.get(evidence_id)
                provenance = (
                    evidence_row.get("provenance")
                    if isinstance(evidence_row, Mapping)
                    else None
                )
                if (
                    not is_current_accepted_state(evidence_row)
                    or not isinstance(provenance, Mapping)
                    or provenance.get("phase") != "authored-function-order"
                    or provenance.get("target_id") != target_id
                    or not isinstance(provenance.get("covered_block_ids"), list)
                    or provenance["covered_block_ids"].count(block_id) != 1
                    or not isinstance(provenance.get("expected_sequence"), list)
                    or provenance["expected_sequence"].count(symbol_id) != 1
                    or not isinstance(provenance.get("candidate_sequence"), list)
                    or provenance["candidate_sequence"].count(symbol_id) != 1
                ):
                    raise ValueError(
                        f"finite symbol-regex row {target_id}:{address} has stale "
                        f"or mismatched accepted evidence {evidence_id!r}"
                    )
            exact_symbol = row.get("symbol")
            if (
                isinstance(exact_symbol, str)
                and exact_symbol
                and exact_symbol not in alternatives
            ):
                raise ValueError(
                    f"finite symbol-regex row {target_id}:{address} exact symbol "
                    "disagrees with its alternatives"
                )
            for name in alternatives:
                previous_finite = finite_names.get(name)
                authority = (identity, str(target_id), address)
                if previous_finite is not None:
                    raise ValueError(
                        f"finite symbol-regex candidate name {name!r} has duplicate "
                        f"or ambiguous authority {previous_finite!r} and {authority!r}"
                    )
                finite_names[name] = authority
                prior = by_candidate_name.get(name)
                if prior is not None and prior != identity:
                    raise ValueError(
                        f"finite symbol-regex candidate name {name!r} conflicts "
                        f"with exact identity {prior!r}"
                    )
                if prior is None:
                    by_candidate_name[name] = identity


def _deleting_destructor_names_for_complete(
    complete_name: Any,
) -> tuple[str, str]:
    """Return the two exact VC5 deleting variants for one complete destructor."""
    if not isinstance(complete_name, str):
        return ()
    match = MSVC_COMPLETE_DESTRUCTOR_PARTS_RE.fullmatch(complete_name)
    if match is None:
        return ()
    class_name = match.group("class_name")
    qualifier = match.group("qualifier")
    return tuple(
        f"??_{variant}{class_name}{qualifier}PAXI@Z"
        for variant in ("E", "G")
    )


def _registered_lifecycle_deleting_destructor_supplier(
    document: ProgressDocument,
    *,
    target_id: str,
    row: Mapping[str, Any],
    by_address: Mapping[str, str],
) -> tuple[RegisteredLifecycleDeletingDestructorSupplier, ...] | None:
    """Prove one current manifest row is an exact non-gating lifecycle identity."""
    complete_name = row.get("symbol")
    candidate_names = _deleting_destructor_names_for_complete(complete_name)
    raw_address = row.get("address")
    if not candidate_names or not isinstance(raw_address, str):
        return None
    try:
        address = normalize_address(raw_address)
    except ProgressError:
        return None
    if (
        row.get("symbol_regex") is not None
        or row.get("pipeline_class") != "authored-lifecycle"
        or row.get("authored_order_role")
        != "compiler-generated-implicit-cleanup"
        or row.get("authored_order_gate") is not False
        or row.get("authored_relative_order_gate") is not False
        or row.get("required_presence") is not True
        or row.get("full_order_gate") is not True
        or row.get("logical_identity_key") not in {None, ""}
        or row.get("icf_fold_status") not in {None, ""}
    ):
        return None

    physical_rows: list[tuple[str, Mapping[str, Any]]] = []
    for symbol_id, symbol in document.collection("symbols").items():
        if (
            not isinstance(symbol, Mapping)
            or symbol.get("kind")
            not in {"function", "provider-function", "compiler-function"}
        ):
            continue
        raw_symbol_address = symbol.get("address", symbol.get("start"))
        if not isinstance(raw_symbol_address, str):
            continue
        try:
            if normalize_address(raw_symbol_address) == address:
                physical_rows.append((str(symbol_id), symbol))
        except ProgressError:
            continue
    if len(physical_rows) != 1:
        return None
    symbol_id, symbol = physical_rows[0]
    raw_end = symbol.get("end_exclusive")
    raw_size = symbol.get("size")
    logical_aliases = symbol.get("logical_aliases")
    icf_group = symbol.get("icf_address_group")
    if (
        symbol.get("binary") != "recoil"
        or symbol.get("kind") != "function"
        or symbol.get("pipeline_class") != "authored-lifecycle"
        or symbol.get("authored_order_role")
        != "compiler-generated-implicit-cleanup"
        or symbol.get("extent_state") != "known"
        or isinstance(raw_size, bool)
        or not isinstance(raw_size, int)
        or raw_size <= 0
        or not isinstance(raw_end, str)
        or address_value(normalize_address(raw_end))
        - address_value(address)
        != raw_size
        or symbol.get("logical_identity_key") not in {None, ""}
        or symbol.get("icf_fold_status") not in {None, ""}
        or isinstance(logical_aliases, Mapping)
        and bool(logical_aliases)
        or isinstance(icf_group, Mapping)
        and bool(icf_group)
    ):
        return None
    identity = f"symbol:{symbol_id}"
    if by_address.get(address) != identity:
        return None
    return tuple(
        RegisteredLifecycleDeletingDestructorSupplier(
            candidate_name=candidate_name,
            complete_name=str(complete_name),
            address=address,
            identity=identity,
            target_id=target_id,
        )
        for candidate_name in candidate_names
    )


def _index_registered_lifecycle_deleting_destructor_names(
    document: ProgressDocument,
    *,
    by_address: Mapping[str, str],
    by_candidate_name: dict[str, str],
) -> None:
    """Bridge exact VC5 deleting names only from convergent current lifecycle rows."""
    from _recoil.lib.verification_targets import vc5_target_registration

    suppliers_by_name: dict[
        str, list[RegisteredLifecycleDeletingDestructorSupplier]
    ] = {}
    complete_names_by_address: dict[str, set[str]] = {}
    ambiguous_names: set[str] = set()
    manifest_root = (REPO_ROOT / "tools" / "vc5_verify_targets").resolve()
    for target_id, target in document.collection(
        "verification_targets"
    ).items():
        if (
            not isinstance(target, Mapping)
            or target.get("binary") != "recoil"
            or target.get("kind") != "vc5"
        ):
            continue
        registration = target.get("registration")
        if not isinstance(registration, Mapping):
            continue
        manifest_value = registration.get("manifest_path")
        if not isinstance(manifest_value, str) or not manifest_value:
            continue
        manifest_path = Path(manifest_value)
        if not manifest_path.is_absolute():
            manifest_path = REPO_ROOT / manifest_path
        try:
            manifest_path = manifest_path.resolve()
            manifest_path.relative_to(manifest_root)
            if not manifest_path.is_file():
                continue
            current_id, current_target = vc5_target_registration(
                manifest_path
            )
        except (OSError, ProgressError, ValueError):
            continue
        current_registration = current_target.get("registration")
        stable_target = (
            current_id == target_id
            and current_target.get("binary") == target.get("binary") == "recoil"
            and current_target.get("kind") == target.get("kind") == "vc5"
            and current_target.get("name") == target.get("name")
            and isinstance(current_registration, Mapping)
            and current_registration.get("manifest_path") == manifest_value
        )
        current_rows = [
            row
            for row in _mapping_target_function_rows(current_target)
            if _deleting_destructor_names_for_complete(row.get("symbol"))
        ]
        for row in current_rows:
            complete_name = str(row["symbol"])
            candidate_names = _deleting_destructor_names_for_complete(
                complete_name
            )
            raw_address = row.get("address")
            try:
                address = normalize_address(str(raw_address))
            except ProgressError:
                ambiguous_names.update(candidate_names)
                continue
            complete_names_by_address.setdefault(address, set()).add(
                complete_name
            )
            same_identity_rows = [
                candidate
                for candidate in current_rows
                if candidate.get("symbol") == complete_name
                and isinstance(candidate.get("address"), str)
                and normalize_address(candidate["address"]) == address
            ]
            if not stable_target or len(same_identity_rows) != 1:
                ambiguous_names.update(candidate_names)
                continue
            suppliers = _registered_lifecycle_deleting_destructor_supplier(
                document,
                target_id=str(target_id),
                row=row,
                by_address=by_address,
            )
            if suppliers is None:
                ambiguous_names.update(candidate_names)
                continue
            for supplier in suppliers:
                suppliers_by_name.setdefault(
                    supplier.candidate_name, []
                ).append(supplier)

    for address, complete_names in complete_names_by_address.items():
        if len(complete_names) <= 1:
            continue
        for complete_name in complete_names:
            ambiguous_names.update(
                _deleting_destructor_names_for_complete(complete_name)
            )
    for name in set(suppliers_by_name) | ambiguous_names:
        suppliers = suppliers_by_name.get(name, [])
        identities = {
            (
                supplier.identity,
                supplier.address,
                supplier.complete_name,
            )
            for supplier in suppliers
        }
        prior = by_candidate_name.get(name)
        if (
            name in ambiguous_names
            or len(identities) != 1
            or prior not in {None, next(iter(identities))[0]}
        ):
            by_candidate_name[name] = ""
            continue
        by_candidate_name[name] = next(iter(identities))[0]


def _nonvirtual_scalar_deleting_destructor_class(
    name: Any,
) -> tuple[str, str] | None:
    """Parse one exact natural VC5 x86 nonvirtual scalar-deleting ABI."""
    if not isinstance(name, str):
        return None
    match = MSVC_NONVIRTUAL_SCALAR_DELETING_DESTRUCTOR_RE.fullmatch(name)
    if match is None:
        return None
    encoded = match.group("class_scope")
    return encoded, "::".join(reversed(encoded.split("@")))


def _scalar_deleting_destructor_row_class(
    row: Mapping[str, Any],
) -> str | None:
    """Return the one literal ``??_G`` class family carried by a row."""
    symbol = row.get("symbol")
    symbol_regex = row.get("symbol_regex")
    if bool(symbol) == bool(symbol_regex):
        return None
    if symbol is not None and not isinstance(symbol, str):
        return None
    if isinstance(symbol, str) and symbol:
        parsed = _nonvirtual_scalar_deleting_destructor_class(symbol)
        return parsed[1] if parsed is not None else None
    if not isinstance(symbol_regex, str):
        return None
    try:
        re.compile(symbol_regex)
    except re.error:
        return None
    readable = symbol_regex.replace(r"\?", "?")
    encoded_classes = {
        match.group("class_scope")
        for match in re.finditer(
            r"\?\?_G"
            r"(?P<class_scope>[A-Za-z_][A-Za-z0-9_]*"
            r"(?:@[A-Za-z_][A-Za-z0-9_]*)*)@@",
            readable,
        )
    }
    if len(encoded_classes) != 1:
        return None
    encoded = next(iter(encoded_classes))
    canonical = f"??_G{encoded}@@QAEPAXI@Z"
    if re.fullmatch(symbol_regex, canonical) is None:
        return None
    return "::".join(reversed(encoded.split("@")))


def _synchronized_scalar_deleting_destructor_targets(
    document: ProgressDocument,
    *,
    address: str,
    class_identity: str,
    navigation_name: str,
) -> tuple[tuple[str, ...], str | None]:
    """Find convergent current VC5 rows for one reviewed deleting variant."""
    from _recoil.lib.verification_targets import vc5_target_registration

    evidence: set[str] = set()
    manifest_root = (REPO_ROOT / "tools" / "vc5_verify_targets").resolve()

    def normalized_address_value(value: Any) -> str | None:
        if not isinstance(value, str):
            return None
        try:
            return normalize_address(value)
        except ProgressError:
            return None

    def normalized_row_address(row: Mapping[str, Any]) -> str | None:
        return normalized_address_value(row.get("address"))

    def relevant_row(row: Mapping[str, Any]) -> bool:
        return (
            normalized_row_address(row) == address
            or row.get("name") == navigation_name
        )

    for target_id, target in document.collection(
        "verification_targets"
    ).items():
        if (
            not isinstance(target, Mapping)
            or target.get("binary") != "recoil"
            or target.get("kind") != "vc5"
        ):
            continue
        stored_rows = [
            row
            for row in _mapping_target_function_rows(target)
            if relevant_row(row)
        ]
        if not stored_rows:
            continue
        registration = target.get("registration")
        manifest_value = (
            registration.get("manifest_path")
            if isinstance(registration, Mapping)
            else None
        )
        if not isinstance(manifest_value, str) or not manifest_value:
            return (), "stale or conflicting registered scalar-deleting-destructor evidence"
        manifest_path = Path(manifest_value)
        if not manifest_path.is_absolute():
            manifest_path = REPO_ROOT / manifest_path
        try:
            manifest_path = manifest_path.resolve()
            manifest_path.relative_to(manifest_root)
            if not manifest_path.is_file():
                raise ValueError("missing manifest")
            current_id, current = vc5_target_registration(manifest_path)
            raw_manifest = json.loads(
                manifest_path.read_text(encoding="utf-8")
            )
            if not isinstance(raw_manifest, Mapping):
                raise ValueError("manifest root is not an object")
        except (OSError, ProgressError, ValueError):
            return (), "stale or conflicting registered scalar-deleting-destructor evidence"
        current_registration = current.get("registration")
        if (
            current_id != target_id
            or not (
                current.get("binary")
                == target.get("binary")
                == "recoil"
            )
            or not (
                current.get("kind")
                == target.get("kind")
                == "vc5"
            )
            or current.get("name") != target.get("name")
            or not isinstance(current_registration, Mapping)
            or current_registration.get("manifest_path") != manifest_value
        ):
            return (), "stale or conflicting registered scalar-deleting-destructor evidence"
        registered_addresses = current.get("registered_addresses")
        if (
            not isinstance(registered_addresses, list)
            or sum(
                1
                for item in registered_addresses
                if normalized_address_value(item) == address
            )
            != 1
        ):
            return (), "stale or conflicting registered scalar-deleting-destructor evidence"
        current_rows = [
            row
            for row in _mapping_target_function_rows(current)
            if relevant_row(row)
        ]
        stored_matches = [
            row
            for row in stored_rows
            if normalized_row_address(row) == address
            and row.get("name") == navigation_name
            and _scalar_deleting_destructor_row_class(row)
            == class_identity
        ]
        current_matches = [
            row
            for row in current_rows
            if normalized_row_address(row) == address
            and row.get("name") == navigation_name
            and _scalar_deleting_destructor_row_class(row)
            == class_identity
        ]
        raw_rows: list[Mapping[str, Any]] = [
            row
            for row in raw_manifest.get("functions", [])
            if isinstance(row, Mapping)
        ]
        for collection_name in (
            "translation_unit_function_order",
            "linked_function_intervals",
        ):
            for entry in raw_manifest.get(collection_name, []):
                if isinstance(entry, Mapping):
                    raw_rows.extend(
                        row
                        for row in entry.get("functions", [])
                        if isinstance(row, Mapping)
                    )
        raw_matches = [
            row
            for row in raw_rows
            if normalized_row_address(row) == address
            and row.get("name") == navigation_name
            and _scalar_deleting_destructor_row_class(row)
            == class_identity
        ]
        raw_relevant_rows = [row for row in raw_rows if relevant_row(row)]

        def authority(row: Mapping[str, Any]) -> tuple[Any, ...]:
            raw_symbol = row.get("symbol")
            raw_symbol_regex = row.get("symbol_regex")
            return (
                normalize_address(str(row.get("address"))),
                row.get("name"),
                raw_symbol if isinstance(raw_symbol, str) else "",
                (
                    raw_symbol_regex
                    if isinstance(raw_symbol_regex, str)
                    else ""
                ),
                _scalar_deleting_destructor_row_class(row),
            )

        if (
            len(stored_rows) != 1
            or len(current_rows) != 1
            or len(raw_relevant_rows) != 1
            or len(stored_matches) != 1
            or len(current_matches) != 1
            or len(raw_matches) != 1
            or authority(stored_matches[0])
            != authority(current_matches[0])
            or authority(stored_matches[0])
            != authority(raw_matches[0])
        ):
            return (), "stale or conflicting registered scalar-deleting-destructor evidence"
        evidence.add(f"registered:{target_id}")
    return tuple(sorted(evidence)), None


def _scalar_deleting_destructor_bn_evidence(
    bridge_by_address: Mapping[str, Any],
    *,
    address: str,
    class_identity: str,
    navigation_name: str,
) -> tuple[bool, bool]:
    """Return ``(present, conflicting)`` for exact retail BN symbol evidence."""
    rows: list[Any] = []
    for raw_address, row in bridge_by_address.items():
        try:
            if normalize_address(str(raw_address)) == address:
                rows.append(row)
        except ProgressError:
            continue
    if len(rows) > 1:
        return False, True
    if not rows:
        return False, False
    row = rows[0]
    try:
        row_address = normalize_address(str(getattr(row, "address", "")))
    except ProgressError:
        return False, True
    if row_address != address:
        return False, True
    names = {
        str(value)
        for value in (
            getattr(row, "name", ""),
            getattr(row, "raw_name", ""),
            getattr(row, "full_name", ""),
        )
        if value
    }
    observed_classes: set[str] = set()
    malformed_abi = False
    for name in names:
        navigation = SCALAR_DELETING_DESTRUCTOR_NAVIGATION_RE.fullmatch(name)
        if navigation is not None:
            observed_classes.add(navigation.group("class_name"))
        if name.startswith(MSVC_SCALAR_DELETING_DESTRUCTOR_PREFIX):
            parsed = _nonvirtual_scalar_deleting_destructor_class(name)
            if parsed is None:
                malformed_abi = True
            else:
                observed_classes.add(parsed[1])
    if malformed_abi or observed_classes - {class_identity}:
        return False, True
    return (
        navigation_name in names or class_identity in observed_classes,
        False,
    )


def _registered_scalar_deleting_destructor_suppliers(
    document: ProgressDocument,
    *,
    by_address: Mapping[str, str],
    bridge_by_address: Mapping[str, Any],
) -> tuple[
    tuple[RegisteredScalarDeletingDestructorSupplier, ...],
    dict[str, str],
]:
    """Index reviewed direct deleting variants without candidate-derived truth."""
    candidates_by_class: dict[
        str, list[tuple[str, Mapping[str, Any], str]]
    ] = {}
    for symbol_id, symbol in document.collection("symbols").items():
        if not isinstance(symbol, Mapping):
            continue
        navigation_name = symbol.get("navigation_name")
        navigation = (
            SCALAR_DELETING_DESTRUCTOR_NAVIGATION_RE.fullmatch(
                navigation_name
            )
            if isinstance(navigation_name, str)
            else None
        )
        if navigation is None:
            continue
        candidates_by_class.setdefault(
            navigation.group("class_name"), []
        ).append((str(symbol_id), symbol, navigation_name))

    suppliers: list[RegisteredScalarDeletingDestructorSupplier] = []
    blockers: dict[str, str] = {}
    for class_identity, candidates in candidates_by_class.items():
        if len(candidates) != 1:
            blockers[class_identity] = (
                "ambiguous reviewed scalar-deleting-destructor tracker identity"
            )
            continue
        symbol_id, symbol, navigation_name = candidates[0]
        raw_address = symbol.get("address", symbol.get("start"))
        raw_end = symbol.get("end_exclusive")
        raw_size = symbol.get("size")
        try:
            address = normalize_address(str(raw_address))
            end_exclusive = normalize_address(str(raw_end))
        except ProgressError:
            blockers[class_identity] = (
                "stale or conflicting scalar-deleting-destructor tracker identity"
            )
            continue
        identity = f"symbol:{symbol_id}"
        logical_aliases = symbol.get("logical_aliases")
        icf_group = symbol.get("icf_address_group")
        if (
            symbol.get("binary") != "recoil"
            or symbol.get("kind") != "function"
            or symbol.get("pipeline_class") != "authored-lifecycle"
            or symbol.get("authored_order_role")
            != "compiler-generated-deleting-variant"
            or symbol.get("extent_state") != "known"
            or isinstance(raw_size, bool)
            or not isinstance(raw_size, int)
            or raw_size <= 0
            or address_value(end_exclusive) - address_value(address)
            != raw_size
            or by_address.get(address) != identity
            or symbol.get("logical_identity_key") not in {None, ""}
            or symbol.get("icf_fold_status") not in {None, ""}
            or isinstance(logical_aliases, Mapping)
            and bool(logical_aliases)
            or isinstance(icf_group, Mapping)
            and bool(icf_group)
        ):
            blockers[class_identity] = (
                "stale or conflicting scalar-deleting-destructor tracker identity"
            )
            continue
        registered, registration_blocker = (
            _synchronized_scalar_deleting_destructor_targets(
                document,
                address=address,
                class_identity=class_identity,
                navigation_name=navigation_name,
            )
        )
        bn_present, bn_conflicting = (
            _scalar_deleting_destructor_bn_evidence(
                bridge_by_address,
                address=address,
                class_identity=class_identity,
                navigation_name=navigation_name,
            )
        )
        if registration_blocker is not None or bn_conflicting:
            blockers[class_identity] = (
                registration_blocker
                or "conflicting BN scalar-deleting-destructor evidence"
            )
            continue
        evidence_sources = (
            *registered,
            *(("bn",) if bn_present else ()),
        )
        if not evidence_sources:
            blockers[class_identity] = (
                "missing current registered or BN-backed scalar-deleting-destructor evidence"
            )
            continue
        suppliers.append(
            RegisteredScalarDeletingDestructorSupplier(
                class_identity=class_identity,
                address=address,
                identity=identity,
                evidence_sources=tuple(evidence_sources),
            )
        )
    return tuple(suppliers), blockers


def _registered_vector_assignment_provider_supplier(
    document: ProgressDocument,
    *,
    target_id: str,
    target: Mapping[str, Any],
    row: Mapping[str, Any],
    by_address: Mapping[str, str],
    provider_ids: frozenset[str],
) -> RegisteredVectorAssignmentProviderSupplier | None:
    """Prove one registered provider row and its exact tracker identity."""
    registration = target.get("registration")
    manifest_value = (
        registration.get("manifest_path")
        if isinstance(registration, Mapping)
        else None
    )
    if (
        target.get("binary") != "recoil"
        or target.get("kind") != "vc5"
        or not isinstance(registration, Mapping)
        or registration.get("binary") != "recoil"
        or registration.get("name") != target.get("name")
        or not isinstance(manifest_value, str)
        or not manifest_value
    ):
        return None
    manifest_path = Path(manifest_value)
    if not manifest_path.is_absolute():
        manifest_path = REPO_ROOT / manifest_path
    manifest_root = (REPO_ROOT / "tools" / "vc5_verify_targets").resolve()
    try:
        manifest_path = manifest_path.resolve()
        manifest_path.relative_to(manifest_root)
    except (OSError, ValueError):
        return None
    if not manifest_path.is_file():
        return None

    raw_address = row.get("address")
    if not isinstance(raw_address, str):
        return None
    try:
        address = normalize_address(raw_address)
    except ProgressError:
        return None
    if (
        row.get("name") != HUD_PANEL_LAYOUT_COPY_ASSIGN_PROVIDER_NAME
        or row.get("symbol") not in {None, ""}
        or row.get("symbol_regex")
        != HUD_PANEL_LAYOUT_COPY_ASSIGN_PROVIDER_REGEX
        or row.get("pipeline_class") != "unresolved"
        or row.get("authored_order_role") != "unresolved"
        or row.get("authored_order_gate") is not False
        or row.get("authored_relative_order_gate") is not False
        or row.get("required_presence") is not True
        or row.get("full_order_gate") is not True
        or row.get("logical_identity_key") not in {None, ""}
        or row.get("icf_fold_status") not in {None, ""}
    ):
        return None

    physical_rows: list[tuple[str, Mapping[str, Any]]] = []
    for symbol_id, symbol in document.collection("symbols").items():
        if not isinstance(symbol, Mapping):
            continue
        raw_symbol_address = symbol.get("address", symbol.get("start"))
        if not isinstance(raw_symbol_address, str):
            continue
        try:
            if normalize_address(raw_symbol_address) == address:
                physical_rows.append((str(symbol_id), symbol))
        except ProgressError:
            continue
    if len(physical_rows) != 1:
        return None
    symbol_id, symbol = physical_rows[0]
    raw_end = symbol.get("end_exclusive")
    raw_size = symbol.get("size")
    logical_aliases = symbol.get("logical_aliases")
    icf_group = symbol.get("icf_address_group")
    identity = f"provider:{symbol_id}"
    if not isinstance(raw_end, str):
        return None
    try:
        extent_size = (
            address_value(normalize_address(raw_end))
            - address_value(address)
        )
    except ProgressError:
        return None
    if (
        symbol.get("binary") != "recoil"
        or symbol.get("kind") != "function"
        or symbol.get("pipeline_class") != "non-authored"
        or symbol.get("authored_order_role") != "non-authored"
        or symbol.get("extent_state") != "known"
        or isinstance(raw_size, bool)
        or not isinstance(raw_size, int)
        or raw_size <= 0
        or extent_size != raw_size
        or symbol.get("logical_identity_key") not in {None, ""}
        or symbol.get("icf_fold_status") not in {None, ""}
        or isinstance(logical_aliases, Mapping)
        and bool(logical_aliases)
        or isinstance(icf_group, Mapping)
        and bool(icf_group)
        or by_address.get(address) != identity
        or identity not in provider_ids
    ):
        return None
    return RegisteredVectorAssignmentProviderSupplier(
        candidate_name=HUD_PANEL_LAYOUT_VECTOR_ASSIGNMENT_SYMBOL,
        address=address,
        identity=identity,
        target_id=target_id,
    )


def _index_registered_vector_assignment_provider_name(
    document: ProgressDocument,
    *,
    by_address: Mapping[str, str],
    by_candidate_name: dict[str, str],
    provider_ids: frozenset[str],
) -> None:
    """Publish the one exact vector-assignment name from one provider row."""
    suppliers: list[RegisteredVectorAssignmentProviderSupplier] = []
    matching_row_count = 0
    ambiguous = False
    for target_id, target in document.collection(
        "verification_targets"
    ).items():
        if not isinstance(target, Mapping):
            continue
        registration = target.get("registration")
        if not isinstance(registration, Mapping):
            continue
        for row in _mapping_target_function_rows(target):
            if (
                row.get("name")
                != HUD_PANEL_LAYOUT_COPY_ASSIGN_PROVIDER_NAME
                and row.get("symbol_regex")
                != HUD_PANEL_LAYOUT_COPY_ASSIGN_PROVIDER_REGEX
            ):
                continue
            matching_row_count += 1
            supplier = _registered_vector_assignment_provider_supplier(
                document,
                target_id=str(target_id),
                target=target,
                row=row,
                by_address=by_address,
                provider_ids=provider_ids,
            )
            if supplier is None:
                ambiguous = True
                continue
            suppliers.append(supplier)

    identities = {
        (supplier.identity, supplier.address, supplier.target_id)
        for supplier in suppliers
    }
    prior = by_candidate_name.get(
        HUD_PANEL_LAYOUT_VECTOR_ASSIGNMENT_SYMBOL
    )
    if (
        ambiguous
        or matching_row_count != 1
        or len(identities) != 1
        or prior not in {None, suppliers[0].identity if suppliers else ""}
    ):
        by_candidate_name[HUD_PANEL_LAYOUT_VECTOR_ASSIGNMENT_SYMBOL] = ""
        return
    by_candidate_name[HUD_PANEL_LAYOUT_VECTOR_ASSIGNMENT_SYMBOL] = (
        suppliers[0].identity
    )


def _direct_bn_retail_bytes(
    bridge: BinaryNinjaBridge | None,
    *,
    address: str,
    length: int,
) -> bytes | None:
    """Read exact same-invocation retail bytes from the authenticated BN view."""

    if bridge is None or length <= 0:
        return None
    try:
        text = bridge.hexdump(address, length)
    except (BridgeError, OSError, RuntimeError, ValueError):
        return None
    result = bytearray()
    expected_address = address_value(normalize_address(address))
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        match = re.fullmatch(
            r"(?:0x)?(?P<address>[0-9a-fA-F]{8})\s*:?[ ]+"
            r"(?P<bytes>(?:[0-9a-fA-F]{2}(?:\s+|$))+)",
            line,
        )
        if match is None or int(match.group("address"), 16) != (
            expected_address + len(result)
        ):
            return None
        result.extend(int(token, 16) for token in match.group("bytes").split())
    return bytes(result) if len(result) == length else None


def _registered_pointer_vector_destroy_provider_suppliers(
    document: ProgressDocument,
    *,
    by_address: Mapping[str, str],
    provider_ids: frozenset[str],
    bridge: BinaryNinjaBridge | None,
    fact_transcript: list[dict[str, Any]] | None = None,
) -> tuple[RegisteredPointerVectorDestroyProviderSupplier, ...]:
    """Derive reviewed pointer-vector no-op destroy providers without candidates.

    Authority comes from one exact tracker function, its synchronized VC5
    catalog row, and direct bytes from this invocation's authenticated retail
    BN session. Candidate object names never participate in supplier discovery.
    """

    from _recoil.lib.verification_targets import vc5_target_registration

    target_rows = document.collection("verification_targets")
    manifest_root = (REPO_ROOT / "tools" / "vc5_verify_targets").resolve()
    suppliers: list[RegisteredPointerVectorDestroyProviderSupplier] = []
    for symbol_id, symbol in document.collection("symbols").items():
        if not isinstance(symbol, Mapping):
            continue
        navigation_name = symbol.get("navigation_name")
        if (
            not isinstance(navigation_name, str)
            or MSVC_POINTER_VECTOR_DESTROY_NAVIGATION_RE.fullmatch(
                navigation_name
            )
            is None
        ):
            continue
        raw_address = symbol.get("address", symbol.get("start"))
        raw_end = symbol.get("end_exclusive")
        raw_size = symbol.get("size")
        trace = symbol.get("source_traceability")
        verification_target_ids = symbol.get("verification_target_ids")
        if (
            not isinstance(raw_address, str)
            or not isinstance(raw_end, str)
            or isinstance(raw_size, bool)
            or not isinstance(raw_size, int)
            or raw_size <= 0
            or not isinstance(trace, Mapping)
            or trace.get("state") != "not-applicable"
            or trace.get("reason_code") != "provider-boundary"
            or not isinstance(verification_target_ids, list)
            or symbol.get("binary") != "recoil"
            or symbol.get("kind") != "function"
            or symbol.get("pipeline_class") != "non-authored"
            or symbol.get("authored_order_role")
            != "compiler-generated-icf-representative"
            or symbol.get("extent_state") != "known"
            or symbol.get("logical_identity_key") not in {None, ""}
            or symbol.get("icf_fold_status") not in {None, ""}
        ):
            continue
        try:
            address = normalize_address(raw_address)
            end_exclusive = normalize_address(raw_end)
        except ProgressError:
            continue
        if address_value(end_exclusive) - address_value(address) != raw_size:
            continue
        identity = f"provider:{symbol_id}"
        if (
            by_address.get(address) != identity
            or identity not in provider_ids
        ):
            continue

        for target_id in verification_target_ids:
            target = target_rows.get(str(target_id))
            if not isinstance(target, Mapping):
                continue
            symbol_ids = target.get("symbol_ids")
            unresolved_addresses = target.get("unresolved_addresses")
            if (
                target.get("binary") != "recoil"
                or target.get("kind") != "vc5"
                or not isinstance(symbol_ids, list)
                or symbol_ids.count(str(symbol_id)) != 1
                or unresolved_addresses not in (None, [])
            ):
                continue
            registration = target.get("registration")
            manifest_value = (
                registration.get("manifest_path")
                if isinstance(registration, Mapping)
                else None
            )
            if (
                not isinstance(registration, Mapping)
                or registration.get("binary") != "recoil"
                or registration.get("name") != target.get("name")
                or not isinstance(manifest_value, str)
                or not manifest_value
            ):
                continue
            manifest_path = Path(manifest_value)
            if not manifest_path.is_absolute():
                manifest_path = REPO_ROOT / manifest_path
            try:
                manifest_path = manifest_path.resolve()
                manifest_path.relative_to(manifest_root)
            except (OSError, ValueError):
                continue
            if not manifest_path.is_file():
                continue
            try:
                current_id, current = vc5_target_registration(manifest_path)
            except (OSError, ProgressError, ValueError):
                continue
            current_registration = current.get("registration")
            if (
                current_id != target_id
                or not (
                    current.get("binary")
                    == target.get("binary")
                    == "recoil"
                )
                or not (
                    current.get("kind")
                    == target.get("kind")
                    == "vc5"
                )
                or current.get("name") != target.get("name")
                or not isinstance(current_registration, Mapping)
                or current_registration.get("manifest_path") != manifest_value
            ):
                continue
            current_registered_addresses = current.get(
                "registered_addresses"
            )
            stored_function_addresses = registration.get(
                "function_addresses"
            )
            current_function_addresses = current_registration.get(
                "function_addresses"
            )
            if (
                not isinstance(current_registered_addresses, list)
                or current_registered_addresses.count(address) != 1
                or not isinstance(stored_function_addresses, list)
                or stored_function_addresses.count(address) != 1
                or not isinstance(current_function_addresses, list)
                or current_function_addresses.count(address) != 1
            ):
                continue
            try:
                stored_rows = [
                    row
                    for row in _mapping_target_function_rows(target)
                    if isinstance(row.get("address"), str)
                    and normalize_address(str(row["address"])) == address
                ]
                current_rows = [
                    row
                    for row in _mapping_target_function_rows(current)
                    if isinstance(row.get("address"), str)
                    and normalize_address(str(row["address"])) == address
                ]
            except ProgressError:
                continue
            if (
                len(stored_rows) != 1
                or len(current_rows) != 1
                or dict(stored_rows[0]) != dict(current_rows[0])
            ):
                continue

            try:
                manifest = load_manifest(
                    manifest_path,
                    enforce_source_policy=False,
                )
            except (OSError, ValueError):
                continue
            manifest_rows = [
                row
                for row in manifest.functions
                if normalize_address(row.address) == address
            ]
            if len(manifest_rows) != 1:
                continue
            manifest_row = manifest_rows[0]
            catalog_symbol = manifest_row.symbol
            if (
                not isinstance(catalog_symbol, str)
                or not _decorated_coff_name(catalog_symbol)
                or manifest_row.symbol_regex is not None
                or MSVC_POINTER_VECTOR_DESTROY_PROVIDER_RE.fullmatch(
                    catalog_symbol
                )
                is None
            ):
                continue

            retail_body = _direct_bn_retail_bytes(
                bridge,
                address=address,
                length=3,
            )
            cleanup_bytes = (
                struct.unpack_from("<H", retail_body, 1)[0]
                if retail_body is not None
                and len(retail_body) == 3
                and retail_body[0] == 0xC2
                else None
            )
            if cleanup_bytes != 8:
                continue
            if fact_transcript is not None:
                fact_transcript.append({
                    "fact": "provider-pointer-vector-destroy-cleanup",
                    "address": address,
                    "requested_length": 3,
                    "direct_bytes": list(retail_body),
                    "parsed_cleanup_bytes": cleanup_bytes,
                    "provider_identity": identity,
                    "provider_role": "compiler-generated-pointer-vector-destroy",
                })
            suppliers.append(
                RegisteredPointerVectorDestroyProviderSupplier(
                    address=address,
                    identity=identity,
                    target_id=str(target_id),
                    catalog_symbol=catalog_symbol,
                    stack_cleanup_bytes=cleanup_bytes,
                )
            )
    return tuple(suppliers)


def _hud_cmd_binding_ptr_vector_erase_provider_supplier(
    document: ProgressDocument,
    *,
    by_address: Mapping[str, str],
    provider_ids: frozenset[str],
    bridge: BinaryNinjaBridge | None,
    fact_transcript: list[dict[str, Any]] | None = None,
) -> StructuralPhysicalProviderSupplier | None:
    """Derive one exact provider from tracker plus same-invocation retail bytes."""

    physical_rows: list[tuple[str, Mapping[str, Any]]] = []
    named_rows: list[tuple[str, Mapping[str, Any]]] = []
    for symbol_id, symbol in document.collection("symbols").items():
        if not isinstance(symbol, Mapping):
            continue
        if (
            symbol.get("navigation_name")
            == HUD_CMD_BINDING_PTR_VECTOR_ERASE_NAVIGATION_NAME
        ):
            named_rows.append((str(symbol_id), symbol))
        raw_address = symbol.get("address", symbol.get("start"))
        if not isinstance(raw_address, str):
            continue
        try:
            address = normalize_address(raw_address)
        except ProgressError:
            continue
        if address == HUD_CMD_BINDING_PTR_VECTOR_ERASE_ADDRESS:
            physical_rows.append((str(symbol_id), symbol))
    expected_symbol_id = "recoil:function:0x4ba4d0"
    if (
        len(physical_rows) != 1
        or len(named_rows) != 1
        or physical_rows[0] != named_rows[0]
        or physical_rows[0][0] != expected_symbol_id
    ):
        return None
    symbol = physical_rows[0][1]
    logical_aliases = symbol.get("logical_aliases")
    icf_group = symbol.get("icf_address_group")
    if (
        symbol.get("binary") != "recoil"
        or symbol.get("kind") != "function"
        or symbol.get("address")
        != HUD_CMD_BINDING_PTR_VECTOR_ERASE_ADDRESS
        or symbol.get("end_exclusive")
        != HUD_CMD_BINDING_PTR_VECTOR_ERASE_END_EXCLUSIVE
        or symbol.get("extent_state") != "known"
        or symbol.get("size") != 0x40
        or symbol.get("pipeline_class") != "non-authored"
        or symbol.get("authored_order_role") != "non-authored"
        or symbol.get("navigation_name")
        != HUD_CMD_BINDING_PTR_VECTOR_ERASE_NAVIGATION_NAME
        or symbol.get("logical_identity_key") not in {None, ""}
        or symbol.get("icf_fold_status") not in {None, ""}
        or symbol.get("object_symbol") not in {None, ""}
        or logical_aliases not in (None, {})
        or icf_group not in (None, {})
        or by_address.get(HUD_CMD_BINDING_PTR_VECTOR_ERASE_ADDRESS)
        != HUD_CMD_BINDING_PTR_VECTOR_ERASE_IDENTITY
        or HUD_CMD_BINDING_PTR_VECTOR_ERASE_IDENTITY not in provider_ids
    ):
        return None
    if (
        address_value(HUD_CMD_BINDING_PTR_VECTOR_ERASE_END_EXCLUSIVE)
        - address_value(HUD_CMD_BINDING_PTR_VECTOR_ERASE_ADDRESS)
        != 0x40
    ):
        return None
    retail_body = _direct_bn_retail_bytes(
        bridge,
        address=HUD_CMD_BINDING_PTR_VECTOR_ERASE_ADDRESS,
        length=len(HUD_CMD_BINDING_PTR_VECTOR_ERASE_RETAIL_BODY),
    )
    if retail_body != HUD_CMD_BINDING_PTR_VECTOR_ERASE_RETAIL_BODY:
        return None
    if fact_transcript is not None:
        fact_transcript.append({
            "fact": "provider-pointer-vector-erase-body",
            "address": HUD_CMD_BINDING_PTR_VECTOR_ERASE_ADDRESS,
            "requested_length": len(HUD_CMD_BINDING_PTR_VECTOR_ERASE_RETAIL_BODY),
            "direct_bytes": list(retail_body),
            "parsed_cleanup_bytes": 8,
            "provider_identity": HUD_CMD_BINDING_PTR_VECTOR_ERASE_IDENTITY,
            "provider_role": "msvc-stl-vector-erase-range",
        })
    return StructuralPhysicalProviderSupplier(
        candidate_name=HUD_CMD_BINDING_PTR_VECTOR_ERASE_SYMBOL,
        address=HUD_CMD_BINDING_PTR_VECTOR_ERASE_ADDRESS,
        identity=HUD_CMD_BINDING_PTR_VECTOR_ERASE_IDENTITY,
        stack_cleanup_bytes=8,
    )


def _hud_ui_mgr_stats_list_static_storage_reference_bridges(
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    candidate_storage_bridges: Mapping[str, str],
    compiler_generated_bridges: Mapping[str, str],
) -> dict[str, ReviewedStaticStorageReferenceBridge]:
    """Resolve one exact aggregate-plus-field candidate storage reference.

    This is deliberately separate from registered decorated-data publication:
    it grants one candidate-side, call-contract-only static load after the
    synchronized aggregate manifest, tracker aggregate/leaf ownership, and
    current caller-object COD/COFF evidence all converge.  Lifecycle, byte,
    tier, and final-layout state are intentionally outside this predicate.
    """
    def exact_mov_source(instruction: Instruction) -> str:
        match = re.fullmatch(
            r"mov\s+[a-z]{2,3}\s*,\s*(?P<source>.+)",
            instruction.raw_text.strip(),
            flags=re.IGNORECASE,
        )
        return (
            _exact_memory_expression(match.group("source"))
            if match is not None
            else ""
        )

    normalized_start = normalize_address(caller_start)
    if normalized_start != HUD_SCOREBOARD_DISPATCH_SET_SCALE_CALLER_START:
        return {}

    caller = candidate.caller_definition
    caller_addresses = [
        address
        for address, identity in indexes.by_address.items()
        if identity == caller_identity
    ]
    if (
        caller_identity
        != HUD_SCOREBOARD_DISPATCH_SET_SCALE_CALLER_IDENTITY
        or normalized_start
        != HUD_SCOREBOARD_DISPATCH_SET_SCALE_CALLER_START
        or normalize_address(caller_end_exclusive)
        != HUD_SCOREBOARD_DISPATCH_SET_SCALE_CALLER_END_EXCLUSIVE
        or caller_addresses
        != [HUD_SCOREBOARD_DISPATCH_SET_SCALE_CALLER_START]
        or caller_identity in indexes.provider_ids
        or caller is None
        or caller.symbol
        != HUD_SCOREBOARD_DISPATCH_SET_SCALE_CALLER_SYMBOL
        or len(caller.data) != len(caller.relocation_mask)
    ):
        raise ValueError(
            "HUD stats-list static-storage bridge requires the exact reviewed "
            "authored 0x40eae0 caller identity, extent, symbol, and object body"
        )

    target = document.collection("verification_targets").get(
        HUD_UI_MGR_AGGREGATE_TARGET_ID
    )
    registration = (
        target.get("registration")
        if isinstance(target, Mapping)
        else None
    )
    aggregate_registrations: list[str] = []
    for target_id, candidate_target in document.collection(
        "verification_targets"
    ).items():
        if not isinstance(candidate_target, Mapping):
            continue
        candidate_registration = candidate_target.get("registration")
        if not isinstance(candidate_registration, Mapping):
            continue
        matching_addresses = []
        for raw_address in candidate_registration.get("data_addresses", []):
            if not isinstance(raw_address, str):
                continue
            try:
                if (
                    normalize_address(raw_address)
                    == HUD_UI_MGR_AGGREGATE_ADDRESS
                ):
                    matching_addresses.append(raw_address)
            except ProgressError:
                continue
        if matching_addresses:
            aggregate_registrations.append(str(target_id))
    if (
        not isinstance(target, Mapping)
        or target.get("binary") != "recoil"
        or target.get("kind") != "vc5"
        or target.get("name") != "hud_ui_mgr_data"
        or target.get("symbol_ids") != [HUD_UI_MGR_AGGREGATE_SYMBOL_ID]
        or target.get("unresolved_addresses") not in (None, [])
        or not isinstance(registration, Mapping)
        or registration.get("binary") != "recoil"
        or registration.get("name") != "hud_ui_mgr_data"
        or registration.get("manifest_path")
        != HUD_UI_MGR_AGGREGATE_TARGET_MANIFEST
        or registration.get("data_addresses")
        != [HUD_UI_MGR_AGGREGATE_ADDRESS]
        or aggregate_registrations
        != [HUD_UI_MGR_AGGREGATE_TARGET_ID]
    ):
        raise ValueError(
            "HUD stats-list static-storage bridge requires one exact "
            "registered aggregate target without registry collisions"
        )

    from _recoil.lib.verification_targets import vc5_target_registration

    manifest_path = (
        REPO_ROOT / HUD_UI_MGR_AGGREGATE_TARGET_MANIFEST
    ).resolve()
    manifest_root = (REPO_ROOT / "tools" / "vc5_verify_targets").resolve()
    try:
        manifest_path.relative_to(manifest_root)
        current_id, current_target = vc5_target_registration(manifest_path)
        manifest = load_manifest(
            manifest_path,
            enforce_source_policy=False,
        )
    except (OSError, ProgressError, ValueError) as exc:
        raise ValueError(
            "HUD stats-list static-storage bridge cannot read the synchronized "
            "aggregate target"
        ) from exc
    current_registration = current_target.get("registration")
    aggregate_rows = tuple(getattr(manifest, "data_symbols", ()))
    if (
        current_id != HUD_UI_MGR_AGGREGATE_TARGET_ID
        or current_target.get("binary") != "recoil"
        or current_target.get("kind") != "vc5"
        or current_target.get("name") != "hud_ui_mgr_data"
        or not isinstance(current_registration, Mapping)
        or current_registration.get("manifest_path")
        != HUD_UI_MGR_AGGREGATE_TARGET_MANIFEST
        or current_registration.get("data_addresses")
        != [HUD_UI_MGR_AGGREGATE_ADDRESS]
        or len(aggregate_rows) != 1
        or getattr(aggregate_rows[0], "address", None)
        != HUD_UI_MGR_AGGREGATE_ADDRESS
        or getattr(aggregate_rows[0], "symbol", None)
        != HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        or getattr(aggregate_rows[0], "symbol_regex", None) is not None
        or getattr(aggregate_rows[0], "name", None)
        != HUD_UI_MGR_AGGREGATE_NAME
        or getattr(aggregate_rows[0], "bn_name", None)
        != HUD_UI_MGR_AGGREGATE_NAME
        or getattr(aggregate_rows[0], "byte_length", None)
        != HUD_UI_MGR_AGGREGATE_SIZE
    ):
        raise ValueError(
            "HUD stats-list static-storage bridge requires the synchronized "
            "exact decorated aggregate symbol and positive 0x7844 extent"
        )

    symbols = document.collection("symbols")
    storage_rows = document.collection("storage_contributions")
    owners = document.collection("owners")

    def rows_at_address(
        rows: Mapping[str, Any],
        address: str,
        *,
        storage: bool,
    ) -> list[tuple[str, Mapping[str, Any]]]:
        matches: list[tuple[str, Mapping[str, Any]]] = []
        for entity_id, row in rows.items():
            if not isinstance(row, Mapping):
                continue
            reference = row.get("reference")
            raw_address = (
                reference.get("address")
                if storage and isinstance(reference, Mapping)
                else row.get("address", row.get("start"))
            )
            if not isinstance(raw_address, str):
                continue
            try:
                if normalize_address(raw_address) == address:
                    matches.append((str(entity_id), row))
            except ProgressError:
                continue
        return matches

    aggregate_symbol_rows = rows_at_address(
        symbols,
        HUD_UI_MGR_AGGREGATE_ADDRESS,
        storage=False,
    )
    leaf_symbol_rows = rows_at_address(
        symbols,
        HUD_UI_MGR_STATS_LIST_ADDRESS,
        storage=False,
    )
    aggregate_storage_rows = rows_at_address(
        storage_rows,
        HUD_UI_MGR_AGGREGATE_ADDRESS,
        storage=True,
    )
    leaf_storage_rows = rows_at_address(
        storage_rows,
        HUD_UI_MGR_STATS_LIST_ADDRESS,
        storage=True,
    )
    if (
        len(aggregate_symbol_rows) != 1
        or aggregate_symbol_rows[0][0]
        != HUD_UI_MGR_AGGREGATE_SYMBOL_ID
        or len(leaf_symbol_rows) != 1
        or leaf_symbol_rows[0][0] != HUD_UI_MGR_STATS_LIST_SYMBOL_ID
        or len(aggregate_storage_rows) != 1
        or aggregate_storage_rows[0][0]
        != HUD_UI_MGR_AGGREGATE_STORAGE_ID
        or len(leaf_storage_rows) != 1
        or leaf_storage_rows[0][0] != HUD_UI_MGR_STATS_LIST_STORAGE_ID
    ):
        raise ValueError(
            "HUD stats-list static-storage bridge requires unique aggregate "
            "and leaf symbol/storage rows without data/provider collisions"
        )

    aggregate_symbol = aggregate_symbol_rows[0][1]
    leaf_symbol = leaf_symbol_rows[0][1]
    aggregate_storage = aggregate_storage_rows[0][1]
    leaf_storage = leaf_storage_rows[0][1]
    if (
        aggregate_symbol.get("binary") != "recoil"
        or aggregate_symbol.get("kind") != "data"
        or aggregate_symbol.get("disposition") != "authored"
        or aggregate_symbol.get("navigation_name")
        != HUD_UI_MGR_AGGREGATE_NAME
        or aggregate_symbol.get("output_section_id")
        != "recoil:section:.data"
        or aggregate_symbol.get("storage_contribution_ids")
        != [HUD_UI_MGR_AGGREGATE_STORAGE_ID]
        or aggregate_symbol.get("verification_target_ids")
        != [HUD_UI_MGR_AGGREGATE_TARGET_ID]
        or aggregate_symbol.get("extent_state") != "unknown"
        or aggregate_symbol.get("size") is not None
        or aggregate_symbol.get("end_exclusive") is not None
        or aggregate_symbol.get("logical_aliases")
        or aggregate_symbol.get("relocation_target_binding")
        or leaf_symbol.get("binary") != "recoil"
        or leaf_symbol.get("kind") != "data"
        or leaf_symbol.get("disposition") != "authored"
        or leaf_symbol.get("navigation_name")
        != HUD_UI_MGR_STATS_LIST_NAME
        or leaf_symbol.get("ownership_state") != "primary-owned"
        or leaf_symbol.get("output_section_id") != "recoil:section:.data"
        or leaf_symbol.get("storage_contribution_ids")
        != [HUD_UI_MGR_STATS_LIST_STORAGE_ID]
        or not isinstance(
            leaf_symbol.get("verification_target_ids"),
            list,
        )
        or not leaf_symbol.get("verification_target_ids")
        or len(leaf_symbol["verification_target_ids"])
        != len(set(leaf_symbol["verification_target_ids"]))
        or leaf_symbol.get("extent_state") != "unknown"
        or leaf_symbol.get("size") is not None
        or leaf_symbol.get("end_exclusive") is not None
        or leaf_symbol.get("logical_aliases")
        or leaf_symbol.get("relocation_target_binding")
    ):
        raise ValueError(
            "HUD stats-list static-storage bridge requires exact authored "
            "aggregate and canonical primary-owned leaf classification"
        )

    for storage_id, storage, symbol_id, address in (
        (
            HUD_UI_MGR_AGGREGATE_STORAGE_ID,
            aggregate_storage,
            HUD_UI_MGR_AGGREGATE_SYMBOL_ID,
            HUD_UI_MGR_AGGREGATE_ADDRESS,
        ),
        (
            HUD_UI_MGR_STATS_LIST_STORAGE_ID,
            leaf_storage,
            HUD_UI_MGR_STATS_LIST_SYMBOL_ID,
            HUD_UI_MGR_STATS_LIST_ADDRESS,
        ),
    ):
        reference = storage.get("reference")
        if (
            storage.get("binary") != "recoil"
            or storage.get("kind") != "data-symbol"
            or storage.get("output_section_id")
            != "recoil:section:.data"
            or storage.get("overlap") != "none"
            or storage.get("owner_ids") != [HUD_UI_MGR_OWNER_ID]
            or storage.get("parent_contribution_id") is not None
            or storage.get("symbol_ids") != [symbol_id]
            or storage.get("logical_aliases")
            or not isinstance(reference, Mapping)
            or normalize_address(str(reference.get("address", "")))
            != address
            or reference.get("extent_state") != "unknown"
            or reference.get("size") is not None
            or reference.get("end_exclusive") is not None
        ):
            raise ValueError(
                "HUD stats-list static-storage bridge requires exact authored "
                f"storage linkage for {storage_id}"
            )

    owner = owners.get(HUD_UI_MGR_OWNER_ID)
    gates = owner.get("gates") if isinstance(owner, Mapping) else None
    primary_relationships = [
        (str(owner_id), relationship)
        for owner_id, candidate_owner in owners.items()
        if isinstance(candidate_owner, Mapping)
        for relationship in candidate_owner.get("relationships", [])
        if isinstance(relationship, Mapping)
        and relationship.get("kind") == "primary-data"
        and relationship.get("symbol_id")
        in {
            HUD_UI_MGR_AGGREGATE_SYMBOL_ID,
            HUD_UI_MGR_STATS_LIST_SYMBOL_ID,
        }
    ]
    expected_relationships = {
        (
            HUD_UI_MGR_OWNER_ID,
            HUD_UI_MGR_AGGREGATE_SYMBOL_ID,
            HUD_UI_MGR_AGGREGATE_ADDRESS,
            HUD_UI_MGR_AGGREGATE_NAME,
        ),
        (
            HUD_UI_MGR_OWNER_ID,
            HUD_UI_MGR_STATS_LIST_SYMBOL_ID,
            HUD_UI_MGR_STATS_LIST_ADDRESS,
            HUD_UI_MGR_STATS_LIST_NAME,
        ),
    }
    actual_relationships = {
        (
            owner_id,
            str(relationship.get("symbol_id", "")),
            normalize_address(str(relationship.get("address", ""))),
            str(relationship.get("name", "")),
        )
        for owner_id, relationship in primary_relationships
    }
    if (
        not isinstance(owner, Mapping)
        or owner.get("binary") != "recoil"
        or owner.get("kind") != "data-owner"
        or owner.get("provider_state") == "accepted"
        or not isinstance(gates, Mapping)
        or any(
            gates.get(gate) != "accepted"
            for gate in ("boundary", "source", "data", "owner_linkage")
        )
        or len(primary_relationships) != 2
        or actual_relationships != expected_relationships
    ):
        raise ValueError(
            "HUD stats-list static-storage bridge requires one identical "
            "non-provider owner with accepted boundary/source/data/linkage gates"
        )

    aggregate_start = address_value(HUD_UI_MGR_AGGREGATE_ADDRESS)
    leaf_start = address_value(HUD_UI_MGR_STATS_LIST_ADDRESS)
    if (
        aggregate_start + HUD_UI_MGR_STATS_LIST_DISPLACEMENT
        != leaf_start
        or HUD_UI_MGR_STATS_LIST_DISPLACEMENT < 0
        or HUD_UI_MGR_STATS_LIST_DISPLACEMENT
        + HUD_UI_MGR_STATS_LIST_ACCESS_WIDTH
        > HUD_UI_MGR_AGGREGATE_SIZE
    ):
        raise ValueError(
            "HUD stats-list static-storage bridge leaf is not the exact "
            "bounded 4-byte field at aggregate delta 0x7610"
        )

    decorated_folded = HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL.casefold()
    ordinary_callable_names = [
        name
        for name in indexes.by_candidate_name
        if name.casefold() == decorated_folded
    ]
    ordinary_storage_names = [
        (name, identity)
        for name, identity in indexes.storage_by_name.items()
        if name.casefold() == decorated_folded
    ]
    permitted_storage_names = {
        (),
        ((HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL, ""),),
        (
            (
                HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
                f"storage:{HUD_UI_MGR_AGGREGATE_SYMBOL_ID}",
            ),
        ),
    }
    candidate_bridge_names = [
        name
        for name in (
            set(candidate_storage_bridges)
            | set(compiler_generated_bridges)
        )
        if name.casefold() == decorated_folded
    ]
    retail_name_addresses: set[str] = set()
    for name, rows in bridge_names.items():
        if name.casefold() != decorated_folded:
            continue
        values = (
            list(rows)
            if isinstance(rows, (list, tuple, set, frozenset))
            else [rows]
        )
        for row in values:
            try:
                retail_name_addresses.add(
                    normalize_address(str(getattr(row, "address", "")))
                )
            except ProgressError:
                retail_name_addresses.add("")
    if (
        ordinary_callable_names
        or tuple(ordinary_storage_names) not in permitted_storage_names
        or candidate_bridge_names
        or (
            retail_name_addresses
            and retail_name_addresses != {HUD_UI_MGR_AGGREGATE_ADDRESS}
        )
        or HUD_UI_MGR_STATS_LIST_IDENTITY in indexes.provider_ids
    ):
        raise ValueError(
            "HUD stats-list static-storage bridge has a data/provider/IAT/"
            "alias/registry identity collision"
        )

    expected_decimal_expression = (
        f"{HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL}"
        f"+{HUD_UI_MGR_STATS_LIST_DISPLACEMENT}"
    )
    expected_hex_expression = (
        f"{HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL}"
        f"+0x{HUD_UI_MGR_STATS_LIST_DISPLACEMENT:x}"
    )
    instruction_offsets = _instruction_runtime_addresses(
        candidate.instructions,
        source="cod",
        caller_start=0,
    )
    references = [
        (index, instruction, offset)
        for index, (instruction, offset) in enumerate(
            zip(candidate.instructions, instruction_offsets)
        )
        if "g_huduimgr" in instruction.raw_text.casefold()
    ]
    exact_references = [
        row
        for row in references
        if exact_mov_source(row[1])
        in {expected_decimal_expression, expected_hex_expression}
    ]
    if len(references) != 1 or len(exact_references) != 1:
        raise ValueError(
            "HUD stats-list static-storage bridge requires one exact "
            "case-sensitive candidate aggregate field reference"
        )
    instruction_index, instruction, instruction_offset = exact_references[0]
    if (
        instruction_index != 0
        or instruction_offset
        not in {None, HUD_UI_MGR_STATS_LIST_REFERENCE_OFFSET}
        or _instruction_mnemonic(instruction) != "mov"
        or not re.match(
            r"^mov\s+ecx\s*,",
            instruction.raw_text.strip(),
            flags=re.IGNORECASE,
        )
        or tuple(item.lower() for item in instruction.bytes)
        != ("8b", "0d", "10", "76", "00", "00")
        or caller.data[:6] != b"\x8b\x0d\x10\x76\x00\x00"
    ):
        raise ValueError(
            "HUD stats-list static-storage bridge requires exact COD/COFF "
            "MOV ECX, moffs32 bytes at caller offset zero"
        )

    folded_relocations = [
        relocation
        for relocation in caller.relocations
        if relocation.symbol_name.casefold() == decorated_folded
    ]
    relocation_rows = [
        relocation
        for relocation in caller.relocations
        if relocation.offset == HUD_UI_MGR_STATS_LIST_RELOCATION_OFFSET
    ]
    undefined_folded = [
        name
        for name in caller.undefined_external_data
        if name.casefold() == decorated_folded
    ]
    defined_folded = [
        name
        for name in caller.defined_external_data
        if name.casefold() == decorated_folded
    ]
    relocation_end = HUD_UI_MGR_STATS_LIST_RELOCATION_OFFSET + 4
    if (
        len(folded_relocations) != 1
        or relocation_rows != folded_relocations
        or folded_relocations[0].symbol_name
        != HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        or folded_relocations[0].type != IMAGE_REL_I386_DIR32
        or undefined_folded
        != [HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL]
        or defined_folded
        or relocation_end > len(caller.data)
        or relocation_end > len(caller.relocation_mask)
        or struct.unpack_from(
            "<I",
            caller.data,
            HUD_UI_MGR_STATS_LIST_RELOCATION_OFFSET,
        )[0]
        != HUD_UI_MGR_STATS_LIST_DISPLACEMENT
        or not all(
            caller.relocation_mask[index]
            for index in range(
                HUD_UI_MGR_STATS_LIST_RELOCATION_OFFSET,
                relocation_end,
            )
        )
    ):
        raise ValueError(
            "HUD stats-list static-storage bridge requires one exact undefined "
            "DIR32 relocation with addend 0x7610 at caller+2"
        )

    expression = exact_mov_source(instruction)
    return {
        expression: ReviewedStaticStorageReferenceBridge(
            aggregate_symbol=HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
            displacement=HUD_UI_MGR_STATS_LIST_DISPLACEMENT,
            access_width=HUD_UI_MGR_STATS_LIST_ACCESS_WIDTH,
            storage_identity=HUD_UI_MGR_STATS_LIST_IDENTITY,
        )
    }


def _hud_shield_layout_affine_storage_bridges(
    retail_instructions: Sequence[Instruction],
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
) -> tuple[
    dict[str, str],
    dict[str, ReviewedStaticStorageReferenceBridge],
]:
    """Bridge one reviewed aggregate-interior pointer on both call-contract sides.

    Retail has no independently catalogued leaf at 0x4e6dac.  The identity is
    therefore an affine pointer field within the synchronized g_HudUiMgr
    aggregate, never a fabricated tracker symbol.  Every predicate is scoped
    to the exact 0x40eb00 caller and validates retail and candidate evidence
    independently before publishing either side of the bridge.
    """
    if normalize_address(caller_start) != HUD_SHIELD_LAYOUT_CALLER_START:
        return {}, {}

    caller = candidate.caller_definition
    caller_addresses = [
        address
        for address, identity in indexes.by_address.items()
        if identity == caller_identity
    ]
    if (
        caller_identity != HUD_SHIELD_LAYOUT_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != HUD_SHIELD_LAYOUT_CALLER_END_EXCLUSIVE
        or caller_addresses != [HUD_SHIELD_LAYOUT_CALLER_START]
        or caller_identity in indexes.provider_ids
        or caller is None
        or caller.symbol != HUD_SHIELD_LAYOUT_CALLER_SYMBOL
        or not caller.data
        or len(caller.data) != len(caller.relocation_mask)
    ):
        raise ValueError(
            "HUD shield-layout affine-storage bridge requires the exact "
            "authored 0x40eb00 caller identity, extent, symbol, and object body"
        )

    target = document.collection("verification_targets").get(
        HUD_UI_MGR_AGGREGATE_TARGET_ID
    )
    registration = (
        target.get("registration")
        if isinstance(target, Mapping)
        else None
    )
    registrations: list[str] = []
    for target_id, row in document.collection(
        "verification_targets"
    ).items():
        candidate_registration = (
            row.get("registration") if isinstance(row, Mapping) else None
        )
        if not isinstance(candidate_registration, Mapping):
            continue
        try:
            registered_addresses = {
                normalize_address(str(raw_address))
                for raw_address in candidate_registration.get(
                    "data_addresses", []
                )
                if isinstance(raw_address, str)
            }
        except ProgressError:
            continue
        if HUD_UI_MGR_AGGREGATE_ADDRESS in registered_addresses:
            registrations.append(str(target_id))
    if (
        not isinstance(target, Mapping)
        or target.get("binary") != "recoil"
        or target.get("kind") != "vc5"
        or target.get("name") != "hud_ui_mgr_data"
        or target.get("symbol_ids") != [HUD_UI_MGR_AGGREGATE_SYMBOL_ID]
        or target.get("unresolved_addresses") not in (None, [])
        or not isinstance(registration, Mapping)
        or registration.get("binary") != "recoil"
        or registration.get("name") != "hud_ui_mgr_data"
        or registration.get("manifest_path")
        != HUD_UI_MGR_AGGREGATE_TARGET_MANIFEST
        or registration.get("data_addresses")
        != [HUD_UI_MGR_AGGREGATE_ADDRESS]
        or registrations != [HUD_UI_MGR_AGGREGATE_TARGET_ID]
    ):
        raise ValueError(
            "HUD shield-layout affine-storage bridge requires one exact "
            "registered aggregate target without registry collisions"
        )

    from _recoil.lib.verification_targets import vc5_target_registration

    manifest_path = (
        REPO_ROOT / HUD_UI_MGR_AGGREGATE_TARGET_MANIFEST
    ).resolve()
    manifest_root = (REPO_ROOT / "tools" / "vc5_verify_targets").resolve()
    try:
        manifest_path.relative_to(manifest_root)
        current_id, current_target = vc5_target_registration(manifest_path)
        manifest = load_manifest(manifest_path, enforce_source_policy=False)
    except (OSError, ProgressError, ValueError) as exc:
        raise ValueError(
            "HUD shield-layout affine-storage bridge cannot read the "
            "synchronized aggregate target"
        ) from exc
    current_registration = current_target.get("registration")
    manifest_rows = tuple(getattr(manifest, "data_symbols", ()))
    if (
        current_id != HUD_UI_MGR_AGGREGATE_TARGET_ID
        or current_target.get("binary") != "recoil"
        or current_target.get("kind") != "vc5"
        or current_target.get("name") != "hud_ui_mgr_data"
        or not isinstance(current_registration, Mapping)
        or current_registration.get("manifest_path")
        != HUD_UI_MGR_AGGREGATE_TARGET_MANIFEST
        or current_registration.get("data_addresses")
        != [HUD_UI_MGR_AGGREGATE_ADDRESS]
        or len(manifest_rows) != 1
        or getattr(manifest_rows[0], "address", None)
        != HUD_UI_MGR_AGGREGATE_ADDRESS
        or getattr(manifest_rows[0], "symbol", None)
        != HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        or getattr(manifest_rows[0], "symbol_regex", None) is not None
        or getattr(manifest_rows[0], "name", None)
        != HUD_UI_MGR_AGGREGATE_NAME
        or getattr(manifest_rows[0], "bn_name", None)
        != HUD_UI_MGR_AGGREGATE_NAME
        or getattr(manifest_rows[0], "byte_length", None)
        != HUD_UI_MGR_AGGREGATE_SIZE
    ):
        raise ValueError(
            "HUD shield-layout affine-storage bridge requires the synchronized "
            "exact decorated aggregate symbol and 0x7844 extent"
        )

    symbols = document.collection("symbols")
    storages = document.collection("storage_contributions")
    owners = document.collection("owners")
    symbol_rows = [
        (str(symbol_id), row)
        for symbol_id, row in symbols.items()
        if isinstance(row, Mapping)
        and isinstance(row.get("address", row.get("start")), str)
        and normalize_address(
            str(row.get("address", row.get("start")))
        )
        == HUD_UI_MGR_AGGREGATE_ADDRESS
    ]
    storage_rows = [
        (str(storage_id), row)
        for storage_id, row in storages.items()
        if isinstance(row, Mapping)
        and isinstance(row.get("reference"), Mapping)
        and isinstance(row["reference"].get("address"), str)
        and normalize_address(str(row["reference"]["address"]))
        == HUD_UI_MGR_AGGREGATE_ADDRESS
    ]
    if (
        len(symbol_rows) != 1
        or symbol_rows[0][0] != HUD_UI_MGR_AGGREGATE_SYMBOL_ID
        or len(storage_rows) != 1
        or storage_rows[0][0] != HUD_UI_MGR_AGGREGATE_STORAGE_ID
    ):
        raise ValueError(
            "HUD shield-layout affine-storage bridge requires unique aggregate "
            "symbol/storage authority"
        )
    aggregate_symbol = symbol_rows[0][1]
    aggregate_storage = storage_rows[0][1]
    reference = aggregate_storage.get("reference")
    if (
        aggregate_symbol.get("binary") != "recoil"
        or aggregate_symbol.get("kind") != "data"
        or aggregate_symbol.get("disposition") != "authored"
        or aggregate_symbol.get("navigation_name")
        != HUD_UI_MGR_AGGREGATE_NAME
        or aggregate_symbol.get("output_section_id")
        != "recoil:section:.data"
        or aggregate_symbol.get("storage_contribution_ids")
        != [HUD_UI_MGR_AGGREGATE_STORAGE_ID]
        or aggregate_symbol.get("verification_target_ids")
        != [HUD_UI_MGR_AGGREGATE_TARGET_ID]
        or aggregate_symbol.get("extent_state") != "unknown"
        or aggregate_symbol.get("size") is not None
        or aggregate_symbol.get("end_exclusive") is not None
        or aggregate_symbol.get("logical_aliases")
        or aggregate_symbol.get("relocation_target_binding")
        or aggregate_storage.get("binary") != "recoil"
        or aggregate_storage.get("kind") != "data-symbol"
        or aggregate_storage.get("output_section_id")
        != "recoil:section:.data"
        or aggregate_storage.get("overlap") != "none"
        or aggregate_storage.get("owner_ids") != [HUD_UI_MGR_OWNER_ID]
        or aggregate_storage.get("parent_contribution_id") is not None
        or aggregate_storage.get("symbol_ids")
        != [HUD_UI_MGR_AGGREGATE_SYMBOL_ID]
        or aggregate_storage.get("logical_aliases")
        or not isinstance(reference, Mapping)
        or reference.get("extent_state") != "unknown"
        or reference.get("size") is not None
        or reference.get("end_exclusive") is not None
    ):
        raise ValueError(
            "HUD shield-layout affine-storage bridge requires exact authored "
            "aggregate classification and storage linkage"
        )

    owner = owners.get(HUD_UI_MGR_OWNER_ID)
    gates = owner.get("gates") if isinstance(owner, Mapping) else None
    relationships = [
        (str(owner_id), relationship)
        for owner_id, row in owners.items()
        if isinstance(row, Mapping)
        for relationship in row.get("relationships", [])
        if isinstance(relationship, Mapping)
        and relationship.get("kind") == "primary-data"
        and relationship.get("symbol_id")
        == HUD_UI_MGR_AGGREGATE_SYMBOL_ID
    ]
    if (
        not isinstance(owner, Mapping)
        or owner.get("binary") != "recoil"
        or owner.get("kind") != "data-owner"
        or owner.get("provider_state") == "accepted"
        or not isinstance(gates, Mapping)
        or any(
            gates.get(gate) != "accepted"
            for gate in ("boundary", "source", "data", "owner_linkage")
        )
        or len(relationships) != 1
        or relationships[0][0] != HUD_UI_MGR_OWNER_ID
        or relationships[0][1].get("address")
        != HUD_UI_MGR_AGGREGATE_ADDRESS
        or relationships[0][1].get("name")
        != HUD_UI_MGR_AGGREGATE_NAME
    ):
        raise ValueError(
            "HUD shield-layout affine-storage bridge requires one accepted "
            "non-provider aggregate owner relationship"
        )

    aggregate_start = address_value(HUD_UI_MGR_AGGREGATE_ADDRESS)
    pointer_start = address_value(HUD_SHIELD_LAYOUT_POINTER_ADDRESS)
    if (
        aggregate_start + HUD_SHIELD_LAYOUT_POINTER_DISPLACEMENT
        != pointer_start
        or HUD_SHIELD_LAYOUT_POINTER_DISPLACEMENT
        + HUD_SHIELD_LAYOUT_POINTER_ACCESS_WIDTH
        > HUD_UI_MGR_AGGREGATE_SIZE
        or HUD_SHIELD_LAYOUT_POINTER_ADDRESS in indexes.storage_by_address
        or HUD_SHIELD_LAYOUT_POINTER_IDENTITY in indexes.provider_ids
    ):
        raise ValueError(
            "HUD shield-layout pointer is not one uncatalogued bounded "
            "aggregate-interior 4-byte field"
        )

    decorated_folded = HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL.casefold()
    callable_collisions = [
        name
        for name in indexes.by_candidate_name
        if name.casefold() == decorated_folded
    ]
    storage_collisions = [
        (name, identity)
        for name, identity in indexes.storage_by_name.items()
        if name.casefold() == decorated_folded
        and identity
        not in {"", f"storage:{HUD_UI_MGR_AGGREGATE_SYMBOL_ID}"}
    ]
    retail_name_addresses = {
        normalize_address(str(getattr(row, "address", "")))
        for name, rows in bridge_names.items()
        if name.casefold() == decorated_folded
        for row in (
            list(rows)
            if isinstance(rows, (list, tuple, set, frozenset))
            else [rows]
        )
    }
    if (
        callable_collisions
        or storage_collisions
        or (
            retail_name_addresses
            and retail_name_addresses != {HUD_UI_MGR_AGGREGATE_ADDRESS}
        )
    ):
        raise ValueError(
            "HUD shield-layout affine-storage bridge has a callable/storage/"
            "provider/registry identity collision"
        )

    retail_offsets = _instruction_runtime_addresses(
        retail_instructions,
        source="bn",
        caller_start=address_value(HUD_SHIELD_LAYOUT_CALLER_START),
    )
    retail_by_address = {
        normalize_address(hex(offset)): instruction
        for instruction, offset in zip(retail_instructions, retail_offsets)
        if offset is not None
    }
    absolute_references = {
        address: instruction
        for address, instruction in retail_by_address.items()
        if HUD_SHIELD_LAYOUT_POINTER_ADDRESS[2:]
        in instruction.raw_text.casefold()
    }
    if set(absolute_references) != set(HUD_SHIELD_LAYOUT_RETAIL_LOADS):
        raise ValueError(
            "HUD shield-layout affine-storage bridge requires the exact "
            "fourteen immutable retail pointer-load sites"
        )
    for address, expected_bytes in HUD_SHIELD_LAYOUT_RETAIL_LOADS.items():
        instruction = absolute_references[address]
        if (
            _instruction_mnemonic(instruction) != "mov"
            or tuple(item.lower() for item in instruction.bytes)
            != expected_bytes
        ):
            raise ValueError(
                "HUD shield-layout affine-storage bridge has a mismatched "
                f"retail pointer load at {address}"
            )
    primary_chain = {
        "0x40eb41": ("8b", "0d", "ac", "6d", "4e", "00"),
        "0x40eb4b": ("83", "c1", "1c"),
        "0x40eb4e": ("8b", "11"),
        "0x40eb50": ("ff", "52", "68"),
    }
    if any(
        address not in retail_by_address
        or tuple(
            item.lower() for item in retail_by_address[address].bytes
        )
        != expected_bytes
        for address, expected_bytes in primary_chain.items()
    ):
        raise ValueError(
            "HUD shield-layout affine-storage bridge requires the exact retail "
            "load/add/vptr/slot-0x68 provenance chain"
        )

    expected_expression = (
        f"{HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL}"
        f"+{HUD_SHIELD_LAYOUT_POINTER_DISPLACEMENT}"
    )
    candidate_offsets = _instruction_runtime_addresses(
        candidate.instructions,
        source="cod",
        caller_start=0,
    )
    candidate_references = [
        (index, instruction, offset)
        for index, (instruction, offset) in enumerate(
            zip(candidate.instructions, candidate_offsets)
        )
        if "g_huduimgr" in instruction.raw_text.casefold()
    ]
    expected_loads = {
        (
            "edx",
            f"{HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL}+804",
        ): (b"\x8b\x15", 2, 0x324),
        (
            "edi",
            expected_expression,
        ): (b"\x8b\x3d", 2, HUD_SHIELD_LAYOUT_POINTER_DISPLACEMENT),
        (
            "eax",
            f"{HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL}+800",
        ): (b"\xa1", 1, 0x320),
    }
    derived_relocation_sites: dict[int, int] = {}
    matched_loads: dict[
        tuple[str, str],
        tuple[Instruction, int],
    ] = {}
    address_load_count = 0
    for index, instruction, offset in candidate_references:
        if offset is None:
            raise ValueError(
                "HUD shield-layout affine-storage bridge cannot derive a "
                "candidate aggregate relocation from an unresolved COD offset"
            )
        try:
            encoded = bytes(int(item, 16) for item in instruction.bytes)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                "HUD shield-layout affine-storage bridge requires exact "
                "candidate aggregate instruction bytes"
            ) from exc
        load_match = re.fullmatch(
            r"mov\s+(?P<register>edx|edi|eax)\s*,\s*(?P<source>.+)",
            instruction.raw_text.strip(),
            flags=re.IGNORECASE,
        )
        if load_match is not None:
            key = (
                load_match.group("register").lower(),
                _exact_memory_expression(load_match.group("source")),
            )
            specification = expected_loads.get(key)
            if (
                specification is None
                or key in matched_loads
                or not encoded.startswith(specification[0])
                or len(encoded) != specification[1] + 4
            ):
                raise ValueError(
                    "HUD shield-layout affine-storage bridge has a duplicate "
                    "or mismatched candidate aggregate load"
                )
            immediate_offset = specification[1]
            relocation_offset = offset + immediate_offset
            matched_loads[key] = (instruction, offset)
            derived_relocation_sites[relocation_offset] = specification[2]
            continue
        address_match = re.fullmatch(
            r"mov\s+ecx\s*,\s*OFFSET\s+FLAT:"
            r"(?P<symbol>\?g_HudUiMgr@@3THudUiMgrDataStorage@@A)",
            instruction.raw_text.strip(),
            flags=re.IGNORECASE,
        )
        if (
            address_match is None
            or address_match.group("symbol")
            != HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
            or encoded != b"\xb9\x00\x00\x00\x00"
            or index + 1 >= len(candidate.instructions)
            or not re.fullmatch(
                r"call\s+"
                + re.escape(HUD_SHIELD_LAYOUT_ADD_CHILD_SYMBOL),
                candidate.instructions[index + 1].raw_text.strip(),
                flags=re.IGNORECASE,
            )
            or tuple(
                item.lower()
                for item in candidate.instructions[index + 1].bytes[:1]
            )
            != ("e8",)
        ):
            raise ValueError(
                "HUD shield-layout affine-storage bridge has an unmatched "
                "candidate aggregate address load"
            )
        address_load_count += 1
        derived_relocation_sites[offset + 1] = 0
    pointer_instruction = matched_loads.get(
        ("edi", expected_expression)
    )
    if (
        len(candidate_references) != 6
        or set(matched_loads) != set(expected_loads)
        or address_load_count != 3
        or len(derived_relocation_sites) != 6
        or pointer_instruction is None
    ):
        raise ValueError(
            "HUD shield-layout affine-storage bridge requires exactly three "
            "precise aggregate loads and three AddChild address loads"
        )
    expected_relocations = [
        relocation
        for relocation in caller.relocations
        if relocation.symbol_name.casefold() == decorated_folded
    ]
    undefined_aggregate_symbols = [
        name
        for name in caller.undefined_external_data
        if name.casefold() == decorated_folded
    ]
    defined_aggregate_symbols = [
        name
        for name in caller.defined_external_data
        if name.casefold() == decorated_folded
    ]
    actual_relocations = {
        relocation.offset: relocation
        for relocation in expected_relocations
    }
    if (
        len(expected_relocations) != 6
        or len(actual_relocations) != len(expected_relocations)
        or set(actual_relocations)
        != set(derived_relocation_sites)
        or undefined_aggregate_symbols
        != [HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL]
        or defined_aggregate_symbols
    ):
        raise ValueError(
            "HUD shield-layout affine-storage bridge requires the exact "
            "candidate pointer expression, body, and aggregate relocation set"
        )
    for offset, addend in derived_relocation_sites.items():
        relocation = actual_relocations[offset]
        owning_references = [
            (instruction, instruction_offset)
            for _index, instruction, instruction_offset
            in candidate_references
            if (
                instruction_offset is not None
                and instruction_offset <= offset
                < instruction_offset + len(instruction.bytes)
            )
        ]
        if len(owning_references) != 1:
            raise ValueError(
                "HUD shield-layout affine-storage bridge cannot uniquely "
                f"associate candidate relocation caller+0x{offset:x}"
            )
        instruction, instruction_offset = owning_references[0]
        instruction_end = instruction_offset + len(instruction.bytes)
        if (
            relocation.symbol_name != HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
            or relocation.type != IMAGE_REL_I386_DIR32
            or offset + 4 > len(caller.data)
            or struct.unpack_from("<I", caller.data, offset)[0] != addend
            or not all(
                caller.relocation_mask[index]
                for index in range(offset, offset + 4)
            )
            or caller.data[instruction_offset:instruction_end]
            != bytes(int(item, 16) for item in instruction.bytes)
            or any(
                caller.relocation_mask[index]
                for index in range(instruction_offset, offset)
            )
        ):
            raise ValueError(
                "HUD shield-layout affine-storage bridge has a mismatched "
                f"candidate DIR32 aggregate relocation at caller+0x{offset:x}"
            )

    return (
        {
            HUD_SHIELD_LAYOUT_POINTER_ADDRESS: (
                HUD_SHIELD_LAYOUT_POINTER_IDENTITY
            )
        },
        {
            expected_expression: ReviewedStaticStorageReferenceBridge(
                aggregate_symbol=HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
                displacement=HUD_SHIELD_LAYOUT_POINTER_DISPLACEMENT,
                access_width=HUD_SHIELD_LAYOUT_POINTER_ACCESS_WIDTH,
                storage_identity=HUD_SHIELD_LAYOUT_POINTER_IDENTITY,
            )
        },
    )


def _registered_data_supplier(
    document: ProgressDocument,
    *,
    target_id: str,
    target: Mapping[str, Any],
    current_target: Mapping[str, Any],
    row: Any,
) -> RegisteredDecoratedDataNameSupplier | None:
    name = str(getattr(row, "symbol", "") or "")
    if (
        not name.startswith("?")
        or not _decorated_coff_name(name)
        or getattr(row, "symbol_regex", None) is not None
    ):
        return None
    try:
        address = normalize_address(str(getattr(row, "address", "")))
    except ProgressError:
        return None
    registration = target.get("registration")
    current_registration = current_target.get("registration")
    if not isinstance(registration, Mapping) or not isinstance(
        current_registration,
        Mapping,
    ):
        return None
    for data_addresses in (
        registration.get("data_addresses"),
        current_registration.get("data_addresses"),
    ):
        if (
            not isinstance(data_addresses, list)
            or sum(
                1
                for item in data_addresses
                if isinstance(item, str)
                and normalize_address(item) == address
            )
            != 1
        ):
            return None
    symbols = document.collection("symbols")
    address_symbols: list[tuple[str, Mapping[str, Any]]] = []
    for symbol_id, symbol in symbols.items():
        if (
            not isinstance(symbol, Mapping)
            or symbol.get("binary") != "recoil"
            or symbol.get("kind") not in {"data", "provider-data"}
        ):
            continue
        raw_address = symbol.get("address", symbol.get("start"))
        if not isinstance(raw_address, str):
            continue
        try:
            if normalize_address(raw_address) == address:
                address_symbols.append((str(symbol_id), symbol))
        except ProgressError:
            continue
    if len(address_symbols) != 1:
        return None
    symbol_id, symbol = address_symbols[0]
    if (
        symbol.get("kind") != "data"
        or symbol.get("disposition") != "authored"
        or symbol.get("navigation_name") != getattr(row, "name", "")
        or getattr(row, "bn_name", "") != getattr(row, "name", "")
    ):
        return None
    target_symbol_ids = target.get("symbol_ids")
    verification_target_ids = symbol.get("verification_target_ids")
    if (
        not isinstance(target_symbol_ids, list)
        or target_symbol_ids.count(symbol_id) != 1
        or len(target_symbol_ids) != len(set(target_symbol_ids))
        or len(target_symbol_ids)
        != len(registration.get("data_addresses", []))
        or not isinstance(verification_target_ids, list)
        or verification_target_ids.count(target_id) != 1
        or len(verification_target_ids) != len(set(verification_target_ids))
    ):
        return None
    target_symbol_addresses: list[str] = []
    for attached_symbol_id in target_symbol_ids:
        attached_symbol = symbols.get(attached_symbol_id)
        if (
            not isinstance(attached_symbol_id, str)
            or not isinstance(attached_symbol, Mapping)
            or attached_symbol.get("binary") != "recoil"
            or attached_symbol.get("kind") != "data"
        ):
            return None
        raw_attached_address = attached_symbol.get(
            "address",
            attached_symbol.get("start"),
        )
        if not isinstance(raw_attached_address, str):
            return None
        target_symbol_addresses.append(
            normalize_address(raw_attached_address)
        )
    if target_symbol_addresses != [
        normalize_address(item)
        for item in registration.get("data_addresses", [])
        if isinstance(item, str)
    ]:
        return None
    raw_storage_ids = symbol.get("storage_contribution_ids")
    if (
        not isinstance(raw_storage_ids, list)
        or len(raw_storage_ids) != 1
        or not isinstance(raw_storage_ids[0], str)
    ):
        return None
    storage_id = raw_storage_ids[0]
    storage_rows_at_address: list[tuple[str, Mapping[str, Any]]] = []
    for entity_id, storage in document.collection(
        "storage_contributions"
    ).items():
        if not isinstance(storage, Mapping):
            continue
        reference = storage.get("reference")
        raw_address = (
            reference.get("address")
            if isinstance(reference, Mapping)
            else storage.get("address", storage.get("start"))
        )
        if not isinstance(raw_address, str):
            continue
        try:
            if normalize_address(raw_address) == address:
                storage_rows_at_address.append((str(entity_id), storage))
        except ProgressError:
            continue
    if (
        len(storage_rows_at_address) != 1
        or storage_rows_at_address[0][0] != storage_id
    ):
        return None
    storage = storage_rows_at_address[0][1]
    reference = storage.get("reference")
    raw_owner_ids = storage.get("owner_ids")
    if (
        storage.get("binary") != "recoil"
        or storage.get("overlap") != "none"
        or storage.get("symbol_ids") != [symbol_id]
        or not isinstance(reference, Mapping)
        or normalize_address(str(reference.get("address", ""))) != address
        or not isinstance(raw_owner_ids, list)
        or len(raw_owner_ids) != 1
        or not isinstance(raw_owner_ids[0], str)
    ):
        return None
    owner_id = raw_owner_ids[0]
    owner = document.collection("owners").get(owner_id)
    if not isinstance(owner, Mapping):
        return None
    gates = owner.get("gates")
    if (
        owner.get("binary") != "recoil"
        or owner.get("kind") == "provider-boundary"
        or owner.get("provider_state") == "accepted"
        or owner.get("lifecycle_state") != "accepted"
        or not isinstance(gates, Mapping)
        or any(
            gates.get(gate) != "accepted"
            for gate in ("boundary", "source", "data", "owner_linkage")
        )
    ):
        return None
    owner_relationships = [
        (
            str(candidate_owner_id),
            relationship,
        )
        for candidate_owner_id, candidate_owner in document.collection(
            "owners"
        ).items()
        if isinstance(candidate_owner, Mapping)
        for relationship in candidate_owner.get("relationships", [])
        if isinstance(relationship, Mapping)
        and relationship.get("kind") == "primary-data"
        and relationship.get("symbol_id") == symbol_id
    ]
    if len(owner_relationships) != 1:
        return None
    relationship_owner_id, relationship = owner_relationships[0]
    if (
        relationship_owner_id != owner_id
        or normalize_address(str(relationship.get("address", ""))) != address
        or relationship.get("name") != getattr(row, "name", "")
    ):
        return None
    byte_length = getattr(row, "byte_length", None)
    if (
        isinstance(byte_length, bool)
        or not isinstance(byte_length, int)
        or byte_length <= 0
    ):
        return None
    extent_state = symbol.get("extent_state")
    if extent_state == "known":
        raw_size = symbol.get("size")
        raw_end = symbol.get("end_exclusive")
        if (
            isinstance(raw_size, bool)
            or not isinstance(raw_size, int)
            or raw_size != byte_length
            or not isinstance(raw_end, str)
            or address_value(normalize_address(raw_end))
            - address_value(address)
            != byte_length
        ):
            return None
    elif extent_state == "unknown":
        if symbol.get("size") is not None or symbol.get("end_exclusive") is not None:
            return None
    elif candidate_variant == "corrected-retained-source":
        return None
    return RegisteredDecoratedDataNameSupplier(
        name=name,
        address=address,
        storage_identity=f"storage:{symbol_id}",
        target_id=target_id,
    )


def _index_registered_decorated_data_names(
    document: ProgressDocument,
    *,
    storage_by_name: dict[str, str],
) -> None:
    """Publish exact decorated data names only after all suppliers converge."""
    from _recoil.lib.verification_targets import vc5_target_registration

    suppliers_by_name: dict[
        str, list[RegisteredDecoratedDataNameSupplier]
    ] = {}
    names_by_address: dict[str, set[str]] = {}
    ambiguous_names: set[str] = set()
    manifest_root = (REPO_ROOT / "tools" / "vc5_verify_targets").resolve()
    for target_id, target in document.collection(
        "verification_targets"
    ).items():
        if (
            not isinstance(target, Mapping)
            or target.get("binary") != "recoil"
            or target.get("kind") != "vc5"
        ):
            continue
        registration = target.get("registration")
        if (
            not isinstance(registration, Mapping)
            or not registration.get("data_addresses")
            or not target.get("symbol_ids")
        ):
            continue
        manifest_value = registration.get("manifest_path")
        if not isinstance(manifest_value, str) or not manifest_value:
            continue
        manifest_path = Path(manifest_value)
        if not manifest_path.is_absolute():
            manifest_path = REPO_ROOT / manifest_path
        try:
            manifest_path = manifest_path.resolve()
            manifest_path.relative_to(manifest_root)
            if not manifest_path.is_file():
                continue
            current_id, current_target = vc5_target_registration(
                manifest_path
            )
            manifest = load_manifest(
                manifest_path,
                enforce_source_policy=False,
            )
        except (OSError, ProgressError, ValueError):
            continue
        decorated_rows = [
            row
            for row in getattr(manifest, "data_symbols", ())
            if isinstance(getattr(row, "symbol", None), str)
            and row.symbol.startswith("?")
            and getattr(row, "symbol_regex", None) is None
        ]
        if not decorated_rows:
            continue
        for row in decorated_rows:
            try:
                address = normalize_address(str(row.address))
            except ProgressError:
                ambiguous_names.add(str(row.symbol))
                continue
            names_by_address.setdefault(address, set()).add(str(row.symbol))
        current_registration = current_target.get("registration")
        stable_target = (
            current_id == target_id
            and current_target.get("binary") == target.get("binary") == "recoil"
            and current_target.get("kind") == target.get("kind") == "vc5"
            and current_target.get("name") == target.get("name")
            and isinstance(current_registration, Mapping)
            and current_registration.get("manifest_path") == manifest_value
        )
        for row in decorated_rows:
            name = str(row.symbol)
            if not stable_target:
                ambiguous_names.add(name)
                continue
            same_address_rows = [
                candidate
                for candidate in decorated_rows
                if normalize_address(str(candidate.address))
                == normalize_address(str(row.address))
            ]
            if len(same_address_rows) != 1:
                ambiguous_names.add(name)
                continue
            supplier = _registered_data_supplier(
                document,
                target_id=str(target_id),
                target=target,
                current_target=current_target,
                row=row,
            )
            if supplier is None:
                ambiguous_names.add(name)
                continue
            suppliers_by_name.setdefault(name, []).append(supplier)
    for names in names_by_address.values():
        if len(names) > 1:
            ambiguous_names.update(names)
    all_names = set(suppliers_by_name) | ambiguous_names
    for name in all_names:
        suppliers = suppliers_by_name.get(name, [])
        identities = {
            (supplier.storage_identity, supplier.address)
            for supplier in suppliers
        }
        if (
            name in ambiguous_names
            or len(identities) != 1
            or name in storage_by_name
        ):
            storage_by_name[name] = ""
            continue
        storage_by_name[name] = next(iter(identities))[0]


def _current_tracker_iat_storage_packages(
    document: ProgressDocument,
) -> tuple[CurrentIatStoragePackage, ...]:
    """Return complete current candidate-independent named/ordinal IAT packages."""
    symbols = document.collection("symbols")
    storage_contributions = document.collection("storage_contributions")
    owners = document.collection("owners")
    evidence = document.collection("evidence")
    packages: list[CurrentIatStoragePackage] = []
    for function_id, function in symbols.items():
        if (
            not isinstance(function, Mapping)
            or function.get("kind") != "provider-function"
            or "import_name" not in function
            or "import_dll" not in function
        ):
            continue
        import_name = function.get("import_name")
        import_dll = function.get("import_dll")
        object_symbol = function.get("object_symbol")
        raw_address = function.get("address")
        has_ordinal = "import_ordinal" in function
        raw_ordinal = function.get("import_ordinal")
        import_ordinal = (
            raw_ordinal
            if (
                has_ordinal
                and isinstance(raw_ordinal, int)
                and not isinstance(raw_ordinal, bool)
                and 0 <= raw_ordinal <= 0xFFFF
            )
            else None
        )
        if (
            not isinstance(import_name, str)
            or not import_name
            or not isinstance(import_dll, str)
            or not import_dll
            or not isinstance(object_symbol, str)
            or not object_symbol.startswith("__imp_")
            or not _decorated_coff_name(object_symbol)
            or not isinstance(raw_address, str)
            or (has_ordinal and import_ordinal is None)
            or (
                import_ordinal is not None
                and import_name != f"#{import_ordinal}"
            )
        ):
            continue
        try:
            address = normalize_address(raw_address)
        except ProgressError:
            continue
        data_id = f"recoil:data:{address}"
        storage_id = f"recoil:storage:va:{address}"
        if function_id != f"recoil:function:{address}":
            continue
        data = symbols.get(data_id)
        storage = storage_contributions.get(storage_id)
        if not isinstance(storage, Mapping):
            continue
        owner_ids = storage.get("owner_ids")
        if (
            not isinstance(owner_ids, list)
            or len(owner_ids) != 1
            or not isinstance(owner_ids[0], str)
        ):
            continue
        owner_id = owner_ids[0]
        owner = owners.get(owner_id)
        end_exclusive = normalize_address(address_value(address) + 4)
        function_end = normalize_address(address_value(address) + 1)
        expected_relationships = [
            {"kind": "anchor-address", "address": address},
            {
                "kind": "primary-function",
                "address": address,
                "symbol_id": function_id,
            },
            {
                "kind": "primary-data",
                "address": address,
                "symbol_id": data_id,
                "name": f"{import_dll}!{import_name} IAT",
            },
        ]
        if (
            not isinstance(owner, Mapping)
            or owner.get("binary") != "recoil"
            or owner.get("kind") != "provider-boundary"
            or owner.get("blocker") != "none"
            or owner.get("lifecycle_state") != "accepted"
            or owner.get("provider_state") != "accepted"
            or owner.get("relationships") != expected_relationships
            or owner.get("source_paths") != []
            or function.get("binary") != "recoil"
            or function.get("disposition") != "provider"
            or function.get("pipeline_class") != "non-authored"
            or function.get("authored_order_role") != "non-authored"
            or function.get("address") != address
            or function.get("end_exclusive") != function_end
            or function.get("extent_state") != "known"
            or function.get("size") != 1
            or function.get("output_section_id") != "recoil:section:.rdata"
            or function.get("ownership_state") != "primary-owned"
            or function.get("physical_block_id") is not None
            or function.get("storage_contribution_ids") != []
        ):
            continue
        if (
            not isinstance(data, Mapping)
            or data.get("binary") != "recoil"
            or data.get("kind") != "data"
            or data.get("disposition") != "provider"
            or data.get("address") != address
            or data.get("end_exclusive") != end_exclusive
            or data.get("extent_state") != "known"
            or data.get("size") != 4
            or data.get("import_dll") != import_dll
            or data.get("import_name") != import_name
            or ("import_ordinal" in data) != has_ordinal
            or data.get("import_ordinal") != import_ordinal
            or data.get("output_section_id") != "recoil:section:.rdata"
            or data.get("ownership_state") != "primary-owned"
            or data.get("physical_block_id") is not None
            or data.get("storage_contribution_ids") != [storage_id]
        ):
            continue
        reference = storage.get("reference")
        verification = storage.get("verification")
        extent = (
            verification.get("extent")
            if isinstance(verification, Mapping)
            else None
        )
        if (
            storage.get("binary") != "recoil"
            or storage.get("kind") != "provider-data"
            or storage.get("output_section_id") != "recoil:section:.rdata"
            or storage.get("overlap") != "none"
            or storage.get("owner_ids") != [owner_id]
            or storage.get("parent_contribution_id") is not None
            or storage.get("symbol_ids") != [data_id]
            or not isinstance(reference, Mapping)
            or reference.get("address") != address
            or reference.get("end_exclusive") != end_exclusive
            or reference.get("extent_state") != "known"
            or reference.get("size") != 4
            or not isinstance(extent, Mapping)
            or not is_current_accepted_state(extent)
            or extent.get("validation_mode") != "live"
            or extent.get("gating") is not True
        ):
            continue
        shared_evidence = set(owner.get("evidence_ids", ()))
        for row in (function, data, storage, reference, extent):
            shared_evidence &= set(row.get("evidence_ids", ()))
        expected_scope_ids = {owner_id, function_id, data_id, storage_id}
        expected_iat_rva = normalize_address(
            address_value(address) - 0x400000
        )
        expected_iat_end_rva = normalize_address(
            address_value(end_exclusive) - 0x400000
        )
        current_evidence: list[Mapping[str, Any]] = []
        for evidence_id in shared_evidence:
            row = evidence.get(evidence_id)
            scope_ids = (
                row.get("scope_ids") if isinstance(row, Mapping) else None
            )
            if (
                not isinstance(row, Mapping)
                or row.get("kind")
                not in {
                    "provider-target-registration",
                    "provider-target-legacy-completion",
                }
                or not is_current_accepted_state(row)
                or row.get("validation_mode") != "live"
                or row.get("gating") is not True
                or not isinstance(scope_ids, list)
                or len(scope_ids) != len(expected_scope_ids)
                or set(scope_ids) != expected_scope_ids
            ):
                continue
            provenance = row.get("provenance")
            if not isinstance(provenance, Mapping):
                continue
            operation = provenance.get("operation")
            if (
                row.get("kind") == "provider-target-legacy-completion"
                and operation != "legacy-provider-completion"
            ) or (
                row.get("kind") == "provider-target-registration"
                and operation == "legacy-provider-completion"
            ):
                continue
            descriptor_index = provenance.get("descriptor_index")
            thunk_index = provenance.get("thunk_index")
            if (
                provenance.get("producer") != "pe32-import-directory"
                or provenance.get("reference") != "support/Recoil.exe"
                or provenance.get("candidate_independent") is not True
                or provenance.get("address") != address
                or provenance.get("dll") != import_dll
                or provenance.get("import_name") != import_name
                or provenance.get("import_ordinal") != import_ordinal
                or provenance.get("iat_rva") != expected_iat_rva
                or provenance.get("iat_end_rva") != expected_iat_end_rva
                or not isinstance(descriptor_index, int)
                or isinstance(descriptor_index, bool)
                or descriptor_index < 0
                or not isinstance(thunk_index, int)
                or isinstance(thunk_index, bool)
                or thunk_index < 0
                or provenance.get("object_symbol") != object_symbol
                or provenance.get("object_symbol_basis")
                != "reviewed-vc5-provider-declaration"
            ):
                continue
            current_evidence.append(row)
        if len(current_evidence) != 1:
            continue
        packages.append(
            CurrentIatStoragePackage(
                address=address,
                import_dll=import_dll,
                import_name=import_name,
                import_ordinal=import_ordinal,
                object_symbol=object_symbol,
                identity=(
                    f"iat:{import_name}"
                    if import_ordinal is None
                    else (
                        "iat:ordinal:"
                        f"{len(import_dll)}:{import_dll}:{import_ordinal}"
                    )
                ),
            )
        )
    return tuple(packages)


def _publish_collected_identity(
    index: dict[str, str],
    key: str,
    identities: set[str],
) -> None:
    """Publish one convergent identity, preserving any prior ambiguity."""
    if not key:
        return
    identity = next(iter(identities)) if len(identities) == 1 else ""
    prior = index.get(key)
    index[key] = identity if prior in {None, identity} else ""


def _winner_unknown_icf_group_indexes(
    document: ProgressDocument,
) -> tuple[dict[str, str], dict[str, str]]:
    """Build exact reviewed ICF-group authority before inspecting a candidate."""
    targets = document.collection("verification_targets")
    owners = document.collection("owners")
    evidence_rows = document.collection("evidence")
    groups_by_address: dict[str, str] = {}
    groups_by_logical_identity: dict[str, str] = {}

    for symbol_id, symbol in document.collection("symbols").items():
        if not isinstance(symbol, Mapping):
            continue
        group = symbol.get("icf_address_group")
        if not isinstance(group, Mapping) or group.get("winner_status") != "winner-unknown":
            continue
        if (
            symbol.get("binary") != "recoil"
            or symbol.get("kind") not in {"function", "compiler-function"}
            or symbol.get("pipeline_class") != "non-authored"
            or symbol.get("authored_order_role")
            != "compiler-generated-icf-representative"
            or symbol.get("linked_provider_binding") is not None
            or group.get("winner_identity_key") not in {None, ""}
        ):
            # Other inventoried winner-unknown groups remain on the existing
            # exact-alias/fail-closed path. They do not gain group authority.
            continue
        group_evidence = group.get("evidence_ids")
        opted_in = isinstance(group_evidence, list) and any(
            isinstance(evidence_id, str)
            and isinstance(evidence_rows.get(evidence_id), Mapping)
            and evidence_rows[evidence_id].get("kind")
            == "authored-order-icf-logical-alias-review"
            for evidence_id in group_evidence
        )
        if not opted_in:
            # Historical logical-alias inventories describe exact aliases only.
            # Group arbitration is a separate, explicit current review contract.
            continue
        if (
            not isinstance(group_evidence, list)
            or not group_evidence
            or any(not isinstance(item, str) or not item for item in group_evidence)
            or len(set(group_evidence)) != len(group_evidence)
        ):
            raise ValueError(
                f"winner-unknown ICF group {symbol_id} has missing or duplicate evidence"
            )
        raw_address = symbol.get("address", symbol.get("start"))
        if not isinstance(raw_address, str):
            raise ValueError(f"winner-unknown ICF group {symbol_id} has no address")
        address = normalize_address(raw_address)
        expected_alias_prefix = f"recoil:logical-function:{address}:"
        aliases = symbol.get("logical_aliases")
        if not isinstance(aliases, Mapping) or len(aliases) < 2:
            continue
        if any(
            not isinstance(alias_id, str)
            or not isinstance(alias, Mapping)
            or (
                alias.get("pipeline_class"),
                alias.get("authored_order_role"),
            )
            not in {
                ("authored", "authored-body"),
                ("authored-lifecycle", "authored-lifecycle-body"),
            }
            or alias.get("fold_status") != "proven-fold-alias"
            or alias.get("source_owner_status") != "authored-owner"
            or alias.get("original_name_status")
            not in {"recovered", "provisional"}
            for alias_id, alias in aliases.items()
        ):
            continue
        expected_evidence_scope = {
            symbol_id,
            *aliases.keys(),
            *(alias.get("owner_id") for alias in aliases.values()),
        }

        object_symbols: set[str] = set()
        recovered_original_names: set[str] = set()
        alias_ids: set[str] = set()
        for alias_id, alias in aliases.items():
            if (
                not isinstance(alias_id, str)
                or not alias_id.startswith(expected_alias_prefix)
            ):
                raise ValueError(
                    f"winner-unknown ICF group {symbol_id} has incomplete or "
                    "wrong-address logical alias membership"
                )
            object_symbol = alias.get("object_symbol")
            original_name = alias.get("original_name")
            original_name_status = alias.get("original_name_status")
            owner_id = alias.get("owner_id")
            alias_evidence = alias.get("evidence_ids")
            if (
                not isinstance(object_symbol, str)
                or not _decorated_coff_name(object_symbol)
                or not isinstance(original_name, str)
                or not original_name
                or (
                    original_name_status == "recovered"
                    and original_name.startswith("CompilerICF::")
                )
                or not isinstance(owner_id, str)
                or not owner_id
                or not isinstance(alias_evidence, list)
                or alias_evidence != group_evidence
                or len(set(alias_evidence)) != len(alias_evidence)
            ):
                raise ValueError(
                    f"winner-unknown ICF group {symbol_id} has incomplete alias "
                    f"identity/evidence for {alias_id}"
                )
            if object_symbol in object_symbols or (
                original_name_status == "recovered"
                and original_name in recovered_original_names
            ):
                raise ValueError(
                    f"winner-unknown ICF group {symbol_id} has duplicate alias names"
                )
            owner = owners.get(owner_id)
            gates = owner.get("gates") if isinstance(owner, Mapping) else None
            if (
                not isinstance(owner, Mapping)
                or owner.get("binary") != "recoil"
                or owner.get("kind") == "provider-boundary"
                or owner.get("provider_state")
                in {"accepted", "provider-boundary", "provider-owned"}
                or not isinstance(gates, Mapping)
                or gates.get("source") != "accepted"
                or gates.get("owner_linkage") != "accepted"
            ):
                raise ValueError(
                    f"winner-unknown ICF group {symbol_id} has missing, provider, "
                    f"or unaccepted owner {owner_id!r}"
                )
            for evidence_id in alias_evidence:
                evidence = evidence_rows.get(evidence_id)
                scopes = (
                    evidence.get("scope_ids")
                    if isinstance(evidence, Mapping)
                    else None
                )
                if (
                    not isinstance(scopes, list)
                    or len(set(scopes)) != len(scopes)
                    or symbol_id not in scopes
                    or alias_id not in scopes
                    or owner_id not in scopes
                ):
                    raise ValueError(
                        f"winner-unknown ICF group {symbol_id} has missing or "
                        f"conflicting evidence membership for {alias_id}"
                    )
                if isinstance(evidence, Mapping) and evidence.get("kind") == (
                    "authored-order-icf-logical-alias-review"
                ):
                    provenance = evidence.get("provenance")
                    validation_context = (
                        provenance.get("validation_context")
                        if isinstance(provenance, Mapping)
                        else None
                    )
                    if (
                        len(group_evidence) != 1
                        or not is_current_accepted_state(evidence)
                        or evidence.get("gating") is not True
                        or not isinstance(scopes, list)
                        or len(scopes) != len(expected_evidence_scope)
                        or set(scopes) != expected_evidence_scope
                        or not isinstance(provenance, Mapping)
                        or provenance.get("candidate_independent") is not True
                        or not isinstance(validation_context, Mapping)
                        or validation_context.get("candidate_output_used") is not False
                        or (
                            provenance.get("evidence_contract") is not None
                            and (
                                provenance.get("evidence_contract")
                                != "existing-winner-unknown-physical-group-refresh-v1"
                                or validation_context.get("authority_scope")
                                != "physical-icf-group-only"
                                or validation_context.get(
                                    "original_name_used_as_authority"
                                )
                                is not False
                                or validation_context.get("winner_identity_claimed")
                                is not False
                            )
                        )
                    ):
                        raise ValueError(
                            f"winner-unknown ICF group {symbol_id} has stale, "
                            "candidate-dependent, or inexact current alias-review evidence"
                        )
            alias_ids.add(alias_id)
            object_symbols.add(object_symbol)
            if original_name_status == "recovered":
                recovered_original_names.add(original_name)

        matching_targets: list[tuple[str, Mapping[str, Any], dict[str, Mapping[str, Any]]]] = []
        for target_id, target in targets.items():
            if (
                not isinstance(target, Mapping)
                or target.get("binary") != "recoil"
                or target.get("kind") != "vc5"
            ):
                continue
            rows = {
                str(row.get("logical_identity_key")): row
                for row in _mapping_target_function_rows(target)
                if row.get("logical_identity_key") in alias_ids
            }
            if rows:
                matching_targets.append((str(target_id), target, rows))
        if len(matching_targets) != 1:
            raise ValueError(
                f"winner-unknown ICF group {symbol_id} has missing, duplicate, or "
                "conflicting governed target membership"
            )
        target_id, target, stored_rows = matching_targets[0]
        for evidence_id in group_evidence:
            evidence = evidence_rows.get(evidence_id)
            provenance = (
                evidence.get("provenance")
                if isinstance(evidence, Mapping)
                else None
            )
            if (
                isinstance(provenance, Mapping)
                and provenance.get("evidence_contract")
                == "existing-winner-unknown-physical-group-refresh-v1"
                and provenance.get("governed_target_id") != target_id
            ):
                raise ValueError(
                    f"winner-unknown ICF group {symbol_id} has conflicting governed "
                    "target evidence"
                )
        if set(stored_rows) != alias_ids:
            raise ValueError(
                f"winner-unknown ICF group {symbol_id} has incomplete governed "
                "target alias membership"
            )
        stored_all_at_address = [
            row
            for row in _mapping_target_function_rows(target)
            if isinstance(row.get("address"), str)
            and normalize_address(row["address"]) == address
            and isinstance(row.get("logical_identity_key"), str)
            and row.get("logical_identity_key")
        ]
        if (
            len(stored_all_at_address) != len(alias_ids)
            or {str(row["logical_identity_key"]) for row in stored_all_at_address}
            != alias_ids
        ):
            raise ValueError(
                f"winner-unknown ICF group {symbol_id} has extra or duplicate "
                "registered aliases"
            )
        for alias_id, row in stored_rows.items():
            alias = aliases[alias_id]
            alternatives = _finite_literal_symbol_regex_alternatives(
                row.get("symbol_regex")
            )
            registered_names = (
                {str(row.get("symbol"))}
                if isinstance(row.get("symbol"), str) and row.get("symbol")
                else set(alternatives or ())
            )
            if (
                normalize_address(row.get("address")) != address
                or (
                    row.get("pipeline_class"),
                    row.get("authored_order_role"),
                )
                != (
                    alias.get("pipeline_class"),
                    alias.get("authored_order_role"),
                )
                or row.get("authored_order_gate") is not True
                or row.get("required_presence") is not True
                or row.get("icf_fold_status") != "proven-fold-alias"
                or alias.get("object_symbol") not in registered_names
            ):
                raise ValueError(
                    f"winner-unknown ICF group {symbol_id} has stale or conflicting "
                    f"registered alias {alias_id}"
                )

        registration = target.get("registration")
        manifest_value = (
            registration.get("manifest_path")
            if isinstance(registration, Mapping)
            else None
        )
        if not isinstance(manifest_value, str) or not manifest_value:
            raise ValueError(
                f"winner-unknown ICF authority target {target_id!r} has no manifest"
            )
        manifest_path = Path(manifest_value)
        if not manifest_path.is_absolute():
            manifest_path = REPO_ROOT / manifest_path
        try:
            manifest_path = manifest_path.resolve()
            manifest_path.relative_to(
                (REPO_ROOT / "tools" / "vc5_verify_targets").resolve()
            )
        except ValueError as exc:
            raise ValueError(
                f"winner-unknown ICF authority target {target_id!r} is outside "
                "tools/vc5_verify_targets"
            ) from exc
        from _recoil.lib.verification_targets import vc5_target_registration

        try:
            current_id, current = vc5_target_registration(manifest_path)
        except (OSError, ValueError) as exc:
            raise ValueError(
                f"winner-unknown ICF authority target {target_id!r} cannot be "
                f"synchronized: {exc}"
            ) from exc
        current_registration = current.get("registration")
        if (
            current_id != target_id
            or current.get("binary") != target.get("binary")
            or current.get("kind") != target.get("kind")
            or current.get("name") != target.get("name")
            or not isinstance(current_registration, Mapping)
            or current_registration.get("manifest_path") != manifest_value
        ):
            raise ValueError(
                f"winner-unknown ICF authority target {target_id!r} is stale or "
                "conflicting"
            )
        current_rows = [
            row
            for row in _mapping_target_function_rows(current)
            if row.get("logical_identity_key") in alias_ids
        ]
        current_all_at_address = [
            row
            for row in _mapping_target_function_rows(current)
            if isinstance(row.get("address"), str)
            and normalize_address(row["address"]) == address
            and isinstance(row.get("logical_identity_key"), str)
            and row.get("logical_identity_key")
        ]
        if (
            len(current_rows) != len(alias_ids)
            or {str(row["logical_identity_key"]) for row in current_rows} != alias_ids
            or len(current_all_at_address) != len(alias_ids)
            or {
                str(row["logical_identity_key"])
                for row in current_all_at_address
            }
            != alias_ids
            or any(
                dict(row) != dict(stored_rows[str(row["logical_identity_key"])])
                for row in current_rows
            )
        ):
            raise ValueError(
                f"winner-unknown ICF authority target {target_id!r} has stale, "
                "missing, duplicate, or conflicting current alias rows"
            )

        group_identity = f"icf-group:{symbol_id}"
        prior_group = groups_by_address.get(address)
        if prior_group not in {None, group_identity}:
            raise ValueError(
                f"winner-unknown ICF address {address} has conflicting groups"
            )
        groups_by_address[address] = group_identity
        for alias_id in alias_ids:
            logical_identity = f"logical:{alias_id}"
            prior = groups_by_logical_identity.get(logical_identity)
            if prior not in {None, group_identity}:
                raise ValueError(
                    f"winner-unknown ICF logical alias {alias_id} belongs to "
                    "conflicting groups"
                )
            groups_by_logical_identity[logical_identity] = group_identity

    return groups_by_address, groups_by_logical_identity


def _registered_non_gating_logical_target_indexes(
    document: ProgressDocument,
) -> tuple[dict[str, str], dict[str, str]]:
    """Index synchronized single logical targets without selecting a physical row.

    A physical function whose authored classification is still unresolved does
    not become ordinary ``by_address`` truth.  This narrower authority applies
    only when one non-gating registered logical body was accepted exactly once
    in authored order and its current manifest, tracker alias, owner, block,
    and physical neutral-group facts all converge.
    """
    symbols = document.collection("symbols")
    blocks = document.collection("physical_blocks")
    targets = document.collection("verification_targets")
    by_address: dict[str, str] = {}
    by_candidate_name: dict[str, str] = {}

    candidate_name_memberships: dict[
        str, list[tuple[str, str, str]]
    ] = {}
    for physical_id, candidate_symbol in symbols.items():
        if not isinstance(candidate_symbol, Mapping):
            continue
        aliases = candidate_symbol.get("logical_aliases")
        if not isinstance(aliases, Mapping):
            continue
        for alias_id, alias in aliases.items():
            object_symbol = (
                alias.get("object_symbol")
                if isinstance(alias, Mapping)
                else None
            )
            if isinstance(object_symbol, str) and object_symbol:
                candidate_name_memberships.setdefault(
                    object_symbol.casefold(), []
                ).append(
                    (
                        str(physical_id),
                        str(alias_id),
                        object_symbol,
                    )
                )

    accepted_occurrences: dict[str, int] = {}
    for block in blocks.values():
        facts = (
            block.get("accepted_order_facts")
            if isinstance(block, Mapping)
            else None
        )
        if (
            not isinstance(facts, Mapping)
            or facts.get("phase") != "authored-function-order"
        ):
            continue
        for identity in facts.get("matched_identities", []):
            if isinstance(identity, str):
                accepted_occurrences[identity] = (
                    accepted_occurrences.get(identity, 0) + 1
                )

    for physical_id, symbol in symbols.items():
        if not isinstance(symbol, Mapping):
            continue
        aliases = symbol.get("logical_aliases")
        if (
            not isinstance(aliases, Mapping)
            or not any(
                isinstance(alias, Mapping)
                and alias.get("fold_status") == "not-established"
                for alias in aliases.values()
            )
        ):
            continue
        raw_address = symbol.get("address", symbol.get("start"))
        if not isinstance(raw_address, str):
            raise ValueError(
                f"registered non-gating logical target {physical_id} has no "
                "physical address"
            )
        address = normalize_address(raw_address)
        if (
            symbol.get("binary") != "recoil"
            or symbol.get("kind") != "function"
            or symbol.get("disposition") != "unresolved"
            or symbol.get("pipeline_class") != "unresolved"
            or symbol.get("authored_order_role") != "unresolved"
            or symbol.get("ownership_state") != "unresolved"
            or symbol.get("extent_state") != "known"
            or symbol.get("output_section_id") != "recoil:section:.text"
            or symbol.get("accepted_order_facts") is not None
            or symbol.get("accepted_byte_facts") is not None
            or symbol.get("icf_address_group") is not None
            or symbol.get("linked_provider_binding") is not None
            or symbol.get("lifecycle_variant_of") is not None
            or len(aliases) != 1
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} lacks "
                "the exact unresolved physical classification"
            )
        start = address_value(address)
        try:
            size = int(symbol.get("size"))
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"registered non-gating logical target {physical_id} has no "
                "known positive extent"
            ) from exc
        if (
            size <= 0
            or normalize_address(str(symbol.get("end_exclusive", "")))
            != normalize_address(start + size)
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} has a "
                "conflicting physical extent"
            )
        linked_group = symbol.get("linked_address_group")
        if (
            not isinstance(linked_group, Mapping)
            or linked_group.get("group_kind")
            != "neutral-linked-address-group"
            or linked_group.get("fold_state") != "not-established"
            or linked_group.get("winner_status") != "not-established"
            or linked_group.get("winner_identity_key") is not None
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} lacks "
                "neutral unresolved source/linkage state"
            )

        alias_id, alias = next(iter(aliases.items()))
        if not isinstance(alias, Mapping):
            raise ValueError(
                f"registered non-gating logical target {physical_id} has a "
                "malformed logical alias"
            )
        alias_id = str(alias_id)
        logical_identity = f"logical:{alias_id}"
        expected_alias_prefix = f"recoil:logical-function:{address}:"
        object_symbol = alias.get("object_symbol")
        original_name = alias.get("original_name")
        owner_id = alias.get("owner_id")
        if (
            not alias_id.startswith(expected_alias_prefix)
            or alias.get("pipeline_class") != "authored"
            or alias.get("authored_order_role") != "authored-body"
            or alias.get("fold_status") != "not-established"
            or alias.get("source_owner_status") != "authored-owner"
            or not isinstance(object_symbol, str)
            or not _decorated_coff_name(object_symbol)
            or not isinstance(original_name, str)
            or not original_name
            or not isinstance(owner_id, str)
            or not owner_id
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} has "
                "incomplete authored alias authority"
            )
        name_memberships = candidate_name_memberships.get(
            object_symbol.casefold(), []
        )
        if name_memberships != [
            (str(physical_id), alias_id, object_symbol)
        ]:
            raise ValueError(
                f"registered non-gating logical target {physical_id} has an "
                "ambiguous or case-conflicting candidate object name"
            )

        block_id = symbol.get("physical_block_id")
        block = blocks.get(str(block_id))
        facts = (
            block.get("accepted_order_facts")
            if isinstance(block, Mapping)
            else None
        )
        expected_target_id = (
            facts.get("target_id")
            if isinstance(facts, Mapping)
            else None
        )
        vc5_target_ids = [
            str(candidate_target_id)
            for candidate_target_id in symbol.get(
                "verification_target_ids", []
            )
            if isinstance(
                targets.get(str(candidate_target_id)), Mapping
            )
            and targets[str(candidate_target_id)].get("kind") == "vc5"
        ]
        if (
            not isinstance(block_id, str)
            or not isinstance(block, Mapping)
            or not isinstance(expected_target_id, str)
            or not expected_target_id
            or vc5_target_ids != [expected_target_id]
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} lacks "
                "one exact physical-block/VC5-target relationship"
            )
        stored_matches: list[
            tuple[str, Mapping[str, Any], str, Mapping[str, Any]]
        ] = []
        stored_same_address: list[
            tuple[str, str, Mapping[str, Any]]
        ] = []
        for target_id, target in targets.items():
            if (
                str(target_id) != expected_target_id
                or not isinstance(target, Mapping)
            ):
                continue
            for view, row in _mapping_target_function_rows_with_views(target):
                raw_row_address = row.get("address")
                if not isinstance(raw_row_address, str):
                    continue
                try:
                    row_address = normalize_address(raw_row_address)
                except ProgressError:
                    continue
                if row_address != address:
                    continue
                if isinstance(row.get("logical_identity_key"), str) and row.get(
                    "logical_identity_key"
                ):
                    stored_same_address.append((str(target_id), view, row))
                if row.get("logical_identity_key") == alias_id:
                    stored_matches.append(
                        (str(target_id), target, view, row)
                    )
        if (
            not stored_matches
            or not stored_same_address
            or len({item[0] for item in stored_matches}) != 1
            or any(
                dict(item[3]) != dict(stored_matches[0][3])
                for item in stored_matches
            )
            or any(
                item[0] != stored_matches[0][0]
                or dict(item[2]) != dict(stored_matches[0][3])
                for item in stored_same_address
            )
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} has a "
                "missing, duplicate, or conflicting registered row"
            )
        target_id, target, _view, row = stored_matches[0]
        registration = target.get("registration")
        if (
            target.get("binary") != "recoil"
            or target.get("kind") != "vc5"
            or not isinstance(registration, Mapping)
            or registration.get("binary") != "recoil"
            or registration.get("name") != target.get("name")
            or normalize_address(str(row.get("address", ""))) != address
            or row.get("symbol") != object_symbol
            or row.get("symbol_regex") is not None
            or row.get("name") != original_name
            or row.get("pipeline_class") != "authored"
            or row.get("authored_order_role") != "authored-body"
            or row.get("authored_order_gate") is not True
            or row.get("authored_relative_order_gate") is not True
            or row.get("required_presence") is not True
            or row.get("full_order_gate") is not False
            or row.get("icf_fold_status") != "not-established"
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} has a "
                "stale or gating registered alias row"
            )
        registered_addresses = target.get("registered_addresses")
        if (
            not isinstance(registered_addresses, list)
            or sum(
                1
                for raw_registered in registered_addresses
                if isinstance(raw_registered, str)
                and normalize_address(raw_registered) == address
            )
            != 1
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} lacks "
                "one exact registered address"
            )
        manifest_value = (
            registration.get("manifest_path")
            if isinstance(registration, Mapping)
            else None
        )
        if not isinstance(manifest_value, str) or not manifest_value:
            raise ValueError(
                f"registered non-gating logical target {physical_id} has no "
                "manifest path"
            )
        manifest_path = Path(manifest_value)
        if not manifest_path.is_absolute():
            manifest_path = REPO_ROOT / manifest_path
        try:
            manifest_path = manifest_path.resolve()
            manifest_path.relative_to(
                (REPO_ROOT / "tools" / "vc5_verify_targets").resolve()
            )
        except ValueError as exc:
            raise ValueError(
                f"registered non-gating logical target {physical_id} has a "
                "manifest outside tools/vc5_verify_targets"
            ) from exc
        from _recoil.lib.verification_targets import vc5_target_registration

        try:
            current_id, current_target = vc5_target_registration(
                manifest_path
            )
        except (OSError, ValueError) as exc:
            raise ValueError(
                f"registered non-gating logical target {physical_id} cannot "
                "synchronize its registered target"
            ) from exc
        current_registration = current_target.get("registration")
        current_registered_addresses = current_target.get(
            "registered_addresses"
        )
        current_rows = [
            current_row
            for current_row in _mapping_target_function_rows(current_target)
            if isinstance(current_row.get("address"), str)
            and normalize_address(current_row["address"]) == address
        ]
        if (
            current_id != target_id
            or current_target.get("binary") != target.get("binary")
            or current_target.get("kind") != target.get("kind")
            or current_target.get("name") != target.get("name")
            or not isinstance(current_registration, Mapping)
            or current_registration.get("manifest_path") != manifest_value
            or current_registration.get("binary")
            != registration.get("binary")
            or current_registration.get("name")
            != registration.get("name")
            or not isinstance(current_registered_addresses, list)
            or sum(
                1
                for raw_registered in current_registered_addresses
                if isinstance(raw_registered, str)
                and normalize_address(raw_registered) == address
            )
            != 1
            or not current_rows
            or any(
                dict(current_row) != dict(row)
                for current_row in current_rows
            )
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} has a "
                "stale or conflicting synchronized manifest row"
            )

        authored_order = (
            block.get("order", {}).get("authored", {})
            if isinstance(block, Mapping)
            and isinstance(block.get("order"), Mapping)
            else None
        )
        if (
            not isinstance(block_id, str)
            or not isinstance(block, Mapping)
            or not isinstance(facts, Mapping)
            or facts.get("phase") != "authored-function-order"
            or facts.get("validation_mode") != "live"
            or facts.get("target_id") != target_id
            or not isinstance(facts.get("covered_block_ids"), list)
            or facts["covered_block_ids"].count(block_id) != 1
            or not isinstance(facts.get("matched_identities"), list)
            or facts["matched_identities"].count(alias_id) != 1
            or facts["matched_identities"].count(str(physical_id)) != 0
            or accepted_occurrences.get(alias_id, 0) != 1
            or accepted_occurrences.get(str(physical_id), 0) != 0
            or vc5_target_ids != [target_id]
            or not isinstance(authored_order, Mapping)
            or not authored_order
            or any(
                not isinstance(state, Mapping)
                or state.get("disposition") != "accepted"
                or state.get("freshness") != "current"
                or state.get("result") != "passed"
                or state.get("validation_mode") != "live"
                for state in authored_order.values()
            )
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} lacks "
                "one exact accepted authored-order block/target occurrence"
            )

        registered_name_rows = [
            (
                str(candidate_target_id),
                candidate_row,
            )
            for candidate_target_id, candidate_target in targets.items()
            if isinstance(candidate_target, Mapping)
            for candidate_row in _mapping_target_function_rows(
                candidate_target
            )
            if isinstance(candidate_row.get("symbol"), str)
            and candidate_row["symbol"].casefold()
            == object_symbol.casefold()
        ]
        if (
            len(registered_name_rows) != 1
            or registered_name_rows[0][0] != target_id
            or dict(registered_name_rows[0][1]) != dict(row)
        ):
            raise ValueError(
                f"registered non-gating logical target {physical_id} has an "
                "ambiguous registered candidate name"
            )
        prior_address = by_address.get(address)
        prior_name = by_candidate_name.get(object_symbol)
        if prior_address not in {None, logical_identity} or prior_name not in {
            None,
            logical_identity,
        }:
            raise ValueError(
                f"registered non-gating logical target {physical_id} "
                "collides with another reviewed logical target"
            )
        by_address[address] = logical_identity
        by_candidate_name[object_symbol] = logical_identity

    return by_address, by_candidate_name


def build_identity_indexes(
    document: ProgressDocument,
    *,
    bridge: BinaryNinjaBridge | None = None,
    retail_provider_fact_transcript: list[dict[str, Any]] | None = None,
    bridge_by_address: Mapping[str, Any] | None = None,
    bridge_data_rows: Sequence[Any] | None = None,
) -> IdentityIndexes:
    require_valid_authored_icf_groups(document.data)
    (
        reviewed_icf_group_by_address,
        reviewed_icf_group_by_logical_identity,
    ) = _winner_unknown_icf_group_indexes(document)
    (
        reviewed_non_gating_logical_target_by_address,
        reviewed_non_gating_logical_target_by_candidate_name,
    ) = _registered_non_gating_logical_target_indexes(document)
    by_address: dict[str, str] = {}
    provider_ids: set[str] = set()
    reviewed_logical_aliases_by_address: dict[
        str, list[ReviewedLogicalAlias]
    ] = {}
    reviewed_authored_icf_by_call_site: dict[str, tuple[str, str]] = {}
    reviewed_authored_icf_candidate_by_call_site: dict[
        str, tuple[str, str, str, str]
    ] = {}
    reviewed_authored_icf_provisional_candidate_by_name: dict[
        str, tuple[str, str]
    ] = {}
    reviewed_authored_icf_physical_by_logical_identity: dict[str, str] = {}
    authored_icf_candidate_only_names: set[str] = set()
    authored_icf_object_memberships: dict[str, tuple[str, str, str]] = {}
    for symbol_id, symbol in document.collection("symbols").items():
        if not isinstance(symbol, Mapping):
            continue
        if symbol.get("kind") not in {
            "function",
            "provider-function",
            "compiler-function",
        }:
            # Invocation targets and storage have distinct identities. In
            # particular, one IAT address may have both a provider-function
            # view and a provider-data view; the latter is indexed below as
            # storage and must not make the callable identity ambiguous.
            continue
        raw_address = symbol.get("address", symbol.get("start"))
        if not isinstance(raw_address, str):
            continue
        try:
            address = normalize_address(raw_address)
        except ProgressError:
            continue
        identity = _symbol_identity(str(symbol_id), symbol)
        logical_aliases = symbol.get("logical_aliases")
        if isinstance(logical_aliases, Mapping) and logical_aliases:
            group = symbol.get("icf_address_group")
            authored_icf_group = bool(
                isinstance(group, Mapping)
                and group.get("model") == AUTHORED_ICF_GROUP_MODEL
                and group.get("physical_gate_symbol_id") == symbol_id
            )
            reviewed_logical_aliases_by_address.setdefault(address, []).extend(
                ReviewedLogicalAlias(
                    identity=f"logical:{alias_id}",
                    original_name=(
                        str(alias.get("original_name") or "")
                        if alias.get("original_name_status") != "provisional"
                        else ""
                    ),
                    object_symbol=(
                        ""
                        if authored_icf_group
                        else str(alias.get("object_symbol") or "")
                    ),
                )
                for alias_id, alias in logical_aliases.items()
                if isinstance(alias, Mapping)
                and alias.get("pipeline_class") in {"authored", "authored-lifecycle"}
                and (
                    alias.get("fold_status") == "proven-fold-alias"
                    or authored_icf_group
                )
                and (
                    isinstance(alias.get("original_name"), str)
                    and bool(alias.get("original_name"))
                    or isinstance(alias.get("object_symbol"), str)
                    and bool(alias.get("object_symbol"))
                )
            )
            if authored_icf_group:
                for alias_id, alias in logical_aliases.items():
                    if not isinstance(alias, Mapping):
                        raise ValueError(
                            f"authored ICF logical member {alias_id!r} is not an object"
                        )
                    logical_identity = f"logical:{alias_id}"
                    reviewed_authored_icf_physical_by_logical_identity[
                        logical_identity
                    ] = str(symbol_id)
                    object_symbol = alias.get("object_symbol")
                    if (
                        not isinstance(object_symbol, str)
                        or not _decorated_coff_name(object_symbol)
                    ):
                        raise ValueError(
                            f"authored ICF logical member {alias_id!r} has no "
                            "exact decorated candidate object symbol"
                        )
                    object_membership = (
                        str(symbol_id),
                        str(alias_id),
                        object_symbol,
                    )
                    prior_object_membership = authored_icf_object_memberships.get(
                        object_symbol.casefold()
                    )
                    if prior_object_membership not in {None, object_membership}:
                        raise ValueError(
                            f"authored ICF candidate object symbol {object_symbol!r} "
                            "has an ambiguous or case-conflicting logical population"
                        )
                    authored_icf_object_memberships[
                        object_symbol.casefold()
                    ] = object_membership
                    authored_icf_candidate_only_names.add(object_symbol)
                    if alias.get("original_name_status") == "provisional":
                        provisional_selection = (
                            str(symbol_id),
                            logical_identity,
                        )
                        prior_provisional = (
                            reviewed_authored_icf_provisional_candidate_by_name.get(
                                object_symbol
                            )
                        )
                        if prior_provisional not in {
                            None,
                            provisional_selection,
                        }:
                            raise ValueError(
                                "authored ICF provisional candidate object symbol "
                                f"{object_symbol!r} selects conflicting reviewed "
                                "logical identities"
                            )
                        reviewed_authored_icf_provisional_candidate_by_name[
                            object_symbol
                        ] = provisional_selection
                    selectors = alias.get("retail_target_selectors")
                    if not isinstance(selectors, Mapping):
                        raise ValueError(
                            f"authored ICF logical member {alias_id!r} has no retail selectors"
                        )
                    direct_call_sites = selectors.get("direct_call_sites")
                    if (
                        not isinstance(direct_call_sites, list)
                        or any(
                            not isinstance(raw_call_site, str)
                            or not raw_call_site
                            for raw_call_site in direct_call_sites
                        )
                    ):
                        raise ValueError(
                            f"authored ICF logical member {alias_id!r} has a "
                            "malformed direct-call selector population"
                        )
                    normalized_call_sites = [
                        normalize_address(raw_call_site)
                        for raw_call_site in direct_call_sites
                    ]
                    if len(set(normalized_call_sites)) != len(normalized_call_sites):
                        raise ValueError(
                            f"authored ICF logical member {alias_id!r} has a "
                            "duplicate direct-call selector population"
                        )
                    for call_site in normalized_call_sites:
                        selection = (address, logical_identity)
                        prior = reviewed_authored_icf_by_call_site.get(call_site)
                        if prior not in {None, selection}:
                            raise ValueError(
                                f"authored ICF retail call site {call_site} selects "
                                "conflicting logical identities"
                            )
                        reviewed_authored_icf_by_call_site[call_site] = selection
                        candidate_selection = (
                            address,
                            str(symbol_id),
                            object_symbol,
                            logical_identity,
                        )
                        prior_candidate = (
                            reviewed_authored_icf_candidate_by_call_site.get(
                                call_site
                            )
                        )
                        if prior_candidate not in {None, candidate_selection}:
                            raise ValueError(
                                f"authored ICF retail call site {call_site} has "
                                "a conflicting candidate object-symbol population"
                            )
                        reviewed_authored_icf_candidate_by_call_site[
                            call_site
                        ] = candidate_selection
            authored_aliases = {
                str(alias_id): alias
                for alias_id, alias in logical_aliases.items()
                if isinstance(alias, Mapping)
                and alias.get("authored_order_role")
                in {"authored-body", "authored-lifecycle-body"}
            }
            winner_key = (
                str(group.get("winner_identity_key") or "")
                if isinstance(group, Mapping)
                and group.get("winner_status") == "selected-winner"
                else ""
            )
            selected_aliases = [
                alias_id
                for alias_id, alias in authored_aliases.items()
                if winner_key
                and winner_key
                in {
                    str(alias_id),
                    str(alias.get("logical_identity_key") or ""),
                    str(alias.get("object_symbol") or ""),
                }
            ]
            if not authored_icf_group:
                identity = (
                    f"logical:{selected_aliases[0]}"
                    if len(selected_aliases) == 1
                    else ""
                )
        if address in by_address and by_address[address] != identity:
            # Physical aliases are not silently selected as expected truth.
            by_address[address] = ""
        else:
            by_address[address] = identity
        if identity.startswith("provider:"):
            provider_ids.add(identity)

    by_candidate_name: dict[str, str] = {}
    reviewed_binding_names: set[str] = set()
    reviewed_data_bindings: list[
        tuple[str, Mapping[str, Any], Mapping[str, Any], str]
    ] = []

    # A governed provider-function registration carries a candidate-independent
    # object identity on the existing physical function row.  Schema v1 names
    # one exact static-library archive member; schema v2 names one exact
    # canonical-header COMDAT probe.  Index the object name directly only when
    # the complete accepted owner/evidence package remains current.  In
    # particular, v2 must not weaken the v1 archive-member provenance checks.
    for symbol_id, symbol in document.collection("symbols").items():
        if not isinstance(symbol, Mapping):
            continue
        provider_object = symbol.get("provider_object_identity")
        if not isinstance(provider_object, Mapping):
            continue
        provider_schema = provider_object.get("schema")
        object_symbol = provider_object.get("object_symbol")
        raw_address = symbol.get("address")
        evidence_id = provider_object.get("evidence_id")
        archive_member_registration = provider_schema == (
            "recoil-provider-function-object-v1"
        )
        canonical_header_registration = provider_schema == (
            "recoil-provider-function-object-v2"
        )
        physical_emitter = provider_object.get("physical_emitter")
        retail_icf = provider_object.get("retail_icf")
        logical_symbols = (
            retail_icf.get("logical_symbols")
            if isinstance(retail_icf, Mapping)
            else None
        )
        schema_registration_complete = (
            (
                archive_member_registration
                and isinstance(provider_object.get("library_path"), str)
                and bool(provider_object["library_path"])
                and isinstance(provider_object.get("archive_member"), str)
                and bool(provider_object["archive_member"])
            )
            or (
                canonical_header_registration
                and provider_object.get("proof_mode")
                == "canonical-header-comdat"
                and isinstance(provider_object.get("canonical_header"), str)
                and bool(provider_object["canonical_header"])
                and isinstance(provider_object.get("probe_recipe"), str)
                and bool(provider_object["probe_recipe"])
                and isinstance(provider_object.get("section_name"), str)
                and bool(provider_object["section_name"])
                and isinstance(provider_object.get("body_size"), int)
                and not isinstance(provider_object["body_size"], bool)
                and provider_object["body_size"] > 0
                and isinstance(provider_object.get("comdat_selection"), int)
                and not isinstance(provider_object["comdat_selection"], bool)
                and provider_object["comdat_selection"] > 0
                and isinstance(provider_object.get("semantic_provider"), str)
                and bool(provider_object["semantic_provider"])
                and isinstance(physical_emitter, Mapping)
                and physical_emitter.get("state") == "winner-unknown"
                and isinstance(retail_icf, Mapping)
                and retail_icf.get("winner_status") == "winner-unknown"
                and isinstance(logical_symbols, list)
                and bool(logical_symbols)
                and all(
                    isinstance(logical_symbol, str) and bool(logical_symbol)
                    for logical_symbol in logical_symbols
                )
                and len(set(logical_symbols)) == len(logical_symbols)
                and object_symbol in logical_symbols
            )
        )
        if (
            not schema_registration_complete
            or symbol.get("kind") != "provider-function"
            or symbol.get("disposition") != "provider"
            or symbol.get("ownership_state") != "primary-owned"
            or symbol.get("pipeline_class") != "non-authored"
            or symbol.get("authored_order_role") != "non-authored"
            or not isinstance(object_symbol, str)
            or not object_symbol
            or symbol.get("object_symbol") != object_symbol
            or not isinstance(raw_address, str)
            or not isinstance(evidence_id, str)
            or evidence_id not in symbol.get("evidence_ids", ())
        ):
            raise ValueError(
                f"registered provider object identity for {symbol_id} is incomplete"
            )
        address = normalize_address(raw_address)
        identity = by_address.get(address, "")
        if not identity or identity != f"provider:{symbol_id}":
            raise ValueError(
                f"registered provider object identity for {symbol_id} has no unique "
                "provider physical identity"
            )
        matching_owners = []
        for owner_id, owner in document.collection("owners").items():
            if not isinstance(owner, Mapping):
                continue
            relationships = owner.get("relationships")
            if not isinstance(relationships, list):
                continue
            if any(
                isinstance(relationship, Mapping)
                and relationship.get("kind") == "primary-function"
                and relationship.get("symbol_id") == symbol_id
                and relationship.get("address") == address
                for relationship in relationships
            ):
                matching_owners.append((owner_id, owner))
        if len(matching_owners) != 1:
            raise ValueError(
                f"registered provider object identity for {symbol_id} does not have "
                "exactly one primary provider owner"
            )
        owner_id, owner = matching_owners[0]
        gates = owner.get("gates")
        if (
            owner.get("kind") != "provider-boundary"
            or owner.get("provider_state") != "accepted"
            or owner.get("lifecycle_state") != "accepted"
            or not isinstance(gates, Mapping)
            or gates.get("boundary") != "accepted"
            or gates.get("source") != "accepted"
            or gates.get("owner_linkage") != "accepted"
            or evidence_id not in owner.get("evidence_ids", ())
        ):
            raise ValueError(
                f"registered provider object identity for {symbol_id} has stale "
                f"provider owner {owner_id}"
            )
        evidence = document.collection("evidence").get(evidence_id)
        provenance = evidence.get("provenance") if isinstance(evidence, Mapping) else None
        archive_member_provenance_matches = bool(
            archive_member_registration
            and isinstance(provenance, Mapping)
            and provenance.get("library_path")
            == provider_object.get("library_path")
            and provenance.get("archive_member")
            == provider_object.get("archive_member")
            and provenance.get("object_symbol") == object_symbol
        )
        canonical_header_provenance_matches = bool(
            canonical_header_registration
            and isinstance(provenance, Mapping)
            and provenance.get("proof_mode") == "canonical-header-comdat"
            and provenance.get("canonical_header")
            == provider_object.get("canonical_header")
            and provenance.get("probe_recipe")
            == provider_object.get("probe_recipe")
            and provenance.get("object_symbol") == object_symbol
            and provenance.get("section_name")
            == provider_object.get("section_name")
            and provenance.get("body_size") == provider_object.get("body_size")
            and provenance.get("comdat_selection")
            == provider_object.get("comdat_selection")
            and provenance.get("semantic_provider")
            == provider_object.get("semantic_provider")
            and provenance.get("physical_emitter_state")
            == physical_emitter.get("state")
            and provenance.get("retail_icf_winner_status")
            == retail_icf.get("winner_status")
            and provenance.get("retail_icf_logical_symbols") == logical_symbols
        )
        if (
            not isinstance(evidence, Mapping)
            or evidence.get("kind") != "provider-function-registration"
            or evidence.get("freshness") != "current"
            or not isinstance(provenance, Mapping)
            or provenance.get("candidate_independent") is not True
            or not (
                archive_member_provenance_matches
                or canonical_header_provenance_matches
            )
        ):
            raise ValueError(
                f"registered provider object identity for {symbol_id} has stale "
                "or mismatched live evidence"
            )
        prior = by_candidate_name.get(object_symbol)
        if prior not in {None, identity}:
            raise ValueError(
                f"registered provider object name {object_symbol!r} maps to "
                f"conflicting identities {prior!r} and {identity!r}"
            )
        by_candidate_name[object_symbol] = identity

    for symbol in document.collection("symbols").values():
        if not isinstance(symbol, Mapping):
            continue
        logical_aliases = symbol.get("logical_aliases")
        if not isinstance(logical_aliases, Mapping):
            continue
        for alias_id, alias in logical_aliases.items():
            if not isinstance(alias, Mapping):
                continue
            object_symbol = alias.get("object_symbol")
            if isinstance(object_symbol, str) and object_symbol:
                by_candidate_name[object_symbol] = f"logical:{alias_id}"
    for symbol_id, symbol in document.collection("symbols").items():
        if not isinstance(symbol, Mapping):
            continue
        raw_binding = symbol.get("relocation_target_binding")
        if not isinstance(raw_binding, Mapping):
            continue
        binding = normalize_relocation_target_binding(raw_binding)
        context = binding["binding_context"]
        if context["creation_mode"] != "existing-symbol":
            continue
        target = context["target"]
        if target["symbol_id"] != symbol_id:
            raise ValueError(
                f"reviewed relocation target binding for {symbol_id} points to "
                f"different existing symbol {target['symbol_id']}"
            )
        raw_address = symbol.get("address", symbol.get("start"))
        if not isinstance(raw_address, str):
            raise ValueError(
                f"reviewed relocation target binding for {symbol_id} has no physical address"
            )
        address = normalize_address(raw_address)
        if target["address"] != address:
            raise ValueError(
                f"reviewed relocation target binding for {symbol_id} has stale target address"
            )
        target_kind = symbol.get("kind")
        if target_kind in {"data", "data-symbol"}:
            if (
                symbol.get("binary") != "recoil"
                or any(
                    field in symbol
                    for field in ("import_name", "import_dll", "import_ordinal")
                )
            ):
                raise ValueError(
                    f"reviewed relocation target binding for {symbol_id} has "
                    "provider/import data identity"
                )
            current_target = relocation_target_row_context(
                symbol_id=str(symbol_id),
                row=symbol,
                object_symbol=str(binding["object_symbol"]),
            )
            if current_target != target:
                raise ValueError(
                    f"reviewed relocation target binding for {symbol_id} has "
                    "stale data target snapshot"
                )
            reviewed_data_bindings.append(
                (str(symbol_id), symbol, binding, address)
            )
            continue
        if target_kind not in {
            "function",
            "provider-function",
            "compiler-function",
        }:
            raise ValueError(
                f"reviewed relocation target binding for {symbol_id} has "
                f"unsupported target kind {target_kind!r}"
            )
        identity = by_address.get(address, "")
        if not identity:
            raise ValueError(
                f"reviewed relocation target binding for {symbol_id} has ambiguous "
                "or unresolved physical identity"
            )
        object_symbol = binding["object_symbol"]
        prior = by_candidate_name.get(object_symbol)
        if prior is not None and prior != identity:
            raise ValueError(
                f"reviewed existing-symbol object name {object_symbol!r} maps to "
                f"conflicting identities {prior!r} and {identity!r} ({symbol_id})"
            )
        by_candidate_name[object_symbol] = identity
        reviewed_binding_names.add(object_symbol)
    for target in document.collection("verification_targets").values():
        if not isinstance(target, Mapping):
            continue
        registration = target.get("registration")
        if not isinstance(registration, Mapping):
            continue
        function_rows: list[Mapping[str, Any]] = []
        for value in registration.get("functions", []):
            if isinstance(value, Mapping):
                function_rows.append(value)
        for entry in registration.get("translation_unit_function_order", []):
            if isinstance(entry, Mapping):
                function_rows.extend(
                    value
                    for value in entry.get("functions", [])
                    if isinstance(value, Mapping)
                )
        for interval in registration.get("linked_function_intervals", []):
            if isinstance(interval, Mapping):
                function_rows.extend(
                    value
                    for value in interval.get("functions", [])
                    if isinstance(value, Mapping)
                )
        for row in function_rows:
            address = row.get("address")
            symbol_name = row.get("symbol")
            if not isinstance(address, str) or not isinstance(symbol_name, str) or not symbol_name:
                continue
            identity = by_address.get(normalize_address(address), "")
            if not identity:
                continue
            prior = by_candidate_name.get(symbol_name)
            if (
                symbol_name in reviewed_binding_names
                and prior is not None
                and prior != identity
            ):
                raise ValueError(
                    f"reviewed existing-symbol object name {symbol_name!r} maps to "
                    f"conflicting identities {prior!r} and {identity!r} "
                    f"(verification target row {address})"
                )
            by_candidate_name[symbol_name] = (
                identity if prior in {None, identity} else ""
            )

    _index_finite_symbol_regex_names(
        document,
        by_address=by_address,
        by_candidate_name=by_candidate_name,
    )
    for name, identity in (
        reviewed_non_gating_logical_target_by_candidate_name.items()
    ):
        if by_candidate_name.get(name) != identity:
            raise ValueError(
                f"registered non-gating logical candidate name {name!r} "
                "does not resolve uniquely to its reviewed alias"
            )
    candidate_names_before_lifecycle_fallback = set(by_candidate_name)
    _index_registered_lifecycle_deleting_destructor_names(
        document,
        by_address=by_address,
        by_candidate_name=by_candidate_name,
    )
    scalar_deleting_destructor_legacy_fallback_names = frozenset(
        name
        for name, identity in by_candidate_name.items()
        if (
            not identity
            and name not in candidate_names_before_lifecycle_fallback
            and _nonvirtual_scalar_deleting_destructor_class(name)
            is not None
        )
    )
    (
        scalar_deleting_destructors,
        scalar_deleting_destructor_blockers,
    ) = _registered_scalar_deleting_destructor_suppliers(
        document,
        by_address=by_address,
        bridge_by_address=bridge_by_address or {},
    )
    _index_registered_vector_assignment_provider_name(
        document,
        by_address=by_address,
        by_candidate_name=by_candidate_name,
        provider_ids=frozenset(provider_ids),
    )
    pointer_vector_destroy_providers = (
        _registered_pointer_vector_destroy_provider_suppliers(
            document,
            by_address=by_address,
            provider_ids=frozenset(provider_ids),
            bridge=bridge,
            fact_transcript=retail_provider_fact_transcript,
        )
    )
    hud_cmd_binding_ptr_vector_erase_provider = (
        _hud_cmd_binding_ptr_vector_erase_provider_supplier(
            document,
            by_address=by_address,
            provider_ids=frozenset(provider_ids),
            bridge=bridge,
            fact_transcript=retail_provider_fact_transcript,
        )
    )

    storage_by_address: dict[str, str] = {}
    storage_by_name: dict[str, str] = {}
    for collection_name in ("storage_contributions", "symbols"):
        for entity_id, row in document.collection(collection_name).items():
            if not isinstance(row, Mapping):
                continue
            if (
                row.get("kind") == "provider-data"
                or "import_name" in row
                or "import_dll" in row
                or "import_ordinal" in row
            ):
                # Provider IAT views are indexed only from a complete current
                # tracker package below. Partial rows never become truth.
                continue
            raw_address = row.get("address", row.get("start"))
            address = ""
            if isinstance(raw_address, str):
                try:
                    address = normalize_address(raw_address)
                except ProgressError:
                    pass
            if collection_name == "symbols" and row.get("kind") in {
                "function",
                "provider-function",
                "compiler-function",
            }:
                continue
            if address:
                identity = f"storage:{entity_id}"
                storage_by_address.setdefault(address, identity)
            for key in ("name", "navigation_name", "symbol"):
                value = row.get(key)
                if isinstance(value, str) and value:
                    storage_by_name.setdefault(value, f"storage:{entity_id}")
    packages = _current_tracker_iat_storage_packages(document)
    packages_by_address: dict[str, set[CurrentIatStoragePackage]] = {}
    packages_by_name: dict[str, set[CurrentIatStoragePackage]] = {}
    for package in packages:
        packages_by_address.setdefault(package.address, set()).add(package)
        packages_by_name.setdefault(package.import_name, set()).add(package)
        packages_by_name.setdefault(package.object_symbol, set()).add(package)
        if package.import_ordinal is not None:
            packages_by_name.setdefault(
                f"{package.import_dll}!#{package.import_ordinal}",
                set(),
            ).add(package)
    for address, suppliers in packages_by_address.items():
        _publish_collected_identity(
            storage_by_address,
            address,
            {supplier.identity for supplier in suppliers}
            if len(suppliers) == 1
            else set(),
        )
    for name, suppliers in packages_by_name.items():
        _publish_collected_identity(
            storage_by_name,
            name,
            {supplier.identity for supplier in suppliers}
            if len(suppliers) == 1
            else set(),
        )
    storage_containers: set[StorageContainer] = set()
    data_rows = tuple(bridge_data_rows or ())
    data_row_address_counts: dict[int, int] = {}
    for row in data_rows:
        try:
            value = address_value(normalize_address(str(getattr(row, "address", ""))))
        except (ProgressError, ValueError):
            continue
        data_row_address_counts[value] = data_row_address_counts.get(value, 0) + 1
    for row in data_rows:
        raw_address = getattr(row, "address", "")
        if not raw_address:
            continue
        try:
            address = normalize_address(str(raw_address))
        except ProgressError:
            continue
        identity = storage_by_address.get(address, "")
        if not identity or identity.startswith("iat:"):
            continue
        try:
            size = int(getattr(row, "size", 0))
        except (TypeError, ValueError):
            size = 0
        start = address_value(address)
        if size <= 0:
            # BN sometimes leaves an individual function-pointer cell
            # untyped/unsized even though its immediately adjacent data rows
            # prove both exact four-byte boundaries.  Require unique rows on
            # both sides; one neighbor, a duplicate row, or a wider gap is not
            # extent evidence.
            if not (
                data_row_address_counts.get(start, 0) == 1
                and data_row_address_counts.get(start - 4, 0) == 1
                and data_row_address_counts.get(start + 4, 0) == 1
            ):
                continue
            size = 4
        storage_containers.add(
            StorageContainer(
                start=start,
                end_exclusive=start + size,
                identity=identity,
            )
        )
        bridge_names = {
            str(getattr(row, "name", "") or ""),
            str(getattr(row, "raw_name", "") or ""),
        }
        for name in bridge_names | {
            name.lower() for name in bridge_names if name
        }:
            if not name:
                continue
            prior = storage_by_name.get(name)
            storage_by_name[name] = (
                identity if prior in {None, identity} else ""
            )
    _index_registered_decorated_data_names(
        document,
        storage_by_name=storage_by_name,
    )
    for symbol_id, _symbol, binding, address in reviewed_data_bindings:
        expected_identity = f"storage:{symbol_id}"
        address_identities: set[str] = set()
        matching_name_identities: set[str] = set()
        object_symbol = str(binding["object_symbol"])
        for collection_name in ("storage_contributions", "symbols"):
            for entity_id, row in document.collection(collection_name).items():
                if not isinstance(row, Mapping):
                    continue
                if (
                    row.get("kind") == "provider-data"
                    or "import_name" in row
                    or "import_dll" in row
                    or "import_ordinal" in row
                ):
                    continue
                raw_address = row.get("address", row.get("start"))
                row_address = ""
                if isinstance(raw_address, str):
                    try:
                        row_address = normalize_address(raw_address)
                    except ProgressError:
                        pass
                identity = f"storage:{entity_id}"
                if row_address == address:
                    address_identities.add(identity)
                if any(
                    row.get(key) == object_symbol
                    for key in ("name", "navigation_name", "symbol")
                ):
                    matching_name_identities.add(identity)
        if (
            address_identities != {expected_identity}
            or storage_by_address.get(address) != expected_identity
        ):
            raise ValueError(
                f"reviewed data relocation target binding for {symbol_id} has "
                "missing, ambiguous, or colliding storage identity"
            )
        prior = storage_by_name.get(object_symbol)
        if (
            prior not in {None, expected_identity}
            or matching_name_identities - {expected_identity}
        ):
            raise ValueError(
                f"reviewed existing-data object name {object_symbol!r} maps to "
                f"a conflicting storage identity ({symbol_id})"
            )
        storage_by_name[object_symbol] = expected_identity
    return IdentityIndexes(
        by_address=by_address,
        by_candidate_name=by_candidate_name,
        provider_ids=frozenset(provider_ids),
        storage_by_address=storage_by_address,
        storage_by_name=storage_by_name,
        candidate_only_names=frozenset(authored_icf_candidate_only_names),
        reviewed_icf_group_by_address=reviewed_icf_group_by_address,
        reviewed_icf_group_by_logical_identity=(
            reviewed_icf_group_by_logical_identity
        ),
        reviewed_logical_aliases_by_address={
            address: tuple(aliases)
            for address, aliases in reviewed_logical_aliases_by_address.items()
            if aliases
        },
        reviewed_authored_icf_by_call_site=reviewed_authored_icf_by_call_site,
        reviewed_authored_icf_candidate_by_call_site=(
            reviewed_authored_icf_candidate_by_call_site
        ),
        reviewed_authored_icf_provisional_candidate_by_name=(
            reviewed_authored_icf_provisional_candidate_by_name
        ),
        reviewed_authored_icf_physical_by_logical_identity=(
            reviewed_authored_icf_physical_by_logical_identity
        ),
        reviewed_authored_icf_by_vtable_selector=(
            authored_icf_vtable_selector_index(document.collection("symbols"))
        ),
        reviewed_non_gating_logical_target_by_address=(
            reviewed_non_gating_logical_target_by_address
        ),
        storage_containers=tuple(
            sorted(
                storage_containers,
                key=lambda row: (row.start, row.end_exclusive, row.identity),
            )
        ),
        pointer_vector_destroy_providers=(
            pointer_vector_destroy_providers
        ),
        hud_cmd_binding_ptr_vector_erase_provider=(
            hud_cmd_binding_ptr_vector_erase_provider
        ),
        scalar_deleting_destructors=scalar_deleting_destructors,
        scalar_deleting_destructor_blockers=(
            scalar_deleting_destructor_blockers
        ),
        scalar_deleting_destructor_legacy_fallback_names=(
            scalar_deleting_destructor_legacy_fallback_names
        ),
    )


def _instruction_mnemonic(instruction: Instruction) -> str:
    return instruction.raw_text.split(None, 1)[0].lower() if instruction.raw_text else ""


def _instruction_operand(instruction: Instruction) -> str:
    parts = instruction.raw_text.split(None, 1)
    return parts[1].strip() if len(parts) == 2 else ""


def _exact_invocation_encoding(
    instruction: Instruction,
    *,
    mnemonic: str,
) -> bool:
    """Require the rendered CALL/JMP form to agree with exact x86 bytes.

    Binary Ninja may return a containing function for an overlapping EH
    continuation.  The continuation's first bytes and rendered instruction
    remain authoritative: a TEST (or any other non-invocation encoding) must
    never enter the static invocation census merely because stale/overlapping
    text labels it as a CALL.  Prefixes are intentionally rejected here; no
    reviewed call-contract row depends on a prefixed CALL/JMP form.
    """

    try:
        body = bytes(int(item, 16) for item in instruction.bytes)
    except (TypeError, ValueError):
        return False
    def exact_ff_group_length() -> bool:
        if len(body) < 2 or body[0] != 0xFF:
            return False
        modrm = body[1]
        mode = modrm >> 6
        rm = modrm & 0x07
        length = 2
        sib_base: int | None = None
        if mode != 3 and rm == 4:
            if len(body) <= length:
                return False
            sib_base = body[length] & 0x07
            length += 1
        if mode == 0 and (rm == 5 or (rm == 4 and sib_base == 5)):
            length += 4
        elif mode == 1:
            length += 1
        elif mode == 2:
            length += 4
        return len(body) == length

    if mnemonic == "call":
        return (
            (len(body) == 5 and body[0] == 0xE8)
            or (
                exact_ff_group_length()
                and (
                    ((body[1] >> 3) & 0x07) == 2
                    or (
                        ((body[1] >> 3) & 0x07) == 3
                        and body[1] >> 6 != 3
                    )
                )
            )
            or (len(body) == 7 and body[0] == 0x9A)
        )
    if mnemonic == "jmp":
        return (
            (len(body) == 2 and body[0] == 0xEB)
            or (len(body) == 5 and body[0] == 0xE9)
            or (
                exact_ff_group_length()
                and (
                    ((body[1] >> 3) & 0x07) == 4
                    or (
                        ((body[1] >> 3) & 0x07) == 5
                        and body[1] >> 6 != 3
                    )
                )
            )
            or (len(body) == 7 and body[0] == 0xEA)
        )
    return False


def _retail_extent_has_call_references(
    instructions: Sequence[Instruction],
    *,
    caller_start: str,
    caller_end_exclusive: str,
) -> bool:
    """Report exact in-extent CALL encodings, never BN overlap metadata."""

    start = address_value(caller_start)
    end = address_value(caller_end_exclusive)
    addresses = _instruction_runtime_addresses(
        instructions,
        source="bn",
        caller_start=start,
    )
    counts: dict[int, int] = {}
    for address in addresses:
        if address is not None and start <= address < end:
            counts[address] = counts.get(address, 0) + 1
    return any(
        address is not None
        and start <= address < end
        and counts.get(address) == 1
        and _instruction_mnemonic(instruction) == "call"
        and _exact_invocation_encoding(instruction, mnemonic="call")
        for instruction, address in zip(instructions, addresses)
    )


def _exact_local_indexed_jump_table_address(
    instruction: Instruction,
    *,
    caller_start: int,
    caller_end: int,
) -> int | None:
    """Prove an encoded absolute indexed JMP table is caller-local.

    This classification is intentionally independent from complete switch
    edge recovery.  An exact ``FF /4`` SIB form with scale four, no base, and
    an absolute table base inside the selected caller extent is local control
    flow even when its cardinality or every successor cannot be recovered.
    Unknown successors terminate forward provenance and remain unresolved;
    the dispatch itself is never reinterpreted as an external tail call.
    """

    if _instruction_mnemonic(instruction) != "jmp":
        return None
    try:
        body = bytes(int(item, 16) for item in instruction.bytes)
    except (TypeError, ValueError):
        return None
    if (
        len(body) != 7
        or body[0:2] != b"\xff\x24"
        or body[2] >> 6 != 2
        or body[2] & 0x07 != 5
        or ((body[2] >> 3) & 0x07) == 4
    ):
        return None
    table_address = struct.unpack_from("<I", body, 3)[0]
    rendered_addresses = ADDRESS_RE.findall(_instruction_operand(instruction))
    memory_operands = MEMORY_RE.findall(_instruction_operand(instruction))
    index_registers = (
        "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi",
    )
    rendered_index = re.search(
        r"\b(?P<register>e(?:ax|cx|dx|bx|bp|si|di))\s*\*\s*4\b",
        memory_operands[0] if memory_operands else "",
        flags=re.IGNORECASE,
    )
    if (
        len(rendered_addresses) != 1
        or address_value(rendered_addresses[0]) != table_address
        or len(memory_operands) != 1
        or rendered_index is None
        or rendered_index.group("register").lower()
        != index_registers[(body[2] >> 3) & 0x07]
        or not caller_start <= table_address < caller_end
    ):
        return None
    return table_address


def _parse_unsigned_assembly_integer(token: str) -> int:
    """Parse one exact unsigned assembly literal without Python octal rules."""
    if re.fullmatch(r"\d+", token):
        return int(token, 10)
    if re.fullmatch(r"0x[0-9a-f]+", token, flags=re.IGNORECASE):
        return int(token[2:], 16)
    raise ValueError(f"invalid unsigned assembly integer literal {token!r}")


def _source_instruction_address(instruction: Instruction) -> str:
    parts = instruction.source_line.strip().split()
    if not parts:
        return ""
    raw = parts[0].rstrip(":")
    if re.fullmatch(r"[0-9a-fA-F]{5,8}", raw):
        return normalize_address(f"0x{raw}")
    return ""


REGISTER_STATE_NAMES = (
    "eax",
    "ebx",
    "ecx",
    "edx",
    "esi",
    "edi",
    "esp",
    "ebp",
)
SHORT_JCC_MNEMONICS = (
    frozenset({"jo"}),
    frozenset({"jno"}),
    frozenset({"jb", "jc", "jnae"}),
    frozenset({"jae", "jnb", "jnc"}),
    frozenset({"je", "jz"}),
    frozenset({"jne", "jnz"}),
    frozenset({"jbe", "jna"}),
    frozenset({"ja", "jnbe"}),
    frozenset({"js"}),
    frozenset({"jns"}),
    frozenset({"jp", "jpe"}),
    frozenset({"jnp", "jpo"}),
    frozenset({"jl", "jnge"}),
    frozenset({"jge", "jnl"}),
    frozenset({"jle", "jng"}),
    frozenset({"jg", "jnle"}),
)


def _instruction_runtime_address(
    instruction: Instruction,
    *,
    source: str,
    caller_start: int,
) -> int | None:
    raw_address = _source_instruction_address(instruction)
    if not raw_address:
        return None
    value = address_value(raw_address)
    if source == "cod":
        return caller_start + value
    if source == "bn" and value < caller_start:
        # Binary Ninja normally renders absolute virtual addresses, but its
        # bounded body renderers may use a zero-based body coordinate.  Bind
        # both renderings to the one runtime coordinate here; downstream
        # producers and consumers must never independently guess which space
        # an instruction row occupies.
        return caller_start + value
    return value


def _exact_instruction_byte_length(
    instruction: Instruction,
) -> int | None:
    if not instruction.bytes or any(
        re.fullmatch(r"[0-9a-fA-F]{2}", item) is None
        for item in instruction.bytes
    ):
        return None
    return len(instruction.bytes)


def _instruction_runtime_addresses(
    instructions: Sequence[Instruction],
    *,
    source: str,
    caller_start: int,
) -> tuple[int | None, ...]:
    """Resolve instruction starts, including exact VC5 COD continuations.

    VC5 wraps a six-byte instruction after five rendered bytes.  The assembly
    parser joins those bytes to the mnemonic continuation but necessarily
    retains the continuation as ``source_line``, which has no explicit offset.
    Derive that one start only from the immediately preceding resolved
    instruction and its exact encoded length.  An explicit offset remains
    authoritative and resets the local sequence after gaps or malformed rows.
    """
    addresses: list[int | None] = []
    previous_address: int | None = None
    previous_length: int | None = None
    for instruction in instructions:
        explicit_address = _instruction_runtime_address(
            instruction,
            source=source,
            caller_start=caller_start,
        )
        if explicit_address is not None:
            address = explicit_address
        elif (
            source == "cod"
            and previous_address is not None
            and previous_length is not None
        ):
            address = previous_address + previous_length
        else:
            address = None
        addresses.append(address)
        previous_address = address
        previous_length = (
            _exact_instruction_byte_length(instruction)
            if address is not None
            else None
        )
    return tuple(addresses)


def _closed_candidate_invocation_runtime_address(
    instructions: Sequence[Instruction],
    *,
    instruction_index: int,
    caller_start: int,
    caller_end: int,
    caller_definition: CandidateCallerDefinition,
) -> int:
    """Recover one addressless candidate invocation from exact closed bytes.

    VC5 can print an offset-bearing first line for a wrapped invocation and put
    the mnemonic on an addressless continuation retained by the shared parser.
    Bind that invocation to a runtime coordinate only when the containing COFF
    body, an explicit neighboring coordinate, cumulative instruction lengths,
    exact invocation bytes, and any relocation field all agree.  This is a
    coordinate proof only; it grants no target/provider identity.
    """

    def reject(detail: str) -> NoReturn:
        raise ValueError(
            "candidate invocation has no exact byte-closed runtime coordinate: "
            + detail
        )

    if (
        not 0 <= instruction_index < len(instructions)
        or caller_definition.section_start != 0
        or caller_definition.section_end != len(caller_definition.data)
        or len(caller_definition.relocation_mask)
        != len(caller_definition.data)
        or caller_start >= caller_end
        or _source_instruction_address(instructions[instruction_index])
    ):
        reject("instruction index, caller extent, or explicit-coordinate drift")

    explicit = tuple(
        _instruction_runtime_address(
            instruction,
            source="cod",
            caller_start=caller_start,
        )
        for instruction in instructions
    )
    previous_explicit = next(
        (
            index
            for index in range(instruction_index - 1, -1, -1)
            if explicit[index] is not None
        ),
        None,
    )
    next_explicit = next(
        (
            index
            for index in range(instruction_index + 1, len(instructions))
            if explicit[index] is not None
        ),
        None,
    )
    terminal_split_parts = (
        instructions[instruction_index]
        .source_line.split(";", 1)[0]
        .strip()
        .split()
    )
    if (
        next_explicit is not None
        and tuple(
            item.casefold()
            for item in instructions[instruction_index].bytes
        )
        == ("ff", "25", "00", "00", "00", "00")
        and len(terminal_split_parts) >= 2
        and terminal_split_parts[0].casefold() == "00"
        and terminal_split_parts[1].casefold() == "jmp"
    ):
        reject("nonterminal wrapped FF25 continuation")
    terminal_wrapped = False
    inferred: dict[int, int] = {}
    if next_explicit is None:
        instruction = instructions[instruction_index]
        marker_parts = instruction.source_line.rsplit(
            _COD_TERMINAL_WRAP_MARKER,
            1,
        )
        continuation_parts = (
            marker_parts[0].split(";", 1)[0].strip().split()
            if len(marker_parts) == 2
            else []
        )
        first_parts = (
            marker_parts[1].strip().split()
            if len(marker_parts) == 2
            else []
        )
        if (
            instruction_index != len(instructions) - 1
            or len(marker_parts) != 2
            or instruction.source_line.count(_COD_TERMINAL_WRAP_MARKER) != 1
            or len(continuation_parts) != 5
            or continuation_parts[0].casefold() != "00"
            or continuation_parts[1].casefold() != "jmp"
            or continuation_parts[2].casefold() != "dword"
            or continuation_parts[3].casefold() != "ptr"
            or re.fullmatch(
                r"[A-Za-z_?$@][A-Za-z0-9_?$@]*",
                continuation_parts[4],
            )
            is None
            or _instruction_operand(instruction).strip().casefold()
            != f"dword {continuation_parts[4]}".casefold()
            or len(first_parts) != 6
            or re.fullmatch(r"[0-9A-Fa-f]{5}", first_parts[0]) is None
            or tuple(item.casefold() for item in first_parts[1:])
            != ("ff", "25", "00", "00", "00")
            or caller_definition.section_index <= 0
            or caller_end - caller_start != len(caller_definition.data)
        ):
            reject("unclosed trailing row")
        invocation_address = caller_start + int(first_parts[0], 16)
        terminal_wrapped = True
    else:
        run_start = 0 if previous_explicit is None else previous_explicit + 1
        if any(
            explicit[index] is not None
            for index in range(run_start, next_explicit)
        ):
            reject("ambiguous explicit coordinate inside inferred run")
        if previous_explicit is None:
            cursor = caller_start
        else:
            previous_length = _exact_instruction_byte_length(
                instructions[previous_explicit]
            )
            if previous_length is None:
                reject("unparseable preceding instruction bytes")
            cursor = int(explicit[previous_explicit]) + previous_length

        for index in range(run_start, next_explicit):
            length = _exact_instruction_byte_length(instructions[index])
            if length is None:
                reject("unparseable inferred instruction bytes")
            inferred[index] = cursor
            cursor += length
        if cursor != explicit[next_explicit]:
            reject("next explicit coordinate does not close cumulative bytes")
        invocation_address = inferred.get(instruction_index)
    invocation_length = _exact_instruction_byte_length(
        instructions[instruction_index]
    )
    if invocation_address is None or invocation_length is None:
        reject("invocation is outside the closed inferred run")

    all_coordinates = [
        int(address)
        for address in explicit
        if address is not None
    ] + list(inferred.values())
    body_offset = invocation_address - caller_start
    if (
        len(all_coordinates) != len(set(all_coordinates))
        or not caller_start <= invocation_address < caller_end
        or invocation_address + invocation_length > caller_end
        or body_offset < 0
        or body_offset + invocation_length > len(caller_definition.data)
    ):
        reject("duplicate coordinate or caller/COFF bounds drift")

    instruction = instructions[instruction_index]
    mnemonic = _instruction_mnemonic(instruction)
    if mnemonic not in {"call", "jmp"} or not _exact_invocation_encoding(
        instruction, mnemonic=mnemonic
    ):
        reject("opcode/rendered invocation drift")
    try:
        invocation_body = bytes(int(item, 16) for item in instruction.bytes)
    except (TypeError, ValueError):
        reject("unparseable invocation bytes")
    if (
        caller_definition.data[
            body_offset : body_offset + invocation_length
        ]
        != invocation_body
    ):
        reject("COD/COFF invocation bytes drift")

    relocation_offset: int | None = None
    relocation_type: int | None = None
    operand_symbol = ""
    operand = _instruction_operand(instruction).strip()
    if len(invocation_body) == 5 and invocation_body[0] in {0xE8, 0xE9}:
        if invocation_body[1:] == b"\0" * 4:
            relocation_offset = body_offset + 1
            relocation_type = IMAGE_REL_I386_REL32
            operand_symbol = (
                _cod_space_bearing_direct_target(operand, instruction.source_line)
                or operand
            )
    elif (
        len(invocation_body) == 6
        and invocation_body[:2] in {b"\xff\x15", b"\xff\x25"}
        and invocation_body[2:] == b"\0" * 4
    ):
        relocation_offset = body_offset + 2
        relocation_type = IMAGE_REL_I386_DIR32
        operand_symbol = re.sub(
            r"^(?:(?:byte|word|dword|qword)\s+(?:ptr\s+)?)",
            "",
            operand,
            flags=re.IGNORECASE,
        ).strip()
        if operand_symbol.startswith("[") and operand_symbol.endswith("]"):
            operand_symbol = operand_symbol[1:-1].strip()

    overlapping_relocations = [
        relocation
        for relocation in caller_definition.relocations
        if body_offset
        <= relocation.offset
        < body_offset + invocation_length
    ]
    if relocation_offset is not None:
        matching_relocations = [
            relocation
            for relocation in overlapping_relocations
            if relocation.offset == relocation_offset
            and relocation.type == relocation_type
            and relocation.symbol_name == operand_symbol
        ]
        field_end = relocation_offset + 4
        nonfield_offsets = {
            offset
            for offset in range(body_offset, body_offset + invocation_length)
            if not relocation_offset <= offset < field_end
        }
        if (
            not operand_symbol
            or len(matching_relocations) != 1
            or len(overlapping_relocations) != 1
            or caller_definition.data[relocation_offset:field_end] != b"\0" * 4
            or not all(
                caller_definition.relocation_mask[offset]
                for offset in range(relocation_offset, field_end)
            )
            or any(
                caller_definition.relocation_mask[offset]
                for offset in nonfield_offsets
            )
        ):
            reject("opcode operand/COFF relocation agreement drift")
        if terminal_wrapped:
            body_end = body_offset + invocation_length
            if (
                len(caller_definition.relocations) != 1
                or any(
                    byte != 0x90
                    for byte in caller_definition.data[body_end:]
                )
                or any(caller_definition.relocation_mask[body_end:])
            ):
                reject("terminal section padding/relocation population drift")
            symbol_population = (
                caller_definition.undefined_external_functions.count(
                    operand_symbol
                )
                + caller_definition.defined_external_functions.count(
                    operand_symbol
                )
                + caller_definition.undefined_external_data.count(
                    operand_symbol
                )
                + caller_definition.defined_external_data.count(
                    operand_symbol
                )
            )
            if symbol_population != 1:
                reject("terminal relocation symbol population drift")
    elif overlapping_relocations or any(
        caller_definition.relocation_mask[offset]
        for offset in range(body_offset, body_offset + invocation_length)
    ):
        reject("unexpected relocation in nonrelocated invocation")
    return invocation_address


def _exact_cod_split_absolute_mov_instruction_address(
    instructions: Sequence[Instruction],
    *,
    instruction_index: int,
    instruction_addresses: Sequence[int | None],
    instruction_address_counts: Mapping[int, int],
    caller_start: int,
    caller_end: int,
) -> str:
    """Recover one unique, contiguous VC5 split absolute-MOV offset.

    VC5 renders a six-byte ``8B /r disp32`` instruction as five bytes on an
    offset-bearing row and the final byte plus mnemonic on a continuation row.
    ``parse_assembly`` correctly joins the bytes, but the resulting
    ``Instruction.source_line`` is the addressless continuation.  Publish the
    derived relative offset only when both neighboring instruction boundaries,
    the one-byte continuation, and the unique computed address agree exactly.
    Malformed or ambiguous rows remain addressless and therefore fail closed in
    the IAT provenance verifier.
    """
    if not (0 < instruction_index < len(instructions) - 1):
        return ""
    instruction = instructions[instruction_index]
    if _source_instruction_address(instruction):
        return ""
    try:
        body = bytes(int(item, 16) for item in instruction.bytes)
    except (TypeError, ValueError):
        return ""
    continuation_parts = instruction.source_line.strip().split()
    if (
        len(body) != 6
        or body[0] != 0x8B
        or body[1] >> 6 != 0
        or body[1] & 0x07 != 0x05
        or len(continuation_parts) < 2
        or continuation_parts[0] != "00"
        or continuation_parts[1].casefold() != "mov"
        or _instruction_mnemonic(instruction) != "mov"
    ):
        return ""
    address = instruction_addresses[instruction_index]
    previous_address = instruction_addresses[instruction_index - 1]
    previous_length = _exact_instruction_byte_length(
        instructions[instruction_index - 1]
    )
    next_explicit_address = _instruction_runtime_address(
        instructions[instruction_index + 1],
        source="cod",
        caller_start=caller_start,
    )
    if (
        address is None
        or previous_address is None
        or previous_length is None
        or not caller_start <= address < caller_end
        or instruction_address_counts.get(address, 0) != 1
        or previous_address + previous_length != address
        or next_explicit_address != address + len(body)
    ):
        return ""
    return normalize_address(address - caller_start)


def _reviewed_cod_register_definition_address(
    instructions: Sequence[Instruction],
    *,
    instruction_index: int,
    instruction_addresses: Sequence[int | None],
    instruction_address_counts: Mapping[int, int],
    caller_start: int,
    caller_end: int,
    reviewed_absolute_storage_load_bridges: Mapping[
        str, ReviewedAbsoluteStorageLoadBridge
    ],
    reviewed_member_vptr_load_bridges: Mapping[
        str, ReviewedMemberVptrStorageBridge
    ],
    reviewed_iat_register_definition_offsets: frozenset[str],
) -> str:
    """Return a unique explicit, exact split-IAT, or reviewed bridge offset."""
    instruction = instructions[instruction_index]
    address = instruction_addresses[instruction_index]
    relative_address = (
        normalize_address(address - caller_start)
        if address is not None
        else ""
    )
    if (
        address is not None
        and _source_instruction_address(instruction)
        and instruction_address_counts.get(address, 0) == 1
    ):
        return relative_address
    split_address = _exact_cod_split_absolute_mov_instruction_address(
        instructions,
        instruction_index=instruction_index,
        instruction_addresses=instruction_addresses,
        instruction_address_counts=instruction_address_counts,
        caller_start=caller_start,
        caller_end=caller_end,
    )
    if split_address:
        return split_address
    if relative_address in reviewed_iat_register_definition_offsets:
        # A caller-scoped candidate proof may authorize an otherwise exact
        # split MOV whose immediate right neighbor is another wrapped MOV.
        # The proof owns the complete COD/COFF cover, relocation, unique CFG
        # definition, and register lifetime; this path supplies only the
        # already-proved relative definition address to the generic marker.
        return relative_address
    # Reviewed aggregate-load and member-vptr bridges already require exact
    # candidate COFF/COD bytes, operands, relocation-backed storage lineage,
    # unique inferred offsets, and an unclobbered path to the reviewed call.
    # Preserve those independent proof paths for abbreviated COD
    # views; an unreviewed addressless register load remains unresolved.
    if relative_address in {
        *reviewed_absolute_storage_load_bridges,
        *reviewed_member_vptr_load_bridges,
    }:
        return relative_address
    return ""


def _rendered_numeric_branch_target(
    instruction: Instruction,
    *,
    source: str,
    caller_start: int,
) -> int | None:
    matches = ADDRESS_RE.findall(_instruction_operand(instruction))
    if not matches:
        return None
    value = address_value(matches[-1])
    return caller_start + value if source == "cod" else value


_COD_LOCAL_BRANCH_LABEL_RE = re.compile(
    r"(?:(?:short|near)\s+)?(?:"
    r"\$L[0-9A-Za-z_]+|"
    r"\$[A-Za-z_][0-9A-Za-z_]*\$[0-9]+"
    r")",
    re.IGNORECASE,
)


def _exact_cod_local_branch_label(operand: str) -> bool:
    return _COD_LOCAL_BRANCH_LABEL_RE.fullmatch(operand.strip()) is not None


def _exact_local_direct_branch(
    instruction: Instruction,
    *,
    instruction_index: int,
    instruction_addresses: Sequence[int | None],
    instruction_index_by_address: Mapping[int, int],
    source: str,
    caller_start: int,
    caller_end: int,
) -> tuple[str, int] | None:
    """Decode one exact unprefixed local x86 branch.

    Only direct short/near Jcc and JMP encodings participate in forward
    provenance.  Text is not trusted to supply a target, but an available
    numeric rendering must agree with the encoded relative displacement.
    A VC5 COD external REL32 operand has a zero placeholder until link time;
    require an exact local-label or numeric rendering before treating that
    placeholder as caller-local control flow.
    """
    address = instruction_addresses[instruction_index]
    if address is None:
        return None
    rendered_target = _rendered_numeric_branch_target(
        instruction,
        source=source,
        caller_start=caller_start,
    )
    if source == "cod" and rendered_target is None:
        if not _exact_cod_local_branch_label(
            _instruction_operand(instruction)
        ):
            return None
    try:
        body = bytes(int(item, 16) for item in instruction.bytes)
    except (TypeError, ValueError):
        return None
    mnemonic = _instruction_mnemonic(instruction)
    kind: str
    displacement: int
    if (
        len(body) == 2
        and 0x70 <= body[0] <= 0x7F
        and mnemonic in SHORT_JCC_MNEMONICS[body[0] - 0x70]
    ):
        kind = "conditional"
        displacement = struct.unpack("<b", body[1:2])[0]
    elif (
        len(body) == 6
        and body[0] == 0x0F
        and 0x80 <= body[1] <= 0x8F
        and mnemonic in SHORT_JCC_MNEMONICS[body[1] - 0x80]
    ):
        kind = "conditional"
        displacement = struct.unpack("<i", body[2:6])[0]
    elif len(body) == 2 and body[0] == 0xEB and mnemonic == "jmp":
        kind = "unconditional"
        displacement = struct.unpack("<b", body[1:2])[0]
    elif len(body) == 5 and body[0] == 0xE9 and mnemonic == "jmp":
        kind = "unconditional"
        displacement = struct.unpack("<i", body[1:5])[0]
    else:
        return None
    target = address + len(body) + displacement
    if not caller_start <= target < caller_end:
        return None
    target_index = instruction_index_by_address.get(target)
    if target_index is None:
        return None
    if rendered_target is not None and rendered_target != target:
        return None
    return kind, target_index


def _exact_return_terminates(instruction: Instruction) -> bool:
    mnemonic = _instruction_mnemonic(instruction)
    if mnemonic not in {"ret", "retn"}:
        return False
    try:
        body = bytes(int(item, 16) for item in instruction.bytes)
    except (TypeError, ValueError):
        return False
    operand = _instruction_operand(instruction).strip().lower()
    if body == b"\xc3":
        return operand in {"", "0", "0x0"}
    if len(body) != 3 or body[0] != 0xC2:
        return False
    try:
        rendered_immediate = _parse_unsigned_assembly_integer(operand)
    except ValueError:
        return False
    return rendered_immediate == struct.unpack("<H", body[1:3])[0]


def _empty_register_state() -> dict[str, str]:
    return {register: "" for register in REGISTER_STATE_NAMES}


def _register_state_snapshot(registers: Mapping[str, str]) -> dict[str, str]:
    return {
        register: str(registers.get(register, "") or "")
        for register in REGISTER_STATE_NAMES
    }


def _merge_register_states(
    predecessors: Sequence[Mapping[str, str]],
    *,
    reviewed_iat_register_joins: frozenset[tuple[str, str]] = frozenset(),
) -> dict[str, str]:
    merged = _empty_register_state()
    for register in REGISTER_STATE_NAMES:
        values = {
            str(predecessor.get(register, "") or "")
            for predecessor in predecessors
        }
        if len(values) == 1:
            value = next(iter(values))
            if value:
                merged[register] = value
            continue
        exact_iat_definitions = [
            re.fullmatch(
                r"exact-iat-load\("
                r"(?P<register>e(?:ax|bx|cx|dx|si|di|bp)),"
                r"0x[0-9a-f]+,"
                r"(?P<identity>iat:[^)]+)\)",
                value,
            )
            for value in values
        ]
        if (
            values
            and "" not in values
            and all(match is not None for match in exact_iat_definitions)
            and {
                match.group("register")
                for match in exact_iat_definitions
                if match is not None
            }
            == {register}
            and len(
                {
                    match.group("identity")
                    for match in exact_iat_definitions
                    if match is not None
                }
            )
            == 1
        ):
            identity = next(
                match.group("identity")
                for match in exact_iat_definitions
                if match is not None
            )
            if (register, identity) not in reviewed_iat_register_joins:
                continue
            # Every incoming path independently loads the same immutable IAT
            # identity into the same register.  Preserve that path-complete
            # fact without pretending the reaching definition has one site.
            merged[register] = f"exact-iat-join({register},{identity})"
            continue
        non_null = values - {"null"}
        if (
            len(values) == 2
            and len(non_null) == 1
            and "" not in values
        ):
            value = next(iter(non_null))
            if value.startswith("call-result(") and value.endswith(")"):
                merged[register] = f"nullable({value})"
    return merged


def _is_terminal_local_frame_teardown(
    instructions: Sequence[Instruction],
    *,
    call_index: int,
    cleanup_index: int,
    cleanup_bytes: int,
) -> bool:
    """Prove one ADD ESP is a terminal local-frame reversal, not call cleanup.

    The proof stays instruction-local and source-independent: the adjustment
    must reverse one unique earlier ``sub esp, N`` frame allocation, immediately
    follow an explicit EAX return-value write, and immediately precede the
    function return.  Missing or competing frame facts leave the ADD classified
    as caller cleanup.
    """

    if cleanup_index <= call_index or cleanup_index + 1 >= len(instructions):
        return False

    if _instruction_mnemonic(instructions[cleanup_index + 1]) not in {
        "ret", "retn"
    }:
        return False

    adjacent = list(instructions[call_index + 1 : cleanup_index])
    if (
        not adjacent
        or _written_full_register(adjacent[-1]) != "eax"
        or not _instruction_may_clobber_register(adjacent[-1], "eax")
    ):
        return False

    matching_allocations: list[int] = []
    for instruction_index, instruction in enumerate(
        instructions[:call_index]
    ):
        match = STACK_ALLOCATION_RE.fullmatch(
            instruction.raw_text.strip().lower()
        )
        if (
            match is not None
            and _parse_unsigned_assembly_integer(match.group(1))
            == cleanup_bytes
        ):
            matching_allocations.append(instruction_index)
    if len(matching_allocations) != 1:
        return False

    allocation_index = matching_allocations[0]
    return not any(
        (match := STACK_CLEANUP_RE.fullmatch(
            instruction.raw_text.strip().lower()
        ))
        is not None
        and _parse_unsigned_assembly_integer(match.group(1))
        == cleanup_bytes
        for instruction in instructions[allocation_index + 1 : call_index]
    )


def _cleanup_after(instructions: Sequence[Instruction], index: int) -> int | None:
    """Attribute the first straight-line caller cleanup to one call.

    VC5 may schedule independent register work between a cdecl call and its
    ``add esp, N``. Stop before any later invocation, control-flow transfer, or
    competing stack mutation so cleanup cannot be stolen across semantic
    boundaries.
    """
    for instruction_index, instruction in enumerate(
        instructions[index + 1 :], start=index + 1
    ):
        text = instruction.raw_text.strip().lower()
        match = STACK_CLEANUP_RE.fullmatch(text)
        if match:
            cleanup_bytes = _parse_unsigned_assembly_integer(match.group(1))
            if _is_terminal_local_frame_teardown(
                instructions,
                call_index=index,
                cleanup_index=instruction_index,
                cleanup_bytes=cleanup_bytes,
            ):
                return None
            return cleanup_bytes
        mnemonic = _instruction_mnemonic(instruction)
        if (
            mnemonic == "call"
            or mnemonic.startswith("j")
            or mnemonic in {"ret", "retn", "iret", "loop", "loope", "loopne", "jecxz"}
        ):
            return None
        if mnemonic in {
            "push",
            "pop",
            "pusha",
            "pushad",
            "popa",
            "popad",
            "enter",
            "leave",
        }:
            return None
        operands = [
            item.strip().lower()
            for item in _instruction_operand(instruction).split(",")
        ]
        if operands and (
            operands[0] == "esp"
            or (mnemonic == "xchg" and "esp" in operands)
        ):
            return None
    return None


def _guarded_switch_entry_count(
    instructions: Sequence[Instruction],
    dispatch_index: int,
) -> int | None:
    operand = _instruction_operand(instructions[dispatch_index]).lower()
    indexed = re.search(
        r"\[\s*[^\]]*\b(?P<index>e?[abcd]x|e?[sd]i|e?[sb]p)\s*\*\s*4\b[^\]]*\]",
        operand,
    )
    if indexed is None:
        return None
    index_register = indexed.group("index")
    for compare_index in range(dispatch_index - 1, max(-1, dispatch_index - 9), -1):
        compare = re.fullmatch(
            rf"cmp\s+{re.escape(index_register)}\s*,\s*(0x[0-9a-f]+|\d+)",
            instructions[compare_index].raw_text.strip().lower(),
        )
        if compare is None:
            continue
        branches = {
            _instruction_mnemonic(item)
            for item in instructions[compare_index + 1 : dispatch_index]
        }
        maximum = _parse_unsigned_assembly_integer(compare.group(1))
        if "ja" in branches:
            return maximum + 1
        if "jae" in branches:
            return maximum
        return None
    return None


def _hexdump_bytes(text: str) -> bytes:
    result = bytearray()
    for line in text.splitlines():
        parts = line.strip().split()
        if (
            not parts
            or re.fullmatch(
                r"[0-9a-fA-F]{5,8}", parts[0].rstrip(":")
            ) is None
        ):
            continue
        for token in parts[1:]:
            if re.fullmatch(r"[0-9a-fA-F]{2}", token) is None:
                break
            result.append(int(token, 16))
    return bytes(result)


def _classifier_switch_entry_count(
    instructions: Sequence[Instruction],
    dispatch_index: int,
    *,
    caller_start: int,
    caller_end: int,
    bridge: BinaryNinjaBridge,
) -> int | None:
    """Prove the bounded VC5 byte-classifier indexed-JMP shape.

    The established shape is ``cmp base,31`` with a 32-byte classifier and
    five-entry table.  zInterp additionally has one exact ``cmp eax,0x2c`` /
    ECX classifier at 0x4c543c with an adjacent 20-entry table at 0x4c53ec.
    zVideo_dd::ReportError has one finite ``cmp eax,0x3c`` / EDX classifier at
    0x4ae274 with an adjacent 34-entry table at 0x4ae1ec.  In all cases the
    unsigned guard supplies the classifier length and every classifier value
    selects a table entry.  The two finite extensions also prove exact bytes,
    complete xrefs, and unique caller-local table/default targets.  This
    recognizes CFG only; it publishes no invocation, target identity, or
    storage fact.
    """
    if dispatch_index < 4:
        return None
    dispatch = instructions[dispatch_index]
    operand = _instruction_operand(dispatch).strip().lower()
    match = re.fullmatch(
        r"(?:dword(?:ptr)?)?\["
        r"(?P<index>e(?:ax|cx|dx|bx|bp|si|di))\*4\+"
        r"(?P<table>0x[0-9a-f]+)\]",
        re.sub(r"\s+", "", operand),
    )
    if match is None:
        return None
    index_register = match.group("index")
    register_code = {
        "eax": 0, "ecx": 1, "edx": 2, "ebx": 3,
        "ebp": 5, "esi": 6, "edi": 7,
    }[index_register]
    try:
        dispatch_body = bytes(int(item, 16) for item in dispatch.bytes)
    except (TypeError, ValueError):
        return None
    expected_sib = (2 << 6) | (register_code << 3) | 5
    table_address = address_value(match.group("table"))
    if (
        _instruction_mnemonic(dispatch) != "jmp"
        or len(dispatch_body) != 7
        or dispatch_body[:2] != b"\xff\x24"
        or dispatch_body[2] != expected_sib
        or struct.unpack_from("<I", dispatch_body, 3)[0] != table_address
    ):
        return None

    load = instructions[dispatch_index - 1]
    zero = instructions[dispatch_index - 2]
    guard_branch = instructions[dispatch_index - 3]
    guard_compare = instructions[dispatch_index - 4]
    low_register = {
        "eax": "al", "ecx": "cl", "edx": "dl", "ebx": "bl",
    }.get(index_register)
    if low_register is None or not _is_exact_self_xor_zero(
        zero, destination=index_register
    ):
        return None
    try:
        load_body = bytes(int(item, 16) for item in load.bytes)
    except (TypeError, ValueError):
        return None
    load_operands = _instruction_operand(load).split(",", 1)
    if (
        _instruction_mnemonic(load) != "mov"
        or len(load_body) != 6
        or load_body[0] != 0x8A
        or load_body[1] >> 6 != 2
        or ((load_body[1] >> 3) & 7) != register_code
        or (load_body[1] & 7) == 4
        or len(load_operands) != 2
        or load_operands[0].strip().lower() != low_register
    ):
        return None
    classifier_address = struct.unpack_from("<I", load_body, 2)[0]
    base_code = load_body[1] & 7
    base_register = (
        "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi",
    )[base_code]
    try:
        compare_body = bytes(int(item, 16) for item in guard_compare.bytes)
    except (TypeError, ValueError):
        return None
    compare_operands = [
        item.strip().lower()
        for item in _instruction_operand(guard_compare).split(",")
    ]
    try:
        guard_maximum = _parse_unsigned_assembly_integer(compare_operands[1])
    except (IndexError, ValueError):
        return None
    classifier_length = guard_maximum + 1
    compare_encoding = compare_body == bytes(
        (0x83, 0xF8 | base_code, guard_maximum)
    )
    runtime_addresses = _instruction_runtime_addresses(
        instructions,
        source="bn",
        caller_start=caller_start,
    )
    address_counts: dict[int, int] = {}
    for runtime_address in runtime_addresses:
        if runtime_address is not None:
            address_counts[runtime_address] = (
                address_counts.get(runtime_address, 0) + 1
            )
    index_by_address = {
        runtime_address: index
        for index, runtime_address in enumerate(runtime_addresses)
        if runtime_address is not None
        and address_counts.get(runtime_address) == 1
    }
    exact_branch = _exact_local_direct_branch(
        guard_branch,
        instruction_index=dispatch_index - 3,
        instruction_addresses=runtime_addresses,
        instruction_index_by_address=index_by_address,
        source="bn",
        caller_start=caller_start,
        caller_end=caller_end,
    )
    rendered_addresses = ADDRESS_RE.findall(load_operands[1])
    if (
        _instruction_mnemonic(guard_compare) != "cmp"
        or len(compare_operands) != 2
        or compare_operands[0] != base_register
        or classifier_length not in {32, 45, 61}
        or not compare_encoding
        or _instruction_mnemonic(guard_branch) != "ja"
        or exact_branch is None
        or exact_branch[0] != "conditional"
        or exact_branch[1] <= dispatch_index
        or len(rendered_addresses) != 1
        or address_value(rendered_addresses[0]) != classifier_address
        or not caller_start <= table_address < classifier_address
        or classifier_address + classifier_length > caller_end
    ):
        return None
    exact_zinterp_shape = (
        classifier_length == 45
        and caller_start == address_value("0x4c20a0")
        and caller_end == address_value("0x4c5480")
        and base_register == "eax"
        and index_register == "ecx"
        and table_address == address_value("0x4c53ec")
        and classifier_address == address_value("0x4c543c")
    )
    exact_zvid_reporterror_shape = (
        classifier_length == 61
        and caller_start == address_value("0x4ad6a0")
        and caller_end == address_value("0x4ae380")
        and tuple(
            runtime_addresses[dispatch_index - offset]
            for offset in (4, 3, 2, 1, 0)
        )
        == (0x4ADC9C, 0x4ADC9F, 0x4ADCA5, 0x4ADCA7, 0x4ADCAD)
        and base_register == "eax"
        and index_register == "edx"
        and table_address == address_value("0x4ae1ec")
        and classifier_address == address_value("0x4ae274")
        and exact_branch[1] == index_by_address.get(0x4AE156)
    )
    if (
        classifier_length == 45 and not exact_zinterp_shape
        or classifier_length == 61 and not exact_zvid_reporterror_shape
    ):
        return None
    classifier = _hexdump_bytes(
        bridge.hexdump(
            normalize_address(classifier_address),
            classifier_length,
        )
    )
    if len(classifier) != classifier_length:
        return None
    exact_zvid_classifier = (
        bytes(range(0x12))
        + b"\x21"
        + bytes(range(0x12, 0x20))
        + b"\x21" * 27
        + b"\x20"
    )
    entry_count = max(classifier, default=0) + 1
    if (
        entry_count
        != (
            20
            if exact_zinterp_shape
            else 34 if exact_zvid_reporterror_shape else 5
        )
        or set(classifier) != set(range(entry_count))
        or table_address + entry_count * 4 != classifier_address
        or exact_zvid_reporterror_shape
        and classifier != exact_zvid_classifier
    ):
        return None
    if exact_zinterp_shape or exact_zvid_reporterror_shape:
        raw_table = _hexdump_bytes(
            bridge.hexdump(normalize_address(table_address), entry_count * 4)
        )
        if len(raw_table) != entry_count * 4:
            return None
        table_targets = struct.unpack(f"<{entry_count}I", raw_table)
        table_target_indices = tuple(
            index_by_address.get(target, -1) for target in table_targets
        )
        default_index = exact_branch[1]
        exact_zvid_targets = (
            0x4ADE5D, 0x4ADD36, 0x4ADCF5, 0x4ADD95, 0x4ADE26,
            0x4ADDA4, 0x4ADE35, 0x4ADCDC, 0x4ADD6D, 0x4ADDAE,
            0x4ADD1D, 0x4ADD0E, 0x4ADDCC, 0x4ADDD6, 0x4ADCB4,
            0x4ADD5E, 0x4ADD86, 0x4ADE1C, 0x4ADD45, 0x4ADDE5,
            0x4ADD04, 0x4ADDF4, 0x4ADCCD, 0x4ADDFE, 0x4ADCBE,
            0x4ADD7C, 0x4ADE4E, 0x4ADD2C, 0x4ADE0D, 0x4ADE44,
            0x4ADDBD, 0x4ADD54, 0x4ADCE6, 0x4AE156,
        )
        if (
            len(set(table_targets)) != entry_count
            or any(
                target_index <= dispatch_index
                for target_index in table_target_indices
            )
            or default_index <= dispatch_index
            or exact_zinterp_shape and default_index in table_target_indices
            or exact_zvid_reporterror_shape
            and table_targets != exact_zvid_targets
        ):
            return None
        if exact_zvid_reporterror_shape:
            get_json = getattr(bridge, "get_json", None)
            if not callable(get_json):
                return None
            try:
                classifier_xrefs = get_json(
                    "getXrefsTo", address="0x4ae274", limit=100000
                )
                table_xrefs = get_json(
                    "getXrefsTo", address="0x4ae1ec", limit=100000
                )
            except (BridgeError, OSError, RuntimeError, ValueError):
                return None
            classifier_code, classifier_data, classifier_complete = (
                _bn_inbound_xref_items(classifier_xrefs)
            )
            table_code, table_data, table_complete = _bn_inbound_xref_items(
                table_xrefs
            )
            classifier_sources = Counter(
                _bn_xref_address(
                    row,
                    "source_address",
                    "source_addr",
                    "from_address",
                    "address",
                )
                for row in classifier_code
            )
            table_sources = Counter(
                _bn_xref_address(
                    row,
                    "source_address",
                    "source_addr",
                    "from_address",
                    "address",
                )
                for row in table_code
            )
            if (
                not classifier_complete
                or not table_complete
                or classifier_data
                or table_data
                or classifier_sources
                != {"0x4adca7": 1, "0x4adcad": 1}
                or table_sources != {"0x4adcad": 1}
            ):
                return None
    return entry_count


def retail_local_switch_targets(
    instructions: Sequence[Instruction],
    *,
    caller_start: str,
    caller_end_exclusive: str,
    bridge: BinaryNinjaBridge,
) -> dict[int, tuple[int, ...]]:
    """Return exact caller-local BN jump-table edges.

    A table participates only when its guarded cardinality is exact, every
    immutable table entry names one unique instruction start in the caller,
    and every target is forward of the dispatch.  The forward-only constraint
    keeps the single-pass provenance merge fail-closed.
    """
    start = address_value(caller_start)
    end = address_value(caller_end_exclusive)
    instruction_addresses = _instruction_runtime_addresses(
        instructions,
        source="bn",
        caller_start=start,
    )
    address_counts: dict[int, int] = {}
    for address in instruction_addresses:
        if address is not None and start <= address < end:
            address_counts[address] = address_counts.get(address, 0) + 1
    instruction_index_by_address = {
        address: index
        for index, address in enumerate(instruction_addresses)
        if (
            address is not None
            and start <= address < end
            and address_counts.get(address) == 1
        )
    }
    local: dict[int, tuple[int, ...]] = {}
    for index, instruction in enumerate(instructions):
        if _instruction_mnemonic(instruction) != "jmp" or "[" not in _instruction_operand(
            instruction
        ):
            continue
        count = _guarded_switch_entry_count(instructions, index)
        if count is None:
            count = _classifier_switch_entry_count(
                instructions,
                index,
                caller_start=start,
                caller_end=end,
                bridge=bridge,
            )
        if count is None or count < 1:
            continue
        addresses = ADDRESS_RE.findall(_instruction_operand(instruction))
        if len(addresses) != 1:
            continue
        table_address = normalize_address(addresses[0])
        raw = _hexdump_bytes(bridge.hexdump(table_address, count * 4))
        if len(raw) != count * 4:
            continue
        targets = struct.unpack(f"<{count}I", raw)
        target_indices = tuple(
            instruction_index_by_address.get(target, -1) for target in targets
        )
        if all(target_index > index for target_index in target_indices):
            local[index] = target_indices
    return local


def retail_local_switch_indices(
    instructions: Sequence[Instruction],
    *,
    caller_start: str,
    caller_end_exclusive: str,
    bridge: BinaryNinjaBridge,
) -> frozenset[int]:
    """Return exact local dispatches, including edge-incomplete tables.

    ``retail_local_switch_targets`` remains the stricter complete-edge view.
    This index view additionally classifies an exact absolute indexed table
    whose base lies inside the selected caller.  It grants no successor edge
    and therefore cannot manufacture downstream provenance.
    """
    start = address_value(caller_start)
    end = address_value(caller_end_exclusive)
    complete = retail_local_switch_targets(
            instructions,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
            bridge=bridge,
    )
    local = set(complete)
    instruction_addresses = _instruction_runtime_addresses(
        instructions,
        source="bn",
        caller_start=start,
    )
    address_counts: dict[int, int] = {}
    for address in instruction_addresses:
        if address is not None and start <= address < end:
            address_counts[address] = address_counts.get(address, 0) + 1
    local.update(
        index
        for index, instruction in enumerate(instructions)
        if (
            instruction_addresses[index] is not None
            and start <= int(instruction_addresses[index]) < end
            and address_counts.get(instruction_addresses[index], 0) == 1
            and _exact_local_indexed_jump_table_address(
                instruction,
                caller_start=start,
                caller_end=end,
            )
            is not None
        )
    )
    return frozenset(local)


def _pointer_vector_destroy_provider_identity(
    name: str,
    *,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    compiler_generated_bridges: Mapping[str, str],
    allow_proven_value_noop: bool = False,
) -> str:
    """Resolve one exact no-op vector ``_Destroy`` ABI to reviewed retail.

    Pointer elements retain their established decoration-level route because
    destroying a pointer range is intrinsically a no-op.  A value element is
    eligible only after the caller-local COFF bridge proves the complete VC5
    no-op COMDAT, or when that proof is already present in the reviewed
    compiler/provider bridge map.  Thus a value-vector decoration alone never
    acquires the physical provider identity.
    """

    if not name.startswith(MSVC_VECTOR_DESTROY_PREFIX):
        return ""
    if name == HUD_PANEL_LAYOUT_VECTOR_DESTROY_SYMBOL:
        # This specialization destroys nontrivial values and therefore cannot
        # share the pointer/no-op supplier.  Its exact same-object sentinel is
        # resolved only by the later comparison-scoped retail COMDAT gate.
        return ""
    match = MSVC_VECTOR_NOOP_DESTROY_RE.fullmatch(name)
    if match is None:
        raise ValueError(
            f"ABI-incompatible vector destroy decoration {name!r}"
        )
    is_pointer_element = match.group("element").startswith("P")
    compiler_identity = compiler_generated_bridges.get(name)
    if (
        not is_pointer_element
        and not allow_proven_value_noop
        and compiler_identity is None
    ):
        return ""
    suppliers = indexes.pointer_vector_destroy_providers
    if not suppliers:
        raise ValueError(
            f"missing reviewed pointer-vector destroy provider for {name!r}"
        )
    if len(suppliers) != 1:
        raise ValueError(
            f"ambiguous reviewed pointer-vector destroy provider for {name!r}"
        )
    supplier = suppliers[0]
    if (
        supplier.stack_cleanup_bytes != 8
        or MSVC_POINTER_VECTOR_DESTROY_PROVIDER_RE.fullmatch(
            supplier.catalog_symbol
        )
        is None
        or indexes.by_address.get(supplier.address) != supplier.identity
        or supplier.identity not in indexes.provider_ids
    ):
        raise ValueError(
            "ABI-incompatible reviewed pointer-vector destroy provider "
            f"for {name!r}"
        )

    indexed = indexes.by_candidate_name.get(name)
    if indexed is not None and indexed != supplier.identity:
        raise ValueError(
            f"conflicting indexed pointer-vector destroy identity for {name!r}"
        )
    if (
        compiler_identity is not None
        and compiler_identity != supplier.identity
    ):
        raise ValueError(
            f"conflicting compiler pointer-vector destroy identity for {name!r}"
        )
    raw_matches = bridge_names.get(name)
    if raw_matches is not None:
        matches = (
            list(raw_matches)
            if isinstance(
                raw_matches,
                (list, tuple, set, frozenset),
            )
            else [raw_matches]
        )
        try:
            addresses = {
                normalize_address(str(getattr(item, "address", "")))
                for item in matches
                if getattr(item, "address", "")
            }
        except ProgressError as exc:
            raise ValueError(
                f"conflicting BN pointer-vector destroy identity for {name!r}"
            ) from exc
        if addresses != {supplier.address}:
            raise ValueError(
                f"conflicting BN pointer-vector destroy identity for {name!r}"
            )
    return supplier.identity


def _hud_cmd_binding_ptr_vector_erase_provider_identity(
    name: str,
    *,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    compiler_generated_bridges: Mapping[str, str],
) -> str:
    """Resolve only the reviewed HudCmdBindingEntry pointer-vector erase ABI."""

    if name != HUD_CMD_BINDING_PTR_VECTOR_ERASE_SYMBOL:
        return ""
    supplier = indexes.hud_cmd_binding_ptr_vector_erase_provider
    if supplier is None:
        raise ValueError(
            "missing reviewed physical HudCmdBindingEntry pointer-vector "
            f"erase provider for {name!r}"
        )
    if (
        supplier.candidate_name != HUD_CMD_BINDING_PTR_VECTOR_ERASE_SYMBOL
        or supplier.address != HUD_CMD_BINDING_PTR_VECTOR_ERASE_ADDRESS
        or supplier.identity != HUD_CMD_BINDING_PTR_VECTOR_ERASE_IDENTITY
        or supplier.stack_cleanup_bytes != 8
        or indexes.by_address.get(supplier.address) != supplier.identity
        or supplier.identity not in indexes.provider_ids
    ):
        raise ValueError(
            "ABI-incompatible reviewed physical HudCmdBindingEntry "
            f"pointer-vector erase provider for {name!r}"
        )
    indexed = indexes.by_candidate_name.get(name)
    if indexed is not None and indexed != supplier.identity:
        raise ValueError(
            "conflicting indexed HudCmdBindingEntry pointer-vector erase "
            f"identity for {name!r}"
        )
    compiler_identity = compiler_generated_bridges.get(name)
    if (
        compiler_identity is not None
        and compiler_identity != supplier.identity
    ):
        raise ValueError(
            "conflicting compiler HudCmdBindingEntry pointer-vector erase "
            f"identity for {name!r}"
        )
    raw_matches = bridge_names.get(name)
    if raw_matches is not None:
        matches = (
            list(raw_matches)
            if isinstance(
                raw_matches,
                (list, tuple, set, frozenset),
            )
            else [raw_matches]
        )
        try:
            addresses = [
                normalize_address(str(getattr(item, "address", "")))
                for item in matches
                if getattr(item, "address", "")
            ]
        except ProgressError as exc:
            raise ValueError(
                "conflicting BN HudCmdBindingEntry pointer-vector erase "
                f"identity for {name!r}"
            ) from exc
        if addresses != [supplier.address]:
            raise ValueError(
                "conflicting BN HudCmdBindingEntry pointer-vector erase "
                f"identity for {name!r}"
            )
    return supplier.identity


def _scalar_deleting_destructor_identity(
    name: str,
    *,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    compiler_generated_bridges: Mapping[str, str],
) -> str:
    """Resolve exact natural VC5 scalar deletion to reviewed retail identity."""
    if not name.startswith(MSVC_SCALAR_DELETING_DESTRUCTOR_PREFIX):
        return ""
    class_match = MSVC_SCALAR_DELETING_DESTRUCTOR_CLASS_RE.match(name)
    if class_match is None:
        return ""
    encoded_class = class_match.group("class_scope")
    class_identity = "::".join(reversed(encoded_class.split("@")))
    if MSVC_VIRTUAL_SCALAR_DELETING_DESTRUCTOR_RE.fullmatch(name):
        return ""
    suppliers = [
        supplier
        for supplier in indexes.scalar_deleting_destructors
        if supplier.class_identity == class_identity
    ]
    if len(suppliers) > 1:
        raise ValueError(
            "ambiguous reviewed scalar-deleting-destructor identity "
            f"for {name!r}"
        )
    if not suppliers:
        blocker = indexes.scalar_deleting_destructor_blockers.get(
            class_identity
        )
        if blocker:
            raise ValueError(f"{blocker} for {name!r}")
        return ""
    parsed = _nonvirtual_scalar_deleting_destructor_class(name)
    if parsed is None:
        raise ValueError(
            f"ABI-incompatible scalar-deleting-destructor decoration {name!r}"
        )
    supplier = suppliers[0]
    if (
        not supplier.identity
        or indexes.by_address.get(supplier.address) != supplier.identity
    ):
        raise ValueError(
            f"stale scalar-deleting-destructor identity for {name!r}"
        )
    indexed = indexes.by_candidate_name.get(name)
    if (
        indexed is not None
        and indexed != supplier.identity
        and not (
            indexed == ""
            and name
            in indexes.scalar_deleting_destructor_legacy_fallback_names
        )
    ):
        raise ValueError(
            f"conflicting indexed scalar-deleting-destructor identity for {name!r}"
        )
    compiler_identity = compiler_generated_bridges.get(name)
    if (
        compiler_identity is not None
        and compiler_identity != supplier.identity
    ):
        raise ValueError(
            f"conflicting compiler scalar-deleting-destructor identity for {name!r}"
        )
    raw_matches = bridge_names.get(name)
    if raw_matches is not None:
        matches = (
            list(raw_matches)
            if isinstance(raw_matches, (list, tuple, set, frozenset))
            else [raw_matches]
        )
        try:
            addresses = {
                normalize_address(str(getattr(item, "address", "")))
                for item in matches
                if getattr(item, "address", "")
            }
        except ProgressError as exc:
            raise ValueError(
                f"conflicting BN scalar-deleting-destructor identity for {name!r}"
            ) from exc
        if addresses != {supplier.address}:
            raise ValueError(
                f"conflicting BN scalar-deleting-destructor identity for {name!r}"
            )
    return supplier.identity


ZSND_RELEASE_UNKNOWN_COFF_NAME = (
    "?ReleaseUnknown@?%"
    + str(
        REPO_ROOT / "src" / "GameZRecoil" / "zSound" / "zsnd_init.cpp"
    )
    + "921116370@zSndBackend@@YIXAAPAX@Z"
)
ZSND_RELEASE_UNKNOWN_COD_NAME = (
    ZSND_RELEASE_UNKNOWN_COFF_NAME.replace("@?%", "@?", 1)
)
ZSND_RELEASE_UNKNOWN_SOURCE_PATH = (
    REPO_ROOT / "src" / "GameZRecoil" / "zSound" / "zsnd_init.cpp"
)
_ZSND_RELEASE_UNKNOWN_COFF_NAME_RE = re.compile(
    re.escape("?ReleaseUnknown@?%" + str(ZSND_RELEASE_UNKNOWN_SOURCE_PATH))
    + r"[0-9]+@zSndBackend@@YIXAAPAX@Z"
)
ZSND_RELEASE_UNKNOWN_BODY = bytes.fromhex(
    "56 8b f1 8b 06 85 c0 74 0c 8b 08 50 ff 51 08 c7 "
    "06 00 00 00 00 5e c3 90 90 90 90 90 90 90 90 90"
)


def _is_zsnd_release_unknown_coff_name(value: str) -> bool:
    """Recognize the exact VC5 TU-local ReleaseUnknown identity grammar."""

    return _ZSND_RELEASE_UNKNOWN_COFF_NAME_RE.fullmatch(value) is not None

_COD_SPACE_BEARING_DIRECT_TARGET_RE = re.compile(
    r"(?P<head>\?[^\s]+?@\?)"
    r"(?P<source>[A-Za-z]:[\\/][^@\r\n]*[ \t][^@\r\n]*"
    r"\.(?:c|cc|cpp|cxx)[0-9]+)"
    r"(?P<scope>@@|@[A-Za-z_?$][A-Za-z0-9_?$]*@@)"
    r"(?P<suffix>[A-Za-z0-9_?$@]+Z)",
    re.IGNORECASE,
)
_COD_SPACE_BEARING_DIRECT_TARGET_COMMENT_RE = re.compile(
    r"(?P<head>\?[^\s]+?@\?)%"
    r"(?P<source>[A-Za-z]:[\\/][^@\r\n]*[ \t][^@\r\n]*"
    r"\.(?:c|cc|cpp|cxx)[0-9]+)"
    r"(?P<scope>@@|@[A-Za-z_?$][A-Za-z0-9_?$]*@@)"
    r"(?P<suffix>[A-Za-z0-9_?$@]+Z)",
    re.IGNORECASE,
)


def _cod_space_bearing_direct_target(
    operand: str,
    source_line: str,
) -> str | None:
    """Return one exact VC5 COFF identity for a space-bearing COD target."""

    candidate = operand.strip()
    if not candidate.startswith("?"):
        return None
    has_space = any(character.isspace() for character in candidate)
    has_drive_scope = re.search(
        r"@\?[A-Za-z]:[\\/]", candidate, re.IGNORECASE
    ) is not None
    if not has_space:
        if has_drive_scope and not candidate.endswith("Z"):
            raise ValueError(
                "invalid or truncated COD space-bearing decorated call "
                f"target operand {operand!r}"
            )
        return None
    operand_match = _COD_SPACE_BEARING_DIRECT_TARGET_RE.fullmatch(candidate)
    if operand_match is None:
        raise ValueError(
            "invalid or ambiguous COD space-bearing decorated call target "
            f"operand {operand!r}"
        )
    source_prefix, separator, comment = source_line.rpartition(" ; ")
    if (
        not separator
        or not source_prefix.rstrip().endswith(candidate)
        or source_prefix.rstrip().count(candidate) != 1
    ):
        raise ValueError(
            "COD space-bearing decorated call target lacks one exact "
            f"source-line termination for {operand!r}"
        )
    comment_match = _COD_SPACE_BEARING_DIRECT_TARGET_COMMENT_RE.fullmatch(
        comment.strip()
    )
    if comment_match is None:
        raise ValueError(
            "COD space-bearing decorated call target lacks one exact "
            f"percent-marked identity comment for {operand!r}"
        )
    canonical_coff_name = comment_match.group(0)
    if (
        canonical_coff_name
        != (
            f"{operand_match.group('head')}%"
            f"{operand_match.group('source')}"
            f"{operand_match.group('scope')}"
            f"{operand_match.group('suffix')}"
        )
        or _vc5_compiler_normalized_cod_proc_symbol(canonical_coff_name)
        != candidate
    ):
        raise ValueError(
            "COD space-bearing decorated call target operand and "
            "percent-marked canonical COFF identity do not agree exactly: "
            f"{operand!r}"
        )
    return canonical_coff_name


def _canonical_direct_identity(
    operand: str,
    *,
    source: str,
    caller_identity: str,
    caller_start: int,
    caller_end: int,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    compiler_generated_bridges: Mapping[str, str],
    call_site_address: str | int | None = None,
    call_site_unique: bool | None = None,
    retail_call_site_address: str | int | None = None,
    cod_source_line: str = "",
) -> tuple[str, str]:
    if "__imp_" in operand:
        match = DECORATED_RE.search(operand)
        if match is None:
            raise ValueError(f"unresolved IAT identity in {operand!r}")
        return "iat", f"iat:{match.group(0).removeprefix('__imp_')}"
    address_matches = ADDRESS_RE.findall(operand)
    reviewed_import_thunk: tuple[str, str] | None = None
    if source == "bn" and call_site_address is not None:
        call_site = normalize_address(call_site_address)
        reviewed_import_thunk = (
            indexes.reviewed_direct_import_thunk_by_call_site.get(call_site)
        )
        exact_local_import_thunk = (
            indexes.reviewed_exact_local_import_thunk_by_call_site.get(
                call_site
            )
        )
        if exact_local_import_thunk is not None:
            if (
                exact_local_import_thunk != reviewed_import_thunk
                or not exact_local_import_thunk[1].startswith("iat:")
            ):
                raise ValueError(
                    f"exact local import-thunk selector {call_site} conflicts "
                    "with its composed IAT identity"
                )
            return "iat", exact_local_import_thunk[1]
        if reviewed_import_thunk is not None and not address_matches:
            expected_thunk_address, target_identity = reviewed_import_thunk
            friendly_name = re.sub(
                r"^(?:(?:near|far)\s+)?(?:ptr\s+)?",
                "",
                operand.strip(),
                flags=re.IGNORECASE,
            ).strip()
            raw_matches = bridge_names.get(friendly_name)
            matches = (
                list(raw_matches)
                if isinstance(raw_matches, (list, tuple, set, frozenset))
                else ([raw_matches] if raw_matches is not None else [])
            )
            try:
                addresses = {
                    normalize_address(str(getattr(item, "address", "")))
                    for item in matches
                    if getattr(item, "address", "")
                }
            except ProgressError as exc:
                raise ValueError(
                    f"direct import-thunk selector {call_site} has malformed "
                    "friendly-name authority"
                ) from exc
            identity_kind = (
                "iat"
                if target_identity.startswith("iat:")
                else (
                    "provider"
                    if indexes.by_address.get(expected_thunk_address)
                    == target_identity
                    and target_identity in indexes.provider_ids
                    else ""
                )
            )
            if addresses != {expected_thunk_address} or not identity_kind:
                raise ValueError(
                    f"direct import-thunk selector {call_site} does not join "
                    f"friendly target {friendly_name!r} to "
                    f"{expected_thunk_address}"
                )
            return identity_kind, target_identity
    if address_matches:
        address = normalize_address(address_matches[-1])
        value = address_value(address)
        if caller_start <= value < caller_end:
            return "self", caller_identity
        if source == "bn":
            if call_site_address is not None:
                call_site = normalize_address(call_site_address)
                import_thunk = reviewed_import_thunk
                if import_thunk is not None:
                    expected_thunk_address, target_identity = import_thunk
                    identity_kind = (
                        "iat"
                        if target_identity.startswith("iat:")
                        else (
                            "provider"
                            if indexes.by_address.get(expected_thunk_address)
                            == target_identity
                            and target_identity in indexes.provider_ids
                            else ""
                        )
                    )
                    if expected_thunk_address != address or not identity_kind:
                        raise ValueError(
                            f"direct import-thunk selector {call_site} expected "
                            f"physical target {expected_thunk_address}, found "
                            f"{address}"
                        )
                    return identity_kind, target_identity
                selected = indexes.reviewed_authored_icf_by_call_site.get(call_site)
                if selected is not None:
                    expected_physical_address, logical_identity = selected
                    if expected_physical_address != address:
                        raise ValueError(
                            f"authored ICF retail call selector {call_site} expected "
                            f"physical target {expected_physical_address}, found {address}"
                        )
                    return "direct", logical_identity
            group_identity = indexes.reviewed_icf_group_by_address.get(
                address, ""
            )
            if group_identity:
                return "direct", group_identity
            logical_identity = (
                indexes.reviewed_non_gating_logical_target_by_address.get(
                    address, ""
                )
            )
            if logical_identity:
                return "direct", logical_identity
        identity = indexes.by_address.get(address, "")
        if not identity:
            raise ValueError(f"unresolved retail call target identity {address}")
        return ("provider" if identity in indexes.provider_ids else "direct"), identity
    if source == "bn":
        friendly_name = re.sub(
            r"^(?:(?:near|far)\s+)?(?:ptr\s+)?",
            "",
            operand.strip(),
            flags=re.IGNORECASE,
        ).strip()
        exact_name_kind = "friendly" if "::" in friendly_name else "exact-name"
        if (
            DECORATED_RE.fullmatch(friendly_name) is None
            and not any(
                token in friendly_name
                for token in ("[", "]", "+", "-", "*", "/")
            )
            and not any(character.isspace() for character in friendly_name)
        ):
            raw_matches = bridge_names.get(friendly_name)
            if raw_matches is None:
                raise ValueError(
                    f"unresolved bn {exact_name_kind} call target bridge identity "
                    f"{friendly_name!r}"
                )
            matches = (
                list(raw_matches)
                if isinstance(raw_matches, (list, tuple, set, frozenset))
                else [raw_matches]
            )
            addresses = {
                normalize_address(str(getattr(item, "address", "")))
                for item in matches
                if getattr(item, "address", "")
            }
            if len(addresses) != 1:
                raise ValueError(
                    f"ambiguous bn {exact_name_kind} call target identity "
                    f"{friendly_name!r}"
                )
            address = next(iter(addresses))
            if call_site_address is not None:
                call_site = normalize_address(call_site_address)
                selected = indexes.reviewed_authored_icf_by_call_site.get(call_site)
                if selected is not None:
                    expected_physical_address, logical_identity = selected
                    if expected_physical_address != address:
                        raise ValueError(
                            f"authored ICF retail call selector {call_site} expected "
                            f"physical target {expected_physical_address}, found {address}"
                        )
                    return "direct", logical_identity
            group_identity = indexes.reviewed_icf_group_by_address.get(
                address, ""
            )
            if group_identity:
                return "direct", group_identity
            exact_bridge_names = {friendly_name}
            for item in matches:
                exact_bridge_names.update(
                    str(value)
                    for value in (
                        getattr(item, "name", ""),
                        getattr(item, "raw_name", ""),
                        getattr(item, "full_name", ""),
                    )
                    if value
                )
            matching_aliases = [
                (alias_address, alias)
                for alias_address, aliases in (
                    indexes.reviewed_logical_aliases_by_address.items()
                )
                for alias in aliases
                if (
                    alias.original_name in exact_bridge_names
                    or alias.object_symbol in exact_bridge_names
                )
            ]
            aliases_at_address = [
                alias
                for alias_address, alias in matching_aliases
                if alias_address == address
            ]
            alias_identities = {
                alias.identity for alias in aliases_at_address
            }
            if len(alias_identities) > 1:
                raise ValueError(
                    f"ambiguous reviewed logical alias for bn {exact_name_kind} "
                    f"call target "
                    f"{friendly_name!r} at {address}"
                )
            non_gating_identity = (
                indexes.reviewed_non_gating_logical_target_by_address.get(
                    address, ""
                )
            )
            if non_gating_identity:
                physical_identity = indexes.by_address.get(address, "")
                if (
                    non_gating_identity in indexes.provider_ids
                    or physical_identity not in {"", non_gating_identity}
                    or (
                        alias_identities
                        and alias_identities != {non_gating_identity}
                    )
                ):
                    raise ValueError(
                        "conflicting reviewed non-gating logical target for "
                        f"bn {exact_name_kind} call target "
                        f"{friendly_name!r} at {address}"
                    )
                if matching_aliases and not aliases_at_address:
                    raise ValueError(
                        "reviewed logical alias for bn "
                        f"{exact_name_kind} call target "
                        f"{friendly_name!r} resolves at a different address "
                        f"than {address}"
                    )
                if (
                    indexes.reviewed_logical_aliases_by_address.get(address)
                    and not aliases_at_address
                ):
                    raise ValueError(
                        "missing exact reviewed logical alias for bn "
                        f"{exact_name_kind} call target "
                        f"{friendly_name!r} at {address}"
                    )
                return "direct", non_gating_identity
            if len(alias_identities) == 1:
                identity = next(iter(alias_identities))
                return "direct", identity
            if matching_aliases:
                raise ValueError(
                    f"reviewed logical alias for bn {exact_name_kind} call target "
                    f"{friendly_name!r} resolves at a different address than {address}"
                )
            if indexes.reviewed_logical_aliases_by_address.get(address):
                raise ValueError(
                    f"missing exact reviewed logical alias for bn {exact_name_kind} "
                    f"call target "
                    f"{friendly_name!r} at {address}"
                )
            identity = indexes.by_address.get(address, "")
            if not identity:
                raise ValueError(
                    f"unresolved bn {exact_name_kind} call target tracker identity "
                    f"{friendly_name!r} at {address}"
                )
            return (
                "provider" if identity in indexes.provider_ids else "direct"
            ), identity
    cod_space_bearing_name = (
        _cod_space_bearing_direct_target(operand, cod_source_line)
        if source == "cod"
        else None
    )
    decorated_match = DECORATED_RE.search(operand)
    decorated_name = (
        cod_space_bearing_name
        if cod_space_bearing_name is not None
        else (decorated_match.group(0) if decorated_match is not None else None)
    )
    if source == "cod" and decorated_name is not None:
        physical_provider_identity = (
            _hud_cmd_binding_ptr_vector_erase_provider_identity(
                decorated_name,
                indexes=indexes,
                bridge_names=bridge_names,
                compiler_generated_bridges=compiler_generated_bridges,
            )
        )
        if physical_provider_identity:
            return "provider", physical_provider_identity
        scalar_identity = _scalar_deleting_destructor_identity(
            decorated_name,
            indexes=indexes,
            bridge_names=bridge_names,
            compiler_generated_bridges=compiler_generated_bridges,
        )
        if scalar_identity:
            return "direct", scalar_identity
        provider_identity = _pointer_vector_destroy_provider_identity(
            decorated_name,
            indexes=indexes,
            bridge_names=bridge_names,
            compiler_generated_bridges=compiler_generated_bridges,
        )
        if provider_identity:
            return "provider", provider_identity
    exact_compiler_identities = (
        {
            identity
            for lookup_name in {
                cod_space_bearing_name or operand.strip(),
                decorated_name or "",
            }
            if lookup_name
            for identity in (compiler_generated_bridges.get(lookup_name, ""),)
            if identity
        }
        if source == "cod"
        else set()
    )
    if len(exact_compiler_identities) > 1:
        raise ValueError(
            "compiler-generated candidate bridge has conflicting exact "
            "operand and decorated-symbol identities"
        )
    exact_compiler_identity = (
        next(iter(exact_compiler_identities))
        if exact_compiler_identities else ""
    )
    if exact_compiler_identity:
        return (
            "provider"
            if exact_compiler_identity in indexes.provider_ids
            else "direct"
        ), exact_compiler_identity
    if decorated_name is not None:
        name = decorated_name
        if source == "cod" and name in indexes.candidate_only_names:
            r4564_set_enabled_identity = (
                "logical:recoil:logical-function:0x42ee40:"
                "hud-ui-background-container-set-enabled"
            )
            if (
                name
                == "?SetEnabled@HudUiBackgroundContainer@@UAEXH@Z"
                and caller_identity
                == "symbol:recoil:function:0x4b9900"
                and caller_start == 0x4B9900
                and caller_end == 0x4BA020
                and call_site_unique is True
                and call_site_address is not None
                and normalize_address(call_site_address) == "0x4b9e67"
                and indexes.reviewed_authored_icf_physical_by_logical_identity.get(
                    r4564_set_enabled_identity
                )
                == "recoil:function:0x42ee40"
                and r4564_set_enabled_identity not in indexes.provider_ids
            ):
                return "direct", r4564_set_enabled_identity
            provisional_selection = (
                indexes.reviewed_authored_icf_provisional_candidate_by_name.get(
                    name
                )
            )
            if provisional_selection is not None:
                physical_symbol_id, logical_identity = provisional_selection
                if (
                    indexes.reviewed_authored_icf_physical_by_logical_identity.get(
                        logical_identity
                    )
                    == physical_symbol_id
                ):
                    return "direct", logical_identity
                message = (
                    "unresolved cod decorated call target bridge identity "
                    f"{name!r}: reviewed provisional authored ICF candidate "
                    "selection has incomplete physical/logical population"
                )
                raise CandidateCallTargetBridgeError(
                    decorated_identity=name,
                    decoded_identity=(
                        _decode_candidate_dependent_callable_identity(name)
                    ),
                    call_site_address=call_site_address,
                    message=message,
                    call_site_unique=call_site_unique,
                )
            call_site = (
                normalize_address(retail_call_site_address)
                if retail_call_site_address is not None
                else ""
            )
            candidate_selection = (
                indexes.reviewed_authored_icf_candidate_by_call_site.get(
                    call_site
                )
                if call_site and call_site_unique is True
                else None
            )
            selected = (
                indexes.reviewed_authored_icf_by_call_site.get(call_site)
                if call_site
                else None
            )
            if candidate_selection is not None:
                (
                    physical_address,
                    physical_symbol_id,
                    selected_object_symbol,
                    logical_identity,
                ) = candidate_selection
                if (
                    selected == (physical_address, logical_identity)
                    and selected_object_symbol == name
                    and indexes.reviewed_authored_icf_physical_by_logical_identity.get(
                        logical_identity
                    )
                    == physical_symbol_id
                ):
                    return "direct", logical_identity
            message = (
                "unresolved cod decorated call target bridge identity "
                f"{name!r}: authored ICF candidate selection requires one "
                "exact target/object-symbol/retail-callsite population"
            )
            raise CandidateCallTargetBridgeError(
                decorated_identity=name,
                decoded_identity=(
                    _decode_candidate_dependent_callable_identity(name)
                ),
                call_site_address=call_site_address,
                message=message,
                call_site_unique=call_site_unique,
            )
        identity = (
            ""
            if source == "bn" and name in indexes.candidate_only_names
            else indexes.by_candidate_name.get(name, "")
        )
        if (
            not identity
            and source == "cod"
            and name not in indexes.by_candidate_name
        ):
            identity = compiler_generated_bridges.get(name, "")
        if not identity:
            raw_matches = bridge_names.get(name)
            if raw_matches is None:
                message = (
                    f"unresolved {source} decorated call target bridge identity "
                    f"{name!r}"
                )
                decoded_identity = (
                    _decode_candidate_dependent_callable_identity(name)
                    if source == "cod"
                    else None
                )
                if source == "cod":
                    raise CandidateCallTargetBridgeError(
                        decorated_identity=name,
                        decoded_identity=decoded_identity,
                        call_site_address=call_site_address,
                        message=message,
                        call_site_unique=call_site_unique,
                    )
                raise ValueError(message)
            matches = (
                list(raw_matches)
                if isinstance(raw_matches, (list, tuple, set, frozenset))
                else [raw_matches]
            )
            addresses = {
                normalize_address(str(getattr(item, "address", "")))
                for item in matches
                if getattr(item, "address", "")
            }
            if not addresses:
                raise ValueError(
                    f"unresolved {source} decorated call target bridge address "
                    f"{name!r}"
                )
            if len(addresses) != 1:
                raise ValueError(
                    f"ambiguous {source} decorated call target identity {name!r}"
                )
            address = next(iter(addresses))
            if source == "bn":
                if call_site_address is not None:
                    call_site = normalize_address(call_site_address)
                    selected = indexes.reviewed_authored_icf_by_call_site.get(call_site)
                    if selected is not None:
                        expected_physical_address, logical_identity = selected
                        if expected_physical_address != address:
                            raise ValueError(
                                f"authored ICF retail call selector {call_site} expected "
                                f"physical target {expected_physical_address}, found {address}"
                            )
                        return "direct", logical_identity
                group_identity = indexes.reviewed_icf_group_by_address.get(
                    address, ""
                )
                if group_identity:
                    return "direct", group_identity
            exact_bridge_names = {name}
            for item in matches:
                exact_bridge_names.update(
                    str(value)
                    for value in (
                        getattr(item, "name", ""),
                        getattr(item, "raw_name", ""),
                        getattr(item, "full_name", ""),
                    )
                    if value
                )
            matching_aliases = [
                (alias_address, alias)
                for alias_address, aliases in (
                    indexes.reviewed_logical_aliases_by_address.items()
                )
                for alias in aliases
                if (
                    alias.original_name in exact_bridge_names
                    or alias.object_symbol in exact_bridge_names
                )
            ]
            aliases_at_address = [
                alias
                for alias_address, alias in matching_aliases
                if alias_address == address
            ]
            alias_identities = {
                alias.identity for alias in aliases_at_address
            }
            if len(alias_identities) > 1:
                raise ValueError(
                    f"ambiguous reviewed logical alias for {source} decorated "
                    f"call target {name!r} at {address}"
                )
            if len(alias_identities) == 1:
                identity = next(iter(alias_identities))
            elif matching_aliases:
                raise ValueError(
                    f"reviewed logical alias for {source} decorated call target "
                    f"{name!r} resolves at a different address than {address}"
                )
            elif indexes.reviewed_logical_aliases_by_address.get(address):
                raise ValueError(
                    f"missing exact reviewed logical alias for {source} decorated "
                    f"call target {name!r} at {address}"
                )
            else:
                identity = indexes.by_address.get(address, "")
            if not identity:
                raise ValueError(
                    f"unresolved {source} decorated call target tracker identity "
                    f"{name!r} at {address}"
                )
        if not identity:
            raise ValueError(f"unresolved {source} call target identity {name!r}")
        if source == "cod":
            group_identity = (
                indexes.reviewed_icf_group_by_logical_identity.get(identity, "")
            )
            if group_identity:
                if indexes.by_candidate_name.get(name) != identity:
                    raise ValueError(
                        f"candidate decorated call target {name!r} is not an "
                        "exact reviewed member of its winner-unknown ICF group"
                    )
                identity = group_identity
        return ("provider" if identity in indexes.provider_ids else "direct"), identity
    raise ValueError(f"unresolved {source} direct call operand {operand!r}")


def _exact_thiscall_constructor_result(
    operand: str,
    *,
    source: str,
    target_identity: str,
    indexes: IdentityIndexes,
    receiver_provenance: str,
) -> str:
    """Preserve exact VC5 constructor ``EAX == this`` lineage.

    This records only the ABI relationship needed at a control-flow join.  It
    does not turn unknown receiver state into object provenance: an empty or
    null receiver remains unresolved, and later indirect-call validation still
    applies its ordinary storage/vptr restrictions.
    """
    if not receiver_provenance or receiver_provenance == "null":
        return ""
    constructor_names = {
        name
        for name, identity in indexes.by_candidate_name.items()
        if identity == target_identity and MSVC_CONSTRUCTOR_RE.fullmatch(name)
    }
    if len(constructor_names) != 1:
        return ""
    constructor_name = next(iter(constructor_names))
    if source == "cod":
        decorated = DECORATED_RE.search(operand)
        if decorated is None or decorated.group(0) != constructor_name:
            return ""
    elif source != "bn":
        return ""
    return receiver_provenance


def _memory_slot(operand: str) -> tuple[str, int | None]:
    match = MEMORY_RE.search(operand)
    if match is None:
        expression = re.sub(
            r"^(?:byte|word|dword)\s+(?:ptr\s+)?",
            "",
            operand.strip().lower(),
        )
    else:
        expression = match.group(1).lower()
    expression = re.sub(r"\s+", "", expression)
    displacement: int | None = 0 if match is not None else None
    numbers = list(re.finditer(r"(?P<sign>[+-]?)(?P<number>0x[0-9a-f]+|\d+)", expression))
    if numbers:
        item = numbers[-1]
        value = _parse_unsigned_assembly_integer(item.group("number"))
        displacement = -value if item.group("sign") == "-" else value
    return expression, displacement


def _exact_indirect_register_call_slot(
    instruction: Instruction,
    *,
    allow_zero: bool = False,
) -> tuple[str, int] | None:
    """Decode one exact ``CALL [r32+disp]`` with render/byte agreement."""

    if _instruction_mnemonic(instruction) != "call":
        return None
    try:
        body = bytes(int(item, 16) for item in instruction.bytes)
    except (TypeError, ValueError):
        return None
    if len(body) < 2 or body[0] != 0xFF:
        return None
    modrm = body[1]
    mode = modrm >> 6
    if ((modrm >> 3) & 7) != 2 or mode == 3 or (modrm & 7) == 4:
        return None
    if mode == 0 and len(body) == 2 and (modrm & 7) != 5:
        displacement = 0
    elif mode == 1 and len(body) == 3:
        displacement = struct.unpack("<b", body[2:3])[0]
    elif mode == 2 and len(body) == 6:
        displacement = struct.unpack("<i", body[2:6])[0]
    else:
        return None
    registers = (
        "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi",
    )
    base = registers[modrm & 7]
    expression, rendered_displacement = _memory_slot(
        _instruction_operand(instruction)
    )
    rendered = re.fullmatch(
        r"(?P<base>eax|ecx|edx|ebx|esi|edi|ebp)"
        r"(?:\+(?:0x[0-9a-f]+|\d+))?",
        expression,
    )
    if (
        rendered is None
        or rendered.group("base") != base
        or rendered_displacement != displacement
        or displacement < 0
        or (displacement == 0 and not allow_zero)
    ):
        return None
    return base, displacement


def _exact_indexed_affine_load(
    instruction: Instruction,
) -> tuple[str, str, str, int, int, str] | None:
    """Decode one exact MOV/LEA r32,[base+index*scale+disp] SIB form."""

    mnemonic = _instruction_mnemonic(instruction)
    expected_opcode = 0x8B if mnemonic == "mov" else 0x8D if mnemonic == "lea" else -1
    try:
        body = bytes(int(item, 16) for item in instruction.bytes)
    except (TypeError, ValueError):
        return None
    if len(body) < 3 or body[0] != expected_opcode:
        return None
    modrm = body[1]
    mode = modrm >> 6
    if mode == 3 or (modrm & 7) != 4:
        return None
    sib = body[2]
    scale = 1 << (sib >> 6)
    index_code = (sib >> 3) & 7
    base_code = sib & 7
    if index_code == 4 or (mode == 0 and base_code == 5):
        return None
    if mode == 0 and len(body) == 3:
        displacement = 0
    elif mode == 1 and len(body) == 4:
        displacement = struct.unpack("<b", body[3:4])[0]
    elif mode == 2 and len(body) == 7:
        displacement = struct.unpack("<i", body[3:7])[0]
    else:
        return None
    registers = (
        "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi",
    )
    destination = registers[(modrm >> 3) & 7]
    base_register = registers[base_code]
    index_register = registers[index_code]
    operands = _instruction_operand(instruction).split(",", 1)
    if len(operands) != 2 or operands[0].strip().lower() != destination:
        return None
    rendered = re.sub(
        r"\s+",
        "",
        _exact_memory_expression(operands[1]).lower(),
    )
    displacement_texts = (
        ("",)
        if displacement == 0
        else tuple(
            ("+" if displacement > 0 else "-") + value
            for value in (
                f"0x{abs(displacement):x}",
                str(abs(displacement)),
            )
        )
    )
    terms = {
        term
        for displacement_text in displacement_texts
        for term in (
            f"{base_register}+{index_register}*{scale}{displacement_text}",
            f"{index_register}*{scale}+{base_register}{displacement_text}",
        )
    }
    if rendered not in terms:
        return None
    return (
        destination,
        base_register,
        index_register,
        scale,
        displacement,
        mnemonic,
    )


def _exact_memory_expression(operand: str) -> str:
    """Return a whitespace-free memory expression without case folding."""
    match = MEMORY_RE.search(operand)
    if match is None:
        expression = re.sub(
            r"^(?:byte|word|dword)\s+(?:ptr\s+)?",
            "",
            operand.strip(),
            flags=re.IGNORECASE,
        )
    else:
        expression = match.group(1)
    return re.sub(r"\s+", "", expression)


def _exact_ff15_absolute_address(
    instruction: Instruction,
) -> str | None:
    """Decode exactly one unprefixed ``FF 15 imm32`` instruction."""
    try:
        body = bytes(int(item, 16) for item in instruction.bytes)
    except (TypeError, ValueError):
        return None
    if len(body) != 6 or body[:2] != b"\xff\x15":
        return None
    return normalize_address(struct.unpack("<I", body[2:6])[0])


def _hud_loading_checkpoint_stdio_iat_indexes(
    retail_instructions: Sequence[Instruction],
    *,
    candidate: CandidateAssembly,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_data_rows: Sequence[Any],
    bridge: BinaryNinjaBridge,
    reference: Path = DEFAULT_REFERENCE,
) -> IdentityIndexes:
    """Publish only this caller's immutable-retail ``puts``/``fflush`` IATs.

    This is a comparison-scoped identity bridge, not a provider registration.
    The two identities come from the immutable retail import directory, exact
    live retail data/provider rows and slot bytes, and the already-reviewed
    authored caller/TU/target authority.  Candidate COD/COFF proves only the
    independently compiled call form and symbols; it never supplies expected
    retail identity.
    """

    normalized_start = normalize_address(caller_start)
    if normalized_start != HUD_LOADING_CHECKPOINT_CALLER_START:
        return indexes

    caller_row = document.collection("symbols").get(
        HUD_LOADING_CHECKPOINT_CALLER_IDENTITY.removeprefix("symbol:")
    )
    trace = (
        caller_row.get("source_traceability")
        if isinstance(caller_row, Mapping)
        else None
    )
    source_edges = (
        trace.get("source_edges") if isinstance(trace, Mapping) else None
    )
    definition = candidate.caller_definition
    target = candidate.target
    contribution_rows = [
        (entry, row)
        for entry in getattr(target, "translation_unit_function_order", ())
        for row in getattr(entry, "functions", ())
        if normalize_address(str(getattr(row, "address", "")))
        == HUD_LOADING_CHECKPOINT_CALLER_START
    ]
    tracker_target = document.collection("verification_targets").get(
        HUD_UI_MESSAGE_REBUILD_WEAPON_ORDER_TARGET_ID
    )
    registration = (
        tracker_target.get("registration")
        if isinstance(tracker_target, Mapping)
        else None
    )
    if (
        caller_identity != HUD_LOADING_CHECKPOINT_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != HUD_LOADING_CHECKPOINT_CALLER_END_EXCLUSIVE
        or indexes.by_address.get(normalized_start) != caller_identity
        or caller_identity in indexes.provider_ids
        or not isinstance(caller_row, Mapping)
        or caller_row.get("binary") != "recoil"
        or caller_row.get("kind") != "function"
        or caller_row.get("pipeline_class") != "authored"
        or caller_row.get("ownership_state") != "primary-owned"
        or caller_row.get("address") != normalized_start
        or caller_row.get("end_exclusive")
        != HUD_LOADING_CHECKPOINT_CALLER_END_EXCLUSIVE
        or caller_row.get("extent_state") != "known"
        or caller_row.get("size") != 0x90
        or caller_row.get("navigation_name")
        != "HudUiLoadingCheckpoint::AdvanceAndLog"
        or caller_row.get("output_section_id") != "recoil:section:.text"
        or caller_row.get("physical_block_id") != "recoil:block:0x404ca0"
        or tuple(caller_row.get("verification_target_ids", ()))
        != (
            HUD_LOADING_CHECKPOINT_FUNCTIONAL_TARGET_ID,
            HUD_UI_MESSAGE_REBUILD_WEAPON_ORDER_TARGET_ID,
            HUD_LOADING_CHECKPOINT_TRIGGER_TARGET_ID,
        )
        or not isinstance(trace, Mapping)
        or trace.get("state") != "resolved"
        or trace.get("reason_code") not in {None, ""}
        or not isinstance(source_edges, list)
        or len(source_edges) != 1
        or not isinstance(source_edges[0], Mapping)
        or source_edges[0].get("relation") != "defines"
        or source_edges[0].get("anchor_id")
        != HUD_LOADING_CHECKPOINT_CALLER_ANCHOR_ID
        or source_edges[0].get("emission_context")
        != {"translation_unit": HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH}
        or definition is None
        or definition.symbol != HUD_LOADING_CHECKPOINT_CALLER_SYMBOL
        or len(definition.data) != 0x80
        or len(definition.relocation_mask) != len(definition.data)
        or target is None
        or getattr(target, "name", "") != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or Path(str(getattr(target, "manifest_path", ""))).resolve()
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_MANIFEST.resolve()
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
        or tuple(getattr(target, "source_files", ())).count(
            HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        )
        != 1
        or len(contribution_rows) != 1
        or not isinstance(tracker_target, Mapping)
        or tracker_target.get("binary") != "recoil"
        or tracker_target.get("kind") != "vc5"
        or tracker_target.get("name") != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or tuple(tracker_target.get("registered_addresses", ())).count(
            normalized_start
        )
        != 1
        or not isinstance(registration, Mapping)
        or registration.get("binary") != "recoil"
        or registration.get("name") != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or registration.get("manifest_path")
        != str(
            HUD_UI_MGR_INIT_LAYOUTS_TARGET_MANIFEST.relative_to(REPO_ROOT)
        ).replace("\\", "/")
        or registration.get("source_from")
        != HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        or registration.get("check_translation_unit_function_order")
        is not True
        or registration.get("function_order_scope") != "authored"
    ):
        raise ValueError(
            "HUD loading-checkpoint stdio IAT bridge requires the exact "
            "authored caller, source anchor/TU, extent, object symbol, and "
            "governed target authority"
        )

    contribution, contribution_row = contribution_rows[0]
    if (
        getattr(contribution, "source_from", "")
        != HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        or getattr(contribution, "order_scope", "") != "authored"
        or getattr(contribution_row, "symbol", "")
        != HUD_LOADING_CHECKPOINT_CALLER_SYMBOL
        or getattr(contribution_row, "symbol_regex", None) is not None
        or getattr(contribution_row, "name", "")
        != "HudUiLoadingCheckpoint::AdvanceAndLog"
        or getattr(contribution_row, "pipeline_class", "") != "authored"
        or getattr(contribution_row, "authored_order_role", "")
        != "authored-body"
        or getattr(contribution_row, "required_presence", None) is not True
        or getattr(contribution_row, "full_order_gate", None) is not True
    ):
        raise ValueError(
            "HUD loading-checkpoint stdio IAT bridge rejects exact hud.cpp "
            "target contribution-row authority drift"
        )

    retail_addresses = _instruction_runtime_addresses(
        retail_instructions,
        source="bn",
        caller_start=address_value(normalized_start),
    )
    retail_invocations = tuple(
        address
        for instruction, address in zip(retail_instructions, retail_addresses)
        if address is not None and _instruction_mnemonic(instruction) == "call"
    )
    candidate_offsets = _candidate_complete_instruction_offsets(candidate)
    candidate_invocation_indices = _candidate_static_invocation_indices(
        candidate,
        caller_start=normalized_start,
        caller_end_exclusive=caller_end_exclusive,
    )
    candidate_invocations = tuple(
        candidate_offsets[index] for index in candidate_invocation_indices
    )
    if (
        retail_invocations != HUD_LOADING_CHECKPOINT_RETAIL_CALL_ORDER
        or candidate_invocations
        != HUD_LOADING_CHECKPOINT_CANDIDATE_CALL_ORDER
    ):
        raise ValueError(
            "HUD loading-checkpoint stdio IAT bridge rejects complete retail/"
            "candidate five-call population, order, or call form drift"
        )

    retail_by_address = {
        normalize_address(hex(address)): (index, instruction)
        for index, (instruction, address) in enumerate(
            zip(retail_instructions, retail_addresses)
        )
        if address is not None
    }
    candidate_by_offset = {
        offset: (index, candidate.instructions[index])
        for index, offset in enumerate(candidate_offsets)
        if offset is not None
    }
    storage_by_address = dict(indexes.storage_by_address)
    storage_by_name = dict(indexes.storage_by_name)
    for spec in HUD_LOADING_CHECKPOINT_STDIO_IAT_SPECS:
        import_name = str(spec["import_name"])
        candidate_symbol = str(spec["candidate_symbol"])
        iat_address = str(spec["iat_address"])
        provider_address = str(spec["provider_address"])
        iat_identity = f"iat:{import_name}"
        retail_import, _directory_context = retail_import_target(
            reference=reference,
            address=iat_address,
            dll="MSVCRT.dll",
            import_name=import_name,
        )
        if (
            retail_import.address != iat_address
            or retail_import.dll != "MSVCRT.dll"
            or retail_import.import_name != import_name
            or retail_import.import_ordinal is not None
        ):
            raise ValueError(
                "HUD loading-checkpoint stdio IAT bridge immutable retail "
                f"{import_name} import tuple drifted"
            )

        iat_rows = [
            row
            for row in bridge_data_rows
            if normalize_address(str(getattr(row, "address", "")))
            == iat_address
        ]
        provider_rows = [
            row
            for row in bridge_data_rows
            if normalize_address(str(getattr(row, "address", "")))
            == provider_address
        ]
        if (
            len(iat_rows) != 1
            or getattr(iat_rows[0], "name", "") != import_name
            or getattr(iat_rows[0], "raw_name", "") != import_name
            or getattr(iat_rows[0], "type_text", "") != spec["iat_type"]
            or getattr(iat_rows[0], "size", 0) != 4
        ):
            raise ValueError(
                "HUD loading-checkpoint stdio IAT bridge requires one exact "
                f"live retail typed {import_name} IAT row"
            )
        if (
            len(provider_rows) != 1
            or getattr(provider_rows[0], "name", "") != import_name
            or getattr(provider_rows[0], "raw_name", "") != import_name
            or getattr(provider_rows[0], "type_text", "")
            != spec["provider_type"]
            or getattr(provider_rows[0], "size", -1) != 0
        ):
            raise ValueError(
                "HUD loading-checkpoint stdio IAT bridge requires one exact "
                f"live retail bound {import_name} provider row"
            )
        slot_bytes = _hexdump_bytes(bridge.hexdump(iat_address, 4))
        if (
            len(slot_bytes) != 4
            or normalize_address(struct.unpack("<I", slot_bytes)[0])
            != provider_address
        ):
            raise ValueError(
                "HUD loading-checkpoint stdio IAT bridge retail slot bytes "
                f"do not bind the exact {import_name} provider row"
            )

        retail_call_address = str(spec["retail_call_address"])
        candidate_call_offset = int(spec["candidate_call_offset"])
        retail_call_row = retail_by_address.get(retail_call_address)
        candidate_call_row = candidate_by_offset.get(candidate_call_offset)
        if retail_call_row is None or candidate_call_row is None:
            raise ValueError(
                "HUD loading-checkpoint stdio IAT bridge lacks an exact "
                f"{import_name} callsite"
            )
        retail_call_index, retail_call = retail_call_row
        candidate_call_index, candidate_call = candidate_call_row
        if (
            _instruction_mnemonic(retail_call) != "call"
            or _instruction_operand(retail_call).strip().lower()
            != f"dword [{import_name}]"
            or _exact_ff15_absolute_address(retail_call) != iat_address
            or _cleanup_after(retail_instructions, retail_call_index) != 4
            or _instruction_mnemonic(candidate_call) != "call"
            or _instruction_operand(candidate_call).strip().lower()
            != f"dword {candidate_symbol.lower()}"
            or tuple(value.lower() for value in candidate_call.bytes)
            != ("ff", "15", "00", "00", "00", "00")
            or _cleanup_after(candidate.instructions, candidate_call_index) != 4
            or retail_invocations[int(spec["ordinal"])]
            != address_value(retail_call_address)
            or candidate_invocations[int(spec["ordinal"])]
            != candidate_call_offset
        ):
            raise ValueError(
                "HUD loading-checkpoint stdio IAT bridge rejects exact "
                f"{import_name} ordinal, FF15 form, storage, target, or "
                "caller cleanup +4"
            )

        references = tuple(
            relocation
            for relocation in definition.relocations
            if relocation.symbol_name == candidate_symbol
        )
        relocation_offset = int(spec["candidate_relocation_offset"])
        if (
            definition.undefined_external_functions.count(candidate_symbol)
            != 1
            or len(references) != 1
            or references[0].type != IMAGE_REL_I386_DIR32
            or references[0].offset != relocation_offset
            or relocation_offset < 2
            or relocation_offset + 4 > len(definition.data)
            or definition.data[relocation_offset - 2 : relocation_offset]
            != b"\xff\x15"
            or struct.unpack_from("<I", definition.data, relocation_offset)[0]
            != 0
            or not all(
                definition.relocation_mask[index]
                for index in range(relocation_offset, relocation_offset + 4)
            )
            or (
                definition.defined_external_functions
                + definition.undefined_external_data
                + definition.defined_external_data
            ).count(candidate_symbol)
            != 0
        ):
            raise ValueError(
                "HUD loading-checkpoint stdio IAT bridge requires one exact "
                f"undefined external {candidate_symbol} FF15 DIR32 relocation"
            )

        for mapping, key in (
            (storage_by_address, iat_address),
            (storage_by_name, import_name),
            (storage_by_name, candidate_symbol),
        ):
            prior = mapping.get(key)
            if prior is not None and prior != iat_identity:
                raise ValueError(
                    "HUD loading-checkpoint stdio IAT bridge conflicts with "
                    f"an existing storage identity for {key!r}"
                )
            mapping[key] = iat_identity

    return replace(
        indexes,
        storage_by_address=storage_by_address,
        storage_by_name=storage_by_name,
    )


def _gamenet_chat_compose_candidate_register_storage_bridges(
    retail_instructions: Sequence[Instruction],
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
) -> tuple[dict[str, str], dict[str, str]]:
    """Prove ChatComposeKeyCallback's candidate ``esi`` vptr origin.

    Retail absolute addresses already resolve through the reviewed aggregate
    container.  The candidate bridge only maps the decorated aggregate name
    after proving the same complete caller, reaching-definition chain, call
    contract, body, and COFF relocation population.  It never supplies retail
    expected truth.
    """

    normalized_start = normalize_address(caller_start)
    if normalized_start != GAMENET_CHAT_COMPOSE_CALLER_START:
        return {}, {}

    caller_symbol_id = GAMENET_CHAT_COMPOSE_CALLER_IDENTITY.removeprefix(
        "symbol:"
    )
    caller_row = document.collection("symbols").get(caller_symbol_id)
    trace = (
        caller_row.get("source_traceability")
        if isinstance(caller_row, Mapping)
        else None
    )
    source_edges = (
        trace.get("source_edges") if isinstance(trace, Mapping) else None
    )
    definition = candidate.caller_definition
    target = candidate.target
    contribution_rows = [
        (entry, row)
        for entry in getattr(target, "translation_unit_function_order", ())
        for row in getattr(entry, "functions", ())
        if normalize_address(str(getattr(row, "address", "")))
        == GAMENET_CHAT_COMPOSE_CALLER_START
    ]
    tracker_target = document.collection("verification_targets").get(
        HUD_UI_MESSAGE_REBUILD_WEAPON_ORDER_TARGET_ID
    )
    registration = (
        tracker_target.get("registration")
        if isinstance(tracker_target, Mapping)
        else None
    )
    if (
        caller_identity != GAMENET_CHAT_COMPOSE_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != GAMENET_CHAT_COMPOSE_CALLER_END_EXCLUSIVE
        or indexes.by_address.get(normalized_start) != caller_identity
        or caller_identity in indexes.provider_ids
        or not isinstance(caller_row, Mapping)
        or caller_row.get("binary") != "recoil"
        or caller_row.get("kind") != "function"
        or caller_row.get("pipeline_class") != "authored"
        or caller_row.get("ownership_state") != "primary-owned"
        or caller_row.get("address") != normalized_start
        or caller_row.get("end_exclusive")
        != GAMENET_CHAT_COMPOSE_CALLER_END_EXCLUSIVE
        or caller_row.get("extent_state") != "known"
        or caller_row.get("size") != 0x40
        or caller_row.get("navigation_name")
        != "GameNet::ChatComposeKeyCallback"
        or caller_row.get("output_section_id") != "recoil:section:.text"
        or caller_row.get("physical_block_id") != "recoil:block:0x404ca0"
        or tuple(caller_row.get("verification_target_ids", ()))
        != (
            GAMENET_CHAT_COMPOSE_FUNCTIONAL_TARGET_ID,
            HUD_UI_MESSAGE_REBUILD_WEAPON_ORDER_TARGET_ID,
        )
        or not isinstance(trace, Mapping)
        or trace.get("state") != "resolved"
        or trace.get("reason_code") not in {None, ""}
        or not isinstance(source_edges, list)
        or len(source_edges) != 1
        or not isinstance(source_edges[0], Mapping)
        or source_edges[0].get("relation") != "defines"
        or source_edges[0].get("anchor_id")
        != GAMENET_CHAT_COMPOSE_CALLER_ANCHOR_ID
        or source_edges[0].get("emission_context")
        != {"translation_unit": HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH}
        or definition is None
        or definition.symbol != GAMENET_CHAT_COMPOSE_CALLER_SYMBOL
        or definition.data != GAMENET_CHAT_COMPOSE_CANDIDATE_CODE
        or len(definition.relocation_mask) != len(definition.data)
        or target is None
        or getattr(target, "name", "") != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or Path(str(getattr(target, "manifest_path", ""))).resolve()
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_MANIFEST.resolve()
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
        or tuple(getattr(target, "source_files", ())).count(
            HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        )
        != 1
        or len(contribution_rows) != 1
        or not isinstance(tracker_target, Mapping)
        or tracker_target.get("binary") != "recoil"
        or tracker_target.get("kind") != "vc5"
        or tracker_target.get("name") != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or tuple(tracker_target.get("registered_addresses", ())).count(
            normalized_start
        )
        != 1
        or not isinstance(registration, Mapping)
        or registration.get("binary") != "recoil"
        or registration.get("name") != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or registration.get("manifest_path")
        != str(
            HUD_UI_MGR_INIT_LAYOUTS_TARGET_MANIFEST.relative_to(REPO_ROOT)
        ).replace("\\", "/")
        or registration.get("source_from")
        != HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        or registration.get("check_translation_unit_function_order")
        is not True
        or registration.get("function_order_scope") != "authored"
    ):
        raise ValueError(
            "GameNet chat-compose esi bridge requires the exact authored "
            "caller, source anchor/TU, extent, object symbol/body, and "
            "governed target authority"
        )

    contribution, contribution_row = contribution_rows[0]
    if (
        getattr(contribution, "source_from", "")
        != HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        or getattr(contribution, "order_scope", "") != "authored"
        or getattr(contribution_row, "symbol", "") != ""
        or getattr(contribution_row, "symbol_regex", None)
        != GAMENET_CHAT_COMPOSE_CONTRIBUTION_SYMBOL_RE
        or re.fullmatch(
            GAMENET_CHAT_COMPOSE_CONTRIBUTION_SYMBOL_RE,
            definition.symbol,
        )
        is None
        or getattr(contribution_row, "name", "")
        != "GameNet::ChatComposeKeyCallback"
        or getattr(contribution_row, "pipeline_class", "") != "authored"
        or getattr(contribution_row, "authored_order_role", "")
        != "authored-body"
        or getattr(contribution_row, "required_presence", None) is not True
        or getattr(contribution_row, "full_order_gate", None) is not True
    ):
        raise ValueError(
            "GameNet chat-compose esi bridge rejects exact hud.cpp "
            "contribution-row authority drift"
        )

    symbols = document.collection("symbols")
    storages = document.collection("storage_contributions")
    owners = document.collection("owners")
    targets = document.collection("verification_targets")
    aggregate_symbol = symbols.get(HUD_UI_MGR_AGGREGATE_SYMBOL_ID)
    aggregate_storage = storages.get(HUD_UI_MGR_AGGREGATE_STORAGE_ID)
    aggregate_target = targets.get(HUD_UI_MGR_AGGREGATE_TARGET_ID)
    aggregate_registration = (
        aggregate_target.get("registration")
        if isinstance(aggregate_target, Mapping)
        else None
    )
    owner = owners.get(HUD_UI_MGR_OWNER_ID)
    gates = owner.get("gates") if isinstance(owner, Mapping) else None
    reference = (
        aggregate_storage.get("reference")
        if isinstance(aggregate_storage, Mapping)
        else None
    )
    owner_relationships = [
        relationship
        for relationship in (
            owner.get("relationships", ())
            if isinstance(owner, Mapping)
            else ()
        )
        if isinstance(relationship, Mapping)
        and relationship.get("kind") == "primary-data"
        and relationship.get("symbol_id") == HUD_UI_MGR_AGGREGATE_SYMBOL_ID
    ]
    aggregate_identity = f"storage:{HUD_UI_MGR_AGGREGATE_SYMBOL_ID}"
    aggregate_start = address_value(HUD_UI_MGR_AGGREGATE_ADDRESS)
    exact_containers = [
        row
        for row in indexes.storage_containers
        if row.identity == aggregate_identity
        and row.start == aggregate_start
        and row.end_exclusive == aggregate_start + HUD_UI_MGR_AGGREGATE_SIZE
    ]
    aggregate_addresses = [
        address
        for address, identity in indexes.storage_by_address.items()
        if identity == aggregate_identity
    ]
    if (
        not isinstance(aggregate_symbol, Mapping)
        or aggregate_symbol.get("binary") != "recoil"
        or aggregate_symbol.get("kind") != "data"
        or aggregate_symbol.get("address") != HUD_UI_MGR_AGGREGATE_ADDRESS
        or aggregate_symbol.get("disposition") != "authored"
        or aggregate_symbol.get("navigation_name")
        != HUD_UI_MGR_AGGREGATE_NAME
        or aggregate_symbol.get("output_section_id") != "recoil:section:.data"
        or aggregate_symbol.get("storage_contribution_ids")
        != [HUD_UI_MGR_AGGREGATE_STORAGE_ID]
        or aggregate_symbol.get("verification_target_ids")
        != [HUD_UI_MGR_AGGREGATE_TARGET_ID]
        or aggregate_symbol.get("extent_state") != "unknown"
        or not isinstance(aggregate_storage, Mapping)
        or aggregate_storage.get("binary") != "recoil"
        or aggregate_storage.get("kind") != "data-symbol"
        or aggregate_storage.get("output_section_id") != "recoil:section:.data"
        or aggregate_storage.get("overlap") != "none"
        or aggregate_storage.get("owner_ids") != [HUD_UI_MGR_OWNER_ID]
        or aggregate_storage.get("parent_contribution_id") is not None
        or aggregate_storage.get("symbol_ids")
        != [HUD_UI_MGR_AGGREGATE_SYMBOL_ID]
        or not isinstance(reference, Mapping)
        or reference.get("address") != HUD_UI_MGR_AGGREGATE_ADDRESS
        or reference.get("extent_state") != "unknown"
        or not isinstance(aggregate_target, Mapping)
        or aggregate_target.get("binary") != "recoil"
        or aggregate_target.get("kind") != "vc5"
        or aggregate_target.get("name") != "hud_ui_mgr_data"
        or aggregate_target.get("symbol_ids")
        != [HUD_UI_MGR_AGGREGATE_SYMBOL_ID]
        or aggregate_target.get("unresolved_addresses") not in (None, [])
        or not isinstance(aggregate_registration, Mapping)
        or aggregate_registration.get("manifest_path")
        != HUD_UI_MGR_AGGREGATE_TARGET_MANIFEST
        or aggregate_registration.get("data_addresses")
        != [HUD_UI_MGR_AGGREGATE_ADDRESS]
        or not isinstance(owner, Mapping)
        or owner.get("binary") != "recoil"
        or owner.get("kind") != "data-owner"
        or owner.get("provider_state") == "accepted"
        or not isinstance(gates, Mapping)
        or any(
            gates.get(gate) != "accepted"
            for gate in ("boundary", "source", "data", "owner_linkage")
        )
        or owner_relationships
        != [
            {
                "kind": "primary-data",
                "symbol_id": HUD_UI_MGR_AGGREGATE_SYMBOL_ID,
                "address": HUD_UI_MGR_AGGREGATE_ADDRESS,
                "name": HUD_UI_MGR_AGGREGATE_NAME,
            }
        ]
        or indexes.storage_by_address.get(HUD_UI_MGR_AGGREGATE_ADDRESS)
        != aggregate_identity
        or aggregate_addresses != [HUD_UI_MGR_AGGREGATE_ADDRESS]
        or len(exact_containers) != 1
        or aggregate_identity in indexes.provider_ids
        or GAMENET_CHAT_COMPOSE_AGGREGATE_POINTER_DISPLACEMENT + 4
        > HUD_UI_MGR_AGGREGATE_SIZE
        or GAMENET_CHAT_COMPOSE_TEXT_INPUT_DISPLACEMENT + 4
        > HUD_UI_MGR_AGGREGATE_SIZE
    ):
        raise ValueError(
            "GameNet chat-compose esi bridge requires the exact reviewed "
            "g_HudUiMgr aggregate symbol, storage, target, owner, gates, "
            "and bounded container authority"
        )

    def instruction_bytes(instruction: Instruction) -> bytes:
        try:
            return bytes(int(value, 16) for value in instruction.bytes)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                "GameNet chat-compose esi bridge requires exact instruction bytes"
            ) from exc

    retail_addresses = _instruction_runtime_addresses(
        retail_instructions,
        source="bn",
        caller_start=address_value(normalized_start),
    )
    candidate_offsets = _candidate_complete_instruction_offsets(candidate)
    expected_offsets = (
        0x00,
        0x05,
        0x07,
        0x09,
        0x0A,
        0x0B,
        0x10,
        0x15,
        0x1A,
        0x1F,
        0x21,
        0x26,
        0x2C,
        0x2D,
        0x2E,
        0x31,
        0x34,
        0x35,
    )
    retail_offsets = tuple(
        address - address_value(normalized_start)
        for address in retail_addresses
        if address is not None
    )
    if (
        retail_offsets != expected_offsets
        or tuple(offset for offset in candidate_offsets if offset is not None)
        != expected_offsets
        or b"".join(instruction_bytes(row) for row in retail_instructions)
        != GAMENET_CHAT_COMPOSE_RETAIL_CODE[:0x36]
        or b"".join(instruction_bytes(row) for row in candidate.instructions)
        != GAMENET_CHAT_COMPOSE_CANDIDATE_CODE[:0x36]
        or candidate.local_control_flow_indices
        or candidate.local_control_flow_targets
    ):
        raise ValueError(
            "GameNet chat-compose esi bridge requires the exact complete "
            "retail/candidate instruction population, bytes, and CFG"
        )

    retail_invocation_indices = tuple(
        index
        for index, instruction in enumerate(retail_instructions)
        if _instruction_mnemonic(instruction) == "call"
    )
    candidate_invocation_indices = _candidate_static_invocation_indices(
        candidate,
        caller_start=normalized_start,
        caller_end_exclusive=caller_end_exclusive,
    )
    retail_invocations = tuple(
        retail_addresses[index] for index in retail_invocation_indices
    )
    candidate_invocations = tuple(
        candidate_offsets[index] for index in candidate_invocation_indices
    )
    if (
        retail_invocations != GAMENET_CHAT_COMPOSE_RETAIL_CALL_ORDER
        or candidate_invocations != GAMENET_CHAT_COMPOSE_CANDIDATE_CALL_ORDER
        or tuple(
            _cleanup_after(retail_instructions, index)
            for index in retail_invocation_indices
        )
        != (None, None, None, 8)
        or tuple(
            _cleanup_after(candidate.instructions, index)
            for index in candidate_invocation_indices
        )
        != (None, None, None, 8)
    ):
        raise ValueError(
            "GameNet chat-compose esi bridge rejects complete four-call "
            "population, order, form, or caller cleanup drift"
        )

    retail_by_offset = {
        offset: retail_instructions[index]
        for index, offset in enumerate(retail_offsets)
    }
    candidate_by_offset = {
        offset: candidate.instructions[index]
        for index, offset in enumerate(candidate_offsets)
        if offset is not None
    }
    for ordinal, (address, candidate_name, _retail_name) in enumerate(
        GAMENET_CHAT_COMPOSE_DIRECT_CALLS
    ):
        identity = indexes.by_address.get(address, "")
        if (
            not identity
            or identity in indexes.provider_ids
            or indexes.by_candidate_name.get(candidate_name) != identity
            or candidate_name
            not in _instruction_operand(
                candidate_by_offset[
                    GAMENET_CHAT_COMPOSE_CANDIDATE_CALL_ORDER[ordinal]
                ]
            )
        ):
            raise ValueError(
                "GameNet chat-compose esi bridge requires exact authored "
                f"direct-call identity and order for {candidate_name!r}"
            )
    if (
        _exact_memory_expression(
            _instruction_operand(retail_by_offset[0x2E])
        )
        not in {"esi+116", "esi+0x74"}
        or _exact_memory_expression(
            _instruction_operand(candidate_by_offset[0x2E])
        )
        not in {"esi+116", "esi+0x74"}
        or _exact_memory_expression(
            _instruction_operand(retail_by_offset[0x15]).split(",", 1)[1]
        )
        != "0x4e6844"
        or _exact_memory_expression(
            _instruction_operand(retail_by_offset[0x1F]).split(",", 1)[1]
        )
        != "eax"
        or _exact_memory_expression(
            _instruction_operand(retail_by_offset[0x26]).split(",", 1)[1]
        )
        != "0x4e6844"
        or _exact_memory_expression(
            _instruction_operand(candidate_by_offset[0x15]).split(",", 1)[1]
        )
        not in {
            (
                f"{HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL}+"
                f"{GAMENET_CHAT_COMPOSE_AGGREGATE_POINTER_DISPLACEMENT}"
            ),
            (
                f"{HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL}+0x"
                f"{GAMENET_CHAT_COMPOSE_AGGREGATE_POINTER_DISPLACEMENT:x}"
            ),
        }
        or _exact_memory_expression(
            _instruction_operand(candidate_by_offset[0x1F]).split(",", 1)[1]
        )
        != "eax"
        or _exact_memory_expression(
            _instruction_operand(candidate_by_offset[0x26]).split(",", 1)[1]
        )
        not in {
            (
                f"{HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL}+"
                f"{GAMENET_CHAT_COMPOSE_AGGREGATE_POINTER_DISPLACEMENT}"
            ),
            (
                f"{HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL}+0x"
                f"{GAMENET_CHAT_COMPOSE_AGGREGATE_POINTER_DISPLACEMENT:x}"
            ),
        }
    ):
        raise ValueError(
            "GameNet chat-compose esi bridge rejects the exact aggregate "
            "+0x974 pointer, esi vptr, slot +0x74, receiver, or argument chain"
        )

    expected_relocations = (
        (0x01, IMAGE_REL_I386_REL32, GAMENET_CHAT_COMPOSE_DIRECT_CALLS[0][1], 0),
        (
            0x0C,
            IMAGE_REL_I386_DIR32,
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
            GAMENET_CHAT_COMPOSE_TEXT_INPUT_DISPLACEMENT,
        ),
        (0x11, IMAGE_REL_I386_REL32, GAMENET_CHAT_COMPOSE_DIRECT_CALLS[1][1], 0),
        (
            0x16,
            IMAGE_REL_I386_DIR32,
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
            GAMENET_CHAT_COMPOSE_AGGREGATE_POINTER_DISPLACEMENT,
        ),
        (
            0x1B,
            IMAGE_REL_I386_DIR32,
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
            GAMENET_CHAT_COMPOSE_TEXT_INPUT_DISPLACEMENT,
        ),
        (0x22, IMAGE_REL_I386_REL32, GAMENET_CHAT_COMPOSE_DIRECT_CALLS[2][1], 0),
        (
            0x28,
            IMAGE_REL_I386_DIR32,
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
            GAMENET_CHAT_COMPOSE_AGGREGATE_POINTER_DISPLACEMENT,
        ),
    )
    actual_relocations = tuple(
        (
            row.offset,
            row.type,
            row.symbol_name,
            struct.unpack_from("<I", definition.data, row.offset)[0],
        )
        for row in definition.relocations
    )
    expected_mask = {
        index
        for offset, _type, _symbol, _addend in expected_relocations
        for index in range(offset, offset + 4)
    }
    if (
        actual_relocations != expected_relocations
        or {
            index
            for index, masked in enumerate(definition.relocation_mask)
            if masked
        }
        != expected_mask
        or definition.undefined_external_data.count(
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        )
        != 1
        or HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        in definition.defined_external_data
        or any(
            definition.undefined_external_functions.count(name) != 1
            or name in definition.defined_external_functions
            for _address, name, _retail_name in GAMENET_CHAT_COMPOSE_DIRECT_CALLS
        )
    ):
        raise ValueError(
            "GameNet chat-compose esi bridge requires the exact seven "
            "candidate DIR32/REL32 relocations, addends, masks, and external "
            "symbol provenance"
        )

    candidate_bridges = {
        HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL: aggregate_identity,
    }
    retail_bridge_names = {
        retail_name: Symbol(
            address=address,
            name=retail_name,
            raw_name=retail_name,
            full_name=retail_name,
        )
        for address, _candidate_name, retail_name in (
            GAMENET_CHAT_COMPOSE_DIRECT_CALLS
        )
    }
    expected_contract = extract_invocation_contract(
        retail_instructions,
        source="bn",
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
        indexes=indexes,
        bridge_names=retail_bridge_names,
    )
    candidate_contract = extract_invocation_contract(
        candidate.instructions,
        source="cod",
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
        indexes=indexes,
        reviewed_register_storage_bridges=candidate_bridges,
    )
    expected_storage = (
        "load(load("
        f"{aggregate_identity}+0x"
        f"{GAMENET_CHAT_COMPOSE_AGGREGATE_POINTER_DISPLACEMENT:x}))"
    )
    if (
        expected_contract != candidate_contract
        or len(expected_contract) != 4
        or expected_contract[-1]
        != {
            "ordinal": 3,
            "form": "call",
            "dispatch": "indirect",
            "identity_kind": "virtual-slot",
            "target_identity": "",
            "storage_identity": expected_storage,
            "slot_displacement": GAMENET_CHAT_COMPOSE_VIRTUAL_SLOT,
            "cleanup_bytes": 8,
        }
    ):
        raise ValueError(
            "GameNet chat-compose esi bridge cannot derive the exact "
            "candidate-independent retail and candidate four-call contract"
        )
    return {}, candidate_bridges


def _gamenet_end_chat_compose_strncat_register_storage_bridges(
    retail_instructions: Sequence[Instruction],
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    reference: Path = DEFAULT_REFERENCE,
) -> tuple[dict[str, str], dict[str, str]]:
    """Prove 0x414590's two-call ``esi`` MSVCRT ``strncat`` lifetime.

    The retail IAT tuple and authored caller/TU authority are independent of
    the candidate.  Candidate COD/COFF may publish only the matching decorated
    storage name after the whole reviewed caller shape, relocation population,
    call order, cleanup, and unclobbered register lifetime converge.
    """

    normalized_start = normalize_address(caller_start)
    if normalized_start != GAMENET_END_CHAT_COMPOSE_CALLER_START:
        return {}, {}

    caller_symbol_id = GAMENET_END_CHAT_COMPOSE_CALLER_IDENTITY.removeprefix(
        "symbol:"
    )
    caller_row = document.collection("symbols").get(caller_symbol_id)
    trace = (
        caller_row.get("source_traceability")
        if isinstance(caller_row, Mapping)
        else None
    )
    source_edges = (
        trace.get("source_edges") if isinstance(trace, Mapping) else None
    )
    definition = candidate.caller_definition
    target = candidate.target
    contribution_rows = [
        (entry, row)
        for entry in getattr(target, "translation_unit_function_order", ())
        for row in getattr(entry, "functions", ())
        if normalize_address(str(getattr(row, "address", "")))
        == GAMENET_END_CHAT_COMPOSE_CALLER_START
    ]
    tracker_target = document.collection("verification_targets").get(
        HUD_UI_MESSAGE_REBUILD_WEAPON_ORDER_TARGET_ID
    )
    registration = (
        tracker_target.get("registration")
        if isinstance(tracker_target, Mapping)
        else None
    )
    if (
        caller_identity != GAMENET_END_CHAT_COMPOSE_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != GAMENET_END_CHAT_COMPOSE_CALLER_END_EXCLUSIVE
        or indexes.by_address.get(normalized_start) != caller_identity
        or caller_identity in indexes.provider_ids
        or not isinstance(caller_row, Mapping)
        or caller_row.get("binary") != "recoil"
        or caller_row.get("kind") != "function"
        or caller_row.get("pipeline_class") != "authored"
        or caller_row.get("ownership_state") != "primary-owned"
        or caller_row.get("address") != normalized_start
        or caller_row.get("end_exclusive")
        != GAMENET_END_CHAT_COMPOSE_CALLER_END_EXCLUSIVE
        or caller_row.get("extent_state") != "known"
        or caller_row.get("size") != 0xD0
        or caller_row.get("navigation_name")
        != "GameNet::EndChatComposeAndSend"
        or caller_row.get("output_section_id") != "recoil:section:.text"
        or caller_row.get("physical_block_id") != "recoil:block:0x404ca0"
        or tuple(caller_row.get("verification_target_ids", ()))
        != (
            GAMENET_END_CHAT_COMPOSE_FUNCTIONAL_TARGET_ID,
            HUD_UI_MESSAGE_REBUILD_WEAPON_ORDER_TARGET_ID,
        )
        or not isinstance(trace, Mapping)
        or trace.get("state") != "resolved"
        or trace.get("reason_code") not in {None, ""}
        or not isinstance(source_edges, list)
        or len(source_edges) != 1
        or not isinstance(source_edges[0], Mapping)
        or source_edges[0].get("relation") != "defines"
        or source_edges[0].get("anchor_id")
        != GAMENET_END_CHAT_COMPOSE_CALLER_ANCHOR_ID
        or source_edges[0].get("emission_context")
        != {"translation_unit": HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH}
        or definition is None
        or definition.symbol != GAMENET_END_CHAT_COMPOSE_CALLER_SYMBOL
        or definition.data != GAMENET_END_CHAT_COMPOSE_CANDIDATE_CODE
        or len(definition.relocation_mask) != len(definition.data)
        or target is None
        or getattr(target, "name", "") != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or Path(str(getattr(target, "manifest_path", ""))).resolve()
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_MANIFEST.resolve()
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
        or tuple(getattr(target, "source_files", ())).count(
            HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        )
        != 1
        or len(contribution_rows) != 1
        or not isinstance(tracker_target, Mapping)
        or tracker_target.get("binary") != "recoil"
        or tracker_target.get("kind") != "vc5"
        or tracker_target.get("name") != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or tuple(tracker_target.get("registered_addresses", ())).count(
            normalized_start
        )
        != 1
        or not isinstance(registration, Mapping)
        or registration.get("binary") != "recoil"
        or registration.get("name") != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or registration.get("manifest_path")
        != str(
            HUD_UI_MGR_INIT_LAYOUTS_TARGET_MANIFEST.relative_to(REPO_ROOT)
        ).replace("\\", "/")
        or registration.get("source_from")
        != HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        or registration.get("check_translation_unit_function_order") is not True
        or registration.get("function_order_scope") != "authored"
    ):
        raise ValueError(
            "GameNet end-chat strncat esi bridge requires the exact authored "
            "caller, source anchor/TU, extent, object symbol/body, and governed "
            "target authority"
        )

    contribution, contribution_row = contribution_rows[0]
    if (
        getattr(contribution, "source_from", "")
        != HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        or getattr(contribution, "order_scope", "") != "authored"
        or getattr(contribution_row, "symbol", "") != ""
        or getattr(contribution_row, "symbol_regex", None)
        != GAMENET_END_CHAT_COMPOSE_CONTRIBUTION_SYMBOL_RE
        or re.fullmatch(
            GAMENET_END_CHAT_COMPOSE_CONTRIBUTION_SYMBOL_RE,
            definition.symbol,
        )
        is None
        or getattr(contribution_row, "name", "")
        != "GameNet::EndChatComposeAndSend"
        or getattr(contribution_row, "pipeline_class", "") != "authored"
        or getattr(contribution_row, "authored_order_role", "")
        != "authored-body"
        or getattr(contribution_row, "required_presence", None) is not True
        or getattr(contribution_row, "full_order_gate", None) is not True
    ):
        raise ValueError(
            "GameNet end-chat strncat esi bridge rejects exact hud.cpp "
            "contribution-row authority drift"
        )

    iat_identity = "iat:strncat"
    retail_import, _directory_context = retail_import_target(
        reference=reference,
        address=GAMENET_END_CHAT_COMPOSE_STRNCAT_IAT_ADDRESS,
        dll="MSVCRT.dll",
        import_name="strncat",
    )
    indexed_iat_identities = (
        indexes.storage_by_address.get(
            GAMENET_END_CHAT_COMPOSE_STRNCAT_IAT_ADDRESS
        ),
        indexes.storage_by_name.get("strncat"),
        indexes.storage_by_name.get(
            GAMENET_END_CHAT_COMPOSE_STRNCAT_CANDIDATE_SYMBOL
        ),
    )
    if (
        retail_import.address != GAMENET_END_CHAT_COMPOSE_STRNCAT_IAT_ADDRESS
        or retail_import.dll != "MSVCRT.dll"
        or retail_import.import_name != "strncat"
        or retail_import.import_ordinal is not None
        or any(
            indexed_identity is not None and indexed_identity != iat_identity
            for indexed_identity in indexed_iat_identities
        )
    ):
        raise ValueError(
            "GameNet end-chat strncat esi bridge requires the exact immutable "
            "retail MSVCRT strncat IAT tuple and rejects conflicting indexed "
            "identity"
        )

    def instruction_bytes(instruction: Instruction) -> bytes:
        try:
            return bytes(int(value, 16) for value in instruction.bytes)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                "GameNet end-chat strncat esi bridge requires exact "
                "instruction bytes"
            ) from exc

    retail_addresses = _instruction_runtime_addresses(
        retail_instructions,
        source="bn",
        caller_start=address_value(normalized_start),
    )
    retail_offsets = tuple(
        address - address_value(normalized_start)
        for address in retail_addresses
        if address is not None
    )
    candidate_offsets = _candidate_complete_instruction_offsets(candidate)

    def require_contiguous_code(
        label: str,
        instructions: Sequence[Instruction],
        offsets: Sequence[int | None],
        expected: bytes,
    ) -> None:
        if (
            len(offsets) != len(instructions)
            or any(offset is None for offset in offsets)
            or not offsets
            or offsets[0] != 0
            or any(
                int(offsets[index])
                + len(instruction_bytes(instructions[index]))
                != int(offsets[index + 1])
                for index in range(len(offsets) - 1)
            )
            or int(offsets[-1]) + len(instruction_bytes(instructions[-1]))
            != len(expected)
            or b"".join(instruction_bytes(row) for row in instructions)
            != expected
        ):
            raise ValueError(
                "GameNet end-chat strncat esi bridge requires the exact "
                f"complete contiguous {label} instruction population and bytes"
            )

    require_contiguous_code(
        "retail",
        retail_instructions,
        retail_offsets,
        GAMENET_END_CHAT_COMPOSE_RETAIL_CODE,
    )
    require_contiguous_code(
        "candidate",
        candidate.instructions,
        candidate_offsets,
        GAMENET_END_CHAT_COMPOSE_CANDIDATE_CODE[:0xC5],
    )
    if candidate.local_control_flow_indices or candidate.local_control_flow_targets:
        raise ValueError(
            "GameNet end-chat strncat esi bridge rejects candidate local-switch "
            "CFG drift"
        )

    retail_invocation_indices = tuple(
        index
        for index, instruction in enumerate(retail_instructions)
        if _instruction_mnemonic(instruction) == "call"
    )
    candidate_invocation_indices = _candidate_static_invocation_indices(
        candidate,
        caller_start=normalized_start,
        caller_end_exclusive=caller_end_exclusive,
    )
    retail_invocations = tuple(
        retail_addresses[index] for index in retail_invocation_indices
    )
    candidate_invocations = tuple(
        candidate_offsets[index] for index in candidate_invocation_indices
    )
    cleanup_order = (None, None, None, 12, 12, None, 12, None, None)
    if (
        retail_invocations != GAMENET_END_CHAT_COMPOSE_RETAIL_CALL_ORDER
        or candidate_invocations
        != GAMENET_END_CHAT_COMPOSE_CANDIDATE_CALL_ORDER
        or tuple(
            _cleanup_after(retail_instructions, index)
            for index in retail_invocation_indices
        )
        != cleanup_order
        or tuple(
            _cleanup_after(candidate.instructions, index)
            for index in candidate_invocation_indices
        )
        != cleanup_order
    ):
        raise ValueError(
            "GameNet end-chat strncat esi bridge rejects complete nine-call "
            "population, order, form, or caller cleanup drift"
        )

    retail_by_offset = {
        offset: retail_instructions[index]
        for index, offset in enumerate(retail_offsets)
    }
    candidate_by_offset = {
        int(offset): candidate.instructions[index]
        for index, offset in enumerate(candidate_offsets)
        if offset is not None
    }
    load_and_calls = (
        (
            "retail",
            retail_instructions,
            retail_offsets,
            retail_by_offset,
            0x5B,
            (0x74, 0x9F),
            GAMENET_END_CHAT_COMPOSE_STRNCAT_IAT_ADDRESS,
            b"\x8b\x35\xf0\xc4\x4c\x00",
        ),
        (
            "candidate",
            candidate.instructions,
            candidate_offsets,
            candidate_by_offset,
            0x5F,
            (0x78, 0xA3),
            GAMENET_END_CHAT_COMPOSE_STRNCAT_CANDIDATE_SYMBOL,
            b"\x8b\x35\x00\x00\x00\x00",
        ),
    )
    for (
        label,
        instructions,
        offsets,
        by_offset,
        load_offset,
        call_offsets,
        storage_operand,
        load_body,
    ) in load_and_calls:
        load = by_offset.get(load_offset)
        calls = tuple(by_offset.get(offset) for offset in call_offsets)
        load_operand = (
            _exact_memory_expression(_instruction_operand(load).split(",", 1)[1])
            if load is not None and "," in _instruction_operand(load)
            else ""
        )
        if (
            load is None
            or _instruction_mnemonic(load) != "mov"
            or not _instruction_operand(load).lower().startswith("esi,")
            or load_operand != storage_operand.lower()
            or instruction_bytes(load) != load_body
            or any(call is None for call in calls)
            or any(
                _instruction_mnemonic(call) != "call"
                or _instruction_operand(call).lower() != "esi"
                or instruction_bytes(call) != b"\xff\xd6"
                for call in calls
                if call is not None
            )
        ):
            raise ValueError(
                "GameNet end-chat strncat esi bridge rejects exact "
                f"{label} load, storage, or two-call register form"
            )
        load_index = offsets.index(load_offset)
        last_call_index = offsets.index(call_offsets[-1])
        register_calls = [
            index
            for index, instruction in enumerate(instructions)
            if _instruction_mnemonic(instruction) == "call"
            and _instruction_operand(instruction).lower() == "esi"
        ]
        if (
            tuple(offsets[index] for index in register_calls) != call_offsets
            or any(
                _instruction_may_clobber_register(instruction, "esi")
                for instruction in instructions[load_index + 1 : last_call_index]
                if _instruction_mnemonic(instruction) != "call"
            )
        ):
            raise ValueError(
                "GameNet end-chat strncat esi bridge rejects clobbered, "
                f"ambiguous, or extra {label} register provenance"
            )

    expected_relocations = (
        (0x04, IMAGE_REL_I386_DIR32, "_g_GameStateOrMapTable", 0),
        (0x14, IMAGE_REL_I386_DIR32, HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL, 0xAB4),
        (0x19, IMAGE_REL_I386_REL32, "?BindMapContext_Pop@zInput@@YIXXZ", 0),
        (0x1E, IMAGE_REL_I386_REL32, "?Begin@HudUiMgrObjective@@YIXXZ", 0),
        (0x23, IMAGE_REL_I386_DIR32, HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL, 0xAB8),
        (0x28, IMAGE_REL_I386_REL32, "?GetBuffer@HudUiTextInput@@QAEPADXZ", 0),
        (0x4B, IMAGE_REL_I386_DIR32, "__imp__strncpy", 0),
        (
            0x61,
            IMAGE_REL_I386_DIR32,
            GAMENET_END_CHAT_COMPOSE_STRNCAT_CANDIDATE_SYMBOL,
            0,
        ),
        (0x73, IMAGE_REL_I386_DIR32, "?g_HudUiMessage_SeparatorColon@@3PADA", 0),
        (0x93, IMAGE_REL_I386_DIR32, HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL, 0xAB8),
        (0x99, IMAGE_REL_I386_REL32, "?GetBuffer@HudUiTextInput@@QAEPADXZ", 0),
        (0xB2, IMAGE_REL_I386_REL32, "?ShowChatLine@HudUi@@YIXPBDM@Z", 0),
        (
            0xBB,
            IMAGE_REL_I386_REL32,
            "?SendPkt0B_ChatMessage@GameNet@@YIXPBD@Z",
            0,
        ),
    )
    actual_relocations = tuple(
        (
            row.offset,
            row.type,
            row.symbol_name,
            struct.unpack_from("<I", definition.data, row.offset)[0],
        )
        for row in definition.relocations
    )
    expected_mask = {
        index
        for offset, _type, _symbol, _addend in expected_relocations
        for index in range(offset, offset + 4)
    }
    expected_defined_function_names = {
        "?Begin@HudUiMgrObjective@@YIXXZ",
        "?ShowChatLine@HudUi@@YIXPBDM@Z",
    }
    expected_undefined_function_names = {
        symbol
        for _offset, relocation_type, symbol, _addend in expected_relocations
        if relocation_type == IMAGE_REL_I386_REL32
        or symbol.startswith("__imp__")
    } - expected_defined_function_names
    expected_data_names = {
        symbol
        for _offset, relocation_type, symbol, _addend in expected_relocations
        if relocation_type == IMAGE_REL_I386_DIR32
        and not symbol.startswith("__imp__")
    }
    if (
        actual_relocations != expected_relocations
        or {
            index
            for index, masked in enumerate(definition.relocation_mask)
            if masked
        }
        != expected_mask
        or any(
            definition.undefined_external_functions.count(name) != 1
            or name in definition.defined_external_functions
            or name in definition.undefined_external_data
            or name in definition.defined_external_data
            for name in expected_undefined_function_names
        )
        or any(
            definition.defined_external_functions.count(name) != 1
            or name in definition.undefined_external_functions
            or name in definition.undefined_external_data
            or name in definition.defined_external_data
            for name in expected_defined_function_names
        )
        or any(
            definition.undefined_external_data.count(name) != 1
            or name in definition.defined_external_data
            or name in definition.undefined_external_functions
            or name in definition.defined_external_functions
            for name in expected_data_names
        )
    ):
        raise CandidateCallContractEvidenceError(
            "GameNet end-chat strncat esi bridge requires the exact thirteen "
            "candidate DIR32/REL32 relocations, addends, masks, and external "
            "symbol provenance"
        )

    # Publish the immutable retail route only in this comparison-scoped view,
    # then require the generic candidate exact-IAT producer to re-prove the
    # COD/COFF definition and every reached register transfer.  The reviewed
    # name bridge alone must not bypass the schema-27 path-sensitive
    # multi-call, kill, join, partial-register, mixed-use, or unresolved-CFG
    # gates.
    proof_storage_by_address = dict(indexes.storage_by_address)
    proof_storage_by_name = dict(indexes.storage_by_name)
    for mapping, key in (
        (
            proof_storage_by_address,
            GAMENET_END_CHAT_COMPOSE_STRNCAT_IAT_ADDRESS,
        ),
        (proof_storage_by_name, "strncat"),
    ):
        prior = mapping.get(key)
        if prior is not None and prior != iat_identity:
            raise ValueError(
                "GameNet end-chat strncat typed proof conflicts with the "
                f"immutable retail identity for {key!r}"
            )
        mapping[key] = iat_identity
    proof_indexes = replace(
        indexes,
        storage_by_address=proof_storage_by_address,
        storage_by_name=proof_storage_by_name,
    )
    candidate_iat_proofs = _candidate_exact_iat_register_load_proofs(
        candidate,
        indexes=proof_indexes,
        retail_import_targets=(retail_import,),
    )
    expected_candidate_proof = CandidateExactIatRegisterLoadProof(
        definition_offset="0x5f",
        destination="esi",
        object_symbol=GAMENET_END_CHAT_COMPOSE_STRNCAT_CANDIDATE_SYMBOL,
        identity=iat_identity,
        transfer_offsets=("0x78", "0xa3"),
    )
    if candidate_iat_proofs != {"0x5f": expected_candidate_proof}:
        raise CandidateCallContractEvidenceError(
            "GameNet end-chat strncat bridge requires one exact typed "
            "candidate IAT definition with its complete two-call CFG lifetime"
        )

    retail_bridges = {
        GAMENET_END_CHAT_COMPOSE_STRNCAT_IAT_ADDRESS: iat_identity,
    }
    candidate_bridges = {
        GAMENET_END_CHAT_COMPOSE_STRNCAT_CANDIDATE_SYMBOL: iat_identity,
    }
    candidate_names = dict(indexes.by_candidate_name)
    for direct_address, candidate_name in GAMENET_END_CHAT_COMPOSE_DIRECT_TARGETS:
        direct_identity = f"symbol:recoil:function:{direct_address}"
        indexed_name_identity = candidate_names.get(candidate_name)
        if (
            indexes.by_address.get(direct_address) != direct_identity
            or direct_identity in indexes.provider_ids
            or (
                indexed_name_identity is not None
                and indexed_name_identity != direct_identity
            )
        ):
            raise ValueError(
                "GameNet end-chat strncat esi bridge requires exact reviewed "
                "retail-address identities for every candidate direct-call name"
            )
        candidate_names[candidate_name] = direct_identity
    candidate_indexes = replace(
        proof_indexes,
        by_candidate_name=candidate_names,
    )
    expected_contract = extract_invocation_contract(
        retail_instructions,
        source="bn",
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
        indexes=indexes,
        bridge_names=bridge_names,
        reviewed_register_storage_bridges=retail_bridges,
    )
    candidate_contract = extract_invocation_contract(
        candidate.instructions,
        source="cod",
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
        indexes=candidate_indexes,
        bridge_names=bridge_names,
        reviewed_register_storage_bridges=candidate_bridges,
        reviewed_iat_register_definition_offsets=frozenset(
            candidate_iat_proofs
        ),
        candidate_exact_iat_register_load_proofs=candidate_iat_proofs,
        local_control_flow_indices=candidate.local_control_flow_indices,
        local_control_flow_targets=candidate.local_control_flow_targets,
    )
    required_rows = {
        ordinal: {
            "ordinal": ordinal,
            "form": "call",
            "dispatch": "indirect",
            "identity_kind": "iat",
            "target_identity": iat_identity,
            "storage_identity": iat_identity,
            "slot_displacement": None,
            "cleanup_bytes": 12,
        }
        for ordinal in (4, 6)
    }
    if (
        expected_contract != candidate_contract
        or len(expected_contract) != 9
        or any(
            expected_contract[ordinal] != required_row
            for ordinal, required_row in required_rows.items()
        )
        or sum(
            row.get("target_identity") == iat_identity
            for row in expected_contract
        )
        != 2
        or sum(
            row.get("target_identity") == iat_identity
            for row in candidate_contract
        )
        != 2
    ):
        raise ValueError(
            "GameNet end-chat strncat esi bridge cannot derive the exact "
            "candidate-independent retail and candidate nine-call contract"
        )
    return retail_bridges, candidate_bridges


RECOIL_MAIN_MENU_TRANSITION_CALLER_START = "0x415220"
RECOIL_MAIN_MENU_TRANSITION_CALLER_END_EXCLUSIVE = "0x415370"
RECOIL_MAIN_MENU_TRANSITION_CALLER_IDENTITY = "symbol:recoil:function:0x415220"
RECOIL_MAIN_MENU_TRANSITION_CALLER_SYMBOL = (
    "?OnTryBecomeCurrent@RecoilStateMainMenuTransition@@UAEHXZ"
)
RECOIL_MAIN_MENU_TRANSITION_CALLER_ANCHOR_ID = (
    "recoil:anchor:battlesport.hud."
    "recoilstatemainmenutransition-ontrybecomecurrent"
)
RECOIL_MAIN_MENU_TRANSITION_VERIFICATION_TARGET_IDS = (
    "recoil:functional-target:"
    "recoil_state_main_menu_transition_on_try_become_current",
    "recoil:vc5-target:hud_404ca0_415ab0_authored_order",
    "recoil:vc5-target:"
    "recoil_state_main_menu_transition_on_try_become_current",
)
