def _player_ob1_require_pointer_vector_helpers(
    candidate: CandidateAssembly,
) -> None:
    ucopy = (
        "?_Ucopy@?$vector@PAUzInput_BindGroupInfo@@"
        "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@"
        "IAEPAPAUzInput_BindGroupInfo@@PBQAU3@0PAPAU3@@Z"
    )
    ufill = (
        "?_Ufill@?$vector@PAUzInput_BindGroupInfo@@"
        "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@"
        "IAEXPAPAUzInput_BindGroupInfo@@IABQAU3@@Z"
    )
    destroy = (
        "?_Destroy@?$vector@PAUzInput_BindGroupInfo@@"
        "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@"
        "IAEXPAPAUzInput_BindGroupInfo@@0@Z"
    )
    size = (
        "?size@?$vector@PAUzInput_BindGroupInfo@@"
        "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@QBEIXZ"
    )
    definitions = (
        (ucopy, bytes.fromhex(
            "8b4c24048b5424083bca741b8b44240c5685c074048b31893083c10483c004"
            "3bca75ee5ec20c008b44240cc20c00" + "90" * 2
        )),
        (ufill, bytes.fromhex(
            "8b4c240885c976188b54240c8b4424045685c074048b32893083c0044975f2"
            "5ec20c00" + "90" * 13
        )),
        (destroy, b"\xc2\x08\x00" + b"\x90" * 13),
        (size, bytes.fromhex(
            "8b510485d2750333c0c38b41082bc2c1f802c3" + "90" * 13
        )),
    )
    for name, body in definitions:
        _player_ob1_require_helper_definition(
            candidate,
            name=name,
            body=body,
            selection=2,
            source_suffix="/VC/INCLUDE/vector",
        )
    caller = candidate.caller_definition
    if caller is None:
        raise ValueError("Player /Ob1 pointer-vector helper graph lacks caller")
    helper_names = {name for name, _body in definitions}
    actual_pointer_vector_helpers = {
        name
        for name in candidate.tu_local_function_definitions
        if "?$vector@PAUzInput_BindGroupInfo@@" in name
    }
    occurrences = Counter(
        relocation.symbol_name
        for relocation in caller.relocations
        if relocation.symbol_name in helper_names
    )
    if (
        actual_pointer_vector_helpers != helper_names
        or occurrences != Counter({
            ucopy: 4, ufill: 2, destroy: 1, size: 1
        })
    ):
        raise ValueError(
            "Player /Ob1 pointer-vector helper graph rejects unique helper "
            "identity or complete occurrence population drift"
        )
    forbidden = (
        "??0zInput_BindGroupInfo@@QAE@XZ",
        "?_Construct@std@@YIXPAPAUzInput_BindGroupInfo@@"
        "ABQAU2@@Z",
    )
    if any(
        name in candidate.tu_local_function_definitions
        or any(row.symbol_name == name for row in caller.relocations)
        for name in forbidden
    ):
        raise ValueError(
            "Player /Ob1 pointer-vector helper graph rejects retired local "
            "record-constructor or single-value _Construct interpretation"
        )


def _player_ob1_finite_identity_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Qualify only unchanged semantic rows from exact finite `/Ob1` packages."""

    spec = _player_ob1_require_exact_caller_package(
        candidate,
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
    )
    if spec is None:
        return [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) in {"0x41eb30", "0x41eb90",
                                           "0x41ec40", "0x41ec90"}:
        # Those four rows are qualified by their dedicated retail-target
        # bridges, which also prove their nested constructor package.
        return [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) == "0x420c60":
        _player_ob1_require_cstring_recursive_helpers(candidate)
    elif normalize_address(caller_start) == "0x42a070":
        _player_ob1_require_pointer_vector_helpers(candidate)
    elif normalize_address(caller_start) == "0x42a2c0":
        _player_ob1_require_int_vector_helpers(candidate)
    expected_rows = [dict(row) for row in expected]
    candidate_rows = [dict(row) for row in candidate_contract]
    count = int(spec["contract_count"])
    dispatches = tuple(
        spec.get("contract_dispatches", ("direct",) * count)
    )
    if (
        len(expected_rows) != count
        or len(candidate_rows) != count
        or expected_rows != candidate_rows
        or len(dispatches) != count
        or any(row.get("ordinal") != ordinal
               for ordinal, row in enumerate(expected_rows))
        or any(
            row.get("form") != call[1]
            or row.get("dispatch") != dispatch
            or row.get("cleanup_bytes") != call[3]
            for row, call, dispatch in zip(
                expected_rows, spec["calls"], dispatches
            )
        )
    ):
        raise ValueError(
            f"Player /Ob1 finite caller profile {caller_start} rejects "
            "immutable retail cardinality/identity/form/order or candidate "
            "row deletion, reorder, substitution, dispatch, or cleanup drift"
        )
    retail_identities = tuple(spec.get("retail_identities", ()))
    if retail_identities and tuple(
        row.get("target_identity") for row in expected_rows
    ) != retail_identities:
        raise ValueError(
            f"Player /Ob1 finite caller profile {caller_start} rejects "
            "immutable retail target identity drift"
        )
    retail_identity_kinds = tuple(spec.get("retail_identity_kinds", ()))
    if retail_identity_kinds and tuple(
        row.get("identity_kind") for row in expected_rows
    ) != retail_identity_kinds:
        raise ValueError(
            f"Player /Ob1 finite caller profile {caller_start} rejects "
            "immutable retail identity-kind drift"
        )
    if normalize_address(caller_start) in {"0x42a070", "0x42a2c0"} and (
        expected_rows[4].get("identity_kind") != "provider"
        or expected_rows[4].get("dispatch") != "direct"
    ):
        raise ValueError(
            "Player /Ob1 vector profile requires the exact reviewed "
            "compiler-provider identity at physical ordinal 4"
        )
    return candidate_rows


def _player_ob1_finite_provider_comdat_map(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge: BinaryNinjaBridge,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> dict[str, str]:
    """Authenticate exact finite `/Ob1` COMDATs against retail bodies."""

    spec = _player_ob1_require_exact_caller_package(
        candidate,
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
    )
    address = normalize_address(caller_start)
    if spec is None or address not in {"0x42a070", "0x42a2c0"}:
        return {}
    pointer = address == "0x42a070"
    if pointer:
        _player_ob1_require_pointer_vector_helpers(candidate)
        ucopy = (
            "?_Ucopy@?$vector@PAUzInput_BindGroupInfo@@"
            "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@"
            "IAEPAPAUzInput_BindGroupInfo@@PBQAU3@0PAPAU3@@Z"
        )
        ufill = (
            "?_Ufill@?$vector@PAUzInput_BindGroupInfo@@"
            "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@"
            "IAEXPAPAUzInput_BindGroupInfo@@IABQAU3@@Z"
        )
        destroy = (
            "?_Destroy@?$vector@PAUzInput_BindGroupInfo@@"
            "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@"
            "IAEXPAPAUzInput_BindGroupInfo@@0@Z"
        )
        size = (
            "?size@?$vector@PAUzInput_BindGroupInfo@@"
            "V?$allocator@PAUzInput_BindGroupInfo@@@std@@@std@@QBEIXZ"
        )
        provider_specs = (
            (ucopy, "provider:recoil:function:0x48bf10", "0x48bf10",
             bytes.fromhex(
                 "8b4c24048b5424083bca741b8b44240c5685c074048b31893083c10483c004"
                 "3bca75ee5ec20c008b44240cc20c00" + "90" * 2
             )),
            (ufill, "provider:recoil:function:0x40c190", "0x40c190",
             bytes.fromhex(
                 "8b4c240885c976188b54240c8b4424045685c074048b32893083c0044975f2"
                 "5ec20c00" + "90" * 13
             )),
            (destroy, "provider:recoil:function:0x40bdf0", "0x40bdf0",
             b"\xc2\x08\x00" + b"\x90" * 13),
            (size, "provider:recoil:function:0x42a9d0", "0x42a9d0",
             bytes.fromhex(
                 "8b510485d2750333c0c38b41082bc2c1f802c3" + "90" * 13
             )),
        )
    else:
        _player_ob1_require_int_vector_helpers(candidate)
        construct = "?_Construct@std@@YIXPAHABH@Z"
        ufill = (
            "?_Ufill@?$vector@HV?$allocator@H@std@@@std@@IAEXPAHIABH@Z"
        )
        ucopy = (
            "?_Ucopy@?$vector@HV?$allocator@H@std@@@std@@"
            "IAEPAHPBH0PAH@Z"
        )
        destroy = (
            "?_Destroy@?$vector@HV?$allocator@H@std@@@std@@IAEXPAH0@Z"
        )
        provider_specs = (
            (construct, "provider:recoil:function:0x40c1c0", "0x40c1c0",
             bytes.fromhex("85c974048b028901c3" + "90" * 7)),
            (ufill, "provider:recoil:function:0x40c190", "0x40c190",
             bytes.fromhex(
                 "8b4c240885c976188b54240c8b4424045685c074048b32893083c0044975f2"
                 "5ec20c00" + "90" * 13
             )),
            (ucopy, "provider:recoil:function:0x48bf10", "0x48bf10",
             bytes.fromhex(
                 "8b4c24048b5424083bca741b8b44240c5685c074048b31893083c10483c004"
                 "3bca75ee5ec20c008b44240cc20c00" + "90" * 2
             )),
            (destroy, "provider:recoil:function:0x40bdf0", "0x40bdf0",
             b"\xc2\x08\x00" + b"\x90" * 13),
        )

    rows = [dict(row) for row in candidate_contract]
    symbols = document.collection("symbols")
    result: dict[str, str] = {}
    for name, identity, retail_address, retail_body in provider_specs:
        matching_candidate = [
            row
            for row in rows
            if row.get("target_identity")
            in {f"candidate-local-coff:{name}", identity}
            and 0 <= int(row.get("ordinal", -1)) < len(expected)
        ]
        matching_expected = [
            expected[int(row["ordinal"])] for row in matching_candidate
        ]
        physical = symbols.get(identity.removeprefix("provider:"))
        retail_end = hex(address_value(retail_address) + len(retail_body))
        if (
            not matching_candidate
            or any(
                row.get("form") != "call"
                or row.get("dispatch") != "direct"
                or (
                    row.get("target_identity") == identity
                    and row.get("identity_kind") != "provider"
                )
                for row in matching_candidate
            )
            or any(
                row.get("form") != "call"
                or row.get("dispatch") != "direct"
                or row.get("identity_kind") != "provider"
                or row.get("target_identity") != identity
                or row.get("storage_identity") != ""
                or row.get("slot_displacement") is not None
                for row in matching_expected
            )
            or identity not in indexes.provider_ids
            or indexes.by_address.get(retail_address) != identity
            or not isinstance(physical, Mapping)
            or physical.get("binary") != "recoil"
            or physical.get("pipeline_class") != "non-authored"
            or physical.get("extent_state") != "known"
            or normalize_address(str(physical.get("address", "")))
            != retail_address
            or normalize_address(str(physical.get("end_exclusive", "")))
            != retail_end
            or physical.get("size") != len(retail_body)
            or physical.get("output_section_id") != "recoil:section:.text"
            or _hexdump_bytes(
                bridge.hexdump(retail_address, len(retail_body))
            ) != retail_body
        ):
            raise ValueError(
                "Player /Ob1 finite provider COMDAT map rejects immutable "
                f"retail identity/body/extent or expected-row drift for {name!r}: "
                f"expected_rows={tuple(dict(row) for row in matching_expected)!r}, "
                f"required_identity={identity!r}, retail_address={retail_address!r}"
            )
        result[name] = identity
    return result


def _player_hud_ui_panel_default_constructor_candidate_bridge(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
) -> dict[str, str]:
    """Bind two exact Player global-panel wrappers to retail ctor truth."""

    name = "?ConstructorDefault@HudUiPanel@@QAEPAU1@PBDHH@Z"
    profiles = {
        (
            "symbol:recoil:function:0x41ec40",
            "0x41ec40",
            "0x41ec60",
        ): (
            "?Constructor@Player_TopMsgPanel1@@YAXXZ",
            "_g_Player_TopMsgPanel1",
        ),
        (
            "symbol:recoil:function:0x41ec90",
            "0x41ec90",
            "0x41ecb0",
        ): (
            "?Constructor@Player_TopMsgPanel2@@YAXXZ",
            "_g_Player_TopMsgPanel2",
        ),
    }
    profile = profiles.get(
        (
            caller_identity,
            normalize_address(caller_start),
            normalize_address(caller_end_exclusive),
        )
    )
    if profile is None:
        return {}
    prefix = "Player HudUiPanel default-constructor bridge"
    caller_symbol, storage_symbol = profile
    target_symbol_id = "recoil:function:0x4ba740"
    target_identity = f"symbol:{target_symbol_id}"
    target = document.collection("symbols").get(target_symbol_id)
    exact_expected = [{
        "ordinal": 0,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "direct",
        "target_identity": target_identity,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }]
    if (
        [dict(row) for row in expected] != exact_expected
        or indexes.by_address.get("0x4ba740") != target_identity
        or target_identity in indexes.provider_ids
        or not isinstance(target, Mapping)
        or _symbol_identity(target_symbol_id, target) != target_identity
        or target.get("binary") != "recoil"
        or target.get("kind") != "function"
        or target.get("address") != "0x4ba740"
        or target.get("end_exclusive") != "0x4ba830"
        or target.get("size") != 0xF0
        or target.get("extent_state") != "known"
        or target.get("pipeline_class") != "authored"
        or target.get("ownership_state") != "primary-owned"
        or target.get("navigation_name")
        != "HudUiPanel::ConstructorDefault"
    ):
        raise ValueError(f"{prefix} rejects immutable retail authority drift")

    if _player_ob1_finite_profile_active(candidate):
        spec = _player_ob1_require_exact_caller_package(
            candidate,
            caller_identity=caller_identity,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
        )
        if spec is None:
            raise ValueError(f"{prefix} lacks its exact /Ob1 caller profile")
        base_constructor = "??0HudUiPanel@@QAE@PBDHH@Z"
        return {base_constructor: target_identity}

    caller = candidate.caller_definition
    definition = candidate.tu_local_function_definitions.get(name)
    caller_relocations = (
        sorted(caller.relocations, key=lambda row: row.offset)
        if caller is not None else []
    )
    definition_relocations = (
        tuple(definition.relocations) if definition is not None else ()
    )
    if (
        caller is None
        or caller.symbol != caller_symbol
        or caller.data
        != b"\x6a\x00\x6a\x00\x6a\x00\xb9\x00\x00\x00\x00"
        + b"\xe8\x00\x00\x00\x00\xc3"
        + b"\x90" * 15
        or caller.relocation_mask
        != (False,) * 7 + (True,) * 4 + (False,) + (True,) * 4
        + (False,) * 16
        or len(caller_relocations) != 2
        or caller_relocations[0].offset != 7
        or caller_relocations[0].type != IMAGE_REL_I386_DIR32
        or caller_relocations[0].symbol_name != storage_symbol
        or caller_relocations[1].offset != 0x0C
        or caller_relocations[1].type != IMAGE_REL_I386_REL32
        or caller_relocations[1].symbol_name != name
        or caller_relocations[0].symbol_index
        == caller_relocations[1].symbol_index
        or definition is None
        or definition.symbol != name
        or not definition.section_is_comdat
        or definition.comdat_selection != 2
        or definition.section_external_functions != (name,)
        or definition.section_size != 0x40
        or definition.data
        != bytes.fromhex(
            "568bf15668a4020000e80000000083c40885c07416"
            "8b4c24108b54240c518b4c240c52518bc8e800000000"
            "8bc65ec20c00"
        )
        + b"\x90" * 15
        or definition.relocation_mask
        != (False,) * 10 + (True,) * 4 + (False,) * 25
        + (True,) * 4 + (False,) * 21
        or len(definition_relocations) != 2
        or definition_relocations[0].offset != 0x0A
        or definition_relocations[0].type != IMAGE_REL_I386_REL32
        or definition_relocations[0].symbol_name != "??2@YAPAXIPAX@Z"
        or definition_relocations[1].offset != 0x27
        or definition_relocations[1].type != IMAGE_REL_I386_REL32
        or definition_relocations[1].symbol_name
        != "??0HudUiPanel@@QAE@PBDHH@Z"
        or definition_relocations[0].symbol_index
        == definition_relocations[1].symbol_index
        or definition.local_control_flow_indices != frozenset()
        or bool(definition.local_control_flow_targets)
        or not definition.source_provenance.replace("\\", "/").endswith(
            "/src/GameZRecoil/zHud/zhud_ui.h"
        )
    ):
        raise ValueError(
            f"{prefix} requires exact caller and nested placement/constructor "
            "COD/COFF packages"
        )
    invocation_indices = _candidate_static_invocation_indices(
        candidate,
        caller_start="0x0",
        caller_end_exclusive="0x20",
    )
    offsets = _candidate_complete_instruction_offsets(candidate)
    if (
        len(invocation_indices) != 1
        or offsets[invocation_indices[0]] != 0x0B
        or _instruction_mnemonic(
            candidate.instructions[invocation_indices[0]]
        ) != "call"
        or _instruction_operand(
            candidate.instructions[invocation_indices[0]]
        ).strip() != name
        or _cleanup_after(candidate.instructions, invocation_indices[0])
        is not None
    ):
        raise ValueError(f"{prefix} rejects candidate invocation drift")
    return {name: target_identity}


def _player_pass3_constructor_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Collapse two exact placement/default-ctor graphs to retail ctor truth."""

    profiles = {
        (
            "symbol:recoil:function:0x41eb30",
            "0x41eb30",
            "0x41eb50",
        ): (
            "?Constructor@Player_UnderwaterFxPass3Ui@@QAEPAU1@XZ",
            "??0Player_UnderwaterFxPass3Ui@@QAE@XZ",
            "??_7Player_UnderwaterFxPass3Ui@@6B@",
        ),
        (
            "symbol:recoil:function:0x41eb90",
            "0x41eb90",
            "0x41ebb0",
        ): (
            "?Constructor@Player_ProjectileCameraFxPass3Ui@@QAEPAU1@XZ",
            "??0Player_ProjectileCameraFxPass3Ui@@QAE@XZ",
            "??_7Player_ProjectileCameraFxPass3Ui@@6B@",
        ),
    }
    profile = profiles.get(
        (
            caller_identity,
            normalize_address(caller_start),
            normalize_address(caller_end_exclusive),
        )
    )
    if profile is None:
        return [dict(row) for row in candidate_contract]
    prefix = "Player pass-3 constructor graph projection"
    caller_symbol, derived_name, derived_vftable = profile
    target_symbol_id = "recoil:function:0x4b4070"
    target_identity = f"symbol:{target_symbol_id}"
    target = document.collection("symbols").get(target_symbol_id)
    exact_expected = [{
        "ordinal": 0,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "direct",
        "target_identity": target_identity,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }]
    exact_candidate = [
        {
            "ordinal": 0,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": "candidate-local-coff:??2@YAPAXIPAX@Z",
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": 8,
        },
        {
            "ordinal": 1,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": f"candidate-local-coff:{derived_name}",
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        },
    ]
    if (
        [dict(row) for row in expected] != exact_expected
        or not isinstance(target, Mapping)
        or _symbol_identity(target_symbol_id, target) != target_identity
        or target.get("binary") != "recoil"
        or target.get("kind") != "function"
        or target.get("address") != "0x4b4070"
        or target.get("end_exclusive") != "0x4b40c0"
        or target.get("size") != 0x50
        or target.get("extent_state") != "known"
        or target.get("pipeline_class") != "authored"
        or target.get("ownership_state") != "primary-owned"
        or target.get("navigation_name") != "HudUiElement::Constructor"
    ):
        raise ValueError(f"{prefix} rejects contract or retail authority drift")

    if _player_ob1_finite_profile_active(candidate):
        spec = _player_ob1_require_exact_caller_package(
            candidate,
            caller_identity=caller_identity,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
        )
        exact_ob1_candidate = [{
            "ordinal": 0,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": f"candidate-local-coff:{derived_name}",
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        }]
        if (
            spec is None
            or [dict(row) for row in candidate_contract]
            != exact_ob1_candidate
        ):
            raise ValueError(
                f"{prefix} rejects exact /Ob1 identity-preserving row"
            )
        _player_ob1_require_pass3_helper(
            candidate, derived_name, derived_vftable
        )
        return [dict(row) for row in expected]

    if [dict(row) for row in candidate_contract] != exact_candidate:
        raise ValueError(f"{prefix} rejects contract or retail authority drift")

    caller = candidate.caller_definition
    placement = candidate.tu_local_function_definitions.get(
        "??2@YAPAXIPAX@Z"
    )
    derived = candidate.tu_local_function_definitions.get(derived_name)
    video_name = "??0zVideoFxPass3Element@@QAE@HH@Z"
    video = candidate.tu_local_function_definitions.get(video_name)
    caller_relocations = (
        sorted(caller.relocations, key=lambda row: row.offset)
        if caller is not None else []
    )
    if (
        caller is None
        or caller.symbol != caller_symbol
        or caller.data
        != bytes.fromhex(
            "568bf1566a38e80000000083c40885c074078bc8e800000000"
            "8bc65ec3"
        )
        + b"\x90" * 3
        or caller.relocation_mask
        != (False,) * 7 + (True,) * 4 + (False,) * 10
        + (True,) * 4 + (False,) * 7
        or len(caller_relocations) != 2
        or caller_relocations[0].offset != 7
        or caller_relocations[0].type != IMAGE_REL_I386_REL32
        or caller_relocations[0].symbol_name != "??2@YAPAXIPAX@Z"
        or caller_relocations[1].offset != 0x15
        or caller_relocations[1].type != IMAGE_REL_I386_REL32
        or caller_relocations[1].symbol_name != derived_name
        or caller_relocations[0].symbol_index
        == caller_relocations[1].symbol_index
        or placement is None
        or placement.symbol != "??2@YAPAXIPAX@Z"
        or placement.data
        != b"\x8b\x44\x24\x08\xc3" + b"\x90" * 11
        or placement.relocations != ()
        or any(placement.relocation_mask)
        or placement.section_size != 0x10
        or not placement.section_is_comdat
        or placement.comdat_selection != 2
        or placement.section_external_functions != (placement.symbol,)
        or derived is None
        or derived.symbol != derived_name
        or derived.data
        != bytes.fromhex(
            "566a008bf16a00e800000000c706000000008bc65ec3"
        )
        + b"\x90" * 10
        or derived.section_size != 0x20
        or not derived.section_is_comdat
        or derived.comdat_selection != 1
        or derived.section_external_functions != (derived_name,)
        or tuple(
            (row.offset, row.type, row.symbol_name)
            for row in derived.relocations
        ) != (
            (8, IMAGE_REL_I386_REL32, video_name),
            (0x0E, IMAGE_REL_I386_DIR32, derived_vftable),
        )
        or video is None
        or video.symbol != video_name
        or video.data
        != bytes.fromhex(
            "8b442408568bf1508b4c240c518bcee800000000"
            "c70600000000c74634000000008bc65ec20800"
        )
        + b"\x90" * 9
        or video.section_size != 0x30
        or not video.section_is_comdat
        or video.comdat_selection != 2
        or video.section_external_functions != (video_name,)
        or tuple(
            (row.offset, row.type, row.symbol_name)
            for row in video.relocations
        ) != (
            (0x10, IMAGE_REL_I386_REL32, "??0HudUiElement@@QAE@HH@Z"),
            (0x16, IMAGE_REL_I386_DIR32, "??_7zVideoFxPass3Element@@6B@"),
        )
        or caller.undefined_external_functions.count(
            "??0HudUiElement@@QAE@HH@Z"
        ) != 1
        or not placement.source_provenance.replace("\\", "/").endswith(
            "/src/Battlesport/player.cpp"
        )
        or not derived.source_provenance.replace("\\", "/").endswith(
            "/src/Battlesport/player.cpp"
        )
        or not video.source_provenance.replace("\\", "/").endswith(
            "/src/GameZRecoil/zVideo/zvid_fx_pass3.h"
        )
    ):
        raise ValueError(
            f"{prefix} requires exact placement, derived, and base "
            "constructor COD/COFF packages"
        )
    return exact_expected


