        (0x24, IMAGE_REL_I386_DIR32, RECOIL_APP_MP_EXIT_DIALOG_OBJECT_SYMBOL),
        (0x30, IMAGE_REL_I386_DIR32, local_constant_sentinel),
        (0x47, IMAGE_REL_I386_REL32, "?GetMessageString@zLoc@@YIPADI@Z"),
        (0x74, IMAGE_REL_I386_REL32, "?GetMessageString@zLoc@@YIPADI@Z"),
        (
            0x9F,
            IMAGE_REL_I386_REL32,
            RECOIL_APP_MP_EXIT_UPDATE_SHOULD_QUIT_FLIP_TO_GDI_SYMBOL,
        ),
        (
            0xA4,
            IMAGE_REL_I386_REL32,
            RECOIL_APP_MP_EXIT_UPDATE_SHOULD_QUIT_SHUTDOWN_SYMBOL,
        ),
        (
            0xA9,
            IMAGE_REL_I386_REL32,
            RECOIL_APP_MP_EXIT_UPDATE_SHOULD_QUIT_SESSION_SHUTDOWN_SYMBOL,
        ),
        (
            0xAE,
            IMAGE_REL_I386_REL32,
            RECOIL_APP_MP_EXIT_UPDATE_SHOULD_QUIT_VIDEO_SHUTDOWN_SYMBOL,
        ),
        (0xC0, IMAGE_REL_I386_DIR32, "??_C@_07OEOL@?$CFs?3?5?$CFs?6?$AA@"),
