_ZNETWORK_DISPATCH_LIST_OBJECT_SYMBOL = (
    "_g_zNetwork_DispatchHandlerList"
)
_ZNETWORK_DISPATCH_CANDIDATE_BODY = bytes.fromhex(
    "53 8b 1d 04 00 00 00 55 56 8b 33 33 c0 3b f3 57 "
    "0f 95 c0 84 c0 8b fa 8b e9 74 1f 8b 46 08 66 8b "
    "08 66 3b 0f 75 07 8b d7 8b cd ff 50 04 8b 36 33 "
    "c0 3b f3 0f 95 c0 84 c0 75 e1 5f 5e 5d 5b c3 90"
)
_ZNETWORK_PUMP_SWITCH_CLASSIFIER = bytes(
    {
        0: 0,
        208: 1,
        209: 2,
        210: 3,
        211: 4,
        220: 5,
    }.get(index, 6)
    for index in range(221)
)
_ZNETWORK_PUMP_SWITCH_LABELS = (
    ("$L27805", 0x1D4),
    ("$L27807", 0x1F7),
    ("$L27808", 0x20B),
    ("$L27809", 0x214),
    ("$L27810", 0x240),
    ("$L27812", 0x25D),
    ("$L27814", 0x25),
)


def _retail_call_contract_comparison_end_exclusive(
    retail_instructions: Sequence[Instruction],
    *,
    caller_start: str,
    caller_end_exclusive: str,
) -> str:
    """Return the finite executable comparison end for one retail caller.

    The tracker extent remains the physical/function byte envelope.  One
    reviewed zNetwork body owns non-executed alignment, switch-table, case-map,
    and padding bytes after its terminal RET, so its invocation comparison must
    use the independently complete BN instruction population instead.  Every
    other caller retains its tracker extent unchanged.
    """

    start = normalize_address(caller_start)
    envelope_end = normalize_address(caller_end_exclusive)
    if start != _ZNETWORK_OPEN_SELECTED_SESSION_START:
        return envelope_end
    if envelope_end != _ZNETWORK_OPEN_SELECTED_SESSION_ENVELOPE_END:
        raise ValueError(
            "zNetwork OpenSelectedSession tracker byte envelope drifted"
        )

    spans: list[tuple[int, int, Instruction, bytes]] = []
    for instruction in retail_instructions:
        raw_address = _source_instruction_address(instruction)
        if raw_address is None:
            raise ValueError(
                "zNetwork OpenSelectedSession execution extent requires "
                "complete address-labelled BN instruction rows"
            )
        try:
            address = address_value(normalize_address(raw_address))
            body = bytes(int(item, 16) for item in instruction.bytes)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                "zNetwork OpenSelectedSession execution extent requires "
                "complete BN instruction bytes"
            ) from exc
        instruction_end = address + len(body)
        if (
            not body
            or address < address_value(start)
            or instruction_end > address_value(envelope_end)
        ):
            raise ValueError(
                "zNetwork OpenSelectedSession BN instruction row escapes its "
                "tracker byte envelope"
            )
        spans.append((address, instruction_end, instruction, body))

    if not spans or spans != sorted(spans, key=lambda row: row[0]):
        raise ValueError(
            "zNetwork OpenSelectedSession execution extent requires one "
            "ordered complete BN instruction population"
        )
    if len({address for address, _end, _row, _body in spans}) != len(spans):
        raise ValueError(
            "zNetwork OpenSelectedSession BN instruction coordinates collide"
        )
    if spans[0][0] != address_value(start) or any(
        left[1] != right[0] for left, right in zip(spans, spans[1:])
    ):
        raise ValueError(
            "zNetwork OpenSelectedSession BN instruction population is not "
            "complete and contiguous"
        )

    derived_end = max(end for _address, end, _row, _body in spans)
    terminal_rows = [
        (instruction, body)
        for address, _end, instruction, body in spans
        if address
        == address_value(_ZNETWORK_OPEN_SELECTED_SESSION_TERMINAL_RET)
    ]
    if (
        derived_end
        != address_value(_ZNETWORK_OPEN_SELECTED_SESSION_EXECUTION_END)
        or len(terminal_rows) != 1
        or terminal_rows[0][1] != b"\xc3"
        or _instruction_mnemonic(terminal_rows[0][0]) not in {"ret", "retn"}
        or _instruction_operand(terminal_rows[0][0]).strip()
    ):
        raise ValueError(
            "zNetwork OpenSelectedSession complete retail instruction "
            "execution end drifted"
        )
    return normalize_address(derived_end)


def _znetwork_open_selected_session_retail_switch_targets(
    retail_instructions: Sequence[Instruction],
    *,
    caller_start: str,
    caller_end_exclusive: str,
    caller_execution_end_exclusive: str,
    bridge: BinaryNinjaBridge,
) -> dict[int, tuple[int, ...]]:
    """Publish the exact attached-table successors for OpenSelectedSession."""

    start = normalize_address(caller_start)
    if start != _ZNETWORK_OPEN_SELECTED_SESSION_START:
        return {}
    execution_end = _retail_call_contract_comparison_end_exclusive(
        retail_instructions,
        caller_start=start,
        caller_end_exclusive=caller_end_exclusive,
    )
    if (
        execution_end != normalize_address(caller_execution_end_exclusive)
        or execution_end != _ZNETWORK_OPEN_SELECTED_SESSION_EXECUTION_END
    ):
        raise ValueError(
            "zNetwork OpenSelectedSession switch proof execution extent drifted"
        )

    addresses = _instruction_runtime_addresses(
        retail_instructions,
        source="bn",
        caller_start=address_value(start),
    )
    positions: dict[str, list[tuple[int, Instruction]]] = {}
    for index, (address, instruction) in enumerate(
        zip(addresses, retail_instructions)
    ):
        if address is not None:
            positions.setdefault(normalize_address(address), []).append(
                (index, instruction)
            )

    required_rows = {
        "0x48a7a8": bytes.fromhex("33 d2"),
        "0x48a7aa": bytes.fromhex("8a 90 2c a9 48 00"),
        "0x48a7b0": bytes.fromhex("ff 24 95 0c a9 48 00"),
    }
    for address, expected_body in required_rows.items():
        rows = positions.get(address, [])
        try:
            body = (
                bytes(int(item, 16) for item in rows[0][1].bytes)
                if len(rows) == 1
                else b""
            )
        except (TypeError, ValueError):
            body = b""
        if body != expected_body:
            raise ValueError(
                "zNetwork OpenSelectedSession switch proof exact instruction "
                f"drifted at {address}"
            )

    dispatch_index, dispatch = positions["0x48a7b0"][0]
    if (
        _instruction_mnemonic(dispatch) != "jmp"
        or _instruction_operand(dispatch).strip().casefold()
        != "dword [edx*4+0x48a90c]"
    ):
        raise ValueError(
            "zNetwork OpenSelectedSession switch proof dispatch rendering drifted"
        )

    tail = _hexdump_bytes(
        bridge.hexdump(
            _ZNETWORK_OPEN_SELECTED_SESSION_EXECUTION_END,
            address_value(_ZNETWORK_OPEN_SELECTED_SESSION_ENVELOPE_END)
            - address_value(_ZNETWORK_OPEN_SELECTED_SESSION_EXECUTION_END),
        )
    )
    if tail != _ZNETWORK_OPEN_SELECTED_SESSION_TAIL:
        raise ValueError(
            "zNetwork OpenSelectedSession attached alignment, jump table, "
            "case map, or padding drifted"
        )
    table_targets = struct.unpack_from("<8I", tail, 3)
    expected_targets = (
        0x48A7F2,
        0x48A810,
        0x48A869,
        0x48A7D4,
        0x48A82D,
        0x48A7B7,
        0x48A84B,
        0x48A89A,
    )
    target_indices = tuple(
        positions.get(normalize_address(target), [(-1, dispatch)])[0][0]
        if len(positions.get(normalize_address(target), [])) == 1
        else -1
        for target in table_targets
    )
    if (
        table_targets != expected_targets
        or any(index <= dispatch_index for index in target_indices)
    ):
        raise ValueError(
            "zNetwork OpenSelectedSession attached switch target population "
            "drifted"
        )
    return {dispatch_index: target_indices}


def _znetwork_pump_exact_candidate_switch_targets(
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
) -> dict[int, tuple[int, ...]]:
    """Publish the exact forward successors of PumpIncomingMessages' switch.

    VC5 lowers this switch through a 221-byte classifier and a seven-entry
    address table.  The generic guarded-table recognizer deliberately cannot
    infer that composition.  This finite proof checks the complete classifier,
    all seven target relocations (including the already-enumerated backward
    default arm), and the exact COD/COFF dispatch before projecting only the six
    forward successors supported by the invocation extractor.
    """

    start = normalize_address(caller_start)
    if start != "0x48afe0":
        return {}
    target = candidate.target
    definition = candidate.caller_definition
    try:
        target_manifest = Path(
            str(getattr(target, "manifest_path", ""))
        ).resolve()
    except (OSError, TypeError, ValueError) as exc:
        raise ValueError(
            "zNetwork Pump switch proof requires its governed target"
        ) from exc
    if (
        caller_identity != _ZNETWORK_FATAL_CALLBACK_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != _ZNETWORK_FATAL_CALLBACK_CALLER_END
        or indexes.by_address.get(start) != caller_identity
        or caller_identity in indexes.provider_ids
        or definition is None
        or definition.symbol != _ZNETWORK_FATAL_CALLBACK_CALLER_SYMBOL
        or definition.section_index <= 0
        or definition.section_start != 0
        or definition.section_end != len(definition.data)
        or len(definition.data) != 0x380
        or len(definition.relocation_mask) != len(definition.data)
        or target is None
        or getattr(target, "name", "") != _ZNETWORK_DPLAY_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or target_manifest != _ZNETWORK_DPLAY_TARGET_MANIFEST.resolve()
        or getattr(target, "source_from", "")
        != _ZNETWORK_DPLAY_SOURCE_PATH
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
    ):
        raise ValueError(
            "zNetwork Pump switch proof rejects caller, extent, symbol, "
            "section, source, or governed-target drift"
        )

    dispatch_specs = (
        (0x1C9, IMAGE_REL_I386_DIR32, "$L28534"),
        (0x1D0, IMAGE_REL_I386_DIR32, "$L28535"),
    )
    table_specs = tuple(
        (0x284 + index * 4, IMAGE_REL_I386_DIR32, label)
        for index, (label, _offset) in enumerate(
            _ZNETWORK_PUMP_SWITCH_LABELS
        )
    )
    relocation_specs = (*dispatch_specs, *table_specs)
    proof_offsets = (
        set(range(0x1C5, 0x1D4))
        | set(range(0x284, 0x37D))
    )
    selected_relocations = tuple(
        sorted(
            (
                row.offset,
                row.type,
                row.symbol_name,
                row.symbol_index,
            )
            for row in definition.relocations
            if row.offset in proof_offsets
        )
    )
    symbol_values = {
        "$L28535": 0x284,
        "$L28534": 0x2A0,
        **dict(_ZNETWORK_PUMP_SWITCH_LABELS),
    }
    symbol_rows = {
        name: [row for row in definition.coff_symbols if row.name == name]
        for name in symbol_values
    }
    expected_mask = {
        byte
        for offset, _kind, _target in relocation_specs
        for byte in range(offset, offset + 4)
    }
    actual_mask = {
        index
        for index, masked in enumerate(definition.relocation_mask)
        if masked and index in proof_offsets
    }
    if (
        definition.data[0x1C5:0x1D4]
        != bytes.fromhex(
            "33 c9 8a 88 00 00 00 00 ff 24 8d 00 00 00 00"
        )
        or definition.data[0x284:0x2A0] != b"\x00" * 0x1C
        or definition.data[0x2A0:0x37D]
        != _ZNETWORK_PUMP_SWITCH_CLASSIFIER
        or tuple(
            (offset, kind, name)
            for offset, kind, name, _symbol_index in selected_relocations
        )
        != relocation_specs
        or actual_mask != expected_mask
        or any(
            struct.unpack_from("<I", definition.data, offset)[0] != 0
            for offset, _kind, _target in relocation_specs
        )
        or any(
            len(symbol_rows[name]) != 1
            or symbol_rows[name][0].value != value
            or symbol_rows[name][0].section_number
            != definition.section_index
            or symbol_rows[name][0].symbol_type != 0
            or symbol_rows[name][0].storage_class != 6
            or symbol_rows[name][0].section_size != len(definition.data)
            or symbol_rows[name][0].natural_end != len(definition.data)
            for name, value in symbol_values.items()
        )
        or any(
            symbol_index != symbol_rows[name][0].index
            for _offset, _kind, name, symbol_index in selected_relocations
        )
    ):
        raise ValueError(
            "zNetwork Pump switch proof rejects exact dispatch, classifier, "
            "table, relocation, mask, addend, or local-symbol drift"
        )

    offsets = _candidate_complete_instruction_offsets(candidate)
    offset_counts = Counter(offset for offset in offsets if offset is not None)
    instruction_index_by_offset = {
        int(offset): index
        for index, offset in enumerate(offsets)
        if offset is not None and offset_counts[offset] == 1
    }
    dispatch_index = instruction_index_by_offset.get(0x1CD)
    forward_indices = tuple(
        instruction_index_by_offset.get(offset, -1)
        for _label, offset in _ZNETWORK_PUMP_SWITCH_LABELS[:-1]
    )
    backward_index = instruction_index_by_offset.get(
        _ZNETWORK_PUMP_SWITCH_LABELS[-1][1]
    )
    dispatch_instruction = (
        candidate.instructions[dispatch_index]
        if dispatch_index is not None
        else None
    )
    if (
        dispatch_index is None
        or dispatch_instruction is None
        or _instruction_mnemonic(dispatch_instruction) != "jmp"
        or _instruction_operand(dispatch_instruction).strip().casefold()
        != "dword $l28535[ecx*4]"
        or tuple(item.casefold() for item in dispatch_instruction.bytes)
        != ("ff", "24", "8d", "00", "00", "00", "00")
        or -1 in forward_indices
        or not all(dispatch_index < index for index in forward_indices)
        or backward_index is None
        or backward_index >= dispatch_index
        or len(set((*forward_indices, backward_index))) != 7
    ):
        raise ValueError(
            "zNetwork Pump switch proof rejects exact COD dispatch or target "
            "instruction coordinates"
        )
    return {dispatch_index: forward_indices}


def _znetwork_pump_folded_dispatch_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    candidate_call_sites: Sequence[str],
    switch_targets: Mapping[int, tuple[int, ...]],
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Project PumpIncomingMessages' two exact case calls from one VC5 body.

    The authored cases 0x102 and 0x103 contain distinct calls, while this exact
    candidate lowering shares their physical E8 at +0x231.  Retail retains two
    rows.  Duplicate only that final semantic row after the complete candidate
    call-site population, both case ingresses, shared block, relocation, and
    independently proven classifier/table have all remained exact.
    """

    start = normalize_address(caller_start)
    result = [dict(row) for row in candidate_contract]
    if start != "0x48afe0":
        return result
    definition = candidate.caller_definition
    offsets = _candidate_complete_instruction_offsets(candidate)
    offset_counts = Counter(offset for offset in offsets if offset is not None)
    index_by_offset = {
        int(offset): index
        for index, offset in enumerate(offsets)
        if offset is not None and offset_counts[offset] == 1
    }
    dispatch_index = index_by_offset.get(0x1CD)
    case_102_index = index_by_offset.get(0x20B)
    case_103_index = index_by_offset.get(0x214)
    expected_call_offsets = (
        0x39,
        0x68,
        0x70,
        0x8F,
        0xA8,
        0x138,
        0x193,
        0x198,
        0x1A8,
        0x1E0,
        0x231,
    )
    expected_call_sites = tuple(
        normalize_address(address_value(start) + offset)
        for offset in expected_call_offsets
    )
    shared_dispatch_body = bytes.fromhex(
        "66 c7 44 24 14 04 00 eb 07 "
        "66 c7 44 24 14 05 00 8b 4b 08 8d 54 24 14 "
        "66 c7 44 24 16 08 00 c7 44 24 18 00 00 00 00 "
        "e8 00 00 00 00 33 c0 5f 5e 5d 5b 83 c4 0c c3"
    )
    shared_relocations = (
        [
            row
            for row in definition.relocations
            if 0x20B <= row.offset < 0x240
        ]
        if definition is not None
        else []
    )
    final_shape = {
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "direct",
        "target_identity": _ZNETWORK_DISPATCH_CALLER_IDENTITY,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    if (
        caller_identity != _ZNETWORK_FATAL_CALLBACK_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != _ZNETWORK_FATAL_CALLBACK_CALLER_END
        or definition is None
        or definition.symbol != _ZNETWORK_FATAL_CALLBACK_CALLER_SYMBOL
        or len(result) != 11
        or len(expected) != 12
        or any(
            dict(result[index]) != dict(expected[index])
            for index in range(11)
        )
        or {
            key: expected[10].get(key)
            for key in final_shape
        }
        != final_shape
        or {
            key: expected[11].get(key)
            for key in final_shape
        }
        != final_shape
        or expected[10].get("ordinal") != 10
        or expected[11].get("ordinal") != 11
        or tuple(candidate_call_sites) != expected_call_sites
        or definition.data[0x20B:0x240] != shared_dispatch_body
        or len(shared_relocations) != 1
        or shared_relocations[0].offset != 0x232
        or shared_relocations[0].type != IMAGE_REL_I386_REL32
        or shared_relocations[0].symbol_name
        != _ZNETWORK_DISPATCH_CALLER_SYMBOL
        or struct.unpack_from("<I", definition.data, 0x232)[0] != 0
        or {
            index
            for index in range(0x20B, 0x240)
            if definition.relocation_mask[index]
        }
        != {0x232, 0x233, 0x234, 0x235}
        or dispatch_index is None
        or case_102_index is None
        or case_103_index is None
        or switch_targets.get(dispatch_index) is None
        or case_102_index not in switch_targets[dispatch_index]
        or case_103_index not in switch_targets[dispatch_index]
    ):
        raise ValueError(
            "zNetwork Pump folded-dispatch projection rejects exact retail "
            "population, candidate calls, case arms, shared body, relocation, "
            "mask, or switch proof drift"
        )
    result.append({**result[-1], "ordinal": 11})
    return result


def _znetwork_exact_candidate_indirect_bridges(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
) -> tuple[
    dict[str, ReviewedRegisterCallStorageBridge],
    dict[str, ReviewedExactIndirectStorageBridge],
]:
    """Recover only two exact zNetwork candidate indirect-call idioms.

    The immutable retail contract remains expected truth.  This adapter only
    proves that the current candidate caller reaches the same independently
    indexed storage through the exact VC5 COD/COFF load and call topology.
    Neither caller grants a static callback target or a generic register-flow
    shortcut: every caller, extent, target, relocation, byte, register and
    storage coordinate is finite and checked here.
    """

    start = normalize_address(caller_start)
    if start not in {"0x48afe0", "0x48c200"}:
        return {}, {}

    target = candidate.target
    definition = candidate.caller_definition
    expected_identity = {
        "0x48afe0": _ZNETWORK_FATAL_CALLBACK_CALLER_IDENTITY,
        "0x48c200": _ZNETWORK_DISPATCH_CALLER_IDENTITY,
    }[start]
    expected_end = {
        "0x48afe0": _ZNETWORK_FATAL_CALLBACK_CALLER_END,
        "0x48c200": _ZNETWORK_DISPATCH_CALLER_END,
    }[start]
    expected_symbol = {
        "0x48afe0": _ZNETWORK_FATAL_CALLBACK_CALLER_SYMBOL,
        "0x48c200": _ZNETWORK_DISPATCH_CALLER_SYMBOL,
    }[start]
    try:
        target_manifest = Path(
            str(getattr(target, "manifest_path", ""))
        ).resolve()
    except (OSError, TypeError, ValueError) as exc:
        raise ValueError(
            "zNetwork exact-indirect bridge requires its governed target"
        ) from exc
    if (
        caller_identity != expected_identity
        or normalize_address(caller_end_exclusive) != expected_end
        or indexes.by_address.get(start) != caller_identity
        or caller_identity in indexes.provider_ids
        or definition is None
        or definition.symbol != expected_symbol
        or definition.section_index <= 0
        or definition.section_start != 0
        or definition.section_end != len(definition.data)
        or len(definition.relocation_mask) != len(definition.data)
        or target is None
        or getattr(target, "name", "") != _ZNETWORK_DPLAY_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or target_manifest != _ZNETWORK_DPLAY_TARGET_MANIFEST.resolve()
        or getattr(target, "source_from", "")
        != _ZNETWORK_DPLAY_SOURCE_PATH
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
    ):
        raise ValueError(
            "zNetwork exact-indirect bridge rejects caller, extent, symbol, "
            "section, source, or governed-target drift"
        )

    offsets = _candidate_complete_instruction_offsets(candidate)
    by_offset: dict[int, Instruction] = {}
    for offset, instruction in zip(offsets, candidate.instructions):
        if offset is None or offset in by_offset:
            raise ValueError(
                "zNetwork exact-indirect bridge requires unique complete "
                "candidate COD coordinates"
            )
        by_offset[offset] = instruction

    def exact_instruction(
        offset: int,
        *,
        mnemonic: str,
        operand: str,
        body: bytes,
    ) -> None:
        instruction = by_offset.get(offset)
        try:
            encoded = bytes(int(item, 16) for item in instruction.bytes)
        except (AttributeError, TypeError, ValueError) as exc:
            raise ValueError(
                "zNetwork exact-indirect bridge requires exact candidate "
                f"instruction bytes at +0x{offset:x}"
            ) from exc
        if (
            _instruction_mnemonic(instruction) != mnemonic
            or _instruction_operand(instruction).strip().casefold()
            != operand.casefold()
            or encoded != body
        ):
            raise ValueError(
                "zNetwork exact-indirect bridge rejects candidate topology "
                f"at +0x{offset:x}"
            )

    if start == "0x48afe0":
        storage_identity = _candidate_c_external_storage_identity(
            _ZNETWORK_FATAL_CALLBACK_OBJECT_SYMBOL,
            indexes=indexes,
        )
        expected_rows = [
            row
            for row in expected
            if row.get("form") == "call"
            and row.get("dispatch") == "indirect"
            and row.get("identity_kind") == "callback"
            and row.get("target_identity") == ""
            and row.get("storage_identity")
            == _ZNETWORK_FATAL_CALLBACK_STORAGE_IDENTITY
            and row.get("slot_displacement") is None
            and row.get("cleanup_bytes") is None
        ]
        fatal_relocations = [
            row
            for row in definition.relocations
            if row.symbol_name == _ZNETWORK_FATAL_CALLBACK_OBJECT_SYMBOL
        ]
        if (
            storage_identity != _ZNETWORK_FATAL_CALLBACK_STORAGE_IDENTITY
            or len(expected_rows) != 1
            or len(definition.data) != 0x380
            or definition.data[0x1D4:0x1E2]
            != bytes.fromhex(
                "a1 00 00 00 00 85 c0 74 05 83 c9 ff ff d0"
            )
            or len(fatal_relocations) != 1
            or fatal_relocations[0].offset != 0x1D5
            or fatal_relocations[0].type != IMAGE_REL_I386_DIR32
            or struct.unpack_from("<I", definition.data, 0x1D5)[0] != 0
            or definition.relocation_mask[0x1D4]
            or not all(definition.relocation_mask[0x1D5:0x1D9])
            or definition.defined_external_data.count(
                _ZNETWORK_FATAL_CALLBACK_OBJECT_SYMBOL
            )
            != 1
            or definition.undefined_external_data.count(
                _ZNETWORK_FATAL_CALLBACK_OBJECT_SYMBOL
            )
            != 0
        ):
            raise ValueError(
                "zNetwork fatal-callback candidate bridge rejects exact "
                "retail contract, storage, body, relocation, or definition "
                "population drift"
            )
        exact_instruction(
            0x1D4,
            mnemonic="mov",
            operand=(
                "eax, dword "
                + _ZNETWORK_FATAL_CALLBACK_OBJECT_SYMBOL
            ),
            body=bytes.fromhex("a1 00 00 00 00"),
        )
        exact_instruction(
            0x1D9,
            mnemonic="test",
            operand="eax, eax",
            body=bytes.fromhex("85 c0"),
        )
        exact_instruction(
            0x1DB,
            mnemonic="je",
            operand="$L27806",
            body=bytes.fromhex("74 05"),
        )
        exact_instruction(
            0x1DD,
            mnemonic="or",
            operand="ecx, -1",
            body=bytes.fromhex("83 c9 ff"),
        )
        exact_instruction(
            0x1E0,
            mnemonic="call",
            operand="eax",
            body=bytes.fromhex("ff d0"),
        )
        return {
            "0x1e0": ReviewedRegisterCallStorageBridge(
                register="eax",
                storage_identity=storage_identity,
                identity_kind="callback",
                assembly_source="cod",
            )
        }, {}

    candidate_dispatch_storage_identity = _candidate_c_external_storage_identity(
        _ZNETWORK_DISPATCH_LIST_OBJECT_SYMBOL,
        indexes=indexes,
    )
    expected_row = expected[0] if len(expected) == 1 else None
    expected_storage_match = re.fullmatch(
        r"load\(load\((?P<root>storage:recoil:data:0x[0-9a-f]+)\)\+0x8\)",
        str(expected_row.get("storage_identity", ""))
        if isinstance(expected_row, Mapping)
        else "",
    )
    dispatch_storage_identity = (
        expected_storage_match.group("root")
        if expected_storage_match is not None
        else ""
    )
    expected_storage_identity = (
        expected_storage_match.group(0)
        if expected_storage_match is not None
        else ""
    )
    expected_contract = {
        "ordinal": 0,
        "form": "call",
        "dispatch": "indirect",
        "identity_kind": "virtual-slot",
        "target_identity": "",
        "storage_identity": expected_storage_identity,
        "slot_displacement": 4,
        "cleanup_bytes": None,
    }
    dispatch_relocations = [
        row
        for row in definition.relocations
        if row.symbol_name == _ZNETWORK_DISPATCH_LIST_OBJECT_SYMBOL
    ]
    expected_mask = {3, 4, 5, 6}
    if (
        not dispatch_storage_identity
        or dispatch_storage_identity.startswith("iat:")
        or list(indexes.storage_by_address.values()).count(
            dispatch_storage_identity
        )
        != 1
        or candidate_dispatch_storage_identity
        not in {None, "", dispatch_storage_identity}
        or list(expected) != [expected_contract]
        or definition.data != _ZNETWORK_DISPATCH_CANDIDATE_BODY
        or len(dispatch_relocations) != 1
        or dispatch_relocations[0].offset != 3
        or dispatch_relocations[0].type != IMAGE_REL_I386_DIR32
        or struct.unpack_from("<I", definition.data, 3)[0] != 4
        or {
            index
            for index, masked in enumerate(definition.relocation_mask)
            if masked
        }
        != expected_mask
        or definition.defined_external_data.count(
            _ZNETWORK_DISPATCH_LIST_OBJECT_SYMBOL
        )
        != 1
        or definition.undefined_external_data.count(
            _ZNETWORK_DISPATCH_LIST_OBJECT_SYMBOL
        )
        != 0
    ):
        raise ValueError(
            "zNetwork dispatch-handler candidate bridge rejects exact retail "
            "contract, storage, body, relocation, or definition population "
            "drift"
        )
    for offset, mnemonic, operand, body in (
        (0x1B, "mov", "eax, dword [esi+8]", bytes.fromhex("8b 46 08")),
        (0x1E, "mov", "cx, word [eax]", bytes.fromhex("66 8b 08")),
        (0x21, "cmp", "cx, word [edi]", bytes.fromhex("66 3b 0f")),
        (0x24, "jne", "$L28109", bytes.fromhex("75 07")),
        (0x26, "mov", "edx, edi", bytes.fromhex("8b d7")),
        (0x28, "mov", "ecx, ebp", bytes.fromhex("8b cd")),
        (0x2A, "call", "dword [eax+4]", bytes.fromhex("ff 50 04")),
    ):
        exact_instruction(
            offset,
            mnemonic=mnemonic,
            operand=operand,
            body=body,
        )
    return {}, {
        "0x2a": ReviewedExactIndirectStorageBridge(
            register="eax",
            storage_identity=expected_storage_identity,
            slot_displacement=4,
            assembly_source="cod",
        )
    }


_ZINTERP_LOGF_CALLER_IDENTITY = "symbol:recoil:function:0x4c1b30"
_ZINTERP_LOGF_CALLER_START = "0x4c1b30"
_ZINTERP_LOGF_CALLER_END_EXCLUSIVE = "0x4c1b50"
_ZINTERP_LOGF_CANDIDATE_SYMBOL = "?Logf@zInterp_Context@@SAXPAU1@PBDZZ"
_ZINTERP_LOGF_FASTCALL_TAIL_BODY = bytes.fromhex(
    "8b 44 24 04 8b 40 70 85 c0 74 0a 8b 4c 24 08 "
    "8d 54 24 0c ff e0 c3"
)
_ZINTERP_LOGF_CDECL_CALL_BODY = bytes.fromhex(
    "8b 44 24 04 8b 40 70 85 c0 74 0f 8b 54 24 08 "
    "8d 4c 24 0c 51 52 ff d0 83 c4 08 c3"
)
_ZINTERP_CONTEXT_CALLBACK_IDENTITY = (
    "dynamic:zInterp_Context+0x70-callback"
)
_ZINTERP_REPORT_ERRORF_CALLER_IDENTITY = "symbol:recoil:function:0x4c5520"
_ZINTERP_REPORT_ERRORF_CALLER_START = "0x4c5520"
_ZINTERP_REPORT_ERRORF_CALLER_END_EXCLUSIVE = "0x4c5550"
_ZINTERP_REPORT_ERRORF_CANDIDATE_SYMBOL = (
    "?ReportErrorf@zInterp_Context@@SAXPAU1@PBDZZ"
)
_ZINTERP_REPORT_ERRORF_SEMANTIC_BODY = bytes.fromhex(
    "8b 44 24 04 c7 40 10 01 00 00 00 8b 40 70 85 c0 "
    "74 0f 8b 54 24 08 8d 4c 24 0c 51 52 ff d0 83 c4 08 c3"
)
_ZINTERP_REPORT_ERRORF_PHYSICAL_BODY = (
    _ZINTERP_REPORT_ERRORF_SEMANTIC_BODY + b"\x90" * 14
)


def _exact_zinterp_logf_parameter_load(
    instruction: Instruction,
    *,
    destination: str,
    encoded_displacement: int,
    vc5_symbol: str,
) -> bool:
    """Accept one exact numeric or VC5 symbolic Logf parameter load.

    VC5 COD renders these incoming parameters as ``_ctx$[esp-4]`` and
    ``_fmt$[esp-4]`` even though the encoded SIB displacements are +4 and +8.
    Keep that presentation quirk local to this fully byte-gated finite body.
    """

    if _exact_stack_slot_load(instruction) == (
        destination,
        encoded_displacement,
    ):
        return True
    return _exact_vc5_symbolic_stack_slot_load(instruction) == (
        encoded_displacement,
        destination,
        vc5_symbol,
        -4,
    )


def _zinterp_logf_candidate_ctx_callback_bridge(
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    existing_bridges: Mapping[str, ReviewedLoopVptrStorageBridge] | None = None,
) -> dict[str, ReviewedLoopVptrStorageBridge]:
    """Bind only Logf's exact candidate ctx+0x70 callback provenance.

    This bridge deliberately does not change the candidate invocation form.
    The current VC5 body tail-jumps through EAX, while retail calls EAX; normal
    contract extraction retains that distinction for the live comparison.
    """

    start = normalize_address(caller_start)
    if start != _ZINTERP_LOGF_CALLER_START:
        return {}
    definition = candidate.caller_definition
    offsets = _candidate_complete_instruction_offsets(candidate)
    rows = candidate.instructions
    physical_bodies = {
        "fastcall-tail": (
            _ZINTERP_LOGF_FASTCALL_TAIL_BODY,
            _ZINTERP_LOGF_FASTCALL_TAIL_BODY
            + b"\x90" * (0x20 - len(_ZINTERP_LOGF_FASTCALL_TAIL_BODY)),
        ),
        "cdecl-call": (
            _ZINTERP_LOGF_CDECL_CALL_BODY,
            _ZINTERP_LOGF_CDECL_CALL_BODY
            + b"\x90" * (0x20 - len(_ZINTERP_LOGF_CDECL_CALL_BODY)),
        ),
    }
    shape = next(
        (
            name
            for name, representations in physical_bodies.items()
            if definition is not None
            and definition.data in representations
        ),
        "",
    )
    semantic_body = (
        physical_bodies[shape][0]
        if shape in physical_bodies
        else b""
    )
    callback_offset = normalize_address(
        "0x13" if shape == "fastcall-tail" else "0x15"
    )
    candidate_names = [
        name
        for name, identity in indexes.by_candidate_name.items()
        if identity == caller_identity
    ]
    caller_addresses = [
        address
        for address, identity in indexes.by_address.items()
        if identity == caller_identity
    ]
    try:
        listed_body: bytes | None = b"".join(
            bytes(int(item, 16) for item in row.bytes) for row in rows
        )
    except (TypeError, ValueError):
        listed_body = None
    expected_row_count = 8 if shape == "fastcall-tail" else 11
    expected_offsets = (
        (0, 4, 7, 9, 0x0B, 0x0F, 0x13, 0x15)
        if shape == "fastcall-tail"
        else (0, 4, 7, 9, 0x0B, 0x0F, 0x13, 0x14, 0x15, 0x17, 0x1A)
    )
    # CandidateCallerDefinition carries the object/TU-wide undefined-symbol
    # census, not a per-function dependency list.  This exact body has no
    # relocation-bearing operand, so the empty per-body relocation tuple and
    # all-clear mask below are the authoritative exclusion.  TU neighbors may
    # add or remove unrelated undefined symbols without changing this caller.
    aggregate_checks: dict[str, tuple[bool, Any]] = {
        "caller_identity": (
            caller_identity == _ZINTERP_LOGF_CALLER_IDENTITY,
            caller_identity,
        ),
        "caller_end_exclusive": (
            normalize_address(caller_end_exclusive)
            == _ZINTERP_LOGF_CALLER_END_EXCLUSIVE,
            normalize_address(caller_end_exclusive),
        ),
        "address_identity": (
            indexes.by_address.get(start) == caller_identity,
            indexes.by_address.get(start),
        ),
        "caller_addresses": (
            caller_addresses == [_ZINTERP_LOGF_CALLER_START],
            tuple(caller_addresses),
        ),
        "candidate_symbol_identity": (
            indexes.by_candidate_name.get(_ZINTERP_LOGF_CANDIDATE_SYMBOL)
            == caller_identity,
            indexes.by_candidate_name.get(_ZINTERP_LOGF_CANDIDATE_SYMBOL),
        ),
        "candidate_names": (
            candidate_names == [_ZINTERP_LOGF_CANDIDATE_SYMBOL],
            tuple(candidate_names),
        ),
        "provider": (
            caller_identity not in indexes.provider_ids,
            caller_identity in indexes.provider_ids,
        ),
        "definition": (definition is not None, definition is not None),
        "definition_symbol": (
            definition is not None
            and definition.symbol == _ZINTERP_LOGF_CANDIDATE_SYMBOL,
            definition.symbol if definition is not None else None,
        ),
        "body_shape": (
            shape in {"fastcall-tail", "cdecl-call"},
            (
                definition.data.hex()
                if definition is not None
                else None
            ),
        ),
        "relocations": (
            definition is not None and not definition.relocations,
            definition.relocations if definition is not None else None,
        ),
        "relocation_mask": (
            definition is not None
            and len(definition.relocation_mask) == len(definition.data)
            and not any(definition.relocation_mask),
            (
                (
                    len(definition.relocation_mask),
                    sum(bool(item) for item in definition.relocation_mask),
                )
                if definition is not None
                else None
            ),
        ),
        "instruction_count": (
            len(rows) == expected_row_count,
            len(rows),
        ),
        "instruction_offsets": (offsets == expected_offsets, offsets),
        "listing_body": (
            definition is not None and listed_body == semantic_body,
            listed_body.hex() if listed_body is not None else None,
        ),
    }
    aggregate_drift = {
        name: observed
        for name, (passed, observed) in aggregate_checks.items()
        if not passed
    }
    if aggregate_drift:
        raise ValueError(
            "zInterp Logf candidate ctx callback requires the exact authored "
            "caller identity, symbol, extent, body, and empty relocation set; "
            f"drift={aggregate_drift!r}"
        )
    common_lineage_checks: dict[str, tuple[bool, Any]] = {
        "context_root": (
            _exact_zinterp_logf_parameter_load(
                rows[0],
                destination="eax",
                encoded_displacement=4,
                vc5_symbol="_ctx$",
            ),
            (
                _exact_stack_slot_load(rows[0]),
                _exact_vc5_symbolic_stack_slot_load(rows[0]),
                rows[0].raw_text,
                tuple(rows[0].bytes),
            ),
        ),
        "callback_field": (
            _exact_register_memory_load(rows[1]) == ("eax", "eax", 0x70),
            (
                _exact_register_memory_load(rows[1]),
                rows[1].raw_text,
                tuple(rows[1].bytes),
            ),
        ),
        "callback_test": (
            _exact_test_same_register(rows[2]) == "eax",
            (_exact_test_same_register(rows[2]), rows[2].raw_text),
        ),
        "null_branch": (
            _instruction_mnemonic(rows[3]) in {"je", "jz"},
            rows[3].raw_text,
        ),
    }
    if shape == "fastcall-tail":
        shape_lineage_checks: dict[str, tuple[bool, Any]] = {
            "null_branch_bytes": (
                tuple(rows[3].bytes) == ("74", "0a"),
                tuple(rows[3].bytes),
            ),
            "format_argument": (
                _exact_zinterp_logf_parameter_load(
                    rows[4],
                    destination="ecx",
                    encoded_displacement=8,
                    vc5_symbol="_fmt$",
                ),
                (
                    _exact_stack_slot_load(rows[4]),
                    _exact_vc5_symbolic_stack_slot_load(rows[4]),
                    rows[4].raw_text,
                ),
            ),
            "varargs_argument": (
                _instruction_mnemonic(rows[5]) == "lea"
                and tuple(rows[5].bytes) == ("8d", "54", "24", "0c"),
                (rows[5].raw_text, tuple(rows[5].bytes)),
            ),
            "eax_clobber": (
                not any(
                    _instruction_may_clobber_register(row, "eax")
                    for row in rows[2:6]
                ),
                tuple(
                    row.raw_text
                    for row in rows[2:6]
                    if _instruction_may_clobber_register(row, "eax")
                ),
            ),
            "invocation": (
                _instruction_mnemonic(rows[6]) == "jmp"
                and _instruction_operand(rows[6]).strip().lower() == "eax"
                and _exact_invocation_encoding(rows[6], mnemonic="jmp"),
                (rows[6].raw_text, tuple(rows[6].bytes)),
            ),
            "return": (
                _instruction_mnemonic(rows[7]) in {"ret", "retn"},
                rows[7].raw_text,
            ),
        }
    else:
        shape_lineage_checks = {
            "null_branch_bytes": (
                tuple(rows[3].bytes) == ("74", "0f"),
                tuple(rows[3].bytes),
            ),
            "format_argument": (
                _exact_zinterp_logf_parameter_load(
                    rows[4],
                    destination="edx",
                    encoded_displacement=8,
                    vc5_symbol="_fmt$",
                ),
                (
                    _exact_stack_slot_load(rows[4]),
                    _exact_vc5_symbolic_stack_slot_load(rows[4]),
                    rows[4].raw_text,
                ),
            ),
            "varargs_argument": (
                _instruction_mnemonic(rows[5]) == "lea"
                and tuple(rows[5].bytes) == ("8d", "4c", "24", "0c"),
                (rows[5].raw_text, tuple(rows[5].bytes)),
            ),
            "argument_pushes": (
                tuple(rows[6].bytes) == ("51",)
                and tuple(rows[7].bytes) == ("52",),
                (rows[6].raw_text, rows[7].raw_text),
            ),
            "eax_clobber": (
                not any(
                    _instruction_may_clobber_register(row, "eax")
                    for row in rows[2:8]
                ),
                tuple(
                    row.raw_text
                    for row in rows[2:8]
                    if _instruction_may_clobber_register(row, "eax")
                ),
            ),
            "invocation": (
                _instruction_mnemonic(rows[8]) == "call"
                and _instruction_operand(rows[8]).strip().lower() == "eax"
                and _exact_invocation_encoding(rows[8], mnemonic="call"),
                (rows[8].raw_text, tuple(rows[8].bytes)),
            ),
            "cleanup": (
                tuple(rows[9].bytes) == ("83", "c4", "08"),
                (rows[9].raw_text, tuple(rows[9].bytes)),
            ),
            "return": (
                _instruction_mnemonic(rows[10]) in {"ret", "retn"},
                rows[10].raw_text,
            ),
        }
    lineage_drift = {
        name: observed
        for name, (passed, observed) in {
            **common_lineage_checks,
            **shape_lineage_checks,
        }.items()
        if not passed
    }
    if lineage_drift:
        raise ValueError(
            "zInterp Logf candidate ctx callback field/root/register/use "
            f"lineage drifted; drift={lineage_drift!r}"
        )
    prior = (existing_bridges or {}).get(callback_offset)
    if prior is not None:
        raise ValueError(
            "zInterp Logf candidate ctx callback has duplicate or conflicting "
            f"existing provenance at {callback_offset}: {prior!r}"
        )
    return {
        callback_offset: ReviewedLoopVptrStorageBridge(
            register="eax",
            storage_identity=_ZINTERP_CONTEXT_CALLBACK_IDENTITY,
            slot_displacement=0,
            assembly_source="cod",
        )
    }


def _zinterp_report_errorf_candidate_ctx_callback_bridge(
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    existing_bridges: Mapping[str, ReviewedLoopVptrStorageBridge] | None = None,
) -> dict[str, ReviewedLoopVptrStorageBridge]:
    """Bind only ReportErrorf's exact candidate ctx+0x70 callback call.

    Retail and the current VC5 candidate both load the callback from the
    incoming context's +0x70 field and call it through EAX.  The callback is
    runtime-selected, so this finite caller proof publishes targetless storage
    provenance; it does not grant generic EAX provenance to any other caller.
    """

    start = normalize_address(caller_start)
    if start != _ZINTERP_REPORT_ERRORF_CALLER_START:
        return {}
    definition = candidate.caller_definition
    rows = candidate.instructions
    offsets = _candidate_complete_instruction_offsets(candidate)
    candidate_names = [
        name
        for name, identity in indexes.by_candidate_name.items()
        if identity == caller_identity
    ]
    caller_addresses = [
        address
        for address, identity in indexes.by_address.items()
        if identity == caller_identity
    ]
    try:
        listed_body: bytes | None = b"".join(
            bytes(int(item, 16) for item in row.bytes) for row in rows
        )
    except (TypeError, ValueError):
        listed_body = None
    aggregate_checks: dict[str, tuple[bool, Any]] = {
        "caller_identity": (
            caller_identity == _ZINTERP_REPORT_ERRORF_CALLER_IDENTITY,
            caller_identity,
        ),
        "caller_end_exclusive": (
            normalize_address(caller_end_exclusive)
            == _ZINTERP_REPORT_ERRORF_CALLER_END_EXCLUSIVE,
            normalize_address(caller_end_exclusive),
        ),
        "address_identity": (
            indexes.by_address.get(start) == caller_identity,
            indexes.by_address.get(start),
        ),
        "caller_addresses": (
            caller_addresses == [_ZINTERP_REPORT_ERRORF_CALLER_START],
            tuple(caller_addresses),
        ),
        "candidate_symbol_identity": (
            indexes.by_candidate_name.get(
                _ZINTERP_REPORT_ERRORF_CANDIDATE_SYMBOL
            )
            == caller_identity,
            indexes.by_candidate_name.get(
                _ZINTERP_REPORT_ERRORF_CANDIDATE_SYMBOL
            ),
        ),
        "candidate_names": (
            candidate_names == [_ZINTERP_REPORT_ERRORF_CANDIDATE_SYMBOL],
            tuple(candidate_names),
        ),
        "provider": (
            caller_identity not in indexes.provider_ids,
            caller_identity in indexes.provider_ids,
        ),
        "definition": (definition is not None, definition is not None),
        "definition_symbol": (
            definition is not None
            and definition.symbol == _ZINTERP_REPORT_ERRORF_CANDIDATE_SYMBOL,
            definition.symbol if definition is not None else None,
        ),
        "body": (
            definition is not None
            and definition.data == _ZINTERP_REPORT_ERRORF_PHYSICAL_BODY,
            definition.data.hex() if definition is not None else None,
        ),
        "relocations": (
            definition is not None and not definition.relocations,
            definition.relocations if definition is not None else None,
        ),
        "relocation_mask": (
            definition is not None
            and len(definition.relocation_mask) == len(definition.data)
            and not any(definition.relocation_mask),
            (
                (
                    len(definition.relocation_mask),
                    sum(bool(item) for item in definition.relocation_mask),
                )
                if definition is not None
                else None
            ),
        ),
        "section_extent": (
            definition is not None
            and definition.section_start == 0
            and definition.section_end == len(definition.data),
            (
                (definition.section_start, definition.section_end)
                if definition is not None
                else None
            ),
        ),
        "instruction_count": (len(rows) == 12, len(rows)),
        "instruction_offsets": (
            offsets
            == (0, 4, 0x0B, 0x0E, 0x10, 0x12, 0x16, 0x1A, 0x1B, 0x1C, 0x1E, 0x21),
            offsets,
        ),
        "listing_body": (
            listed_body == _ZINTERP_REPORT_ERRORF_SEMANTIC_BODY,
            listed_body.hex() if listed_body is not None else None,
        ),
    }
    aggregate_drift = {
        name: observed
        for name, (passed, observed) in aggregate_checks.items()
        if not passed
    }
    if aggregate_drift:
        raise ValueError(
            "zInterp ReportErrorf candidate ctx callback requires the exact "
            "authored caller identity, symbol, extent, body, padding, and "
            f"empty relocation set; drift={aggregate_drift!r}"
        )

    lineage_checks: dict[str, tuple[bool, Any]] = {
        "context_root": (
            _exact_zinterp_logf_parameter_load(
                rows[0],
                destination="eax",
                encoded_displacement=4,
                vc5_symbol="_ctx$",
            ),
            rows[0].raw_text,
        ),
        "error_flag_write": (
            tuple(rows[1].bytes)
            == ("c7", "40", "10", "01", "00", "00", "00"),
            (rows[1].raw_text, tuple(rows[1].bytes)),
        ),
        "callback_field": (
            _exact_register_memory_load(rows[2]) == ("eax", "eax", 0x70),
            (_exact_register_memory_load(rows[2]), rows[2].raw_text),
        ),
        "callback_test": (
            _exact_test_same_register(rows[3]) == "eax",
            (_exact_test_same_register(rows[3]), rows[3].raw_text),
        ),
        "null_branch": (
            _instruction_mnemonic(rows[4]) in {"je", "jz"}
            and tuple(rows[4].bytes) == ("74", "0f"),
            (rows[4].raw_text, tuple(rows[4].bytes)),
        ),
        "format_argument": (
            _exact_zinterp_logf_parameter_load(
                rows[5],
                destination="edx",
                encoded_displacement=8,
                vc5_symbol="_fmt$",
            ),
            rows[5].raw_text,
        ),
        "varargs_argument": (
            _instruction_mnemonic(rows[6]) == "lea"
            and tuple(rows[6].bytes) == ("8d", "4c", "24", "0c"),
            (rows[6].raw_text, tuple(rows[6].bytes)),
        ),
        "argument_pushes": (
            tuple(rows[7].bytes) == ("51",)
            and tuple(rows[8].bytes) == ("52",),
            (rows[7].raw_text, rows[8].raw_text),
        ),
        "eax_lineage": (
            not any(
                _instruction_may_clobber_register(row, "eax")
                for row in rows[3:9]
            ),
            tuple(
                row.raw_text
                for row in rows[3:9]
                if _instruction_may_clobber_register(row, "eax")
            ),
        ),
        "invocation": (
            _instruction_mnemonic(rows[9]) == "call"
            and _instruction_operand(rows[9]).strip().lower() == "eax"
            and _exact_invocation_encoding(rows[9], mnemonic="call"),
            (rows[9].raw_text, tuple(rows[9].bytes)),
        ),
        "cleanup": (
            tuple(rows[10].bytes) == ("83", "c4", "08"),
            (rows[10].raw_text, tuple(rows[10].bytes)),
        ),
        "return": (
            _instruction_mnemonic(rows[11]) in {"ret", "retn"},
            rows[11].raw_text,
        ),
    }
    lineage_drift = {
        name: observed
        for name, (passed, observed) in lineage_checks.items()
        if not passed
    }
    if lineage_drift:
        raise ValueError(
            "zInterp ReportErrorf candidate ctx callback field/root/register/"
            f"argument/use lineage drifted; drift={lineage_drift!r}"
        )
    callback_offset = "0x1c"
    prior = (existing_bridges or {}).get(callback_offset)
    if prior is not None:
        raise ValueError(
            "zInterp ReportErrorf candidate ctx callback has duplicate or "
            f"conflicting existing provenance at {callback_offset}: {prior!r}"
        )
    return {
        callback_offset: ReviewedLoopVptrStorageBridge(
            register="eax",
            storage_identity=_ZINTERP_CONTEXT_CALLBACK_IDENTITY,
            slot_displacement=0,
            assembly_source="cod",
        )
    }


def _reviewed_r3994_dplay_ordinal_thunk_indexes(
    retail_instructions: Sequence[Instruction],
    *,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge: BinaryNinjaBridge,
    ordinal_provider_thunks: Sequence[ProviderOrdinalImportThunk] = (),
    retail_import_targets: Sequence[Any] | None = None,
) -> IdentityIndexes:
    """Bind the one reviewed DPLAYX ordinal-4 local FF25 thunk."""

    if normalize_address(caller_start) != "0x48be10":
        return indexes
    if normalize_address(caller_end_exclusive) != "0x48be70":
        raise ValueError("reviewed DPLAYX ordinal caller extent drifted")
    addresses = _instruction_runtime_addresses(
        retail_instructions,
        source="bn",
        caller_start=address_value(caller_start),
    )
    matches: list[Instruction] = []
    call_indices: list[int] = []
    for index, (address, instruction) in enumerate(
        zip(addresses, retail_instructions)
    ):
        if address is not None and normalize_address(address) == "0x48be33":
            matches.append(instruction)
            call_indices.append(index)
    instruction_ends = [
        address_value(normalize_address(address)) + len(instruction.bytes)
        for address, instruction in zip(addresses, retail_instructions)
        if address is not None and instruction.bytes
    ]
    if not instruction_ends or max(instruction_ends) != address_value("0x48be6a"):
        raise ValueError(
            "reviewed DPLAYX ordinal functional body extent drifted inside "
            "its selected call-contract extent"
        )
    if len(matches) != 1:
        raise ValueError("reviewed DPLAYX ordinal call site is missing or duplicated")
    try:
        call_body = bytes(int(item, 16) for item in matches[0].bytes)
    except (TypeError, ValueError):
        call_body = b""
    if (
        call_body != bytes.fromhex("e8 b2 a5 03 00")
        or _instruction_mnemonic(matches[0]) != "call"
        or address_value("0x48be33") + 5
        + struct.unpack_from("<i", call_body, 1)[0]
        != address_value("0x4c63ea")
    ):
        raise ValueError("reviewed DPLAYX ordinal direct thunk transfer drifted")
    if (
        len(call_indices) != 1
        or _cleanup_after(retail_instructions, call_indices[0]) is not None
    ):
        raise ValueError("reviewed DPLAYX ordinal call gained caller cleanup")
    expected_pushes = {
        "0x48be14": bytes.fromhex("6a 00"),
        "0x48be16": bytes.fromhex("6a 00"),
        "0x48be1c": bytes.fromhex("6a 00"),
        "0x48be1e": bytes.fromhex("50"),
        "0x48be21": bytes.fromhex("6a 00"),
    }
    argument_rows: list[tuple[str, bytes]] = []
    for address, instruction in zip(addresses, retail_instructions):
        if (
            address is None
            or not address_value("0x48be14")
            <= address
            < address_value("0x48be33")
            or _instruction_mnemonic(instruction) != "push"
        ):
            continue
        try:
            body = bytes(int(item, 16) for item in instruction.bytes)
        except (TypeError, ValueError):
            body = b""
        argument_rows.append((normalize_address(address), body))
    if argument_rows != list(expected_pushes.items()):
        raise ValueError("reviewed DPLAYX ordinal five-argument route drifted")
    thunk_extent = _hexdump_bytes(bridge.hexdump("0x4c63ea", 6))
    if thunk_extent != bytes.fromhex("ff 25 54 c0 4c 00"):
        raise ValueError("reviewed DPLAYX ordinal FF25 thunk body drifted")
    if (
        _immutable_retail_interval(
            DEFAULT_REFERENCE,
            start=address_value("0x48be6a"),
            end_exclusive=address_value("0x48be70"),
        )
        != b"\x90" * 6
    ):
        raise ValueError(
            "reviewed DPLAYX ordinal caller padding drifted"
        )
    import_rows = [
        row
        for row in (
            retail_import_targets
            if retail_import_targets is not None
            else _retail_import_targets(DEFAULT_REFERENCE)[0]
        )
        if getattr(row, "address", "") == "0x4cc054"
    ]
    if (
        len(import_rows) != 1
        or getattr(import_rows[0], "dll", "") != "DPLAYX.dll"
        or getattr(import_rows[0], "import_name", "") != "#4"
        or getattr(import_rows[0], "import_ordinal", None) != 4
        or getattr(import_rows[0], "iat_end_rva", "") != "0xcc058"
    ):
        raise ValueError("reviewed DPLAYX ordinal immutable import tuple drifted")
    _require_exact_retail_storage_layout(
        address="0x4cc054",
        size=4,
        section_name=".rdata",
    )
    if _hexdump_bytes(bridge.hexdump("0x4cc054", 4)) != bytes.fromhex(
        "0c 8c 7c 00"
    ):
        raise ValueError("reviewed DPLAYX ordinal immutable IAT cell drifted")
    identity = "iat:ordinal:10:DPLAYX.dll:4"
    indexed_identity = indexes.storage_by_address.get("0x4cc054", "")
    if indexed_identity and indexed_identity != identity:
        raise ValueError("reviewed DPLAYX ordinal IAT identity conflicts")
    aliases = [
        address
        for address, current in indexes.storage_by_address.items()
        if current == identity
    ]
    if aliases not in ([], ["0x4cc054"]):
        raise ValueError("reviewed DPLAYX ordinal IAT identity collides")
    provider_identity = indexes.by_address.get("0x4c63ea", "")
    reviewed = dict(indexes.reviewed_direct_import_thunk_by_call_site)
    same_thunk_packages = [
        thunk
        for thunk in ordinal_provider_thunks
        if normalize_address(thunk.thunk_address) == "0x4c63ea"
    ]
    if len(same_thunk_packages) > 1:
        raise ValueError(
            "reviewed DPLAYX ordinal provider proof is duplicated or ambiguous"
        )
    if same_thunk_packages:
        package = same_thunk_packages[0]
        if (
            package.iat_identity != identity
            or package.import_dll.casefold() != "dplayx.dll"
            or package.import_ordinal != 4
            or package.provider_identity != provider_identity
        ):
            raise ValueError(
                "reviewed DPLAYX ordinal provider proof conflicts with its "
                "governed physical identity"
            )
    if (
        not provider_identity
        or provider_identity not in indexes.provider_ids
    ):
        raise ValueError(
            "reviewed DPLAYX ordinal provider proof conflicts with its "
            "governed physical identity"
        )
    if "0x48be33" not in reviewed:
        reviewed["0x48be33"] = ("0x4c63ea", provider_identity)
        indexes = replace(
            indexes,
            reviewed_direct_import_thunk_by_call_site=reviewed,
        )
    value = ("0x4c63ea", provider_identity)
    if (
        not provider_identity.startswith("provider:")
        or provider_identity not in indexes.provider_ids
        or indexes.reviewed_direct_import_thunk_by_call_site.get("0x48be33")
        != value
    ):
        raise ValueError(
            "reviewed DPLAYX ordinal call-site lacks its canonical provider identity"
        )
    if indexed_identity == identity:
        return indexes
    storage_by_address = dict(indexes.storage_by_address)
    storage_by_address["0x4cc054"] = identity
    return replace(indexes, storage_by_address=storage_by_address)


def _reviewed_r3994_dplay_ordinal_retail_bridge_names(
    retail_instructions: Sequence[Instruction],
    *,
    caller_start: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Sequence[Any]],
) -> dict[str, list[Any]]:
    """Expose only the finite DPLAY ordinal selector's exact friendly name."""

    result = {name: list(rows) for name, rows in bridge_names.items()}
    if normalize_address(caller_start) != "0x48be10":
        return result
    call_site = "0x48be33"
    thunk_address = "0x4c63ea"
    friendly_name = "DPLAYX_Ordinal4_ImportThunk"
    provider_identity = indexes.by_address.get(thunk_address, "")
    if (
        not provider_identity.startswith("provider:")
        or provider_identity not in indexes.provider_ids
        or indexes.reviewed_direct_import_thunk_by_call_site.get(call_site)
        != (thunk_address, provider_identity)
    ):
        raise ValueError(
            "reviewed DPLAYX ordinal friendly selector lacks its exact "
            "caller-local provider proof"
        )
    addresses = _instruction_runtime_addresses(
        retail_instructions,
        source="bn",
        caller_start=address_value(caller_start),
    )
    matching_calls = [
        instruction
        for address, instruction in zip(addresses, retail_instructions)
        if address is not None and normalize_address(address) == call_site
    ]
    if len(matching_calls) != 1:
        raise ValueError(
            "reviewed DPLAYX ordinal friendly selector call population drifted"
        )
    operand = re.sub(
        r"^(?:near|far)\s+(?:ptr\s+)?",
        "",
        _instruction_operand(matching_calls[0]).strip(),
        flags=re.IGNORECASE,
    )
    if operand != friendly_name:
        # A numeric rendering already selects the reviewed address directly.
        # Another friendly spelling remains unresolved; it is not an operand
        # fallback for this exact exception.
        if ADDRESS_RE.search(operand):
            return result
        raise ValueError(
            "reviewed DPLAYX ordinal friendly selector spelling drifted"
        )
    colliding_names = [
        name
        for name in result
        if name.casefold() == friendly_name.casefold()
        and name != friendly_name
    ]
    prior = result.get(friendly_name)
    prior_addresses: list[str] = []
    for row in prior or ():
        try:
            prior_addresses.append(
                normalize_address(str(getattr(row, "address", "")))
            )
        except ProgressError:
            prior_addresses.append("")
    if colliding_names or (
        prior is not None and prior_addresses != [thunk_address]
    ):
        raise ValueError(
            "reviewed DPLAYX ordinal friendly selector collides with a "
            "different or ambiguous bridge population"
        )
    if prior is None:
        result[friendly_name] = [
            SimpleNamespace(
                address=thunk_address,
                name=friendly_name,
                raw_name=friendly_name,
                full_name=friendly_name,
                kind="function",
            )
        ]
    return result


