        register="edx",
        source_register="ecx",
        source_provenance=aggregate_identity,
        receiver_register="ecx",
        receiver_provenance=aggregate_identity,
        storage_identity=HUD_UI_MGR_UPDATE_FRAME_LAYOUT_STORAGE_IDENTITY,
        slot_displacement=0,
        call_address="0x80",
