def _hud_ui_mgr_stats_list_set_visible_candidate_bridges(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
) -> tuple[
    dict[str, ReviewedStaticStorageReferenceBridge],
    dict[str, ReviewedMemberVptrStorageBridge],
]:
    """Prove one aggregate-field load feeding the final stats-list slot call."""
    normalized_start = normalize_address(caller_start)
    if normalized_start != HUD_UI_MGR_INIT_LAYOUTS_CALLER_START:
        return {}, {}
    if (
        caller_identity != HUD_UI_MGR_INIT_LAYOUTS_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != HUD_UI_MGR_INIT_LAYOUTS_CALLER_END_EXCLUSIVE
    ):
        raise ValueError(
            "HUD stats-list SetVisible candidate bridge requires the exact "
            "reviewed InitHudLayouts caller and extent"
        )

    definition = candidate.caller_definition
    target = candidate.target
    contribution_rows = [
        (entry, row)
        for entry in getattr(target, "translation_unit_function_order", ())
        for row in getattr(entry, "functions", ())
        if normalize_address(str(getattr(row, "address", "")))
        == HUD_UI_MGR_INIT_LAYOUTS_CALLER_START
    ]
    if (
        definition is None
        or definition.symbol != HUD_UI_MGR_INIT_LAYOUTS_CALLER_SYMBOL
        or len(definition.data) != len(definition.relocation_mask)
        or not definition.data
        or target is None
        or getattr(target, "name", "")
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or Path(str(getattr(target, "manifest_path", ""))).resolve()
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_MANIFEST.resolve()
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
        or tuple(getattr(target, "source_files", ())).count(
            HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        )
        != 1
        or len(contribution_rows) != 1
    ):
        raise ValueError(
            "HUD stats-list SetVisible candidate bridge requires the exact "
            "registered HUD target, caller definition, and contribution"
        )
    contribution, contribution_row = contribution_rows[0]
    if (
        getattr(contribution, "source_from", "")
        != HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        or getattr(contribution, "order_scope", "") != "authored"
        or getattr(contribution_row, "symbol", "") != ""
        or getattr(contribution_row, "symbol_regex", None)
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_SYMBOL_REGEX
        or re.fullmatch(
            HUD_UI_MGR_INIT_LAYOUTS_TARGET_SYMBOL_REGEX,
            definition.symbol,
        )
        is None
        or getattr(contribution_row, "name", "")
        != "HudUiMgr::InitHudLayouts"
        or getattr(contribution_row, "pipeline_class", "") != "authored"
        or getattr(contribution_row, "authored_order_role", "")
        != "authored-body"
        or not bool(getattr(contribution_row, "required_presence", False))
        or not bool(getattr(contribution_row, "full_order_gate", False))
    ):
        raise ValueError(
            "HUD stats-list SetVisible candidate bridge requires the exact "
            "authored InitHudLayouts hud.cpp contribution identity"
        )

    aggregate_identity = f"storage:{HUD_UI_MGR_AGGREGATE_SYMBOL_ID}"
    expected_storage = f"load({HUD_UI_MGR_STATS_LIST_IDENTITY})"
    if (
        indexes.storage_by_address.get(HUD_UI_MGR_AGGREGATE_ADDRESS)
        != aggregate_identity
        or indexes.storage_by_address.get(HUD_UI_MGR_STATS_LIST_ADDRESS)
        != HUD_UI_MGR_STATS_LIST_IDENTITY
        or [
            address
            for address, identity in indexes.storage_by_address.items()
            if identity == HUD_UI_MGR_STATS_LIST_IDENTITY
        ]
        != [HUD_UI_MGR_STATS_LIST_ADDRESS]
        or HUD_UI_MGR_STATS_LIST_IDENTITY in indexes.provider_ids
    ):
        raise ValueError(
            "HUD stats-list SetVisible candidate bridge rejects missing, "
            "aliased, or provider aggregate/field storage"
        )
    expected_rows = [
        row
        for row in expected
        if (
            row.get("identity_kind") == "virtual-slot"
            and row.get("storage_identity") == expected_storage
            and row.get("slot_displacement")
            == HUD_UI_MGR_STATS_LIST_VPTR_SLOT_DISPLACEMENT
        )
    ]
    if (
        len(expected_rows) != 1
        or any(
            expected_rows[0].get(key) != value
            for key, value in {
                "form": "call",
                "dispatch": "indirect",
                "target_identity": "",
                "cleanup_bytes": None,
            }.items()
        )
    ):
        raise ValueError(
            "HUD stats-list SetVisible candidate bridge requires one exact "
            "retail virtual-slot contract"
        )

    start = address_value(normalized_start)
    end = address_value(caller_end_exclusive)
    instructions = candidate.instructions
    addresses = _instruction_runtime_addresses(
        instructions,
        source="cod",
        caller_start=start,
    )
    counts: dict[int, int] = {}
    for address in addresses:
        if address is not None:
            counts[address] = counts.get(address, 0) + 1
    by_offset = {
        address - start: instruction
        for instruction, address in zip(instructions, addresses)
        if address is not None and counts.get(address) == 1
    }
    index_by_address = {
        address: index
        for index, address in enumerate(addresses)
        if address is not None and counts.get(address) == 1
    }
    symbol_pattern = re.escape(HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL)
    load_body = b"\x8b\x0d\x10\x76\x00\x00"
    load_pattern = (
        rf"mov\s+ecx\s*,\s*(?:dword\s+(?:ptr\s+)?)?"
        rf"{symbol_pattern}\+30224"
    )
    load_offsets = [
        offset
        for offset, instruction in by_offset.items()
        if (
            bytes(int(value, 16) for value in instruction.bytes)
            == load_body
            and re.fullmatch(
                load_pattern,
                instruction.raw_text.strip(),
                flags=re.IGNORECASE,
            )
            is not None
            and definition.data[offset : offset + len(load_body)]
            == load_body
        )
    ]
    if len(load_offsets) != 1:
        raise ValueError(
            "HUD stats-list SetVisible candidate bridge requires one exact "
            "unique relocation-backed aggregate-field load anchor"
        )
    load_offset = load_offsets[0]
    relative_rows = {
        0x00: (
            b"\x8b\x0d\x10\x76\x00\x00",
            load_pattern,
        ),
        0x06: (
            b"\xc7\x05\x10\x00\x00\x00\x01\x00\x00\x00",
            rf"mov\s+(?:dword\s+(?:ptr\s+)?)?"
            rf"{symbol_pattern}\+16\s*,\s*1",
        ),
        0x12: (
            b"\x74\x17",
            r"je\s+(?:SHORT\s+)?\$L[0-9]+",
        ),
        0x14: (
            b"\x8b\x11",
            r"mov\s+edx\s*,\s*(?:dword\s+(?:ptr\s+)?)?\[ecx\]",
        ),
        0x16: (
            b"\x6a\x01",
            r"push\s+1",
        ),
        0x18: (
            b"\xff\x52\x60",
            r"call\s+(?:dword\s+(?:ptr\s+)?)?\[edx\+96\]",
        ),
    }
    exact_rows = {
        load_offset + relative_offset: row
        for relative_offset, row in relative_rows.items()
    }
    if (
        not set(exact_rows).issubset(by_offset)
        or any(counts.get(start + offset) != 1 for offset in exact_rows)
    ):
        raise ValueError(
            "HUD stats-list SetVisible candidate bridge requires one unique "
            "instruction at every reviewed contribution offset"
        )
    for offset, (body, pattern) in exact_rows.items():
        instruction = by_offset[offset]
        if (
            bytes(int(value, 16) for value in instruction.bytes) != body
            or re.fullmatch(
                pattern,
                instruction.raw_text.strip(),
                flags=re.IGNORECASE,
            )
            is None
            or definition.data[offset : offset + len(body)] != body
        ):
            raise ValueError(
                "HUD stats-list SetVisible candidate bridge requires exact "
                f"instruction bytes and operands at +{hex(offset)}"
            )

    null_check_offset = load_offset + 0x10
    null_check = by_offset.get(null_check_offset)
    null_check_match = (
        re.fullmatch(
            r"cmp\s+ecx\s*,\s*(?P<zero_register>"
            r"e(?:ax|dx|bx|bp|si|di))",
            null_check.raw_text.strip(),
            flags=re.IGNORECASE,
        )
        if null_check is not None
        else None
    )
    zero_register = (
        null_check_match.group("zero_register").lower()
        if null_check_match is not None
        else ""
    )
    register_codes = {
        "eax": 0,
        "edx": 2,
        "ebx": 3,
        "ebp": 5,
        "esi": 6,
        "edi": 7,
    }
    null_check_body = (
        bytes((0x3B, 0xC8 | register_codes[zero_register]))
        if zero_register in register_codes
        else b""
    )
    null_check_index = index_by_address.get(start + null_check_offset)
    zero_writes = (
        [
            index
            for index in range(null_check_index)
            if _instruction_may_clobber_register(
                instructions[index],
                zero_register,
            )
        ]
        if null_check_index is not None and zero_register
        else []
    )
    zero_seed_index = zero_writes[-1] if zero_writes else None
    zero_seed = (
        instructions[zero_seed_index]
        if zero_seed_index is not None
        else None
    )
    zero_seed_address = (
        addresses[zero_seed_index]
        if zero_seed_index is not None
        else None
    )
    zero_seed_code = register_codes.get(zero_register)
    zero_seed_body = (
        bytes((0x33, 0xC0 | (zero_seed_code << 3) | zero_seed_code))
        if zero_seed_code is not None
        else b""
    )
    if (
        null_check is None
        or null_check_index is None
        or counts.get(start + null_check_offset) != 1
        or bytes(int(value, 16) for value in null_check.bytes)
        != null_check_body
        or definition.data[
            null_check_offset : null_check_offset + len(null_check_body)
        ]
        != null_check_body
        or zero_seed is None
        or zero_seed_address is None
        or bytes(int(value, 16) for value in zero_seed.bytes)
        != zero_seed_body
        or re.fullmatch(
            rf"xor\s+{zero_register}\s*,\s*{zero_register}",
            zero_seed.raw_text.strip(),
            flags=re.IGNORECASE,
        )
        is None
        or definition.data[
            zero_seed_address - start :
            zero_seed_address - start + len(zero_seed_body)
        ]
        != zero_seed_body
    ):
        raise ValueError(
            "HUD stats-list SetVisible candidate bridge requires an exact "
            "unique zero-register seed and unclobbered null comparison"
        )

    for relocation_offset, addend in (
        (
            load_offset + 0x02,
            HUD_UI_MGR_STATS_LIST_DISPLACEMENT,
        ),
        (
            load_offset + 0x08,
            0x10,
        ),
    ):
        relocations = [
            relocation
            for relocation in definition.relocations
            if relocation.offset == relocation_offset
        ]
        if (
            len(relocations) != 1
            or relocations[0].type != IMAGE_REL_I386_DIR32
            or relocations[0].symbol_name
            != HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
            or struct.unpack_from(
                "<I",
                definition.data,
                relocation_offset,
            )[0]
            != addend
            or not all(
                definition.relocation_mask[index]
                for index in range(relocation_offset, relocation_offset + 4)
            )
        ):
            raise ValueError(
                "HUD stats-list SetVisible candidate bridge requires exact "
                "aggregate-field DIR32 relocations"
            )
    if (
        definition.undefined_external_data.count(
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        )
        != 1
        or HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        in definition.defined_external_data
    ):
        raise ValueError(
            "HUD stats-list SetVisible candidate bridge requires one exact "
            "undefined aggregate data identity"
        )

    null_branch_offset = load_offset + 0x12
    vptr_load_offset = load_offset + 0x14
    call_offset = load_offset + 0x18
    null_target_offset = load_offset + 0x2B
    branch_address = start + null_branch_offset
    branch_index = index_by_address[branch_address]
    branch = _exact_local_direct_branch(
        instructions[branch_index],
        instruction_index=branch_index,
        instruction_addresses=addresses,
        instruction_index_by_address=index_by_address,
        source="cod",
        caller_start=start,
        caller_end=end,
    )
    load_index = index_by_address[start + load_offset]
    vptr_index = index_by_address[start + vptr_load_offset]
    call_index = index_by_address[start + call_offset]
    reviewed_window = range(load_index, call_index + 1)
    if (
        branch is None
        or branch[0] != "conditional"
        or addresses[branch[1]] != start + null_target_offset
        or sum(
            1
            for index in reviewed_window
            if (
                _instruction_mnemonic(instructions[index]) == "call"
                and _memory_slot(
                    _instruction_operand(instructions[index])
                )[1]
                == HUD_UI_MGR_STATS_LIST_VPTR_SLOT_DISPLACEMENT
            )
        )
        != 1
        or any(
            _instruction_mnemonic(instructions[index]).startswith("j")
            for index in reviewed_window
            if index != branch_index
        )
        or any(
            _instruction_may_clobber_register(
                instructions[index],
                "ecx",
            )
            for index in range(load_index + 1, vptr_index)
        )
        or any(
            _instruction_may_clobber_register(
                instructions[index],
                "ecx",
            )
            or _instruction_may_clobber_register(
                instructions[index],
                "edx",
            )
            for index in range(vptr_index + 1, call_index)
        )
        or _cleanup_after(instructions, call_index) is not None
        or any(
            definition.relocation_mask[
                call_offset : call_offset + 3
            ]
        )
    ):
        raise ValueError(
            "HUD stats-list SetVisible candidate bridge rejects alternate "
            "calls, CFG, cleanup, receiver/vptr clobbers, or masked call bytes"
        )

    expression = (
        f"{HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL}"
        f"+{HUD_UI_MGR_STATS_LIST_DISPLACEMENT}"
    )
    return (
        {
            expression: ReviewedStaticStorageReferenceBridge(
                aggregate_symbol=HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
                displacement=HUD_UI_MGR_STATS_LIST_DISPLACEMENT,
                access_width=HUD_UI_MGR_STATS_LIST_ACCESS_WIDTH,
                storage_identity=HUD_UI_MGR_STATS_LIST_IDENTITY,
            )
        },
        {
            normalize_address(vptr_load_offset): ReviewedMemberVptrStorageBridge(
                register="edx",
                source_register="ecx",
                source_provenance=HUD_UI_MGR_STATS_LIST_IDENTITY,
                receiver_register="ecx",
                receiver_provenance=HUD_UI_MGR_STATS_LIST_IDENTITY,
                storage_identity=expected_storage,
                slot_displacement=(
                    HUD_UI_MGR_STATS_LIST_VPTR_SLOT_DISPLACEMENT
                ),
                call_address=normalize_address(call_offset),
            )
        },
    )


def _ftol_import_thunk_retail_bridge(
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge_by_address: Mapping[str, Any],
    bridge_by_name: Mapping[str, Any],
    bridge_data_rows: Sequence[Any],
    bridge: BinaryNinjaBridge,
) -> tuple[str, dict[str, list[Any]]]:
    thunk_symbol = bridge_by_name.get(MSVC_FTOL_RETAIL_THUNK_NAME)
    if thunk_symbol is None:
        return "", {}
    import_symbol = bridge_by_name.get(MSVC_FTOL_IMPORT_NAME)
    address_symbol = bridge_by_address.get(MSVC_FTOL_PROVIDER_ADDRESS)
    if (
        getattr(thunk_symbol, "address", "") != MSVC_FTOL_PROVIDER_ADDRESS
        or getattr(thunk_symbol, "name", "") != MSVC_FTOL_RETAIL_THUNK_NAME
        or getattr(thunk_symbol, "raw_name", "")
        != MSVC_FTOL_RETAIL_THUNK_NAME
        or getattr(thunk_symbol, "kind", "") != "function"
        or import_symbol is None
        or getattr(import_symbol, "address", "")
        != MSVC_FTOL_PROVIDER_ADDRESS
        or getattr(import_symbol, "name", "") != MSVC_FTOL_IMPORT_NAME
        or getattr(import_symbol, "raw_name", "") != MSVC_FTOL_IMPORT_NAME
        or getattr(import_symbol, "full_name", "") != MSVC_FTOL_IMPORT_NAME
        or getattr(import_symbol, "kind", "") != "import"
        or address_symbol is None
        or getattr(address_symbol, "address", "")
        != MSVC_FTOL_PROVIDER_ADDRESS
        or getattr(address_symbol, "name", "") != MSVC_FTOL_IMPORT_NAME
        or getattr(address_symbol, "kind", "") != "import"
        or MSVC_FTOL_CANDIDATE_SYMBOL in bridge_by_name
    ):
        raise ValueError(
            "MSVC _ftol import-thunk bridge lacks the exact current "
            "collocated retail function/import symbols"
        )

    provider_symbol = document.collection("symbols").get(
        MSVC_FTOL_PROVIDER_SYMBOL_ID
    )
    provider_block = document.collection("physical_blocks").get(
        MSVC_FTOL_PROVIDER_BLOCK_ID
    )
    if (
        not isinstance(provider_symbol, Mapping)
        or provider_symbol.get("address") != MSVC_FTOL_PROVIDER_ADDRESS
        or provider_symbol.get("end_exclusive") != "0x4c60b0"
        or provider_symbol.get("size") != 10
        or provider_symbol.get("extent_state") != "known"
        or provider_symbol.get("binary") != "recoil"
        or provider_symbol.get("kind") != "function"
        or provider_symbol.get("pipeline_class") != "non-authored"
        or provider_symbol.get("authored_order_role") != "non-authored"
        or provider_symbol.get("navigation_name")
        != MSVC_FTOL_RETAIL_THUNK_NAME
        or provider_symbol.get("output_section_id") != "recoil:section:.text"
        or provider_symbol.get("physical_block_id")
        != MSVC_FTOL_PROVIDER_BLOCK_ID
        or indexes.by_address.get(MSVC_FTOL_PROVIDER_ADDRESS)
        != MSVC_FTOL_PROVIDER_IDENTITY
        or MSVC_FTOL_PROVIDER_IDENTITY not in indexes.provider_ids
    ):
        raise ValueError(
            "MSVC _ftol import-thunk bridge lacks the exact governed "
            "non-authored provider symbol"
        )
    mapping = (
        provider_block.get("mapping")
        if isinstance(provider_block, Mapping)
        else None
    )
    authored_order = (
        provider_block.get("order", {}).get("authored")
        if isinstance(provider_block, Mapping)
        and isinstance(provider_block.get("order"), Mapping)
        else None
    )
    current_not_applicable = (
        isinstance(authored_order, Mapping)
        and all(
            isinstance(authored_order.get(key), Mapping)
            and authored_order[key].get("result") == "not-applicable"
            and authored_order[key].get("disposition") == "accepted"
            and authored_order[key].get("freshness") == "current"
            and authored_order[key].get("gating") is True
            and authored_order[key].get("validation_mode") == "live"
            for key in (
                "authored_linked_order",
                "authored_object_order",
                "block_precedence",
                "linked_identity_presence",
                "object_identity_presence",
            )
        )
    )
    if (
        not isinstance(provider_block, Mapping)
        or provider_block.get("binary") != "recoil"
        or provider_block.get("row_kind") != "physical-source-block"
        or provider_block.get("start") != "0x4c60a0"
        or provider_block.get("end_exclusive") != "0x4c60b0"
        or provider_block.get("contribution_kind") != "provider"
        or provider_block.get("agent_source_path")
        != "provider:msvc-crt-import-thunks"
        or provider_block.get("source_path")
        != "provider:msvc-crt-import-thunks"
        or provider_block.get("contribution_ids")
        != [
            "recoil:function:0x4c60a0",
            MSVC_FTOL_PROVIDER_SYMBOL_ID,
        ]
        or not isinstance(mapping, Mapping)
        or mapping.get("status") != "provider-boundary"
        or not current_not_applicable
    ):
        raise ValueError(
            "MSVC _ftol import-thunk bridge lacks the exact current "
            "provider-boundary block"
        )

    iat_packages = [
        package
        for package in _current_tracker_iat_storage_packages(document)
        if package.address == MSVC_FTOL_IAT_ADDRESS
    ]
    iat_storage = document.collection("storage_contributions").get(
        f"recoil:storage:va:{MSVC_FTOL_IAT_ADDRESS}"
    )
    if (
        len(iat_packages) != 1
        or iat_packages[0].import_dll != "MSVCRT.dll"
        or iat_packages[0].import_name != MSVC_FTOL_IMPORT_NAME
        or iat_packages[0].object_symbol != MSVC_FTOL_IAT_OBJECT_SYMBOL
        or iat_packages[0].identity != MSVC_FTOL_IAT_STORAGE_IDENTITY
        or not isinstance(iat_storage, Mapping)
        or iat_storage.get("owner_ids") != [MSVC_FTOL_IAT_OWNER_ID]
        or indexes.by_address.get(MSVC_FTOL_IAT_ADDRESS)
        != MSVC_FTOL_IAT_PROVIDER_IDENTITY
        or MSVC_FTOL_IAT_PROVIDER_IDENTITY not in indexes.provider_ids
        or indexes.storage_by_address.get(MSVC_FTOL_IAT_ADDRESS)
        != MSVC_FTOL_IAT_STORAGE_IDENTITY
        or indexes.storage_by_name.get(MSVC_FTOL_IMPORT_NAME)
        != MSVC_FTOL_IAT_STORAGE_IDENTITY
        or indexes.storage_by_name.get(MSVC_FTOL_IAT_OBJECT_SYMBOL)
        != MSVC_FTOL_IAT_STORAGE_IDENTITY
    ):
        raise ValueError(
            "MSVC _ftol import-thunk bridge lacks the exact current "
            "registered MSVCRT _ftol IAT provider package"
        )

    iat_rows = [
        row
        for row in bridge_data_rows
        if getattr(row, "address", "") == MSVC_FTOL_IAT_ADDRESS
    ]
    lookup_rows = [
        row
        for row in bridge_data_rows
        if getattr(row, "address", "") == "0x4d8368"
    ]
    import_name_rows = [
        row
        for row in bridge_data_rows
        if getattr(row, "address", "") == "0x4d8580"
    ]
    if (
        len(iat_rows) != 1
        or getattr(iat_rows[0], "name", "") != MSVC_FTOL_IMPORT_NAME
        or getattr(iat_rows[0], "raw_name", "") != MSVC_FTOL_IMPORT_NAME
        or getattr(iat_rows[0], "size", 0) != 4
        or getattr(iat_rows[0], "type_text", "")
        != "int32_t (* const)(double value @ st0)"
        or len(lookup_rows) != 1
        or getattr(lookup_rows[0], "name", "")
        != "__import_lookup_table_3(MSVCRT:_ftol)"
        or getattr(lookup_rows[0], "size", 0) != 4
        or len(import_name_rows) != 1
        or getattr(import_name_rows[0], "name", "")
        != "__import_by_name_3(MSVCRT:_ftol)"
        or getattr(import_name_rows[0], "size", 0) != 8
    ):
        raise ValueError(
            "MSVC _ftol import-thunk bridge lacks the exact current "
            "MSVCRT import/IAT data"
        )
    thunk_bytes = _hexdump_bytes(
        bridge.hexdump(MSVC_FTOL_PROVIDER_ADDRESS, 10)
    )
    if thunk_bytes != bytes.fromhex("ff 25 ac c5 4c 00 cc cc cc cc"):
        raise ValueError(
            "MSVC _ftol import-thunk bridge retail thunk bytes or IAT "
            "operand drifted"
        )
    return (
        MSVC_FTOL_PROVIDER_IDENTITY,
        {MSVC_FTOL_RETAIL_THUNK_NAME: [thunk_symbol]},
    )


def _gettickcount_named_import_thunk_retail_bridge(
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge_by_address: Mapping[str, Any],
    bridge_by_name: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    reference: Path = DEFAULT_REFERENCE,
) -> tuple[ProviderNamedImportThunk | None, dict[str, list[Any]]]:
    """Prove the one fixed named KERNEL32 GetTickCount retail thunk."""
    thunk_symbol = bridge_by_name.get(GETTICKCOUNT_RETAIL_THUNK_NAME)
    if thunk_symbol is None:
        return None, {}
    import_symbol = bridge_by_name.get(GETTICKCOUNT_IMPORT_NAME)
    address_symbol = bridge_by_address.get(GETTICKCOUNT_PROVIDER_ADDRESS)
    if (
        getattr(thunk_symbol, "address", "") != GETTICKCOUNT_PROVIDER_ADDRESS
        or getattr(thunk_symbol, "name", "") != GETTICKCOUNT_RETAIL_THUNK_NAME
        or getattr(thunk_symbol, "raw_name", "")
        != GETTICKCOUNT_RETAIL_THUNK_NAME
        or getattr(thunk_symbol, "full_name", "")
        not in {"", GETTICKCOUNT_RETAIL_THUNK_NAME}
        or getattr(thunk_symbol, "kind", "") != "function"
        or import_symbol is None
        or getattr(import_symbol, "address", "")
        != GETTICKCOUNT_PROVIDER_ADDRESS
        or getattr(import_symbol, "name", "") != GETTICKCOUNT_IMPORT_NAME
        or getattr(import_symbol, "raw_name", "")
        != GETTICKCOUNT_IMPORT_NAME
        or getattr(import_symbol, "full_name", "")
        != GETTICKCOUNT_IMPORT_NAME
        or getattr(import_symbol, "kind", "") != "import"
        or address_symbol is None
        or getattr(address_symbol, "address", "")
        != GETTICKCOUNT_PROVIDER_ADDRESS
        or getattr(address_symbol, "name", "")
        != GETTICKCOUNT_IMPORT_NAME
        or getattr(address_symbol, "kind", "") != "import"
        or bridge_by_name.get(GETTICKCOUNT_CANDIDATE_CALLABLE) is not None
        or bridge_by_name.get(GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL) is not None
    ):
        raise ValueError(
            "GetTickCount named import-thunk bridge lacks its exact distinct "
            "retail BN function name and address"
        )

    symbol = document.collection("symbols").get(
        GETTICKCOUNT_PROVIDER_SYMBOL_ID
    )
    owner = document.collection("owners").get(
        GETTICKCOUNT_PROVIDER_OWNER_ID
    )
    block = document.collection("physical_blocks").get(
        GETTICKCOUNT_PROVIDER_BLOCK_ID
    )
    expected_relationships = [
        {"address": GETTICKCOUNT_PROVIDER_ADDRESS, "kind": "anchor-address"},
        {
            "address": GETTICKCOUNT_PROVIDER_ADDRESS,
            "kind": "primary-function",
            "symbol_id": GETTICKCOUNT_PROVIDER_SYMBOL_ID,
        },
    ]
    if (
        not isinstance(symbol, Mapping)
        or symbol.get("address") != GETTICKCOUNT_PROVIDER_ADDRESS
        or symbol.get("end_exclusive")
        != GETTICKCOUNT_PROVIDER_END_EXCLUSIVE
        or symbol.get("size") != 16
        or symbol.get("extent_state") != "known"
        or symbol.get("binary") != "recoil"
        or symbol.get("kind") != "function"
        or symbol.get("pipeline_class") != "non-authored"
        or symbol.get("authored_order_role") != "non-authored"
        or symbol.get("navigation_name") != GETTICKCOUNT_RETAIL_THUNK_NAME
        or symbol.get("output_section_id") != "recoil:section:.text"
        or symbol.get("ownership_state") != "primary-owned"
        or symbol.get("physical_block_id")
        != GETTICKCOUNT_PROVIDER_BLOCK_ID
        or not isinstance(owner, Mapping)
        or owner.get("binary") != "recoil"
        or owner.get("kind") != "provider-boundary"
        or owner.get("blocker") != "none"
        or owner.get("lifecycle_state") != "accepted"
        or owner.get("provider_state") != "accepted"
        or owner.get("relationships") != expected_relationships
        or owner.get("source_paths") != []
        or owner.get("gates")
        != {
            "boundary": "accepted",
            "byte": "deferred",
            "data": "none",
            "functional": "none",
            "owner_linkage": "none",
            "source": "accepted",
        }
        or indexes.by_address.get(GETTICKCOUNT_PROVIDER_ADDRESS)
        != GETTICKCOUNT_PROVIDER_IDENTITY
        or GETTICKCOUNT_PROVIDER_IDENTITY not in indexes.provider_ids
    ):
        raise ValueError(
            "GetTickCount named import-thunk bridge lacks the exact accepted "
            "tracker provider owner/function and gates"
        )

    mapping = block.get("mapping") if isinstance(block, Mapping) else None
    authored_order = (
        block.get("order", {}).get("authored")
        if isinstance(block, Mapping)
        and isinstance(block.get("order"), Mapping)
        else None
    )
    current_not_applicable = (
        isinstance(authored_order, Mapping)
        and all(
            isinstance(authored_order.get(key), Mapping)
            and authored_order[key].get("result") == "not-applicable"
            and authored_order[key].get("disposition") == "accepted"
            and authored_order[key].get("freshness") == "current"
            and authored_order[key].get("gating") is True
            and authored_order[key].get("validation_mode") == "live"
            for key in AUTHORED_ORDER_DIMENSIONS
        )
    )
    if (
        not isinstance(block, Mapping)
        or block.get("binary") != "recoil"
        or block.get("row_kind") != "physical-source-block"
        or block.get("start") != GETTICKCOUNT_PROVIDER_ADDRESS
        or block.get("end_exclusive")
        != GETTICKCOUNT_PROVIDER_END_EXCLUSIVE
        or block.get("contribution_kind") != "provider"
        or block.get("agent_source_path") != GETTICKCOUNT_PROVIDER_PATH
        or block.get("source_path") != GETTICKCOUNT_PROVIDER_PATH
        or block.get("contribution_ids")
        != [GETTICKCOUNT_PROVIDER_SYMBOL_ID]
        or not isinstance(mapping, Mapping)
        or mapping.get("status") != "provider-boundary"
        or not current_not_applicable
    ):
        raise ValueError(
            "GetTickCount named import-thunk bridge lacks its exact current "
            "provider block and non-authored order gates"
        )

    target = load_manifest(
        GETTICKCOUNT_PROVIDER_ORDER_MANIFEST,
        enforce_source_policy=False,
    )
    rows = tuple(getattr(target, "functions", ()))
    translation_rows = tuple(
        (entry, row)
        for entry in getattr(target, "translation_unit_function_order", ())
        for row in getattr(entry, "functions", ())
    )
    linked_intervals = tuple(getattr(target, "linked_function_intervals", ()))
    exact_row = (
        len(rows) == 1
        and getattr(rows[0], "address", "") == GETTICKCOUNT_PROVIDER_ADDRESS
        and getattr(rows[0], "symbol", "")
        == GETTICKCOUNT_CANDIDATE_CALLABLE
        and getattr(rows[0], "provenance", "") == "provider-boundary"
        and getattr(rows[0], "pipeline_class", "") == "non-authored"
        and getattr(rows[0], "authored_order_role", "") == "non-authored"
        and getattr(rows[0], "required_presence", None) is True
        and getattr(rows[0], "full_order_gate", None) is True
    )
    if (
        getattr(target, "name", "")
        != GETTICKCOUNT_PROVIDER_ORDER_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or Path(str(getattr(target, "manifest_path", ""))).resolve()
        != GETTICKCOUNT_PROVIDER_ORDER_MANIFEST.resolve()
        or getattr(target, "retail_start", "")
        != GETTICKCOUNT_PROVIDER_ADDRESS
        or getattr(target, "retail_end_exclusive", "")
        != GETTICKCOUNT_PROVIDER_END_EXCLUSIVE
        or getattr(target, "check_translation_unit_function_order", None)
        is not True
        or not exact_row
        or len(translation_rows) != 1
        or translation_rows[0][1] != rows[0]
        or getattr(translation_rows[0][0], "order_scope", "") != "authored"
        or len(linked_intervals) != 1
        or getattr(linked_intervals[0], "order_scope", "") != "full"
        or getattr(linked_intervals[0], "retail_start", "")
        != GETTICKCOUNT_PROVIDER_ADDRESS
        or getattr(linked_intervals[0], "retail_end_exclusive", "")
        != GETTICKCOUNT_PROVIDER_END_EXCLUSIVE
        or tuple(getattr(linked_intervals[0], "functions", ())) != rows
    ):
        raise ValueError(
            "GetTickCount named import-thunk bridge lacks its exact synchronized "
            "governed provider-order manifest row"
        )

    retail_import, _directory_context = retail_import_target(
        reference=reference,
        address=GETTICKCOUNT_IAT_ADDRESS,
        dll=GETTICKCOUNT_IMPORT_DLL,
        import_name=GETTICKCOUNT_IMPORT_NAME,
    )
    if (
        retail_import.address != GETTICKCOUNT_IAT_ADDRESS
        or retail_import.dll != GETTICKCOUNT_IMPORT_DLL
        or retail_import.import_name != GETTICKCOUNT_IMPORT_NAME
        or retail_import.import_ordinal is not None
    ):
        raise ValueError(
            "GetTickCount named import-thunk bridge immutable retail import "
            "tuple drifted"
        )
    thunk_bytes = _hexdump_bytes(
        bridge.hexdump(GETTICKCOUNT_PROVIDER_ADDRESS, 16)
    )
    if thunk_bytes != bytes.fromhex(
        "ff 25 40 c1 4c 00 90 90 90 90 90 90 90 90 90 90"
    ):
        raise ValueError(
            "GetTickCount named import-thunk bytes, IAT operand, instruction "
            "extent, or NOP padding drifted"
        )
    return (
        ProviderNamedImportThunk(
            provider_identity=GETTICKCOUNT_PROVIDER_IDENTITY,
            thunk_address=GETTICKCOUNT_PROVIDER_ADDRESS,
            retail_name=GETTICKCOUNT_RETAIL_THUNK_NAME,
            callable_symbol=GETTICKCOUNT_CANDIDATE_CALLABLE,
            iat_object_symbol=GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL,
            iat_identity=GETTICKCOUNT_IAT_IDENTITY,
            iat_address=GETTICKCOUNT_IAT_ADDRESS,
            import_dll=GETTICKCOUNT_IMPORT_DLL,
            import_name=GETTICKCOUNT_IMPORT_NAME,
        ),
        {GETTICKCOUNT_RETAIL_THUNK_NAME: [thunk_symbol]},
    )


def _gettickcount_retail_e8_call_population(
    retail_instructions: Sequence[Instruction],
    *,
    thunk: ProviderNamedImportThunk | None,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> tuple[int, ...]:
    """Prove the immutable retail E8 population without consulting candidate state."""

    if (
        caller_identity != GETTICKCOUNT_CALLER_IDENTITY
        or normalize_address(caller_start) != GETTICKCOUNT_CALLER_START
        or normalize_address(caller_end_exclusive)
        != GETTICKCOUNT_CALLER_END_EXCLUSIVE
    ):
        return ()
    if thunk is None:
        raise ValueError(
            "GetTickCount retail E8 proof has no proven immutable retail thunk"
        )
    retail_addresses = _instruction_runtime_addresses(
        retail_instructions,
        source="bn",
        caller_start=address_value(GETTICKCOUNT_CALLER_START),
    )
    retail_calls = [
        (address, instruction)
        for address, instruction in zip(retail_addresses, retail_instructions)
        if _instruction_mnemonic(instruction) == "call"
        and address in GETTICKCOUNT_RETAIL_E8_CALL_BYTES
    ]
    retail_ff_d7_calls = [
        instruction
        for instruction in retail_instructions
        if _instruction_mnemonic(instruction) == "call"
        and tuple(value.lower() for value in instruction.bytes) == ("ff", "d7")
    ]
    if (
        tuple(address for address, _instruction in retail_calls)
        != tuple(GETTICKCOUNT_RETAIL_E8_CALL_BYTES)
        or retail_ff_d7_calls
    ):
        raise ValueError(
            "GetTickCount retail truth requires exactly three direct E8 thunk "
            "calls and no candidate-shaped FF D7 calls"
        )
    for address, instruction in retail_calls:
        try:
            body = bytes(int(value, 16) for value in instruction.bytes)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                "GetTickCount retail caller callsite bytes are malformed"
            ) from exc
        if (
            body != GETTICKCOUNT_RETAIL_E8_CALL_BYTES[address]
            or address + 5 + struct.unpack_from("<i", body, 1)[0]
            != address_value(GETTICKCOUNT_PROVIDER_ADDRESS)
            or _instruction_operand(instruction).strip()
            != GETTICKCOUNT_RETAIL_THUNK_NAME
        ):
            raise ValueError(
                "GetTickCount retail caller requires exact direct E8 calls to "
                "the named provider thunk"
            )
    return tuple(address for address, _instruction in retail_calls)


def _gettickcount_named_import_thunk_candidate_bridges(
    retail_e8_call_population: Sequence[int],
    candidate: CandidateAssembly,
    *,
    thunk: ProviderNamedImportThunk | None,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
) -> tuple[dict[str, str], dict[str, str]]:
    """Prove one exact direct-thunk or legacy register-IAT candidate form."""
    if (
        caller_identity != GETTICKCOUNT_CALLER_IDENTITY
        or normalize_address(caller_start) != GETTICKCOUNT_CALLER_START
        or normalize_address(caller_end_exclusive)
        != GETTICKCOUNT_CALLER_END_EXCLUSIVE
    ):
        return {}, {}
    if thunk is None:
        raise ValueError(
            "GetTickCount candidate bridge has no proven immutable retail thunk"
        )
    if tuple(retail_e8_call_population) != tuple(
        GETTICKCOUNT_RETAIL_E8_CALL_BYTES
    ):
        raise ValueError(
            "GetTickCount candidate bridge lacks the exact immutable retail "
            "E8 call population"
        )
    caller = document.collection("symbols").get(
        GETTICKCOUNT_CALLER_IDENTITY.removeprefix("symbol:")
    )
    definition = candidate.caller_definition
    if (
        not isinstance(caller, Mapping)
        or caller.get("binary") != "recoil"
        or caller.get("kind") != "function"
        or caller.get("pipeline_class") != "authored"
        or caller.get("address") != GETTICKCOUNT_CALLER_START
        or caller.get("end_exclusive")
        != GETTICKCOUNT_CALLER_END_EXCLUSIVE
        or caller.get("extent_state") != "known"
        or caller.get("size") != 0xA0
        or caller.get("ownership_state") != "primary-owned"
        or indexes.by_address.get(GETTICKCOUNT_CALLER_START)
        != GETTICKCOUNT_CALLER_IDENTITY
        or definition is None
        or definition.symbol != GETTICKCOUNT_CALLER_SYMBOL
    ):
        raise ValueError(
            "GetTickCount candidate bridge requires its exact governed caller "
            "identity, extent, and COD definition"
        )
    if (
        thunk
        != ProviderNamedImportThunk(
            provider_identity=GETTICKCOUNT_PROVIDER_IDENTITY,
            thunk_address=GETTICKCOUNT_PROVIDER_ADDRESS,
            retail_name=GETTICKCOUNT_RETAIL_THUNK_NAME,
            callable_symbol=GETTICKCOUNT_CANDIDATE_CALLABLE,
            iat_object_symbol=GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL,
            iat_identity=GETTICKCOUNT_IAT_IDENTITY,
            iat_address=GETTICKCOUNT_IAT_ADDRESS,
            import_dll=GETTICKCOUNT_IMPORT_DLL,
            import_name=GETTICKCOUNT_IMPORT_NAME,
        )
        or indexes.by_address.get(thunk.thunk_address)
        != thunk.provider_identity
        or thunk.provider_identity not in indexes.provider_ids
        or indexes.by_candidate_name.get(thunk.callable_symbol, "")
        or indexes.by_candidate_name.get(thunk.iat_object_symbol, "")
        or indexes.storage_by_name.get(thunk.callable_symbol, "")
        or indexes.storage_by_name.get(thunk.iat_object_symbol, "")
        not in {"", thunk.iat_identity}
        or thunk.callable_symbol in bridge_names
        or thunk.iat_object_symbol in bridge_names
    ):
        raise ValueError(
            "GetTickCount candidate bridge has provider/package identity drift "
            "or a callable/IAT collision"
        )

    offsets = _candidate_complete_instruction_offsets(candidate)
    rows_by_offset = {
        offset: (index, candidate.instructions[index])
        for index, offset in enumerate(offsets)
        if offset is not None
    }
    direct_like_calls = [
        (offset, instruction)
        for offset, (_index, instruction) in rows_by_offset.items()
        if _instruction_mnemonic(instruction) in {"call", "jmp"}
        and (
            _instruction_operand(instruction).strip().casefold()
            == GETTICKCOUNT_CANDIDATE_CALLABLE.casefold()
            or GETTICKCOUNT_CANDIDATE_CALLABLE.casefold()
            in _instruction_operand(instruction).casefold()
        )
    ]
    candidate_iat_mentions = (
        any(
            GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL.casefold()
            in _instruction_operand(instruction).casefold()
            for instruction in candidate.instructions
        )
        or any(
            relocation.symbol_name.casefold()
            == GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL.casefold()
            for relocation in definition.relocations
        )
        or any(
            name.casefold()
            == GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL.casefold()
            for name in (
                *definition.undefined_external_functions,
                *definition.undefined_external_data,
                *definition.defined_external_functions,
                *definition.defined_external_data,
            )
        )
    )
    if not direct_like_calls and not candidate_iat_mentions:
        return {}, {}
    if direct_like_calls:
        direct_rows = [
            rows_by_offset.get(offset)
            for offset in GETTICKCOUNT_CANDIDATE_DIRECT_CALL_OFFSETS
        ]
        virtual_rows = [
            rows_by_offset.get(offset)
            for offset in GETTICKCOUNT_CANDIDATE_DIRECT_VIRTUAL_CALL_OFFSETS
        ]
        ret_row = rows_by_offset.get(GETTICKCOUNT_CANDIDATE_DIRECT_RET_OFFSET)
        invocation_indices = _candidate_static_invocation_indices(
            candidate,
            caller_start=GETTICKCOUNT_CALLER_START,
            caller_end_exclusive=GETTICKCOUNT_CALLER_END_EXCLUSIVE,
        )
        invocation_offsets = tuple(offsets[index] for index in invocation_indices)
        if (
            len(definition.data)
            != GETTICKCOUNT_CANDIDATE_DIRECT_SECTION_LENGTH
            or len(definition.relocation_mask) != len(definition.data)
            or invocation_offsets
            != GETTICKCOUNT_CANDIDATE_DIRECT_INVOCATION_OFFSETS
            or any(row is None for row in direct_rows)
            or any(row is None for row in virtual_rows)
            or ret_row is None
            or _instruction_mnemonic(ret_row[1]) not in {"ret", "retn"}
            or tuple(value.lower() for value in ret_row[1].bytes) != ("c3",)
            or definition.data[GETTICKCOUNT_CANDIDATE_DIRECT_RET_OFFSET]
            != 0xC3
            or any(
                _instruction_mnemonic(row[1]) != "call"
                or _instruction_operand(row[1]).strip()
                != GETTICKCOUNT_CANDIDATE_CALLABLE
                or tuple(value.lower() for value in row[1].bytes)
                != ("e8", "00", "00", "00", "00")
                for row in direct_rows
                if row is not None
            )
            or tuple(offset for offset, _instruction in direct_like_calls)
            != GETTICKCOUNT_CANDIDATE_DIRECT_CALL_OFFSETS
            or any(
                _instruction_mnemonic(row[1]) != "call"
                or not row[1].bytes
                or row[1].bytes[0].lower() != "ff"
                for row in virtual_rows
                if row is not None
            )
            or tuple(
                _memory_slot(_instruction_operand(row[1]))[1]
                for row in virtual_rows
                if row is not None
            )
            != (8, 4, 4, 12)
        ):
            raise ValueError(
                "GetTickCount direct candidate bridge requires the exact "
                "three direct calls, four reviewed virtual calls, RET, and "
                "0xb0 section shape"
            )

        references = tuple(
            sorted(
                (
                    relocation
                    for relocation in definition.relocations
                    if relocation.symbol_name.casefold()
                    == GETTICKCOUNT_CANDIDATE_CALLABLE.casefold()
                ),
                key=lambda relocation: relocation.offset,
            )
        )
        expected_relocation_offsets = tuple(
            offset + 1
            for offset in GETTICKCOUNT_CANDIDATE_DIRECT_CALL_OFFSETS
        )
        undefined_case_collisions = tuple(
            name
            for name in definition.undefined_external_functions
            if name.casefold() == GETTICKCOUNT_CANDIDATE_CALLABLE.casefold()
        )
        if (
            definition.undefined_external_functions.count(
                GETTICKCOUNT_CANDIDATE_CALLABLE
            )
            != 1
            or undefined_case_collisions
            != (GETTICKCOUNT_CANDIDATE_CALLABLE,)
            or GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL
            in definition.undefined_external_functions
            or tuple(reference.offset for reference in references)
            != expected_relocation_offsets
            or len(references) != 3
            or any(
                reference.type != IMAGE_REL_I386_REL32
                or reference.symbol_name != GETTICKCOUNT_CANDIDATE_CALLABLE
                or reference.offset < 1
                or reference.offset + 4 > len(definition.data)
                or definition.data[reference.offset - 1] != 0xE8
                or struct.unpack_from("<I", definition.data, reference.offset)[0]
                != 0
                or not all(
                    definition.relocation_mask[index]
                    for index in range(reference.offset, reference.offset + 4)
                )
                for reference in references
            )
            or any(
                relocation.symbol_name.casefold()
                == GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL.casefold()
                for relocation in definition.relocations
            )
            or any(
                GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL.casefold()
                in _instruction_operand(instruction).casefold()
                for instruction in candidate.instructions
            )
        ):
            raise ValueError(
                "GetTickCount direct candidate bridge requires exactly three "
                "case-exact zero-addend fully masked E8 REL32 relocations and "
                "rejects mixed direct/IAT packages"
            )
        return {
            GETTICKCOUNT_CANDIDATE_CALLABLE: thunk.provider_identity
        }, {}

    load_row = rows_by_offset.get(GETTICKCOUNT_CANDIDATE_LOAD_OFFSET)
    call_rows = [
        (offset, row)
        for offset, row in sorted(rows_by_offset.items())
        if _instruction_mnemonic(row[1]) == "call"
        and _instruction_operand(row[1]).lower() == "edi"
    ]
    body_ff_d7_offsets = tuple(
        offset
        for offset in range(max(0, len(definition.data) - 1))
        if definition.data[offset : offset + 2] == b"\xff\xd7"
    )
    if (
        load_row is None
        or _instruction_mnemonic(load_row[1]) != "mov"
        or _instruction_operand(load_row[1]).lower()
        != f"edi, dword {GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL.lower()}"
        or tuple(value.lower() for value in load_row[1].bytes)
        != ("8b", "3d", "00", "00", "00", "00")
        or not call_rows
        or tuple(offset for offset, _row in call_rows)
        != body_ff_d7_offsets
        or any(
            offset <= GETTICKCOUNT_CANDIDATE_LOAD_OFFSET
            or tuple(value.lower() for value in row[1].bytes) != ("ff", "d7")
            or offset + 2 > len(definition.data)
            or definition.data[offset : offset + 2] != b"\xff\xd7"
            or any(definition.relocation_mask[offset : offset + 2])
            for offset, row in call_rows
        )
    ):
        raise ValueError(
            "GetTickCount candidate bridge requires the exact EDI IAT load and "
            "the immutable-retail-derived population of ordered FF D7 callsites"
        )
    last_call_index = call_rows[-1][1][0]
    reviewed_call_indices = {
        row[0] for _offset, row in call_rows
    }
    if any(
        _instruction_may_clobber_register(instruction, "edi")
        for index, instruction in enumerate(candidate.instructions)
        if load_row[0] < index < last_call_index
        and index not in reviewed_call_indices
    ):
        raise ValueError(
            "GetTickCount candidate bridge rejects EDI provenance clobbering"
        )

    references = tuple(
        relocation
        for relocation in definition.relocations
        if relocation.symbol_name == GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL
    )
    case_collisions = [
        name
        for name in definition.undefined_external_functions
        if name.casefold()
        == GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL.casefold()
    ]
    if (
        definition.undefined_external_functions.count(
            GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL
        )
        != 1
        or case_collisions != [GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL]
        or GETTICKCOUNT_CANDIDATE_CALLABLE
        in definition.undefined_external_functions
        or len(references) != 1
        or references[0].type != IMAGE_REL_I386_DIR32
        or references[0].offset != GETTICKCOUNT_CANDIDATE_RELOCATION_OFFSET
        or references[0].offset + 4 > len(definition.data)
        or references[0].offset + 4 > len(definition.relocation_mask)
        or definition.data[
            GETTICKCOUNT_CANDIDATE_LOAD_OFFSET:
            GETTICKCOUNT_CANDIDATE_RELOCATION_OFFSET
        ]
        != b"\x8b\x3d"
        or struct.unpack_from(
            "<I", definition.data, GETTICKCOUNT_CANDIDATE_RELOCATION_OFFSET
        )[0]
        != 0
        or not all(
            definition.relocation_mask[index]
            for index in range(
                GETTICKCOUNT_CANDIDATE_RELOCATION_OFFSET,
                GETTICKCOUNT_CANDIDATE_RELOCATION_OFFSET + 4,
            )
        )
    ):
        raise ValueError(
            "GetTickCount candidate bridge requires one exact undefined IAT "
            "symbol and zero-addend fully masked MOV DIR32 relocation"
        )
    return {}, {
        GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL: GETTICKCOUNT_IAT_IDENTITY
    }


def _time_reset_gettickcount_candidate_direct_bridge(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    thunk: ProviderNamedImportThunk | None,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
) -> dict[str, str]:
    """Bind only Time::Reset's natural direct GetTickCount callable."""

    if (
        caller_identity != TIME_RESET_GETTICKCOUNT_CALLER_IDENTITY
        or normalize_address(caller_start)
        != TIME_RESET_GETTICKCOUNT_CALLER_START
        or normalize_address(caller_end_exclusive)
        != TIME_RESET_GETTICKCOUNT_CALLER_END_EXCLUSIVE
    ):
        return {}

    definition = candidate.caller_definition
    folded_callable = GETTICKCOUNT_CANDIDATE_CALLABLE.casefold()
    folded_iat = GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL.casefold()
    callable_mentions = [
        instruction
        for instruction in candidate.instructions
        if folded_callable in _instruction_operand(instruction).casefold()
    ]
    callable_rows = (
        tuple(
            row
            for row in definition.relocations
            if row.symbol_name.casefold() == folded_callable
        )
        if definition is not None
        else ()
    )
    if not callable_mentions and not callable_rows:
        return {}

    exact_thunk = ProviderNamedImportThunk(
        provider_identity=GETTICKCOUNT_PROVIDER_IDENTITY,
        thunk_address=GETTICKCOUNT_PROVIDER_ADDRESS,
        retail_name=GETTICKCOUNT_RETAIL_THUNK_NAME,
        callable_symbol=GETTICKCOUNT_CANDIDATE_CALLABLE,
        iat_object_symbol=GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL,
        iat_identity=GETTICKCOUNT_IAT_IDENTITY,
        iat_address=GETTICKCOUNT_IAT_ADDRESS,
        import_dll=GETTICKCOUNT_IMPORT_DLL,
        import_name=GETTICKCOUNT_IMPORT_NAME,
    )
    if (
        thunk != exact_thunk
        or indexes.by_address.get(GETTICKCOUNT_PROVIDER_ADDRESS)
        != GETTICKCOUNT_PROVIDER_IDENTITY
        or GETTICKCOUNT_PROVIDER_IDENTITY not in indexes.provider_ids
    ):
        raise ValueError(
            "Time::Reset GetTickCount bridge requires the exact registered "
            "KERNEL32 provider thunk"
        )

    expected_row = {
        "ordinal": 0,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "iat",
        "target_identity": GETTICKCOUNT_IAT_IDENTITY,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": 8,
    }
    if [dict(row) for row in expected] != [expected_row]:
        raise ValueError(
            "Time::Reset GetTickCount bridge requires exact retail "
            "ordinal-zero direct named-import truth"
        )

    caller = document.collection("symbols").get(
        WOL_TIME_RESET_TARGET_SYMBOL_ID
    )
    block = document.collection("physical_blocks").get(
        WOL_TIME_RESET_TARGET_BLOCK_ID
    )
    owner = document.collection("owners").get(
        WOL_TIME_RESET_TARGET_OWNER_ID
    )
    trace = (
        caller.get("source_traceability")
        if isinstance(caller, Mapping)
        else None
    )
    primary_rows = [
        relationship
        for relationship in (
            owner.get("relationships", ())
            if isinstance(owner, Mapping)
            else ()
        )
        if isinstance(relationship, Mapping)
        and relationship.get("kind") == "primary-function"
        and relationship.get("symbol_id") == WOL_TIME_RESET_TARGET_SYMBOL_ID
    ]
    if (
        not isinstance(caller, Mapping)
        or caller.get("binary") != "recoil"
        or caller.get("kind") != "function"
        or caller.get("pipeline_class") != "authored"
        or caller.get("address") != TIME_RESET_GETTICKCOUNT_CALLER_START
        or caller.get("end_exclusive")
        != TIME_RESET_GETTICKCOUNT_CALLER_END_EXCLUSIVE
        or caller.get("extent_state") != "known"
        or caller.get("size") != TIME_RESET_GETTICKCOUNT_SECTION_LENGTH
        or caller.get("navigation_name") != "Time::Reset"
        or caller.get("ownership_state") != "primary-owned"
        or caller.get("physical_block_id")
        != WOL_TIME_RESET_TARGET_BLOCK_ID
        or indexes.by_address.get(TIME_RESET_GETTICKCOUNT_CALLER_START)
        != TIME_RESET_GETTICKCOUNT_CALLER_IDENTITY
        or TIME_RESET_GETTICKCOUNT_CALLER_IDENTITY in indexes.provider_ids
        or not isinstance(trace, Mapping)
        or trace.get("state") != "resolved"
        or trace.get("reason_code") is not None
        or trace.get("source_edges")
        != [
            {
                "anchor_id": (
                    "recoil:anchor:gamezrecoil-time-time-time-reset"
                ),
                "emission_context": {
                    "translation_unit": "src/GameZRecoil/Time/Time.cpp"
                },
                "evidence_ids": [],
                "relation": "defines",
            }
        ]
        or not isinstance(block, Mapping)
        or block.get("binary") != "recoil"
        or block.get("row_kind") != "physical-source-block"
        or block.get("start") != TIME_RESET_GETTICKCOUNT_CALLER_START
        or block.get("end_exclusive") != "0x4a5780"
        or block.get("contribution_kind") != "authored"
        or block.get("agent_source_path")
        != "src/GameZRecoil/Time/Time.cpp"
        or block.get("source_path") != "src/GameZRecoil/Time/Time.cpp"
        or block.get("contribution_ids", []).count(
            WOL_TIME_RESET_TARGET_SYMBOL_ID
        )
        != 1
        or not isinstance(owner, Mapping)
        or owner.get("binary") != "recoil"
        or owner.get("kind") != "source-file"
        or owner.get("provider_state") == "accepted"
        or owner.get("source_paths")
        != [
            "src/GameZRecoil/Time/Time.cpp",
            "src/GameZRecoil/Time/Time.h",
        ]
        or len(primary_rows) != 1
        or primary_rows[0].get("address")
        != TIME_RESET_GETTICKCOUNT_CALLER_START
    ):
        raise ValueError(
            "Time::Reset GetTickCount bridge requires the exact authored "
            "caller, block, owner, and resolved source trace"
        )

    folded_collisions = [
        (label, name, identity)
        for label, rows in (
            ("candidate identity", indexes.by_candidate_name),
            ("candidate storage", indexes.storage_by_name),
        )
        for name, identity in rows.items()
        if str(name).casefold() in {folded_callable, folded_iat}
        and identity
        not in {GETTICKCOUNT_PROVIDER_IDENTITY, GETTICKCOUNT_IAT_IDENTITY}
    ]
    bn_collisions = [
        (name, row)
        for name, rows in bridge_names.items()
        if str(name).casefold() in {folded_callable, folded_iat}
        for row in (
            rows
            if isinstance(rows, Sequence)
            and not isinstance(rows, (str, bytes))
            else (rows,)
        )
    ]
    if folded_collisions or bn_collisions:
        raise ValueError(
            "Time::Reset GetTickCount bridge rejects callable/provider/IAT "
            "collision drift"
        )

    if definition is None or definition.symbol != TIME_RESET_GETTICKCOUNT_CALLER_SYMBOL:
        raise ValueError(
            "Time::Reset GetTickCount bridge requires the exact caller COFF "
            "definition"
        )
    iat_mentions = [
        instruction
        for instruction in candidate.instructions
        if folded_iat in _instruction_operand(instruction).casefold()
    ]
    iat_rows = [
        row
        for row in definition.relocations
        if row.symbol_name.casefold() == folded_iat
    ]
    iat_external_rows = [
        name
        for population in (
            definition.undefined_external_functions,
            definition.defined_external_functions,
            definition.undefined_external_data,
            definition.defined_external_data,
        )
        for name in population
        if name.casefold() == folded_iat
    ]
    if iat_mentions or iat_rows or iat_external_rows:
        raise ValueError(
            "Time::Reset GetTickCount bridge rejects IAT-form substitution "
            "or mixed direct/IAT packages"
        )

    call_offset, relocation = (
        _require_unique_exact_candidate_direct_external_call_row(
            candidate,
            candidate_symbol=GETTICKCOUNT_CANDIDATE_CALLABLE,
        )
    )
    if (
        len(definition.data) != TIME_RESET_GETTICKCOUNT_SECTION_LENGTH
        or len(definition.relocation_mask) != len(definition.data)
        or definition.section_start != 0
        or definition.section_end
        not in {0, TIME_RESET_GETTICKCOUNT_SECTION_LENGTH}
        or call_offset != TIME_RESET_GETTICKCOUNT_CALL_OFFSET
        or relocation.offset != TIME_RESET_GETTICKCOUNT_RELOCATION_OFFSET
    ):
        raise ValueError(
            "Time::Reset GetTickCount bridge requires the exact 0x60-byte "
            "caller section and offset-0x35 CALL/REL32 row"
        )
    return {
        GETTICKCOUNT_CANDIDATE_CALLABLE: GETTICKCOUNT_PROVIDER_IDENTITY
    }


def _time_tick_gettickcount_candidate_direct_bridge(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    thunk: ProviderNamedImportThunk | None,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
) -> dict[str, str]:
    """Bind only Time::Tick's natural direct GetTickCount callable."""

    if (
        caller_identity != TIME_TICK_GETTICKCOUNT_CALLER_IDENTITY
        or normalize_address(caller_start)
        != TIME_TICK_GETTICKCOUNT_CALLER_START
        or normalize_address(caller_end_exclusive)
        != TIME_TICK_GETTICKCOUNT_CALLER_END_EXCLUSIVE
    ):
        return {}

    definition = candidate.caller_definition
    folded_callable = GETTICKCOUNT_CANDIDATE_CALLABLE.casefold()
    folded_iat = GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL.casefold()
    callable_mentions = [
        instruction
        for instruction in candidate.instructions
        if folded_callable in _instruction_operand(instruction).casefold()
    ]
    callable_rows = (
        tuple(
            row
            for row in definition.relocations
            if row.symbol_name.casefold() == folded_callable
        )
        if definition is not None
        else ()
    )
    if not callable_mentions and not callable_rows:
        return {}

    exact_thunk = ProviderNamedImportThunk(
        provider_identity=GETTICKCOUNT_PROVIDER_IDENTITY,
        thunk_address=GETTICKCOUNT_PROVIDER_ADDRESS,
        retail_name=GETTICKCOUNT_RETAIL_THUNK_NAME,
        callable_symbol=GETTICKCOUNT_CANDIDATE_CALLABLE,
        iat_object_symbol=GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL,
        iat_identity=GETTICKCOUNT_IAT_IDENTITY,
        iat_address=GETTICKCOUNT_IAT_ADDRESS,
        import_dll=GETTICKCOUNT_IMPORT_DLL,
        import_name=GETTICKCOUNT_IMPORT_NAME,
    )
    if (
        thunk != exact_thunk
        or indexes.by_address.get(GETTICKCOUNT_PROVIDER_ADDRESS)
        != GETTICKCOUNT_PROVIDER_IDENTITY
        or GETTICKCOUNT_PROVIDER_IDENTITY not in indexes.provider_ids
    ):
        raise ValueError(
            "Time::Tick GetTickCount bridge requires the exact registered "
            "KERNEL32 provider thunk"
        )

    expected_row = {
        "ordinal": 0,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "iat",
        "target_identity": GETTICKCOUNT_IAT_IDENTITY,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    if [dict(row) for row in expected] != [expected_row]:
        raise ValueError(
            "Time::Tick GetTickCount bridge requires exact retail "
            "ordinal-zero direct named-import truth; observed "
            f"{[dict(row) for row in expected]!r}"
        )

    caller_symbol_id = TIME_TICK_GETTICKCOUNT_CALLER_IDENTITY.removeprefix(
        "symbol:"
    )
    caller = document.collection("symbols").get(caller_symbol_id)
    block = document.collection("physical_blocks").get(
        WOL_TIME_RESET_TARGET_BLOCK_ID
    )
    owner = document.collection("owners").get(
        WOL_TIME_RESET_TARGET_OWNER_ID
    )
    trace = (
        caller.get("source_traceability")
        if isinstance(caller, Mapping)
        else None
    )
    primary_rows = [
        relationship
        for relationship in (
            owner.get("relationships", ())
            if isinstance(owner, Mapping)
            else ()
        )
        if isinstance(relationship, Mapping)
        and relationship.get("kind") == "primary-function"
        and relationship.get("symbol_id") == caller_symbol_id
    ]
    if (
        not isinstance(caller, Mapping)
        or caller.get("binary") != "recoil"
        or caller.get("kind") != "function"
        or caller.get("pipeline_class") != "authored"
        or caller.get("address") != TIME_TICK_GETTICKCOUNT_CALLER_START
        or caller.get("end_exclusive")
        != TIME_TICK_GETTICKCOUNT_CALLER_END_EXCLUSIVE
        or caller.get("extent_state") != "known"
        or caller.get("size") != TIME_TICK_GETTICKCOUNT_SECTION_LENGTH
        or caller.get("navigation_name") != "Time::Tick"
        or caller.get("ownership_state") != "primary-owned"
        or caller.get("physical_block_id")
        != WOL_TIME_RESET_TARGET_BLOCK_ID
        or indexes.by_address.get(TIME_TICK_GETTICKCOUNT_CALLER_START)
        != TIME_TICK_GETTICKCOUNT_CALLER_IDENTITY
        or TIME_TICK_GETTICKCOUNT_CALLER_IDENTITY in indexes.provider_ids
        or not isinstance(trace, Mapping)
        or trace.get("state") != "resolved"
        or trace.get("reason_code") is not None
        or trace.get("source_edges")
        != [
            {
                "anchor_id": (
                    "recoil:anchor:gamezrecoil-time-time-time-tick-time-cpp"
                ),
                "emission_context": {
                    "translation_unit": "src/GameZRecoil/Time/Time.cpp"
                },
                "evidence_ids": [],
                "relation": "defines",
            }
        ]
        or not isinstance(block, Mapping)
        or block.get("binary") != "recoil"
        or block.get("row_kind") != "physical-source-block"
        or block.get("start") != WOL_TIME_RESET_TARGET_ADDRESS
        or block.get("end_exclusive")
        != TIME_TICK_GETTICKCOUNT_CALLER_END_EXCLUSIVE
        or block.get("contribution_kind") != "authored"
        or block.get("agent_source_path")
        != "src/GameZRecoil/Time/Time.cpp"
        or block.get("source_path") != "src/GameZRecoil/Time/Time.cpp"
        or block.get("contribution_ids", []).count(caller_symbol_id) != 1
        or not isinstance(owner, Mapping)
        or owner.get("binary") != "recoil"
        or owner.get("kind") != "source-file"
        or owner.get("provider_state") == "accepted"
        or owner.get("source_paths")
        != [
            "src/GameZRecoil/Time/Time.cpp",
            "src/GameZRecoil/Time/Time.h",
        ]
        or len(primary_rows) != 1
        or primary_rows[0].get("address")
        != TIME_TICK_GETTICKCOUNT_CALLER_START
    ):
        raise ValueError(
            "Time::Tick GetTickCount bridge requires the exact authored "
            "caller, block, owner, and resolved source trace"
        )

    folded_collisions = [
        (label, name, identity)
        for label, rows in (
            ("candidate identity", indexes.by_candidate_name),
            ("candidate storage", indexes.storage_by_name),
        )
        for name, identity in rows.items()
        if str(name).casefold() in {folded_callable, folded_iat}
        and identity
        not in {GETTICKCOUNT_PROVIDER_IDENTITY, GETTICKCOUNT_IAT_IDENTITY}
    ]
    bn_collisions = [
        (name, row)
        for name, rows in bridge_names.items()
        if str(name).casefold() in {folded_callable, folded_iat}
        for row in (
            rows
            if isinstance(rows, Sequence)
            and not isinstance(rows, (str, bytes))
            else (rows,)
        )
    ]
    if folded_collisions or bn_collisions:
        raise ValueError(
            "Time::Tick GetTickCount bridge rejects callable/provider/IAT "
            "collision drift"
        )

    if (
        definition is None
        or definition.symbol != TIME_TICK_GETTICKCOUNT_CALLER_SYMBOL
    ):
        raise ValueError(
            "Time::Tick GetTickCount bridge requires the exact caller COFF "
            "definition"
        )
    iat_mentions = [
        instruction
        for instruction in candidate.instructions
        if folded_iat in _instruction_operand(instruction).casefold()
    ]
    iat_rows = [
        row
        for row in definition.relocations
        if row.symbol_name.casefold() == folded_iat
    ]
    iat_external_rows = [
        name
        for population in (
            definition.undefined_external_functions,
            definition.defined_external_functions,
            definition.undefined_external_data,
            definition.defined_external_data,
        )
        for name in population
        if name.casefold() == folded_iat
    ]
    if iat_mentions or iat_rows or iat_external_rows:
        raise ValueError(
            "Time::Tick GetTickCount bridge rejects IAT-form substitution "
            "or mixed direct/IAT packages"
        )

    call_offset, relocation = (
        _require_unique_exact_candidate_direct_external_call_row(
            candidate,
            candidate_symbol=GETTICKCOUNT_CANDIDATE_CALLABLE,
        )
    )
    if (
        len(definition.data) != TIME_TICK_GETTICKCOUNT_SECTION_LENGTH
        or len(definition.relocation_mask) != len(definition.data)
        or definition.section_start != 0
        or definition.section_end
        not in {0, TIME_TICK_GETTICKCOUNT_SECTION_LENGTH}
        or call_offset != TIME_TICK_GETTICKCOUNT_CALL_OFFSET
        or relocation.offset != TIME_TICK_GETTICKCOUNT_RELOCATION_OFFSET
    ):
        raise ValueError(
            "Time::Tick GetTickCount bridge requires the exact 0xb0-byte "
            "caller section and offset-0x03 CALL/REL32 row"
        )
    return {
        GETTICKCOUNT_CANDIDATE_CALLABLE: GETTICKCOUNT_PROVIDER_IDENTITY
    }


def _gettickcount_candidate_bridges_for_caller(
    retail_e8_call_population: Sequence[int],
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    thunk: ProviderNamedImportThunk | None,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
) -> tuple[dict[str, str], dict[str, str], dict[str, str]]:
    """Compose the finite exact caller-scoped GetTickCount candidate forms."""

    direct_bridges, register_storage_bridges = (
        _gettickcount_named_import_thunk_candidate_bridges(
            retail_e8_call_population,
            candidate,
            thunk=thunk,
            document=document,
            caller_identity=caller_identity,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
            indexes=indexes,
            bridge_names=bridge_names,
        )
    )
    time_reset_direct_bridges = (
        _time_reset_gettickcount_candidate_direct_bridge(
            expected,
            candidate,
            thunk=thunk,
            document=document,
            caller_identity=caller_identity,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
            indexes=indexes,
            bridge_names=bridge_names,
        )
    )
    time_tick_direct_bridges = (
        _time_tick_gettickcount_candidate_direct_bridge(
            expected,
            candidate,
            thunk=thunk,
            document=document,
            caller_identity=caller_identity,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
            indexes=indexes,
            bridge_names=bridge_names,
        )
    )
    conflicts = direct_bridges.keys() & time_reset_direct_bridges.keys()
    if any(
        direct_bridges[name] != time_reset_direct_bridges[name]
        for name in conflicts
    ):
        raise ValueError(
            "Time::Reset GetTickCount bridge conflicts with another exact "
            "GetTickCount caller bridge"
        )
    direct_bridges.update(time_reset_direct_bridges)
    conflicts = direct_bridges.keys() & time_tick_direct_bridges.keys()
    if any(
        direct_bridges[name] != time_tick_direct_bridges[name]
        for name in conflicts
    ):
        raise ValueError(
            "Time::Tick GetTickCount bridge conflicts with another exact "
            "GetTickCount caller bridge"
        )
    direct_bridges.update(time_tick_direct_bridges)
    equivalences = _gettickcount_candidate_retail_iat_equivalences(
        thunk,
        direct_bridges,
        register_storage_bridges,
    )
    return direct_bridges, register_storage_bridges, equivalences


def _gettickcount_candidate_retail_iat_equivalences(
    thunk: ProviderNamedImportThunk | None,
    direct_bridges: Mapping[str, str],
    register_storage_bridges: Mapping[str, str],
) -> dict[str, str]:
    """Expose exact candidate-to-retail identity after dedicated proof.

    The dedicated bridge above owns caller scope, bytes, call population,
    package, provenance, and collision checks.  This helper returns only the
    final comparison identity for one reviewed candidate form and rejects an
    incomplete or mixed package.
    """

    if not direct_bridges and not register_storage_bridges:
        return {}
    if thunk is None:
        raise ValueError(
            "GetTickCount comparison equivalence has no immutable retail thunk"
        )
    exact_direct = {
        GETTICKCOUNT_CANDIDATE_CALLABLE: thunk.provider_identity
    }
    exact_register = {
        GETTICKCOUNT_CANDIDATE_IMPORT_SYMBOL: thunk.iat_identity
    }
    if direct_bridges == exact_direct and not register_storage_bridges:
        return {thunk.provider_identity: thunk.iat_identity}
    if register_storage_bridges == exact_register and not direct_bridges:
        return {thunk.iat_identity: thunk.iat_identity}
    raise ValueError(
        "GetTickCount comparison equivalence requires one exact unmixed "
        "direct-provider or register-IAT candidate package"
    )


def _integrate_preproven_named_import_thunk_packages(
    indexes: IdentityIndexes,
    thunks: Sequence[ProviderNamedImportThunk],
) -> tuple[IdentityIndexes, tuple[CurrentIatStoragePackage, ...]]:
    """Publish complete candidate-independent named packages already proven.

    Some legacy provider boundaries predate the tracker provider-data package
    schema, while their dedicated retail bridge proves the same immutable
    named-import tuple and exact IAT operand.  Join that proof into the generic
    package/index path without weakening ambiguity checks or consulting the
    candidate.
    """

    packages: set[CurrentIatStoragePackage] = set()
    storage_by_address = dict(indexes.storage_by_address)
    storage_by_name = dict(indexes.storage_by_name)
    for thunk in thunks:
        if (
            not isinstance(thunk, ProviderNamedImportThunk)
            or not thunk.provider_identity.startswith("provider:")
            or not thunk.retail_name
            or not thunk.callable_symbol
            or not _decorated_coff_name(thunk.callable_symbol)
            or not thunk.iat_object_symbol.startswith("__imp_")
            or not _decorated_coff_name(thunk.iat_object_symbol)
            or not thunk.import_dll
            or not thunk.import_name
            or thunk.import_name.startswith("#")
            or thunk.iat_identity != f"iat:{thunk.import_name}"
        ):
            raise ValueError(
                "preproven named import thunk lacks one complete immutable "
                "named package"
            )
        address = normalize_address(thunk.iat_address)
        package = CurrentIatStoragePackage(
            address=address,
            import_dll=thunk.import_dll,
            import_name=thunk.import_name,
            import_ordinal=None,
            object_symbol=thunk.iat_object_symbol,
            identity=thunk.iat_identity,
        )
        packages.add(package)
        for mapping, key in (
            (storage_by_address, address),
            (storage_by_name, thunk.iat_object_symbol),
        ):
            prior = mapping.get(key)
            if prior not in {None, package.identity}:
                raise ValueError(
                    "preproven named import package conflicts with current "
                    f"identity for {key!r}"
                )
            mapping[key] = package.identity
    packages_by_address: dict[str, set[CurrentIatStoragePackage]] = {}
    for package in packages:
        packages_by_address.setdefault(package.address, set()).add(package)
    ambiguous = sorted(
        address
        for address, rows in packages_by_address.items()
        if len(rows) != 1
    )
    if ambiguous:
        raise ValueError(
            "preproven named import packages have ambiguous IAT addresses: "
            + ", ".join(ambiguous)
        )
    return (
        replace(
            indexes,
            storage_by_address=storage_by_address,
            storage_by_name=storage_by_name,
        ),
        tuple(sorted(packages, key=lambda row: address_value(row.address))),
    )


def _provider_named_import_thunk_retail_bridges(
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge_by_address: Mapping[str, Any],
    bridge_by_name: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    additional_named_packages: Sequence[CurrentIatStoragePackage] = (),
    preproven_named_thunks: Sequence[ProviderNamedImportThunk] = (),
    retail_import_targets: Sequence[Any] | None = None,
) -> tuple[
    tuple[ProviderNamedImportThunk | ProviderPeNamedImportThunk, ...],
    dict[str, list[Any]],
]:
    """Prove unique named-import FF25 thunks from governed live facts.

    The provider function/owner/block and current IAT package are tracker
    authority.  The first six immutable retail bytes prove the thunk and its
    exact IAT operand; any remaining registered function bytes must be only
    linker/compiler padding.  No name, address, DLL, or import allowlist is
    involved.
    """

    owners = document.collection("owners")
    symbols = document.collection("symbols")
    physical_blocks = document.collection("physical_blocks")
    supplied_packages: list[CurrentIatStoragePackage] = []
    for package in additional_named_packages:
        if (
            not isinstance(package, CurrentIatStoragePackage)
            or package.import_ordinal is not None
            or not package.import_name
            or package.import_name.startswith("#")
            or not package.import_dll
            or not package.object_symbol.startswith("__imp_")
            or not _decorated_coff_name(package.object_symbol)
            or package.identity != f"iat:{package.import_name}"
        ):
            raise ValueError(
                "named import thunk discovery received an incomplete "
                "additional named package"
            )
        supplied_packages.append(
            replace(package, address=normalize_address(package.address))
        )
    import_packages = tuple(
        sorted(
            {
                package
                for package in (
                    *_current_tracker_iat_storage_packages(document),
                    *supplied_packages,
                )
            },
            key=lambda package: (
                address_value(package.address),
                package.import_dll,
                package.import_name,
                package.object_symbol,
            ),
        )
    )
    packages_by_address: dict[str, list[CurrentIatStoragePackage]] = {}
    for package in import_packages:
        packages_by_address.setdefault(package.address, []).append(package)
    preproven_by_address: dict[str, ProviderNamedImportThunk] = {}
    for thunk in preproven_named_thunks:
        if not isinstance(thunk, ProviderNamedImportThunk):
            raise ValueError(
                "named import thunk discovery received malformed preproven thunk"
            )
        address = normalize_address(thunk.thunk_address)
        prior = preproven_by_address.get(address)
        if prior is not None and prior != thunk:
            raise ValueError(
                "named import thunk discovery has competing preproven thunks at "
                f"{address}"
            )
        preproven_by_address[address] = thunk

    primary_owners_by_symbol: dict[
        str, list[tuple[str, Mapping[str, Any]]]
    ] = {}
    for owner_id, owner in owners.items():
        if not isinstance(owner, Mapping):
            continue
        relationships = owner.get("relationships")
        if not isinstance(relationships, list):
            continue
        for relationship in relationships:
            if (
                isinstance(relationship, Mapping)
                and relationship.get("kind") == "primary-function"
                and isinstance(relationship.get("symbol_id"), str)
            ):
                primary_owners_by_symbol.setdefault(
                    str(relationship["symbol_id"]), []
                ).append((str(owner_id), owner))

    proven: list[ProviderNamedImportThunk | ProviderPeNamedImportThunk] = []
    retail_names: dict[str, list[Any]] = {}
    for symbol_id, owner_rows in primary_owners_by_symbol.items():
        symbol = symbols.get(symbol_id)
        if not isinstance(symbol, Mapping):
            continue
        retail_name = symbol.get("navigation_name")
        if not isinstance(retail_name, str) or not retail_name:
            continue
        raw_address = symbol.get("address")
        if not isinstance(raw_address, str):
            continue
        try:
            address = normalize_address(raw_address)
            end_exclusive = normalize_address(
                str(symbol.get("end_exclusive", ""))
            )
        except ProgressError:
            continue
        size = address_value(end_exclusive) - address_value(address)
        if (
            symbol.get("binary") != "recoil"
            or symbol.get("kind") != "function"
            or symbol.get("pipeline_class") != "non-authored"
            or symbol.get("authored_order_role") != "non-authored"
            or symbol.get("extent_state") != "known"
            or symbol.get("address") != address
            or size < 6
            or symbol.get("size") != size
            or symbol.get("output_section_id") != "recoil:section:.text"
            or symbol.get("ownership_state") != "primary-owned"
            or not isinstance(symbol.get("physical_block_id"), str)
        ):
            continue

        # Provider owners may legitimately group several ordinary MFC/CRT
        # bodies.  Classify the immutable instruction shape before applying
        # invariants that belong only to a named import thunk; otherwise an
        # unrelated grouped destructor can fail the whole live producer.
        thunk_prefix = _hexdump_bytes(bridge.hexdump(address, 6))
        if len(thunk_prefix) != 6:
            raise ValueError(
                f"named import thunk prefilter at {symbol_id} has truncated "
                "immutable bytes"
            )
        if thunk_prefix[:2] != b"\xff\x25":
            continue
        accepted_owner_rows = [
            (owner_id, owner)
            for owner_id, owner in owner_rows
            if owner.get("binary") == "recoil"
            and owner.get("kind") == "provider-boundary"
            and owner.get("blocker") == "none"
            and owner.get("lifecycle_state") == "accepted"
            and owner.get("provider_state") == "accepted"
            and owner.get("source_paths") == []
        ]
        if not accepted_owner_rows:
            # A true immutable thunk under a pending/rejected provider owner
            # is unresolved provider debt.  It is not eligible for accepted
            # thunk discovery and remains available to the separate
            # convergence retail-blocker route.
            continue
        iat_address = normalize_address(
            struct.unpack_from("<I", thunk_prefix, 2)[0]
        )
        packages = packages_by_address.get(iat_address, [])
        if len(packages) != 1:
            raise ValueError(
                f"import thunk {symbol_id} IAT operand does not join one "
                "unique complete current named or ordinal package"
            )
        package = packages[0]
        if package.import_ordinal is not None:
            # This exact true thunk belongs to the sibling ordinal producer,
            # which independently proves its owner, block, six-byte extent,
            # package identities, and BN target.  Named discovery must route
            # it onward rather than misreport a missing named package.
            continue
        preproven = preproven_by_address.get(address)
        if preproven is not None:
            if (
                preproven.provider_identity != f"provider:{symbol_id}"
                or normalize_address(preproven.iat_address) != package.address
                or preproven.iat_identity != package.identity
                or preproven.iat_object_symbol != package.object_symbol
                or preproven.import_dll != package.import_dll
                or preproven.import_name != package.import_name
                or preproven.retail_name != retail_name
            ):
                raise ValueError(
                    f"preproven named import thunk {symbol_id} conflicts with "
                    "the unique current package or provider identity"
                )
            # The earlier dedicated producer has already proved the complete
            # provider/package/body/BN chain.  Do not publish a second generic
            # thunk for the same physical provider, which would make candidate
            # provider and IAT identities compete in downstream extraction.
            continue

        expected_relationships = [
            {"kind": "anchor-address", "address": address},
            {
                "kind": "primary-function",
                "address": address,
                "symbol_id": symbol_id,
            },
        ]
        if (
            len(owner_rows) != 1
            or len(accepted_owner_rows) != 1
            or accepted_owner_rows[0][1].get("relationships")
            != expected_relationships
        ):
            raise ValueError(
                f"named import thunk {symbol_id} lacks exactly one accepted "
                "provider-boundary primary owner"
            )

        block_id = str(symbol["physical_block_id"])
        block = physical_blocks.get(block_id)
        mapping = block.get("mapping") if isinstance(block, Mapping) else None
        contribution_ids = (
            block.get("contribution_ids")
            if isinstance(block, Mapping)
            else None
        )
        try:
            block_start = normalize_address(str(block.get("start", "")))
            block_end = normalize_address(
                str(block.get("end_exclusive", ""))
            )
        except (ProgressError, AttributeError):
            block_start = ""
            block_end = ""
        if (
            not isinstance(block, Mapping)
            or block.get("binary") != "recoil"
            or block.get("row_kind") != "physical-source-block"
            or block.get("contribution_kind") != "provider"
            or not isinstance(mapping, Mapping)
            or mapping.get("status") != "provider-boundary"
            or not isinstance(contribution_ids, list)
            or contribution_ids.count(symbol_id) != 1
            or not block_start
            or not block_end
            or address_value(block_start) > address_value(address)
            or address_value(block_end) < address_value(end_exclusive)
            or not isinstance(block.get("agent_source_path"), str)
            or not str(block["agent_source_path"]).startswith("provider:")
            or block.get("source_path") != block.get("agent_source_path")
        ):
            raise ValueError(
                f"named import thunk {symbol_id} lacks one exact provider block"
            )

        thunk_extent = _hexdump_bytes(bridge.hexdump(address, size))
        if len(thunk_extent) != size:
            raise ValueError(
                f"named import thunk candidate {symbol_id} immutable extent "
                "is truncated"
            )
        if thunk_extent[:6] != thunk_prefix:
            raise ValueError(
                f"named import thunk {symbol_id} immutable prefix changed "
                "between classification and extent proof"
            )
        if any(value not in {0x90, 0xCC} for value in thunk_extent[6:]):
            raise ValueError(
                f"named import thunk {symbol_id} is not one exact immutable "
                "FF25 thunk followed only by registered padding"
            )
        callable_symbol = package.object_symbol.removeprefix("__imp_")
        if (
            callable_symbol == package.object_symbol
            or not callable_symbol
            or not _decorated_coff_name(callable_symbol)
            or indexes.storage_by_address.get(package.address)
            != package.identity
            or indexes.storage_by_name.get(package.object_symbol)
            != package.identity
        ):
            raise ValueError(
                f"named import thunk {symbol_id} package has no exact distinct "
                "callable/IAT COFF identity"
            )

        provider_identity = f"provider:{symbol_id}"
        if (
            indexes.by_address.get(address) != provider_identity
            or provider_identity not in indexes.provider_ids
        ):
            raise ValueError(
                f"named import thunk {symbol_id} lacks one collision-free "
                "governed callable identity"
            )
        friendly_symbol = _exact_bn_pe_import_friendly_symbol(
            bridge_by_address=bridge_by_address,
            bridge_by_name=bridge_by_name,
            address=address,
            retail_name=str(retail_name),
            immutable_import_name=package.import_name,
        )
        if friendly_symbol is None:
            raise ValueError(
                f"named import thunk {symbol_id} lacks one exact BN friendly "
                "target at its governed address"
            )

        thunk = ProviderNamedImportThunk(
            provider_identity=provider_identity,
            thunk_address=address,
            retail_name=str(retail_name),
            callable_symbol=callable_symbol,
            iat_object_symbol=package.object_symbol,
            iat_identity=package.identity,
            iat_address=package.address,
            import_dll=package.import_dll,
            import_name=package.import_name,
        )
        proven.append(thunk)
        retail_names.setdefault(str(retail_name), []).append(friendly_symbol)

    # Some exact retail named-import thunks predate reviewed provider-owner and
    # provider-data package topology.  Expected call identity is nevertheless
    # available without inventing that topology: the registered non-authored
    # symbol/block bounds the thunk bytes and the immutable retail PE import
    # directory owns its named IAT tuple.  This sibling route is expected-side
    # only; ordinal imports and candidate COFF spellings retain their stricter
    # current-package producers above and below.
    supplied_retail_targets = tuple(
        retail_import_targets
        if retail_import_targets is not None
        else _retail_import_targets(DEFAULT_REFERENCE)[0]
    )
    import_targets_by_address: dict[str, list[Any]] = {}
    named_targets_by_address: dict[str, list[Any]] = {}
    named_target_routes: dict[str, set[tuple[str, str, str]]] = {}
    for target in supplied_retail_targets:
        raw_address = getattr(target, "address", "")
        import_name = getattr(target, "import_name", None)
        import_dll = getattr(target, "dll", None)
        import_ordinal = getattr(target, "import_ordinal", None)
        if not raw_address:
            continue
        try:
            target_address = normalize_address(str(raw_address))
        except ProgressError as exc:
            raise ValueError(
                "named import thunk discovery received a malformed immutable "
                "PE import address"
            ) from exc
        if (
            not isinstance(import_name, str)
            or not import_name
            or not isinstance(import_dll, str)
            or not import_dll
            or "/" in import_dll
            or "\\" in import_dll
            or (
                import_ordinal is not None
                and (
                    not isinstance(import_ordinal, int)
                    or isinstance(import_ordinal, bool)
                    or not 0 <= import_ordinal <= 0xFFFF
                    or import_name != f"#{import_ordinal}"
                )
            )
            or (import_ordinal is None and import_name.startswith("#"))
        ):
            raise ValueError(
                "named import thunk discovery received a malformed immutable "
                "PE import tuple"
            )
        import_targets_by_address.setdefault(target_address, []).append(target)
        if import_ordinal is not None:
            continue
        named_targets_by_address.setdefault(target_address, []).append(target)
        named_target_routes.setdefault(import_name, set()).add(
            (target_address, import_dll, import_name)
        )

    already_proven = {
        normalize_address(thunk.thunk_address) for thunk in proven
    } | set(preproven_by_address)
    current_packages = _current_tracker_iat_storage_packages(document)
    for symbol_id, symbol in symbols.items():
        if not isinstance(symbol, Mapping):
            continue
        raw_address = symbol.get("address")
        retail_name = symbol.get("navigation_name")
        if not isinstance(raw_address, str) or not isinstance(retail_name, str):
            continue
        try:
            address = normalize_address(raw_address)
        except ProgressError:
            continue
        if address in already_proven:
            continue
        block_id = symbol.get("physical_block_id")
        block = physical_blocks.get(block_id)
        mapping = block.get("mapping") if isinstance(block, Mapping) else None
        contribution_ids = (
            block.get("contribution_ids")
            if isinstance(block, Mapping)
            else None
        )
        authored_order = (
            block.get("order", {}).get("authored")
            if isinstance(block, Mapping)
            and isinstance(block.get("order"), Mapping)
            else None
        )
        current_not_applicable = (
            isinstance(authored_order, Mapping)
            and all(
                isinstance(authored_order.get(key), Mapping)
                and authored_order[key].get("result") == "not-applicable"
                and authored_order[key].get("disposition") == "accepted"
                and authored_order[key].get("freshness") == "current"
                and authored_order[key].get("gating") is True
                and authored_order[key].get("validation_mode") == "live"
                for key in AUTHORED_ORDER_DIMENSIONS
            )
        )
        try:
            block_start = normalize_address(str(block.get("start", "")))
            block_end = normalize_address(str(block.get("end_exclusive", "")))
            symbol_end = normalize_address(str(symbol.get("end_exclusive", "")))
        except (ProgressError, AttributeError):
            continue
        if (
            symbol.get("binary") != "recoil"
            or symbol.get("kind") != "function"
            or symbol.get("pipeline_class") != "non-authored"
            or symbol.get("authored_order_role") != "non-authored"
            or symbol.get("extent_state") != "known"
            or symbol.get("output_section_id") != "recoil:section:.text"
            or symbol.get("ownership_state") not in {"unresolved", "primary-owned"}
            or not isinstance(block, Mapping)
            or block.get("binary") != "recoil"
            or block.get("row_kind") != "physical-source-block"
            or block.get("contribution_kind") != "provider"
            or not isinstance(mapping, Mapping)
            or mapping.get("status") != "provider-boundary"
            or not current_not_applicable
            or not isinstance(contribution_ids, list)
            or contribution_ids.count(str(symbol_id)) != 1
            or not isinstance(block.get("agent_source_path"), str)
            or not str(block["agent_source_path"]).startswith("provider:")
            or block.get("source_path") != block.get("agent_source_path")
            or not (address_value(block_start) <= address_value(address) < address_value(block_end))
        ):
            continue

        # A sole-contribution provider block is the narrower physical extent
        # when a legacy descriptive function row incorrectly runs into later
        # provider data.  Grouped blocks retain each exact symbol boundary.
        if address_value(symbol_end) <= address_value(block_end):
            proof_end = symbol_end
        elif (
            (contribution_ids == [symbol_id] and block_start == address)
            or contribution_ids[-1:] == [symbol_id]
        ):
            # Legacy descriptive function extents may run beyond the exact
            # provider block.  The block end is authoritative for either a
            # sole contribution or the final contribution in a grouped block;
            # an interior crossing row remains ambiguous and is skipped.
            proof_end = block_end
        else:
            continue
        proof_size = address_value(proof_end) - address_value(address)
        if proof_size < 6:
            continue
        thunk_extent = _hexdump_bytes(bridge.hexdump(address, proof_size))
        if len(thunk_extent) != proof_size:
            raise ValueError(
                f"PE named import thunk {symbol_id} immutable extent is truncated"
            )
        if thunk_extent[:2] != b"\xff\x25":
            continue
        if any(value not in {0x90, 0xCC} for value in thunk_extent[6:]):
            raise ValueError(
                f"PE named import thunk {symbol_id} is not one exact immutable "
                "FF25 thunk followed only by registered padding"
            )
        iat_address = normalize_address(struct.unpack_from("<I", thunk_extent, 2)[0])
        immutable_matches = import_targets_by_address.get(iat_address, [])
        if len(immutable_matches) > 1 and any(
            getattr(target, "import_ordinal", None) is not None
            for target in immutable_matches
        ):
            raise ValueError(
                f"PE import thunk {symbol_id} IAT operand has ambiguous "
                "immutable named/ordinal routes"
            )
        provider_identity = f"provider:{symbol_id}"
        if (
            indexes.by_address.get(address) != provider_identity
            or provider_identity not in indexes.provider_ids
        ):
            raise ValueError(
                f"PE import thunk {symbol_id} lacks one collision-free "
                "governed physical provider identity"
            )
        ordinal_route = (
            len(immutable_matches) == 1
            and getattr(immutable_matches[0], "import_ordinal", None) is not None
        )
        named_matches = named_targets_by_address.get(iat_address, [])
        immutable_import_name = (
            str(getattr(named_matches[0], "import_name"))
            if len(named_matches) == 1
            else None
        )
        friendly_symbol = _exact_bn_pe_import_friendly_symbol(
            bridge_by_address=bridge_by_address,
            bridge_by_name=bridge_by_name,
            address=address,
            retail_name=retail_name,
            immutable_import_name=(
                None if ordinal_route else immutable_import_name
            ),
        )
        if friendly_symbol is None:
            raise ValueError(
                f"PE import thunk {symbol_id} lacks one exact BN friendly "
                "target at its governed address"
            )
        if ordinal_route:
            # The sibling ordinal producer owns its accepted-owner/current-IAT
            # package and candidate COFF identity proof.  Classify the exact
            # immutable ordinal tuple before enforcing named-import authority
            # so a real ordinal thunk cannot be misreported as a missing named
            # package by this expected-side fallback.
            continue
        target_matches = named_matches
        if len(target_matches) != 1:
            raise ValueError(
                f"PE named import thunk {symbol_id} IAT operand does not join "
                "one unique immutable named import"
            )
        target = target_matches[0]
        import_name = str(getattr(target, "import_name"))
        import_dll = str(getattr(target, "dll"))
        if len(named_target_routes.get(import_name, set())) != 1:
            raise ValueError(
                f"PE named import thunk {symbol_id} import name {import_name!r} "
                "has ambiguous DLL/IAT routes"
            )
        package_matches = [
            package
            for package in current_packages
            if package.address == iat_address
        ]
        if len(package_matches) > 1:
            raise ValueError(
                f"PE named import thunk {symbol_id} has ambiguous current "
                "tracker packages"
            )
        if package_matches:
            package = package_matches[0]
            if (
                package.import_ordinal is not None
                or package.import_dll != import_dll
                or package.import_name != import_name
                or package.identity != f"iat:{import_name}"
            ):
                raise ValueError(
                    f"PE named import thunk {symbol_id} conflicts with its "
                    "current tracker package"
                )
        proven.append(
            ProviderPeNamedImportThunk(
                provider_identity=provider_identity,
                thunk_address=address,
                retail_name=retail_name,
                iat_identity=f"iat:{import_name}",
                iat_address=iat_address,
                import_dll=import_dll,
                import_name=import_name,
            )
        )
        retail_names.setdefault(retail_name, []).append(friendly_symbol)
        already_proven.add(address)

    for attribute in (
        "provider_identity",
        "thunk_address",
        "retail_name",
        "iat_identity",
    ):
        values = [getattr(thunk, attribute) for thunk in proven]
        if len(values) != len(set(values)):
            raise ValueError(
                "named import thunk discovery has duplicate or colliding "
                f"{attribute.replace('_', ' ')} values"
            )
    return tuple(proven), retail_names


def _exact_bn_pe_import_friendly_symbol(
    *,
    bridge_by_address: Mapping[str, Any],
    bridge_by_name: Mapping[str, Any],
    address: str,
    retail_name: str,
    immutable_import_name: str | None = None,
) -> Any | None:
    """Join one exact BN function/import view for a PE import thunk.

    Binary Ninja exposes an imported-function symbol through both its function
    and import inventories.  ``BinaryNinjaBridge.symbols`` deliberately gives
    the import inventory the final address slot.  Most live MFC42 rows retain
    the decorated navigation name while ``full_name`` is a demangled alias;
    one reviewed function navigation alias can coexist with a differently
    named import row at that exact address.  Named CRT/platform thunks use the
    same two representations.  Admit them only when every nonempty import alias
    is independently indexed back to the identical import symbol and the
    governed function alias is exact.  When immutable PE supplies a named
    import, also require the canonical BN import name/raw name to equal it.
    Keep the legacy function-only row accepted for stable views and fixtures;
    no other symbol kind or alias approximation participates.
    """

    friendly_symbol = bridge_by_name.get(retail_name)
    address_symbol = bridge_by_address.get(address)
    if friendly_symbol is None or address_symbol is None:
        return None

    def identity(symbol: Any) -> tuple[str, str, str, str, str]:
        return (
            str(getattr(symbol, "address", "")),
            str(getattr(symbol, "name", "")),
            str(getattr(symbol, "raw_name", "")),
            str(getattr(symbol, "full_name", "")),
            str(getattr(symbol, "kind", "")),
        )

    friendly_identity = identity(friendly_symbol)
    address_identity = identity(address_symbol)
    friendly_address, friendly_name, friendly_raw, friendly_full, friendly_kind = (
        friendly_identity
    )
    if friendly_address != address or friendly_name != retail_name:
        return None
    if friendly_identity == address_identity and friendly_kind == "function":
        return friendly_symbol

    import_address, import_name, import_raw, import_full, import_kind = (
        address_identity
    )
    if (
        import_address != address
        or import_kind != "import"
        or not import_name
        or import_raw != import_name
        or not import_full
        or (
            immutable_import_name is not None
            and import_name != immutable_import_name
        )
    ):
        return None
    for alias in {import_name, import_raw, import_full}:
        indexed = bridge_by_name.get(alias)
        if indexed is None or identity(indexed) != address_identity:
            return None

    if friendly_identity == address_identity:
        if friendly_raw != retail_name:
            return None
        return friendly_symbol
    if (
        friendly_kind == "function"
        and friendly_raw == retail_name
        and friendly_full in {"", retail_name}
        and retail_name not in {import_name, import_raw, import_full}
    ):
        return friendly_symbol
    return None


def _provider_ordinal_import_thunk_retail_bridges(
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge_by_address: Mapping[str, Any],
    bridge_by_name: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    excluded_symbol_ids: frozenset[str] = frozenset(),
) -> tuple[
    tuple[ProviderOrdinalImportThunk, ...],
    dict[str, list[Any]],
]:
    """Prove governed six-byte FF25 ordinal-import thunks from current facts."""
    owners = document.collection("owners")
    symbols = document.collection("symbols")
    physical_blocks = document.collection("physical_blocks")
    ordinal_packages = tuple(
        package
        for package in _current_tracker_iat_storage_packages(document)
        if package.import_ordinal is not None
    )
    packages_by_address: dict[str, list[CurrentIatStoragePackage]] = {}
    for package in ordinal_packages:
        packages_by_address.setdefault(package.address, []).append(package)

    primary_owners_by_symbol: dict[str, list[tuple[str, Mapping[str, Any]]]] = {}
    for owner_id, owner in owners.items():
        if not isinstance(owner, Mapping):
            continue
        relationships = owner.get("relationships")
        if not isinstance(relationships, list):
            continue
        for relationship in relationships:
            if (
                isinstance(relationship, Mapping)
                and relationship.get("kind") == "primary-function"
                and isinstance(relationship.get("symbol_id"), str)
            ):
                primary_owners_by_symbol.setdefault(
                    str(relationship["symbol_id"]),
                    [],
                ).append((str(owner_id), owner))

    proven: list[ProviderOrdinalImportThunk] = []
    retail_names: dict[str, list[Any]] = {}
    for symbol_id, owner_rows in primary_owners_by_symbol.items():
        if symbol_id in excluded_symbol_ids:
            continue
        symbol = symbols.get(symbol_id)
        if not isinstance(symbol, Mapping):
            continue
        raw_address = symbol.get("address")
        if not isinstance(raw_address, str):
            continue
        try:
            address = normalize_address(raw_address)
        except ProgressError:
            continue
        if (
            symbol.get("binary") != "recoil"
            or symbol.get("kind") != "function"
            or symbol.get("pipeline_class") != "non-authored"
            or symbol.get("authored_order_role") != "non-authored"
            or symbol.get("extent_state") != "known"
            or symbol.get("address") != address
            or symbol.get("end_exclusive")
            != normalize_address(address_value(address) + 6)
            or symbol.get("size") != 6
            or symbol.get("output_section_id") != "recoil:section:.text"
            or symbol.get("ownership_state") != "primary-owned"
            or not isinstance(symbol.get("physical_block_id"), str)
        ):
            continue

        expected_relationships = [
            {"kind": "anchor-address", "address": address},
            {
                "kind": "primary-function",
                "address": address,
                "symbol_id": symbol_id,
            },
        ]
        accepted_owner_rows = [
            (owner_id, owner)
            for owner_id, owner in owner_rows
            if owner.get("binary") == "recoil"
            and owner.get("kind") == "provider-boundary"
            and owner.get("blocker") == "none"
            and owner.get("lifecycle_state") == "accepted"
            and owner.get("provider_state") == "accepted"
            and owner.get("source_paths") == []
        ]
        if not accepted_owner_rows:
            continue
        if (
            len(owner_rows) != 1
            or len(accepted_owner_rows) != 1
            or accepted_owner_rows[0][1].get("relationships")
            != expected_relationships
        ):
            raise ValueError(
                f"ordinal import thunk {symbol_id} lacks exactly one accepted "
                "provider-boundary primary owner"
            )

        block_id = str(symbol["physical_block_id"])
        block = physical_blocks.get(block_id)
        mapping = block.get("mapping") if isinstance(block, Mapping) else None
        contribution_ids = (
            block.get("contribution_ids")
            if isinstance(block, Mapping)
            else None
        )
        try:
            block_start = normalize_address(str(block.get("start", "")))
            block_end = normalize_address(str(block.get("end_exclusive", "")))
        except (ProgressError, AttributeError):
            block_start = ""
            block_end = ""
        if (
            not isinstance(block, Mapping)
            or block.get("binary") != "recoil"
            or block.get("row_kind") != "physical-source-block"
            or block.get("contribution_kind") != "provider"
            or not isinstance(mapping, Mapping)
            or mapping.get("status") != "provider-boundary"
            or not isinstance(contribution_ids, list)
            or contribution_ids.count(symbol_id) != 1
            or not block_start
            or not block_end
            or address_value(block_start) > address_value(address)
            or address_value(block_end)
            < address_value(symbol["end_exclusive"])
            or not isinstance(block.get("agent_source_path"), str)
            or not str(block["agent_source_path"]).startswith("provider:")
            or block.get("source_path") != block.get("agent_source_path")
        ):
            raise ValueError(
                f"ordinal import thunk {symbol_id} lacks one exact provider block"
            )

        thunk_bytes = _hexdump_bytes(bridge.hexdump(address, 6))
        if len(thunk_bytes) != 6 or thunk_bytes[:2] != b"\xff\x25":
            raise ValueError(
                f"ordinal import thunk {symbol_id} is not an exact immutable "
                "six-byte FF25 thunk"
            )
        iat_address = normalize_address(struct.unpack_from("<I", thunk_bytes, 2)[0])
        packages = packages_by_address.get(iat_address, [])
        if len(packages) != 1:
            raise ValueError(
                f"ordinal import thunk {symbol_id} IAT operand does not join "
                "one complete current ordinal package"
            )
        package = packages[0]
        callable_symbol = package.object_symbol.removeprefix("__imp_")
        if (
            callable_symbol == package.object_symbol
            or not callable_symbol
            or not _decorated_coff_name(callable_symbol)
            or indexes.storage_by_address.get(package.address)
            != package.identity
            or indexes.storage_by_name.get(package.object_symbol)
            != package.identity
        ):
            raise ValueError(
                f"ordinal import thunk {symbol_id} package has no exact distinct "
                "callable/IAT COFF identity"
            )

        provider_identity = f"provider:{symbol_id}"
        if (
            indexes.by_address.get(address) != provider_identity
            or provider_identity not in indexes.provider_ids
        ):
            raise ValueError(
                f"ordinal import thunk {symbol_id} lacks one collision-free "
                "governed callable identity"
            )
        retail_name = symbol.get("navigation_name")
        friendly_symbol = (
            _exact_bn_pe_import_friendly_symbol(
                bridge_by_address=bridge_by_address,
                bridge_by_name=bridge_by_name,
                address=address,
                retail_name=retail_name,
            )
            if isinstance(retail_name, str) and retail_name
            else None
        )
        if friendly_symbol is None:
            raise ValueError(
                f"ordinal import thunk {symbol_id} lacks one exact BN friendly "
                "target at its governed address"
            )

        thunk = ProviderOrdinalImportThunk(
            provider_identity=provider_identity,
            thunk_address=address,
            retail_name=str(retail_name),
            callable_symbol=callable_symbol,
            iat_object_symbol=package.object_symbol,
            iat_identity=package.identity,
            import_dll=package.import_dll,
            import_ordinal=int(package.import_ordinal),
        )
        proven.append(thunk)
        retail_names.setdefault(str(retail_name), []).append(friendly_symbol)

    for attribute in (
        "provider_identity",
        "thunk_address",
        "retail_name",
        "callable_symbol",
        "iat_object_symbol",
        "iat_identity",
    ):
        values = [getattr(thunk, attribute) for thunk in proven]
        if len(values) != len(set(values)):
            raise ValueError(
                "ordinal import thunk discovery has duplicate or colliding "
                f"{attribute.replace('_', ' ')} values"
            )
    return tuple(proven), retail_names


def _wol_cstring_provider_ordinal_import_thunk_retail_bridge(
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge_by_address: Mapping[str, Any],
    bridge_by_name: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    retail_import_targets: Sequence[Any] | None = None,
) -> tuple[tuple[ProviderOrdinalImportThunk, ...], dict[str, list[Any]]]:
    """Prove WOL's CString thunk without trusting BN's import label.

    Binary Ninja currently exposes the physical ``0x4c5ba0`` function under
    the reviewed CString navigation label while its import inventory assigns
    the same ordinal-only slot an unrelated MFC class name.  The immutable PE
    import directory, the accepted tracker provider, exact FF25 bytes, and
    complete inbound xrefs own the route.  The current BN import row is checked
    only as a same-address diagnostic representation; none of its names supply
    CString identity, the callable COFF spelling, or the IAT object spelling.
    """

    symbols = document.collection("symbols")
    owners = document.collection("owners")
    blocks = document.collection("physical_blocks")
    symbol = symbols.get(WOL_CSTRING_TARGET_SYMBOL_ID)
    owner = owners.get(WOL_CSTRING_OWNER_ID)
    if symbol is None and owner is None:
        return (), {}
    block = (
        blocks.get(str(symbol.get("physical_block_id")))
        if isinstance(symbol, Mapping)
        else None
    )
    mapping = block.get("mapping") if isinstance(block, Mapping) else None
    authored_order = (
        block.get("order", {}).get("authored")
        if isinstance(block, Mapping)
        and isinstance(block.get("order"), Mapping)
        else None
    )
    current_not_applicable = (
        isinstance(authored_order, Mapping)
        and all(
            isinstance(authored_order.get(key), Mapping)
            and authored_order[key].get("result") == "not-applicable"
            and authored_order[key].get("disposition") == "accepted"
            and authored_order[key].get("freshness") == "current"
            and authored_order[key].get("gating") is True
            and authored_order[key].get("validation_mode") == "live"
            for key in AUTHORED_ORDER_DIMENSIONS
        )
    )
    expected_relationships = [
        {"kind": "anchor-address", "address": WOL_CSTRING_TARGET_ADDRESS},
        {
            "kind": "primary-function",
            "address": WOL_CSTRING_TARGET_ADDRESS,
            "symbol_id": WOL_CSTRING_TARGET_SYMBOL_ID,
        },
    ]
    primary_owner_ids = [
        str(owner_id)
        for owner_id, row in owners.items()
        if isinstance(row, Mapping)
        and any(
            isinstance(relationship, Mapping)
            and relationship.get("kind") == "primary-function"
            and relationship.get("symbol_id") == WOL_CSTRING_TARGET_SYMBOL_ID
            for relationship in row.get("relationships", ())
        )
    ]
    if (
        not isinstance(symbol, Mapping)
        or symbol.get("binary") != "recoil"
        or symbol.get("kind") != "function"
        or symbol.get("pipeline_class") != "non-authored"
        or symbol.get("authored_order_role") != "non-authored"
        or symbol.get("address") != WOL_CSTRING_TARGET_ADDRESS
        or symbol.get("end_exclusive") != WOL_CSTRING_TARGET_END_EXCLUSIVE
        or symbol.get("extent_state") != "known"
        or symbol.get("size") != 6
        or symbol.get("navigation_name") != WOL_CSTRING_RETAIL_NAME
        or symbol.get("output_section_id") != "recoil:section:.text"
        or symbol.get("ownership_state") != "primary-owned"
        or symbol.get("physical_block_id") != WOL_CEDIT_TARGET_BLOCK_ID
        or indexes.by_address.get(WOL_CSTRING_TARGET_ADDRESS)
        != WOL_CSTRING_TARGET_IDENTITY
        or WOL_CSTRING_TARGET_IDENTITY not in indexes.provider_ids
        or primary_owner_ids != [WOL_CSTRING_OWNER_ID]
        or not isinstance(owner, Mapping)
        or owner.get("binary") != "recoil"
        or owner.get("kind") != "provider-boundary"
        or owner.get("blocker") != "none"
        or owner.get("lifecycle_state") != "accepted"
        or owner.get("provider_state") != "accepted"
        or owner.get("source_paths") != []
        or owner.get("relationships") != expected_relationships
        or not isinstance(block, Mapping)
        or block.get("binary") != "recoil"
        or block.get("row_kind") != "physical-source-block"
        or block.get("start") != "0x4c5a50"
        or block.get("end_exclusive") != "0x4c5eb8"
        or block.get("contribution_kind") != "provider"
        or block.get("agent_source_path")
        != "provider:mfc42-tail-import-thunks"
        or block.get("source_path") != "provider:mfc42-tail-import-thunks"
        or not isinstance(block.get("contribution_ids"), list)
        or block["contribution_ids"].count(WOL_CSTRING_TARGET_SYMBOL_ID) != 1
        or not isinstance(mapping, Mapping)
        or mapping.get("status") != "provider-boundary"
        or not current_not_applicable
    ):
        raise ValueError(
            "WOL CString ordinal bridge lacks the exact accepted tracker "
            "provider and current provider block"
        )

    targets = tuple(
        retail_import_targets
        if retail_import_targets is not None
        else _retail_import_targets(DEFAULT_REFERENCE)[0]
    )
    slot_matches = [
        target
        for target in targets
        if normalize_address(str(getattr(target, "address", "")))
        == WOL_CSTRING_IAT_ADDRESS
    ]
    target = slot_matches[0] if len(slot_matches) == 1 else None
    if (
        target is None
        or getattr(target, "dll", None) != "MFC42.DLL"
        or getattr(target, "import_name", None)
        != f"#{WOL_CSTRING_IMPORT_ORDINAL}"
        or getattr(target, "import_ordinal", None)
        != WOL_CSTRING_IMPORT_ORDINAL
        or getattr(target, "descriptor_index", None)
        != WOL_CSTRING_IMPORT_DESCRIPTOR_INDEX
        or getattr(target, "thunk_index", None)
        != WOL_CSTRING_IMPORT_SLOT_INDEX
        or normalize_address(str(getattr(target, "iat_rva", "")))
        != WOL_CSTRING_IAT_RVA
        or normalize_address(str(getattr(target, "iat_end_rva", "")))
        != WOL_CSTRING_IAT_END_RVA
        or (
            address_value(WOL_CSTRING_IAT_RVA)
            - WOL_CSTRING_IMPORT_SLOT_INDEX * 4
        )
        != WOL_CSTRING_MFC42_FIRST_IAT_RVA
    ):
        raise ValueError(
            "WOL CString ordinal bridge lacks the exact immutable "
            "MFC42 descriptor-two ordinal-540 IAT/ILT slot"
        )

    friendly = bridge_by_name.get(WOL_CSTRING_RETAIL_NAME)
    import_diagnostic = bridge_by_address.get(WOL_CSTRING_TARGET_ADDRESS)

    def bn_identity(row: Any) -> tuple[str, str, str, str, str]:
        return (
            str(getattr(row, "address", "")),
            str(getattr(row, "name", "")),
            str(getattr(row, "raw_name", "")),
            str(getattr(row, "full_name", "")),
            str(getattr(row, "kind", "")),
        )

    friendly_identity = bn_identity(friendly)
    import_identity = bn_identity(import_diagnostic)
    diagnostic_aliases = {
        value for value in import_identity[1:4] if value
    }
    if (
        friendly_identity
        != (
            WOL_CSTRING_TARGET_ADDRESS,
            WOL_CSTRING_RETAIL_NAME,
            WOL_CSTRING_RETAIL_NAME,
            "",
            "function",
        )
        or import_identity[0] != WOL_CSTRING_TARGET_ADDRESS
        or import_identity[4] != "import"
        or not import_identity[1]
        or import_identity[2] != import_identity[1]
        or any(
            bn_identity(bridge_by_name.get(alias)) != import_identity
            for alias in diagnostic_aliases
        )
    ):
        raise ValueError(
            "WOL CString ordinal bridge lacks the exact BN function view "
            "and complete same-address diagnostic import view"
        )

    thunk_bytes = _hexdump_bytes(
        bridge.hexdump(WOL_CSTRING_TARGET_ADDRESS, 6)
    )
    if (
        thunk_bytes != b"\xff\x25\xc0\xc3\x4c\x00"
        or normalize_address(struct.unpack_from("<I", thunk_bytes, 2)[0])
        != WOL_CSTRING_IAT_ADDRESS
    ):
        raise ValueError(
            "WOL CString ordinal bridge requires exact immutable "
            "FF25 [0x4cc3c0] thunk bytes"
        )

    get_json = getattr(bridge, "get_json", None)
    if not callable(get_json):
        raise ValueError(
            "WOL CString ordinal bridge lacks complete BN xref authority"
        )
    thunk_payload = get_json(
        "getXrefsTo", address=WOL_CSTRING_TARGET_ADDRESS, limit=100000
    )
    thunk_code, thunk_data, thunk_complete = _bn_inbound_xref_items(
        thunk_payload
    )
    code_addresses = tuple(
        _bn_xref_address(
            row,
            "source_address",
            "source_addr",
            "from_address",
            "address",
        )
        for row in thunk_code
    )
    data_addresses = tuple(
        _bn_xref_address(
            row,
            "source_address",
            "source_addr",
            "from_address",
            "address",
        )
        for row in thunk_data
    )
    if (
        not thunk_complete
        or not code_addresses
        or any(not address for address in (*code_addresses, *data_addresses))
        or len(code_addresses) != len(set(code_addresses))
        or len(data_addresses) != len(set(data_addresses))
    ):
        raise ValueError(
            "WOL CString ordinal bridge lacks a complete collision-free "
            "thunk-xref population"
        )

    assembly_by_function: dict[str, tuple[Instruction, ...]] = {}
    rel32_addresses: list[str] = []
    caller_rel32_addresses: list[str] = []
    for call_address in code_addresses:
        _name, function_address = _bn_unique_containing_function(
            bridge,
            instruction_address=call_address,
        )
        rows = assembly_by_function.setdefault(
            function_address,
            tuple(parse_assembly(bridge.assembly(function_address), source="bn")),
        )
        matches = [
            row
            for row in rows
            if _source_instruction_address(row) == call_address
        ]
        if len(matches) != 1:
            raise ValueError(
                "WOL CString ordinal bridge has thunk caller xref drift"
            )
        try:
            encoded = bytes(int(value, 16) for value in matches[0].bytes)
        except (TypeError, ValueError):
            encoded = b""
        is_rel32 = (
            len(encoded) == 5
            and encoded[0] in {0xE8, 0xE9}
            and normalize_address(
                address_value(call_address)
                + 5
                + struct.unpack_from("<i", encoded, 1)[0]
            )
            == WOL_CSTRING_TARGET_ADDRESS
        )
        if not is_rel32:
            continue
        rel32_addresses.append(call_address)
        if (
            address_value(WOL_CEDIT_CALLER_ADDRESS)
            <= address_value(call_address)
            < address_value(WOL_CEDIT_CALLER_END_EXCLUSIVE)
        ):
            if function_address != WOL_CEDIT_CALLER_ADDRESS or encoded[0] != 0xE8:
                raise ValueError(
                    "WOL CString ordinal bridge has non-direct WOL caller xref drift"
                )
            caller_rel32_addresses.append(call_address)
    if (
        not rel32_addresses
        or tuple(caller_rel32_addresses) != WOL_CSTRING_RETAIL_CALL_SITES
    ):
        raise ValueError(
            "WOL CString ordinal bridge requires exactly the three reviewed "
            "WOL direct E8 caller sites"
        )

    iat_payload = get_json(
        "getXrefsTo", address=WOL_CSTRING_IAT_ADDRESS, limit=100000
    )
    iat_code, iat_data, iat_complete = _bn_inbound_xref_items(iat_payload)
    iat_readers = tuple(
        _bn_xref_address(
            row,
            "source_address",
            "source_addr",
            "from_address",
            "address",
        )
        for row in iat_code
    )
    if (
        not iat_complete
        or iat_data
        or iat_readers != (WOL_CSTRING_TARGET_ADDRESS,)
    ):
        raise ValueError(
            "WOL CString ordinal bridge requires the exact sole FF25 IAT reader"
        )

    thunk = ProviderOrdinalImportThunk(
        provider_identity=WOL_CSTRING_TARGET_IDENTITY,
        thunk_address=WOL_CSTRING_TARGET_ADDRESS,
        retail_name=WOL_CSTRING_RETAIL_NAME,
        callable_symbol=WOL_CSTRING_CANDIDATE_SYMBOL,
        iat_object_symbol=WOL_CSTRING_IAT_OBJECT_SYMBOL,
        iat_identity=(
            f"iat:ordinal:9:MFC42.DLL:{WOL_CSTRING_IMPORT_ORDINAL}"
        ),
        import_dll="MFC42.DLL",
        import_ordinal=WOL_CSTRING_IMPORT_ORDINAL,
    )
    return (thunk,), {WOL_CSTRING_RETAIL_NAME: [friendly]}


def _provider_pe_ordinal_import_thunk_retail_bridges(
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge_by_address: Mapping[str, Any],
    bridge_by_name: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    retail_import_targets: Sequence[Any] | None = None,
) -> tuple[
    IdentityIndexes,
    tuple[ProviderOrdinalImportThunk, ...],
    dict[str, list[Any]],
]:
    """Compose exact unowned ordinal thunks through reviewed provider blocks.

    The immutable PE import directory owns the ordinal IAT tuple, while the
    tracker owns the physical function extent/identity and the already
    reviewed provider block.  This comparison-scoped join deliberately does
    not require or create a primary owner or provider-target registration for
    every six-byte MFC thunk.
    """

    symbols = document.collection("symbols")
    blocks = document.collection("physical_blocks")
    owners = document.collection("owners")
    primary_owned_symbols = {
        str(relationship.get("symbol_id"))
        for owner in owners.values()
        if isinstance(owner, Mapping)
        for relationship in owner.get("relationships", ())
        if isinstance(relationship, Mapping)
        and relationship.get("kind") == "primary-function"
        and isinstance(relationship.get("symbol_id"), str)
    }
    supplied_targets = tuple(
        retail_import_targets
        if retail_import_targets is not None
        else _retail_import_targets(DEFAULT_REFERENCE)[0]
    )
    all_targets_by_address: dict[str, list[Any]] = {}
    ordinal_targets_by_address: dict[str, list[Any]] = {}
    for target in supplied_targets:
        raw_address = getattr(target, "address", "")
        import_name = getattr(target, "import_name", None)
        import_dll = getattr(target, "dll", None)
        import_ordinal = getattr(target, "import_ordinal", None)
        try:
            iat_address = normalize_address(str(raw_address))
        except ProgressError as exc:
            raise ValueError(
                "PE ordinal thunk composition received a malformed immutable "
                "IAT address"
            ) from exc
        all_targets_by_address.setdefault(iat_address, []).append(target)
        if import_ordinal is None:
            continue
        if (
            not isinstance(import_ordinal, int)
            or isinstance(import_ordinal, bool)
            or not 0 <= import_ordinal <= 0xFFFF
            or import_name != f"#{import_ordinal}"
            or not isinstance(import_dll, str)
            or not import_dll
            or "/" in import_dll
            or "\\" in import_dll
        ):
            raise ValueError(
                "PE ordinal thunk composition received a malformed immutable "
                "ordinal import tuple"
            )
        ordinal_targets_by_address.setdefault(iat_address, []).append(target)

    get_json = getattr(bridge, "get_json", None)
    proven: list[ProviderOrdinalImportThunk] = []
    names: dict[str, list[Any]] = {}
    storage_by_address = dict(indexes.storage_by_address)
    storage_by_name = dict(indexes.storage_by_name)
    for symbol_id, symbol in symbols.items():
        if (
            not isinstance(symbol, Mapping)
            or symbol_id in primary_owned_symbols
            or symbol.get("binary") != "recoil"
            or symbol.get("kind") != "function"
            or symbol.get("pipeline_class") != "non-authored"
            or symbol.get("authored_order_role") != "non-authored"
            or symbol.get("ownership_state") != "unresolved"
            or symbol.get("disposition") != "unresolved"
            or symbol.get("extent_state") != "known"
            or symbol.get("output_section_id") != "recoil:section:.text"
            or symbol.get("size") != 6
            or not isinstance(symbol.get("address"), str)
            or not isinstance(symbol.get("physical_block_id"), str)
            or not isinstance(symbol.get("navigation_name"), str)
            or not symbol.get("navigation_name")
        ):
            continue
        try:
            address = normalize_address(str(symbol["address"]))
            end_exclusive = normalize_address(
                str(symbol.get("end_exclusive", ""))
            )
        except ProgressError:
            continue
        if end_exclusive != normalize_address(address_value(address) + 6):
            continue

        thunk_bytes = _hexdump_bytes(bridge.hexdump(address, 6))
        if len(thunk_bytes) != 6:
            raise ValueError(
                f"PE ordinal thunk prefilter at {symbol_id} has truncated "
                "immutable bytes"
            )
        if thunk_bytes[:2] != b"\xff\x25":
            continue
        iat_address = normalize_address(
            struct.unpack_from("<I", thunk_bytes, 2)[0]
        )
        packages = ordinal_targets_by_address.get(iat_address, [])
        all_packages = all_targets_by_address.get(iat_address, [])
        if not packages and len(all_packages) == 1:
            # A unique named import belongs to the sibling named producer.
            continue
        if len(packages) != 1:
            raise ValueError(
                f"PE ordinal thunk {symbol_id} IAT operand does not join one "
                "unique immutable ordinal import"
            )
        package = packages[0]

        same_address_symbols = [
            other_id
            for other_id, other in symbols.items()
            if isinstance(other, Mapping)
            and other.get("binary") == "recoil"
            and other.get("kind") == "function"
            and other.get("address") == address
        ]
        if same_address_symbols != [symbol_id]:
            raise ValueError(
                f"PE ordinal thunk {symbol_id} has ambiguous physical aliases"
            )
        block = blocks.get(str(symbol["physical_block_id"]))
        mapping = block.get("mapping") if isinstance(block, Mapping) else None
        contribution_ids = (
            block.get("contribution_ids")
            if isinstance(block, Mapping)
            else None
        )
        authored_order = (
            block.get("order", {}).get("authored")
            if isinstance(block, Mapping)
            and isinstance(block.get("order"), Mapping)
            else None
        )
        current_not_applicable = (
            isinstance(authored_order, Mapping)
            and all(
                isinstance(authored_order.get(key), Mapping)
                and authored_order[key].get("result") == "not-applicable"
                and authored_order[key].get("disposition") == "accepted"
                and authored_order[key].get("freshness") == "current"
                and authored_order[key].get("gating") is True
                and authored_order[key].get("validation_mode") == "live"
                for key in AUTHORED_ORDER_DIMENSIONS
            )
        )
        try:
            block_start = normalize_address(str(block.get("start", "")))
            block_end = normalize_address(str(block.get("end_exclusive", "")))
        except (ProgressError, AttributeError):
            block_start = ""
            block_end = ""
        if block_end == end_exclusive:
            # Preserve the stricter terminal-block producer for its existing
            # current-package/xref population.
            continue
        if (
            not isinstance(block, Mapping)
            or block.get("binary") != "recoil"
            or block.get("row_kind") != "physical-source-block"
            or block.get("contribution_kind") != "provider"
            or not isinstance(mapping, Mapping)
            or mapping.get("status") != "provider-boundary"
            or not current_not_applicable
            or not isinstance(contribution_ids, list)
            or contribution_ids.count(symbol_id) != 1
            or not block_start
            or not block_end
            or not (
                address_value(block_start)
                <= address_value(address)
                < address_value(end_exclusive)
                <= address_value(block_end)
            )
            or not isinstance(block.get("agent_source_path"), str)
            or not str(block["agent_source_path"]).startswith("provider:")
            or block.get("source_path") != block.get("agent_source_path")
        ):
            raise ValueError(
                f"PE ordinal thunk {symbol_id} lacks one exact current "
                "provider block"
            )

        provider_identity = f"provider:{symbol_id}"
        if (
            indexes.by_address.get(address) != provider_identity
            or provider_identity not in indexes.provider_ids
        ):
            raise ValueError(
                f"PE ordinal thunk {symbol_id} lacks one collision-free "
                "physical provider identity"
            )
        retail_name = str(symbol["navigation_name"])
        friendly = _exact_bn_pe_import_friendly_symbol(
            bridge_by_address=bridge_by_address,
            bridge_by_name=bridge_by_name,
            address=address,
            retail_name=retail_name,
        )
        address_symbol = bridge_by_address.get(address)
        callable_symbol = str(getattr(address_symbol, "name", ""))
        if (
            friendly is None
            or getattr(address_symbol, "kind", "") != "import"
            or not callable_symbol
            or (
                not _decorated_coff_name(callable_symbol)
                and re.fullmatch(
                    r"[A-Za-z_][A-Za-z0-9_@$?]*", callable_symbol
                )
                is None
            )
        ):
            raise ValueError(
                f"PE ordinal thunk {symbol_id} lacks one exact BN friendly "
                "callable"
            )

        if not callable(get_json):
            raise ValueError(
                f"PE ordinal thunk {symbol_id} lacks complete xref authority"
            )
        thunk_payload = get_json("getXrefsTo", address=address, limit=100000)
        thunk_code, thunk_data, thunk_complete = _bn_inbound_xref_items(
            thunk_payload
        )
        caller_addresses = tuple(
            _bn_xref_address(
                row,
                "source_address",
                "source_addr",
                "from_address",
                "address",
            )
            for row in thunk_code
        )
        if thunk_complete and not caller_addresses:
            # A physical six-byte ordinal stub with no immutable inbound
            # REL32 transfer is not active for call-contract comparison.
            # Static data references do not turn an address-valued provider
            # entry into a call target.
            continue
        if (
            not thunk_complete
            or any(not caller for caller in caller_addresses)
            or len(caller_addresses) != len(set(caller_addresses))
        ):
            raise ValueError(
                f"PE ordinal thunk {symbol_id} lacks a complete collision-free "
                "REL32 caller population"
            )
        rel32_caller_addresses: list[str] = []
        for caller_address in caller_addresses:
            _caller_name, caller_function = _bn_unique_containing_function(
                bridge,
                instruction_address=caller_address,
            )
            caller_rows = tuple(
                parse_assembly(bridge.assembly(caller_function), source="bn")
            )
            matches = [
                row
                for row in caller_rows
                if _source_instruction_address(row) == caller_address
            ]
            if len(matches) != 1:
                raise ValueError(
                    f"PE ordinal thunk {symbol_id} has caller xref drift"
                )
            try:
                caller_bytes = bytes(int(value, 16) for value in matches[0].bytes)
            except (TypeError, ValueError):
                caller_bytes = b""
            if (
                len(caller_bytes) != 5
                or caller_bytes[0] not in {0xE8, 0xE9}
                or normalize_address(
                    address_value(caller_address)
                    + 5
                    + struct.unpack_from("<i", caller_bytes, 1)[0]
                )
                != address
            ):
                # BN code xrefs also include address materializations and EH
                # metadata consumers.  They do not activate an invocation
                # route; only exact rel32 CALL/JMP rows do.
                continue
            rel32_caller_addresses.append(caller_address)
        if not rel32_caller_addresses:
            continue
        iat_payload = get_json(
            "getXrefsTo", address=iat_address, limit=100000
        )
        iat_code, iat_data, iat_complete = _bn_inbound_xref_items(iat_payload)
        iat_readers = tuple(
            _bn_xref_address(
                row,
                "source_address",
                "source_addr",
                "from_address",
                "address",
            )
            for row in iat_code
        )
        if (
            not iat_complete
            or iat_data
            or iat_readers != (address,)
        ):
            raise ValueError(
                f"PE ordinal thunk {symbol_id} has IAT-reader xref drift"
            )

        import_dll = str(getattr(package, "dll"))
        import_ordinal = int(getattr(package, "import_ordinal"))
        iat_identity = (
            f"iat:ordinal:{len(import_dll)}:{import_dll}:{import_ordinal}"
        )
        iat_object_symbol = f"__imp_{callable_symbol}"
        for mapping_index, key in (
            (storage_by_address, iat_address),
            (storage_by_name, iat_object_symbol),
        ):
            prior = mapping_index.get(key)
            if prior not in {None, iat_identity}:
                raise ValueError(
                    f"PE ordinal thunk {symbol_id} conflicts with current "
                    f"comparison identity for {key!r}"
                )
            mapping_index[key] = iat_identity
        proven.append(
            ProviderOrdinalImportThunk(
                provider_identity=provider_identity,
                thunk_address=address,
                retail_name=retail_name,
                callable_symbol=callable_symbol,
                iat_object_symbol=iat_object_symbol,
                iat_identity=iat_identity,
                import_dll=import_dll,
                import_ordinal=import_ordinal,
            )
        )
        names.setdefault(retail_name, []).append(friendly)

    for attribute in (
        "provider_identity",
        "thunk_address",
        "retail_name",
        "callable_symbol",
        "iat_object_symbol",
        "iat_identity",
    ):
        values = [getattr(thunk, attribute) for thunk in proven]
        if len(values) != len(set(values)):
            raise ValueError(
                "PE ordinal thunk composition has duplicate or colliding "
                f"{attribute.replace('_', ' ')} values"
            )
    return (
        replace(
            indexes,
            storage_by_address=storage_by_address,
            storage_by_name=storage_by_name,
        ),
        tuple(proven),
        names,
    )


def _provider_terminal_ordinal_import_thunk_retail_bridges(
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge_by_address: Mapping[str, Any],
    bridge_by_name: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
) -> tuple[tuple[ProviderOrdinalImportThunk, ...], dict[str, list[Any]]]:
    """Prove exact terminal FF25 ordinal thunks in reviewed provider blocks.

    Some retail provider blocks end in a six-byte import thunk while the BN
    navigation function deliberately has a larger descriptive extent and no
    standalone primary owner.  Accept that physical row only when it is the
    exact final six bytes of one reviewed provider block and joins one current
    immutable ordinal-IAT package plus exact BN function/import aliases, one
    complete REL32 caller xref, and one complete FF25 IAT-reader xref.  This is
    not an address or name allowlist and does not infer a target from candidate
    text.
    """

    symbols = document.collection("symbols")
    blocks = document.collection("physical_blocks")
    owners = document.collection("owners")
    ordinal_packages = tuple(
        package
        for package in _current_tracker_iat_storage_packages(document)
        if package.import_ordinal is not None
    )
    primary_owned_symbols = {
        str(relationship.get("symbol_id"))
        for owner in owners.values()
        if isinstance(owner, Mapping)
        for relationship in owner.get("relationships", ())
        if isinstance(relationship, Mapping)
        and relationship.get("kind") == "primary-function"
        and isinstance(relationship.get("symbol_id"), str)
    }
    proven: list[ProviderOrdinalImportThunk] = []
    names: dict[str, list[Any]] = {}
    for symbol_id, symbol in symbols.items():
        if not isinstance(symbol, Mapping) or symbol_id in primary_owned_symbols:
            continue
        raw_address = symbol.get("address")
        block_id = symbol.get("physical_block_id")
        if (
            not isinstance(raw_address, str)
            or not isinstance(block_id, str)
            or symbol.get("kind") != "function"
            or symbol.get("pipeline_class") != "non-authored"
            or symbol.get("authored_order_role") != "non-authored"
        ):
            continue
        try:
            address = normalize_address(raw_address)
            terminal = normalize_address(address_value(address) + 6)
        except (ProgressError, TypeError, ValueError):
            continue

        # A terminal provider block is not, by itself, ordinal-package
        # authority.  Activate only from either the exact raw FF25 operand or
        # an exact BN import alias that joins a complete current package.
        # After that activation every physical/provider/byte/identity gate
        # below remains mandatory and fail-closed.
        thunk_bytes = _hexdump_bytes(bridge.hexdump(address, 6))
        operand_packages: list[CurrentIatStoragePackage] = []
        if len(thunk_bytes) == 6 and thunk_bytes[:2] == b"\xff\x25":
            raw_iat_address = normalize_address(
                struct.unpack_from("<I", thunk_bytes, 2)[0]
            )
            operand_packages = [
                package
                for package in ordinal_packages
                if package.address == raw_iat_address
            ]

        def bridge_identity(row: Any) -> tuple[str, str, str, str, str]:
            return (
                str(getattr(row, "address", "")),
                str(getattr(row, "name", "")),
                str(getattr(row, "raw_name", "")),
                str(getattr(row, "full_name", "")),
                str(getattr(row, "kind", "")),
            )

        address_symbol_identity = bridge_identity(
            bridge_by_address.get(address)
        )
        alias_packages: list[CurrentIatStoragePackage] = []
        for package_candidate in ordinal_packages:
            candidate_callable = (
                package_candidate.object_symbol.removeprefix("__imp_")
            )
            candidate_module = re.sub(
                r"(?i)\.dll$", "", package_candidate.import_dll
            ).upper()
            candidate_ordinal_alias = (
                f"Ordinal_{candidate_module}_{package_candidate.import_ordinal}"
            )
            if (
                not candidate_callable
                or candidate_callable == package_candidate.object_symbol
                or address_symbol_identity[0] != address
                or address_symbol_identity[1]
                not in {candidate_callable, candidate_ordinal_alias}
                or address_symbol_identity[2] != address_symbol_identity[1]
                or not address_symbol_identity[3]
                or address_symbol_identity[4] != "import"
                or any(
                    bridge_identity(bridge_by_name.get(alias))
                    != address_symbol_identity
                    for alias in {
                        address_symbol_identity[1],
                        address_symbol_identity[2],
                        address_symbol_identity[3],
                    }
                )
            ):
                continue
            alias_packages.append(package_candidate)

        activated_packages = {
            package
            for package in (*operand_packages, *alias_packages)
        }
        if not activated_packages:
            continue
        if len(activated_packages) != 1:
            raise ValueError(
                f"terminal ordinal thunk {symbol_id} activates ambiguous "
                "immutable ordinal IAT packages"
            )
        package = next(iter(activated_packages))

        block = blocks.get(block_id)
        mapping = block.get("mapping") if isinstance(block, Mapping) else None
        contribution_ids = (
            block.get("contribution_ids")
            if isinstance(block, Mapping)
            else None
        )
        try:
            block_start = normalize_address(str(block.get("start", "")))
            block_end = normalize_address(str(block.get("end_exclusive", "")))
            symbol_end = normalize_address(
                str(symbol.get("end_exclusive", ""))
            )
        except (ProgressError, AttributeError, TypeError, ValueError):
            raise ValueError(
                f"activated terminal ordinal thunk {symbol_id} has malformed "
                "symbol or provider-block extent"
            )
        if (
            symbol.get("binary") != "recoil"
            or symbol.get("extent_state") != "known"
            or symbol.get("output_section_id") != "recoil:section:.text"
            or not isinstance(block, Mapping)
            or block.get("binary") != "recoil"
            or block.get("row_kind") != "physical-source-block"
            or block.get("contribution_kind") != "provider"
            or not isinstance(mapping, Mapping)
            or mapping.get("status") != "provider-boundary"
            or not isinstance(contribution_ids, list)
            or contribution_ids.count(symbol_id) != 1
            or address_value(block_start) > address_value(address)
            or block_end != terminal
            or address_value(symbol_end) < address_value(terminal)
            or not isinstance(block.get("agent_source_path"), str)
            or not str(block["agent_source_path"]).startswith("provider:")
            or block.get("source_path") != block.get("agent_source_path")
        ):
            raise ValueError(
                f"activated terminal ordinal thunk {symbol_id} lacks one "
                "exact terminal provider block"
            )
        provider_identity = f"provider:{symbol_id}"
        if (
            indexes.by_address.get(address) != provider_identity
            or provider_identity not in indexes.provider_ids
        ):
            raise ValueError(
                f"terminal ordinal thunk {symbol_id} lacks its exact provider "
                "identity"
            )
        if len(thunk_bytes) != 6 or thunk_bytes[:2] != b"\xff\x25":
            raise ValueError(
                f"terminal ordinal thunk {symbol_id} is not exact FF25"
            )
        iat_address = normalize_address(
            struct.unpack_from("<I", thunk_bytes, 2)[0]
        )
        if iat_address != package.address:
            raise ValueError(
                f"terminal ordinal thunk {symbol_id} FF25 operand conflicts "
                "with its activated immutable ordinal IAT package"
            )
        get_json = getattr(bridge, "get_json", None)
        if not callable(get_json):
            raise ValueError(
                f"terminal ordinal thunk {symbol_id} lacks complete inbound "
                "xref authority"
            )

        def one_code_xref(target_address: str, label: str) -> str:
            payload = get_json(
                "getXrefsTo",
                address=target_address,
                limit=100000,
            )
            code_rows, data_rows, complete = _bn_inbound_xref_items(payload)
            source_addresses = tuple(
                _bn_xref_address(
                    row,
                    "source_address",
                    "source_addr",
                    "from_address",
                    "address",
                )
                for row in code_rows
            )
            if (
                not complete
                or data_rows
                or len(source_addresses) != 1
                or not source_addresses[0]
            ):
                raise ValueError(
                    f"terminal ordinal thunk {symbol_id} lacks one complete "
                    f"collision-free {label} xref"
                )
            return source_addresses[0]

        thunk_caller_address = one_code_xref(address, "thunk-caller")
        iat_reader_address = one_code_xref(iat_address, "IAT-reader")
        if iat_reader_address != address:
            raise ValueError(
                f"terminal ordinal thunk {symbol_id} IAT xref does not "
                "rejoin the exact FF25 reader"
            )
        _caller_name, caller_function = _bn_unique_containing_function(
            bridge,
            instruction_address=thunk_caller_address,
        )
        caller_rows = tuple(
            parse_assembly(bridge.assembly(caller_function), source="bn")
        )
        caller_matches = [
            row
            for row in caller_rows
            if _source_instruction_address(row) == thunk_caller_address
        ]
        if len(caller_matches) != 1:
            raise ValueError(
                f"terminal ordinal thunk {symbol_id} lacks one exact caller row"
            )
        caller_row = caller_matches[0]
        try:
            caller_body = bytes(int(item, 16) for item in caller_row.bytes)
        except (TypeError, ValueError):
            caller_body = b""
        caller_target = (
            normalize_address(
                address_value(thunk_caller_address)
                + 5
                + struct.unpack_from("<i", caller_body, 1)[0]
            )
            if len(caller_body) == 5 and caller_body[0] == 0xE8
            else ""
        )
        caller_operand = _instruction_operand(caller_row).strip()
        if (
            _instruction_mnemonic(caller_row) != "call"
            or caller_target != address
            or (
                caller_operand != str(symbol.get("navigation_name", ""))
                and (
                    not ADDRESS_RE.fullmatch(caller_operand)
                    or normalize_address(caller_operand) != address
                )
            )
        ):
            raise ValueError(
                f"terminal ordinal thunk {symbol_id} caller is not one exact "
                "REL32 call to the governed thunk"
            )
        callable_symbol = package.object_symbol.removeprefix("__imp_")
        if (
            not callable_symbol
            or callable_symbol == package.object_symbol
            or (
                not _decorated_coff_name(callable_symbol)
                and re.fullmatch(
                    r"[A-Za-z_][A-Za-z0-9_@$?]*", callable_symbol
                )
                is None
            )
            or indexes.storage_by_address.get(package.address)
            != package.identity
            or indexes.storage_by_name.get(package.object_symbol)
            != package.identity
        ):
            raise ValueError(
                f"terminal ordinal thunk {symbol_id} lacks its exact callable/IAT package"
            )
        retail_name = symbol.get("navigation_name")
        ordinal_module = re.sub(r"(?i)\.dll$", "", package.import_dll).upper()
        ordinal_bn_alias = f"Ordinal_{ordinal_module}_{package.import_ordinal}"
        friendly = (
            _exact_bn_pe_import_friendly_symbol(
                bridge_by_address=bridge_by_address,
                bridge_by_name=bridge_by_name,
                address=address,
                retail_name=retail_name,
                immutable_import_name=ordinal_bn_alias,
            )
            if isinstance(retail_name, str) and retail_name
            else None
        )
        if friendly is None:
            raise ValueError(
                f"terminal ordinal thunk {symbol_id} lacks one exact BN alias"
            )
        thunk = ProviderOrdinalImportThunk(
            provider_identity=provider_identity,
            thunk_address=address,
            retail_name=str(retail_name),
            callable_symbol=callable_symbol,
            iat_object_symbol=package.object_symbol,
            iat_identity=package.identity,
            import_dll=package.import_dll,
            import_ordinal=int(package.import_ordinal),
        )
        proven.append(thunk)
        names.setdefault(str(retail_name), []).append(friendly)
    for attribute in (
        "provider_identity",
        "thunk_address",
        "retail_name",
        "callable_symbol",
        "iat_object_symbol",
        "iat_identity",
    ):
        values = [getattr(thunk, attribute) for thunk in proven]
        if len(values) != len(set(values)):
            raise ValueError(
                "terminal ordinal thunk discovery has duplicate or colliding "
                f"{attribute.replace('_', ' ')} values"
            )
    return tuple(proven), names


def _wol_config_reviewed_ordinal_noncall_relocation_offsets(
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    supplemental_candidate_direct_bridges: Mapping[str, str],
) -> dict[str, frozenset[int]]:
    """Prove config-dialog CString callback pointers beside direct calls."""

    if caller_identity != WOL_CONFIG_CEDIT_CALLER_TOKEN:
        return {}
    if (
        supplemental_candidate_direct_bridges.get(
            WOL_CONFIG_CEDIT_CANDIDATE_SYMBOL
        )
        != WOL_CEDIT_TARGET_IDENTITY
        or supplemental_candidate_direct_bridges.get(
            WOL_CCOMBOBOX_CANDIDATE_SYMBOL
        )
        != WOL_CEDIT_TARGET_IDENTITY
    ):
        return {}
    caller_spec = WOL_CATEGORY_A_CALLER_SPECS[WOL_CONFIG_CEDIT_CALLER_TOKEN]
    definition = candidate.caller_definition
    if (
        normalize_address(caller_start) != caller_spec["address"]
        or normalize_address(caller_end_exclusive)
        != caller_spec["end_exclusive"]
        or definition is None
        or definition.symbol != caller_spec["symbol"]
        or len(definition.data) != WOL_CONFIG_CEDIT_CANDIDATE_SIZE
        or len(definition.relocation_mask) != len(definition.data)
        or definition.section_start != 0
        or definition.section_end != WOL_CONFIG_CEDIT_CANDIDATE_SIZE
        or len(definition.relocations)
        != WOL_CONFIG_CEDIT_CANDIDATE_RELOCATION_COUNT
    ):
        raise ValueError(
            "WOL config CString callback proof requires the exact complete "
            "caller COFF package"
        )

    folded_symbol = WOL_CSTRING_CANDIDATE_SYMBOL.casefold()
    references = tuple(
        sorted(
            (
                relocation
                for relocation in definition.relocations
                if relocation.symbol_name.casefold() == folded_symbol
            ),
            key=lambda relocation: relocation.offset,
        )
    )
    expected_rows = tuple(
        (offset, IMAGE_REL_I386_REL32, WOL_CSTRING_CANDIDATE_SYMBOL)
        for offset in WOL_CONFIG_CSTRING_CALL_RELOCATION_OFFSETS
    ) + tuple(
        (offset, IMAGE_REL_I386_DIR32, WOL_CSTRING_CANDIDATE_SYMBOL)
        for offset in WOL_CONFIG_CSTRING_CALLBACK_RELOCATION_OFFSETS
    )
    observed_rows = tuple(
        (row.offset, row.type, row.symbol_name) for row in references
    )
    if observed_rows != tuple(sorted(expected_rows)):
        raise ValueError(
            "WOL config CString callback proof requires two exact REL32 calls "
            "and four exact case-sensitive DIR32 callback relocations"
        )
    for offset in WOL_CONFIG_CSTRING_CALLBACK_RELOCATION_OFFSETS:
        if (
            offset < 1
            or offset + 4 > len(definition.data)
            or definition.data[offset - 1] != 0x68
            or definition.relocation_mask[offset - 1]
            or struct.unpack_from("<I", definition.data, offset)[0] != 0
            or not all(
                definition.relocation_mask[index]
                for index in range(offset, offset + 4)
            )
        ):
            raise ValueError(
                "WOL config CString callback proof requires four exact "
                "zero-addend fully masked PUSH/DIR32 rows"
            )
    return {
        WOL_CSTRING_CANDIDATE_SYMBOL: frozenset(
            WOL_CONFIG_CSTRING_CALLBACK_RELOCATION_OFFSETS
        )
    }


def _directsoundcreate_ordinal1_candidate_bridge(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    retail_instructions: Sequence[Instruction],
    *,
    document: ProgressDocument,
    thunks: Sequence[ProviderOrdinalImportThunk],
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    retail_import_targets: Sequence[Any] | None = None,
) -> dict[str, str]:
    """Bridge the one DX6 decorated callable to retail DSOUND ordinal 1.

    Retail's import is ordinal-only, while the canonical DX6 header makes VC5
    emit the documented stdcall callable ``_DirectSoundCreate@12``.  This
    finite proof consumes the already-proven PE ordinal thunk and admits that
    one source-level spelling only in ``zSndBackend::InitDirectSound``.  It
    creates no tracker/provider/IAT fact and does not generalize ordinal
    aliases from decorations.
    """

    normalized_start = normalize_address(caller_start)
    caller_profile = DIRECTSOUND_CREATE_CALLER_PROFILES.get(normalized_start)
    if caller_profile is None:
        return {}

    normalized_end = normalize_address(caller_end_exclusive)
    exact_caller_identity = str(caller_profile["identity"])
    caller_symbol_id = exact_caller_identity.removeprefix("symbol:")
    caller_row = document.collection("symbols").get(caller_symbol_id)
    caller_trace = (
        caller_row.get("source_traceability")
        if isinstance(caller_row, Mapping)
        else None
    )
    source_edges = (
        caller_trace.get("source_edges")
        if isinstance(caller_trace, Mapping)
        else None
    )
    target = candidate.target
    caller = candidate.caller_definition
    contribution_rows = [
        (entry, row)
        for entry in getattr(target, "translation_unit_function_order", ())
        for row in getattr(entry, "functions", ())
        if normalize_address(str(getattr(row, "address", "")))
        == normalized_start
    ]
    if (
        caller_identity != exact_caller_identity
        or normalized_end != caller_profile["end_exclusive"]
        or indexes.by_address.get(normalized_start) != caller_identity
        or caller_identity in indexes.provider_ids
        or not isinstance(caller_row, Mapping)
        or caller_row.get("binary") != "recoil"
        or caller_row.get("kind") != "function"
        or caller_row.get("pipeline_class") != "authored"
        or caller_row.get("ownership_state") != "primary-owned"
        or caller_row.get("address") != normalized_start
        or caller_row.get("end_exclusive") != caller_profile["end_exclusive"]
        or caller_row.get("extent_state") != "known"
        or caller_row.get("size") != caller_profile["candidate_size"]
        or caller_row.get("navigation_name")
        != caller_profile["navigation_name"]
        or caller_row.get("output_section_id") != "recoil:section:.text"
        or caller_row.get("physical_block_id")
        != caller_profile["physical_block_id"]
        or not isinstance(caller_trace, Mapping)
        or caller_trace.get("state") != caller_profile["source_trace_state"]
        or caller_trace.get("reason_code")
        != caller_profile["source_trace_reason"]
        or not isinstance(source_edges, list)
        or source_edges != list(caller_profile["source_edges"])
        or caller is None
        or caller.symbol != caller_profile["symbol"]
        or caller.section_index != caller_profile["candidate_section_index"]
        or caller.section_start != 0
        or caller.section_end != caller_profile["candidate_size"]
        or len(caller.data) != caller_profile["candidate_size"]
        or len(caller.relocation_mask) != len(caller.data)
        or target is None
        or getattr(target, "name", "") != caller_profile["target_name"]
        or getattr(target, "target_binary", "") != "recoil"
        or Path(str(getattr(target, "manifest_path", ""))).resolve()
        != Path(caller_profile["target_manifest"]).resolve()
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
        or len(contribution_rows) != 1
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires the exact authored "
            "caller, source-trace state, target, TU contribution, and COFF "
            "candidate package"
        )
    contribution, contribution_row = contribution_rows[0]
    if (
        getattr(contribution, "source_from", "")
        != caller_profile["source_path"]
        or getattr(contribution, "order_scope", "") != "authored"
        or getattr(contribution_row, "symbol", "")
        != caller_profile["symbol"]
        or getattr(contribution_row, "symbol_regex", None) is not None
        or getattr(contribution_row, "name", "")
        != caller_profile["navigation_name"]
        or getattr(contribution_row, "pipeline_class", "") != "authored"
        or getattr(contribution_row, "authored_order_role", "")
        != "authored-body"
        or not bool(getattr(contribution_row, "required_presence", False))
        or not bool(getattr(contribution_row, "full_order_gate", False))
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires the exact authored "
            "caller contribution row"
        )

    provider_symbol = document.collection("symbols").get(
        ZSND_DIRECTSOUND_CREATE_PROVIDER_SYMBOL_ID
    )
    provider_block = document.collection("physical_blocks").get(
        ZSND_DIRECTSOUND_CREATE_PROVIDER_BLOCK_ID
    )
    mapping = (
        provider_block.get("mapping")
        if isinstance(provider_block, Mapping)
        else None
    )
    authored_order = (
        provider_block.get("order", {}).get("authored")
        if isinstance(provider_block, Mapping)
        and isinstance(provider_block.get("order"), Mapping)
        else None
    )
    current_not_applicable = (
        isinstance(authored_order, Mapping)
        and all(
            isinstance(authored_order.get(dimension), Mapping)
            and authored_order[dimension].get("result") == "not-applicable"
            and authored_order[dimension].get("disposition") == "accepted"
            and authored_order[dimension].get("freshness") == "current"
            and authored_order[dimension].get("gating") is True
            and authored_order[dimension].get("validation_mode") == "live"
            for dimension in AUTHORED_ORDER_DIMENSIONS
        )
    )
    primary_owner_rows = [
        owner_id
        for owner_id, owner in document.collection("owners").items()
        if isinstance(owner, Mapping)
        and any(
            isinstance(relationship, Mapping)
            and relationship.get("kind") == "primary-function"
            and relationship.get("symbol_id")
            == ZSND_DIRECTSOUND_CREATE_PROVIDER_SYMBOL_ID
            for relationship in owner.get("relationships", ())
        )
    ]
    if (
        not isinstance(provider_symbol, Mapping)
        or provider_symbol.get("binary") != "recoil"
        or provider_symbol.get("kind") != "function"
        or provider_symbol.get("pipeline_class") != "non-authored"
        or provider_symbol.get("authored_order_role") != "non-authored"
        or provider_symbol.get("ownership_state") != "unresolved"
        or provider_symbol.get("disposition") != "unresolved"
        or provider_symbol.get("extent_state") != "known"
        or provider_symbol.get("address")
        != ZSND_DIRECTSOUND_CREATE_THUNK_ADDRESS
        or provider_symbol.get("end_exclusive")
        != ZSND_DIRECTSOUND_CREATE_THUNK_END_EXCLUSIVE
        or provider_symbol.get("size") != 6
        or provider_symbol.get("navigation_name") != "DirectSoundCreate"
        or provider_symbol.get("output_section_id") != "recoil:section:.text"
        or provider_symbol.get("physical_block_id")
        != ZSND_DIRECTSOUND_CREATE_PROVIDER_BLOCK_ID
        or primary_owner_rows
        or not isinstance(provider_block, Mapping)
        or provider_block.get("binary") != "recoil"
        or provider_block.get("row_kind") != "physical-source-block"
        or provider_block.get("contribution_kind") != "provider"
        or provider_block.get("start") != "0x4c637c"
        or provider_block.get("end_exclusive") != "0x4c63f0"
        or provider_block.get("agent_source_path")
        != "provider:platform-directx-tail-import-thunks"
        or provider_block.get("source_path")
        != "provider:platform-directx-tail-import-thunks"
        or not isinstance(mapping, Mapping)
        or mapping.get("status") != "provider-boundary"
        or not current_not_applicable
        or not isinstance(provider_block.get("contribution_ids"), list)
        or provider_block["contribution_ids"].count(
            ZSND_DIRECTSOUND_CREATE_PROVIDER_SYMBOL_ID
        )
        != 1
        or indexes.by_address.get(ZSND_DIRECTSOUND_CREATE_THUNK_ADDRESS)
        != ZSND_DIRECTSOUND_CREATE_PROVIDER_IDENTITY
        or ZSND_DIRECTSOUND_CREATE_PROVIDER_IDENTITY
        not in indexes.provider_ids
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires the exact unowned "
            "six-byte provider symbol and current DirectX tail block"
        )

    matching_thunks = [
        thunk
        for thunk in thunks
        if thunk.provider_identity
        == ZSND_DIRECTSOUND_CREATE_PROVIDER_IDENTITY
        and thunk.thunk_address == ZSND_DIRECTSOUND_CREATE_THUNK_ADDRESS
        and thunk.retail_name == "DirectSoundCreate"
        and thunk.callable_symbol
        == ZSND_DIRECTSOUND_CREATE_RETAIL_CALLABLE_SYMBOL
        and thunk.iat_object_symbol
        == ZSND_DIRECTSOUND_CREATE_RETAIL_IAT_SYMBOL
        and thunk.iat_identity == "iat:ordinal:10:DSOUND.dll:1"
        and thunk.import_dll == ZSND_DIRECTSOUND_CREATE_IMPORT_DLL
        and thunk.import_ordinal == ZSND_DIRECTSOUND_CREATE_IMPORT_ORDINAL
    ]
    if len(matching_thunks) != 1:
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires one already-proven "
            "DSOUND.dll ordinal-1 retail thunk package"
        )
    if (
        indexes.storage_by_address.get(ZSND_DIRECTSOUND_CREATE_IAT_ADDRESS)
        != matching_thunks[0].iat_identity
        or indexes.storage_by_name.get(
            ZSND_DIRECTSOUND_CREATE_RETAIL_IAT_SYMBOL
        )
        != matching_thunks[0].iat_identity
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge lost its comparison-scoped "
            "immutable IAT identity"
        )

    supplied_targets = tuple(
        retail_import_targets
        if retail_import_targets is not None
        else _retail_import_targets(DEFAULT_REFERENCE)[0]
    )
    exact_imports = [
        item
        for item in supplied_targets
        if normalize_address(str(getattr(item, "address", "")))
        == ZSND_DIRECTSOUND_CREATE_IAT_ADDRESS
        and getattr(item, "dll", None) == ZSND_DIRECTSOUND_CREATE_IMPORT_DLL
        and getattr(item, "import_name", None) == "#1"
        and getattr(item, "import_ordinal", None)
        == ZSND_DIRECTSOUND_CREATE_IMPORT_ORDINAL
    ]
    tuple_collisions = [
        item
        for item in supplied_targets
        if getattr(item, "dll", None) == ZSND_DIRECTSOUND_CREATE_IMPORT_DLL
        and getattr(item, "import_ordinal", None)
        == ZSND_DIRECTSOUND_CREATE_IMPORT_ORDINAL
    ]
    address_collisions = [
        item
        for item in supplied_targets
        if normalize_address(str(getattr(item, "address", "")))
        == ZSND_DIRECTSOUND_CREATE_IAT_ADDRESS
    ]
    if (
        len(exact_imports) != 1
        or tuple_collisions != exact_imports
        or address_collisions != exact_imports
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires one collision-free "
            "immutable PE DSOUND.dll ordinal #1 tuple"
        )

    thunk_body = _hexdump_bytes(
        bridge.hexdump(ZSND_DIRECTSOUND_CREATE_THUNK_ADDRESS, 6)
    )
    get_json = getattr(bridge, "get_json", None)
    if thunk_body != ZSND_DIRECTSOUND_CREATE_THUNK_BODY or not callable(
        get_json
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires exact immutable "
            "FF25 thunk bytes and complete xref authority"
        )
    thunk_code, thunk_data, thunk_complete = _bn_inbound_xref_items(
        get_json(
            "getXrefsTo",
            address=ZSND_DIRECTSOUND_CREATE_THUNK_ADDRESS,
            limit=100000,
        )
    )
    iat_code, iat_data, iat_complete = _bn_inbound_xref_items(
        get_json(
            "getXrefsTo",
            address=ZSND_DIRECTSOUND_CREATE_IAT_ADDRESS,
            limit=100000,
        )
    )
    if (
        not thunk_complete
        or thunk_data
        or tuple(
            _bn_xref_address(
                row,
                "source_address",
                "source_addr",
                "from_address",
                "address",
            )
            for row in thunk_code
        )
        != (
            ZSND_DIRECTSOUND_CREATE_RETAIL_CALL_ADDRESS,
            ZSND_DIRECTSOUND_CREATE_OTHER_RETAIL_CALL_ADDRESS,
        )
        or not iat_complete
        or iat_data
        or tuple(
            _bn_xref_address(
                row,
                "source_address",
                "source_addr",
                "from_address",
                "address",
            )
            for row in iat_code
        )
        != (ZSND_DIRECTSOUND_CREATE_THUNK_ADDRESS,)
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires the exact ordered "
            "two-caller retail population and sole immutable IAT reader"
        )

    retail_matches = [
        instruction
        for instruction in retail_instructions
        if _source_instruction_address(instruction)
        == caller_profile["retail_call_address"]
    ]
    if len(retail_matches) != 1:
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires the exact unique "
            "retail call site"
        )
    try:
        retail_body = bytes(int(item, 16) for item in retail_matches[0].bytes)
    except (TypeError, ValueError):
        retail_body = b""
    if (
        _instruction_mnemonic(retail_matches[0]) != "call"
        or retail_body != caller_profile["retail_call_body"]
        or normalize_address(
            address_value(str(caller_profile["retail_call_address"]))
            + 5
            + struct.unpack_from("<i", retail_body, 1)[0]
        )
        != ZSND_DIRECTSOUND_CREATE_THUNK_ADDRESS
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires retail E8 to the "
            "exact DirectSoundCreate thunk"
        )

    expected_rows = [
        row
        for row in expected
        if row.get("target_identity")
        == ZSND_DIRECTSOUND_CREATE_PROVIDER_IDENTITY
    ]
    exact_expected = {
        "ordinal": int(caller_profile["expected_ordinal"]),
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "provider",
        "target_identity": ZSND_DIRECTSOUND_CREATE_PROVIDER_IDENTITY,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    if expected_rows != [exact_expected]:
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires the exact retail "
            "ordinal, direct-call form, provider identity, and stdcall cleanup"
        )

    casefolded_aliases = {
        str(name).casefold()
        for name in (
            *indexes.by_candidate_name,
            *indexes.storage_by_name,
            *bridge_names,
        )
    }
    if (
        ZSND_DIRECTSOUND_CREATE_CANDIDATE_SYMBOL.casefold()
        in casefolded_aliases
        or ZSND_DIRECTSOUND_CREATE_CANDIDATE_IAT_SYMBOL.casefold()
        in casefolded_aliases
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 candidate alias collides with an "
            "ordinary callable, storage, or BN bridge identity"
        )

    offsets = tuple(_candidate_complete_instruction_offsets(candidate))
    candidate_matches = [
        (index, offset, instruction)
        for index, (offset, instruction) in enumerate(
            zip(offsets, candidate.instructions)
        )
        if _instruction_mnemonic(instruction) in {"call", "jmp"}
        and _instruction_operand(instruction).strip()
        == ZSND_DIRECTSOUND_CREATE_CANDIDATE_SYMBOL
    ]
    candidate_case_collisions = [
        (index, offset, instruction)
        for index, (offset, instruction) in enumerate(
            zip(offsets, candidate.instructions)
        )
        if ZSND_DIRECTSOUND_CREATE_CANDIDATE_SYMBOL.casefold()
        in _instruction_operand(instruction).casefold()
    ]
    alias_relocations = tuple(
        relocation
        for relocation in caller.relocations
        if relocation.symbol_name.casefold()
        in {
            ZSND_DIRECTSOUND_CREATE_CANDIDATE_SYMBOL.casefold(),
            ZSND_DIRECTSOUND_CREATE_CANDIDATE_IAT_SYMBOL.casefold(),
        }
    )
    undefined_aliases = [
        name
        for name in (
            *caller.undefined_external_functions,
            *caller.undefined_external_data,
            *caller.defined_external_functions,
            *caller.defined_external_data,
        )
        if name.casefold()
        in {
            ZSND_DIRECTSOUND_CREATE_CANDIDATE_SYMBOL.casefold(),
            ZSND_DIRECTSOUND_CREATE_CANDIDATE_IAT_SYMBOL.casefold(),
        }
    ]
    exact_alias_relocation = (
        len(alias_relocations) == 1
        and alias_relocations[0].offset
        == caller_profile["candidate_relocation_offset"]
        and alias_relocations[0].type == IMAGE_REL_I386_REL32
        and alias_relocations[0].symbol_name
        == ZSND_DIRECTSOUND_CREATE_CANDIDATE_SYMBOL
    )
    if (
        len(candidate_matches) != 1
        or candidate_case_collisions != candidate_matches
        or candidate_matches[0][1]
        != caller_profile["candidate_call_offset"]
        or candidate_matches[0][0] in candidate.local_control_flow_indices
        or _cleanup_after(candidate.instructions, candidate_matches[0][0])
        is not None
        or tuple(candidate_matches[0][2].bytes)
        != ("e8", "00", "00", "00", "00")
        or not exact_alias_relocation
        or undefined_aliases
        != [ZSND_DIRECTSOUND_CREATE_CANDIDATE_SYMBOL]
        or caller.undefined_external_functions.count(
            ZSND_DIRECTSOUND_CREATE_CANDIDATE_SYMBOL
        )
        != 1
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires one exact direct "
            "candidate E8 and forbids aliases, IAT, mixed, duplicate, and "
            "caller-cleanup forms"
        )
    assert alias_relocations
    relocation = alias_relocations[0]
    field_end = relocation.offset + 4
    if (
        relocation.offset < 1
        or field_end > len(caller.data)
        or caller.data[relocation.offset - 1] != 0xE8
        or struct.unpack_from("<I", caller.data, relocation.offset)[0] != 0
        or not all(
            caller.relocation_mask[index]
            for index in range(relocation.offset, field_end)
        )
        or caller.relocation_mask[relocation.offset - 1]
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 bridge requires the exact zero-addend "
            "fully masked caller-scoped E8 REL32 field"
        )

    return {
        ZSND_DIRECTSOUND_CREATE_CANDIDATE_SYMBOL: (
            ZSND_DIRECTSOUND_CREATE_PROVIDER_IDENTITY
        )
    }


def _merge_directsoundcreate_ordinal1_final_bridges(
    compiler_generated_bridges: Mapping[str, str],
    directsoundcreate_ordinal1_bridges: Mapping[str, str],
) -> dict[str, str]:
    """Consume the finite DirectSound alias in the final extraction map."""

    exact = {
        ZSND_DIRECTSOUND_CREATE_CANDIDATE_SYMBOL: (
            ZSND_DIRECTSOUND_CREATE_PROVIDER_IDENTITY
        )
    }
    if directsoundcreate_ordinal1_bridges not in ({}, exact):
        raise ValueError(
            "DirectSoundCreate ordinal-1 final bridge received an unexpected "
            "or partially consumed finite alias map"
        )
    merged = dict(compiler_generated_bridges)
    collisions = merged.keys() & directsoundcreate_ordinal1_bridges.keys()
    if any(
        merged[name] != directsoundcreate_ordinal1_bridges[name]
        for name in collisions
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 final bridge conflicts with another "
            "reviewed compiler/provider identity"
        )
    merged.update(directsoundcreate_ordinal1_bridges)
    if any(
        merged.get(name) != identity
        for name, identity in directsoundcreate_ordinal1_bridges.items()
    ):
        raise ValueError(
            "DirectSoundCreate ordinal-1 final bridge was not consumed by "
            "the final candidate extraction map"
        )
    return merged


def _merge_player_ftol_expected_direct_bridges(
    compiler_generated_bridges: Mapping[str, str],
    expected_direct_identity_bridges: Mapping[str, str],
    *,
    caller_start: str,
    player_compiler_provider_bridges: Mapping[str, str],
    ftol_provider_bridges: Mapping[str, str],
) -> dict[str, str]:
    """Prefer the exact Player provider identity over ``iat:_ftol``.

    The generic ``__ftol`` candidate proof deliberately publishes the IAT
    storage identity used to reach the CRT provider.  Two current Player
    callers also have a complete caller-local OBJ/COD proof that every
    ``__ftol`` occurrence is the immutable retail provider identity, including
    sites whose retail ordinal contains a later authored call.  Admit that
    stronger classification only when both proof producers are complete and
    agree on this exact finite boundary.  No invocation row is projected,
    removed, reordered, or otherwise changed here.
    """

    merged = dict(compiler_generated_bridges)
    conflicts = merged.keys() & expected_direct_identity_bridges.keys()
    identity_conflicts = {
        name
        for name in conflicts
        if merged[name] != expected_direct_identity_bridges[name]
    }
    if identity_conflicts:
        exact_player_ftol_conflict = (
            normalize_address(caller_start) in {"0x426770", "0x429870"}
            and identity_conflicts == {MSVC_FTOL_CANDIDATE_SYMBOL}
            and player_compiler_provider_bridges
            == {
                MSVC_FTOL_CANDIDATE_SYMBOL:
                MSVC_FTOL_PROVIDER_IDENTITY,
            }
            and ftol_provider_bridges
            == {
                MSVC_FTOL_CANDIDATE_SYMBOL:
                MSVC_FTOL_IAT_STORAGE_IDENTITY,
            }
            and merged.get(MSVC_FTOL_CANDIDATE_SYMBOL)
            == MSVC_FTOL_IAT_STORAGE_IDENTITY
            and expected_direct_identity_bridges.get(
                MSVC_FTOL_CANDIDATE_SYMBOL
            ) == MSVC_FTOL_PROVIDER_IDENTITY
        )
        if not exact_player_ftol_conflict:
            raise ValueError(
                "expected authored direct candidate bridge conflicts with "
                "another reviewed compiler/provider bridge"
            )
        del merged[MSVC_FTOL_CANDIDATE_SYMBOL]
    merged.update(expected_direct_identity_bridges)
    return merged


def _zgameopt_renderer_count_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    retail_instructions: Sequence[Instruction],
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge: BinaryNinjaBridge,
) -> list[dict[str, Any]]:
    """Consume one exact retail renderer-count jump-thunk projection.

    Retail ``HasAcceptedHardwareRenderer`` calls the compiler-generated body
    at ``0x4a7470``.  That body is one exact relative jump to the authored
    cached getter at ``0x4a9910``; the current VC5 object calls the latter
    symbol directly.  The projection is finite to this caller, both governed
    target rows, the immutable retail bodies, and one exact candidate COFF
    relocation.  It does not classify other jump thunks or authored targets.
    """

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != ZGAMEOPT_RENDERER_CALLER_START:
        return result

    caller_row = document.collection("symbols").get(
        ZGAMEOPT_RENDERER_CALLER_IDENTITY.removeprefix("symbol:")
    )
    provider_row = document.collection("symbols").get(
        ZGAMEOPT_RENDERER_PROVIDER_TARGET_ID
    )
    cached_row = document.collection("symbols").get(
        ZGAMEOPT_RENDERER_CANDIDATE_TARGET_ID
    )
    source_trace = (
        caller_row.get("source_traceability")
        if isinstance(caller_row, Mapping)
        else None
    )
    definition = candidate.caller_definition
    exact_expected = {
        "ordinal": 0,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "provider",
        "target_identity": ZGAMEOPT_RENDERER_PROVIDER_TARGET_IDENTITY,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    exact_candidate = {
        **exact_expected,
        "identity_kind": "direct",
        "target_identity": ZGAMEOPT_RENDERER_CANDIDATE_TARGET_IDENTITY,
    }
    offsets = tuple(_candidate_complete_instruction_offsets(candidate))
    candidate_calls = [
        (index, int(offset), instruction)
        for index, (offset, instruction) in enumerate(
            zip(offsets, candidate.instructions)
        )
        if offset is not None
        and _instruction_mnemonic(instruction) in {"call", "jmp"}
        and ZGAMEOPT_RENDERER_CANDIDATE_SYMBOL.casefold()
        in _instruction_operand(instruction).casefold()
    ]
    relocations = (
        ()
        if definition is None
        else tuple(
            relocation
            for relocation in definition.relocations
            if relocation.symbol_name.casefold()
            == ZGAMEOPT_RENDERER_CANDIDATE_SYMBOL.casefold()
        )
    )
    retail_calls = [
        instruction
        for instruction in retail_instructions
        if _source_instruction_address(instruction)
        == ZGAMEOPT_RENDERER_CALLER_START
    ]
    try:
        retail_call_body = bytes(
            int(value, 16) for value in retail_calls[0].bytes
        )
    except (IndexError, TypeError, ValueError):
        retail_call_body = b""
    provider_body = _hexdump_bytes(
        bridge.hexdump(ZGAMEOPT_RENDERER_PROVIDER_TARGET_ID.removeprefix(
            "recoil:function:"
        ), len(ZGAMEOPT_RENDERER_PROVIDER_THUNK_BODY))
    )
    cached_body = _hexdump_bytes(
        bridge.hexdump(ZGAMEOPT_RENDERER_CANDIDATE_TARGET_ID.removeprefix(
            "recoil:function:"
        ), len(ZGAMEOPT_RENDERER_CACHED_GETTER_BODY))
    )
    provider_jump_target = (
        address_value("0x4a7470")
        + 5
        + struct.unpack_from("<i", provider_body, 1)[0]
        if len(provider_body) >= 5 and provider_body[0] == 0xE9
        else -1
    )
    retail_call_target = (
        address_value(ZGAMEOPT_RENDERER_CALLER_START)
        + 5
        + struct.unpack_from("<i", retail_call_body, 1)[0]
        if len(retail_call_body) == 5 and retail_call_body[0] == 0xE8
        else -1
    )
    if (
        caller_identity != ZGAMEOPT_RENDERER_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != ZGAMEOPT_RENDERER_CALLER_END_EXCLUSIVE
        or [dict(row) for row in expected] != [exact_expected]
        or result != [exact_candidate]
        or not isinstance(caller_row, Mapping)
        or caller_row.get("binary") != "recoil"
        or caller_row.get("kind") != "function"
        or caller_row.get("pipeline_class") != "authored"
        or caller_row.get("ownership_state") != "primary-owned"
        or caller_row.get("address") != ZGAMEOPT_RENDERER_CALLER_START
        or caller_row.get("end_exclusive")
        != ZGAMEOPT_RENDERER_CALLER_END_EXCLUSIVE
        or caller_row.get("extent_state") != "known"
        or caller_row.get("size") != 0x10
        or caller_row.get("navigation_name")
        != "zVid::HasAcceptedHardwareRenderer"
        or caller_row.get("physical_block_id") != "recoil:block:0x4b31f0"
        or not isinstance(source_trace, Mapping)
        or source_trace.get("state") != "unresolved"
        or source_trace.get("reason_code") != "multiple-legacy-occurrences"
        or source_trace.get("source_edges") != []
        or tuple(caller_row.get("verification_target_ids", ()))
        != (
            "recoil:functional-target:zvid_has_accepted_hardware_renderer",
            "recoil:vc5-target:zgame_opt_4b2960_4b33f0_authored_order",
            (
                "recoil:vc5-target:"
                "zvid_accepted_hardware_renderer_count_cached"
            ),
        )
        or not isinstance(provider_row, Mapping)
        or provider_row.get("binary") != "recoil"
        or provider_row.get("kind") != "function"
        or provider_row.get("pipeline_class") != "non-authored"
        or provider_row.get("authored_order_role")
        != "compiler-generated-thunk"
        or provider_row.get("ownership_state") != "unresolved"
        or provider_row.get("disposition") != "unresolved"
        or provider_row.get("address") != "0x4a7470"
        or provider_row.get("end_exclusive") != "0x4a7480"
        or provider_row.get("extent_state") != "known"
        or provider_row.get("size") != 0x10
        or provider_row.get("navigation_name")
        != "zVid::GetAcceptedHardwareRendererCountThunk"
        or provider_row.get("physical_block_id") != "recoil:block:0x4a6b40"
        or provider_row.get("output_section_id") != "recoil:section:.text"
        or not isinstance(cached_row, Mapping)
        or cached_row.get("binary") != "recoil"
        or cached_row.get("kind") != "function"
        or cached_row.get("pipeline_class") != "authored"
        or cached_row.get("ownership_state") != "primary-owned"
        or cached_row.get("address") != "0x4a9910"
        or cached_row.get("end_exclusive") != "0x4a9920"
        or cached_row.get("extent_state") != "known"
        or cached_row.get("size") != 0x10
        or cached_row.get("navigation_name")
        != "zVid::GetAcceptedHardwareRendererCount_Cached"
        or cached_row.get("physical_block_id") != "recoil:block:0x4a7b40"
        or cached_row.get("output_section_id") != "recoil:section:.text"
        or indexes.by_address.get("0x4b3220") != caller_identity
        or indexes.by_address.get("0x4a7470")
        != ZGAMEOPT_RENDERER_PROVIDER_TARGET_IDENTITY
        or ZGAMEOPT_RENDERER_PROVIDER_TARGET_IDENTITY
        not in indexes.provider_ids
        or indexes.by_address.get("0x4a9910")
        != ZGAMEOPT_RENDERER_CANDIDATE_TARGET_IDENTITY
        or ZGAMEOPT_RENDERER_CANDIDATE_TARGET_IDENTITY in indexes.provider_ids
        or len(retail_calls) != 1
        or _instruction_mnemonic(retail_calls[0]) != "call"
        or retail_call_body != ZGAMEOPT_RENDERER_RETAIL_CALL_BODY
        or retail_call_target != address_value("0x4a7470")
        or provider_body != ZGAMEOPT_RENDERER_PROVIDER_THUNK_BODY
        or provider_jump_target != address_value("0x4a9910")
        or cached_body != ZGAMEOPT_RENDERER_CACHED_GETTER_BODY
        or definition is None
        or definition.symbol != ZGAMEOPT_RENDERER_CALLER_SYMBOL
        or definition.section_index != 28
        or definition.section_start != 0
        or definition.section_end != 0x10
        or len(definition.data) != 0x10
        or len(definition.relocation_mask) != 0x10
        or definition.data
        != bytes.fromhex(
            "e8 00 00 00 00 33 c9 85 c0 0f 9f c1 8b c1 c3 90"
        )
        or tuple(definition.relocation_mask)
        != (False, True, True, True, True) + (False,) * 11
        or len(relocations) != 1
        or relocations[0].offset != 1
        or relocations[0].type != IMAGE_REL_I386_REL32
        or relocations[0].symbol_name != ZGAMEOPT_RENDERER_CANDIDATE_SYMBOL
        or definition.undefined_external_functions.count(
            ZGAMEOPT_RENDERER_CANDIDATE_SYMBOL
        )
        != 1
        or ZGAMEOPT_RENDERER_CANDIDATE_SYMBOL
        in definition.defined_external_functions
        or len(candidate_calls) != 1
        or candidate_calls[0][1] != 0
        or candidate_calls[0][0] in candidate.local_control_flow_indices
        or _instruction_mnemonic(candidate_calls[0][2]) != "call"
        or _instruction_operand(candidate_calls[0][2]).strip()
        != ZGAMEOPT_RENDERER_CANDIDATE_SYMBOL
        or tuple(candidate_calls[0][2].bytes)
        != ("e8", "00", "00", "00", "00")
    ):
        raise CandidateCallContractEvidenceError(
            "zGameOpt renderer-count thunk projection rejects caller, retail "
            "jump relation, tracker identities, or candidate COFF drift"
        )
    return [dict(exact_expected)]


def _czrecoilframe_reviewed_ordinal_shift(
    *,
    callable_symbol: str,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    provider_identity: str,
    instruction_offsets: Sequence[str],
    candidate_rows: Sequence[Mapping[str, Any]],
    expected_rows: Sequence[Mapping[str, Any]],
) -> bool:
    """Recognize the finite ordinal effects of one reviewed body reshape."""

    specs = {
        "?FromHandle@CMenu@@SGPAV1@PAUHMENU__@@@Z": (
            "provider:recoil:function:0x4c5e04",
            ("0x1b4", "0x1d9", "0x210"),
            (21, 24, 28),
            (21, 24, 27),
        ),
        "??0CString@@QAE@XZ": (
            "provider:recoil:function:0x4c5ba0",
            ("0x240",),
            (30,),
            (29,),
        ),
        "?Format@CString@@QAAXPBDZZ": (
            "provider:recoil:function:0x4c5bca",
            ("0x260",),
            (32,),
            (31,),
        ),
        "?SetWindowTextA@CWnd@@QAEXPBD@Z": (
            "provider:recoil:function:0x4c5c84",
            ("0x278",),
            (34,),
            (33,),
        ),
        "??1CString@@QAE@XZ": (
            "provider:recoil:function:0x4c5b88",
            ("0xb3", "0x26c", "0x281"),
            (7, 33, 35),
            (7, 32, 43),
        ),
        "?CenterWindow@CWnd@@QAEXPAV1@@Z": (
            "provider:recoil:function:0x4c5dfe",
            ("0x350",),
            (42,),
            (40,),
        ),
    }
    spec = specs.get(callable_symbol)
    return bool(
        caller_identity == "symbol:recoil:function:0x430250"
        and normalize_address(caller_start) == "0x430250"
        and normalize_address(caller_end_exclusive) == "0x4305f0"
        and spec is not None
        and provider_identity == spec[0]
        and tuple(instruction_offsets) == spec[1]
        and tuple(row.get("ordinal") for row in candidate_rows) == spec[2]
        and tuple(row.get("ordinal") for row in expected_rows) == spec[3]
        and len(candidate_rows) == len(expected_rows)
        and all(
            {
                key: value
                for key, value in candidate_row.items()
                if key != "ordinal"
            }
            == {
                key: value
                for key, value in expected_row.items()
                if key != "ordinal"
            }
            for candidate_row, expected_row in zip(
                candidate_rows, expected_rows
            )
        )
    )


def _mission_reviewed_ordinal_profile(
    *,
    callable_symbol: str,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    provider_identity: str,
    instruction_offsets: Sequence[str],
    candidate_rows: Sequence[Mapping[str, Any]],
    expected_rows: Sequence[Mapping[str, Any]],
) -> bool:
    """Recognize one complete Mission provider-call population reshape."""

    profiles = {
        "?SetWindowTextA@CWnd@@QAEXPBD@Z": (
            "provider:recoil:function:0x4c5c84",
            ("0x17c", "0x194", "0x1f2", "0x204"),
            (15, 17, 23, 25),
            (16, 18, 22, 24),
        ),
        "?EnableWindow@CWnd@@QAEHH@Z": (
            "provider:recoil:function:0x4c5c8a",
            ("0x10a", "0x117", "0x16a", "0x19d", "0x1dc"),
            (8, 9, 13, 18, 21),
            (8, 9, 14, 20, 25),
        ),
    }
    profile = profiles.get(callable_symbol)
    return bool(
        profile is not None
        and caller_identity == "symbol:recoil:function:0x41b2f0"
        and normalize_address(caller_start) == "0x41b2f0"
        and normalize_address(caller_end_exclusive) == "0x41b510"
        and provider_identity == profile[0]
        and tuple(instruction_offsets) == profile[1]
        and tuple(row.get("ordinal") for row in candidate_rows)
        == profile[2]
        and tuple(row.get("ordinal") for row in expected_rows)
        == profile[3]
        and len(candidate_rows) == len(expected_rows) == len(profile[1])
        and all(
            {
                key: value
                for key, value in candidate_row.items()
                if key != "ordinal"
            }
            == {
                key: value
                for key, value in expected_row.items()
                if key != "ordinal"
            }
            for candidate_row, expected_row in zip(
                candidate_rows, expected_rows
            )
        )
    )


def _player_reviewed_cstring_ordinal_profile(
    *,
    callable_symbol: str,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    provider_identity: str,
    instruction_offsets: Sequence[str],
    candidate_rows: Sequence[Mapping[str, Any]],
    expected_rows: Sequence[Mapping[str, Any]],
) -> bool:
    """Recognize exact CString dtor ordinals after finite Player inlining."""

    profiles = {
        (
            "symbol:recoil:function:0x420c60",
            "0x420c60",
            "0x420d10",
            "??1CString@@QAE@XZ",
        ): (
            "provider:recoil:function:0x4c5b88",
            ("0x9f",),
            (7,),
            (6,),
        ),
        (
            "symbol:recoil:function:0x425060",
            "0x425060",
            "0x425150",
            "??1CString@@QAE@XZ",
        ): (
            "provider:recoil:function:0x4c5b88",
            ("0x95", "0xa6", "0xce", "0xdf"),
            (6, 7, 8, 9),
            (3, 4, 5, 6),
        ),
        (
            "symbol:recoil:function:0x425060",
            "0x425060",
            "0x425150",
            "?Right@CString@@QBE?AV1@H@Z",
        ): (
            "provider:recoil:function:0x4c5cd8",
            ("0x60",),
            (2,),
            (1,),
        ),
    }
    profile = profiles.get((
        caller_identity,
        normalize_address(caller_start),
        normalize_address(caller_end_exclusive),
        callable_symbol,
    ))
    return bool(
        profile is not None
        and provider_identity == profile[0]
        and tuple(instruction_offsets) == profile[1]
        and tuple(row.get("ordinal") for row in candidate_rows)
        == profile[2]
        and tuple(row.get("ordinal") for row in expected_rows)
        == profile[3]
        and len(candidate_rows) == len(expected_rows) == len(profile[1])
        and all(
            {
                key: value
                for key, value in candidate_row.items()
                if key != "ordinal"
            }
            == {
                key: value
                for key, value in expected_row.items()
                if key != "ordinal"
            }
            for candidate_row, expected_row in zip(
                candidate_rows, expected_rows
            )
        )
    )


def _provider_ordinal_import_thunk_candidate_bridges(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    thunks: Sequence[ProviderOrdinalImportThunk],
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    reviewed_candidate_direct_bridges: Mapping[str, str] | None = None,
    reviewed_register_storage_bridges: Mapping[str, str] | None = None,
    reviewed_static_storage_reference_bridges: Mapping[
        str, ReviewedStaticStorageReferenceBridge
    ] | None = None,
    reviewed_member_vptr_storage_bridges: Mapping[
        str, ReviewedMemberVptrStorageBridge
    ] | None = None,
    candidate_exact_iat_register_load_proofs: Mapping[
        str, CandidateExactIatRegisterLoadProof
    ] | None = None,
    reviewed_noncall_relocation_offsets: Mapping[
        str, frozenset[int]
    ] | None = None,
) -> dict[str, str]:
    mission_provider_selection = {
        (
            "symbol:recoil:function:0x41ca10",
            "0x41ca10",
            "0x41ca30",
            "??1CString@@QAE@XZ",
        ): "provider:recoil:function:0x4c5ec0",
    }
    active: dict[str, tuple[ProviderOrdinalImportThunk, list[Instruction]]] = {}
    for thunk in thunks:
        selected_provider = mission_provider_selection.get(
            (
                caller_identity,
                normalize_address(caller_start),
                normalize_address(caller_end_exclusive),
                thunk.callable_symbol,
            )
        )
        if (
            selected_provider is not None
            and thunk.provider_identity != selected_provider
        ):
            continue
        matching: list[Instruction] = []
        for instruction in candidate.instructions:
            if _instruction_mnemonic(instruction) not in {"call", "jmp"}:
                continue
            operand = _instruction_operand(instruction).strip()
            if operand == thunk.callable_symbol:
                matching.append(instruction)
                continue
            if (
                operand.casefold() == thunk.callable_symbol.casefold()
                or thunk.callable_symbol in operand
                or thunk.iat_object_symbol in operand
            ):
                raise ValueError(
                    "ordinal import thunk bridge accepts only the exact direct "
                    f"callable operand {thunk.callable_symbol!r}"
                )
        if matching:
            active[thunk.callable_symbol] = (thunk, matching)
    if not active:
        return {}

    noncall_offsets = dict(reviewed_noncall_relocation_offsets or {})
    if set(noncall_offsets) - set(active):
        raise ValueError(
            "ordinal import thunk bridge rejects noncall relocation proof "
            "for an inactive callable"
        )

    definition = candidate.caller_definition
    compiler_bridges = dict(reviewed_candidate_direct_bridges or {})
    ordinal_bridges = {
        callable_symbol: thunk.provider_identity
        for callable_symbol, (thunk, _matching) in active.items()
    }
    bridge_collisions = compiler_bridges.keys() & ordinal_bridges.keys()
    if bridge_collisions:
        raise ValueError(
            "ordinal import thunk bridge collides with another reviewed "
            "candidate direct identity: "
            + ", ".join(repr(name) for name in sorted(bridge_collisions))
        )
    compiler_bridges.update(ordinal_bridges)
    for callable_symbol, (thunk, _matching) in active.items():
        callable_bridge_rows = tuple(bridge_names.get(callable_symbol, ()))
        callable_bridge_population_is_exact = (
            len(callable_bridge_rows) == 1
            and all(
                getattr(row, "address", "") == thunk.thunk_address
                and getattr(row, "name", "") == callable_symbol
                and getattr(row, "raw_name", "") == callable_symbol
                and getattr(row, "kind", "") == "import"
                for row in callable_bridge_rows
            )
        )
        if (
            definition is None
            or indexes.by_address.get(thunk.thunk_address)
            != thunk.provider_identity
            or thunk.provider_identity not in indexes.provider_ids
            or indexes.storage_by_name.get(thunk.iat_object_symbol)
            != thunk.iat_identity
            or callable_symbol == thunk.iat_object_symbol
            or indexes.by_candidate_name.get(callable_symbol, "")
            not in {"", thunk.provider_identity}
            or indexes.storage_by_name.get(callable_symbol, "")
            or (
                callable_symbol in bridge_names
                and not callable_bridge_population_is_exact
            )
        ):
            raise ValueError(
                "ordinal import thunk bridge lacks an exact collision-free "
                "governed callable/package identity"
            )
        case_collisions = [
            name
            for name in definition.undefined_external_functions
            if name.casefold() == callable_symbol.casefold()
        ]
        if (
            definition.undefined_external_functions.count(callable_symbol) != 1
            or case_collisions != [callable_symbol]
            or thunk.iat_object_symbol
            in definition.undefined_external_functions
        ):
            raise ValueError(
                "ordinal import thunk bridge requires exactly one undefined "
                f"external function {callable_symbol!r}; defined, nonfunction, "
                "duplicate, aliased, case-folded, and direct-IAT forms are forbidden"
            )

    provisional = extract_invocation_contract(
        candidate.instructions,
        source="cod",
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
        indexes=indexes,
        bridge_names=bridge_names,
        compiler_generated_bridges=compiler_bridges,
        reviewed_register_storage_bridges=(
            reviewed_register_storage_bridges
        ),
        reviewed_static_storage_reference_bridges=(
            reviewed_static_storage_reference_bridges
        ),
        reviewed_member_vptr_storage_bridges=(
            reviewed_member_vptr_storage_bridges
        ),
        reviewed_iat_register_definition_offsets=frozenset(
            candidate_exact_iat_register_load_proofs or {}
        ),
        candidate_exact_iat_register_load_proofs=(
            candidate_exact_iat_register_load_proofs
        ),
        local_control_flow_indices=candidate.local_control_flow_indices,
        local_control_flow_targets=candidate.local_control_flow_targets,
    )
    # The exact current Player zInput artifact has one candidate-only leading
    # vector::size call. Apply the same complete artifact-backed projection
    # here, before ordinal-import rows are compared, so the CString provider
    # call is judged at semantic ordinal 2 rather than physical candidate
    # ordinal 3. The ordinary post-extraction projection remains the final
    # complete-contract gate and no other caller is changed.
    provisional = _player_zinput_vector_size_candidate_projection(
        expected,
        provisional,
        candidate,
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
    )
    for callable_symbol, (thunk, matching_instructions) in active.items():
        candidate_rows = [
            row
            for row in provisional
            if row.get("target_identity") == thunk.provider_identity
        ]
        expected_rows = [
            row
            for row in expected
            if row.get("target_identity") == thunk.provider_identity
        ]
        symbol_references = tuple(
            sorted(
                (
                    relocation
                    for relocation in definition.relocations
                    if relocation.symbol_name == callable_symbol
                ),
                key=lambda relocation: relocation.offset,
            )
        )
        try:
            definition_start, definition_end = (
                _candidate_caller_definition_interval(definition)
            )
        except CandidateCallContractEvidenceError as exc:
            raise ValueError(
                "ordinal import thunk bridge requires one exact selected "
                "caller definition interval"
            ) from exc
        boundary_overlaps = tuple(
            relocation
            for relocation in symbol_references
            if (
                relocation.offset < definition_end
                and relocation.offset + relocation_size(relocation.type)
                > definition_start
                and not (
                    definition_start <= relocation.offset
                    and relocation.offset + relocation_size(relocation.type)
                    <= definition_end
                )
            )
        )
        if boundary_overlaps:
            raise ValueError(
                "ordinal import thunk bridge rejects a relocation that "
                "overlaps the selected caller definition boundary"
            )
        all_references = tuple(
            relocation
            for relocation in symbol_references
            if (
                definition_start <= relocation.offset
                and relocation.offset + relocation_size(relocation.type)
                <= definition_end
            )
        )
        allowed_noncall_offsets = noncall_offsets.get(
            callable_symbol, frozenset()
        )
        allowed_noncall_rows = tuple(
            reference
            for reference in all_references
            if reference.offset in allowed_noncall_offsets
        )
        if (
            {reference.offset for reference in allowed_noncall_rows}
            != set(allowed_noncall_offsets)
            or any(
                reference.type != IMAGE_REL_I386_DIR32
                for reference in allowed_noncall_rows
            )
        ):
            raise ValueError(
                "ordinal import thunk bridge noncall relocation proof does "
                "not match exact DIR32 rows"
            )
        references = tuple(
            reference
            for reference in all_references
            if reference.offset not in allowed_noncall_offsets
        )
        population = len(matching_instructions)
        expected_reference_offsets = tuple(
            _candidate_instruction_section_offset(
                instruction,
                definition,
            )
            + 1
            for instruction in matching_instructions
        )
        if (
            population < 1
            or len(candidate_rows) != population
            or len(expected_rows) != population
            or len(references) != population
            or len(set(expected_reference_offsets)) != population
            or tuple(reference.offset for reference in references)
            != tuple(sorted(expected_reference_offsets))
        ):
            raise ValueError(
                "ordinal import thunk bridge requires equal nonempty retail, "
                "candidate instruction, candidate row, and COFF relocation "
                "populations: "
                f"callable={callable_symbol!r}, provider={thunk.provider_identity!r}, "
                f"caller={caller_identity!r}, start={normalize_address(caller_start)!r}, "
                f"end={normalize_address(caller_end_exclusive)!r}, "
                f"instructions={population}, candidate_rows={len(candidate_rows)}, "
                f"retail_rows={len(expected_rows)}, relocations={len(references)}, "
                f"retail_contract={list(expected)!r}"
            )
        reference_by_offset = {
            reference.offset: reference for reference in references
        }
        instruction_by_field = {
            _candidate_instruction_section_offset(instruction, definition) + 1:
            instruction
            for instruction in matching_instructions
        }
        for field_offset in expected_reference_offsets:
            reference = reference_by_offset[field_offset]
            instruction = instruction_by_field[field_offset]
            relative = field_offset - definition_start
            opcode = 0xE8 if _instruction_mnemonic(instruction) == "call" else 0xE9
            if (
                reference.type != IMAGE_REL_I386_REL32
                or reference.symbol_name != callable_symbol
                or relative <= 0
                or relative + 4 > len(definition.data)
                or definition.data[relative - 1] != opcode
                or struct.unpack_from("<I", definition.data, relative)[0] != 0
                or definition.relocation_mask[relative - 1]
                or not all(
                    definition.relocation_mask[index]
                    for index in range(relative, relative + 4)
                )
            ):
                raise ValueError(
                    "ordinal import thunk bridge requires one exact site-bound "
                    "zero-addend E8/E9 REL32 relocation per decoded invocation"
                )
        czrecoilframe_cstring_shift = _czrecoilframe_reviewed_ordinal_shift(
            callable_symbol=callable_symbol,
            caller_identity=caller_identity,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
            provider_identity=thunk.provider_identity,
            instruction_offsets=tuple(
                _source_instruction_address(instruction)
                for instruction in matching_instructions
            ),
            candidate_rows=candidate_rows,
            expected_rows=expected_rows,
        )
        mission_ordinal_profile = _mission_reviewed_ordinal_profile(
            callable_symbol=callable_symbol,
            caller_identity=caller_identity,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
            provider_identity=thunk.provider_identity,
            instruction_offsets=tuple(
                _source_instruction_address(instruction)
                for instruction in matching_instructions
            ),
            candidate_rows=candidate_rows,
            expected_rows=expected_rows,
        )
        player_cstring_ordinal_profile = (
            _player_reviewed_cstring_ordinal_profile(
                callable_symbol=callable_symbol,
                caller_identity=caller_identity,
                caller_start=caller_start,
                caller_end_exclusive=caller_end_exclusive,
                provider_identity=thunk.provider_identity,
                instruction_offsets=tuple(
                    _source_instruction_address(instruction)
                    for instruction in matching_instructions
                ),
                candidate_rows=candidate_rows,
                expected_rows=expected_rows,
            )
        )
        if (
            czrecoilframe_cstring_shift
            or mission_ordinal_profile
            or player_cstring_ordinal_profile
        ):
            expected_rows = candidate_rows
        if candidate_rows != expected_rows:
            raise ValueError(
                "ordinal import thunk bridge has ordinal, direct call/tail form, "
                "or cleanup drift from retail: "
                f"callable={callable_symbol!r}, caller={caller_identity!r}, "
                f"start={normalize_address(caller_start)!r}, "
                f"end={normalize_address(caller_end_exclusive)!r}, "
                f"candidate={candidate_rows!r}, expected={expected_rows!r}"
            )

        relocation_fields: dict[int, int] = {}
        for instruction, row in zip(matching_instructions, candidate_rows):
            raw_offset = _source_instruction_address(instruction)
            mnemonic = _instruction_mnemonic(instruction)
            expected_form = "call" if mnemonic == "call" else "tail"
            opcode = 0xE8 if mnemonic == "call" else 0xE9
            if (
                not raw_offset
                or row.get("form") != expected_form
                or row.get("dispatch") != "direct"
                or tuple(instruction.bytes[:1]) != (f"{opcode:02x}",)
            ):
                raise ValueError(
                    "ordinal import thunk bridge requires exact offset-bearing "
                    "direct E8 CALL or E9 tail-JMP instructions"
                )
            relocation_offset = (
                _candidate_instruction_section_offset(
                    instruction,
                    definition,
                )
                + 1
            )
            if relocation_offset in relocation_fields:
                raise ValueError(
                    "ordinal import thunk bridge candidate instruction offsets "
                    "are not unique"
                )
            relocation_fields[relocation_offset] = opcode
        if {reference.offset for reference in references} != set(
            relocation_fields
        ):
            raise ValueError(
                "ordinal import thunk bridge COFF relocations are not one-to-one "
                "with exact candidate instruction offsets"
            )
        for reference in references:
            opcode = relocation_fields[reference.offset]
            relative = reference.offset - definition_start
            field_end = relative + 4
            if (
                reference.type != IMAGE_REL_I386_REL32
                or relative < 1
                or field_end > len(definition.data)
                or field_end > len(definition.relocation_mask)
                or definition.data[
                    relative - 1 : relative
                ]
                != bytes((opcode,))
                or struct.unpack_from(
                    "<I",
                    definition.data,
                    relative,
                )[0]
                != 0
                or not all(
                    definition.relocation_mask[index]
                    for index in range(relative, field_end)
                )
            ):
                raise ValueError(
                    "ordinal import thunk bridge requires exact zero-addend "
                    "fully masked E8/E9 REL32 relocations"
                )
        if any(
            row.get("identity_kind") != "provider"
            or row.get("target_identity") != thunk.provider_identity
            or row.get("storage_identity") != ""
            or row.get("slot_displacement") is not None
            for row in candidate_rows
        ):
            raise ValueError(
                "ordinal import thunk candidate rows are not exact direct "
                "provider invocations"
            )
    return ordinal_bridges


