def _czgameframe_onpaint_ordinal_bridge_expected(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    thunks: Sequence[ProviderOrdinalImportThunk],
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge: BinaryNinjaBridge,
) -> list[dict[str, Any]]:
    """Expose only OnPaint's four exact non-inlined candidate helpers.

    Retail inlines three CDC::GetSafeHdc calls and one
    CGdiObject::GetSafeHandle call.  The governed /Ob0 candidate emits those
    canonical candidate-local COMDATs, shifting CPaintDC::~CPaintDC from retail
    ordinal 7 to candidate ordinal 11.  This finite pre-extraction view lets
    the unchanged ordinal-import producer validate both CPaintDC calls; the
    OnPaint-local projection later consumes the four helper rows before the
    unchanged generic provider-COMDAT arbitration step.
    """

    result = [dict(row) for row in expected]
    if normalize_address(caller_start) != _CZGAMEFRAME_ONPAINT_CALLER_START:
        return result
    label = "CZGameFrame OnPaint CPaintDC ordinal projection"
    definition = candidate.caller_definition
    target = candidate.target
    try:
        _profile, compile_flags = effective_source_compile_context(
            target, _CZGAMEFRAME_DESTRUCTOR_SOURCE
        )
        compiler_root = compiler_env_path(target, DEFAULT_VC5_ENV).resolve().parent
    except (AttributeError, OSError, TypeError, ValueError) as exc:
        raise ValueError(f"{label} requires the exact governed target") from exc
    upper_flags = tuple(str(flag).upper() for flag in compile_flags)
    if (
        caller_identity != _CZGAMEFRAME_ONPAINT_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != _CZGAMEFRAME_ONPAINT_CALLER_END_EXCLUSIVE
        or target is None
        or getattr(target, "name", "") != _CZGAMEFRAME_DESTRUCTOR_TARGET_NAME
        or getattr(target, "source_from", "") != _CZGAMEFRAME_DESTRUCTOR_SOURCE
        or getattr(target, "source_filename", "") != "CZGameFrame.cpp"
        or tuple(getattr(target, "source_files", ())) != ()
        or [flag for flag in upper_flags if flag in {"/OD", "/O1", "/O2", "/OX"}]
        != ["/O2"]
        or [flag for flag in upper_flags if flag in {"/OB0", "/OB1", "/OB2"}]
        != ["/OB0"]
        or "/TP" not in upper_flags
        or "/FACS" not in upper_flags
        or definition is None
        or definition.symbol != _CZGAMEFRAME_ONPAINT_SYMBOL
        or definition.section_start != 0
        or definition.section_end != 0x110
        or len(definition.data) != 0x110
        or len(definition.relocation_mask) != 0x110
    ):
        raise ValueError(f"{label} rejects caller, extent, target, TU, source, or compile drift")

    exact_provider_rows = {
        0: (_CZGAMEFRAME_ONPAINT_CTOR_IDENTITY, None),
        7: (_CZGAMEFRAME_ONPAINT_DTOR_IDENTITY, None),
    }
    if len(result) != 8 or any(row.get("ordinal") != i for i, row in enumerate(result)):
        raise ValueError(f"{label} requires the complete eight-row retail population")
    for ordinal, (identity, cleanup) in exact_provider_rows.items():
        if dict(result[ordinal]) != {
            "ordinal": ordinal,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "provider",
            "target_identity": identity,
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": cleanup,
        }:
            raise ValueError(f"{label} rejects CPaintDC retail row {ordinal}")

    expected_calls = (
        (0x23, ("e8", "00", "00", "00", "00"), 36, 0x14, _CZGAMEFRAME_ONPAINT_CTOR_SYMBOL, None),
        (0x33, ("e8", "00", "00", "00", "00"), 52, 0x14, "?QueryCachedClientRectUpdateMaskIf3dfx@zVid@@YAHXZ", None),
        (0x55, ("e8", "00", "00", "00", "00"), 86, 0x14, _CZGAMEFRAME_ONPAINT_HDC_SYMBOL, None),
        (0x5B, ("ff", "15", "00", "00", "00", "00"), 93, 0x06, "__imp__CreateCompatibleDC@4", "iat:CreateCompatibleDC"),
        (0x69, ("e8", "00", "00", "00", "00"), 106, 0x14, _CZGAMEFRAME_ONPAINT_HANDLE_SYMBOL, None),
        (0x70, ("ff", "15", "00", "00", "00", "00"), 114, 0x06, "__imp__SelectObject@8", "iat:SelectObject"),
        (0xAB, ("e8", "00", "00", "00", "00"), 172, 0x14, _CZGAMEFRAME_ONPAINT_HDC_SYMBOL, None),
        (0xB1, ("ff", "15", "00", "00", "00", "00"), 179, 0x06, "__imp__StretchBlt@44", "iat:StretchBlt"),
        (0xCE, ("e8", "00", "00", "00", "00"), 207, 0x14, _CZGAMEFRAME_ONPAINT_HDC_SYMBOL, None),
        (0xD4, ("ff", "15", "00", "00", "00", "00"), 214, 0x06, "__imp__BitBlt@36", "iat:BitBlt"),
        (0xDB, ("ff", "15", "00", "00", "00", "00"), 221, 0x06, "__imp__DeleteDC@4", "iat:DeleteDC"),
        (0xF2, ("e8", "00", "00", "00", "00"), 243, 0x14, _CZGAMEFRAME_ONPAINT_DTOR_SYMBOL, None),
    )
    actual_calls = tuple(
        row for row in candidate.instructions if _instruction_mnemonic(row) == "call"
    )
    if len(actual_calls) != len(expected_calls):
        raise ValueError(f"{label} rejects missing or extra candidate callsites")
    for instruction, (offset, body, relocation_offset, relocation_type,
                      symbol_name, iat_identity) in zip(actual_calls, expected_calls):
        matching_relocations = [
            row for row in definition.relocations
            if row.offset == relocation_offset
            and row.type == relocation_type
            and row.symbol_name == symbol_name
        ]
        source_address = (
            address_value(_source_instruction_address(instruction))
            if _source_instruction_address(instruction)
            else None
        )
        actual_body = tuple(item.lower() for item in instruction.bytes)
        actual_address = source_address
        if (
            actual_address is None
            and actual_body[:2] == ("ff", "15")
            and len(matching_relocations) == 1
        ):
            actual_address = matching_relocations[0].offset - 2
        iat_lookup_key = (
            _candidate_iat_import_name(symbol_name)
            if iat_identity is not None
            else ""
        )
        actual_iat_identity = (
            indexes.storage_by_name.get(iat_lookup_key)
            if iat_lookup_key
            else None
        )
        if (
            actual_address != offset
            or actual_body != body
            or len(matching_relocations) != 1
            or (iat_identity is not None and actual_iat_identity != iat_identity)
        ):
            raise ValueError(
                f"{label} rejects exact callsite offset, E8/FF15 form, COFF "
                "relocation, symbol, or IAT storage semantics at "
                f"{offset:#x}: address={actual_address!r}, bytes={actual_body!r}, "
                f"relocations={len(matching_relocations)}, "
                f"storage_key={iat_lookup_key!r}, storage={actual_iat_identity!r}, "
                f"expected_storage={iat_identity!r}"
            )

    exact_candidate = bytes.fromhex(
        "6a ff 68 00 00 00 00 64 a1 00 00 00 00 50 64 89 25 00 00 00 00 81 ec 94 00 00 00 53 8b d9 53 8d 4c 24 48 e8 00 00 00 00 c7 84 24 a0 00 00 00 00 00 00 00 e8 00 00 00 00 85 c0 0f 85 a3 00 00 00 57 56 b9 10 00 00 00 8d 74 24 60 8d 7c 24 0c f3 a5 8d 4c 24 4c e8 00 00 00 00 50 ff 15 00 00 00 00 8d 8b c4 00 00 00 8b f0 e8 00 00 00 00 50 56 ff 15 00 00 00 00 8b 44 24 20 8b 4c 24 18 2b c1 68 20 00 cc 00 3d e0 01 00 00 7e 2d 8b 54 24 18 68 e0 01 00 00 68 80 02 00 00 51 52 56 50 8b 44 24 38 2b c2 50 51 52 8d 4c 24 74 e8 00 00 00 00 50 ff 15 00 00 00 00 eb 21 8b 54 24 18 51 52 56 50 8b 44 24 30 2b c2 50 51 52 8d 4c 24 6c e8 00 00 00 00 50 ff 15 00 00 00 00 56 ff 15 00 00 00 00 5e 5f 8d 4c 24 44 c7 84 24 a0 00 00 00 ff ff ff ff e8 00 00 00 00 8b 8c 24 98 00 00 00 5b 64 89 0d 00 00 00 00 81 c4 a0 00 00 00 c3 90 90 90"
    )
    relocation_specs = (
        (3, 0x06, None), (9, 0x06, "__except_list"),
        (17, 0x06, "__except_list"), (36, 0x14, _CZGAMEFRAME_ONPAINT_CTOR_SYMBOL),
        (52, 0x14, "?QueryCachedClientRectUpdateMaskIf3dfx@zVid@@YAHXZ"),
        (86, 0x14, _CZGAMEFRAME_ONPAINT_HDC_SYMBOL),
        (93, 0x06, "__imp__CreateCompatibleDC@4"),
        (106, 0x14, _CZGAMEFRAME_ONPAINT_HANDLE_SYMBOL),
        (114, 0x06, "__imp__SelectObject@8"),
        (172, 0x14, _CZGAMEFRAME_ONPAINT_HDC_SYMBOL),
        (179, 0x06, "__imp__StretchBlt@44"),
        (207, 0x14, _CZGAMEFRAME_ONPAINT_HDC_SYMBOL),
        (214, 0x06, "__imp__BitBlt@36"), (221, 0x06, "__imp__DeleteDC@4"),
        (243, 0x14, _CZGAMEFRAME_ONPAINT_DTOR_SYMBOL),
        (258, 0x06, "__except_list"),
    )
    expected_mask = {i for offset, _kind, _name in relocation_specs for i in range(offset, offset + 4)}
    if (
        definition.data != exact_candidate
        or len(definition.relocations) != len(relocation_specs)
        or {i for i, value in enumerate(definition.relocation_mask) if value} != expected_mask
        or any(len([
            row for row in definition.relocations
            if row.offset == offset and row.type == kind and (
                row.symbol_name == name if name is not None
                else re.fullmatch(r"\$L\d+", row.symbol_name) is not None
            )
        ]) != 1 for offset, kind, name in relocation_specs)
    ):
        raise ValueError(f"{label} rejects complete caller body, relocation, addend, or mask drift")

    caller_symbols = [
        row
        for row in definition.coff_symbols
        if row.name == _CZGAMEFRAME_ONPAINT_SYMBOL
    ]
    symbol_by_index = {row.index: row for row in definition.coff_symbols}
    name_counts = Counter(row.name for row in definition.coff_symbols)
    associated_by_name = {
        row.name: row for row in definition.associated_sections
    }
    if (
        len(caller_symbols) != 1
        or len(symbol_by_index) != len(definition.coff_symbols)
        or len(associated_by_name) != len(definition.associated_sections)
        or definition.section_index != caller_symbols[0].section_number
        or caller_symbols[0].value != 0
        or caller_symbols[0].section_size != 0x110
        or caller_symbols[0].natural_end != 0x110
        or not (
            caller_symbols[0].section_characteristics & IMAGE_SCN_LNK_COMDAT
        )
        or set(associated_by_name) != {".text$x", ".xdata$x", ".debug$F"}
        or any(
            row.association_section_index != definition.section_index
            or not row.section_is_comdat
            or row.comdat_selection != 5
            for row in definition.associated_sections
        )
    ):
        raise ValueError(
            f"{label} rejects caller COMDAT or associative-section population"
        )

    eh_text = associated_by_name[".text$x"]
    xdata = associated_by_name[".xdata$x"]
    debug_f = associated_by_name[".debug$F"]
    eh_symbols = [
        row
        for row in definition.coff_symbols
        if row.section_number == eh_text.section_index
        and row.symbol_type == 0
        and row.storage_class == 6
        and row.aux_count == 0
    ]
    caller_eh_relocations = [
        row
        for row in definition.relocations
        if row.offset == 3 and row.type == IMAGE_REL_I386_DIR32
    ]
    handler = (
        symbol_by_index.get(caller_eh_relocations[0].symbol_index)
        if len(caller_eh_relocations) == 1
        else None
    )
    handler_relocation = (
        caller_eh_relocations[0]
        if len(caller_eh_relocations) == 1
        else None
    )
    cleanup_rows = [row for row in eh_symbols if row.value == 0]
    handler_rows = [row for row in eh_symbols if row.value == 8]
    cleanup = cleanup_rows[0] if len(cleanup_rows) == 1 else None
    if (
        len(eh_symbols) != 2
        or cleanup is None
        or len(handler_rows) != 1
        or handler is not handler_rows[0]
        or handler_relocation is None
        or handler_relocation.symbol_name != handler.name
        or any(re.fullmatch(r"\$L\d+", row.name) is None for row in eh_symbols)
        or any(name_counts[row.name] != 1 for row in eh_symbols)
        or eh_text.section_size != 18
        or eh_text.data
        != bytes.fromhex(
            "8d 4d a0 e9 00 00 00 00 b8 00 00 00 00 e9 00 00 00 00"
        )
        or eh_text.relocation_mask
        != (False,) * 4
        + (True,) * 4
        + (False,)
        + (True,) * 4
        + (False,)
        + (True,) * 4
        or eh_text.section_external_symbols
        or len(eh_text.symbols) != 2
        or {
            (row.name, row.value, row.section_number, row.type, row.storage_class)
            for row in eh_text.symbols
        }
        != {
            (row.name, row.value, row.section_number, row.symbol_type, row.storage_class)
            for row in eh_symbols
        }
    ):
        raise ValueError(
            f"{label} rejects caller relocation or structural EH entry population"
        )

    def one_associated_relocation(
        section: CandidateAssociatedSection,
        offset: int,
        relocation_type: int,
    ) -> CoffRelocation | None:
        matches = [
            row
            for row in section.relocations
            if row.offset == offset and row.type == relocation_type
        ]
        return matches[0] if len(matches) == 1 else None

    cleanup_to_dtor = one_associated_relocation(
        eh_text, 4, IMAGE_REL_I386_REL32
    )
    handler_to_xdata = one_associated_relocation(
        eh_text, 9, IMAGE_REL_I386_DIR32
    )
    handler_to_frame_handler = one_associated_relocation(
        eh_text, 14, IMAGE_REL_I386_REL32
    )
    if (
        len(eh_text.relocations) != 3
        or cleanup_to_dtor is None
        or cleanup_to_dtor.symbol_name != _CZGAMEFRAME_ONPAINT_DTOR_SYMBOL
        or handler_to_xdata is None
        or handler_to_frame_handler is None
        or handler_to_frame_handler.symbol_name != "___CxxFrameHandler"
    ):
        raise ValueError(
            f"{label} rejects cleanup-to-destructor or handler dispatch paths"
        )

    xdata_symbols = [
        row
        for row in definition.coff_symbols
        if row.section_number == xdata.section_index
        and row.symbol_type == 0
        and row.storage_class == IMAGE_SYM_CLASS_STATIC
        and row.aux_count == 0
    ]
    xdata_root = symbol_by_index.get(handler_to_xdata.symbol_index)
    xdata_next = one_associated_relocation(
        xdata, 8, IMAGE_REL_I386_DIR32
    )
    xdata_cleanup = one_associated_relocation(
        xdata, 36, IMAGE_REL_I386_DIR32
    )
    xdata_next_symbol = (
        symbol_by_index.get(xdata_next.symbol_index)
        if xdata_next is not None
        else None
    )
    if (
        len(xdata_symbols) != 2
        or {row.value for row in xdata_symbols} != {0, 32}
        or any(
            re.fullmatch(r"\$T\d+", row.name) is None
            or name_counts[row.name] != 1
            for row in xdata_symbols
        )
        or xdata_root not in xdata_symbols
        or xdata_root is None
        or xdata_root.value != 0
        or handler_to_xdata.symbol_name != xdata_root.name
        or xdata_next_symbol not in xdata_symbols
        or xdata_next_symbol is None
        or xdata_next_symbol.value != 32
        or xdata_next is None
        or xdata_next.symbol_name != xdata_next_symbol.name
        or xdata_cleanup is None
        or xdata_cleanup.symbol_index != cleanup.index
        or xdata_cleanup.symbol_name != cleanup.name
        or xdata.section_size != 40
        or xdata.data
        != bytes.fromhex(
            "20 05 93 19 01 00 00 00 00 00 00 00 00 00 00 00 "
            "00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 00 "
            "ff ff ff ff 00 00 00 00"
        )
        or xdata.relocation_mask
        != (False,) * 8
        + (True,) * 4
        + (False,) * 24
        + (True,) * 4
        or len(xdata.relocations) != 2
        or xdata.section_external_symbols
        or len(xdata.symbols) != 2
    ):
        raise ValueError(
            f"{label} rejects exact handler xdata or cleanup backlink topology"
        )

    debug_relocation = one_associated_relocation(
        debug_f, 0, IMAGE_REL_I386_DIR32NB
    )
    if (
        debug_f.section_size != 16
        or debug_f.data
        != bytes.fromhex(
            "00 00 00 00 0d 01 00 00 28 00 00 00 00 00 00 03"
        )
        or debug_f.relocation_mask != (True,) * 4 + (False,) * 12
        or len(debug_f.relocations) != 1
        or debug_relocation is None
        or debug_relocation.symbol_index != caller_symbols[0].index
        or debug_relocation.symbol_name != caller_symbols[0].name
        or debug_f.section_external_symbols
        or debug_f.symbols
    ):
        raise ValueError(
            f"{label} rejects caller-associated debug population or collision"
        )

    helper_specs = {
        _CZGAMEFRAME_ONPAINT_HDC_SYMBOL: _CZGAMEFRAME_ONPAINT_HDC_IDENTITY,
        _CZGAMEFRAME_ONPAINT_HANDLE_SYMBOL: _CZGAMEFRAME_ONPAINT_HANDLE_IDENTITY,
    }
    helper_reference_specs = (
        (86, IMAGE_REL_I386_REL32, _CZGAMEFRAME_ONPAINT_HDC_SYMBOL),
        (106, IMAGE_REL_I386_REL32, _CZGAMEFRAME_ONPAINT_HANDLE_SYMBOL),
        (172, IMAGE_REL_I386_REL32, _CZGAMEFRAME_ONPAINT_HDC_SYMBOL),
        (207, IMAGE_REL_I386_REL32, _CZGAMEFRAME_ONPAINT_HDC_SYMBOL),
    )
    actual_helper_references = tuple(
        (row.offset, row.type, row.symbol_name)
        for row in definition.relocations
        if row.symbol_name in helper_specs
    )
    if actual_helper_references != helper_reference_specs:
        raise ValueError(
            f"{label} rejects the exact four caller REL32 helper references"
        )
    if any(
        address in indexes.by_address
        for address in _CZGAMEFRAME_ONPAINT_FALSE_HELPER_ADDRESSES
    ):
        raise ValueError(
            f"{label} rejects false tracker identities inside the retail "
            "CBitmap destructor extent"
        )
    helper_body = bytes.fromhex(
        "85 c9 75 03 33 c0 c3 8b 41 04 c3 90 90 90 90 90"
    )
    helper_sections: dict[str, int] = {}
    for symbol_name, identity in helper_specs.items():
        helper = candidate.tu_local_function_definitions.get(symbol_name)
        symbols = [row for row in definition.coff_symbols if row.name == symbol_name]
        coff_symbol = symbols[0] if len(symbols) == 1 else None
        same_section_externals = (
            tuple(
                row.name
                for row in definition.coff_symbols
                if row.section_number == coff_symbol.section_number
                and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
            )
            if coff_symbol is not None
            else ()
        )
        if (
            helper is None or len(symbols) != 1 or helper.data != helper_body
            or helper.relocations
            or helper.relocation_mask != (False,) * 0x10
            or helper.section_size != 0x10
            or helper.section_external_functions != (symbol_name,)
            or helper.section_is_comdat is not True or helper.comdat_selection != 2
            or helper.local_control_flow_indices
            or helper.local_control_flow_targets
            or Path(helper.source_provenance).resolve()
            != (compiler_root / "VC" / "MFC" / "INCLUDE" / "afxwin1.inl").resolve()
            or definition.defined_external_functions.count(symbol_name) != 1
            or definition.undefined_external_functions.count(symbol_name) != 0
            or coff_symbol is None
            or coff_symbol.section_number <= 0
            or coff_symbol.value != 0
            or coff_symbol.symbol_type != 0x20
            or coff_symbol.storage_class != IMAGE_SYM_CLASS_EXTERNAL
            or coff_symbol.aux_count != 0
            or coff_symbol.weak_external_tag_index is not None
            or coff_symbol.weak_external_characteristics is not None
            or coff_symbol.section_size != 0x10
            or coff_symbol.natural_end != 0x10
            or not (coff_symbol.section_characteristics & IMAGE_SCN_LNK_COMDAT)
            or same_section_externals != (symbol_name,)
        ):
            raise ValueError(
                f"{label} rejects canonical candidate-local helper package "
                f"for {symbol_name!r}"
            )
        if (
            identity in indexes.provider_ids
            or identity in indexes.by_address.values()
            or identity in indexes.by_candidate_name.values()
            or symbol_name in indexes.by_candidate_name
        ):
            raise ValueError(
                f"{label} rejects tracker/provider collision for candidate-local "
                f"helper {symbol_name!r}"
            )
        assert coff_symbol is not None
        helper_sections[symbol_name] = coff_symbol.section_number
    if len(set(helper_sections.values())) != len(helper_specs):
        raise ValueError(f"{label} rejects coincident helper definitions")

    thunk_specs = {
        _CZGAMEFRAME_ONPAINT_CTOR_SYMBOL: (_CZGAMEFRAME_ONPAINT_CTOR_IDENTITY, "0x4c5e94", 470),
        _CZGAMEFRAME_ONPAINT_DTOR_SYMBOL: (_CZGAMEFRAME_ONPAINT_DTOR_IDENTITY, "0x4c5e8e", 755),
    }
    for symbol_name, (identity, address, ordinal) in thunk_specs.items():
        matches = [row for row in thunks if row.callable_symbol == symbol_name]
        iat_identity = f"iat:ordinal:9:MFC42.DLL:{ordinal}"
        if len(matches) != 1:
            raise ValueError(f"{label} requires one CPaintDC ordinal thunk for {symbol_name!r}")
        thunk = matches[0]
        if (
            thunk.provider_identity != identity or thunk.thunk_address != address
            or thunk.retail_name != symbol_name or thunk.iat_object_symbol != f"__imp_{symbol_name}"
            or thunk.iat_identity != iat_identity or thunk.import_dll.upper() != "MFC42.DLL"
            or thunk.import_ordinal != ordinal or indexes.by_address.get(address) != identity
            or identity not in indexes.provider_ids
            or indexes.storage_by_name.get(thunk.iat_object_symbol) != iat_identity
        ):
            raise ValueError(f"{label} rejects CPaintDC provider/thunk/IAT package")

    exact_retail = bytes.fromhex(
        "6a ff 68 28 ad 4c 00 64 a1 00 00 00 00 50 64 89 25 00 00 00 00 81 ec 94 00 00 00 53 8b d9 53 8d 4c 24 48 e8 6c 25 08 00 c7 84 24 a0 00 00 00 00 00 00 00 e8 78 20 06 00 85 c0 0f 85 b6 00 00 00 57 56 b9 10 00 00 00 8d 74 24 60 8d 7c 24 0c 8d 44 24 4c f3 a5 8b 74 24 50 f7 d8 1b c0 23 c6 50 ff 15 a4 c0 4c 00 8b f0 8d 83 c4 00 00 00 85 c0 74 03 8b 40 04 50 56 ff 15 6c c0 4c 00 8b 54 24 20 8b 4c 24 18 2b d1 8d 44 24 4c 81 fa e0 01 00 00 7e 33 8b 7c 24 50 68 20 00 cc 00 f7 d8 1b c0 68 e0 01 00 00 23 c7 8b 7c 24 1c 68 80 02 00 00 51 57 56 52 8b 54 24 38 2b d7 52 51 57 50 ff 15 a8 c0 4c 00 eb 27 8b 7c 24 50 68 20 00 cc 00 f7 d8 1b c0 51 23 c7 8b 7c 24 1c 57 56 52 8b 54 24 30 2b d7 52 51 57 50 ff 15 64 c0 4c 00 56 ff 15 8c c0 4c 00 5e 5f 8d 4c 24 44 c7 84 24 a0 00 00 00 ff ff ff ff e8 84 24 08 00 8b 8c 24 98 00 00 00 5b 64 89 0d 00 00 00 00 81 c4 a0 00 00 00 c3"
    )
    if _hexdump_bytes(bridge.hexdump("0x443900", 0x120)) != exact_retail:
        raise ValueError(f"{label} rejects immutable retail extent/body/receiver/argument/cleanup facts")

    helper_row = lambda ordinal, identity: {
        "ordinal": ordinal, "form": "call", "dispatch": "direct",
        "identity_kind": "direct", "target_identity": identity,
        "storage_identity": "", "slot_displacement": None, "cleanup_bytes": None,
    }
    expanded: list[dict[str, Any]] = []
    helper_at = {2: _CZGAMEFRAME_ONPAINT_HDC_IDENTITY, 4: _CZGAMEFRAME_ONPAINT_HANDLE_IDENTITY,
                 6: _CZGAMEFRAME_ONPAINT_HDC_IDENTITY, 8: _CZGAMEFRAME_ONPAINT_HDC_IDENTITY}
    retail_index = 0
    for ordinal in range(12):
        identity = helper_at.get(ordinal)
        if identity is not None:
            expanded.append(helper_row(ordinal, identity))
        else:
            expanded.append({**result[retail_index], "ordinal": ordinal})
            retail_index += 1
    if retail_index != len(result):
        raise ValueError(f"{label} rejects unused retail population")
    return expanded


def _apply_czgameframe_onpaint_local_helper_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    projected_expected: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    """Consume only the four exact OnPaint candidate-local helper rows."""

    retail = tuple(dict(row) for row in expected)
    projected = tuple(dict(row) for row in projected_expected)
    candidate = tuple(dict(row) for row in candidate_contract)
    if projected == retail:
        return list(candidate)
    label = "CZGameFrame OnPaint local-helper projection"
    helper_ordinals = (2, 4, 6, 8)
    helper_identities = (
        _CZGAMEFRAME_ONPAINT_HDC_IDENTITY,
        _CZGAMEFRAME_ONPAINT_HANDLE_IDENTITY,
        _CZGAMEFRAME_ONPAINT_HDC_IDENTITY,
        _CZGAMEFRAME_ONPAINT_HDC_IDENTITY,
    )
    if (
        len(retail) != 8
        or len(projected) != 12
        or candidate != projected
        or tuple(projected[index].get("ordinal") for index in helper_ordinals)
        != helper_ordinals
        or tuple(
            projected[index].get("identity_kind") for index in helper_ordinals
        )
        != ("direct",) * 4
        or tuple(
            projected[index].get("target_identity") for index in helper_ordinals
        )
        != helper_identities
        or any(projected[index].get("storage_identity") for index in helper_ordinals)
    ):
        raise ValueError(
            f"{label} rejects ordinal, identity-kind, storage, collision, or "
            "unused candidate population"
        )
    compacted = tuple(
        {**row, "ordinal": ordinal}
        for ordinal, row in enumerate(
            row
            for index, row in enumerate(candidate)
            if index not in helper_ordinals
        )
    )
    if compacted != retail:
        raise ValueError(
            f"{label} rejects shifted, missing, extra, or colliding retail rows"
        )
    return list(compacted)


@dataclass(frozen=True)
class CZGameFrameInlineDestructorProjection:
    provider_expected: tuple[Mapping[str, Any], ...]
    candidate_resolved_expected: tuple[Mapping[str, Any], ...]
    retail_expected: tuple[Mapping[str, Any], ...]


def _czgameframe_inline_destructor_projection_proof(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    retail_instructions: Sequence[Instruction],
    *,
    thunks: Sequence[ProviderOrdinalImportThunk],
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge: BinaryNinjaBridge,
) -> CZGameFrameInlineDestructorProjection | None:
    """Prove one exact /Ob0 CBitmap-dtor to retail-inline projection.

    The source-faithful embedded CBitmap is automatically destroyed.  VC5
    emits one local CBitmap destructor call, while retail inlines its canonical
    CBitmap/CGdiObject/CObject chain and therefore exposes DeleteObject at the
    same ordinal.  This package is finite to the reviewed caller and is later
    consumed once to replace only candidate ordinal one.
    """

    if normalize_address(caller_start) != _CZGAMEFRAME_DESTRUCTOR_CALLER_START:
        return None
    label = "CZGameFrame inline-destructor projection"
    target = candidate.target
    definition = candidate.caller_definition
    try:
        _profile, compile_flags = effective_source_compile_context(
            target, _CZGAMEFRAME_DESTRUCTOR_SOURCE
        )
        compiler_root = compiler_env_path(
            target, DEFAULT_VC5_ENV
        ).resolve().parent
    except (AttributeError, OSError, TypeError, ValueError) as exc:
        raise ValueError(f"{label} requires the exact governed target") from exc
    upper_flags = tuple(str(flag).upper() for flag in compile_flags)
    if (
        caller_identity != _CZGAMEFRAME_DESTRUCTOR_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != _CZGAMEFRAME_DESTRUCTOR_CALLER_END_EXCLUSIVE
        or target is None
        or getattr(target, "name", "")
        != _CZGAMEFRAME_DESTRUCTOR_TARGET_NAME
        or getattr(target, "source_from", "")
        != _CZGAMEFRAME_DESTRUCTOR_SOURCE
        or getattr(target, "source_filename", "") != "CZGameFrame.cpp"
        or tuple(getattr(target, "source_files", ())) != ()
        or [flag for flag in upper_flags if flag in {"/OD", "/O1", "/O2", "/OX"}]
        != ["/O2"]
        or [flag for flag in upper_flags if flag in {"/OB0", "/OB1", "/OB2"}]
        != ["/OB0"]
        or "/TP" not in upper_flags
        or "/FACS" not in upper_flags
        or definition is None
        or definition.symbol != _CZGAMEFRAME_DESTRUCTOR_SYMBOL
        or definition.section_start != 0
        or definition.section_end != len(definition.data)
        or len(definition.data) != 0x60
        or len(definition.relocation_mask) != len(definition.data)
    ):
        raise ValueError(
            f"{label} requires the exact reviewed caller, 0x60 extent, target, "
            "TU, source, compile mode, and complete COFF definition"
        )

    exact_expected_delete = {
        "ordinal": 1,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "provider",
        "target_identity": _CZGAMEFRAME_DELETE_OBJECT_PROVIDER_IDENTITY,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    exact_expected_cframewnd = {
        "ordinal": 2,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "provider",
        "target_identity": (
            _CZGAMEFRAME_CFRAMEWND_DESTRUCTOR_PROVIDER_IDENTITY
        ),
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    if (
        len(expected) != 3
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(expected))
        or dict(expected[1]) != exact_expected_delete
        or dict(expected[2]) != exact_expected_cframewnd
    ):
        raise ValueError(
            f"{label} requires exact retail DeleteObject ordinal 1 and "
            "CFrameWnd destructor ordinal 2 provider rows"
        )

    invocation_rows = tuple(
        (
            ordinal,
            address_value(_source_instruction_address(instruction)),
            _instruction_operand(instruction).strip(),
            tuple(item.lower() for item in instruction.bytes),
        )
        for ordinal, instruction in enumerate(
            instruction
            for instruction in candidate.instructions
            if _instruction_mnemonic(instruction) in {"call", "jmp"}
        )
        if _source_instruction_address(instruction)
    )
    expected_invocations = tuple(
        (ordinal, instruction_offset, symbol)
        for ordinal, instruction_offset, _relocation_offset, symbol
        in _CZGAMEFRAME_DESTRUCTOR_CALL_SPECS
    )
    if (
        len(invocation_rows) != len(expected_invocations)
        or tuple(row[:3] for row in invocation_rows) != expected_invocations
        or any(row[3] != ("e8", "00", "00", "00", "00")
               for row in invocation_rows)
    ):
        raise ValueError(
            f"{label} requires three exact offset-bearing E8 COD calls with "
            "natural CBitmap destructor ordinal 1"
        )

    expected_caller_data = bytes.fromhex(
        "6a ff 68 00 00 00 00 64 a1 00 00 00 00 50 64 89 "
        "25 00 00 00 00 51 56 8b f1 89 74 24 04 c7 06 00 "
        "00 00 00 c7 44 24 10 01 00 00 00 e8 00 00 00 00 "
        "8d 8e c4 00 00 00 c6 44 24 10 00 e8 00 00 00 00 "
        "8b ce c7 44 24 10 ff ff ff ff e8 00 00 00 00 8b "
        "4c 24 08 5e 64 89 0d 00 00 00 00 83 c4 10 c3 90"
    )
    expected_relocations = (
        (3, IMAGE_REL_I386_DIR32, None),
        (9, IMAGE_REL_I386_DIR32, "__except_list"),
        (17, IMAGE_REL_I386_DIR32, "__except_list"),
        (31, IMAGE_REL_I386_DIR32, "??_7CZGameFrame@@6B@"),
        (44, IMAGE_REL_I386_REL32, _CZGAMEFRAME_RETURN_SUCCESS_SYMBOL),
        (60, IMAGE_REL_I386_REL32, _CZGAMEFRAME_CBITMAP_DESTRUCTOR_SYMBOL),
        (75, IMAGE_REL_I386_REL32, _CZGAMEFRAME_CFRAMEWND_DESTRUCTOR_SYMBOL),
        (87, IMAGE_REL_I386_DIR32, "__except_list"),
    )
    expected_mask = {
        index
        for offset, _kind, _symbol in expected_relocations
        for index in range(offset, offset + 4)
    }
    actual_relocations = tuple(
        (row.offset, row.type, row.symbol_name, row.symbol_index)
        for row in definition.relocations
    )
    if (
        definition.data != expected_caller_data
        or len(actual_relocations) != len(expected_relocations)
        or len({(row[0], row[3]) for row in actual_relocations})
        != len(actual_relocations)
        or {
            index
            for index, masked in enumerate(definition.relocation_mask)
            if masked
        }
        != expected_mask
        or any(
            len([
                row for row in definition.relocations
                if row.offset == offset
                and row.type == kind
                and (
                    row.symbol_name == symbol
                    if symbol is not None
                    else re.fullmatch(r"\$L\d+", row.symbol_name) is not None
                )
            ]) != 1
            for offset, kind, symbol in expected_relocations
        )
    ):
        raise ValueError(
            f"{label} rejects caller body, relocation, addend, population, or mask drift"
        )

    call_symbols = {spec[3] for spec in _CZGAMEFRAME_DESTRUCTOR_CALL_SPECS}
    call_relocations = tuple(
        sorted(
            (
                (row.offset, row.type, row.symbol_name)
                for row in definition.relocations
                if row.symbol_name in call_symbols
            )
        )
    )
    expected_relocations = tuple(
        sorted(
            (relocation_offset, IMAGE_REL_I386_REL32, symbol)
            for _ordinal, _instruction_offset, relocation_offset, symbol
            in _CZGAMEFRAME_DESTRUCTOR_CALL_SPECS
        )
    )
    if call_relocations != expected_relocations:
        raise ValueError(
            f"{label} requires the three exact caller REL32 target rows"
        )
    for relocation_offset, _relocation_type, _symbol in call_relocations:
        if (
            definition.data[relocation_offset - 1] != 0xE8
            or struct.unpack_from(
                "<I", definition.data, relocation_offset
            )[0] != 0
            or not all(
                definition.relocation_mask[index]
                for index in range(relocation_offset, relocation_offset + 4)
            )
        ):
            raise ValueError(
                f"{label} requires zero-addend fully masked E8 REL32 fields"
            )

    required_thunks = {
        _CZGAMEFRAME_DELETE_OBJECT_SYMBOL: (
            _CZGAMEFRAME_DELETE_OBJECT_PROVIDER_IDENTITY,
            _CZGAMEFRAME_DELETE_OBJECT_THUNK_ADDRESS,
            _CZGAMEFRAME_DELETE_OBJECT_IAT_IDENTITY,
            _CZGAMEFRAME_DELETE_OBJECT_IMPORT_ORDINAL,
        ),
        _CZGAMEFRAME_CFRAMEWND_DESTRUCTOR_SYMBOL: (
            _CZGAMEFRAME_CFRAMEWND_DESTRUCTOR_PROVIDER_IDENTITY,
            _CZGAMEFRAME_CFRAMEWND_DESTRUCTOR_THUNK_ADDRESS,
            _CZGAMEFRAME_CFRAMEWND_DESTRUCTOR_IAT_IDENTITY,
            _CZGAMEFRAME_CFRAMEWND_DESTRUCTOR_IMPORT_ORDINAL,
        ),
    }
    for callable_symbol, (
        provider_identity,
        thunk_address,
        iat_identity,
        import_ordinal,
    ) in (
        required_thunks.items()
    ):
        matches = tuple(
            thunk for thunk in thunks
            if thunk.callable_symbol == callable_symbol
        )
        if len(matches) != 1:
            raise ValueError(
                f"{label} requires one exact MFC ordinal thunk for "
                f"{callable_symbol!r}"
            )
        thunk = matches[0]
        if (
            thunk.provider_identity != provider_identity
            or thunk.thunk_address != thunk_address
            or thunk.retail_name != callable_symbol
            or thunk.iat_object_symbol != f"__imp_{callable_symbol}"
            or thunk.iat_identity != iat_identity
            or thunk.import_dll.upper() != "MFC42.DLL"
            or thunk.import_ordinal != import_ordinal
            or indexes.by_address.get(thunk_address) != provider_identity
            or provider_identity not in indexes.provider_ids
            or indexes.storage_by_name.get(thunk.iat_object_symbol)
            != thunk.iat_identity
        ):
            raise ValueError(
                f"{label} rejects MFC provider, thunk, ordinal-IAT, or "
                f"storage identity drift for {callable_symbol!r}"
            )

    caller_symbols = [
        row for row in definition.coff_symbols
        if row.name == _CZGAMEFRAME_DESTRUCTOR_SYMBOL
    ]
    if len(caller_symbols) != 1:
        raise ValueError(f"{label} rejects caller COFF symbol collision")
    caller_symbol = caller_symbols[0]
    same_section = tuple(
        row.name for row in definition.coff_symbols
        if row.section_number == caller_symbol.section_number
        and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
    )
    if (
        definition.section_index != caller_symbol.section_number
        or caller_symbol.value != 0
        or caller_symbol.symbol_type != 0x20
        or caller_symbol.storage_class != IMAGE_SYM_CLASS_EXTERNAL
        or caller_symbol.section_name != ".text"
        or caller_symbol.section_size != 0x60
        or caller_symbol.natural_end != 0x60
        or not (caller_symbol.section_characteristics & IMAGE_SCN_LNK_COMDAT)
        or same_section != (_CZGAMEFRAME_DESTRUCTOR_SYMBOL,)
        or any(
            row.index != caller_symbol.index
            and (
                row.name == _CZGAMEFRAME_DESTRUCTOR_SYMBOL
                or (
                    row.storage_class == 105
                    and row.weak_external_tag_index == caller_symbol.index
                )
            )
            for row in definition.coff_symbols
        )
    ):
        raise ValueError(f"{label} rejects caller COFF/COMDAT or collision drift")

    helper_specs = {
        _CZGAMEFRAME_CBITMAP_DESTRUCTOR_SYMBOL: (
            bytes.fromhex("c7 01 00 00 00 00 e9 00 00 00 00 90 90 90 90 90"),
            (
                (2, IMAGE_REL_I386_DIR32, _CZGAMEFRAME_CBITMAP_VFTABLE_SYMBOL),
                (7, IMAGE_REL_I386_REL32, _CZGAMEFRAME_CGDIOBJECT_DESTRUCTOR_SYMBOL),
            ),
            compiler_root / "VC" / "MFC" / "INCLUDE" / "afxwin1.inl",
        ),
        _CZGAMEFRAME_CGDIOBJECT_DESTRUCTOR_SYMBOL: (
            bytes.fromhex(
                "6a ff 68 00 00 00 00 64 a1 00 00 00 00 50 64 89 "
                "25 00 00 00 00 51 56 8b f1 89 74 24 04 c7 06 00 "
                "00 00 00 c7 44 24 10 00 00 00 00 e8 00 00 00 00 "
                "8b ce c7 44 24 10 ff ff ff ff e8 00 00 00 00 8b "
                "4c 24 08 5e 64 89 0d 00 00 00 00 83 c4 10 c3 90"
            ),
            (
                (3, IMAGE_REL_I386_DIR32, None),
                (9, IMAGE_REL_I386_DIR32, "__except_list"),
                (17, IMAGE_REL_I386_DIR32, "__except_list"),
                (31, IMAGE_REL_I386_DIR32, _CZGAMEFRAME_CGDIOBJECT_VFTABLE_SYMBOL),
                (44, IMAGE_REL_I386_REL32, _CZGAMEFRAME_DELETE_OBJECT_SYMBOL),
                (59, IMAGE_REL_I386_REL32, _CZGAMEFRAME_COBJECT_DESTRUCTOR_SYMBOL),
                (71, IMAGE_REL_I386_DIR32, "__except_list"),
            ),
            compiler_root / "VC" / "MFC" / "INCLUDE" / "afxwin1.inl",
        ),
        _CZGAMEFRAME_COBJECT_DESTRUCTOR_SYMBOL: (
            bytes.fromhex("c7 01 00 00 00 00 c3 90 90 90 90 90 90 90 90 90"),
            ((2, IMAGE_REL_I386_DIR32, _CZGAMEFRAME_COBJECT_VFTABLE_SYMBOL),),
            compiler_root / "VC" / "MFC" / "INCLUDE" / "afx.inl",
        ),
    }
    for helper_name, (body, relocation_specs, source) in helper_specs.items():
        helper = candidate.tu_local_function_definitions.get(helper_name)
        symbols = [row for row in definition.coff_symbols if row.name == helper_name]
        if helper is None or len(symbols) != 1:
            raise ValueError(f"{label} requires one collision-free {helper_name!r} COMDAT")
        symbol = symbols[0]
        actual_helper_relocations = tuple(
            (row.offset, row.type, row.symbol_name) for row in helper.relocations
        )
        expected_helper_mask = {
            index
            for offset, _kind, _name in relocation_specs
            for index in range(offset, offset + 4)
        }
        relocations_match = len(actual_helper_relocations) == len(relocation_specs)
        for offset, kind, name in relocation_specs:
            relocations_match = relocations_match and len([
                row for row in helper.relocations
                if row.offset == offset
                and row.type == kind
                and (
                    row.symbol_name == name
                    if name is not None
                    else re.fullmatch(r"\$L\d+", row.symbol_name) is not None
                )
            ]) == 1
        try:
            source_matches = Path(helper.source_provenance).resolve() == source.resolve()
        except (OSError, TypeError, ValueError):
            source_matches = False
        same_helper_section = tuple(
            row.name for row in definition.coff_symbols
            if row.section_number == symbol.section_number
            and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
        )
        if (
            helper.data != body
            or helper.section_size != len(body)
            or helper.section_external_functions != (helper_name,)
            or helper.section_is_comdat is not True
            or helper.comdat_selection != 2
            or not relocations_match
            or {index for index, masked in enumerate(helper.relocation_mask) if masked}
            != expected_helper_mask
            or helper.local_control_flow_indices
            or helper.local_control_flow_targets
            or not source_matches
            or symbol.value != 0
            or symbol.symbol_type != 0x20
            or symbol.storage_class != IMAGE_SYM_CLASS_EXTERNAL
            or symbol.section_name != ".text"
            or symbol.section_size != len(body)
            or symbol.natural_end != len(body)
            or not (symbol.section_characteristics & IMAGE_SCN_LNK_COMDAT)
            or same_helper_section != (helper_name,)
            or any(
                row.index != symbol.index
                and (
                    row.name == helper_name
                    or (
                        row.storage_class == 105
                        and row.weak_external_tag_index == symbol.index
                    )
                )
                for row in definition.coff_symbols
            )
        ):
            raise ValueError(
                f"{label} rejects canonical body, relocation, provenance, "
                f"COMDAT, population, or collision drift for {helper_name!r}"
            )

    expected_retail_instructions = bytes.fromhex(
        "6a ff 68 10 ad 4c 00 64 a1 00 00 00 00 50 64 89 "
        "25 00 00 00 00 51 56 8b f1 57 c7 06 d8 21 4d 00 "
        "e8 8b 3d 06 00 8d be c4 00 00 00 89 7c 24 08 c7 "
        "07 f8 22 4d 00 8b cf c7 44 24 14 01 00 00 00 e8 "
        "0e 26 08 00 8b ce c7 07 68 12 4d 00 c7 44 24 14 "
        "ff ff ff ff e8 f3 25 08 00 8b 4c 24 0c 5f 64 89 "
        "0d 00 00 00 00 5e 83 c4 10 c3"
    )
    retail_addresses = _instruction_runtime_addresses(
        retail_instructions,
        source="bn",
        caller_start=address_value(_CZGAMEFRAME_DESTRUCTOR_CALLER_START),
    )
    retail_rows = sorted(
        (address, bytes(int(value, 16) for value in instruction.bytes))
        for instruction, address in zip(retail_instructions, retail_addresses)
        if address is not None
        and 0x443830 <= address < 0x4438A0
    )
    cursor = 0x443830
    retail_body = bytearray()
    for address, body in retail_rows:
        if address != cursor or not body:
            raise ValueError(f"{label} rejects immutable retail extent population")
        retail_body.extend(body)
        cursor += len(body)
    if (
        cursor != 0x44389A
        or bytes(retail_body) != expected_retail_instructions
        or _hexdump_bytes(bridge.hexdump("0x44389a", 6)) != b"\x90" * 6
    ):
        raise ValueError(
            f"{label} rejects immutable retail +0xc4 CBitmap/DeleteObject/"
            "CObject/CFrameWnd semantic body, registered extent, or trailing "
            "six-byte alignment padding"
        )

    provider_expected = [dict(row) for row in expected]
    provider_expected[1] = {
        "ordinal": 1,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "direct",
        "target_identity": _CZGAMEFRAME_CBITMAP_DESTRUCTOR_CANDIDATE_IDENTITY,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    if (
        indexes.by_address.get("0x443c00")
        != _CZGAMEFRAME_CBITMAP_DESTRUCTOR_RESOLVED_PROVIDER_IDENTITY
        or _CZGAMEFRAME_CBITMAP_DESTRUCTOR_RESOLVED_PROVIDER_IDENTITY
        not in indexes.provider_ids
    ):
        raise ValueError(
            f"{label} rejects the reviewed candidate-local CBitmap COMDAT "
            "to provider:recoil:function:0x443c00 resolution identity"
        )
    candidate_resolved_expected = [dict(row) for row in expected]
    candidate_resolved_expected[1] = {
        "ordinal": 1,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "provider",
        "target_identity": (
            _CZGAMEFRAME_CBITMAP_DESTRUCTOR_RESOLVED_PROVIDER_IDENTITY
        ),
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    return CZGameFrameInlineDestructorProjection(
        provider_expected=tuple(provider_expected),
        candidate_resolved_expected=tuple(candidate_resolved_expected),
        retail_expected=tuple(dict(row) for row in expected),
    )


def _apply_czgameframe_inline_destructor_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    proof: CZGameFrameInlineDestructorProjection | None,
) -> list[dict[str, Any]]:
    result = [dict(row) for row in candidate_contract]
    if proof is None:
        return result
    label = "CZGameFrame inline-destructor projection"
    if (
        tuple(dict(row) for row in expected) != proof.retail_expected
        or len(result) != 3
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(result))
        or tuple(result) != proof.candidate_resolved_expected
        or sum(
            row.get("target_identity")
            == _CZGAMEFRAME_CBITMAP_DESTRUCTOR_RESOLVED_PROVIDER_IDENTITY
            for row in result
        ) != 1
        or any(
            row.get("target_identity")
            == _CZGAMEFRAME_DELETE_OBJECT_PROVIDER_IDENTITY
            for row in result
        )
    ):
        raise ValueError(
            f"{label} rejects shifted, colliding, missing, extra, or unused "
            "candidate destructor proof"
        )
    result[1] = dict(expected[1])
    return result


def _compose_supplemental_candidate_direct_bridges(
    *bridge_maps: Mapping[str, str],
) -> dict[str, str]:
    """Compose independent caller-scoped direct proofs without overwrite.

    These maps feed a provisional complete-caller extraction.  A plain mapping
    expansion would silently let the last producer win before the ordinal
    producer can enforce its own collision gates.
    """

    result: dict[str, str] = {}
    for additions in bridge_maps:
        conflicts = result.keys() & additions.keys()
        if any(result[name] != additions[name] for name in conflicts):
            raise ValueError(
                "supplemental candidate direct bridge producers conflict for "
                + ", ".join(repr(name) for name in sorted(conflicts))
            )
        result.update(additions)
    return result


def _provider_ordinal_import_thunk_candidate_bridges_from_reviewed_directs(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    thunks: Sequence[ProviderOrdinalImportThunk],
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    reviewed_candidate_direct_bridges: Mapping[str, str],
    supplemental_candidate_direct_bridges: Mapping[str, str] | None = None,
    reviewed_register_storage_bridges: Mapping[str, str] | None = None,
    reviewed_static_storage_reference_bridges: Mapping[
        str, ReviewedStaticStorageReferenceBridge
    ] | None = None,
    reviewed_member_vptr_storage_bridges: Mapping[
        str, ReviewedMemberVptrStorageBridge
    ] | None = None,
    candidate_exact_iat_register_load_proofs: Mapping[
        str, CandidateExactIatRegisterLoadProof
    ] | None = None,
) -> dict[str, str]:
    """Compose reviewed direct maps before ordinal proof extraction.

    The ordinal producer re-extracts the complete caller.  Supplemental
    caller-scoped proofs therefore have to be visible during that extraction,
    while an exact callable owned by the ordinal producer itself stays out of
    the reviewed map so the producer can prove it independently.
    """

    reviewed_bridges = dict(reviewed_candidate_direct_bridges)
    ordinal_identities = {
        thunk.callable_symbol: thunk.provider_identity for thunk in thunks
    }
    for name, target_identity in (
        supplemental_candidate_direct_bridges or {}
    ).items():
        ordinal_identity = ordinal_identities.get(name)
        if ordinal_identity is not None:
            if target_identity != ordinal_identity:
                raise ValueError(
                    "supplemental candidate direct bridge conflicts with the "
                    f"ordinal producer identity for {name!r}"
                )
            continue
        reviewed_identity = reviewed_bridges.get(name)
        if (
            reviewed_identity is not None
            and reviewed_identity != target_identity
        ):
            raise ValueError(
                "supplemental candidate direct bridge conflicts with another "
                f"reviewed direct identity for {name!r}"
            )
        reviewed_bridges[name] = target_identity

    reviewed_noncall_relocation_offsets = (
        _wol_config_reviewed_ordinal_noncall_relocation_offsets(
            candidate,
            caller_identity=caller_identity,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
            supplemental_candidate_direct_bridges=(
                supplemental_candidate_direct_bridges or {}
            ),
        )
    )
    eh_callback_offsets = (
        _eh_array_destructor_callback_noncall_relocation_offsets(
            candidate,
            indexes=indexes,
        )
    )
    for callable_symbol, offsets in eh_callback_offsets.items():
        prior = reviewed_noncall_relocation_offsets.get(callable_symbol)
        if prior is not None and prior != offsets:
            raise CandidateCallContractEvidenceError(
                "EH array-destructor callback relocation proof conflicts with "
                f"another reviewed noncall proof for {callable_symbol!r}"
            )
        reviewed_noncall_relocation_offsets[callable_symbol] = offsets

    return _provider_ordinal_import_thunk_candidate_bridges(
        expected,
        candidate,
        thunks=thunks,
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
        indexes=indexes,
        bridge_names=bridge_names,
        reviewed_candidate_direct_bridges=reviewed_bridges,
        reviewed_register_storage_bridges=(
            reviewed_register_storage_bridges
        ),
        reviewed_static_storage_reference_bridges=(
            reviewed_static_storage_reference_bridges
        ),
        reviewed_member_vptr_storage_bridges=(
            reviewed_member_vptr_storage_bridges
        ),
        candidate_exact_iat_register_load_proofs=(
            candidate_exact_iat_register_load_proofs
        ),
        reviewed_noncall_relocation_offsets=(
            reviewed_noncall_relocation_offsets
        ),
    )


def _exact_zeroarg_constructor_row_name(
    candidate_name: str,
) -> str | None:
    """Map one exact VC5 constructor decoration to ``Class::Class``."""
    match = MSVC_EXACT_ZEROARG_CONSTRUCTOR_RE.fullmatch(candidate_name)
    if match is None:
        return None
    encoded_parts = match.group("class_scope").split("@")
    class_identity = "::".join(reversed(encoded_parts))
    return f"{class_identity}::{encoded_parts[0]}"


def _exact_parameterized_constructor_row_name(
    candidate_name: str,
) -> str | None:
    """Map one exact ordinary one-enum VC5 constructor to ``Class::Constructor``."""
    match = MSVC_EXACT_SINGLE_ENUM_PARAMETER_CONSTRUCTOR_RE.fullmatch(
        candidate_name
    )
    if match is None:
        return None
    encoded_parts = match.group("class_scope").split("@")
    class_identity = "::".join(reversed(encoded_parts))
    return f"{class_identity}::Constructor"


def _exact_named_zeroarg_constructor_row_name(
    candidate_name: str,
) -> str | None:
    """Map one exact self-returning ``Constructor()`` method to its row.

    This is disjoint from ordinary ``??0`` constructors.  The decoration must
    literally name ``Constructor``, use the VC5 public thiscall ``QAE``
    package, return ``PAU1@`` (a pointer to the same encoded class scope), and
    end in ``XZ`` with zero explicit arguments.
    """
    match = MSVC_EXACT_NAMED_ZEROARG_CONSTRUCTOR_RE.fullmatch(
        candidate_name
    )
    if match is None:
        return None
    encoded_parts = match.group("class_scope").split("@")
    class_identity = "::".join(reversed(encoded_parts))
    return f"{class_identity}::Constructor"


def _exact_zeroarg_lifecycle_row_name(
    candidate_name: str,
) -> str | None:
    """Map one exact ordinary VC5 lifecycle decoration to its row name."""
    constructor_name = _exact_zeroarg_constructor_row_name(candidate_name)
    if constructor_name is not None:
        return constructor_name
    constructor_name = _exact_parameterized_constructor_row_name(
        candidate_name
    )
    if constructor_name is not None:
        return constructor_name
    constructor_name = _exact_named_zeroarg_constructor_row_name(
        candidate_name
    )
    if constructor_name is not None:
        return constructor_name
    return _exact_zeroarg_destructor_row_name(candidate_name)


def _exact_zeroarg_destructor_row_name(
    candidate_name: str,
) -> str | None:
    """Map one exact VC5 complete destructor to ``Class::~Class``."""
    match = MSVC_EXACT_ZEROARG_DESTRUCTOR_RE.fullmatch(candidate_name)
    if match is None:
        return None
    encoded_parts = match.group("class_scope").split("@")
    class_identity = "::".join(reversed(encoded_parts))
    return f"{class_identity}::~{encoded_parts[0]}"


def _has_exact_bn_semantic_function(
    bridge_names: Mapping[str, Any],
    *,
    semantic_name: str,
    address: str,
) -> bool:
    """Require one current BN function carrying one synchronized semantic name."""
    raw_rows = bridge_names.get(semantic_name)
    if raw_rows is None:
        return False
    rows = (
        tuple(raw_rows)
        if isinstance(raw_rows, (list, tuple))
        else (raw_rows,)
    )
    if len(rows) != 1:
        return False
    row = rows[0]
    raw_address = getattr(row, "address", "")
    try:
        row_address = normalize_address(str(raw_address))
    except ProgressError:
        return False
    names = {
        str(value)
        for value in (
            getattr(row, "name", ""),
            getattr(row, "raw_name", ""),
            getattr(row, "full_name", ""),
        )
        if value
    }
    return (
        getattr(row, "kind", "") == "function"
        and row_address == address
        and semantic_name in names
    )


_VC5_TU_LOCAL_CALLABLE_RE = re.compile(
    r"(?P<head>\?.+?@\?%)"
    r"(?P<source>[^@]+\.(?:c|cc|cpp|cxx))"
    r"(?P<discriminator>[0-9]+)@@"
    r"(?P<suffix>.+Z)",
    re.IGNORECASE,
)


def _current_absolute_tu_local_matches_reviewed_symbol(
    candidate_name: str,
    reviewed_name: str,
) -> bool:
    candidate_match = _VC5_TU_LOCAL_CALLABLE_RE.fullmatch(candidate_name)
    reviewed_match = _VC5_TU_LOCAL_CALLABLE_RE.fullmatch(reviewed_name)
    if candidate_match is None or reviewed_match is None:
        return False
    candidate_source = candidate_match.group("source")
    reviewed_source = reviewed_match.group("source")
    if (
        re.fullmatch(r"[A-Za-z]:[\\/].+", candidate_source) is None
        or PureWindowsPath(reviewed_source).name != reviewed_source
        or PureWindowsPath(candidate_source).name != reviewed_source
    ):
        return False
    return (
        candidate_match.group("head") == reviewed_match.group("head")
        and candidate_match.group("suffix") == reviewed_match.group("suffix")
    )


_ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_IDENTITY = (
    "symbol:recoil:function:0x473e60"
)
_ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_START = "0x473e60"
_ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_END = "0x473fc0"
_ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_SYMBOL = (
    "?zMath_Camera_StageInverseRotation@@YIXPBUzMat4x3@@@Z"
)
_ZMATH_CAMERA_STAGE_INVERSE_ROTATION_TARGET_ID = (
    "recoil:vc5-target:zmath_zmth_main_472670_475c40_authored_order"
)
_ZMATH_CAMERA_STAGE_INVERSE_ROTATION_TARGET_NAME = (
    "zmath_zmth_main_472670_475c40_authored_order"
)
_ZMATH_CAMERA_STAGE_INVERSE_ROTATION_MANIFEST = (
    "tools/vc5_verify_targets/"
    "zmath_zmth_main_472670_475c40_authored_order.json"
)
_ZMATH_CAMERA_STAGE_INVERSE_ROTATION_SOURCE = (
    "src/GameZRecoil/zMath/zmth_main.c"
)
_ZMATH_CAMERA_NEGATE_CALL_OFFSETS = (
    0x19,
    0x2B,
    0x3D,
    0x4E,
    0x60,
    0x72,
    0xFB,
    0x10D,
    0x11E,
)


def _zmath_camera_negate_float_sign_bit_candidate_bridge(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    compiler_generated_bridges: Mapping[str, str],
) -> dict[str, str]:
    """Expose one exact nine-call candidate-only zMath helper identity.

    Retail 0x473e60 contains no invocation: VC5 inlined the sign-bit XORs.
    Current source emits the TU-local helper as nine calls instead.  This
    bridge exists only so the ordinary retail/candidate contract comparator
    can report that semantic mismatch.  It does not synthesize retail calls,
    map the helper to a retail address, or grant reviewed identity state.
    """

    caller = candidate.caller_definition
    absolute_calls: dict[str, list[tuple[int, Instruction, int]]] = {}
    for instruction_index, instruction in enumerate(candidate.instructions):
        if _instruction_mnemonic(instruction) not in {"call", "jmp"}:
            continue
        name = _cod_space_bearing_direct_target(
            _instruction_operand(instruction).strip(),
            instruction.source_line,
        )
        if name is not None and "NegateFloatSignBit" in name:
            raw_offset = _source_instruction_address(instruction)
            absolute_calls.setdefault(name, []).append(
                (
                    instruction_index,
                    instruction,
                    address_value(raw_offset) if raw_offset else -1,
                )
            )
    if not absolute_calls:
        return {}
    if len(absolute_calls) != 1:
        raise ValueError(
            "zMath camera negate candidate bridge requires one exact "
            "absolute TU-local helper decoration"
        )
    candidate_name, calls = next(iter(absolute_calls.items()))

    match = _VC5_TU_LOCAL_CALLABLE_RE.fullmatch(candidate_name)
    expected_source = (
        REPO_ROOT / _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_SOURCE
    ).resolve()
    if (
        match is None
        or match.group("head") != "?NegateFloatSignBit@?%"
        or match.group("suffix") != "YIMM@Z"
        or Path(match.group("source")).resolve() != expected_source
    ):
        raise ValueError(
            "zMath camera negate candidate bridge requires the exact "
            "absolute TU-local NegateFloatSignBit(float) decoration"
        )

    target = candidate.target
    manifest_path = Path(str(getattr(target, "manifest_path", "")))
    target_rows = tuple(getattr(target, "functions", ()))
    matching_target_rows = [
        row
        for row in target_rows
        if str(getattr(row, "address", ""))
        == _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_START
    ]
    if (
        caller_identity
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_IDENTITY
        or normalize_address(caller_start)
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_START
        or normalize_address(caller_end_exclusive)
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_END
        or tuple(expected) != ()
        or caller is None
        or caller.symbol
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_SYMBOL
        or target is None
        or getattr(target, "target_binary", "") != "recoil"
        or getattr(target, "name", "")
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_TARGET_NAME
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
        or manifest_path.resolve()
        != (REPO_ROOT / _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_MANIFEST).resolve()
        or getattr(target, "source_from", "")
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_SOURCE
        or tuple(getattr(target, "source_files", ())) != ()
        or len(matching_target_rows) != 1
        or getattr(matching_target_rows[0], "symbol", "")
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_SYMBOL
        or getattr(matching_target_rows[0], "symbol_regex", None) is not None
        or getattr(matching_target_rows[0], "pipeline_class", "")
        != "authored"
        or getattr(matching_target_rows[0], "authored_order_role", "")
        != "authored-body"
        or getattr(matching_target_rows[0], "required_presence", False)
        is not True
        or getattr(matching_target_rows[0], "full_order_gate", False)
        is not True
    ):
        raise ValueError(
            "zMath camera negate candidate bridge requires the exact retail "
            "caller, empty retail contract, and selected VC5 target manifest"
        )

    symbol_id = "recoil:function:0x473e60"
    symbol = document.collection("symbols").get(symbol_id)
    source_traceability = (
        symbol.get("source_traceability")
        if isinstance(symbol, Mapping)
        else None
    )
    source_edges = (
        source_traceability.get("source_edges")
        if isinstance(source_traceability, Mapping)
        else None
    )
    exact_source_edges = [
        edge
        for edge in source_edges or []
        if isinstance(edge, Mapping)
        and edge.get("relation") == "defines"
        and isinstance(edge.get("emission_context"), Mapping)
        and edge["emission_context"].get("translation_unit")
        == _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_SOURCE
    ]
    registered_target = document.collection("verification_targets").get(
        _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_TARGET_ID
    )
    registration = (
        registered_target.get("registration")
        if isinstance(registered_target, Mapping)
        else None
    )
    registered_caller_rows = [
        row
        for _view, row in _mapping_target_function_rows_with_views(
            registered_target or {}
        )
        if row.get("address")
        == _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_START
        and row.get("symbol")
        == _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_SYMBOL
    ]
    unique_registered_rows = {
        json.dumps(dict(row), sort_keys=True, separators=(",", ":"))
        for row in registered_caller_rows
    }
    if (
        not isinstance(symbol, Mapping)
        or _symbol_identity(symbol_id, symbol) != caller_identity
        or symbol.get("binary") != "recoil"
        or symbol.get("kind") != "function"
        or symbol.get("pipeline_class") != "authored"
        or symbol.get("authored_order_role") != "authored-body"
        or symbol.get("address")
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_START
        or symbol.get("end_exclusive")
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_END
        or symbol.get("size") != 0x160
        or symbol.get("extent_state") != "known"
        or symbol.get("disposition") != "unresolved"
        or symbol.get("ownership_state") != "primary-owned"
        or symbol.get("physical_block_id") != "recoil:block:0x472670"
        or symbol.get("output_section_id") != "recoil:section:.text"
        or _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_TARGET_ID
        not in symbol.get("verification_target_ids", [])
        or not isinstance(source_traceability, Mapping)
        or source_traceability.get("state") != "resolved"
        or len(source_edges or []) != 1
        or len(exact_source_edges) != 1
        or indexes.by_address.get(
            _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_START
        )
        != caller_identity
        or caller_identity in indexes.provider_ids
        or not isinstance(registered_target, Mapping)
        or registered_target.get("binary") != "recoil"
        or registered_target.get("kind") != "vc5"
        or registered_target.get("name")
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_TARGET_NAME
        or not isinstance(registration, Mapping)
        or registration.get("manifest_path")
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_MANIFEST
        or registration.get("source_from")
        != _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_SOURCE
        or registration.get("check_translation_unit_function_order")
        is not True
        or registered_target.get("registered_addresses", []).count(
            _ZMATH_CAMERA_STAGE_INVERSE_ROTATION_CALLER_START
        )
        != 1
        or len(unique_registered_rows) != 1
    ):
        raise ValueError(
            "zMath camera negate candidate bridge requires the exact reviewed "
            "caller identity, extent, source edge, and target registration"
        )

    call_offsets = tuple(offset for _index, _instruction, offset in calls)
    if call_offsets != _ZMATH_CAMERA_NEGATE_CALL_OFFSETS:
        raise ValueError(
            "zMath camera negate candidate bridge requires the exact nine "
            "candidate call offsets"
        )
    for instruction_index, instruction, offset in calls:
        if (
            instruction_index in candidate.local_control_flow_indices
            or _instruction_mnemonic(instruction) != "call"
            or tuple(value.lower() for value in instruction.bytes)
            != ("e8", "00", "00", "00", "00")
            or _cod_space_bearing_direct_target(
                _instruction_operand(instruction).strip(),
                instruction.source_line,
            )
            != candidate_name
            or offset < 0
        ):
            raise ValueError(
                "zMath camera negate candidate bridge requires exact nonlocal "
                "zero-addend E8 COD evidence at all nine call sites"
            )

    folded_name = candidate_name.casefold()
    for label, names in (
        ("candidate identity", indexes.by_candidate_name),
        ("Binary Ninja identity", bridge_names),
        ("compiler/provider identity", compiler_generated_bridges),
        ("candidate storage identity", indexes.storage_by_name),
    ):
        collisions = sorted(name for name in names if name.casefold() == folded_name)
        if collisions:
            raise ValueError(
                "zMath camera negate candidate bridge has an existing "
                f"{label} collision for {candidate_name!r}"
            )

    definitions = [
        row
        for row in caller.coff_symbols
        if row.name.casefold() == folded_name
    ]
    defined_names = [
        name
        for name in caller.defined_external_functions
        if name.casefold() == folded_name
    ]
    undefined_names = [
        name
        for name in caller.undefined_external_functions
        if name.casefold() == folded_name
    ]
    if (
        len(definitions) != 1
        or definitions[0].name != candidate_name
        or defined_names != [candidate_name]
        or undefined_names
    ):
        raise ValueError(
            "zMath camera negate candidate bridge requires one exact same-TU "
            "defined COFF external and no duplicate, undefined, or folded alias"
        )
    definition = definitions[0]
    weak_or_coincident = [
        row
        for row in caller.coff_symbols
        if (
            row.storage_class == 105
            and (
                row.name.casefold() == folded_name
                or row.weak_external_tag_index == definition.index
            )
        )
        or (
            row.index != definition.index
            and row.section_number == definition.section_number
            and row.value == definition.value
            and row.symbol_type == 0x20
        )
    ]
    if (
        weak_or_coincident
        or definition.section_number <= 0
        or definition.storage_class != IMAGE_SYM_CLASS_EXTERNAL
        or definition.symbol_type != 0x20
        or definition.section_name != ".text"
        or definition.section_size != 0x10
        or definition.value != 0
        or definition.natural_end != 0x10
        or not (definition.section_characteristics & IMAGE_SCN_CNT_CODE)
        or not (definition.section_characteristics & IMAGE_SCN_LNK_COMDAT)
    ):
        raise ValueError(
            "zMath camera negate candidate bridge requires one exact unaliased "
            "16-byte external code COMDAT definition"
        )

    if (
        caller.section_index <= 0
        or caller.section_start != 0
        or caller.section_end - caller.section_start != len(caller.data)
        or len(caller.data) != len(caller.relocation_mask)
    ):
        raise ValueError(
            "zMath camera negate candidate bridge requires one exact caller "
            "COFF section and body extent"
        )
    matching_relocations = [
        relocation
        for relocation in caller.relocations
        if relocation.symbol_name.casefold() == folded_name
    ]
    expected_relocation_offsets = tuple(
        offset + 1 for offset in _ZMATH_CAMERA_NEGATE_CALL_OFFSETS
    )
    if (
        len(matching_relocations) != len(expected_relocation_offsets)
        or tuple(relocation.offset for relocation in matching_relocations)
        != expected_relocation_offsets
    ):
        raise ValueError(
            "zMath camera negate candidate bridge requires the exact nine "
            "ordered call-site relocations"
        )
    for relocation in matching_relocations:
        field_end = relocation.offset + 4
        if (
            relocation.type != IMAGE_REL_I386_REL32
            or relocation.symbol_name != candidate_name
            or relocation.symbol_index != definition.index
            or relocation.offset < 1
            or field_end > len(caller.data)
            or caller.data[relocation.offset - 1] != 0xE8
            or struct.unpack_from("<I", caller.data, relocation.offset)[0] != 0
            or caller.relocation_mask[relocation.offset - 1]
            or not all(
                caller.relocation_mask[index]
                for index in range(relocation.offset, field_end)
            )
        ):
            raise ValueError(
                "zMath camera negate candidate bridge requires exact REL32 "
                "target, zero addend, opcode mask, and defining-symbol provenance"
            )

    identity = f"candidate-local-coff:{candidate_name}"
    if (
        identity in indexes.provider_ids
        or identity in indexes.by_address.values()
        or identity in indexes.by_candidate_name.values()
        or identity in compiler_generated_bridges.values()
    ):
        raise ValueError(
            "zMath camera negate candidate bridge comparison-only identity "
            "conflicts with reviewed state"
        )
    return {candidate_name: identity}


def _registered_target_symbol_regex_direct_candidate_bridges(
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    compiler_generated_bridges: Mapping[str, str],
) -> dict[str, str]:
    """Resolve exact candidate calls through one synchronized authored row.

    This is a candidate-only identity join.  Retail call order, form, target,
    and cleanup remain independently derived from Binary Ninja and compared by
    the ordinary call-contract verifier.
    """
    caller = candidate.caller_definition
    if caller is None:
        return {}

    direct_instructions_by_name: dict[
        str, list[tuple[int, Instruction, int, int]]
    ] = {}
    absolute_tu_local_names: set[str] = set()
    for instruction_index, instruction in enumerate(candidate.instructions):
        mnemonic = _instruction_mnemonic(instruction)
        if mnemonic not in {"call", "jmp"}:
            continue
        operand = _instruction_operand(instruction).strip()
        absolute_tu_local_name = _cod_space_bearing_direct_target(
            operand,
            instruction.source_line,
        )
        candidate_name = absolute_tu_local_name or operand
        if (
            absolute_tu_local_name is None
            and DECORATED_RE.fullmatch(operand) is None
        ):
            continue
        if absolute_tu_local_name is not None:
            absolute_tu_local_names.add(candidate_name)
        opcode = 0xE8 if mnemonic == "call" else 0xE9
        direct_instructions_by_name.setdefault(candidate_name, []).append(
            (
                instruction_index,
                instruction,
                0,
                opcode,
            )
        )

    if not direct_instructions_by_name:
        return {}

    symbols = document.collection("symbols")
    targets = document.collection("verification_targets")
    resolved: dict[str, str] = {}
    for candidate_name, instructions in direct_instructions_by_name.items():
        absolute_tu_local_bridge = candidate_name in absolute_tu_local_names
        selected_target_name = str(
            getattr(candidate.target, "name", "") or ""
        )
        selected_target_id = (
            f"recoil:vc5-target:{selected_target_name}"
            if selected_target_name
            else ""
        )
        # Existing exact-name authorities always retain priority.  In
        # particular, an explicit ambiguous/empty candidate index must not be
        # repaired by a broader regex row.
        if (
            candidate_name in indexes.by_candidate_name
            or candidate_name in bridge_names
            or candidate_name in compiler_generated_bridges
        ):
            continue
        folded_name = candidate_name.casefold()
        collision_sources = (
            ("candidate index", indexes.by_candidate_name),
            ("Binary Ninja name", bridge_names),
            ("compiler/provider bridge", compiler_generated_bridges),
            ("candidate storage", indexes.storage_by_name),
        )
        for label, names in collision_sources:
            collisions = sorted(
                name
                for name in names
                if name.casefold() == folded_name
            )
            if collisions:
                raise ValueError(
                    "registered target symbol-regex bridge has a "
                    f"case-folded {label} collision for {candidate_name!r}: "
                    + ", ".join(repr(name) for name in collisions)
                )

        proven_instructions: list[tuple[int, Instruction, int, int]] = []
        for instruction_index, instruction, _unused_offset, opcode in instructions:
            raw_offset = _source_instruction_address(instruction)
            if (
                instruction_index in candidate.local_control_flow_indices
                or not raw_offset
                or tuple(value.lower() for value in instruction.bytes[:1])
                != (f"{opcode:02x}",)
            ):
                raise ValueError(
                    "registered target symbol-regex bridge requires exact "
                    f"nonlocal E8/E9 COD evidence for {candidate_name!r}"
                )
            proven_instructions.append(
                (
                    instruction_index,
                    instruction,
                    address_value(raw_offset),
                    opcode,
                )
            )
        instructions = proven_instructions

        governing: dict[
            tuple[str, str, str], tuple[str, Mapping[str, Any], Mapping[str, Any], str]
        ] = {}
        absolute_selected_regex_matches: set[tuple[str, str, str]] = set()
        for target_id, target in targets.items():
            if (
                not isinstance(target, Mapping)
                or target.get("binary") != "recoil"
                or target.get("kind") != "vc5"
            ):
                continue
            registration = target.get("registration")
            registered_addresses = target.get("registered_addresses")
            if (
                not isinstance(registration, Mapping)
                or not isinstance(registered_addresses, list)
            ):
                continue
            for _view, row in _mapping_target_function_rows_with_views(target):
                symbol_regex = row.get("symbol_regex")
                reviewed_symbol = row.get("symbol")
                if (
                    absolute_tu_local_bridge
                    and str(target_id) == selected_target_id
                    and target.get("name") == selected_target_name
                    and isinstance(symbol_regex, str)
                    and symbol_regex
                ):
                    try:
                        if re.fullmatch(symbol_regex, candidate_name) is not None:
                            raw_selected_address = row.get("address")
                            if isinstance(raw_selected_address, str):
                                selected_address = normalize_address(
                                    raw_selected_address
                                )
                                selected_row_key = json.dumps(
                                    dict(row),
                                    sort_keys=True,
                                    separators=(",", ":"),
                                )
                                absolute_selected_regex_matches.add(
                                    (
                                        str(target_id),
                                        selected_address,
                                        selected_row_key,
                                    )
                                )
                    except re.error:
                        pass
                    except ProgressError:
                        pass
                if (
                    not isinstance(symbol_regex, str)
                    or not symbol_regex
                    or (
                        absolute_tu_local_bridge
                        and (
                            str(target_id) != selected_target_id
                            or target.get("name") != selected_target_name
                            or not isinstance(reviewed_symbol, str)
                            or not reviewed_symbol
                            or not _current_absolute_tu_local_matches_reviewed_symbol(
                                candidate_name,
                                reviewed_symbol,
                            )
                        )
                    )
                    or (
                        not absolute_tu_local_bridge
                        and reviewed_symbol not in {None, ""}
                    )
                ):
                    continue
                try:
                    matches = re.fullmatch(symbol_regex, candidate_name)
                except re.error:
                    continue
                if matches is None:
                    continue
                pipeline_class = row.get("pipeline_class")
                expected_role = (
                    "authored-body"
                    if pipeline_class == "authored"
                    else "authored-lifecycle-body"
                    if pipeline_class == "authored-lifecycle"
                    else ""
                )
                if (
                    row.get("required_presence") is not True
                    or not expected_role
                    or row.get("authored_order_role") != expected_role
                    or row.get("authored_order_gate") is not True
                    or row.get("authored_relative_order_gate") is not True
                    or row.get("full_order_gate") is not True
                    or row.get("logical_identity_key") not in {None, ""}
                    or row.get("icf_fold_status") not in {None, ""}
                ):
                    continue
                raw_address = row.get("address")
                if not isinstance(raw_address, str):
                    continue
                try:
                    address = normalize_address(raw_address)
                except ProgressError:
                    continue
                registered_at_address = [
                    item
                    for item in registered_addresses
                    if isinstance(item, str)
                    and normalize_address(item) == address
                ]
                if len(registered_at_address) != 1:
                    raise ValueError(
                        "registered target symbol-regex bridge target "
                        f"{target_id!r} has missing or duplicate active address "
                        f"{address}"
                    )
                row_key = json.dumps(
                    dict(row),
                    sort_keys=True,
                    separators=(",", ":"),
                )
                governing[(str(target_id), address, row_key)] = (
                    str(target_id),
                    target,
                    row,
                    address,
                )

        if absolute_tu_local_bridge and absolute_selected_regex_matches:
            if len(absolute_selected_regex_matches) != 1:
                raise ValueError(
                    "registered target absolute TU-local bridge requires "
                    f"exactly one selected full-regex row for {candidate_name!r}"
                )
            if not governing:
                raise ValueError(
                    "registered target absolute TU-local bridge regex match "
                    "does not preserve the exact reviewed basename and "
                    f"callable signature for {candidate_name!r}"
                )
        if not governing:
            continue
        if len(governing) != 1:
            authorities = sorted(
                f"{target_id}@{address}"
                for target_id, address, _row_key in governing
            )
            raise ValueError(
                "ambiguous active registered VC5 symbol-regex authority for "
                f"{candidate_name!r}: " + ", ".join(authorities)
            )

        target_id, target, row, address = next(iter(governing.values()))
        reviewed_symbol = row.get("symbol")
        _synchronized_finite_symbol_regex_target(
            target_id,
            target,
            address=address,
            row=row,
        )
        row_pipeline_class = row.get("pipeline_class")
        row_name = row.get("name")
        destructor_row_name = None
        parameterized_constructor_row_name = None
        if row_pipeline_class == "authored-lifecycle":
            lifecycle_row_name = _exact_zeroarg_lifecycle_row_name(
                candidate_name
            )
            destructor_row_name = _exact_zeroarg_destructor_row_name(
                candidate_name
            )
            parameterized_constructor_row_name = (
                _exact_parameterized_constructor_row_name(candidate_name)
            )
            if (
                not isinstance(row_name, str)
                or lifecycle_row_name != row_name
            ):
                raise ValueError(
                    "registered target symbol-regex lifecycle bridge requires "
                    "an exact ordinary constructor or zero-argument "
                    "destructor decoration, or an exact named zero-argument "
                    "Constructor self-return method, whose class and lifecycle "
                    "kind map to the synchronized Class::Class, "
                    "Class::Constructor, or Class::~Class row name for "
                    f"{candidate_name!r}"
                )

        identity = indexes.by_address.get(address, "")
        if not identity or identity in indexes.provider_ids:
            raise ValueError(
                "registered target symbol-regex bridge requires one reviewed "
                f"non-provider identity at {address} for {candidate_name!r}"
            )
        physical_symbols: list[tuple[str, Mapping[str, Any]]] = []
        for symbol_id, symbol in symbols.items():
            if (
                not isinstance(symbol, Mapping)
                or symbol.get("kind")
                not in {"function", "provider-function", "compiler-function"}
            ):
                continue
            raw_symbol_address = symbol.get(
                "address",
                symbol.get("start"),
            )
            if not isinstance(raw_symbol_address, str):
                continue
            try:
                symbol_address = normalize_address(raw_symbol_address)
            except ProgressError:
                continue
            if symbol_address == address:
                physical_symbols.append((str(symbol_id), symbol))
        if len(physical_symbols) != 1:
            raise ValueError(
                "registered target symbol-regex bridge requires one exact "
                f"physical symbol at {address} for {candidate_name!r}"
            )
        symbol_id, symbol = physical_symbols[0]
        end_exclusive = symbol.get("end_exclusive")
        size = symbol.get("size")
        verification_target_ids = symbol.get("verification_target_ids")
        block_id = symbol.get("physical_block_id")
        block = document.collection("physical_blocks").get(str(block_id))
        accepted_order_facts = (
            block.get("accepted_order_facts")
            if isinstance(block, Mapping)
            else None
        )
        accepted_occurrences = 0
        for candidate_block in document.collection(
            "physical_blocks"
        ).values():
            candidate_facts = (
                candidate_block.get("accepted_order_facts")
                if isinstance(candidate_block, Mapping)
                else None
            )
            if (
                not isinstance(candidate_facts, Mapping)
                or candidate_facts.get("phase")
                != "authored-function-order"
                or not isinstance(
                    candidate_facts.get("matched_identities"),
                    list,
                )
            ):
                continue
            accepted_occurrences += candidate_facts[
                "matched_identities"
            ].count(symbol_id)
        authored_order = (
            block.get("order", {}).get("authored", {})
            if isinstance(block, Mapping)
            and isinstance(block.get("order"), Mapping)
            else None
        )
        symbol_navigation_name = symbol.get("navigation_name")
        expected_symbol_roles = (
            {None, "authored-body"}
            if row_pipeline_class == "authored"
            else {"authored-lifecycle-body"}
        )
        lifecycle_navigation_current = (
            row_pipeline_class != "authored-lifecycle"
            or symbol_navigation_name == row_name
            # An exact complete-destructor decoration joined to the current
            # synchronized target row is stronger identity evidence than the
            # provisional physical navigation label.  Constructor behavior
            # retains its existing tracker/BN semantic-name requirement except
            # for the equally exact parameterized-constructor bridge below;
            # named Constructor methods retain that semantic-name requirement.
            or destructor_row_name == row_name
            or parameterized_constructor_row_name == row_name
            or (
                isinstance(row_name, str)
                and _has_exact_bn_semantic_function(
                    bridge_names,
                    semantic_name=row_name,
                    address=address,
                )
            )
        )
        authored_navigation_current = (
            row_pipeline_class != "authored"
            or symbol_navigation_name == row_name
            or (
                absolute_tu_local_bridge
                and isinstance(reviewed_symbol, str)
                and bool(reviewed_symbol)
                and _current_absolute_tu_local_matches_reviewed_symbol(
                    candidate_name,
                    reviewed_symbol,
                )
            )
        )
        if (
            _symbol_identity(symbol_id, symbol) != identity
            or symbol.get("binary") != "recoil"
            or symbol.get("kind") != "function"
            or symbol.get("pipeline_class") != row_pipeline_class
            or symbol.get("disposition") != "unresolved"
            or symbol.get("ownership_state") != "primary-owned"
            or symbol.get("output_section_id") != "recoil:section:.text"
            or symbol.get("authored_order_role") not in expected_symbol_roles
            or symbol.get("logical_aliases") not in (None, {})
            or symbol.get("icf_address_group") is not None
            or symbol.get("linked_provider_binding") is not None
            or symbol.get("lifecycle_variant_of") is not None
            or symbol.get("extent_state") != "known"
            or (
                row_pipeline_class == "authored"
                and not authored_navigation_current
            )
            or not lifecycle_navigation_current
            or not isinstance(end_exclusive, str)
            or address_value(normalize_address(end_exclusive))
            <= address_value(address)
            or size
            != address_value(normalize_address(end_exclusive))
            - address_value(address)
            or not isinstance(verification_target_ids, list)
            or verification_target_ids.count(target_id) != 1
            or not isinstance(block_id, str)
            or not isinstance(block, Mapping)
            or not isinstance(accepted_order_facts, Mapping)
            or accepted_order_facts.get("phase")
            != "authored-function-order"
            or accepted_order_facts.get("validation_mode") != "live"
            or accepted_order_facts.get("target_id") != target_id
            or not isinstance(
                accepted_order_facts.get("covered_block_ids"),
                list,
            )
            or accepted_order_facts["covered_block_ids"].count(block_id)
            != 1
            or not isinstance(
                accepted_order_facts.get("matched_identities"),
                list,
            )
            or accepted_order_facts["matched_identities"].count(symbol_id)
            != 1
            or accepted_occurrences != 1
            or not isinstance(authored_order, Mapping)
            or any(
                not is_current_accepted_state(
                    authored_order.get(dimension)
                )
                for dimension in AUTHORED_ORDER_DIMENSIONS
            )
        ):
            raise ValueError(
                "registered target symbol-regex bridge lacks the exact "
                "authored identity, extent, block occurrence, order state, "
                "role, synchronized lifecycle name, or target membership at "
                f"{address} for {candidate_name!r}"
            )

        folded_relocations = [
            relocation
            for relocation in caller.relocations
            if relocation.symbol_name.casefold() == folded_name
        ]
        if (
            len(folded_relocations) != len(instructions)
            or any(
                relocation.symbol_name != candidate_name
                for relocation in folded_relocations
            )
        ):
            raise ValueError(
                "registered target symbol-regex bridge requires one exact "
                f"caller-object relocation per COD invocation of "
                f"{candidate_name!r}"
            )
        folded_defined_names = [
            name
            for name in caller.defined_external_functions
            if name.casefold() == folded_name
        ]
        folded_undefined_names = [
            name
            for name in caller.undefined_external_functions
            if name.casefold() == folded_name
        ]
        same_tu_defined = (
            folded_defined_names == [candidate_name]
            and not folded_undefined_names
        )
        cross_tu_undefined = (
            not folded_defined_names
            and folded_undefined_names == [candidate_name]
        )
        absolute_tu_local_definition_index: int | None = None
        if absolute_tu_local_bridge:
            defined_coff_rows = [
                definition
                for definition in caller.coff_symbols
                if definition.name.casefold() == folded_name
            ]
            if (
                len(defined_coff_rows) != 1
                or defined_coff_rows[0].name != candidate_name
                or defined_coff_rows[0].section_number <= 0
                or defined_coff_rows[0].symbol_type != 0x20
                or defined_coff_rows[0].storage_class
                != IMAGE_SYM_CLASS_EXTERNAL
                or not same_tu_defined
                or cross_tu_undefined
            ):
                raise ValueError(
                    "registered target absolute TU-local bridge requires one "
                    "exact same-TU defined COFF function symbol, with no "
                    "duplicate, undefined, case-folded, or alias row for "
                    f"{candidate_name!r}"
                )
            absolute_definition = defined_coff_rows[0]
            weak_or_coincident = [
                definition
                for definition in caller.coff_symbols
                if (
                    definition.storage_class == 105
                    and (
                        definition.name.casefold() == folded_name
                        or definition.weak_external_tag_index
                        == absolute_definition.index
                    )
                )
                or (
                    definition.index != absolute_definition.index
                    and definition.section_number
                    == absolute_definition.section_number
                    and definition.value == absolute_definition.value
                    and definition.symbol_type == 0x20
                )
            ]
            if weak_or_coincident:
                raise ValueError(
                    "registered target absolute TU-local bridge requires one "
                    "exact unaliased same-TU defined COFF function symbol"
                )
            absolute_tu_local_definition_index = absolute_definition.index
            if any(
                relocation.symbol_index
                == absolute_tu_local_definition_index
                and relocation.symbol_name != candidate_name
                for relocation in caller.relocations
            ):
                raise ValueError(
                    "registered target absolute TU-local bridge has a "
                    "differently named relocation alias for the exact "
                    f"same-TU defined function {candidate_name!r}"
                )
        if not same_tu_defined and not cross_tu_undefined:
            raise ValueError(
                "registered target symbol-regex bridge requires either one "
                "exact same-TU defined COFF external or one exact cross-TU "
                "undefined COFF external, with no duplicate, mixed, "
                "case-folded, or alias row for "
                f"{candidate_name!r}"
            )
        if cross_tu_undefined:
            registration = target.get("registration")
            target_row_key = json.dumps(
                dict(row),
                sort_keys=True,
                separators=(",", ":"),
            )
            callee_source_rows: list[
                tuple[str, Mapping[str, Any]]
            ] = []
            if isinstance(registration, Mapping):
                for contribution in registration.get(
                    "translation_unit_function_order",
                    [],
                ):
                    if not isinstance(contribution, Mapping):
                        continue
                    for contribution_row in contribution.get(
                        "functions",
                        [],
                    ):
                        if (
                            isinstance(contribution_row, Mapping)
                            and json.dumps(
                                dict(contribution_row),
                                sort_keys=True,
                                separators=(",", ":"),
                            )
                            == target_row_key
                        ):
                            callee_source_rows.append(
                                (
                                    str(
                                        contribution.get(
                                            "source_from",
                                            "",
                                        )
                                    ),
                                    contribution,
                                )
                            )

            source_trace = symbol.get("source_traceability")
            source_edges = (
                source_trace.get("source_edges")
                if isinstance(source_trace, Mapping)
                else None
            )
            callee_source = (
                callee_source_rows[0][0]
                if len(callee_source_rows) == 1
                else ""
            )
            callee_contribution = (
                callee_source_rows[0][1]
                if len(callee_source_rows) == 1
                else None
            )
            callee_manifest = (
                str(registration.get("manifest_path", ""))
                if isinstance(registration, Mapping)
                else ""
            )
            if (
                not callee_source
                or not isinstance(callee_contribution, Mapping)
                or registration.get("check_translation_unit_function_order")
                is not True
                or callee_contribution.get("order_scope") != "authored"
                or callee_contribution.get("inventory_only") is not False
                or callee_contribution.get("candidate_only_extras") != []
                or not isinstance(
                    callee_contribution.get("function_addresses"),
                    list,
                )
                or callee_contribution["function_addresses"].count(address)
                != 1
                or registration.get("source_from") != callee_source
                or not callee_manifest
                or not isinstance(source_trace, Mapping)
                or source_trace.get("state") != "resolved"
                or source_trace.get("reason_code") not in {None, ""}
                or not isinstance(source_edges, list)
                or len(source_edges) != 1
                or not isinstance(source_edges[0], Mapping)
                or source_edges[0].get("relation") != "defines"
                or not source_edges[0].get("anchor_id")
                or source_edges[0].get("emission_context")
                != {"translation_unit": callee_source}
                or block.get("agent_source_path") != callee_source
                or block.get("original_source_path") != callee_source
                or block.get("source_path") != callee_source
            ):
                raise ValueError(
                    "registered target symbol-regex cross-TU bridge lacks "
                    "one exact synchronized callee source signature for "
                    f"{candidate_name!r}"
                )

            candidate_target = candidate.target
            caller_manifest = str(
                getattr(candidate_target, "manifest_path", "")
            )
            caller_rows: list[tuple[str, Any, Any]] = []
            for contribution in getattr(
                candidate_target,
                "translation_unit_function_order",
                (),
            ):
                for candidate_row in getattr(
                    contribution,
                    "functions",
                    (),
                ):
                    candidate_symbol = str(
                        getattr(candidate_row, "symbol", "")
                    )
                    candidate_regex = getattr(
                        candidate_row,
                        "symbol_regex",
                        None,
                    )
                    exact_match = candidate_symbol == caller.symbol
                    regex_match = False
                    if (
                        not candidate_symbol
                        and isinstance(candidate_regex, str)
                        and candidate_regex
                    ):
                        try:
                            regex_match = (
                                re.fullmatch(
                                    candidate_regex,
                                    caller.symbol,
                                )
                                is not None
                            )
                        except re.error:
                            regex_match = False
                    if exact_match or regex_match:
                        caller_rows.append(
                            (
                                str(
                                    getattr(
                                        contribution,
                                        "source_from",
                                        "",
                                    )
                                ),
                                contribution,
                                candidate_row,
                            )
                        )
            caller_source = (
                caller_rows[0][0] if len(caller_rows) == 1 else ""
            )
            caller_row = (
                caller_rows[0][2] if len(caller_rows) == 1 else None
            )
            caller_contribution = (
                caller_rows[0][1] if len(caller_rows) == 1 else None
            )
            target_source_from = str(
                getattr(candidate_target, "source_from", "") or ""
            )
            raw_source_files = getattr(
                candidate_target,
                "source_files",
                (),
            )
            source_files = (
                tuple(raw_source_files)
                if isinstance(raw_source_files, (list, tuple))
                else ()
            )
            source_files_well_formed = (
                isinstance(raw_source_files, (list, tuple))
                and all(
                    isinstance(source_file, str) and bool(source_file)
                    for source_file in source_files
                )
                and len(set(source_files)) == len(source_files)
            )
            has_source_from = bool(target_source_from)
            has_source_files = bool(source_files)
            caller_source_authority_converges = (
                (has_source_from or has_source_files)
                and (not has_source_from or target_source_from == caller_source)
                and (
                    not has_source_files
                    or source_files.count(caller_source) == 1
                )
            )
            if (
                candidate_target is None
                or getattr(candidate_target, "target_binary", "") != "recoil"
                or not bool(
                    getattr(
                        candidate_target,
                        "check_translation_unit_function_order",
                        False,
                    )
                )
                or not caller_manifest
                or Path(caller_manifest).resolve()
                == (REPO_ROOT / callee_manifest).resolve()
                or not caller_source
                or caller_source == callee_source
                or not source_files_well_formed
                or not caller_source_authority_converges
                or caller.defined_external_functions.count(caller.symbol)
                != 1
                or caller.symbol in caller.undefined_external_functions
                or caller_contribution is None
                or getattr(caller_contribution, "source_from", "")
                != caller_source
                or getattr(caller_contribution, "order_scope", "")
                != "authored"
                or getattr(caller_contribution, "inventory_only", None)
                is not False
                or tuple(
                    getattr(
                        caller_contribution,
                        "candidate_only_extras",
                        (),
                    )
                )
                != ()
                or caller_row is None
                or getattr(caller_row, "required_presence", False)
                is not True
                or getattr(caller_row, "pipeline_class", "")
                not in {"authored", "authored-lifecycle"}
                or getattr(caller_row, "source_order_gate", False)
                is not True
                or getattr(caller_row, "authored_order_role", "")
                != (
                    "authored-body"
                    if getattr(caller_row, "pipeline_class", "")
                    == "authored"
                    else "authored-lifecycle-body"
                )
                or getattr(caller_row, "full_order_gate", False)
                is not True
                or getattr(caller_row, "logical_identity_key", "")
                not in {None, ""}
                or getattr(caller_row, "icf_fold_status", "")
                not in {None, ""}
            ):
                raise ValueError(
                    "registered target symbol-regex cross-TU bridge lacks "
                    "one exact distinct compiled caller source signature for "
                    f"{candidate_name!r}"
                )

        expected_relocation_offsets = {
            instruction_offset + 1
            for _index, _instruction, instruction_offset, _opcode in instructions
        }
        actual_relocation_offsets = {
            relocation.offset for relocation in folded_relocations
        }
        if (
            len(expected_relocation_offsets) != len(instructions)
            or actual_relocation_offsets != expected_relocation_offsets
            or len(caller.data) != len(caller.relocation_mask)
        ):
            raise ValueError(
                "registered target symbol-regex bridge COD/COFF callsite "
                f"population does not correspond for {candidate_name!r}"
            )
        relocation_by_offset = {
            relocation.offset: relocation for relocation in folded_relocations
        }
        for (
            _instruction_index,
            instruction,
            instruction_offset,
            opcode,
        ) in instructions:
            relocation = relocation_by_offset[instruction_offset + 1]
            field_end = relocation.offset + 4
            relocations_at_offset = [
                item
                for item in caller.relocations
                if item.offset == relocation.offset
            ]
            exact_instruction_name = (
                _cod_space_bearing_direct_target(
                    _instruction_operand(instruction).strip(),
                    instruction.source_line,
                )
                if absolute_tu_local_bridge
                else _instruction_operand(instruction).strip()
            )
            if (
                exact_instruction_name != candidate_name
                or relocation.type != IMAGE_REL_I386_REL32
                or (
                    absolute_tu_local_definition_index is not None
                    and relocation.symbol_index
                    != absolute_tu_local_definition_index
                )
                or len(relocations_at_offset) != 1
                or relocation.offset < 1
                or field_end > len(caller.data)
                or field_end > len(caller.relocation_mask)
                or caller.data[relocation.offset - 1] != opcode
                or struct.unpack_from("<I", caller.data, relocation.offset)[0]
                != 0
                or not all(
                    caller.relocation_mask[index]
                    for index in range(relocation.offset, field_end)
                )
            ):
                raise ValueError(
                    "registered target symbol-regex bridge requires exact "
                    f"zero-addend fully masked E8/E9 REL32 evidence for "
                    f"{candidate_name!r}"
                )

        resolved[candidate_name] = identity
    return resolved


@dataclass(frozen=True)
class _Vc5NamespaceFunctionAbi:
    decorated_identity: str
    semantic_name: str
    calling_convention: str
    return_type: str
    parameter_types: tuple[str, ...]
    parameter_sizes: tuple[int, ...]
    parameter_stack_sizes: tuple[int, ...]

    @property
    def parameter_bytes(self) -> int:
        return sum(self.parameter_stack_sizes)


@dataclass(frozen=True)
class _RetailAuthoredNamespaceAbi:
    semantic_name: str
    address: str
    return_type: str
    parameter_types: tuple[str, ...]
    parameter_sizes: tuple[int, ...]
    cleanup_bytes: int


_VC5_NAMESPACE_PRIMITIVE_TYPES: dict[str, tuple[str, int, int]] = {
    # logical BN type width and x86 argument-stack slot width stay distinct.
    "D": ("char", 1, 4),
    "E": ("unsigned char", 1, 4),
    "F": ("short", 2, 4),
    "G": ("unsigned short", 2, 4),
    "H": ("int", 4, 4),
    "I": ("unsigned int", 4, 4),
    "J": ("long", 4, 4),
    "K": ("unsigned long", 4, 4),
    "M": ("float", 4, 4),
    "N": ("double", 8, 8),
    "O": ("long double", 8, 8),
}


def _decode_vc5_namespace_function_abi(
    decorated_identity: str,
) -> _Vc5NamespaceFunctionAbi | None:
    """Decode one bounded ordinary namespace-function VC5 ABI spelling.

    This intentionally excludes global C-style spellings, members, pointers,
    references, arrays, aggregates, varargs, and templates.  Those forms need
    their own exact proof rather than an optimistic partial demangle.
    """

    identity = str(decorated_identity)
    if not identity.startswith("?") or "@@Y" not in identity:
        return None
    head, encoded = identity[1:].split("@@Y", 1)
    components = head.split("@")
    if (
        len(components) < 2
        or any(
            re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", component) is None
            for component in components
        )
        or len(encoded) < 4
        or not encoded.endswith("Z")
    ):
        return None
    calling_convention = {
        "A": "__cdecl",
        "G": "__stdcall",
        "I": "__fastcall",
    }.get(encoded[0])
    return_type = (
        "void"
        if encoded[1] == "X"
        else _VC5_NAMESPACE_PRIMITIVE_TYPES.get(encoded[1], ("", 0, 0))[0]
    )
    if not calling_convention or not return_type:
        return None
    parameter_encoding = encoded[2:-1]
    if parameter_encoding == "X":
        parameter_codes = ""
    elif parameter_encoding.endswith("@"):
        parameter_codes = parameter_encoding[:-1]
    else:
        return None
    parameters = [
        _VC5_NAMESPACE_PRIMITIVE_TYPES.get(code)
        for code in parameter_codes
    ]
    if any(parameter is None for parameter in parameters):
        return None
    typed_parameters = [parameter for parameter in parameters if parameter]
    semantic_name = "::".join(
        (*reversed(components[1:]), components[0])
    )
    return _Vc5NamespaceFunctionAbi(
        decorated_identity=identity,
        semantic_name=semantic_name,
        calling_convention=calling_convention,
        return_type=return_type,
        parameter_types=tuple(parameter[0] for parameter in typed_parameters),
        parameter_sizes=tuple(parameter[1] for parameter in typed_parameters),
        parameter_stack_sizes=tuple(
            parameter[2] for parameter in typed_parameters
        ),
    )


def _retail_authored_namespace_abi(
    *,
    address: str,
    end_exclusive: str,
    semantic_name: str,
    bridge: BinaryNinjaBridge,
    cache: dict[tuple[str, str, str], _RetailAuthoredNamespaceAbi],
) -> _RetailAuthoredNamespaceAbi:
    """Read one exact BN name/prototype and unanimous retail RET contract."""

    key = (address, end_exclusive, semantic_name)
    cached = cache.get(key)
    if cached is not None:
        return cached

    assembly_payload = bridge.get_json("assembly", name=address)
    function = assembly_payload.get("function")
    function_symbol = (
        function.get("symbol") if isinstance(function, Mapping) else None
    )
    if (
        assembly_payload.get("truncated") is not False
        or not isinstance(function, Mapping)
        or normalize_address(str(function.get("address", ""))) != address
        or function.get("name") != semantic_name
        or function.get("raw_name") != semantic_name
        or not isinstance(function_symbol, Mapping)
        or function_symbol.get("type") != "SymbolType.FunctionSymbol"
        or function_symbol.get("full_name") != semantic_name
        or not isinstance(assembly_payload.get("assembly"), str)
    ):
        raise ValueError(
            "authored decorated ABI bridge requires one exact complete BN "
            f"function/name row for {semantic_name!r} at {address}"
        )
    instructions = tuple(
        parse_assembly(assembly_payload["assembly"], source="bn")
    )
    instruction_addresses: list[int] = []
    for instruction in instructions:
        raw_instruction_address = _source_instruction_address(instruction)
        if not raw_instruction_address:
            raise ValueError(
                "authored decorated ABI bridge requires complete address-labelled "
                f"retail assembly at {address}"
            )
        instruction_address = address_value(raw_instruction_address)
        instruction_end = instruction_address + len(instruction.bytes)
        if (
            instruction_address < address_value(address)
            or instruction_end > address_value(end_exclusive)
            or not instruction.bytes
        ):
            raise ValueError(
                "authored decorated ABI bridge retail assembly escapes its "
                f"governed extent at {address}"
            )
        instruction_addresses.append(instruction_address)
    if (
        not instructions
        or instruction_addresses[0] != address_value(address)
        or len(instruction_addresses) != len(set(instruction_addresses))
        or instruction_addresses != sorted(instruction_addresses)
    ):
        raise ValueError(
            "authored decorated ABI bridge requires one ordered complete "
            f"retail function body at {address}"
        )
    cleanup_rows: list[int] = []
    for instruction in instructions:
        mnemonic = _instruction_mnemonic(instruction)
        if mnemonic not in {"ret", "retn"}:
            continue
        operand = _instruction_operand(instruction).strip()
        try:
            cleanup = int(operand, 0) if operand else 0
        except ValueError as exc:
            raise ValueError(
                "authored decorated ABI bridge has malformed retail RET cleanup"
            ) from exc
        if (
            mnemonic not in {"ret", "retn"}
            or len(instruction.bytes) != 3
            or instruction.bytes[0].casefold() != "c2"
            or cleanup <= 0
            or cleanup > 0xFFFF
            or tuple(
                item.casefold() for item in instruction.bytes[1:]
            )
            != (f"{cleanup & 0xff:02x}", f"{cleanup >> 8:02x}")
        ):
            raise ValueError(
                "authored decorated ABI bridge requires exact callee-pop "
                f"retail RET encodings at {address}"
            )
        cleanup_rows.append(cleanup)
    if not cleanup_rows or len(set(cleanup_rows)) != 1:
        raise ValueError(
            "authored decorated ABI bridge requires unanimous nonzero retail "
            f"RET cleanup at {address}"
        )
    cleanup_bytes = cleanup_rows[0]

    stack_payload = bridge.get_json("getStackFrameVars", address=address)
    stack_rows = stack_payload.get("stack_frame_vars")
    exact_stack_rows = [
        row
        for row in stack_rows or []
        if isinstance(row, Mapping)
        and normalize_address(str(row.get("addr", ""))) == address
        and isinstance(row.get("vars"), list)
    ]
    if len(exact_stack_rows) != 1:
        raise ValueError(
            "authored decorated ABI bridge requires one exact BN stack "
            f"prototype at {address}"
        )
    variables = exact_stack_rows[0]["vars"]
    return_address_rows = [
        row
        for row in variables
        if isinstance(row, Mapping)
        and row.get("source_type") == "StackVariableSourceType"
        and row.get("storage") == 0
        and row.get("name") == "__return_addr"
        and str(row.get("size", "")).casefold() == "0x4"
        and row.get("type") == "void* const"
    ]
    parameter_rows: list[tuple[int, int, str]] = []
    for row in variables:
        if (
            not isinstance(row, Mapping)
            or row.get("source_type") != "StackVariableSourceType"
            or not isinstance(row.get("storage"), int)
            or int(row["storage"]) <= 0
        ):
            continue
        try:
            size = int(str(row.get("size", "0")), 0)
        except ValueError as exc:
            raise ValueError(
                "authored decorated ABI bridge has malformed BN parameter size"
            ) from exc
        if size > 0:
            parameter_rows.append(
                (int(row["storage"]), size, str(row.get("type", "")))
            )
    parameter_rows.sort()
    expected_offset = 4
    parameter_stack_sizes: list[int] = []
    for storage, size, _type in parameter_rows:
        if storage != expected_offset:
            raise ValueError(
                "authored decorated ABI bridge requires contiguous BN stack "
                f"parameters at {address}"
            )
        stack_size = max(size, 4)
        parameter_stack_sizes.append(stack_size)
        expected_offset += stack_size
    if (
        len(return_address_rows) != 1
        or len({row[0] for row in parameter_rows}) != len(parameter_rows)
        or expected_offset - 4 != cleanup_bytes
    ):
        raise ValueError(
            "authored decorated ABI bridge BN prototype disagrees with retail "
            f"cleanup at {address}"
        )

    return_payload = bridge.get_json("functionReturnRegs", address=address)
    return_registers = return_payload.get("return_registers")
    if (
        return_payload.get("status") != "ok"
        or return_payload.get("function") != semantic_name
        or normalize_address(str(return_payload.get("address", ""))) != address
        or not isinstance(return_registers, Mapping)
        or return_registers.get("registers") != []
        or return_registers.get("confidence") != 255
    ):
        raise ValueError(
            "authored decorated ABI bridge requires an exact high-confidence "
            f"void BN return prototype at {address}"
        )

    proof = _RetailAuthoredNamespaceAbi(
        semantic_name=semantic_name,
        address=address,
        return_type="void",
        parameter_types=tuple(row[2] for row in parameter_rows),
        parameter_sizes=tuple(row[1] for row in parameter_rows),
        cleanup_bytes=cleanup_bytes,
    )
    cache[key] = proof
    return proof


def _authored_decorated_abi_direct_candidate_bridges(
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    compiler_generated_bridges: Mapping[str, str],
    bridge: BinaryNinjaBridge,
    retail_abi_cache: dict[
        tuple[str, str, str], _RetailAuthoredNamespaceAbi
    ] | None = None,
) -> dict[str, str]:
    """Join an ABI-correct namespace decoration to one authored retail body.

    Candidate COD/COFF supplies only the proposed decorated spelling and exact
    relocation population.  Retail BN name/prototype/RET facts plus the current
    reviewed tracker symbol/source/block topology supply the target identity.
    """

    caller = candidate.caller_definition
    if caller is None:
        return {}
    cache = retail_abi_cache if retail_abi_cache is not None else {}
    invocations_by_name: dict[
        str, list[tuple[int, Instruction, int, int]]
    ] = {}
    for instruction_index, instruction in enumerate(candidate.instructions):
        mnemonic = _instruction_mnemonic(instruction)
        if mnemonic not in {"call", "jmp"}:
            continue
        name = _instruction_operand(instruction).strip()
        decoded = _decode_vc5_namespace_function_abi(name)
        if decoded is None or decoded.calling_convention != "__stdcall":
            continue
        if (
            name in indexes.by_candidate_name
            or name in bridge_names
            or name in compiler_generated_bridges
        ):
            continue
        raw_offset = _source_instruction_address(instruction)
        opcode = 0xE8 if mnemonic == "call" else 0xE9
        if (
            instruction_index in candidate.local_control_flow_indices
            or not raw_offset
            or tuple(item.casefold() for item in instruction.bytes)
            != (f"{opcode:02x}", "00", "00", "00", "00")
        ):
            raise ValueError(
                "authored decorated ABI bridge requires exact nonlocal "
                f"zero-addend E8/E9 COD evidence for {name!r}"
            )
        invocations_by_name.setdefault(name, []).append(
            (instruction_index, instruction, address_value(raw_offset), opcode)
        )
    if not invocations_by_name:
        return {}

    symbols = document.collection("symbols")
    blocks = document.collection("physical_blocks")
    targets = document.collection("verification_targets")
    resolved: dict[str, str] = {}
    for name, invocations in invocations_by_name.items():
        decoded = _decode_vc5_namespace_function_abi(name)
        assert decoded is not None
        folded_name = name.casefold()
        for label, names in (
            ("candidate identity", indexes.by_candidate_name),
            ("Binary Ninja identity", bridge_names),
            ("compiler/provider identity", compiler_generated_bridges),
            ("candidate storage identity", indexes.storage_by_name),
        ):
            collisions = sorted(
                value for value in names if value.casefold() == folded_name
            )
            if collisions:
                raise ValueError(
                    "authored decorated ABI bridge has a case-folded "
                    f"{label} conflict for {name!r}"
                )
        semantic_collisions = sorted(
            value
            for value in bridge_names
            if value.casefold() == decoded.semantic_name.casefold()
            and value != decoded.semantic_name
        )
        if semantic_collisions:
            raise ValueError(
                "authored decorated ABI bridge has a case-conflicting BN "
                f"semantic name for {decoded.semantic_name!r}"
            )
        raw_matches = bridge_names.get(decoded.semantic_name)
        matches = (
            list(raw_matches)
            if isinstance(raw_matches, (list, tuple, set, frozenset))
            else ([raw_matches] if raw_matches is not None else [])
        )
        exact_matches = [
            match
            for match in matches
            if getattr(match, "kind", "") == "function"
            and getattr(match, "name", "") == decoded.semantic_name
            and getattr(match, "raw_name", "") == decoded.semantic_name
            # The canonical /methods inventory omits top-level full_name for
            # ordinary functions even though the address-scoped function
            # payload below carries the exact nested FunctionSymbol name.
            # Accept only that omission here; a conflicting nonempty spelling
            # still fails, and _retail_authored_namespace_abi independently
            # requires the exact nested full name at the selected address.
            and getattr(match, "full_name", "")
            in ("", decoded.semantic_name)
        ]
        if not matches:
            continue
        if len(exact_matches) != 1 or len(matches) != 1:
            raise ValueError(
                "authored decorated ABI bridge requires one exact BN "
                f"semantic function for {decoded.semantic_name!r}"
            )
        address = normalize_address(str(exact_matches[0].address))
        identity = indexes.by_address.get(address, "")
        physical_symbols: list[tuple[str, Mapping[str, Any]]] = []
        for symbol_id, symbol in symbols.items():
            if not isinstance(symbol, Mapping) or symbol.get("kind") != "function":
                continue
            raw_address = symbol.get("address", symbol.get("start"))
            if not isinstance(raw_address, str):
                continue
            try:
                symbol_address = normalize_address(raw_address)
            except ProgressError:
                continue
            if symbol_address == address:
                physical_symbols.append((str(symbol_id), symbol))
        if len(physical_symbols) != 1:
            raise ValueError(
                "authored decorated ABI bridge requires one unique tracker "
                f"physical authored symbol at {address}"
            )
        symbol_id, symbol = physical_symbols[0]
        end_exclusive = symbol.get("end_exclusive")
        block_id = symbol.get("physical_block_id")
        block = blocks.get(str(block_id))
        order_facts = (
            block.get("accepted_order_facts")
            if isinstance(block, Mapping)
            else None
        )
        accepted_occurrences = 0
        for candidate_block in blocks.values():
            candidate_facts = (
                candidate_block.get("accepted_order_facts")
                if isinstance(candidate_block, Mapping)
                else None
            )
            if (
                not isinstance(candidate_facts, Mapping)
                or candidate_facts.get("phase")
                != "authored-function-order"
                or not isinstance(
                    candidate_facts.get("matched_identities"), list
                )
            ):
                continue
            accepted_occurrences += candidate_facts[
                "matched_identities"
            ].count(symbol_id)
        authored_order = (
            block.get("order", {}).get("authored", {})
            if isinstance(block, Mapping)
            and isinstance(block.get("order"), Mapping)
            else None
        )
        target_id = (
            order_facts.get("target_id")
            if isinstance(order_facts, Mapping)
            else None
        )
        target = targets.get(str(target_id))
        source_traceability = symbol.get("source_traceability")
        source_edges = (
            source_traceability.get("source_edges")
            if isinstance(source_traceability, Mapping)
            else None
        )
        exact_source_edges = [
            edge
            for edge in source_edges or []
            if isinstance(edge, Mapping)
            and edge.get("relation") == "defines"
            and isinstance(edge.get("anchor_id"), str)
            and bool(edge.get("anchor_id"))
            and isinstance(edge.get("emission_context"), Mapping)
            and isinstance(
                edge["emission_context"].get("translation_unit"), str
            )
            and bool(edge["emission_context"].get("translation_unit"))
        ]
        source_path = (
            exact_source_edges[0]["emission_context"]["translation_unit"]
            if len(exact_source_edges) == 1
            else ""
        )
        verification_target_ids = symbol.get("verification_target_ids")
        if (
            symbol_id != f"recoil:function:{address}"
            or identity != f"symbol:{symbol_id}"
            or identity in indexes.provider_ids
            or symbol.get("binary") != "recoil"
            or symbol.get("pipeline_class") != "authored"
            or symbol.get("disposition") != "unresolved"
            or symbol.get("authored_order_role") != "authored-body"
            or symbol.get("ownership_state") != "primary-owned"
            or symbol.get("logical_aliases") not in (None, {})
            or symbol.get("icf_address_group") is not None
            or symbol.get("linked_provider_binding") is not None
            or symbol.get("lifecycle_variant_of") is not None
            or symbol.get("extent_state") != "known"
            or symbol.get("output_section_id") != "recoil:section:.text"
            or symbol.get("navigation_name") != decoded.semantic_name
            or not isinstance(end_exclusive, str)
            or address_value(normalize_address(end_exclusive))
            <= address_value(address)
            or symbol.get("size")
            != address_value(normalize_address(end_exclusive))
            - address_value(address)
            or not isinstance(source_traceability, Mapping)
            or source_traceability.get("state") != "resolved"
            or source_traceability.get("reason_code") not in (None, "")
            or len(source_edges or []) != 1
            or len(exact_source_edges) != 1
            or not isinstance(block_id, str)
            or not isinstance(block, Mapping)
            or block.get("binary") != "recoil"
            or block.get("row_kind") != "physical-source-block"
            or block.get("contribution_kind") != "authored"
            or not isinstance(block.get("contribution_ids"), list)
            or block["contribution_ids"].count(symbol_id) != 1
            or block.get("agent_source_path") != source_path
            or block.get("source_path") != source_path
            or block.get("original_source_path") != source_path
            or not isinstance(order_facts, Mapping)
            or order_facts.get("phase") != "authored-function-order"
            or order_facts.get("validation_mode") != "live"
            or order_facts.get("target_id") != target_id
            or not isinstance(order_facts.get("covered_block_ids"), list)
            or order_facts["covered_block_ids"].count(block_id) != 1
            or not isinstance(order_facts.get("matched_identities"), list)
            or order_facts["matched_identities"].count(symbol_id) != 1
            or accepted_occurrences != 1
            or not isinstance(target_id, str)
            or not isinstance(target, Mapping)
            or target.get("binary") != "recoil"
            or target.get("kind") != "vc5"
            or not isinstance(verification_target_ids, list)
            or verification_target_ids.count(target_id) != 1
            or not isinstance(authored_order, Mapping)
            or any(
                not is_current_accepted_state(
                    authored_order.get(dimension)
                )
                for dimension in AUTHORED_ORDER_DIMENSIONS
            )
        ):
            raise ValueError(
                "authored decorated ABI bridge requires one exact authored "
                f"symbol/source edge/block/target at {address}"
            )

        retail_abi = _retail_authored_namespace_abi(
            address=address,
            end_exclusive=normalize_address(end_exclusive),
            semantic_name=decoded.semantic_name,
            bridge=bridge,
            cache=cache,
        )
        if (
            decoded.return_type != retail_abi.return_type
            or decoded.parameter_types != retail_abi.parameter_types
            or decoded.parameter_sizes != retail_abi.parameter_sizes
            or decoded.parameter_bytes != retail_abi.cleanup_bytes
        ):
            continue

        folded_symbols = [
            row
            for row in caller.coff_symbols
            if row.name.casefold() == folded_name
        ]
        folded_defined = [
            value
            for value in caller.defined_external_functions
            if value.casefold() == folded_name
        ]
        folded_undefined = [
            value
            for value in caller.undefined_external_functions
            if value.casefold() == folded_name
        ]
        if (
            len(folded_symbols) != 1
            or folded_symbols[0].name != name
            or folded_defined
            or folded_undefined != [name]
        ):
            raise ValueError(
                "authored decorated ABI bridge requires one exact undefined "
                f"COFF function symbol for {name!r}"
            )
        external = folded_symbols[0]
        if (
            external.value != 0
            or external.section_number != 0
            or external.symbol_type != 0x20
            or external.storage_class != IMAGE_SYM_CLASS_EXTERNAL
            or external.aux_count != 0
            or external.weak_external_tag_index is not None
            or external.weak_external_characteristics is not None
            or external.section_name
            or external.section_size != 0
            or external.section_characteristics != 0
            or external.natural_end != 0
        ):
            raise ValueError(
                "authored decorated ABI bridge rejects defined, weak, aliased, "
                f"or malformed COFF identity for {name!r}"
            )
        folded_relocations = [
            relocation
            for relocation in caller.relocations
            if relocation.symbol_name.casefold() == folded_name
        ]
        expected_offsets = {
            instruction_offset + 1
            for _index, _instruction, instruction_offset, _opcode in invocations
        }
        if (
            len(folded_relocations) != len(invocations)
            or len(expected_offsets) != len(invocations)
            or {row.offset for row in folded_relocations} != expected_offsets
            or len(caller.data) != len(caller.relocation_mask)
            or caller.section_index <= 0
            or caller.section_end - caller.section_start != len(caller.data)
        ):
            raise ValueError(
                "authored decorated ABI bridge requires one exact candidate "
                f"COFF relocation per invocation of {name!r}"
            )
        relocation_by_offset = {
            relocation.offset: relocation for relocation in folded_relocations
        }
        for _index, instruction, instruction_offset, opcode in invocations:
            relocation = relocation_by_offset[instruction_offset + 1]
            field_end = relocation.offset + 4
            if (
                _instruction_operand(instruction).strip() != name
                or relocation.type != IMAGE_REL_I386_REL32
                or relocation.symbol_name != name
                or relocation.symbol_index != external.index
                or sum(
                    1
                    for row in caller.relocations
                    if row.offset == relocation.offset
                )
                != 1
                or relocation.offset < 1
                or field_end > len(caller.data)
                or field_end > len(caller.relocation_mask)
                or caller.data[relocation.offset - 1] != opcode
                or struct.unpack_from("<I", caller.data, relocation.offset)[0]
                != 0
                or caller.relocation_mask[relocation.offset - 1]
                or not all(
                    caller.relocation_mask[index]
                    for index in range(relocation.offset, field_end)
                )
            ):
                raise ValueError(
                    "authored decorated ABI bridge requires exact zero-addend "
                    f"fully masked E8/E9 REL32 provenance for {name!r}"
                )
        resolved[name] = identity
    return resolved


def _registered_decorated_target_direct_candidate_bridges(
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    compiler_generated_bridges: Mapping[str, str],
) -> dict[str, str]:
    """Join exact unresolved decorated calls to registered target identities.

    Some focused VC5 targets publish their literal decorated callable only in
    the governed manifest.  The synchronized tracker projection still carries
    the target, exact address, and physical symbol membership, but deliberately
    omits a function-row spelling when the target is not an order target.  This
    candidate-scoped bridge rejoins those two independent halves without using
    candidate output as expected truth: COD/COFF proves only the exact external
    call spelling and callsites, while the manifest/tracker join supplies the
    existing callable identity.  Every ambiguity or stale relationship fails
    closed.
    """

    caller = candidate.caller_definition
    if caller is None:
        return {}

    invocations_by_name: dict[
        str, list[tuple[int, Instruction, int, int]]
    ] = {}
    for instruction_index, instruction in enumerate(candidate.instructions):
        mnemonic = _instruction_mnemonic(instruction)
        if mnemonic not in {"call", "jmp"}:
            continue
        name = _instruction_operand(instruction).strip()
        if DECORATED_RE.fullmatch(name) is None:
            continue
        if (
            name in indexes.by_candidate_name
            or name in bridge_names
            or name in compiler_generated_bridges
        ):
            continue
        raw_offset = _source_instruction_address(instruction)
        opcode = 0xE8 if mnemonic == "call" else 0xE9
        if (
            instruction_index in candidate.local_control_flow_indices
            or not raw_offset
            or len(instruction.bytes) != 5
            or tuple(value.lower() for value in instruction.bytes)
            != (f"{opcode:02x}", "00", "00", "00", "00")
        ):
            raise ValueError(
                "registered decorated-target bridge requires exact nonlocal "
                f"zero-addend E8/E9 COD evidence for {name!r}"
            )
        invocations_by_name.setdefault(name, []).append(
            (
                instruction_index,
                instruction,
                address_value(raw_offset),
                opcode,
            )
        )

    if not invocations_by_name:
        return {}

    root = REPO_ROOT.resolve()
    manifest_root = (root / "tools" / "vc5_verify_targets").resolve()
    symbols = document.collection("symbols")
    targets = document.collection("verification_targets")
    resolved: dict[str, str] = {}
    for name, invocations in invocations_by_name.items():
        folded_name = name.casefold()
        for label, names in (
            ("candidate index", indexes.by_candidate_name),
            ("Binary Ninja name", bridge_names),
            ("compiler/provider bridge", compiler_generated_bridges),
            ("candidate storage", indexes.storage_by_name),
        ):
            collisions = sorted(
                value for value in names if value.casefold() == folded_name
            )
            if collisions:
                raise ValueError(
                    "registered decorated-target bridge has a case-folded "
                    f"{label} collision for {name!r}: "
                    + ", ".join(repr(value) for value in collisions)
                )

        suppliers: list[
            tuple[str, str, str, Mapping[str, Any], Any]
        ] = []
        for target_id, target_row in targets.items():
            if (
                not isinstance(target_row, Mapping)
                or target_row.get("binary") != "recoil"
                or target_row.get("kind") != "vc5"
            ):
                continue
            registration = target_row.get("registration")
            manifest_value = (
                registration.get("manifest_path")
                if isinstance(registration, Mapping)
                else None
            )
            if not isinstance(manifest_value, str) or not manifest_value:
                continue
            manifest_path = Path(manifest_value)
            if not manifest_path.is_absolute():
                manifest_path = root / manifest_path
            try:
                manifest_path = manifest_path.resolve()
                manifest_path.relative_to(manifest_root)
                before = manifest_path.stat()
                raw_manifest = json.loads(
                    manifest_path.read_text(encoding="utf-8")
                )
                after = manifest_path.stat()
            except (OSError, ValueError, json.JSONDecodeError):
                continue
            if (
                int(before.st_size) != int(after.st_size)
                or int(before.st_mtime_ns) != int(after.st_mtime_ns)
                or not isinstance(raw_manifest, Mapping)
            ):
                raise ValueError(
                    "registered decorated-target manifest changed during "
                    f"identity routing: {manifest_value}"
                )
            raw_name_rows = [
                row
                for row in raw_manifest.get("functions", [])
                if isinstance(row, Mapping)
                and isinstance(row.get("symbol"), str)
                and row["symbol"].casefold() == folded_name
            ]
            if not raw_name_rows:
                continue
            if (
                len(raw_name_rows) != 1
                or raw_name_rows[0].get("symbol") != name
            ):
                raise ValueError(
                    "registered decorated-target manifest has duplicate or "
                    f"case-conflicting identity for {name!r}: {manifest_value}"
                )

            try:
                live_target = _call_contract_cached_manifest(
                    document, manifest_path
                )
            except (OSError, ProgressError, ValueError) as exc:
                raise ValueError(
                    "registered decorated-target manifest cannot supply an "
                    f"exact live target for {name!r}: {manifest_value}: {exc}"
                ) from exc
            live_rows = [
                row
                for row in tuple(getattr(live_target, "functions", ()))
                if str(getattr(row, "symbol", "")).casefold()
                == folded_name
            ]
            if (
                len(live_rows) != 1
                or str(getattr(live_rows[0], "symbol", "")) != name
                or getattr(live_rows[0], "symbol_regex", None) is not None
            ):
                raise ValueError(
                    "registered decorated-target live manifest has missing, "
                    f"duplicate, or conflicting identity for {name!r}"
                )
            live_row = live_rows[0]
            try:
                address = normalize_address(str(getattr(live_row, "address", "")))
            except ProgressError as exc:
                raise ValueError(
                    "registered decorated-target live manifest has an invalid "
                    f"address for {name!r}"
                ) from exc
            symbol_id = f"recoil:function:{address}"
            function_addresses = registration.get("function_addresses")
            target_symbol_ids = target_row.get("symbol_ids")
            unresolved_addresses = target_row.get("unresolved_addresses")
            try:
                registered_count = sum(
                    1
                    for raw_address in function_addresses or []
                    if isinstance(raw_address, str)
                    and normalize_address(raw_address) == address
                )
            except ProgressError as exc:
                raise ValueError(
                    "registered decorated-target tracker projection has an "
                    f"invalid function address for {name!r}"
                ) from exc
            if (
                str(target_id)
                != f"recoil:vc5-target:{getattr(live_target, 'name', '')}"
                or target_row.get("name")
                != str(getattr(live_target, "name", ""))
                or str(getattr(live_target, "target_binary", "")) != "recoil"
                or Path(str(getattr(live_target, "manifest_path", ""))).resolve()
                != manifest_path
                or raw_manifest.get("name") != target_row.get("name")
                or registered_count != 1
                or not isinstance(target_symbol_ids, list)
                or target_symbol_ids.count(symbol_id) != 1
                or unresolved_addresses != []
                or getattr(live_row, "required_presence", None) is not True
            ):
                raise ValueError(
                    "registered decorated-target identity has stale target, "
                    f"address, presence, or symbol membership for {name!r}"
                )
            identity = indexes.by_address.get(address, "")
            if not identity:
                raise ValueError(
                    "registered decorated-target identity has no unique "
                    f"tracker callable at {address} for {name!r}"
                )
            suppliers.append(
                (str(target_id), address, identity, target_row, live_row)
            )

        if not suppliers:
            continue
        physical_identities = {
            (address, identity) for _target_id, address, identity, _target, _row in suppliers
        }
        if len(physical_identities) != 1:
            raise ValueError(
                "ambiguous registered decorated-target identity for "
                f"{name!r}: "
                + ", ".join(
                    sorted(
                        f"{target_id}@{address}={identity}"
                        for target_id, address, identity, _target, _row in suppliers
                    )
                )
            )
        address, identity = next(iter(physical_identities))
        physical_symbols: list[tuple[str, Mapping[str, Any]]] = []
        for symbol_id, symbol in symbols.items():
            if not isinstance(symbol, Mapping):
                continue
            raw_address = symbol.get("address", symbol.get("start"))
            if not isinstance(raw_address, str):
                continue
            try:
                symbol_address = normalize_address(raw_address)
            except ProgressError:
                continue
            if symbol_address == address:
                physical_symbols.append((str(symbol_id), symbol))
        if len(physical_symbols) != 1:
            raise ValueError(
                "registered decorated-target bridge requires one exact "
                f"physical callable at {address} for {name!r}"
            )
        symbol_id, symbol = physical_symbols[0]
        end_exclusive = symbol.get("end_exclusive")
        size = symbol.get("size")
        verification_target_ids = symbol.get("verification_target_ids")
        supplier_target_ids = {row[0] for row in suppliers}
        if (
            symbol_id != f"recoil:function:{address}"
            or _symbol_identity(symbol_id, symbol) != identity
            or symbol.get("binary") != "recoil"
            or symbol.get("kind")
            not in {"function", "provider-function", "compiler-function"}
            or symbol.get("ownership_state") != "primary-owned"
            or symbol.get("extent_state") != "known"
            or symbol.get("output_section_id") != "recoil:section:.text"
            or not isinstance(end_exclusive, str)
            or address_value(normalize_address(end_exclusive))
            <= address_value(address)
            or size
            != address_value(normalize_address(end_exclusive))
            - address_value(address)
            or not isinstance(verification_target_ids, list)
            or any(
                verification_target_ids.count(target_id) != 1
                for target_id in supplier_target_ids
            )
            or (identity in indexes.provider_ids) != identity.startswith("provider:")
        ):
            raise ValueError(
                "registered decorated-target bridge lacks the exact physical "
                f"identity, extent, provider class, or target membership at "
                f"{address} for {name!r}"
            )

        folded_relocations = [
            relocation
            for relocation in caller.relocations
            if relocation.symbol_name.casefold() == folded_name
        ]
        folded_defined = [
            value
            for value in caller.defined_external_functions
            if value.casefold() == folded_name
        ]
        folded_undefined = [
            value
            for value in caller.undefined_external_functions
            if value.casefold() == folded_name
        ]
        expected_offsets = {
            instruction_offset + 1
            for _index, _instruction, instruction_offset, _opcode in invocations
        }
        if (
            len(folded_relocations) != len(invocations)
            or any(row.symbol_name != name for row in folded_relocations)
            or folded_defined
            or folded_undefined != [name]
            or len(expected_offsets) != len(invocations)
            or {row.offset for row in folded_relocations} != expected_offsets
            or len(caller.data) != len(caller.relocation_mask)
        ):
            raise ValueError(
                "registered decorated-target bridge requires one exact "
                "undefined COFF external and one exact caller relocation per "
                f"COD invocation of {name!r}"
            )
        relocation_by_offset = {
            relocation.offset: relocation for relocation in folded_relocations
        }
        for _index, instruction, instruction_offset, opcode in invocations:
            relocation = relocation_by_offset[instruction_offset + 1]
            field_end = relocation.offset + 4
            if (
                _instruction_operand(instruction).strip() != name
                or relocation.type != IMAGE_REL_I386_REL32
                or sum(
                    1
                    for row in caller.relocations
                    if row.offset == relocation.offset
                )
                != 1
                or relocation.offset < 1
                or field_end > len(caller.data)
                or field_end > len(caller.relocation_mask)
                or caller.data[relocation.offset - 1] != opcode
                or struct.unpack_from("<I", caller.data, relocation.offset)[0]
                != 0
                or caller.relocation_mask[relocation.offset - 1]
                or not all(
                    caller.relocation_mask[index]
                    for index in range(relocation.offset, field_end)
                )
            ):
                raise ValueError(
                    "registered decorated-target bridge requires exact "
                    f"zero-addend fully masked E8/E9 REL32 evidence for {name!r}"
                )
        resolved[name] = identity
    return resolved


_R4575_ZRENDER_STATIC_COMPARISON_ONLY_CALLABLES = frozenset({
    "zVideoFxPass3ClampCurrentRadius",
    "FxLineOutCode",
    "zRndrSpanDepthAtXByPartsLocal",
    "BlendLensFlarePixel",
    "CommitFogParamsIfChanged",
    "SpanTex16SampleIndex",
    "FogBlendPixel565",
    "FogBlendPixel555",
    "BlendPixel565Alpha8",
    "BlendPixel555Alpha8",
    "BlendPixel555ConstAlphaMap",
    "FogBlendPair565",
    "FogBlendPair555",
    "zVideoFxPass3ApproxRadiusIndex",
    "TruncateFloat",
})


def _r4578_zrender_static_comparison_callable(value: str) -> str:
    """Decode only the reviewed zrndr_draw STATIC helper spellings.

    VC5 COFF contains the fully decorated symbol, while the earlier bridge
    compared that symbol to a bare source name and therefore never selected
    STATIC handling.  Anonymous-namespace helpers additionally retain the
    exact absolute zrndr_draw.c scope (including VC5's percent marker); the
    three scoped helpers have exact class/global decorations.  No looser
    basename or suffix match is accepted.
    """

    if value in _R4575_ZRENDER_STATIC_COMPARISON_ONLY_CALLABLES:
        # Retain the already-reviewed unsuffixed STATIC spelling; r4578 adds
        # the actual VC5 decorated spellings without changing that contract.
        return value
    exact_scoped = {
        "?zVideoFxPass3ClampCurrentRadius@zVideo@@YIHHH@Z": (
            "zVideoFxPass3ClampCurrentRadius"
        ),
        "?FxLineOutCode@zVideo_FxSurface@@YIHHHHHHH@Z": "FxLineOutCode",
        "?zRndrSpanDepthAtXByPartsLocal@@YIMHMMH@Z": (
            "zRndrSpanDepthAtXByPartsLocal"
        ),
        "?zVideoFxPass3ApproxRadiusIndex@zVideo@@YIHHH@Z": (
            "zVideoFxPass3ApproxRadiusIndex"
        ),
        "?TruncateFloat@zVideo_FxSurface@@YIHM@Z": "TruncateFloat",
    }
    exact = exact_scoped.get(value)
    if exact is not None:
        return exact
    anonymous_suffixes = {
        "BlendLensFlarePixel": "YIGGGH@Z",
        "CommitFogParamsIfChanged": "YIXABUFogParamsPartial@2@@Z",
        "SpanTex16SampleIndex": "YIHHHHH@Z",
        "FogBlendPixel565": "YIGGI@Z",
        "FogBlendPixel555": "YIGGI@Z",
        "BlendPixel565Alpha8": "YIGGGH@Z",
        "BlendPixel555Alpha8": "YIGGGH@Z",
        "BlendPixel555ConstAlphaMap": "YIGGGH@Z",
        "FogBlendPair565": "YIIII@Z",
        "FogBlendPair555": "YIIII@Z",
    }
    for name, suffix in anonymous_suffixes.items():
        match = re.fullmatch(
            rf"\?{re.escape(name)}@\?%"
            rf"(?P<source>[A-Za-z]:\\[^@\r\n]+\\src\\GameZRecoil\\"
            rf"zRender\\zrndr_draw\.c)"
            rf"(?P<discriminator>[0-9]+)@zRndr@@{re.escape(suffix)}",
            value,
        )
        if match is not None:
            source = PureWindowsPath(match.group("source"))
            if (
                source.name == "zrndr_draw.c"
                and tuple(part.casefold() for part in source.parts[-4:])
                == ("src", "gamezrecoil", "zrender", "zrndr_draw.c")
                and match.group("discriminator").isdigit()
            ):
                return name
    return ""


def _candidate_local_coff_callable_bridges(
    candidate: CandidateAssembly,
    *,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    compiler_generated_bridges: Mapping[str, str],
) -> dict[str, str]:
    """Expose exact unreviewed same-object callables as comparison-only rows.

    A freshly compiled object may contain an inline/COMDAT helper which has no
    retail, tracker, import, or provider identity because retail emitted no such
    call at all.  Blocking extraction in that case hides the useful semantic
    divergence.  This bridge therefore creates only a candidate-local identity
    after proving the exact defining COFF symbol and every direct caller
    relocation.  The identity cannot satisfy retail comparison and grants no
    durable or reviewed state.
    """

    caller = candidate.caller_definition
    if caller is None or not caller.coff_symbols:
        return {}
    if (
        caller.section_index <= 0
        or caller.section_start < 0
        or caller.section_end <= caller.section_start
        or caller.section_end - caller.section_start != len(caller.data)
        or len(caller.relocation_mask) != len(caller.data)
    ):
        raise ValueError(
            "candidate-local COFF callable bridge requires one exact caller "
            "section and body extent"
        )

    invocations_by_name: dict[str, list[tuple[int, Instruction, int, int]]] = {}
    # Only COFF function definitions can seed comparison-only callable
    # identities.  VC5 also emits section-defined type-0 LABEL symbols (for
    # example ``$L73374``) for ordinary intra-function branches and switch
    # table entries.  Those labels remain caller-local control flow; treating
    # every positive-section symbol as callable makes an exact short JMP look
    # like a malformed tail call before the contract extractor can prove its
    # encoded, contained destination.
    defined_function_names = {
        row.name
        for row in caller.coff_symbols
        if row.section_number > 0 and row.symbol_type == 0x20
    }
    defined_coff_casefolds = {
        name.casefold() for name in defined_function_names
    }
    normalized_callable_name_by_cod_operand: dict[
        str, tuple[str, str]
    ] = {}
    for object_name in defined_function_names:
        normalized_cod_name = _vc5_compiler_normalized_cod_proc_symbol(
            object_name
        )
        if normalized_cod_name is not None:
            if normalized_cod_name in defined_function_names:
                raise ValueError(
                    "candidate-local COFF callable bridge normalized COD name "
                    f"{normalized_cod_name!r} collides with an exact COFF symbol"
                )
            route = (normalized_cod_name, object_name)
            prior_route = normalized_callable_name_by_cod_operand.get(
                normalized_cod_name.casefold()
            )
            if prior_route not in {None, route}:
                raise ValueError(
                    "candidate-local COFF callable bridge has an ambiguous or "
                    "case-conflicting normalized COD population for "
                    f"{normalized_cod_name!r}"
                )
            normalized_callable_name_by_cod_operand[
                normalized_cod_name.casefold()
            ] = route
    for instruction_index, instruction in enumerate(candidate.instructions):
        mnemonic = _instruction_mnemonic(instruction)
        if mnemonic not in {"call", "jmp"}:
            continue
        operand = _instruction_operand(instruction).strip()
        callable_route = normalized_callable_name_by_cod_operand.get(
            operand.casefold()
        )
        if operand in defined_function_names:
            object_name = operand
        elif callable_route is not None:
            expected_cod_operand, object_name = callable_route
            if operand != expected_cod_operand:
                raise ValueError(
                    "candidate-local COFF callable bridge has a case-conflicting "
                    f"COD operand for {object_name!r}"
                )
        elif operand.casefold() in defined_coff_casefolds:
            # Preserve the established exact-definition population proof below
            # for ordinary case-conflicting symbols.  Only the reviewed VC5
            # percent-marker spelling uses the normalized route above.
            object_name = operand
        else:
            continue
        raw_offset = _source_instruction_address(instruction)
        opcode = 0xE8 if mnemonic == "call" else 0xE9
        if (
            instruction_index in candidate.local_control_flow_indices
            or not raw_offset
            or len(instruction.bytes) != 5
            or tuple(value.lower() for value in instruction.bytes)
            != (f"{opcode:02x}", "00", "00", "00", "00")
        ):
            raise ValueError(
                "candidate-local COFF callable bridge requires exact nonlocal "
                f"zero-addend E8/E9 COD evidence for {operand!r}"
            )
        invocations_by_name.setdefault(object_name, []).append(
            (
                instruction_index,
                instruction,
                address_value(raw_offset),
                opcode,
            )
        )

    result: dict[str, str] = {}
    for name, invocations in invocations_by_name.items():
        # Existing exact authorities keep their normal resolver.  A differently
        # cased authority is never allowed to be silently shadowed by a local
        # object symbol.
        exact_authorities = (
            name in indexes.by_candidate_name,
            name in bridge_names,
            name in compiler_generated_bridges,
        )
        is_vector_destroy = name.startswith(
            MSVC_VECTOR_DESTROY_PREFIX
        )
        is_hud_panel_layout_vector_destroy = (
            name == HUD_PANEL_LAYOUT_VECTOR_DESTROY_SYMBOL
        )
        is_noop_vector_destroy = (
            is_vector_destroy
            and not is_hud_panel_layout_vector_destroy
        )
        is_hud_cmd_binding_ptr_vector_erase = (
            name == HUD_CMD_BINDING_PTR_VECTOR_ERASE_SYMBOL
        )
        is_reviewed_candidate_local_provider = (
            is_noop_vector_destroy
            or is_hud_panel_layout_vector_destroy
            or is_hud_cmd_binding_ptr_vector_erase
        )
        if any(exact_authorities) and not is_reviewed_candidate_local_provider:
            continue
        folded_name = name.casefold()
        for label, names in (
            ("candidate identity", indexes.by_candidate_name),
            ("Binary Ninja identity", bridge_names),
            ("compiler/provider identity", compiler_generated_bridges),
            ("candidate storage identity", indexes.storage_by_name),
        ):
            collisions = sorted(
                item
                for item in names
                if item.casefold() == folded_name and item != name
            )
            if collisions:
                raise ValueError(
                    "candidate-local COFF callable bridge has a case-folded "
                    f"{label} conflict for {name!r}: "
                    + ", ".join(repr(item) for item in collisions)
                )
        if name in indexes.storage_by_name or "__imp_" in name:
            raise ValueError(
                "candidate-local COFF callable bridge conflicts with import "
                f"or storage identity for {name!r}"
            )

        folded_defined = [
            item
            for item in caller.defined_external_functions
            if item.casefold() == folded_name
        ]
        folded_undefined = [
            item
            for item in caller.undefined_external_functions
            if item.casefold() == folded_name
        ]
        static_comparison_name = _r4578_zrender_static_comparison_callable(
            name
        )
        static_comparison_only = bool(
            static_comparison_name
            and static_comparison_name
            in _R4575_ZRENDER_STATIC_COMPARISON_ONLY_CALLABLES
        )
        if (
            (folded_defined != [name] or folded_undefined)
            if not static_comparison_only
            else bool(folded_defined or folded_undefined)
        ):
            raise ValueError(
                "candidate-local COFF callable bridge requires one exact "
                "defined external callable population and no undefined, duplicate, or "
                f"case-folded external for {name!r}"
            )

        folded_symbols = [
            row
            for row in caller.coff_symbols
            if row.name.casefold() == folded_name
        ]
        if len(folded_symbols) != 1 or folded_symbols[0].name != name:
            raise ValueError(
                "candidate-local COFF callable bridge requires one exact, "
                f"non-duplicate defining symbol for {name!r}"
            )
        definition = folded_symbols[0]
        weak_aliases = [
            row
            for row in caller.coff_symbols
            if row.storage_class == 105
            and (
                row.name.casefold() == folded_name
                or row.weak_external_tag_index == definition.index
            )
        ]
        coincident_callables = [
            row
            for row in caller.coff_symbols
            if row.index != definition.index
            and row.section_number == definition.section_number
            and row.value == definition.value
            and row.symbol_type == 0x20
        ]
        if weak_aliases or coincident_callables:
            raise ValueError(
                "candidate-local COFF callable bridge rejects weak, alias, or "
                f"coincident callable identity for {name!r}"
            )
        if (
            definition.section_number <= 0
            or definition.storage_class
            != (
                IMAGE_SYM_CLASS_STATIC
                if static_comparison_only
                else IMAGE_SYM_CLASS_EXTERNAL
            )
            or definition.symbol_type != 0x20
            or not definition.section_name
            or definition.section_size <= 0
            or not (definition.section_characteristics & IMAGE_SCN_CNT_CODE)
            or definition.value < 0
            or definition.natural_end <= definition.value
            or definition.natural_end > definition.section_size
        ):
            raise ValueError(
                "candidate-local COFF callable bridge requires an exact "
                "external function in the caller code section with a positive "
                f"well-formed extent for {name!r}"
            )

        matching_relocations = [
            relocation
            for relocation in caller.relocations
            if relocation.symbol_name.casefold() == folded_name
        ]
        expected_offsets = [
            instruction_offset + 1
            for _index, _instruction, instruction_offset, _opcode in invocations
        ]
        if (
            len(matching_relocations) != len(invocations)
            or len(set(expected_offsets)) != len(expected_offsets)
            or sorted(relocation.offset for relocation in matching_relocations)
            != sorted(expected_offsets)
        ):
            raise ValueError(
                "candidate-local COFF callable bridge requires one exact "
                f"ordered caller relocation per invocation of {name!r}"
            )
        relocation_by_offset = {
            relocation.offset: relocation
            for relocation in matching_relocations
        }
        opcode_by_relocation_offset = {
            instruction_offset + 1: opcode
            for _index, _instruction, instruction_offset, opcode in invocations
        }
        for expected_offset in expected_offsets:
            relocation = relocation_by_offset[expected_offset]
            relative = relocation.offset - caller.section_start
            if (
                relocation.type != IMAGE_REL_I386_REL32
                or relocation.symbol_name != name
                or relocation.symbol_index != definition.index
                or relative <= 0
                or relative + 4 > len(caller.data)
                or caller.data[relative - 1]
                != opcode_by_relocation_offset[expected_offset]
                or struct.unpack_from("<I", caller.data, relative)[0] != 0
                or caller.relocation_mask[relative - 1]
                or not all(
                    caller.relocation_mask[index]
                    for index in range(relative, relative + 4)
                )
            ):
                raise ValueError(
                    "candidate-local COFF callable bridge requires exact "
                    "REL32 target, zero addend, opcode mask, and defining "
                    f"symbol provenance for {name!r}"
                )

        if is_noop_vector_destroy:
            # A same-object VC5 vector<T>::_Destroy definition can be the
            # candidate spelling of the unique reviewed retail no-op provider,
            # but its decoration alone is not provider evidence.  Require the
            # independently parsed natural COFF definition to contain only the
            # three-byte return body and exact VC5 NOP padding, canonical VC5
            # header provenance, and no relocations before allowing the
            # reviewed supplier/tracker/BN identity resolver to arbitrate it.
            helper_definition = candidate.tu_local_function_definitions.get(
                name
            )
            destroy_match = MSVC_VECTOR_NOOP_DESTROY_RE.fullmatch(name)
            if (
                destroy_match is not None
                and destroy_match.group("element") == "H"
            ):
                if _player_ob1_require_exact_caller_package(
                    candidate,
                    caller_identity="symbol:recoil:function:0x42a2c0",
                    caller_start="0x42a2c0",
                    caller_end_exclusive="0x42a480",
                ) is None:
                    raise ValueError(
                        "value-vector no-op destroy is allowed only by the "
                        "exact Player /Ob1 int-vector caller package"
                    )
                _player_ob1_require_int_vector_helpers(candidate)
            same_section_external_symbols = tuple(
                row.name
                for row in caller.coff_symbols
                if row.section_number == definition.section_number
                and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
            )
            expected_destroy_comdat = b"\xc2\x08\x00" + (b"\x90" * 13)
            try:
                provenance = Path(helper_definition.source_provenance).resolve()
                include_root = (
                    compiler_env_path(candidate.target, DEFAULT_VC5_ENV)
                    .resolve()
                    .parent
                    / "VC"
                    / "INCLUDE"
                ).resolve()
                provenance.relative_to(include_root)
            except (AttributeError, OSError, ValueError, TypeError) as exc:
                raise ValueError(
                    "candidate-local no-op vector destroy provider "
                    "arbitration requires exact canonical VC5 include COD "
                    "provenance"
                ) from exc
            if (
                helper_definition is None
                or helper_definition.symbol != name
                or helper_definition.data != expected_destroy_comdat
                or helper_definition.relocations
                or helper_definition.relocation_mask
                != ((False,) * len(expected_destroy_comdat))
                or helper_definition.section_size
                != len(expected_destroy_comdat)
                or helper_definition.section_external_functions != (name,)
                or helper_definition.section_is_comdat is not True
                or helper_definition.comdat_selection != 2
                or same_section_external_symbols != (name,)
                or definition.value != 0
                or definition.natural_end != len(expected_destroy_comdat)
                or definition.section_size != len(expected_destroy_comdat)
                or not (
                    definition.section_characteristics
                    & IMAGE_SCN_LNK_COMDAT
                )
            ):
                raise ValueError(
                    "candidate-local no-op vector destroy provider "
                    "arbitration requires one exact external, unaliased VC5 "
                    "COMDAT with a natural C2 08 00 body, exact NOP-padded "
                    "extent, and an empty relocation population for "
                    f"{name!r}"
                )
            result[name] = _pointer_vector_destroy_provider_identity(
                name,
                indexes=indexes,
                bridge_names=bridge_names,
                compiler_generated_bridges=compiler_generated_bridges,
                allow_proven_value_noop=True,
            )
            continue

        if is_hud_panel_layout_vector_destroy:
            # This value-vector specialization is not the established
            # pointer/no-op provider.  Preserve its exact same-object COMDAT
            # as a comparison-only sentinel; the later retail-scoped arbiter
            # alone may replace it after proving the independent 0x409b60
            # provider extent, body, relocation, and destructor target.
            identity = f"candidate-local-coff:{name}"
            if (
                identity in indexes.provider_ids
                or identity in indexes.by_address.values()
                or identity in indexes.by_candidate_name.values()
                or identity in compiler_generated_bridges.values()
            ):
                raise ValueError(
                    "HUD panel-layout vector destroy comparison-only identity "
                    "conflicts with reviewed candidate/provider state"
                )
            result[name] = identity
            continue

        if is_hud_cmd_binding_ptr_vector_erase:
            # The candidate emits the exact reviewed erase implementation as a
            # same-object SELECT_ANY COMDAT.  A matching decoration alone is
            # insufficient: prove the complete retail-derived body, exact VC5
            # padding/extent, relocation-free definition, and unaliased COFF
            # population before consulting the reviewed provider supplier.
            helper_definition = candidate.tu_local_function_definitions.get(
                name
            )
            same_section_external_symbols = tuple(
                row.name
                for row in caller.coff_symbols
                if row.section_number == definition.section_number
                and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
            )
            expected_erase_comdat = (
                HUD_CMD_BINDING_PTR_VECTOR_ERASE_RETAIL_BODY
                + (b"\x90" * 14)
            )
            if (
                helper_definition is None
                or helper_definition.symbol != name
                or helper_definition.data != expected_erase_comdat
                or helper_definition.relocations
                or helper_definition.relocation_mask
                != ((False,) * len(expected_erase_comdat))
                or helper_definition.section_size
                != len(expected_erase_comdat)
                or helper_definition.section_external_functions != (name,)
                or helper_definition.section_is_comdat is not True
                or helper_definition.comdat_selection != 2
                or same_section_external_symbols != (name,)
                or definition.value != 0
                or definition.natural_end != len(expected_erase_comdat)
                or definition.section_size != len(expected_erase_comdat)
                or not (
                    definition.section_characteristics
                    & IMAGE_SCN_LNK_COMDAT
                )
            ):
                raise ValueError(
                    "candidate-local HudCmdBindingEntry pointer-vector erase "
                    "provider arbitration requires one exact external, "
                    "unaliased VC5 SELECT_ANY COMDAT with the complete "
                    "retail-derived body, exact NOP-padded extent, and an "
                    f"empty relocation population for {name!r}"
                )
            result[name] = (
                _hud_cmd_binding_ptr_vector_erase_provider_identity(
                    name,
                    indexes=indexes,
                    bridge_names=bridge_names,
                    compiler_generated_bridges=compiler_generated_bridges,
                )
            )
            continue

        if _is_zsnd_release_unknown_coff_name(name):
            helper_definition = candidate.tu_local_function_definitions.get(
                name
            )
            same_section_external_symbols = tuple(
                row.name
                for row in caller.coff_symbols
                if row.section_number == definition.section_number
                and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
            )
            try:
                source_provenance = Path(
                    helper_definition.source_provenance
                ).resolve()
            except (AttributeError, OSError, TypeError, ValueError) as exc:
                raise ValueError(
                    "zSnd ReleaseUnknown candidate-local bridge requires "
                    "exact source provenance"
                ) from exc
            if (
                _vc5_compiler_normalized_cod_proc_symbol(name)
                != name.replace("@?%", "@?", 1)
                or caller.symbol != "?Shutdown@zSndBackend@@YAHXZ"
                or caller.section_index != 27
                or caller.section_start != 0
                or caller.section_end != 0x90
                or len(caller.data) != 0x90
                or len(invocations) != 1
                or invocations[0][2:] != (0x2F, 0xE8)
                or helper_definition is None
                or helper_definition.symbol != name
                or helper_definition.data != ZSND_RELEASE_UNKNOWN_BODY
                or helper_definition.relocations
                or helper_definition.relocation_mask
                != ((False,) * len(ZSND_RELEASE_UNKNOWN_BODY))
                or helper_definition.section_size != 0x20
                or helper_definition.section_external_functions != (name,)
                or helper_definition.section_is_comdat is not True
                or helper_definition.comdat_selection != 1
                or source_provenance
                != ZSND_RELEASE_UNKNOWN_SOURCE_PATH.resolve()
                or same_section_external_symbols != (name,)
                or definition.value != 0
                or definition.natural_end != 0x20
                or definition.section_size != 0x20
                or not (
                    definition.section_characteristics
                    & IMAGE_SCN_LNK_COMDAT
                )
            ):
                raise ValueError(
                    "zSnd ReleaseUnknown candidate-local bridge requires the "
                    "exact canonical COD/COFF name, caller callsite, helper "
                    "body, relocation-free COMDAT, source, and TU population"
                )

        identity = f"candidate-local-coff:{name}"
        if (
            identity in indexes.provider_ids
            or identity in indexes.by_address.values()
            or identity in indexes.by_candidate_name.values()
            or identity in compiler_generated_bridges.values()
        ):
            raise ValueError(
                "candidate-local COFF callable bridge identity conflicts with "
                f"reviewed candidate/provider state for {name!r}"
            )
        result[name] = identity
    return result


def _arbitrate_candidate_local_reviewed_bridges(
    candidate_local_bridges: Mapping[str, str],
    *,
    reviewed_compiler_provider_bridges: Mapping[str, str],
    exact_destructor_bridges: Mapping[str, str],
    exact_constructor_bridges: Mapping[str, str],
    exact_zwep_provider_bridges: Mapping[str, str] | None = None,
) -> dict[str, str]:
    """Reconcile independently proven same-object callable identities.

    The early candidate-local proof must remain available to downstream bridge
    producers, so complete definitions initially receive comparison-only
    ``candidate-local-coff:`` identities.  Only the exact result maps from the
    later destructor and constructor proof producers may replace those local
    sentinels.  A name match or an overlap from any other reviewed producer is
    insufficient, and the two authorized producers may not disagree.
    """

    exact_proof_bridges: dict[str, str] = {}
    exact_proof_sources: dict[str, str] = {}
    for proof_source, proof_bridges in (
        ("destructor", exact_destructor_bridges),
        ("constructor", exact_constructor_bridges),
        ("zWep-provider", exact_zwep_provider_bridges or {}),
    ):
        for name, identity in proof_bridges.items():
            prior_identity = exact_proof_bridges.get(name)
            if prior_identity is not None and prior_identity != identity:
                raise ValueError(
                    "late candidate-local arbitration received conflicting "
                    "identities from its authorized exact proof producers "
                    f"for {name!r}: "
                    f"{exact_proof_sources[name]}={prior_identity!r}, "
                    f"{proof_source}={identity!r}"
                )
            exact_proof_bridges[name] = identity
            exact_proof_sources[name] = proof_source

    for name, identity in exact_proof_bridges.items():
        if reviewed_compiler_provider_bridges.get(name) != identity:
            raise ValueError(
                "late candidate-local arbitration received an authorized "
                "exact proof identity that does not survive unchanged in "
                f"the reviewed compiler/provider population for {name!r}"
            )

    result = dict(candidate_local_bridges)
    overlaps = (
        reviewed_compiler_provider_bridges.keys()
        & candidate_local_bridges.keys()
    )
    for name in overlaps:
        local_identity = candidate_local_bridges[name]
        reviewed_identity = reviewed_compiler_provider_bridges[name]
        if local_identity == reviewed_identity:
            continue
        expected_local_identity = f"candidate-local-coff:{name}"
        exact_proof_identity = exact_proof_bridges.get(name)
        if (
            local_identity != expected_local_identity
            or exact_proof_identity is None
            or exact_proof_identity != reviewed_identity
        ):
            raise ValueError(
                "late candidate-local arbitration rejects an "
                "unproved or conflicting reviewed overlap for "
                f"{name!r}: local={local_identity!r}, "
                f"reviewed={reviewed_identity!r}, "
                f"exact-proof={exact_proof_identity!r}"
            )
        result[name] = exact_proof_identity
    return result


_CZGAMEFRAME_CBITMAP_CALLER_IDENTITY = "symbol:recoil:function:0x4437d0"
_CZGAMEFRAME_CBITMAP_CALLER_START = "0x4437d0"
_CZGAMEFRAME_CBITMAP_CALLER_END_EXCLUSIVE = "0x443810"
_CZGAMEFRAME_CBITMAP_TARGET_NAME = (
    "czgameframe_443730_443c50_authored_order"
)
_CZGAMEFRAME_CBITMAP_SOURCE = "src/CZGameFrame/CZGameFrame.cpp"
_CZGAMEFRAME_CONSTRUCTOR_SYMBOL = "??0CZGameFrame@@QAE@PBD@Z"
_CZGAMEFRAME_CBITMAP_CONSTRUCTOR_SYMBOL = "??0CBitmap@@QAE@XZ"
_CZGAMEFRAME_CGDIOBJECT_CONSTRUCTOR_SYMBOL = "??0CGdiObject@@QAE@XZ"
_CZGAMEFRAME_COBJECT_CONSTRUCTOR_SYMBOL = "??0CObject@@IAE@XZ"
_CZGAMEFRAME_CBITMAP_VFTABLE_SYMBOL = "??_7CBitmap@@6B@"
_CZGAMEFRAME_CGDIOBJECT_VFTABLE_SYMBOL = "??_7CGdiObject@@6B@"
_CZGAMEFRAME_COBJECT_VFTABLE_SYMBOL = "??_7CObject@@6B@"


def _czgameframe_cbitmap_inline_constructor_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    retail_instructions: Sequence[Instruction],
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Consume only CZGameFrame's exact /Ob0 CBitmap constructor artifact.

    Retail inlines the source-faithful embedded ``CBitmap m_gameBitmap``
    construction into two final stores at ``this+0xc4`` and ``this+0xc8``.
    The governed ``/O2 /Ob0`` candidate instead calls the canonical VC5 MFC
    CBitmap/CGdiObject/CObject constructor COMDAT chain at ordinal one.  Drop
    and reordinalize only that one physical caller row after proving the exact
    target, TU, source, compile mode, member coordinate, caller COD/COFF body,
    relocation population, collision-free COMDAT chain, and immutable retail
    inline body.  The proof grants no generic constructor suppression and
    changes no provider, destructor, owner, order, byte, gate, or tier fact.
    """

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != _CZGAMEFRAME_CBITMAP_CALLER_START:
        return result

    label = "CZGameFrame CBitmap inline-constructor projection"
    target = candidate.target
    try:
        _profile, compile_flags = effective_source_compile_context(
            target, _CZGAMEFRAME_CBITMAP_SOURCE
        )
        compiler_root = compiler_env_path(
            target, DEFAULT_VC5_ENV
        ).resolve().parent
    except (AttributeError, OSError, TypeError, ValueError) as exc:
        raise ValueError(f"{label} requires the exact governed target") from exc
    upper_flags = tuple(str(flag).upper() for flag in compile_flags)
    optimization_flags = [
        flag for flag in upper_flags if flag in {"/OD", "/O1", "/O2", "/OX"}
    ]
    inline_flags = [
        flag for flag in upper_flags if flag in {"/OB0", "/OB1", "/OB2"}
    ]
    if (
        caller_identity != _CZGAMEFRAME_CBITMAP_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != _CZGAMEFRAME_CBITMAP_CALLER_END_EXCLUSIVE
        or getattr(target, "name", "") != _CZGAMEFRAME_CBITMAP_TARGET_NAME
        or getattr(target, "source_from", "") != _CZGAMEFRAME_CBITMAP_SOURCE
        or getattr(target, "source_filename", "") != "CZGameFrame.cpp"
        or tuple(getattr(target, "source_files", ())) != ()
        or optimization_flags != ["/O2"]
        or inline_flags != ["/OB0"]
        or "/TP" not in upper_flags
        or "/FACS" not in upper_flags
        or len(expected) != 3
        or len(result) != 4
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(expected))
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(result))
    ):
        raise ValueError(
            f"{label} rejects caller, target, TU, source, compile-mode, or "
            "invocation-population drift"
        )

    comparable_fields = (
        "form",
        "dispatch",
        "identity_kind",
        "target_identity",
        "storage_identity",
        "slot_displacement",
        "cleanup_bytes",
    )
    artifact_identity = (
        f"candidate-local-coff:{_CZGAMEFRAME_CBITMAP_CONSTRUCTOR_SYMBOL}"
    )
    artifact = result[1]
    mapped_candidate_indices = (0, 2, 3)
    if (
        artifact.get("form") != "call"
        or artifact.get("dispatch") != "direct"
        or artifact.get("identity_kind") != "direct"
        or artifact.get("target_identity") != artifact_identity
        or artifact.get("storage_identity") != ""
        or artifact.get("slot_displacement") is not None
        or artifact.get("cleanup_bytes") is not None
        or sum(
            row.get("target_identity") == artifact_identity for row in result
        )
        != 1
        or any(
            result[candidate_index].get(field) != expected[ordinal].get(field)
            for ordinal, candidate_index in enumerate(mapped_candidate_indices)
            for field in comparable_fields
        )
    ):
        raise ValueError(
            f"{label} rejects wrong, colliding, shifted, or unused candidate "
            "constructor proof"
        )

    caller = candidate.caller_definition
    expected_caller_data = bytes.fromhex(
        "6a ff 68 00 00 00 00 64 a1 00 00 00 00 50 64 89 "
        "25 00 00 00 00 51 56 8b f1 89 74 24 04 e8 00 00 "
        "00 00 8d 8e c4 00 00 00 c7 44 24 10 00 00 00 00 "
        "e8 00 00 00 00 8b 4c 24 18 c6 44 24 10 01 c7 06 "
        "00 00 00 00 e8 00 00 00 00 e8 00 00 00 00 8b 4c "
        "24 08 8b c6 64 89 0d 00 00 00 00 5e 83 c4 10 c2 "
        "04 00 90 90 90 90 90 90 90 90 90 90 90 90 90 90"
    )
    expected_caller_relocations = (
        (3, IMAGE_REL_I386_DIR32, None),
        (9, IMAGE_REL_I386_DIR32, "__except_list"),
        (17, IMAGE_REL_I386_DIR32, "__except_list"),
        (30, IMAGE_REL_I386_REL32, "??0CFrameWnd@@QAE@XZ"),
        (49, IMAGE_REL_I386_REL32, _CZGAMEFRAME_CBITMAP_CONSTRUCTOR_SYMBOL),
        (64, IMAGE_REL_I386_DIR32, "??_7CZGameFrame@@6B@"),
        (69, IMAGE_REL_I386_REL32, "?InitStdLogFiles@RecoilApp@@SIXPBD@Z"),
        (74, IMAGE_REL_I386_REL32, "?ModuleInit@zVideo@@YAHXZ"),
        (87, IMAGE_REL_I386_DIR32, "__except_list"),
    )
    if caller is None:
        raise ValueError(f"{label} requires a complete candidate caller")
    actual_relocations = tuple(
        (row.offset, row.type, row.symbol_name, row.symbol_index)
        for row in caller.relocations
    )
    expected_mask: set[int] = set()
    for offset, kind, expected_name in expected_caller_relocations:
        matches = [
            row
            for row in caller.relocations
            if row.offset == offset
            and row.type == kind
            and (
                row.symbol_name == expected_name
                if expected_name is not None
                else re.fullmatch(r"\$L\d+", row.symbol_name) is not None
            )
        ]
        if len(matches) != 1:
            raise ValueError(f"{label} rejects caller relocation drift")
        expected_mask.update(range(offset, offset + 4))
    if (
        caller.symbol != _CZGAMEFRAME_CONSTRUCTOR_SYMBOL
        or caller.data != expected_caller_data
        or caller.section_start != 0
        or caller.section_end != len(expected_caller_data)
        or len(actual_relocations) != len(expected_caller_relocations)
        or len({(row[0], row[3]) for row in actual_relocations})
        != len(actual_relocations)
        or len(caller.relocation_mask) != len(expected_caller_data)
        or {
            index for index, masked in enumerate(caller.relocation_mask) if masked
        }
        != expected_mask
    ):
        raise ValueError(
            f"{label} rejects caller symbol, body, extent, relocation "
            "population, addend, or mask drift"
        )

    caller_symbols = [
        row
        for row in caller.coff_symbols
        if row.name == _CZGAMEFRAME_CONSTRUCTOR_SYMBOL
    ]
    if len(caller_symbols) != 1:
        raise ValueError(f"{label} rejects caller COFF symbol collision")
    caller_symbol = caller_symbols[0]
    same_section_externals = tuple(
        row.name
        for row in caller.coff_symbols
        if row.section_number == caller_symbol.section_number
        and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
    )
    weak_or_coincident = [
        row
        for row in caller.coff_symbols
        if row.index != caller_symbol.index
        and (
            (
                row.storage_class == 105
                and row.weak_external_tag_index == caller_symbol.index
            )
            or (
                row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
                and row.section_number == caller_symbol.section_number
                and row.value == caller_symbol.value
            )
        )
    ]
    if (
        caller.section_index != caller_symbol.section_number
        or caller_symbol.value != 0
        or caller_symbol.section_number <= 0
        or caller_symbol.symbol_type != 0x20
        or caller_symbol.storage_class != IMAGE_SYM_CLASS_EXTERNAL
        or caller_symbol.aux_count != 0
        or caller_symbol.section_name != ".text"
        or caller_symbol.section_size != len(expected_caller_data)
        or caller_symbol.natural_end != len(expected_caller_data)
        or not (caller_symbol.section_characteristics & IMAGE_SCN_LNK_COMDAT)
        or same_section_externals != (_CZGAMEFRAME_CONSTRUCTOR_SYMBOL,)
        or weak_or_coincident
    ):
        raise ValueError(
            f"{label} rejects caller COFF section, external population, or "
            "alias collision"
        )

    for relocation in caller.relocations:
        matches = [
            row
            for row in caller.coff_symbols
            if row.index == relocation.symbol_index
            and row.name == relocation.symbol_name
        ]
        if len(matches) != 1:
            raise ValueError(
                f"{label} rejects caller relocation-target population drift"
            )

    caller_offsets = _candidate_complete_instruction_offsets(candidate)
    counts = Counter(offset for offset in caller_offsets if offset is not None)
    caller_by_offset = {
        offset: instruction
        for instruction, offset in zip(candidate.instructions, caller_offsets)
        if offset is not None and counts[offset] == 1
    }
    caller_cod_rows = {
        0x1D: (("e8", "00", "00", "00", "00"), r"call\s+\?\?0CFrameWnd@@QAE@XZ"),
        0x22: (("8d", "8e", "c4", "00", "00", "00"), r"lea\s+ecx,\s*(?:dword\s+(?:ptr\s+)?)?\[esi\+(?:196|0xc4)\]"),
        0x30: (("e8", "00", "00", "00", "00"), r"call\s+\?\?0CBitmap@@QAE@XZ"),
        0x3E: (("c7", "06", "00", "00", "00", "00"), r"mov\s+dword\s+(?:ptr\s+)?\[esi\],\s*OFFSET\s+FLAT:\?\?_7CZGameFrame@@6B@"),
        0x44: (("e8", "00", "00", "00", "00"), r"call\s+\?InitStdLogFiles@RecoilApp@@SIXPBD@Z"),
        0x49: (("e8", "00", "00", "00", "00"), r"call\s+\?ModuleInit@zVideo@@YAHXZ"),
    }
    if any(
        offset not in caller_by_offset
        or tuple(value.lower() for value in caller_by_offset[offset].bytes)
        != body
        or re.fullmatch(
            pattern,
            caller_by_offset[offset].raw_text.strip(),
            flags=re.IGNORECASE,
        )
        is None
        for offset, (body, pattern) in caller_cod_rows.items()
    ):
        raise ValueError(
            f"{label} rejects caller COD callsite or embedded +0xc4 member "
            "coordinate drift"
        )

    helper_specs = {
        _CZGAMEFRAME_CBITMAP_CONSTRUCTOR_SYMBOL: {
            "data": bytes.fromhex(
                "56 8b f1 e8 00 00 00 00 c7 06 00 00 00 00 8b c6 "
                "5e c3 90 90 90 90 90 90 90 90 90 90 90 90 90 90"
            ),
            "relocations": (
                (4, IMAGE_REL_I386_REL32, _CZGAMEFRAME_CGDIOBJECT_CONSTRUCTOR_SYMBOL),
                (10, IMAGE_REL_I386_DIR32, _CZGAMEFRAME_CBITMAP_VFTABLE_SYMBOL),
            ),
            "source": compiler_root / "VC" / "MFC" / "INCLUDE" / "afxwin1.inl",
            "instructions": (
                (("56",), r"push\s+esi"),
                (("8b", "f1"), r"mov\s+esi,\s*ecx"),
                (("e8", "00", "00", "00", "00"), r"call\s+\?\?0CGdiObject@@QAE@XZ"),
                (("c7", "06", "00", "00", "00", "00"), r"mov\s+dword\s+(?:ptr\s+)?\[esi\],\s*OFFSET\s+FLAT:\?\?_7CBitmap@@6B@"),
                (("8b", "c6"), r"mov\s+eax,\s*esi"),
                (("5e",), r"pop\s+esi"),
                (("c3",), r"ret(?:n)?(?:\s+0)?"),
            ),
        },
        _CZGAMEFRAME_CGDIOBJECT_CONSTRUCTOR_SYMBOL: {
            "data": bytes.fromhex(
                "56 8b f1 e8 00 00 00 00 c7 06 00 00 00 00 c7 46 "
                "04 00 00 00 00 8b c6 5e c3 90 90 90 90 90 90 90"
            ),
            "relocations": (
                (4, IMAGE_REL_I386_REL32, _CZGAMEFRAME_COBJECT_CONSTRUCTOR_SYMBOL),
                (10, IMAGE_REL_I386_DIR32, _CZGAMEFRAME_CGDIOBJECT_VFTABLE_SYMBOL),
            ),
            "source": compiler_root / "VC" / "MFC" / "INCLUDE" / "afxwin1.inl",
            "instructions": (
                (("56",), r"push\s+esi"),
                (("8b", "f1"), r"mov\s+esi,\s*ecx"),
                (("e8", "00", "00", "00", "00"), r"call\s+\?\?0CObject@@IAE@XZ"),
                (("c7", "06", "00", "00", "00", "00"), r"mov\s+dword\s+(?:ptr\s+)?\[esi\],\s*OFFSET\s+FLAT:\?\?_7CGdiObject@@6B@"),
                (("c7", "46", "04", "00", "00", "00", "00"), r"mov\s+dword\s+(?:ptr\s+)?\[esi\+4\],\s*0"),
                (("8b", "c6"), r"mov\s+eax,\s*esi"),
                (("5e",), r"pop\s+esi"),
                (("c3",), r"ret(?:n)?(?:\s+0)?"),
            ),
        },
        _CZGAMEFRAME_COBJECT_CONSTRUCTOR_SYMBOL: {
            "data": bytes.fromhex(
                "8b c1 c7 00 00 00 00 00 c3 90 90 90 90 90 90 90"
            ),
            "relocations": (
                (4, IMAGE_REL_I386_DIR32, _CZGAMEFRAME_COBJECT_VFTABLE_SYMBOL),
            ),
            "source": compiler_root / "VC" / "MFC" / "INCLUDE" / "afx.inl",
            "instructions": (
                (("8b", "c1"), r"mov\s+eax,\s*ecx"),
                (("c7", "00", "00", "00", "00", "00"), r"mov\s+dword\s+(?:ptr\s+)?\[eax\],\s*OFFSET\s+FLAT:\?\?_7CObject@@6B@"),
                (("c3",), r"ret(?:n)?(?:\s+0)?"),
            ),
        },
    }
    for helper_name, spec in helper_specs.items():
        helper = candidate.tu_local_function_definitions.get(helper_name)
        helper_symbols = [
            row for row in caller.coff_symbols if row.name == helper_name
        ]
        if helper is None or len(helper_symbols) != 1:
            raise ValueError(
                f"{label} requires one exact collision-free canonical MFC "
                f"COMDAT {helper_name!r}"
            )
        helper_symbol = helper_symbols[0]
        expected_data = spec["data"]
        expected_relocations = spec["relocations"]
        observed_relocations = tuple(
            (row.offset, row.type, row.symbol_name)
            for row in helper.relocations
        )
        helper_mask = {
            index for index, masked in enumerate(helper.relocation_mask) if masked
        }
        expected_helper_mask = {
            index
            for offset, _kind, _name in expected_relocations
            for index in range(offset, offset + 4)
        }
        same_helper_section_externals = tuple(
            row.name
            for row in caller.coff_symbols
            if row.section_number == helper_symbol.section_number
            and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
        )
        helper_collisions = [
            row
            for row in caller.coff_symbols
            if row.index != helper_symbol.index
            and (
                row.name == helper_name
                or (
                    row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
                    and row.section_number == helper_symbol.section_number
                    and row.value == helper_symbol.value
                )
                or (
                    row.storage_class == 105
                    and row.weak_external_tag_index == helper_symbol.index
                )
            )
        ]
        try:
            provenance_matches = (
                Path(helper.source_provenance).resolve()
                == Path(spec["source"]).resolve()
            )
        except (OSError, TypeError, ValueError):
            provenance_matches = False
        expected_instruction_rows = spec["instructions"]
        instruction_rows_match = (
            len(helper.instructions) == len(expected_instruction_rows)
            and all(
                tuple(value.lower() for value in instruction.bytes) == body
                and re.fullmatch(
                    pattern,
                    instruction.raw_text.strip(),
                    flags=re.IGNORECASE,
                )
                is not None
                for instruction, (body, pattern) in zip(
                    helper.instructions, expected_instruction_rows
                )
            )
        )
        if (
            helper.symbol != helper_name
            or helper.data != expected_data
            or helper.section_size != len(expected_data)
            or helper.section_external_functions != (helper_name,)
            or helper.section_is_comdat is not True
            or helper.comdat_selection != 2
            or observed_relocations != expected_relocations
            or len(helper.relocations) != len(expected_relocations)
            or len(helper.relocation_mask) != len(expected_data)
            or helper_mask != expected_helper_mask
            or helper.local_control_flow_indices
            or helper.local_control_flow_targets
            or not provenance_matches
            or not instruction_rows_match
            or helper_symbol.value != 0
            or helper_symbol.section_number <= 0
            or helper_symbol.symbol_type != 0x20
            or helper_symbol.storage_class != IMAGE_SYM_CLASS_EXTERNAL
            or helper_symbol.aux_count != 0
            or helper_symbol.section_name != ".text"
            or helper_symbol.section_size != len(expected_data)
            or helper_symbol.natural_end != len(expected_data)
            or not (helper_symbol.section_characteristics & IMAGE_SCN_LNK_COMDAT)
            or same_helper_section_externals != (helper_name,)
            or helper_collisions
        ):
            raise ValueError(
                f"{label} rejects canonical MFC body, relocation, COD, COFF, "
                f"provenance, population, or collision drift for {helper_name!r}"
            )
        for relocation in helper.relocations:
            target_symbols = [
                row
                for row in caller.coff_symbols
                if row.index == relocation.symbol_index
                and row.name == relocation.symbol_name
            ]
            if len(target_symbols) != 1:
                raise ValueError(
                    f"{label} rejects canonical MFC relocation-target "
                    f"population drift for {helper_name!r}"
                )
            target_symbol = target_symbols[0]
            if (
                target_symbol.section_number <= 0
                or target_symbol.storage_class != IMAGE_SYM_CLASS_EXTERNAL
                or target_symbol.symbol_type
                != (
                    0x20
                    if relocation.type == IMAGE_REL_I386_REL32
                    else 0
                )
            ):
                raise ValueError(
                    f"{label} rejects canonical MFC relocation-target shape "
                    f"for {helper_name!r}"
                )

    expected_retail_data = bytes.fromhex(
        "56 8b f1 e8 98 26 08 00 8b 4c 24 08 c7 86 c8 00 "
        "00 00 00 00 00 00 c7 86 c4 00 00 00 e0 22 4d 00 "
        "c7 06 d8 21 4d 00 e8 85 1f 06 00 e8 30 3d 06 00 "
        "8b c6 5e c2 04 00"
    )
    retail_addresses = _instruction_runtime_addresses(
        retail_instructions,
        source="bn",
        caller_start=address_value(_CZGAMEFRAME_CBITMAP_CALLER_START),
    )
    retail_rows = sorted(
        (
            address,
            bytes(int(value, 16) for value in instruction.bytes),
        )
        for instruction, address in zip(retail_instructions, retail_addresses)
        if address is not None
        and address_value(_CZGAMEFRAME_CBITMAP_CALLER_START)
        <= address
        < address_value(_CZGAMEFRAME_CBITMAP_CALLER_END_EXCLUSIVE)
    )
    cursor = address_value(_CZGAMEFRAME_CBITMAP_CALLER_START)
    retail_body = bytearray()
    for address, body in retail_rows:
        if address != cursor or not body:
            raise ValueError(
                f"{label} rejects immutable retail COD/extent population drift"
            )
        retail_body.extend(body)
        cursor += len(body)
    if (
        cursor
        != address_value(_CZGAMEFRAME_CBITMAP_CALLER_START)
        + len(expected_retail_data)
        or bytes(retail_body) != expected_retail_data
    ):
        raise ValueError(
            f"{label} rejects immutable retail inline vtable/null-handle "
            "stores, member offsets, call population, or body drift"
        )

    projected: list[dict[str, Any]] = []
    for ordinal, candidate_index in enumerate(mapped_candidate_indices):
        row = dict(result[candidate_index])
        row["ordinal"] = ordinal
        projected.append(row)
    return projected


def _zsnd_snapshot_inline_constructor_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    retail_instructions: Sequence[Instruction],
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
) -> list[dict[str, Any]]:
    """Project one exact /Ob0 snapshot constructor to its inlined provider call.

    Retail inlines ``zSndPlayHandleSnapshot(unsigned char)`` into
    ``CreateFromActiveSamples``.  The governed /Ob0 candidate instead emits
    the ordinary source constructor as one local COMDAT call; its sole nested
    invocation is the second ``operator new`` call visible in retail.  Replace
    only that one row after proving the complete caller population, exact
    caller seam, unique source-provenance COMDAT, nested provider relocation,
    and the immutable retail inline bytes.  The expected provider identity and
    cleanup remain retail-derived; candidate output supplies neither.
    """

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != "0x49fff0":
        return result
    if (
        caller_identity != _ZSND_SNAPSHOT_CREATE_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive) != "0x4a0300"
        or len(expected) != 18
        or len(result) != 18
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(expected))
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(result))
    ):
        raise ValueError(
            "zSnd snapshot inline-constructor projection rejects caller extent "
            "or invocation population drift"
        )

    constructor_identity = (
        f"candidate-local-coff:{_ZSND_SNAPSHOT_CONSTRUCTOR_SYMBOL}"
    )
    constructor_rows = [
        row for row in result if row.get("target_identity") == constructor_identity
    ]
    expected_provider = expected[1].get("target_identity")
    comparable_fields = (
        "form",
        "dispatch",
        "identity_kind",
        "target_identity",
        "storage_identity",
        "slot_displacement",
        "cleanup_bytes",
    )
    if (
        len(constructor_rows) != 1
        or constructor_rows[0] is not result[1]
        or result[1].get("form") != "call"
        or result[1].get("dispatch") != "direct"
        or result[1].get("identity_kind") != "direct"
        or result[1].get("storage_identity") != ""
        or result[1].get("slot_displacement") is not None
        or result[1].get("cleanup_bytes") != 4
        or expected[1].get("identity_kind") != "provider"
        or not isinstance(expected_provider, str)
        or expected_provider not in indexes.provider_ids
        or indexes.by_address.get("0x4c5b76") != expected_provider
        or any(expected[0].get(field) != expected[1].get(field) for field in comparable_fields)
        or any(result[0].get(field) != expected[0].get(field) for field in comparable_fields)
        or expected[1].get("cleanup_bytes") != 4
        or expected[2].get("target_identity")
        != _ZSND_SAMPLE_SET_COUNT_IDENTITY
        or any(result[2].get(field) != expected[2].get(field) for field in comparable_fields)
    ):
        raise ValueError(
            "zSnd snapshot inline-constructor projection rejects provider, "
            "ABI, ordinal, or neighboring-call drift"
        )

    helper = candidate.tu_local_function_definitions.get(
        _ZSND_SNAPSHOT_CONSTRUCTOR_SYMBOL
    )
    caller = candidate.caller_definition
    if helper is None or caller is None:
        raise ValueError(
            "zSnd snapshot inline-constructor projection requires complete "
            "candidate caller and COMDAT definitions"
        )
    expected_helper_data = bytes.fromhex(
        "8a 44 24 04 56 8b f1 6a 30 88 06 e8 00 00 00 00 "
        "83 c4 04 89 00 89 40 04 89 46 04 c7 46 08 00 00 "
        "00 00 8b c6 5e c2 04 00 90 90 90 90 90 90 90 90"
    )
    expected_helper_mask = tuple(
        0x0C <= index < 0x10 for index in range(len(expected_helper_data))
    )
    helper_relocations = tuple(
        (row.offset, row.type, row.symbol_name, row.symbol_index)
        for row in helper.relocations
    )
    if (
        helper.symbol != _ZSND_SNAPSHOT_CONSTRUCTOR_SYMBOL
        or helper.data != expected_helper_data
        or helper.section_size != 0x30
        or helper.section_external_functions
        != (_ZSND_SNAPSHOT_CONSTRUCTOR_SYMBOL,)
        or helper.section_is_comdat is not True
        or helper.comdat_selection != 2
        or tuple(helper.relocation_mask) != expected_helper_mask
        or len(helper_relocations) != 1
        or helper_relocations[0][:3]
        != (0x0C, IMAGE_REL_I386_REL32, _ZSND_SNAPSHOT_OPERATOR_NEW_SYMBOL)
        or not helper.instructions
        or helper.local_control_flow_indices
        or helper.local_control_flow_targets
    ):
        raise ValueError(
            "zSnd snapshot inline-constructor projection rejects COMDAT body, "
            "relocation, padding, or CFG drift"
        )
    try:
        provenance = Path(helper.source_provenance).resolve()
        expected_provenance = (
            REPO_ROOT / "src" / "GameZRecoil" / "zSound" / "zsnd_play.cpp"
        ).resolve()
    except (OSError, TypeError) as exc:
        raise ValueError(
            "zSnd snapshot inline-constructor projection has invalid source provenance"
        ) from exc
    if provenance != expected_provenance:
        raise ValueError(
            "zSnd snapshot inline-constructor projection rejects source provenance drift"
        )

    constructor_symbols = [
        row
        for row in caller.coff_symbols
        if row.name == _ZSND_SNAPSHOT_CONSTRUCTOR_SYMBOL
    ]
    if len(constructor_symbols) != 1:
        raise ValueError(
            "zSnd snapshot inline-constructor projection requires one exact "
            "constructor COFF symbol"
        )
    constructor_symbol = constructor_symbols[0]
    same_section_externals = tuple(
        row.name
        for row in caller.coff_symbols
        if row.section_number == constructor_symbol.section_number
        and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
    )
    weak_or_coincident = [
        row
        for row in caller.coff_symbols
        if row.index != constructor_symbol.index
        and (
            (
                row.storage_class == 105
                and row.weak_external_tag_index == constructor_symbol.index
            )
            or (
                row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
                and row.section_number == constructor_symbol.section_number
                and row.value == constructor_symbol.value
            )
        )
    ]
    nested_symbol_index = helper_relocations[0][3]
    nested_symbols = [
        row
        for row in caller.coff_symbols
        if row.index == nested_symbol_index
        and row.name == _ZSND_SNAPSHOT_OPERATOR_NEW_SYMBOL
    ]
    if (
        constructor_symbol.value != 0
        or constructor_symbol.section_number <= 0
        or constructor_symbol.symbol_type != 0x20
        or constructor_symbol.storage_class != IMAGE_SYM_CLASS_EXTERNAL
        or constructor_symbol.aux_count != 0
        or constructor_symbol.section_name != ".text"
        or constructor_symbol.section_size != 0x30
        or constructor_symbol.natural_end != 0x30
        or not (constructor_symbol.section_characteristics & IMAGE_SCN_LNK_COMDAT)
        or same_section_externals != (_ZSND_SNAPSHOT_CONSTRUCTOR_SYMBOL,)
        or weak_or_coincident
        or len(nested_symbols) != 1
        or nested_symbols[0].section_number != 0
        or nested_symbols[0].symbol_type != 0x20
        or nested_symbols[0].storage_class != IMAGE_SYM_CLASS_EXTERNAL
    ):
        raise ValueError(
            "zSnd snapshot inline-constructor projection rejects COFF symbol, "
            "alias, external-population, or provider-target drift"
        )

    candidate_rows = {
        0x2D: bytes.fromhex("6a 0c"),
        0x2F: bytes.fromhex("f3 ab"),
        0x31: bytes.fromhex("e8 00 00 00 00"),
        0x36: bytes.fromhex("83 c4 04"),
        0x39: bytes.fromhex("89 44 24 24"),
        0x3D: bytes.fromhex("3b c6"),
        0x3F: bytes.fromhex("89 74 24 58"),
        0x43: bytes.fromhex("74 10"),
        0x45: bytes.fromhex("8b 4c 24 24"),
        0x49: bytes.fromhex("51"),
        0x4A: bytes.fromhex("8b c8"),
        0x4C: bytes.fromhex("e8 00 00 00 00"),
        0x51: bytes.fromhex("8b e8"),
        0x53: bytes.fromhex("eb 02"),
        0x55: bytes.fromhex("33 ed"),
        0x57: bytes.fromhex("c7 44 24 58 ff ff ff ff"),
        0x5F: bytes.fromhex("e8 00 00 00 00"),
    }
    candidate_addresses = _instruction_runtime_addresses(
        candidate.instructions,
        source="cod",
        caller_start=0x49FFF0,
    )
    candidate_by_offset = {
        address - 0x49FFF0: instruction
        for instruction, address in zip(candidate.instructions, candidate_addresses)
        if address is not None
    }
    if (
        caller.symbol != _ZSND_SNAPSHOT_CREATE_CALLER_SYMBOL
        or len(caller.data) != 0x250
        or len(caller.relocation_mask) != 0x250
        or caller.section_start != 0
        or caller.section_end != 0x250
        or any(
            offset not in candidate_by_offset
            or bytes(
                int(item, 16) for item in candidate_by_offset[offset].bytes
            )
            != body
            for offset, body in candidate_rows.items()
        )
    ):
        raise ValueError(
            "zSnd snapshot inline-constructor projection rejects candidate "
            "caller symbol, extent, or allocation/constructor seam drift"
        )
    required_caller_relocations = {
        (0x32, IMAGE_REL_I386_REL32, _ZSND_SNAPSHOT_OPERATOR_NEW_SYMBOL),
        (0x4D, IMAGE_REL_I386_REL32, _ZSND_SNAPSHOT_CONSTRUCTOR_SYMBOL),
        (0x60, IMAGE_REL_I386_REL32, "_zSndSampleSetRegistry_GetCount"),
    }
    observed_caller_relocations = {
        (row.offset, row.type, row.symbol_name)
        for row in caller.relocations
        if row.offset in {0x32, 0x4D, 0x60}
    }
    if (
        observed_caller_relocations != required_caller_relocations
        or any(
            caller.data[offset : offset + 4] != b"\x00" * 4
            or not all(
                caller.relocation_mask[index]
                for index in range(offset, offset + 4)
            )
            for offset, _kind, _name in required_caller_relocations
        )
    ):
        raise ValueError(
            "zSnd snapshot inline-constructor projection rejects caller "
            "relocation, addend, or mask drift"
        )

    retail_rows = (
        (0x4A001D, bytes.fromhex("6a 0c")),
        (0x4A001F, bytes.fromhex("f3 ab")),
        (0x4A0021, bytes.fromhex("e8 50 5b 02 00")),
        (0x4A0026, bytes.fromhex("8b e8")),
        (0x4A0028, bytes.fromhex("83 c4 04")),
        (0x4A002B, bytes.fromhex("89 6c 24 28")),
        (0x4A002F, bytes.fromhex("3b ee")),
        (0x4A0031, bytes.fromhex("89 74 24 5c")),
        (0x4A0035, bytes.fromhex("74 1e")),
        (0x4A0037, bytes.fromhex("8a 44 24 13")),
        (0x4A003B, bytes.fromhex("6a 30")),
        (0x4A003D, bytes.fromhex("88 45 00")),
        (0x4A0040, bytes.fromhex("e8 31 5b 02 00")),
        (0x4A0045, bytes.fromhex("89 00")),
        (0x4A0047, bytes.fromhex("89 40 04")),
        (0x4A004A, bytes.fromhex("83 c4 04")),
        (0x4A004D, bytes.fromhex("89 45 04")),
        (0x4A0050, bytes.fromhex("89 75 08")),
        (0x4A0053, bytes.fromhex("eb 02")),
        (0x4A0055, bytes.fromhex("33 ed")),
        (0x4A0057, bytes.fromhex("c7 44 24 5c ff ff ff ff")),
        (0x4A005F, bytes.fromhex("e8 9c 08 00 00")),
    )
    retail_by_address = {
        address_value(address): (index, instruction)
        for index, instruction in enumerate(retail_instructions)
        if (address := _source_instruction_address(instruction))
    }
    selected_retail = [
        retail_by_address.get(address) for address, _body in retail_rows
    ]
    if (
        any(row is None for row in selected_retail)
        or [row[0] for row in selected_retail]
        != list(range(selected_retail[0][0], selected_retail[-1][0] + 1))
        or any(
            bytes(
                int(item, 16)
                for item in retail_by_address[address][1].bytes
            )
            != body
            for address, body in retail_rows
        )
    ):
        raise ValueError(
            "zSnd snapshot inline-constructor projection rejects immutable "
            "retail allocation/inline body drift"
        )

    result[1] = dict(expected[1])
    return result


def _zsnd_snapshot_append_payload_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    retail_instructions: Sequence[Instruction],
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
) -> list[dict[str, Any]]:
    """Project four exact /Ob0 AppendPayload calls to nested NewNode calls.

    Retail inlines the source-inline payload append at each call site while the
    governed candidate emits one caller-local COMDAT.  Its sole invocation is
    the authored ``NewNode`` call visible at the same four normalized retail
    ordinals.  This is deliberately a complete caller/helper/COFF/retail-byte
    proof, not a general local-COMDAT alias rule.
    """

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != "0x49fff0":
        return result
    append_ordinals = (3, 8, 14, 17)
    if (
        caller_identity != _ZSND_SNAPSHOT_CREATE_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive) != "0x4a0300"
        or len(expected) != 18
        or len(result) != 18
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(expected))
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(result))
    ):
        raise ValueError(
            "zSnd snapshot AppendPayload projection rejects caller extent or "
            "invocation population drift"
        )

    append_identity = (
        f"candidate-local-coff:{_ZSND_SNAPSHOT_APPEND_PAYLOAD_SYMBOL}"
    )
    append_rows = tuple(
        int(row.get("ordinal", -1))
        for row in result
        if row.get("target_identity") == append_identity
    )
    if (
        append_rows != append_ordinals
        or indexes.by_address.get("0x4a07c0")
        != _ZSND_SNAPSHOT_NEW_NODE_IDENTITY
        or indexes.by_candidate_name.get(_ZSND_SNAPSHOT_NEW_NODE_SYMBOL)
        != _ZSND_SNAPSHOT_NEW_NODE_IDENTITY
        or any(
            expected[ordinal].get("target_identity")
            != _ZSND_SNAPSHOT_NEW_NODE_IDENTITY
            or expected[ordinal].get("form") != "call"
            or expected[ordinal].get("dispatch") != "direct"
            or expected[ordinal].get("identity_kind") != "direct"
            or expected[ordinal].get("storage_identity") != ""
            or expected[ordinal].get("slot_displacement") is not None
            or expected[ordinal].get("cleanup_bytes") is not None
            or result[ordinal].get("form") != "call"
            or result[ordinal].get("dispatch") != "direct"
            or result[ordinal].get("identity_kind") != "direct"
            or result[ordinal].get("storage_identity") != ""
            or result[ordinal].get("slot_displacement") is not None
            or result[ordinal].get("cleanup_bytes") != 4
            for ordinal in append_ordinals
        )
    ):
        raise ValueError(
            "zSnd snapshot AppendPayload projection rejects authored NewNode, "
            "ABI, or ordinal drift"
        )

    append_helper = candidate.tu_local_function_definitions.get(
        _ZSND_SNAPSHOT_APPEND_PAYLOAD_SYMBOL
    )
    new_node = candidate.tu_local_function_definitions.get(
        _ZSND_SNAPSHOT_NEW_NODE_SYMBOL
    )
    caller = candidate.caller_definition
    if append_helper is None or new_node is None or caller is None:
        raise ValueError(
            "zSnd snapshot AppendPayload projection requires complete caller, "
            "helper, and nested NewNode definitions"
        )

    append_data = bytes.fromhex(
        "53 8b d9 56 57 8b 73 04 8b 46 04 50 56 e8 00 00 "
        "00 00 89 46 04 8b 48 04 8d 78 08 85 ff 89 01 74 "
        "0b 8b 74 24 10 b9 0a 00 00 00 f3 a5 8b 43 08 5f "
        "40 5e 89 43 08 5b c2 04 00 90 90 90 90 90 90 90"
    )
    new_node_data = bytes.fromhex(
        "6a 30 e8 00 00 00 00 8b 4c 24 08 83 c4 04 85 c9 "
        "75 02 8b c8 89 08 8b 4c 24 08 85 c9 75 02 8b c8 "
        "89 48 04 c2 08 00 90 90 90 90 90 90 90 90 90 90"
    )
    append_mask = tuple(
        0x0E <= offset < 0x12 for offset in range(len(append_data))
    )
    new_node_mask = tuple(
        0x03 <= offset < 0x07 for offset in range(len(new_node_data))
    )
    append_relocations = tuple(
        (row.offset, row.type, row.symbol_name, row.symbol_index)
        for row in append_helper.relocations
    )
    new_node_relocations = tuple(
        (row.offset, row.type, row.symbol_name, row.symbol_index)
        for row in new_node.relocations
    )
    if (
        append_helper.symbol != _ZSND_SNAPSHOT_APPEND_PAYLOAD_SYMBOL
        or append_helper.data != append_data
        or append_helper.section_size != 0x40
        or append_helper.section_external_functions
        != (_ZSND_SNAPSHOT_APPEND_PAYLOAD_SYMBOL,)
        or append_helper.section_is_comdat is not True
        or append_helper.comdat_selection != 2
        or tuple(append_helper.relocation_mask) != append_mask
        or len(append_relocations) != 1
        or append_relocations[0][:3]
        != (0x0E, IMAGE_REL_I386_REL32, _ZSND_SNAPSHOT_NEW_NODE_SYMBOL)
        or not append_helper.instructions
        or append_helper.local_control_flow_indices
        or append_helper.local_control_flow_targets
        or new_node.symbol != _ZSND_SNAPSHOT_NEW_NODE_SYMBOL
        or new_node.data != new_node_data
        or new_node.section_size != 0x30
        or new_node.section_external_functions
        != (_ZSND_SNAPSHOT_NEW_NODE_SYMBOL,)
        or new_node.section_is_comdat is not True
        or new_node.comdat_selection != 1
        or tuple(new_node.relocation_mask) != new_node_mask
        or len(new_node_relocations) != 1
        or new_node_relocations[0][:3]
        != (0x03, IMAGE_REL_I386_REL32, _ZSND_SNAPSHOT_OPERATOR_NEW_SYMBOL)
        or not new_node.instructions
        or new_node.local_control_flow_indices
        or new_node.local_control_flow_targets
    ):
        raise ValueError(
            "zSnd snapshot AppendPayload projection rejects helper/NewNode "
            "body, ABI, relocation, padding, COMDAT, or CFG drift"
        )
    expected_provenance = (
        REPO_ROOT / "src" / "GameZRecoil" / "zSound" / "zsnd_play.cpp"
    ).resolve()
    try:
        provenances = {
            Path(append_helper.source_provenance).resolve(),
            Path(new_node.source_provenance).resolve(),
        }
    except (OSError, TypeError) as exc:
        raise ValueError(
            "zSnd snapshot AppendPayload projection has invalid provenance"
        ) from exc
    if provenances != {expected_provenance}:
        raise ValueError(
            "zSnd snapshot AppendPayload projection rejects source provenance drift"
        )

    coff_by_name = {
        name: [row for row in caller.coff_symbols if row.name == name]
        for name in (
            _ZSND_SNAPSHOT_APPEND_PAYLOAD_SYMBOL,
            _ZSND_SNAPSHOT_NEW_NODE_SYMBOL,
        )
    }
    if any(len(rows) != 1 for rows in coff_by_name.values()):
        raise ValueError(
            "zSnd snapshot AppendPayload projection requires unique helper and "
            "NewNode COFF symbols"
        )
    append_symbol = coff_by_name[_ZSND_SNAPSHOT_APPEND_PAYLOAD_SYMBOL][0]
    new_node_symbol = coff_by_name[_ZSND_SNAPSHOT_NEW_NODE_SYMBOL][0]
    aliases = [
        row
        for row in caller.coff_symbols
        if row.index not in {append_symbol.index, new_node_symbol.index}
        and (
            row.storage_class == 105
            and row.weak_external_tag_index
            in {append_symbol.index, new_node_symbol.index}
            or row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
            and row.section_number
            in {append_symbol.section_number, new_node_symbol.section_number}
            and row.value == 0
        )
    ]
    if (
        append_relocations[0][3] != new_node_symbol.index
        or new_node_relocations[0][3]
        not in {
            row.index
            for row in caller.coff_symbols
            if row.name == _ZSND_SNAPSHOT_OPERATOR_NEW_SYMBOL
            and row.section_number == 0
            and row.symbol_type == 0x20
            and row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
        }
        or aliases
        or any(
            row.value != 0
            or row.section_number <= 0
            or row.symbol_type != 0x20
            or row.storage_class != IMAGE_SYM_CLASS_EXTERNAL
            or row.aux_count != 0
            or row.section_name != ".text"
            or row.section_size != size
            or row.natural_end != size
            or not (row.section_characteristics & IMAGE_SCN_LNK_COMDAT)
            for row, size in (
                (append_symbol, 0x40),
                (new_node_symbol, 0x30),
            )
        )
    ):
        raise ValueError(
            "zSnd snapshot AppendPayload projection rejects COFF target, "
            "section, external-population, or alias drift"
        )

    caller_runs = (
        (
            0x64,
            bytes.fromhex(
                "8b15000000008d4c24288bd8518b028bcd895c242889442434"
                "e800000000"
            ),
        ),
        (
            0xDF,
            bytes.fromhex(
                "74188d53448d4c2428e8000000008d5424288bcd52e8000000008b"
            ),
        ),
        (
            0x19C,
            bytes.fromhex(
                "74188d53448d4c2428e8000000008d5424288bcd52e8000000008b"
            ),
        ),
        (
            0x1DC,
            bytes.fromhex(
                "c074178bd68d4c2428e8000000008d4c2428518bcde8000000008b"
            ),
        ),
    )
    append_caller_relocations = {
        (row.offset, row.type, row.symbol_name, row.symbol_index)
        for row in caller.relocations
        if row.symbol_name == _ZSND_SNAPSHOT_APPEND_PAYLOAD_SYMBOL
    }
    required_append_relocations = {
        (offset, IMAGE_REL_I386_REL32, _ZSND_SNAPSHOT_APPEND_PAYLOAD_SYMBOL,
         append_symbol.index)
        for offset in (0x7E, 0xF5, 0x1B2, 0x1F2)
    }
    if (
        caller.symbol != _ZSND_SNAPSHOT_CREATE_CALLER_SYMBOL
        or len(caller.data) != 0x250
        or len(caller.relocation_mask) != 0x250
        or caller.section_start != 0
        or caller.section_end != 0x250
        or any(
            caller.data[offset : offset + len(body)] != body
            for offset, body in caller_runs
        )
        or append_caller_relocations != required_append_relocations
        or any(
            caller.data[offset : offset + 4] != b"\x00" * 4
            or not all(caller.relocation_mask[index] for index in range(offset, offset + 4))
            for offset in (0x7E, 0xF5, 0x1B2, 0x1F2)
        )
    ):
        raise ValueError(
            "zSnd snapshot AppendPayload projection rejects caller bytes, "
            "extent, relocation, mask, addend, or call population drift"
        )

    retail_runs = (
        (0x4A0078, 0x4A00A9, bytes.fromhex(
            "8b75048b46045056e83b0700008946048b48048d780885ff8901740b"
            "b90a0000008d74242cf3a58b4d0833f64189742420"
        )),
        (0x4A0117, 0x4A0143, bytes.fromhex(
            "8b75048bcd8b46045056e89a0600008946048b48048d780885ff8901"
            "740bb90a0000008d74242cf3a5ff4508"
        )),
        (0x4A020C, 0x4A0238, bytes.fromhex(
            "8b75048bcd8b46045056e8a50500008946048b48048d780885ff8901"
            "740bb90a0000008d74242cf3a5ff4508"
        )),
        (0x4A0275, 0x4A02A9, bytes.fromhex(
            "8b75048bcd8b56045256e83c0500008946048b48048d780885ff8901"
            "740bb90a0000008d74242cf3a58b45088b7c241840894508"
        )),
    )
    retail_addresses = [
        _source_instruction_address(instruction)
        for instruction in retail_instructions
    ]
    for start, end, body in retail_runs:
        selected = [
            (index, instruction, address_value(address))
            for index, (instruction, address) in enumerate(
                zip(retail_instructions, retail_addresses)
            )
            if address and start <= address_value(address) < end
        ]
        if (
            not selected
            or [row[0] for row in selected]
            != list(range(selected[0][0], selected[-1][0] + 1))
            or selected[0][2] != start
            or selected[-1][2] + len(selected[-1][1].bytes) != end
            or b"".join(
                bytes(int(item, 16) for item in instruction.bytes)
                for _index, instruction, _address in selected
            )
            != body
        ):
            raise ValueError(
                "zSnd snapshot AppendPayload projection rejects immutable "
                "retail inline NewNode population or bytes"
            )

    for ordinal in append_ordinals:
        result[ordinal] = dict(expected[ordinal])
    return result


def _zsnd_snapshot_is_playing_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    retail_instructions: Sequence[Instruction],
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Project two independent exact backend IsPlaying inline-helper arms."""

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != "0x49fff0":
        return result
    caller = candidate.caller_definition
    if (
        caller_identity != _ZSND_SNAPSHOT_CREATE_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive) != "0x4a0300"
        or len(expected) != 18
        or len(result) != 18
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(expected))
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(result))
        or caller is None
        or caller.symbol != _ZSND_SNAPSHOT_CREATE_CALLER_SYMBOL
        or len(caller.data) != 0x250
        or len(caller.relocation_mask) != 0x250
        or caller.section_start != 0
        or caller.section_end != 0x250
    ):
        raise ValueError(
            "zSnd snapshot IsPlaying projections reject shared caller extent "
            "or invocation population drift"
        )

    source_path = str(
        (
            REPO_ROOT / "src" / "GameZRecoil" / "zSound" / "zsnd_play.cpp"
        ).resolve()
    )
    retail_addresses = [
        _source_instruction_address(instruction)
        for instruction in retail_instructions
    ]
    specs = (
        {
            "label": "A3D",
            "prefix": "?A3dSourceIsPlaying@?%",
            "ordinals": (6, 9),
            "slot": 0xE0,
            "body": bytes.fromhex(
                "8b 01 56 8b f2 56 51 ff 90 e0 00 00 00 8b 06 83 "
                "e0 01 5e c3 90 90 90 90 90 90 90 90 90 90 90 90"
            ),
            "caller_runs": (
                (0xCD, bytes.fromhex(
                    "8b4b4c85c974258d542410e80000000084c07418"
                )),
                (0x10D, bytes.fromhex(
                    "8b83840000008b34b885f6745f8b4e088d542410"
                    "e80000000084c0744f"
                )),
            ),
            "relocations": (0xD9, 0x122),
            "retail_runs": (
                (0x4A00EF, 0x4A010B, bytes.fromhex(
                    "8b434c85c0744d8b088d5424145250ff91e0000000"
                    "f6442414017438"
                )),
                (0x4A0157, 0x4A017C, bytes.fromhex(
                    "8b8b840000008b34b985f6746b8b46088d4c24145150"
                    "8b10ff92e0000000f6442414017453"
                )),
            ),
        },
        {
            "label": "DirectSound",
            "prefix": "?DirectSoundBufferIsPlaying@?%",
            "ordinals": (12, 15),
            "slot": 0x24,
            "body": bytes.fromhex(
                "8b01568bf25651ff50248b0683e0015ec3"
                "909090909090909090909090909090"
            ),
            "caller_runs": (
                (0x18A, bytes.fromhex(
                    "8b4b4c85c974258d542410e80000000084c07418"
                )),
                (0x1C2, bytes.fromhex(
                    "8b83840000008b34b885f674278b4e088d542410"
                    "e80000000084c07417"
                )),
            ),
            "relocations": (0x196, 0x1D7),
            "retail_runs": (
                (0x4A01E7, 0x4A0200, bytes.fromhex(
                    "8b434c85c0744a8b088d5424145250ff5124"
                    "f6442414017438"
                )),
                (0x4A0248, 0x4A026A, bytes.fromhex(
                    "8b8b840000008b34b985f674548b46088d4c24145150"
                    "8b10ff5224f644241401743f"
                )),
            ),
        },
    )

    def structural_name(name: str, prefix: str) -> bool:
        suffix = "@@YI_NPAUzSndBuffer@@PAH@Z"
        beginning = f"{prefix}{source_path}"
        if not name.startswith(beginning) or not name.endswith(suffix):
            return False
        salt = name[len(beginning) : -len(suffix)]
        return bool(salt) and salt.isdecimal()

    def exact_retail_run(start: int, end: int, body: bytes) -> bool:
        selected = [
            (index, instruction, address_value(address))
            for index, (instruction, address) in enumerate(
                zip(retail_instructions, retail_addresses)
            )
            if address and start <= address_value(address) < end
        ]
        return bool(
            selected
            and [row[0] for row in selected]
            == list(range(selected[0][0], selected[-1][0] + 1))
            and selected[0][2] == start
            and selected[-1][2] + len(selected[-1][1].bytes) == end
            and b"".join(
                bytes(int(item, 16) for item in instruction.bytes)
                for _index, instruction, _address in selected
            )
            == body
        )

    for spec in specs:
        ordinals = tuple(spec["ordinals"])
        helper_names = {
            str(result[ordinal].get("target_identity", ""))[
                len("candidate-local-coff:") :
            ]
            for ordinal in ordinals
            if str(result[ordinal].get("target_identity", "")).startswith(
                "candidate-local-coff:"
            )
        }
        if len(helper_names) != 1:
            continue
        helper_name = next(iter(helper_names))
        if not structural_name(helper_name, str(spec["prefix"])):
            continue
        matching_definitions = [
            definition
            for name, definition in candidate.tu_local_function_definitions.items()
            if structural_name(name, str(spec["prefix"]))
        ]
        if len(matching_definitions) != 1:
            continue
        helper = matching_definitions[0]
        helper_symbols = [
            row for row in caller.coff_symbols if row.name == helper_name
        ]
        if len(helper_symbols) != 1:
            continue
        helper_symbol = helper_symbols[0]
        aliases = [
            row
            for row in caller.coff_symbols
            if row.index != helper_symbol.index
            and (
                row.storage_class == 105
                and row.weak_external_tag_index == helper_symbol.index
                or row.storage_class == IMAGE_SYM_CLASS_EXTERNAL
                and row.section_number == helper_symbol.section_number
                and row.value == helper_symbol.value
            )
        ]
        expected_shape = all(
            expected[ordinal].get("form") == "call"
            and expected[ordinal].get("dispatch") == "indirect"
            and expected[ordinal].get("identity_kind") == "virtual-slot"
            and expected[ordinal].get("target_identity") == ""
            and expected[ordinal].get("storage_identity")
            == _ZSND_PLAY_DIRECTSOUND_RETAIL_BACKEND_VPTR
            and expected[ordinal].get("slot_displacement") == spec["slot"]
            and expected[ordinal].get("cleanup_bytes") is None
            and result[ordinal].get("form") == "call"
            and result[ordinal].get("dispatch") == "direct"
            and result[ordinal].get("identity_kind") == "direct"
            and result[ordinal].get("storage_identity") == ""
            and result[ordinal].get("slot_displacement") is None
            and result[ordinal].get("cleanup_bytes") is None
            and result[ordinal].get("target_identity")
            == f"candidate-local-coff:{helper_name}"
            for ordinal in ordinals
        )
        relocation_offsets = tuple(spec["relocations"])
        caller_relocations = {
            (row.offset, row.type, row.symbol_name, row.symbol_index)
            for row in caller.relocations
            if row.symbol_name == helper_name
        }
        required_relocations = {
            (offset, IMAGE_REL_I386_REL32, helper_name, helper_symbol.index)
            for offset in relocation_offsets
        }
        exact_helper = bool(
            helper.symbol == helper_name
            and helper.data == spec["body"]
            and helper.section_size == 0x20
            and helper.section_external_functions == (helper_name,)
            and helper.section_is_comdat is True
            and helper.comdat_selection == 2
            and not helper.relocations
            and not any(helper.relocation_mask)
            and helper.instructions
            and not helper.local_control_flow_indices
            and not helper.local_control_flow_targets
            and helper.source_provenance in {"", source_path}
            and helper_symbol.value == 0
            and helper_symbol.section_number > 0
            and helper_symbol.symbol_type == 0x20
            and helper_symbol.storage_class == IMAGE_SYM_CLASS_EXTERNAL
            and helper_symbol.aux_count == 0
            and helper_symbol.section_name == ".text"
            and helper_symbol.section_size == 0x20
            and helper_symbol.natural_end == 0x20
            and helper_symbol.section_characteristics & IMAGE_SCN_LNK_COMDAT
            and not aliases
        )
        exact_caller = bool(
            all(
                caller.data[offset : offset + len(body)] == body
                for offset, body in spec["caller_runs"]
            )
            and caller_relocations == required_relocations
            and all(
                caller.data[offset : offset + 4] == b"\x00" * 4
                and all(
                    caller.relocation_mask[index]
                    for index in range(offset, offset + 4)
                )
                for offset in relocation_offsets
            )
        )
        exact_retail = all(
            exact_retail_run(start, end, body)
            for start, end, body in spec["retail_runs"]
        )
        if not (expected_shape and exact_helper and exact_caller and exact_retail):
            continue
        for ordinal in ordinals:
            result[ordinal] = dict(expected[ordinal])
    return result


def _zsnd_apply_mute_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    retail_instructions: Sequence[Instruction],
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Reorder the exact dual-backend caller and inline FloatFromBits."""

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != "0x4a0670":
        return result
    if (
        caller_identity != "symbol:recoil:function:0x4a0670"
        or normalize_address(caller_end_exclusive) != "0x4a07a0"
        or len(expected) != 9
        or len(result) != 9
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(expected))
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(result))
    ):
        return result
    direct_specs = (
        (0, _ZSND_IS_MUTED_IDENTITY),
        (1, _ZSND_SNAPSHOT_CREATE_CALLER_IDENTITY),
        (2, _ZSND_IS_MUTED_IDENTITY),
        (4, _ZSND_IS_MUTED_IDENTITY),
        (7, _ZSND_PLAY_SIMPLE_IDENTITY),
    )
    if any(
        result[ordinal].get("dispatch") != "direct"
        or result[ordinal].get("target_identity") != identity
        for ordinal, identity in direct_specs
    ):
        return result
    for ordinal, slot in ((3, 0x3C), (5, 0xA0), (8, 0xA0)):
        row = result[ordinal]
        if (
            row.get("dispatch") != "indirect"
            or row.get("identity_kind") != "virtual-slot"
            or row.get("target_identity") != ""
            or row.get("storage_identity") != _ZSND_APPLY_MUTE_CANDIDATE_VPTR
            or row.get("slot_displacement") != slot
        ):
            return result
    helper_identity = str(result[6].get("target_identity", ""))
    if not helper_identity.startswith("candidate-local-coff:"):
        return result
    helper_name = helper_identity[len("candidate-local-coff:") :]
    match = _VC5_TU_LOCAL_CALLABLE_RE.fullmatch(helper_name)
    helper = candidate.tu_local_function_definitions.get(helper_name)
    if (
        match is None
        or match.group("head") != "?FloatFromBits@?%"
        or match.group("suffix") != "YIMH@Z"
        or not PureWindowsPath(match.group("source")).as_posix().casefold().endswith(
            "src/gamezrecoil/zsound/zsnd_play.cpp"
        )
        or helper is None
        or helper.data != bytes.fromhex(
            "51 89 4c 24 00 d9 44 24 00 59 c3 90 90 90 90 90"
        )
        or helper.section_size != 0x10
        or helper.section_external_functions != (helper_name,)
        or not helper.section_is_comdat
        or helper.comdat_selection != 1
        or helper.relocations
        or any(helper.relocation_mask)
    ):
        return result
    retail_by_address = {
        address_value(address): instruction
        for instruction in retail_instructions
        if (address := _source_instruction_address(instruction))
    }
    retail_calls = (
        (0x4A0685, bytes.fromhex("e8 16 01 00 00")),
        (0x4A06B5, bytes.fromhex("e8 36 f9 ff ff")),
        (0x4A06E9, bytes.fromhex("e8 b2 00 00 00")),
        (0x4A06FD, bytes.fromhex("ff 91 a0 00 00 00")),
        (0x4A070E, bytes.fromhex("e8 ed f2 ff ff")),
        (0x4A0718, bytes.fromhex("ff 95 a0 00 00 00")),
        (0x4A074F, bytes.fromhex("e8 4c 00 00 00")),
        (0x4A0766, bytes.fromhex("ff 51 3c")),
        (0x4A0778, bytes.fromhex("ff 52 3c")),
    )
    if any(
        address not in retail_by_address
        or bytes(int(item, 16) for item in retail_by_address[address].bytes) != body
        for address, body in retail_calls
    ):
        return result
    expected_indirect_specs = ((3, 0xA0), (5, 0xA0), (7, 0x3C), (8, 0x3C))
    if any(
        expected[ordinal].get("form") != "call"
        or expected[ordinal].get("dispatch") != "indirect"
        or expected[ordinal].get("identity_kind") != "virtual-slot"
        or expected[ordinal].get("target_identity") != ""
        or expected[ordinal].get("storage_identity")
        != _ZSND_APPLY_MUTE_RETAIL_VPTR
        or expected[ordinal].get("slot_displacement") != slot
        or expected[ordinal].get("cleanup_bytes") is not None
        for ordinal, slot in expected_indirect_specs
    ):
        return result
    projected = [
        dict(result[0]), dict(result[1]), dict(result[4]), dict(result[5]),
        dict(result[7]), dict(result[8]), dict(result[2]),
        dict(result[3]), dict(result[3]),
    ]
    for ordinal, row in enumerate(projected):
        row["ordinal"] = ordinal
    for ordinal, _slot in expected_indirect_specs:
        projected[ordinal]["storage_identity"] = expected[ordinal][
            "storage_identity"
        ]
    return projected


