        (12, registry_symbol.index, IMAGE_REL_I386_DIR32,
         "_g_zSnd_SampleSetRegistry"),
        (19, end_symbol.index, IMAGE_REL_I386_REL32,
         _ZSND_VECTOR_END_COFF),
        (37, destroy_symbol.index, IMAGE_REL_I386_REL32,
         "?DestroyOwnedData@zSndSampleSet@@QAEXXZ"),
