def _zsnd_wave_data_archive_scalar_destructor_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    retail_instructions: Sequence[Instruction],
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge: BinaryNinjaBridge,
) -> list[dict[str, Any]]:
    """Expand only archive loading's exact flag-1 WaveData scalar destructor."""

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != "0x4a0fb0":
        return result

    expected_specs = (
        ("provider", "provider:recoil:function:0x4c5b76", 4),
        ("direct", "symbol:recoil:function:0x4a53f0", None),
        ("direct", "symbol:recoil:function:0x4a5600", None),
        ("direct", "symbol:recoil:function:0x4a2ea0", None),
        ("direct", ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_IDENTITY, None),
        ("provider", "provider:recoil:function:0x4c5b6a", 4),
    )
    expected_population = [
        {
            "ordinal": ordinal,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": kind,
            "target_identity": target,
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": cleanup,
        }
        for ordinal, (kind, target, cleanup) in enumerate(expected_specs)
    ]
    candidate_population = [dict(row) for row in expected_population[:4]]
    candidate_population.append(
        {
            "ordinal": 4,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": (
                "candidate-local-coff:" + _ZSND_WAVE_DATA_SCALAR_DTOR_COFF
            ),
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": 4,
        }
    )
    delete_identity = indexes.by_address.get("0x4c5b6a", "")
    new_identity = indexes.by_address.get("0x4c5b76", "")
    if (
        caller_identity != "symbol:recoil:function:0x4a0fb0"
        or normalize_address(caller_end_exclusive) != "0x4a1090"
        or indexes.by_address.get("0x4a0fb0") != caller_identity
        or indexes.by_address.get("0x4a5440")
        != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_IDENTITY
        or indexes.by_candidate_name.get(
            ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_SYMBOL
        )
        != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_IDENTITY
        or ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_IDENTITY in indexes.provider_ids
        or new_identity != "provider:recoil:function:0x4c5b76"
        or new_identity not in indexes.provider_ids
        or delete_identity != "provider:recoil:function:0x4c5b6a"
        or delete_identity not in indexes.provider_ids
        or [dict(row) for row in expected] != expected_population
        or result != candidate_population
    ):
        raise ValueError(
            "zSnd archive WaveData scalar-dtor projection requires the exact "
            "registered caller and five-to-six invocation populations"
        )

    caller = candidate.caller_definition
    definitions = candidate.tu_local_function_definitions
    caller_source = definitions.get(_ZSND_WAVE_DATA_LOAD_ARCHIVE_COFF)
    scalar = definitions.get(_ZSND_WAVE_DATA_SCALAR_DTOR_COFF)
    complete = definitions.get(_ZSND_WAVE_DATA_COMPLETE_DTOR_COFF)
    symbols = caller.coff_symbols if caller is not None else ()
    required_names = (
        _ZSND_WAVE_DATA_LOAD_ARCHIVE_COFF,
        "$L35225",
        "__except_list",
        "??2@YAPAXI@Z",
        "??0zSndWaveData@@QAE@PBDH@Z",
        "?LoadAndParseFromIndexArchiveIfNeeded@zSndWaveData@@QAEHPAUzIndexArchive@@@Z",
        "?InitFromWaveData@zSndSample@@QAIHPAUzSndWaveData@@@Z",
        _ZSND_WAVE_DATA_SCALAR_DTOR_COFF,
        _ZSND_WAVE_DATA_COMPLETE_DTOR_COFF,
        ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_SYMBOL,
        "??3@YAXPAX@Z",
    )
    symbols_by_name = {
        name: [row for row in symbols if row.name == name]
        for name in required_names
    }
    if (
        caller is None
        or caller.symbol != _ZSND_WAVE_DATA_LOAD_ARCHIVE_COFF
        or caller_source is None
        or scalar is None
        or complete is None
        or any(len(rows) != 1 for rows in symbols_by_name.values())
    ):
        raise ValueError(
            "zSnd archive WaveData scalar-dtor projection rejects missing, "
            "duplicate, or aliased caller/helper/provider COFF authority"
        )
    caller_symbol = symbols_by_name[_ZSND_WAVE_DATA_LOAD_ARCHIVE_COFF][0]
    scalar_symbol = symbols_by_name[_ZSND_WAVE_DATA_SCALAR_DTOR_COFF][0]
    complete_symbol = symbols_by_name[_ZSND_WAVE_DATA_COMPLETE_DTOR_COFF][0]
    ordinary_symbol = symbols_by_name[
        ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_SYMBOL
    ][0]
    delete_symbol = symbols_by_name["??3@YAXPAX@Z"][0]
    defined_rows = (
        (caller_symbol, caller_source, 0xE0, 1),
        (scalar_symbol, scalar, 0x20, 2),
        (complete_symbol, complete, 0x10, 2),
    )
    if (
        len({row.section_number for row, *_rest in defined_rows}) != 3
        or any(
            row.value != 0
            or row.section_number <= 0
            or row.symbol_type != 0x20
            or row.storage_class != IMAGE_SYM_CLASS_EXTERNAL
            or row.aux_count != 0
            or row.weak_external_tag_index is not None
            or row.weak_external_characteristics is not None
            or row.section_name != ".text"
            or row.section_size != size
            or row.natural_end != size
            or row.section_characteristics & IMAGE_SCN_LNK_COMDAT == 0
            or definition.symbol != row.name
            or definition.section_size != size
            or definition.section_external_functions != (row.name,)
            or not definition.section_is_comdat
            or definition.comdat_selection != selection
            for row, definition, size, selection in defined_rows
        )
        or any(
            row.value != 0
            or row.section_number != 0
            or row.symbol_type != 0x20
            or row.storage_class != IMAGE_SYM_CLASS_EXTERNAL
            or row.aux_count != 0
            or row.weak_external_tag_index is not None
            or row.weak_external_characteristics is not None
            or row.section_name
            or row.section_size != 0
            or row.natural_end != 0
            for row in (ordinary_symbol, delete_symbol)
        )
    ):
        raise ValueError(
            "zSnd archive WaveData scalar-dtor projection rejects COFF extent, "
            "COMDAT selection, ABI, external, or weak-alias drift"
        )

    caller_relocation_specs = (
        (3, "$L35225", IMAGE_REL_I386_DIR32),
        (9, "__except_list", IMAGE_REL_I386_DIR32),
        (17, "__except_list", IMAGE_REL_I386_DIR32),
        (59, "??2@YAPAXI@Z", IMAGE_REL_I386_REL32),
        (88, "??0zSndWaveData@@QAE@PBDH@Z", IMAGE_REL_I386_REL32),
        (110, "?LoadAndParseFromIndexArchiveIfNeeded@zSndWaveData@@QAEHPAUzIndexArchive@@@Z", IMAGE_REL_I386_REL32),
        (124, "?InitFromWaveData@zSndSample@@QAIHPAUzSndWaveData@@@Z", IMAGE_REL_I386_REL32),
        (158, _ZSND_WAVE_DATA_SCALAR_DTOR_COFF, IMAGE_REL_I386_REL32),
        (203, "__except_list", IMAGE_REL_I386_DIR32),
    )
    caller_relocations = tuple(
        (offset, symbols_by_name[name][0].index, kind, name)
        for offset, name, kind in caller_relocation_specs
    )
    caller_mask = tuple(
        any(offset <= byte < offset + 4 for offset, *_rest in caller_relocations)
        for byte in range(0xE0)
    )
    scalar_relocations = (
        (4, complete_symbol.index, IMAGE_REL_I386_REL32,
         _ZSND_WAVE_DATA_COMPLETE_DTOR_COFF),
        (17, delete_symbol.index, IMAGE_REL_I386_REL32, "??3@YAXPAX@Z"),
    )
    scalar_body = bytes.fromhex(
        "56 8b f1 e8 00 00 00 00 f6 44 24 08 01 74 09 56 "
        "e8 00 00 00 00 83 c4 04 8b c6 5e c2 04 00 90 90"
    )
    complete_relocations = (
        (1, ordinary_symbol.index, IMAGE_REL_I386_REL32,
         ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_SYMBOL),
    )
    complete_body = b"\xe9\x00\x00\x00\x00" + b"\x90" * 0x0B
    sources = {
        PureWindowsPath(item.source_provenance).as_posix().casefold()
        for item in (caller_source, scalar, complete)
    }
    if (
        len(sources) != 1
        or not next(iter(sources)).endswith(
            "src/gamezrecoil/zsound/zsnd_play.cpp"
        )
        or candidate.instructions != caller_source.instructions
        or candidate.local_control_flow_indices
        or candidate.local_control_flow_targets
        or caller.data != _ZSND_WAVE_DATA_LOAD_ARCHIVE_CANDIDATE_BODY
        or caller_source.data != _ZSND_WAVE_DATA_LOAD_ARCHIVE_CANDIDATE_BODY
        or caller.relocations != caller_source.relocations
        or caller.relocation_mask != caller_source.relocation_mask
        or tuple(
            (row.offset, row.symbol_index, row.type, row.symbol_name)
            for row in caller.relocations
        ) != caller_relocations
        or caller.relocation_mask != caller_mask
        or caller_source.local_control_flow_indices
        or caller_source.local_control_flow_targets
        or scalar.data != scalar_body
        or tuple(
            (row.offset, row.symbol_index, row.type, row.symbol_name)
            for row in scalar.relocations
        ) != scalar_relocations
        or scalar.relocation_mask != tuple(
            any(offset <= byte < offset + 4 for offset, *_rest in scalar_relocations)
            for byte in range(0x20)
        )
        or scalar.local_control_flow_indices
        or scalar.local_control_flow_targets
        or complete.data != complete_body
        or tuple(
            (row.offset, row.symbol_index, row.type, row.symbol_name)
            for row in complete.relocations
        ) != complete_relocations
        or complete.relocation_mask
        != (False, True, True, True, True) + (False,) * 0x0B
        or complete.local_control_flow_indices
        or complete.local_control_flow_targets
    ):
        raise ValueError(
            "zSnd archive WaveData scalar-dtor projection rejects exact caller/"
            "helper body, relocation, source, CFG, clobber, or alias drift"
        )

    caller_semantics = {
        _source_instruction_address(row): (
            row.raw_text.strip().casefold(), tuple(item.lower() for item in row.bytes)
        )
        for row in caller_source.instructions
        if _source_instruction_address(row) in {
            "0x93", "0x95", "0x97", "0x99", "0x9b", "0x9d", "0xa2"
        }
    }
    if caller_semantics != {
        "0x93": ("test esi, esi", ("85", "f6")),
        "0x95": ("mov dword [edi], eax", ("89", "07")),
        "0x97": ("je $l35217", ("74", "09")),
        "0x99": ("push 1", ("6a", "01")),
        "0x9b": ("mov ecx, esi", ("8b", "ce")),
        "0x9d": (f"call {_ZSND_WAVE_DATA_SCALAR_DTOR_COFF}".casefold(),
                   ("e8", "00", "00", "00", "00")),
        "0xa2": ("mov edx, dword _this$[esp+36]", ("8b", "54", "24", "10")),
    }:
        raise ValueError(
            "zSnd archive WaveData scalar-dtor projection rejects exact flag-1, "
            "ESI receiver, guard, call, or post-call ownership lineage"
        )
    scalar_semantics = tuple(
        (_source_instruction_address(row), row.raw_text.strip().casefold(),
         tuple(item.lower() for item in row.bytes))
        for row in scalar.instructions
    )
    if scalar_semantics != (
        ("0x0", "push esi", ("56",)),
        ("0x1", "mov esi, ecx", ("8b", "f1")),
        ("0x3", f"call {_ZSND_WAVE_DATA_COMPLETE_DTOR_COFF}".casefold(),
         ("e8", "00", "00", "00", "00")),
        ("0x8", "test byte ___flags$[esp], 1", ("f6", "44", "24", "08", "01")),
        ("0xd", "je $l34042", ("74", "09")),
        ("0xf", "push esi", ("56",)),
        ("0x10", "call ??3@yaxpax@z", ("e8", "00", "00", "00", "00")),
        ("0x15", "add esp, 4", ("83", "c4", "04")),
        ("0x18", "mov eax, esi", ("8b", "c6")),
        ("0x1a", "pop esi", ("5e",)),
        ("0x1b", "ret 4", ("c2", "04", "00")),
    ):
        raise ValueError(
            "zSnd archive WaveData scalar-dtor projection rejects exact wrapper "
            "destructor/delete flag ABI or receiver/result preservation"
        )
    complete_semantics = tuple(
        (_source_instruction_address(row), row.raw_text.strip().casefold(),
         tuple(item.lower() for item in row.bytes))
        for row in complete.instructions
    )
    if complete_semantics != (
        ("0x0", f"jmp {ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_SYMBOL}".casefold(),
         ("e9", "00", "00", "00", "00")),
    ):
        raise ValueError(
            "zSnd archive WaveData scalar-dtor projection rejects exact complete-to-authored destructor tail"
        )

    retail_addresses = _instruction_runtime_addresses(
        retail_instructions, source="bn", caller_start=0x4A0FB0
    )
    retail_by_address = {
        address: tuple(item.lower() for item in row.bytes)
        for row, address in zip(retail_instructions, retail_addresses)
        if address is not None
    }
    retail_sequence = (
        0x4A1047, 0x4A1049, 0x4A104B, 0x4A104D,
        0x4A1052, 0x4A1053, 0x4A1058,
    )
    if (
        {address: retail_by_address.get(address) for address in retail_sequence}
        != {
            0x4A1047: ("85", "f6"),
            0x4A1049: ("74", "10"),
            0x4A104B: ("8b", "ce"),
            0x4A104D: ("e8", "ee", "43", "00", "00"),
            0x4A1052: ("56",),
            0x4A1053: ("e8", "12", "4b", "02", "00"),
            0x4A1058: ("83", "c4", "04"),
        }
        or _hexdump_bytes(bridge.hexdump("0x4a0fb0", 0xE0))
        != _ZSND_WAVE_DATA_LOAD_ARCHIVE_RETAIL_BODY
        or _hexdump_bytes(bridge.hexdump("0x4a5440", 0x20))
        != bytes.fromhex(
            "56 8b f1 e8 78 01 00 00 8b 76 04 85 f6 74 0a 56 "
            "ff 15 b4 c5 4c 00 83 c4 04 5e c3 90 90 90 90 90"
        )
    ):
        raise ValueError(
            "zSnd archive WaveData scalar-dtor projection rejects immutable "
            "retail destructor/delete sequence, caller body, or authored target"
        )
    return expected_population


