def _mission_current_artifact_member_provenance_contract(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Normalize two exact direct-member spellings in current mission.cpp.

    The source already expresses both receivers as typed members.  VC5's COD
    renders one extra dereference/address wrapper differently from retail BN,
    so the comparison may normalize only the complete reviewed caller/site
    package below.  No other Mission row, including the genuine 0x41ab70 and
    0x41c000 source-model residuals, enters this projection.
    """

    profiles = {
        (
            "symbol:recoil:function:0x41a350",
            "0x41a350",
            "0x41a3d0",
        ): (
            "?OnActivate@HudUiClampedIntStepButton@@UAEXXZ",
            (
                (
                    3,
                    0x6A,
                    bytes.fromhex("ff 50 20"),
                    "load(load(this+0x14c))",
                    "load(exact-receiver-field(this,+0x14c))",
                    32,
                ),
            ),
        ),
        (
            "symbol:recoil:function:0x41a5b0",
            "0x41a5b0",
            "0x41a7b0",
        ): (
            "?OnActivate@HudUiNetGameSetupPanel_LaunchButton@@UAEXXZ",
            (
                (
                    11,
                    0x11D,
                    bytes.fromhex("ff 92 8c 00 00 00"),
                    "load(load(this+0xc8)+0xba20)",
                    "load(address(load(this+0xc8)+0xba20))",
                    140,
                ),
                (
                    17,
                    0x18E,
                    bytes.fromhex("ff 92 8c 00 00 00"),
                    "load(address(load(this+0xc8)+0xba20))",
                    "load(load(this+0xc8)+0xba20)",
                    140,
                ),
            ),
        ),
    }
    key = (
        caller_identity,
        normalize_address(caller_start),
        normalize_address(caller_end_exclusive),
    )
    profile = profiles.get(key)
    result = [dict(row) for row in candidate_contract]
    if profile is None:
        return result

    caller_symbol, sites = profile
    definition = candidate.caller_definition
    invocation_indices = _candidate_static_invocation_indices(
        candidate,
        caller_start="0x0",
        caller_end_exclusive=hex(max(1, len(definition.data)))
        if definition is not None
        else "0x1",
    )
    instruction_offsets = _candidate_complete_instruction_offsets(candidate)
    if (
        definition is None
        or definition.symbol != caller_symbol
        or definition.section_start != 0
        or definition.section_end != address_value(key[2]) - address_value(key[1])
        or len(definition.data) != definition.section_end
    ):
        raise ValueError(
            "Mission typed-member provenance profile rejects caller, extent, "
            "COD site, retail row, or current candidate spelling drift"
        )
    for (
        ordinal,
        call_offset,
        call_bytes,
        candidate_storage,
        retail_storage,
        slot_displacement,
    ) in sites:
        try:
            instruction_index = invocation_indices[ordinal]
            instruction = candidate.instructions[instruction_index]
            encoded = bytes(int(value, 16) for value in instruction.bytes)
            expected_row = dict(expected[ordinal])
            candidate_row = result[ordinal]
        except (IndexError, TypeError, ValueError) as exc:
            raise ValueError(
                "Mission typed-member provenance profile lacks its exact "
                "caller or invocation population"
            ) from exc
        exact_retail_row = {
            "ordinal": ordinal,
            "form": "call",
            "dispatch": "indirect",
            "identity_kind": "virtual-slot",
            "target_identity": "",
            "storage_identity": retail_storage,
            "slot_displacement": slot_displacement,
            "cleanup_bytes": None,
        }
        exact_candidate_row = {
            **exact_retail_row,
            "storage_identity": candidate_storage,
        }
        if (
            instruction_offsets[instruction_index] != call_offset
            or _instruction_mnemonic(instruction) != "call"
            or encoded != call_bytes
            or expected_row != exact_retail_row
            or candidate_row != exact_candidate_row
        ):
            raise ValueError(
                "Mission typed-member provenance profile rejects caller, "
                "extent, COD site, retail row, or current candidate spelling drift"
            )
        candidate_row["storage_identity"] = retail_storage
    return result


