def _recoilapp_terminal_frame_candidate_cleanup_projection(
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Remove one exact candidate local-frame reversal from call cleanup."""

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != "0x42f8e0":
        return result
    exact_row = {
        "ordinal": 16,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "direct",
        "target_identity": "symbol:recoil:function:0x462630",
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": 0x24,
    }
    definition = candidate.caller_definition
    offsets = _candidate_complete_instruction_offsets(candidate)
    by_offset = {
        offset: instruction
        for offset, instruction in zip(offsets, candidate.instructions)
        if offset is not None
    }
    cleanup_relocations = (
        []
        if definition is None
        else [
            row
            for row in definition.relocations
            if row.symbol_name == "?Cleanup@zFMV_Script@@QAEXXZ"
        ]
    )
    if (
        caller_identity != "symbol:recoil:function:0x42f8e0"
        or normalize_address(caller_end_exclusive) != "0x42f9d0"
        or len(result) != 17
        or result[16] != exact_row
        or definition is None
        or definition.symbol != "?OnDeactivate@RecoilApp_PlayState@@UAEXXZ"
        or bytes(int(item, 16) for item in by_offset[0x00].bytes)
        != b"\x83\xec\x24"
        or bytes(int(item, 16) for item in by_offset[0xB0].bytes)
        != b"\xe8\x00\x00\x00\x00"
        or bytes(int(item, 16) for item in by_offset[0xB5].bytes)
        != b"\x83\xc4\x24"
        or bytes(int(item, 16) for item in by_offset[0xB8].bytes) != b"\xc3"
        or len(cleanup_relocations) != 1
        or cleanup_relocations[0].offset != 0xB1
        or cleanup_relocations[0].type != IMAGE_REL_I386_REL32
        or cleanup_relocations[0].offset + 4 > len(definition.data)
        or definition.data[0xB1:0xB5] != b"\x00\x00\x00\x00"
        or not all(definition.relocation_mask[0xB1:0xB5])
    ):
        raise CandidateCallContractEvidenceError(
            "RecoilApp PlayState candidate terminal-frame cleanup package drifted"
        )
    result[16]["cleanup_bytes"] = None
    return result


def _recoilapp_leave_network_shutdown_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Project one exact aggregate-vptr call to its reviewed retail body."""

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != "0x42f9d0":
        return result
    expected_direct = {
        "ordinal": 1,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "direct",
        "target_identity": "symbol:recoil:function:0x42e430",
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    candidate_virtual = {
        "ordinal": 1,
        "form": "call",
        "dispatch": "indirect",
        "identity_kind": "virtual-slot",
        "target_identity": "",
        "storage_identity": "load(storage:recoil:data:0x4e5ed0)",
        "slot_displacement": 0xB0,
        "cleanup_bytes": None,
    }
    definition = candidate.caller_definition
    global_name = "?g_RecoilApp@@3TRecoilAppStorage@@A"
    global_relocations = (
        []
        if definition is None
        else sorted(
            (
                row
                for row in definition.relocations
                if row.symbol_name == global_name
            ),
            key=lambda row: row.offset,
        )
    )
    if (
        caller_identity != "symbol:recoil:function:0x42f9d0"
        or normalize_address(caller_end_exclusive) != "0x42f9f0"
        or len(expected) != 3
        or len(result) != 3
        or expected[1] != expected_direct
        or result[1] != candidate_virtual
        or definition is None
        or definition.symbol
        != "?OnTryBecomeCurrent@RecoilApp_LeaveNetworkState@@UAEHXZ"
        or len(definition.data) != 0x20
        or definition.data[0x05:0x0F]
        != b"\xa1\x00\x00\x00\x00\xb9\x00\x00\x00\x00"
        or definition.data[0x0F:0x15] != b"\xff\x90\xb0\x00\x00\x00"
        or [(row.offset, row.type) for row in global_relocations]
        != [(0x06, IMAGE_REL_I386_DIR32), (0x0B, IMAGE_REL_I386_DIR32)]
        or not all(definition.relocation_mask[0x06:0x0A])
        or not all(definition.relocation_mask[0x0B:0x0F])
    ):
        raise CandidateCallContractEvidenceError(
            "RecoilApp leave-network ShutdownEngine projection package drifted"
        )
    result[1] = dict(expected_direct)
    return result


def _recoilapp_ftol_branch_join_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    provider_identity: str,
) -> list[dict[str, Any]]:
    """Project one exact VC5 ternary FPU join to retail branch callsites.

    Retail converts the X coordinate in either arm of the replicate-scale
    branch and then converts Y, yielding three static ``_ftol`` sites.  The
    current VC5 source selects the scale first and converts X after the join,
    yielding two sites.  The bridge above independently proves both candidate
    E8/REL32 sites and all three immutable retail rows.  Duplicate only that
    first logical conversion so the comparison retains every surrounding row.
    """

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != "0x432d60":
        return result
    exact_expected_ftol_row = {
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "provider",
        "target_identity": provider_identity,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    exact_candidate_ftol_row = {
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "direct",
        "target_identity": MSVC_FTOL_IAT_STORAGE_IDENTITY,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    expected_ftol = [
        row
        for row in expected
        if row.get("target_identity") == provider_identity
    ]
    candidate_ftol = [
        row
        for row in result
        if row.get("target_identity") == MSVC_FTOL_IAT_STORAGE_IDENTITY
    ]
    if (
        caller_identity != "symbol:recoil:function:0x432d60"
        or normalize_address(caller_end_exclusive) != "0x432e70"
        or len(result) + 1 != len(expected)
        or [row.get("ordinal") for row in expected_ftol] != [5, 6, 7]
        or [row.get("ordinal") for row in candidate_ftol] != [5, 6]
        or any(
            {key: row.get(key) for key in exact_expected_ftol_row}
            != exact_expected_ftol_row
            for row in expected_ftol
        )
        or any(
            {key: row.get(key) for key in exact_candidate_ftol_row}
            != exact_candidate_ftol_row
            for row in candidate_ftol
        )
    ):
        raise ValueError(
            "RecoilApp _ftol branch-join projection rejects caller, extent, "
            "population, ordinal, or direct-provider drift"
        )
    projected = [*result[:6], dict(result[5]), *result[6:]]
    for ordinal, row in enumerate(projected):
        row["ordinal"] = ordinal
    return projected


def _recoilapp_panel_array_destructor_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
) -> list[dict[str, Any]]:
    """Project three exact unrolled Panel destructors to retail EH helpers.

    VC5 emits the current source's one-element Panel array cleanup as a direct
    complete-destructor call.  Retail emitted the compiler EH array helper at
    the same logical call position.  This finite package retains the real
    authored Panel destructor identity everywhere else and projects only the
    reviewed caller, ordinal, call coordinate, and COFF relocation population.
    """

    result = [dict(row) for row in candidate_contract]
    start = normalize_address(caller_start)
    profiles = {
        "0x4349a0": (
            "symbol:recoil:function:0x4349a0",
            "0x434a80",
            "?Destructor@HudUiSaveLoadDialog@@QAEXXZ",
            1,
            0x35,
        ),
        "0x434a80": (
            "symbol:recoil:function:0x434a80",
            "0x434b70",
            "?Destructor@HudUiSaveGameDialog@@QAEXXZ",
            2,
            0x40,
        ),
        "0x434df0": (
            "symbol:recoil:function:0x434df0",
            "0x434ee0",
            "?Destructor@HudUiLoadGameDialog@@QAEXXZ",
            2,
            0x40,
        ),
    }
    profile = profiles.get(start)
    if profile is None:
        return result
    (
        exact_caller_identity,
        exact_caller_end,
        exact_caller_symbol,
        ordinal,
        call_offset,
    ) = profile
    panel_symbol_name = "??1HudUiPanel@@UAE@XZ"
    panel_symbol_id = "recoil:function:0x4bab40"
    panel_identity = f"symbol:{panel_symbol_id}"
    provider_symbol_id = "recoil:function:0x4c5ec0"
    provider_identity = f"provider:{provider_symbol_id}"
    expected_row = {
        "ordinal": ordinal,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "provider",
        "target_identity": provider_identity,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    candidate_row = {
        "ordinal": ordinal,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "direct",
        "target_identity": panel_identity,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    panel_symbol = document.collection("symbols").get(panel_symbol_id)
    provider_symbol = document.collection("symbols").get(provider_symbol_id)
    definition = candidate.caller_definition
    offsets = _candidate_complete_instruction_offsets(candidate)
    panel_instruction_rows = [
        (index, int(offset), instruction)
        for index, (offset, instruction) in enumerate(
            zip(offsets, candidate.instructions)
        )
        if offset is not None
        and _instruction_mnemonic(instruction) == "call"
        and _instruction_operand(instruction).strip() == panel_symbol_name
    ]
    panel_relocations = (
        []
        if definition is None
        else [
            row
            for row in definition.relocations
            if row.symbol_name == panel_symbol_name
        ]
    )
    panel_externals = (
        []
        if definition is None
        else [row for row in definition.coff_symbols if row.name == panel_symbol_name]
    )
    if (
        caller_identity != exact_caller_identity
        or normalize_address(caller_end_exclusive) != exact_caller_end
        or len(expected) != len(result)
        or ordinal >= len(expected)
        or ordinal >= len(result)
        or expected[ordinal] != expected_row
        or result[ordinal] != candidate_row
        or any(
            expected[index] != result[index]
            for index in range(len(result))
            if index != ordinal
        )
        or indexes.by_address.get("0x4bab40") != panel_identity
        or panel_identity in indexes.provider_ids
        or not isinstance(panel_symbol, Mapping)
        or _symbol_identity(panel_symbol_id, panel_symbol) != panel_identity
        or panel_symbol.get("pipeline_class")
        not in {"authored", "authored-lifecycle"}
        or panel_symbol.get("navigation_name") != "HudUiPanel::Destructor"
        or indexes.by_address.get("0x4c5ec0") != provider_identity
        or provider_identity not in indexes.provider_ids
        or not isinstance(provider_symbol, Mapping)
        or _symbol_identity(provider_symbol_id, provider_symbol)
        != provider_identity
        or provider_symbol.get("pipeline_class") != "non-authored"
        or provider_symbol.get("authored_order_role")
        != "compiler-generated-eh-helper"
        or provider_symbol.get("navigation_name") != "MSVC_EH_ArrayDestructor"
        or definition is None
        or definition.symbol != exact_caller_symbol
        or definition.section_start != 0
        or definition.section_end != 0x90
        or len(definition.data) != 0x90
        or definition.undefined_external_functions.count(panel_symbol_name) != 1
        or panel_symbol_name in definition.defined_external_functions
        or len(panel_instruction_rows) != 1
        or panel_instruction_rows[0][1] != call_offset
        or bytes(
            int(item, 16) for item in panel_instruction_rows[0][2].bytes
        )
        != b"\xe8\x00\x00\x00\x00"
        or len(panel_relocations) != 1
        or panel_relocations[0].offset != call_offset + 1
        or panel_relocations[0].type != IMAGE_REL_I386_REL32
        or len(panel_externals) != 1
        or panel_externals[0].section_number != 0
        or panel_externals[0].symbol_type != 0x20
        or panel_externals[0].storage_class != IMAGE_SYM_CLASS_EXTERNAL
        or panel_externals[0].aux_count != 0
        or panel_relocations[0].symbol_index != panel_externals[0].index
        or definition.data[call_offset : call_offset + 5]
        != b"\xe8\x00\x00\x00\x00"
        or not all(definition.relocation_mask[call_offset + 1 : call_offset + 5])
    ):
        raise CandidateCallContractEvidenceError(
            "RecoilApp Panel-array destructor projection rejects caller, "
            "identity, population, coordinate, body, or COFF relocation drift"
        )
    result[ordinal] = dict(expected_row)
    return result


def _czrecoilframe_constructor_branch_lifetime_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Normalize one exact VC5 branch-tail and CString lifetime reshaping.

    Retail shares the campaigns-only ``RemoveMenu`` call site with the else
    arm, sinks the formatted-title CString cleanup to the function exit, and
    selects the reviewed provider identity for the cached renderer-count
    helper.  The current compile emits a distinct else-arm call, performs the
    same cleanup immediately after SetWindowText, and retains its exact local
    helper identity.  The source-visible operations and paths are unchanged;
    this projection is bounded to the exact caller body, call sites,
    relocation populations, identities, and complete contract join.
    """

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != "0x430250":
        return result
    definition = candidate.caller_definition
    offsets = _candidate_complete_instruction_offsets(candidate)
    counts: dict[int, int] = {}
    for offset in offsets:
        if offset is not None:
            counts[int(offset)] = counts.get(int(offset), 0) + 1
    by_offset = {
        int(offset): instruction
        for offset, instruction in zip(offsets, candidate.instructions)
        if offset is not None and counts.get(int(offset)) == 1
    }
    exact_instruction_bodies = {
        0x198: b"\x8b\x86\x2c\x02\x00\x00",
        0x1A4: b"\x85\xc0",
        0x1A6: b"\x74\x44",
        0x1E8: b"\xff\xd7",
        0x1EA: b"\xeb\x18",
        0x1F2: b"\x8b\x3d\x00\x00\x00\x00",
        0x1F8: b"\x68\x00\x04\x00\x00",
        0x1FD: b"\x6a\x01",
        0x1FF: b"\x51",
        0x200: b"\xff\xd7",
        0x202: b"\x33\xdb",
        0x21F: b"\xff\xd7",
        0x281: b"\xe8\x00\x00\x00\x00",
        0x30E: b"\xe8\x00\x00\x00\x00",
    }
    remove_menu_relocations = (
        []
        if definition is None
        else [
            row
            for row in definition.relocations
            if row.symbol_name == "__imp__RemoveMenu@12"
        ]
    )
    cstring_constructor_relocations = (
        []
        if definition is None
        else [
            row
            for row in definition.relocations
            if row.symbol_name == "??0CString@@QAE@XZ"
        ]
    )
    cstring_destructor_relocations = (
        []
        if definition is None
        else [
            row
            for row in definition.relocations
            if row.symbol_name == "??1CString@@QAE@XZ"
        ]
    )
    renderer_count_symbol = (
        "?GetAcceptedHardwareRendererCount_Cached@zVid@@YAHXZ"
    )
    renderer_count_relocations = (
        []
        if definition is None
        else [
            row
            for row in definition.relocations
            if row.symbol_name == renderer_count_symbol
        ]
    )
    if (
        caller_identity != "symbol:recoil:function:0x430250"
        or normalize_address(caller_end_exclusive) != "0x4305f0"
        or len(expected) != 44
        or len(result) != 45
        or definition is None
        or definition.symbol != "??0CZRecoilFrame@@QAE@XZ"
        or definition.section_start != 0
        or definition.section_end != 0x380
        or len(definition.data) != 0x380
        or any(
            offset not in by_offset
            or bytes(int(item, 16) for item in by_offset[offset].bytes) != body
            or definition.data[offset : offset + len(body)] != body
            for offset, body in exact_instruction_bodies.items()
        )
        or [
            (row.offset, row.type) for row in remove_menu_relocations
        ]
        != [(0x1BE, IMAGE_REL_I386_DIR32), (0x1F4, IMAGE_REL_I386_DIR32)]
        or [
            (row.offset, row.type) for row in cstring_constructor_relocations
        ]
        != [(0x241, IMAGE_REL_I386_REL32)]
        or [
            (row.offset, row.type) for row in cstring_destructor_relocations
        ]
        != [
            (0x0B4, IMAGE_REL_I386_REL32),
            (0x26D, IMAGE_REL_I386_REL32),
            (0x282, IMAGE_REL_I386_REL32),
        ]
        or [
            (row.offset, row.type) for row in renderer_count_relocations
        ]
        != [(0x30F, IMAGE_REL_I386_REL32)]
        or definition.undefined_external_functions.count(
            renderer_count_symbol
        )
        != 1
        or renderer_count_symbol in definition.defined_external_functions
        or result[26].get("target_identity") != "iat:RemoveMenu"
        or result[26].get("storage_identity") != "iat:RemoveMenu"
        or result[35].get("target_identity")
        != "provider:recoil:function:0x4c5b88"
    ):
        raise CandidateCallContractEvidenceError(
            "CZRecoilFrame constructor branch/lifetime projection rejects "
            "caller, extent, body, coordinate, relocation, or identity drift"
        )
    # Candidate row 26 is the separately emitted else-arm RemoveMenu call.
    # After it is folded, the immediate CString cleanup is row 34; retail
    # sinks that cleanup after the final SetCursor call.
    result.pop(26)
    lifetime_cleanup = result.pop(34)
    result.append(lifetime_cleanup)
    for ordinal, row in enumerate(result):
        row["ordinal"] = ordinal
    if (
        result[37]
        != {
            "ordinal": 37,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": "symbol:recoil:function:0x4a9910",
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        }
        or dict(expected[37])
        != {
            "ordinal": 37,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "provider",
            "target_identity": "provider:recoil:function:0x4a7470",
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        }
    ):
        raise CandidateCallContractEvidenceError(
            "CZRecoilFrame constructor branch/lifetime projection rejects "
            "renderer caller-local or retail provider identity drift"
        )
    result[37] = dict(expected[37])
    if result != [dict(row) for row in expected]:
        raise CandidateCallContractEvidenceError(
            "CZRecoilFrame constructor branch/lifetime projection rejects "
            "a compensating, missing, reordered, or semantically unequal row"
        )
    return result


def _zinterp_camera_owner_candidate_validation(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    candidate_call_sites: Sequence[str],
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Prove the recovered CameraRotate/CameraGetTranslate owner boundary.

    This check never adds, removes, or reorders contract rows.  It binds the
    CameraRotate command arm to ParseFloatToken x3, SetPosition, and its
    immediate return, then follows CameraGetTranslate's exact local branch to
    the compiler-folded Logf/cleanup36 suffix it shares with a later command.
    Ordinary contract comparison remains authoritative for the retail-versus-
    candidate physical-call population; this validation-only proof prevents a
    compensating call or a revived row projection from hiding local owner drift.
    """

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != _ZINTERP_SHARED_LOGF_CALLER_START:
        return result

    def reject(detail: str) -> NoReturn:
        raise CandidateCallContractEvidenceError(
            "reviewed zInterp camera owner validation drifted: " + detail
        )

    caller = candidate.caller_definition
    if (
        caller_identity != _ZINTERP_SHARED_LOGF_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != _ZINTERP_SHARED_LOGF_CALLER_END_EXCLUSIVE
        or caller is None
        or caller.symbol != _ZINTERP_SHARED_LOGF_CANDIDATE_CALLER
        or caller.section_start != 0
        or caller.section_end != len(caller.data)
        or len(caller.relocation_mask) != len(caller.data)
        or len(candidate_call_sites) != len(result)
        or len(set(candidate_call_sites)) != len(candidate_call_sites)
        or any(
            row.get("ordinal") != ordinal
            for ordinal, row in enumerate(result)
        )
        or any(
            row.get("ordinal") != ordinal
            for ordinal, row in enumerate(expected)
        )
    ):
        reject("caller, extent, call-site, ordinal, or call population")

    offsets = _candidate_complete_instruction_offsets(candidate)
    offset_counts: dict[int, int] = {}
    for offset in offsets:
        if offset is not None:
            offset_counts[int(offset)] = offset_counts.get(int(offset), 0) + 1
    index_by_offset = {
        int(offset): index
        for index, offset in enumerate(offsets)
        if offset is not None and offset_counts.get(int(offset)) == 1
    }

    def body(instruction: Instruction) -> bytes:
        try:
            return bytes(int(item, 16) for item in instruction.bytes)
        except (TypeError, ValueError):
            return b""

    def operand(index: int) -> str:
        instruction = candidate.instructions[index]
        return (
            _cod_space_bearing_direct_target(
                _instruction_operand(instruction),
                instruction.source_line,
            )
            or _instruction_operand(instruction).strip()
        )

    def coordinate(index: int) -> int | None:
        offset = offsets[index]
        if offset is None or offset_counts.get(int(offset)) != 1:
            return None
        return int(offset)

    def exact_coff_instruction(index: int, detail: str) -> int:
        offset = coordinate(index)
        raw = body(candidate.instructions[index])
        if (
            offset is None
            or not raw
            or offset < 0
            or offset + len(raw) > len(caller.data)
            or caller.data[offset : offset + len(raw)] != raw
        ):
            reject(detail)
        return offset

    def exact_coff_spans(
        spans: Sequence[range],
        detail: str,
    ) -> None:
        for span in spans:
            indexes = tuple(span)
            span_offsets = tuple(
                exact_coff_instruction(index, detail) for index in indexes
            )
            if any(
                right
                < left + len(body(candidate.instructions[indexes[position]]))
                for position, (left, right) in enumerate(
                    zip(span_offsets, span_offsets[1:])
                )
            ):
                reject(detail)

    def exact_relocation(
        field_offset: int,
        relocation_type: int,
        symbol_name: str,
        *,
        unique_symbol: bool,
    ) -> None:
        matches = [
            row
            for row in caller.relocations
            if row.offset == field_offset
            and row.type == relocation_type
            and row.symbol_name == symbol_name
        ]
        same_symbol = [
            row for row in caller.relocations if row.symbol_name == symbol_name
        ]
        field_end = field_offset + 4
        if (
            len(matches) != 1
            or (unique_symbol and len(same_symbol) != 1)
            or field_offset < 0
            or field_end > len(caller.data)
            or caller.data[field_offset:field_end] != b"\x00" * 4
            or not all(caller.relocation_mask[field_offset:field_end])
        ):
            reject(f"COFF relocation or mask for {symbol_name}")

    def literal_instruction(symbol_name: str) -> int:
        relocations = [
            row
            for row in caller.relocations
            if row.symbol_name == symbol_name
        ]
        if len(relocations) != 1:
            reject(f"unique command literal {symbol_name}")
        relocation = relocations[0]
        literal_offset = relocation.offset - 1
        index = index_by_offset.get(literal_offset)
        raw = body(candidate.instructions[index]) if index is not None else b""
        if (
            index is None
            or relocation.type != IMAGE_REL_I386_DIR32
            or len(raw) != 5
            or raw[0] not in {0x68, *range(0xB8, 0xC0)}
        ):
            reject(f"command literal producer {symbol_name}")
        exact_relocation(
            relocation.offset,
            IMAGE_REL_I386_DIR32,
            symbol_name,
            unique_symbol=True,
        )
        return index

    rotate_literal_index = literal_instruction(
        _ZINTERP_CAMERA_ROTATE_LITERAL_SYMBOL
    )
    translate_literal_index = literal_instruction(
        _ZINTERP_CAMERA_GET_TRANSLATE_LITERAL_SYMBOL
    )
    if rotate_literal_index >= translate_literal_index:
        reject("CameraRotate/CameraGetTranslate command identity or order")

    call_indexes = [
        index
        for index, instruction in enumerate(candidate.instructions)
        if _instruction_mnemonic(instruction) == "call"
    ]
    rotate_call_indexes = [
        index
        for index in call_indexes
        if rotate_literal_index < index < translate_literal_index
    ]
    expected_rotate_operands = (
        "edi",
        "?ParseFloatToken@zInterp_Context@@QAEMXZ",
        "?ParseFloatToken@zInterp_Context@@QAEMXZ",
        "?ParseFloatToken@zInterp_Context@@QAEMXZ",
        "?gwCameraSetPosition@zClass_Camera@@YIHPAUzClass_NodePartial@@MMM@Z",
    )
    if tuple(operand(index) for index in rotate_call_indexes) != (
        expected_rotate_operands
    ):
        reject(
            "CameraRotate command, ParseFloat x3, SetPosition target/order, "
            "or call population"
        )
    rotate_return_indexes = [
        index
        for index in range(rotate_call_indexes[-1] + 1, translate_literal_index)
        if _instruction_mnemonic(candidate.instructions[index]).startswith("ret")
    ]
    if (
        len(rotate_return_indexes) != 1
        or any(
            index in call_indexes
            for index in range(
                rotate_call_indexes[-1] + 1,
                rotate_return_indexes[0] + 1,
            )
        )
    ):
        reject("CameraRotate immediate post-SetPosition return boundary")

    translate_literal_body = body(
        candidate.instructions[translate_literal_index]
    )
    if not (
        len(translate_literal_body) == 5
        and 0xB8 <= translate_literal_body[0] <= 0xBF
    ):
        reject("CameraGetTranslate inline command literal register")
    literal_register = (
        "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi"
    )[translate_literal_body[0] - 0xB8]

    def decoded_branch_target(index: int) -> int | None:
        raw = body(candidate.instructions[index])
        offset = coordinate(index)
        if offset is None:
            return None
        if len(raw) == 2 and 0x70 <= raw[0] <= 0x7F:
            return offset + 2 + int.from_bytes(raw[1:], "little", signed=True)
        if len(raw) == 2 and raw[0] == 0xEB:
            return offset + 2 + int.from_bytes(raw[1:], "little", signed=True)
        if (
            len(raw) == 5
            and raw[0] == 0xE9
        ):
            return offset + 5 + int.from_bytes(raw[1:], "little", signed=True)
        if (
            len(raw) == 6
            and raw[:1] == b"\x0f"
            and 0x80 <= raw[1] <= 0x8F
        ):
            return offset + 6 + int.from_bytes(raw[2:], "little", signed=True)
        return None

    get_target_indexes = [
        index
        for index in call_indexes
        if index > translate_literal_index
        and operand(index)
        == "?gwCameraGetTarget@zClass_Camera@@YIHPAUzClass_NodePartial@@PAM11@Z"
    ]
    if len(get_target_indexes) != 1:
        reject("CameraGetTranslate GetTarget target or population")
    get_target_index = get_target_indexes[0]

    logf_call_indexes = [
        index
        for index in call_indexes
        if operand(index) == _ZINTERP_LOGF_CANDIDATE_SYMBOL
    ]
    route_candidates: list[tuple[int, int, int]] = []
    for branch_index in range(get_target_index + 1, len(candidate.instructions)):
        if _instruction_mnemonic(candidate.instructions[branch_index]) != "jmp":
            continue
        target = decoded_branch_target(branch_index)
        target_index = index_by_offset.get(target) if target is not None else None
        if target_index is None or target_index <= get_target_index:
            continue
        for logf_index in logf_call_indexes:
            if (
                target_index < logf_index
                and logf_index > branch_index
                and not any(
                    index in call_indexes
                    for index in range(target_index, logf_index)
                )
            ):
                route_candidates.append(
                    (branch_index, target_index, logf_index)
                )
    direct_route_candidates = [
        logf_index
        for logf_index in logf_call_indexes
        if logf_index > get_target_index
        and not any(
            index in call_indexes
            for index in range(get_target_index + 1, logf_index)
        )
        and coordinate(get_target_index) is not None
        and coordinate(logf_index) == coordinate(get_target_index) + 0x30
    ]
    if len(route_candidates) + len(direct_route_candidates) != 1:
        reject("CameraGetTranslate exact folded-or-direct Logf route")
    if direct_route_candidates:
        translate_logf_index = direct_route_candidates[0]
        suffix_index = get_target_index
        if (
            _cleanup_after(candidate.instructions, translate_logf_index) != 36
            or translate_logf_index + 1 >= len(candidate.instructions)
            or coordinate(translate_logf_index + 1)
            != coordinate(translate_logf_index) + 5
            or body(candidate.instructions[translate_logf_index + 1])
            != bytes.fromhex("83 c4 24")
        ):
            reject("CameraGetTranslate direct Logf cleanup36")
        route_kind = "direct"
    else:
        translate_branch_index, suffix_index, translate_logf_index = (
            route_candidates[0]
        )
        if any(
            index in call_indexes
            for index in range(get_target_index + 1, translate_branch_index)
        ):
            reject("CameraGetTranslate GetTarget/shared-suffix call population")
        route_kind = "folded"
    translate_return_indexes = [
        index
        for index in range(translate_logf_index + 1, len(candidate.instructions))
        if _instruction_mnemonic(candidate.instructions[index]).startswith("ret")
    ]
    if not translate_return_indexes:
        reject(f"CameraGetTranslate {route_kind} Logf route return")
    translate_return_index = translate_return_indexes[0]
    route_population_start = (
        suffix_index if route_kind == "folded" else get_target_index + 1
    )
    if any(
        index in call_indexes
        for index in range(route_population_start, translate_return_index + 1)
        if index != translate_logf_index
    ):
        reject(f"CameraGetTranslate {route_kind} Logf route call population")
    if _cleanup_after(candidate.instructions, translate_logf_index) != 36:
        reject("CameraGetTranslate Logf cleanup36")
    cleanup36_logf_call_indexes = [
        index
        for index in logf_call_indexes
        if _cleanup_after(candidate.instructions, index) == 36
    ]

    expected_node_load = (
        bytes.fromhex("8b 8e c8 00 00 00")
        if route_kind == "direct"
        else bytes.fromhex("8b be c8 00 00 00")
    )
    node_load_indexes = [
        index
        for index in range(translate_literal_index + 1, get_target_index)
        if body(candidate.instructions[index]) == expected_node_load
    ]
    if len(node_load_indexes) != 1:
        reject("CameraGetTranslate current-node load")
    node_load_index = node_load_indexes[0]

    if route_kind == "direct":
        direct_argument_bytes = {
            0x06: bytes.fromhex("85 c9"),
            0x0E: bytes.fromhex("8d 54 24 28"),
            0x12: bytes.fromhex("8d 44 24 14"),
            0x16: bytes.fromhex("52"),
            0x17: bytes.fromhex("50"),
            0x18: bytes.fromhex("8d 54 24 18"),
        }
        node_offset = coordinate(node_load_index)
        get_target_offset = coordinate(get_target_index)
        if node_offset is None or get_target_offset != node_offset + 0x1C:
            reject("CameraGetTranslate direct GetTarget argument lineage")
        direct_argument_offsets = {
            node_offset + delta: expected_body
            for delta, expected_body in direct_argument_bytes.items()
        }
        if any(
            body(candidate.instructions[index_by_offset[offset]]) != expected_body
            for offset, expected_body in direct_argument_offsets.items()
            if offset in index_by_offset
        ) or any(
            offset not in index_by_offset for offset in direct_argument_offsets
        ):
            reject("CameraGetTranslate direct GetTarget argument lineage")
        direct_test_index = index_by_offset[node_offset + 0x06]
        if any(
            _instruction_may_clobber_register(
                candidate.instructions[index], "ecx"
            )
            for index in range(node_load_index + 1, get_target_index)
            if index != direct_test_index
        ):
            reject("CameraGetTranslate direct ECX receiver lineage")
        reload_index = index_by_offset.get(get_target_offset + 0x0C)
        name_push_index = index_by_offset.get(get_target_offset + 0x29)
        if (
            reload_index is None
            or name_push_index is None
            or body(candidate.instructions[reload_index])
            != bytes.fromhex("8b 8e c8 00 00 00")
            or body(candidate.instructions[name_push_index]) != b"\x51"
            or not reload_index < name_push_index < translate_logf_index
            or any(
                _instruction_may_clobber_register(
                    candidate.instructions[index], "ecx"
                )
                for index in range(reload_index + 1, name_push_index)
            )
        ):
            reject("CameraGetTranslate direct current-node name lineage")

    inline_compare_indexes = [
        index
        for index in range(translate_literal_index + 1, node_load_index)
        if _instruction_mnemonic(candidate.instructions[index]) == "cmp"
        and literal_register in _instruction_operand(
            candidate.instructions[index]
        ).lower()
    ]
    inline_branch_indexes = [
        index
        for index in range(translate_literal_index + 1, node_load_index)
        if _instruction_mnemonic(candidate.instructions[index]).startswith("j")
    ]
    if len(inline_compare_indexes) != 2 or len(inline_branch_indexes) < 4:
        reject("CameraGetTranslate unique inline comparison")

    null_gate_indexes = [
        index
        for index in range(node_load_index + 1, get_target_index)
        if _instruction_mnemonic(candidate.instructions[index])
        in {"je", "jz"}
        and (
            target := decoded_branch_target(index)
        ) is not None
        and target in index_by_offset
        and coordinate(index) is not None
        and target > coordinate(index)
    ]
    if len(null_gate_indexes) != 1:
        reject("CameraGetTranslate null-current-node return gate")
    null_gate_index = null_gate_indexes[0]
    if route_kind == "direct" and (
        coordinate(null_gate_index) != coordinate(node_load_index) + 0x08
        or body(candidate.instructions[null_gate_index])[:2] != b"\x0f\x84"
        or body(candidate.instructions[node_load_index + 1]) != b"\x85\xc9"
        or coordinate(node_load_index + 1)
        != coordinate(node_load_index) + 0x06
    ):
        reject("CameraGetTranslate direct null-current-node gate")
    null_target = decoded_branch_target(null_gate_index)
    null_target_index = index_by_offset.get(null_target)
    null_return_indexes = [
        index
        for index in range(
            int(null_target_index) if null_target_index is not None else 0,
            len(candidate.instructions),
        )
        if _instruction_mnemonic(candidate.instructions[index]).startswith("ret")
    ]
    if (
        null_target_index is None
        or not null_return_indexes
        or any(
            index in call_indexes
            for index in range(null_target_index, null_return_indexes[0] + 1)
        )
    ):
        reject("CameraGetTranslate null-current-node return route")
    if not any(
        _instruction_mnemonic(candidate.instructions[index])
        in {"cmp", "test"}
        for index in range(node_load_index + 1, null_gate_index)
    ):
        reject("CameraGetTranslate null-current-node comparison")

    exact_coff_spans(
        (
            range(rotate_literal_index, translate_return_index + 1),
            range(int(null_target_index), null_return_indexes[0] + 1),
        ),
        "candidate camera-owner instruction coordinates or COFF bounds",
    )

    format_relocations = [
        row
        for row in caller.relocations
        if row.symbol_name == _ZINTERP_SHARED_LOGF_FORMAT_SYMBOL
        and coordinate(suffix_index) is not None
        and coordinate(translate_logf_index) is not None
        and coordinate(suffix_index) < row.offset
        < coordinate(translate_logf_index)
    ]
    if len(format_relocations) != 1:
        reject("CameraGetTranslate Logf format argument")
    exact_relocation(
        format_relocations[0].offset,
        IMAGE_REL_I386_DIR32,
        _ZINTERP_SHARED_LOGF_FORMAT_SYMBOL,
        unique_symbol=False,
    )
    exact_relocation(
        exact_coff_instruction(
            translate_logf_index,
            "candidate camera-owner instruction coordinates or COFF bounds",
        )
        + 1,
        IMAGE_REL_I386_REL32,
        _ZINTERP_LOGF_CANDIDATE_SYMBOL,
        unique_symbol=False,
    )

    start_value = address_value(caller_start)
    if start_value is None:
        reject("caller runtime coordinate")
    site_to_row = {
        normalize_address(site): ordinal
        for ordinal, site in enumerate(candidate_call_sites)
    }
    actual_logf_rows = [
        site_to_row.get(
            normalize_address(start_value + int(coordinate(index)))
            if coordinate(index) is not None
            else ""
        )
        for index in cleanup36_logf_call_indexes
    ]

    semantic_keys = (
        "form",
        "dispatch",
        "identity_kind",
        "target_identity",
        "storage_identity",
        "slot_displacement",
        "cleanup_bytes",
    )

    def shape(row: Mapping[str, Any]) -> tuple[Any, ...]:
        return tuple(row.get(key) for key in semantic_keys)

    expected_logf_rows = [
        ordinal
        for ordinal, row in enumerate(expected)
        if row.get("target_identity") == _ZINTERP_LOGF_CALLER_IDENTITY
        and row.get("cleanup_bytes") == 36
    ]
    candidate_logf_rows = [
        ordinal
        for ordinal, row in enumerate(result)
        if row.get("target_identity") == _ZINTERP_LOGF_CALLER_IDENTITY
        and row.get("cleanup_bytes") == 36
    ]
    if (
        None in actual_logf_rows
        or len(expected_logf_rows) != 2
        or not 1 <= len(cleanup36_logf_call_indexes) <= 2
        or len(set(actual_logf_rows)) != len(cleanup36_logf_call_indexes)
        or candidate_logf_rows != actual_logf_rows
        or translate_logf_index not in cleanup36_logf_call_indexes
    ):
        reject("retail/candidate physical Logf population or call-site collision")
    translate_logf_row = site_to_row.get(
        normalize_address(
            start_value
            + exact_coff_instruction(
                translate_logf_index,
                "candidate camera-owner instruction coordinates or COFF bounds",
            )
        )
    )
    if (
        translate_logf_row is None
        or shape(result[int(translate_logf_row)])
        != (
            "call",
            "direct",
            "direct",
            _ZINTERP_LOGF_CALLER_IDENTITY,
            "",
            None,
            36,
        )
    ):
        reject("CameraGetTranslate Logf contract identity")

    return result


def _zinterp_load_prepared_fclose_tailfold_candidate_projection(
    expected: Sequence[Mapping[str, Any]],
    candidate_contract: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    candidate_call_sites: Sequence[str],
    *,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
) -> list[dict[str, Any]]:
    """Expand only the exact VC5 A/B/C shared-fclose tail.

    Retail keeps the header-read, version/count, and magic/allocation/table-read
    failure closes as three logical calls.  Current VC5 folds their identical
    close/null/return tails into one physical IAT call.  The stale-table close
    followed by ``free(entries)`` is a separate physical route and remains an
    ordinary candidate row.  This comparison-only projection is available
    only after the complete current caller, call population, and all four
    close routes have been proved against COD and COFF.
    """

    result = [dict(row) for row in candidate_contract]
    if normalize_address(caller_start) != _ZINTERP_LOAD_PREPARED_CALLER_START:
        return result

    def reject(detail: str) -> NoReturn:
        raise CandidateCallContractEvidenceError(
            "reviewed zInterp LoadPreparedScriptIndex fclose tail-fold "
            "projection drifted: " + detail
        )

    if (
        caller_identity != _ZINTERP_LOAD_PREPARED_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != _ZINTERP_LOAD_PREPARED_CALLER_END_EXCLUSIVE
        or len(expected) != 12
        or len(result) != 10
        or len(candidate_call_sites) != len(result)
        or len(set(candidate_call_sites)) != len(candidate_call_sites)
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(expected))
        or any(row.get("ordinal") != ordinal for ordinal, row in enumerate(result))
    ):
        reject("caller, extent, ordinal, or retail/candidate call population")

    caller = candidate.caller_definition
    if (
        caller is None
        or caller.symbol != _ZINTERP_LOAD_PREPARED_CANDIDATE_SYMBOL
        or caller.section_start != 0
        or caller.section_end != 0x1E0
        or len(caller.data) != 0x1E0
        or len(caller.relocation_mask) != len(caller.data)
        or caller.data[0x1D6:] != b"\x90" * 10
    ):
        reject("candidate symbol, body extent, or exact section padding")

    offsets = _candidate_complete_instruction_offsets(candidate)

    def instruction_body(instruction: Instruction) -> bytes:
        try:
            return bytes(int(item, 16) for item in instruction.bytes)
        except (TypeError, ValueError):
            return b""

    if (
        any(offset is None for offset in offsets)
        or len(set(offsets)) != len(offsets)
        or not offsets
        or int(offsets[0]) != 0
    ):
        reject("complete unique COD instruction coordinates")
    closed_offsets = tuple(int(offset) for offset in offsets)
    bodies = tuple(instruction_body(row) for row in candidate.instructions)
    if (
        any(not body for body in bodies)
        or any(
            right != left + len(bodies[index])
            for index, (left, right) in enumerate(
                zip(closed_offsets, closed_offsets[1:])
            )
        )
        or closed_offsets[-1] + len(bodies[-1]) != 0x1D6
        or any(
            caller.data[offset : offset + len(body)] != body
            for offset, body in zip(closed_offsets, bodies)
        )
    ):
        reject("complete contiguous COD/COFF body")
    index_by_offset = {
        offset: index for index, offset in enumerate(closed_offsets)
    }

    required_rows = {
        0x009: bytes.fromhex("33 ed"),
        0x038: bytes.fromhex("e8 00 00 00 00"),
        0x047: bytes.fromhex("68 00 00 00 00"),
        0x04C: bytes.fromhex("e8 00 00 00 00"),
        0x05F: bytes.fromhex("8b 1d 00 00 00 00"),
        0x06F: bytes.fromhex("ff d3"),
        0x071: bytes.fromhex("83 c4 10"),
        0x074: bytes.fromhex("83 f8 01"),
        0x077: bytes.fromhex("74 0c"),
        0x079: bytes.fromhex("8b 8f 80 00 00 00"),
        0x07F: bytes.fromhex("51"),
        0x080: bytes.fromhex("e9 36 01 00 00"),
        0x08D: bytes.fromhex("0f 85 21 01 00 00"),
        0x098: bytes.fromhex("0f 85 0d 01 00 00"),
        0x0AE: bytes.fromhex("ff d3"),
        0x0B0: bytes.fromhex("83 c4 10"),
        0x0B3: bytes.fromhex("83 f8 01"),
        0x0B6: bytes.fromhex("0f 85 ef 00 00 00"),
        0x0C6: bytes.fromhex("ff 15 00 00 00 00"),
        0x0CE: bytes.fromhex("83 c4 08"),
        0x0D1: bytes.fromhex("3b f5"),
        0x0D7: bytes.fromhex("0f 84 d7 00 00 00"),
        0x0EF: bytes.fromhex("ff d3"),
        0x0F5: bytes.fromhex("83 c4 10"),
        0x0F8: bytes.fromhex("3b c1"),
        0x0FA: bytes.fromhex("0f 85 b4 00 00 00"),
        0x102: bytes.fromhex("bd 01 00 00 00"),
        0x10D: bytes.fromhex("74 68"),
        0x115: bytes.fromhex("ff 15 00 00 00 00"),
        0x11B: bytes.fromhex("83 c4 08"),
        0x140: bytes.fromhex("74 35"),
        0x174: bytes.fromhex("c2 04 00"),
        0x177: bytes.fromhex("8b 97 80 00 00 00"),
        0x17D: bytes.fromhex("52"),
        0x17E: bytes.fromhex("ff 15 00 00 00 00"),
        0x188: bytes.fromhex("83 c4 04"),
        0x18B: bytes.fromhex("c7 87 80 00 00 00 00 00 00 00"),
        0x195: bytes.fromhex("50"),
        0x196: bytes.fromhex("ff 15 00 00 00 00"),
        0x19C: bytes.fromhex("83 c4 04"),
        0x19F: bytes.fromhex("33 c0"),
        0x1A8: bytes.fromhex("c2 04 00"),
        0x1AB: bytes.fromhex("8b 8f 80 00 00 00"),
        0x1B1: bytes.fromhex("51"),
        0x1B2: bytes.fromhex("eb 07"),
        0x1B4: bytes.fromhex("8b 97 80 00 00 00"),
        0x1BA: bytes.fromhex("52"),
        0x1BB: bytes.fromhex("ff 15 00 00 00 00"),
        0x1C1: bytes.fromhex("83 c4 04"),
        0x1C4: bytes.fromhex("89 af 80 00 00 00"),
        0x1CD: bytes.fromhex("33 c0"),
        0x1D3: bytes.fromhex("c2 04 00"),
    }
    branch_routes = {
        0x077: 0x085,
        0x080: 0x1BB,
        0x08D: 0x1B4,
        0x098: 0x1AB,
        0x0B6: 0x1AB,
        0x0D7: 0x1B4,
        0x0FA: 0x1B4,
        0x10D: 0x177,
        0x140: 0x177,
        0x1B2: 0x1BB,
    }

    def branch_target(offset: int) -> int | None:
        index = index_by_offset.get(offset)
        raw = bodies[index] if index is not None else b""
        if len(raw) == 2 and 0x70 <= raw[0] <= 0x7F:
            return offset + 2 + int.from_bytes(raw[1:], "little", signed=True)
        if len(raw) == 2 and raw[0] == 0xEB:
            return offset + 2 + int.from_bytes(raw[1:], "little", signed=True)
        if len(raw) == 5 and raw[0] == 0xE9:
            return offset + 5 + int.from_bytes(raw[1:], "little", signed=True)
        if len(raw) == 6 and raw[0] == 0x0F and 0x80 <= raw[1] <= 0x8F:
            return offset + 6 + int.from_bytes(raw[2:], "little", signed=True)
        return None

    if any(branch_target(offset) != target for offset, target in branch_routes.items()):
        reject("exact A/B/C or stale-table ingress control flow")
    if any(
        offset not in index_by_offset
        or bodies[index_by_offset[offset]] != body
        for offset, body in required_rows.items()
    ):
        reject("exact A/B/C or stale-table route instruction body")

    expected_relocations = (
        (0x039, IMAGE_REL_I386_REL32, "@zUtil_ZRDR_CreateSearchPathList@4"),
        (0x048, IMAGE_REL_I386_DIR32, "??_C@_02JKAF@rb?$AA@"),
        (0x04D, IMAGE_REL_I386_REL32, "@zUtil_ZRDR_OpenFileResolved@12"),
        (0x061, IMAGE_REL_I386_DIR32, "__imp__fread"),
        (0x0C8, IMAGE_REL_I386_DIR32, "__imp__realloc"),
        (0x117, IMAGE_REL_I386_DIR32, "__imp___stat"),
        (0x180, IMAGE_REL_I386_DIR32, "__imp__fclose"),
        (0x198, IMAGE_REL_I386_DIR32, "__imp__free"),
        (0x1BD, IMAGE_REL_I386_DIR32, "__imp__fclose"),
    )
    observed_relocations = tuple(
        (row.offset, row.type, row.symbol_name) for row in caller.relocations
    )
    expected_mask = tuple(
        any(offset <= index < offset + 4 for offset, _kind, _name in expected_relocations)
        for index in range(len(caller.data))
    )
    if (
        observed_relocations != expected_relocations
        or caller.relocation_mask != expected_mask
        or any(caller.data[offset : offset + 4] != b"\x00" * 4 for offset, _kind, _name in expected_relocations)
    ):
        reject("exact literal/call/IAT COFF relocations or masks")

    call_offsets = tuple(
        closed_offsets[index]
        for index, instruction in enumerate(candidate.instructions)
        if _instruction_mnemonic(instruction) == "call"
    )
    expected_call_offsets = (
        0x038, 0x04C, 0x06F, 0x0AE, 0x0C6,
        0x0EF, 0x115, 0x17E, 0x196, 0x1BB,
    )
    start_value = address_value(caller_start)
    if (
        call_offsets != expected_call_offsets
        or start_value is None
        or tuple(candidate_call_sites)
        != tuple(normalize_address(start_value + offset) for offset in expected_call_offsets)
    ):
        reject("exact physical call population or call-site coordinates")

    semantic_keys = (
        "form", "dispatch", "identity_kind", "target_identity",
        "storage_identity", "slot_displacement", "cleanup_bytes",
    )

    def shape(row: Mapping[str, Any]) -> tuple[Any, ...]:
        return tuple(row.get(key) for key in semantic_keys)

    # Retail places each logical failure close at its source-level decision
    # point.  Candidate row 9 is consumed three times for A/B/C and is not
    # retained at its late physical coordinate.  Rows 7/8 remain the distinct
    # stale-table fclose/free route.
    expected_to_candidate = (0, 1, 2, 9, 3, 9, 4, 5, 9, 6, 7, 8)
    fclose_shape = (
        "call", "indirect", "iat", "iat:fclose", "iat:fclose", None, 4,
    )
    free_shape = (
        "call", "indirect", "iat", "iat:free", "iat:free", None, 4,
    )
    if (
        any(
            shape(expected[expected_ordinal]) != shape(result[candidate_ordinal])
            for expected_ordinal, candidate_ordinal in enumerate(expected_to_candidate)
        )
        or shape(result[7]) != fclose_shape
        or shape(result[8]) != free_shape
        or shape(result[9]) != fclose_shape
        or any(shape(result[index]) != shape(result[2]) for index in (3, 5))
        or result[2].get("target_identity") != "iat:fread"
        or result[2].get("storage_identity") != "iat:fread"
        or result[2].get("cleanup_bytes") != 16
    ):
        reject("retail order, IAT identity, cleanup, or logical call mapping")

    projected = [
        {**result[candidate_ordinal], "ordinal": expected_ordinal}
        for expected_ordinal, candidate_ordinal in enumerate(expected_to_candidate)
    ]
    return projected


def _resolve_eh_array_destructor_provider_identity(
    *,
    document: ProgressDocument,
    indexes: IdentityIndexes,
) -> str:
    """Resolve ``??_M`` from the complete governed provider catalog.

    Candidate call order and retail expected rows are deliberately absent from
    this resolver.  The VC5 spelling identifies the compiler-lifecycle family;
    the unique tracker row, accepted provider index, and exact known extent
    establish its retail identity.  Any duplicate, malformed, or ungoverned
    catalog row fails closed instead of letting a caller/ordinal select one.
    """

    catalog_rows = [
        (symbol_id, symbol)
        for symbol_id, symbol in document.collection("symbols").items()
        if isinstance(symbol, Mapping)
        and symbol.get("navigation_name") == "MSVC_EH_ArrayDestructor"
    ]
    if len(catalog_rows) != 1:
        raise ValueError(
            "EH array-destructor bridge requires exactly one complete "
            "MSVC_EH_ArrayDestructor tracker catalog row"
        )
    provider_symbol_id, provider_symbol = catalog_rows[0]
    provider_identity = _symbol_identity(provider_symbol_id, provider_symbol)
    provider_addresses = sorted(
        address
        for address, identity in indexes.by_address.items()
        if identity == provider_identity
    )
    provider_address = normalize_address(
        str(provider_symbol.get("address", provider_symbol.get("start", "")))
    )
    provider_end = normalize_address(str(provider_symbol.get("end_exclusive", "")))
    provider_size = address_value(provider_end) - address_value(provider_address)
    if (
        not provider_identity.startswith("provider:")
        or provider_identity not in indexes.provider_ids
        or provider_addresses != [provider_address]
        or provider_symbol.get("pipeline_class") != "non-authored"
        or provider_symbol.get("authored_order_role")
        != "compiler-generated-eh-helper"
        or provider_symbol.get("kind")
        not in {"function", "provider-function", "compiler-function"}
        or provider_size <= 0
        or provider_symbol.get("size") != provider_size
        or provider_symbol.get("extent_state") != "known"
    ):
        raise ValueError(
            "EH array-destructor bridge catalog row lacks one exact governed "
            "provider identity and known retail extent"
        )
    return provider_identity


def _prove_eh_array_destructor_provider_bridge(
    provider_identity: str,
    *,
    invocation_offsets: Sequence[int],
    document: ProgressDocument,
    candidate: CandidateAssembly,
    indexes: IdentityIndexes,
    bridge: BinaryNinjaBridge,
) -> None:
    if provider_identity not in indexes.provider_ids:
        raise ValueError(
            "EH array-destructor bridge target "
            f"{provider_identity!r} is not a governed provider identity"
        )
    provider_addresses = sorted(
        address
        for address, identity in indexes.by_address.items()
        if identity == provider_identity
    )
    if len(provider_addresses) != 1 or not provider_identity.startswith("provider:"):
        raise ValueError(
            "EH array-destructor bridge provider identity must resolve to one "
            "retail address"
        )
    provider_address = provider_addresses[0]
    provider_symbol_id = provider_identity.removeprefix("provider:")
    provider_symbol = document.collection("symbols").get(provider_symbol_id)
    if (
        not isinstance(provider_symbol, Mapping)
        or _symbol_identity(provider_symbol_id, provider_symbol) != provider_identity
        or provider_symbol.get("pipeline_class") != "non-authored"
        or provider_symbol.get("authored_order_role")
        != "compiler-generated-eh-helper"
        or provider_symbol.get("kind")
        not in {"function", "provider-function", "compiler-function"}
        or provider_symbol.get("navigation_name") != "MSVC_EH_ArrayDestructor"
        or normalize_address(
            str(provider_symbol.get("address", provider_symbol.get("start", "")))
        )
        != provider_address
    ):
        raise ValueError(
            "EH array-destructor bridge target lacks one exact governed "
            "MSVC_EH_ArrayDestructor tracker function"
        )
    provider_end = normalize_address(str(provider_symbol.get("end_exclusive", "")))
    provider_size = address_value(provider_end) - address_value(provider_address)
    if (
        provider_size <= 0
        or provider_symbol.get("size") != provider_size
        or provider_symbol.get("extent_state") != "known"
    ):
        raise ValueError(
            "EH array-destructor bridge provider lacks one exact known extent"
        )

    definition = candidate.caller_definition
    if (
        definition is None
        or definition.undefined_external_functions.count(
            MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL
        )
        != 1
    ):
        raise ValueError(
            "EH array-destructor bridge requires the exact undefined VC5 "
            "external function symbol"
        )
    relocations = tuple(
        relocation
        for relocation in definition.relocations
        if relocation.symbol_name == MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL
    )
    if (
        len(relocations) != len(invocation_offsets)
        or any(relocation.type != IMAGE_REL_I386_REL32 for relocation in relocations)
        or tuple(relocation.offset for relocation in relocations)
        != tuple(offset + 1 for offset in invocation_offsets)
    ):
        raise ValueError(
            "EH array-destructor bridge requires one exact REL32 relocation "
            "per candidate invocation; every row must be site-bound REL32"
        )
    for relocation in relocations:
        if (
            relocation.offset <= 0
            or relocation.offset + 4 > len(definition.data)
            or definition.data[relocation.offset - 1] != 0xE8
            or struct.unpack_from("<I", definition.data, relocation.offset)[0]
            != 0
            or not all(
                definition.relocation_mask[index]
                for index in range(relocation.offset, relocation.offset + 4)
            )
        ):
            raise ValueError(
                "EH array-destructor bridge relocation is not one complete "
                "direct-call displacement"
            )

    retail_bytes = _hexdump_bytes(bridge.hexdump(provider_address, provider_size))
    if len(retail_bytes) != provider_size:
        raise ValueError(
            "EH array-destructor bridge retail provider returned an incomplete body"
        )
    retail_instructions = parse_assembly(
        bridge.assembly(provider_address),
        source="bn",
    )
    if (
        not retail_instructions
        or _instruction_mnemonic(retail_instructions[-1]) not in {"ret", "retn"}
        or _instruction_operand(retail_instructions[-1]) not in {"0x10", "16"}
    ):
        raise ValueError(
            "EH array-destructor bridge retail provider lacks the exact "
            "callee-cleaned four-argument return"
        )


def _eh_array_destructor_provider_bridges(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    candidate_storage_bridges: Mapping[str, str] | None = None,
) -> dict[str, str]:
    """Bridge exact candidate ``??_M`` calls without consulting retail rows.

    The returned identity comes only from the complete governed provider
    catalog.  Expected invocation rows remain solely the later comparison
    oracle; changing their ordinal, kind, or target cannot influence this
    candidate identity acquisition.
    """

    del expected, candidate_storage_bridges
    helper_indices = tuple(
        index
        for index, instruction in enumerate(candidate.instructions)
        if _instruction_mnemonic(instruction) in {"call", "jmp"}
        and (
            match := DECORATED_RE.search(_instruction_operand(instruction))
        )
        is not None
        and match.group(0) == MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL
    )
    if not helper_indices:
        return {}
    reviewed_spec: ReviewedEhArrayDestructorCallSpec | None = None
    briefing_spec = BRIEFING_RUNTIME_EH_ARRAY_DESTRUCTOR_CALL_BRIDGE
    if caller_identity == briefing_spec.caller_identity and (
        normalize_address(caller_start) != briefing_spec.caller_start
        or normalize_address(caller_end_exclusive)
        != briefing_spec.caller_end_exclusive
    ):
        return {}
    if caller_identity == briefing_spec.caller_identity:
        reviewed_spec = _reviewed_eh_array_destructor_call_context(
            candidate,
            caller_identity=caller_identity,
            caller_start=caller_start,
            caller_end_exclusive=caller_end_exclusive,
        )
    invocation_indices = _candidate_static_invocation_indices(
        candidate,
        caller_start="0x0",
        caller_end_exclusive=hex(
            max(1, len(candidate.caller_definition.data))
            if candidate.caller_definition is not None else 1
        ),
    )
    invocation_ordinal_by_index = {
        instruction_index: ordinal
        for ordinal, instruction_index in enumerate(invocation_indices)
    }
    if (
        any(
            _instruction_mnemonic(candidate.instructions[index]) != "call"
            or index in candidate.local_control_flow_indices
            or index not in invocation_ordinal_by_index
            for index in helper_indices
        )
        or len(set(helper_indices)) != len(helper_indices)
    ):
        raise ValueError(
            "EH array-destructor bridge requires only exact nonlocal direct "
            "candidate call instructions"
        )
    helper_ordinals = tuple(
        invocation_ordinal_by_index[index] for index in helper_indices
    )
    if reviewed_spec is not None and (
        len(helper_indices) != reviewed_spec.invocation_count
        or helper_ordinals != (reviewed_spec.ordinal,)
    ):
        raise ValueError(
            f"{reviewed_spec.label} requires candidate invocation ordinal "
            f"{reviewed_spec.ordinal} and count {reviewed_spec.invocation_count}"
        )
    instruction_offsets = _candidate_complete_instruction_offsets(candidate)
    if any(instruction_offsets[index] is None for index in helper_indices):
        raise ValueError(
            "EH array-destructor bridge candidate COD call population is not "
            "one complete site set"
        )
    invocation_offsets = tuple(
        int(instruction_offsets[index]) for index in helper_indices
    )
    provider_identity = _resolve_eh_array_destructor_provider_identity(
        document=document,
        indexes=indexes,
    )
    indexed_identity = indexes.by_candidate_name.get(
        MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL
    )
    if indexed_identity not in {None, "", provider_identity}:
        raise ValueError(
            "EH array-destructor bridge candidate-name index conflicts with "
            "the unique governed provider identity"
        )
    raw_matches = bridge_names.get(MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL)
    matches = (
        list(raw_matches)
        if isinstance(raw_matches, (list, tuple, set, frozenset))
        else ([raw_matches] if raw_matches is not None else [])
    )
    if matches:
        provider_addresses = {
            address
            for address, identity in indexes.by_address.items()
            if identity == provider_identity
        }
        bridge_addresses = {
            normalize_address(str(getattr(item, "address", "")))
            for item in matches
            if getattr(item, "address", "")
        }
        if bridge_addresses != provider_addresses:
            raise ValueError(
                "EH array-destructor bridge Binary Ninja name population "
                "conflicts with the unique governed provider address"
            )
    _prove_eh_array_destructor_provider_bridge(
        provider_identity,
        invocation_offsets=invocation_offsets,
        document=document,
        candidate=candidate,
        indexes=indexes,
        bridge=bridge,
    )
    result = {MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL: provider_identity}
    if reviewed_spec is not None:
        result.update(
            _reviewed_eh_array_destructor_operand_bridges(
                candidate,
                provider_identity,
            )
        )
    return result


def _preflight_eh_array_destructor_candidate_identity(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
) -> tuple[dict[str, str], IdentityIndexes]:
    """Install the generic ``??_M`` result before candidate preflights.

    The returned indexes are invocation-local.  Publishing the already-proven
    provider identity there ensures every downstream bridge producer sees the
    same exact compiler-lifecycle authority, including producers that perform
    their own complete candidate-contract preflight before final extraction.
    """

    bridges = _eh_array_destructor_provider_bridges(
        expected,
        candidate,
        document=document,
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
        indexes=indexes,
        bridge_names=bridge_names,
        bridge=bridge,
    )
    if not bridges:
        return {}, indexes
    provider_identity = bridges.get(MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL, "")
    if (
        not provider_identity
        or provider_identity not in indexes.provider_ids
        or any(
            identity != provider_identity
            for identity in bridges.values()
        )
    ):
        raise ValueError(
            "EH array-destructor preflight produced an incomplete or "
            "conflicting provider identity population"
        )
    by_candidate_name = dict(indexes.by_candidate_name)
    prior = by_candidate_name.get(MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL)
    if prior not in {None, "", provider_identity}:
        raise ValueError(
            "EH array-destructor preflight conflicts with the candidate-name "
            "identity index"
        )
    by_candidate_name[MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL] = provider_identity
    return bridges, replace(indexes, by_candidate_name=by_candidate_name)


def _assert_eh_array_destructor_candidate_identity_stage(
    bridges: Mapping[str, str],
    indexes: IdentityIndexes,
    *,
    stage: str,
    final_bridges: Mapping[str, str] | None = None,
) -> None:
    """Fail at the first live producer boundary that drops proven ``??_M``.

    This is deliberately an invariant over the invocation-local result, not a
    second resolver.  Empty bridge sets remain the common no-op path.  Once the
    exact compiler-lifecycle proof exists, every provisional producer and the
    final extractor must retain the same governed provider identity.
    """

    if not bridges:
        return
    provider_identity = bridges.get(MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL, "")
    if (
        not provider_identity
        or provider_identity not in indexes.provider_ids
        or indexes.by_candidate_name.get(MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL)
        != provider_identity
    ):
        raise CandidateCallContractEvidenceError(
            "EH array-destructor identity was discarded at live candidate "
            f"stage {stage!r}"
        )
    if final_bridges is not None and any(
        final_bridges.get(name) != identity
        for name, identity in bridges.items()
    ):
        raise CandidateCallContractEvidenceError(
            "EH array-destructor bridge was discarded at live candidate "
            f"stage {stage!r}"
        )


def _candidate_caller_definition_interval(
    definition: CandidateCallerDefinition,
) -> tuple[int, int]:
    """Return the exact selected body interval, including legacy test bodies."""

    start = definition.section_start
    end = definition.section_end
    if start == 0 and end == 0 and definition.data:
        # Older isolated unit fixtures predate explicit COFF interval fields.
        # Live candidate construction always publishes them.  Treat only the
        # unambiguous zero-based whole-body fixture as [0, len(data)); any
        # partially populated or nonzero interval remains fail-closed.
        end = len(definition.data)
    if (
        start < 0
        or end <= start
        or end - start != len(definition.data)
        or len(definition.relocation_mask) != len(definition.data)
    ):
        raise CandidateCallContractEvidenceError(
            "candidate proof requires one exact selected caller definition interval"
        )
    return start, end


def _candidate_instruction_section_offset(
    instruction: Instruction,
    definition: CandidateCallerDefinition,
) -> int:
    """Bind a COD instruction offset to one unambiguous COFF body field."""

    raw_address = _source_instruction_address(instruction)
    if not raw_address:
        raise CandidateCallContractEvidenceError(
            "candidate instruction lacks an exact source offset"
        )
    raw_offset = address_value(raw_address)
    definition_start, definition_end = _candidate_caller_definition_interval(
        definition
    )
    body_size = definition_end - definition_start
    local_offset = (
        definition_start + raw_offset
        if 0 <= raw_offset < body_size
        else None
    )
    section_offset = (
        raw_offset
        if definition_start <= raw_offset < definition_end
        else None
    )
    candidates = {value for value in (local_offset, section_offset) if value is not None}
    if len(candidates) != 1:
        raise CandidateCallContractEvidenceError(
            "candidate instruction offset is outside or ambiguous within the "
            "selected caller definition"
        )
    return candidates.pop()


def _eh_array_destructor_callback_noncall_relocation_offsets(
    candidate: CandidateAssembly,
    *,
    indexes: IdentityIndexes,
) -> dict[str, frozenset[int]]:
    """Prove exact ``??_M`` destructor-callback argument relocations.

    VC5 passes the ordinary destructor as the first pushed argument to every
    EH array-destructor helper call.  Those DIR32 references share a symbol
    with ordinary direct destructor calls, so the ordinal-import producer must
    classify them independently instead of counting them as calls.
    """

    provider_identity = indexes.by_candidate_name.get(
        MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL, ""
    )
    if not provider_identity:
        return {}
    if provider_identity not in indexes.provider_ids:
        raise CandidateCallContractEvidenceError(
            "EH array-destructor callback proof lacks a governed provider identity"
        )
    definition = candidate.caller_definition
    if definition is None:
        raise CandidateCallContractEvidenceError(
            "EH array-destructor callback proof requires one exact selected "
            "caller definition interval"
        )
    definition_start, _definition_end = _candidate_caller_definition_interval(
        definition
    )

    helper_indices = tuple(
        index
        for index, instruction in enumerate(candidate.instructions)
        if _instruction_mnemonic(instruction) == "call"
        and _instruction_operand(instruction).strip()
        == MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL
    )
    if not helper_indices:
        return {}
    if any(index in candidate.local_control_flow_indices for index in helper_indices):
        raise CandidateCallContractEvidenceError(
            "EH array-destructor callback proof rejects caller-local helper calls"
        )

    offsets_by_symbol: dict[str, set[int]] = {}
    previous_helper = -1
    for helper_index in helper_indices:
        callback_pushes: list[tuple[Instruction, str]] = []
        for instruction in candidate.instructions[previous_helper + 1 : helper_index]:
            if _instruction_mnemonic(instruction) != "push":
                continue
            operand = _instruction_operand(instruction).strip()
            prefix = "OFFSET FLAT:"
            if not operand.startswith(prefix):
                continue
            callback_symbol = operand[len(prefix) :]
            if callback_symbol.startswith("??1"):
                callback_pushes.append((instruction, callback_symbol))
        if len(callback_pushes) != 1:
            raise CandidateCallContractEvidenceError(
                "EH array-destructor callback proof requires exactly one "
                "ordinary destructor PUSH argument per helper call"
            )
        callback_instruction, callback_symbol = callback_pushes[0]
        if (
            len(callback_instruction.bytes) != 5
            or tuple(value.lower() for value in callback_instruction.bytes)
            != ("68", "00", "00", "00", "00")
        ):
            raise CandidateCallContractEvidenceError(
                "EH array-destructor callback proof requires exact zero-addend "
                "PUSH imm32 encoding"
            )
        folded_undefined = tuple(
            name
            for name in definition.undefined_external_functions
            if name.casefold() == callback_symbol.casefold()
        )
        if folded_undefined != (callback_symbol,):
            raise CandidateCallContractEvidenceError(
                "EH array-destructor callback proof requires one exact undefined "
                "ordinary destructor symbol"
            )
        field_offset = (
            _candidate_instruction_section_offset(
                callback_instruction, definition
            )
            + 1
        )
        matching_relocations = tuple(
            relocation
            for relocation in definition.relocations
            if relocation.offset == field_offset
        )
        relative = field_offset - definition_start
        if (
            len(matching_relocations) != 1
            or matching_relocations[0].type != IMAGE_REL_I386_DIR32
            or matching_relocations[0].symbol_name != callback_symbol
            or relative <= 0
            or relative + 4 > len(definition.data)
            or definition.data[relative - 1] != 0x68
            or struct.unpack_from("<I", definition.data, relative)[0] != 0
            or definition.relocation_mask[relative - 1]
            or not all(
                definition.relocation_mask[index]
                for index in range(relative, relative + 4)
            )
        ):
            raise CandidateCallContractEvidenceError(
                "EH array-destructor callback proof requires one exact "
                "site-bound zero-addend DIR32 relocation"
            )
        offsets_by_symbol.setdefault(callback_symbol, set()).add(field_offset)
        previous_helper = helper_index
    if sum(len(offsets) for offsets in offsets_by_symbol.values()) != len(
        helper_indices
    ):
        raise CandidateCallContractEvidenceError(
            "EH array-destructor callback proof has duplicate callback fields"
        )
    return {
        symbol: frozenset(offsets)
        for symbol, offsets in offsets_by_symbol.items()
    }


def _prove_compiler_destructor_provider_bridge(
    candidate_name: str,
    provider_identity: str,
    *,
    document: ProgressDocument,
    candidate: CandidateAssembly,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
) -> None:
    if provider_identity not in indexes.provider_ids:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} target "
            f"{provider_identity!r} is not a governed provider identity"
        )
    provider_addresses = sorted(
        address
        for address, identity in indexes.by_address.items()
        if identity == provider_identity
    )
    if len(provider_addresses) != 1:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} provider identity "
            f"{provider_identity!r} must resolve to one retail address"
        )
    provider_address = provider_addresses[0]
    if not provider_identity.startswith("provider:"):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} has malformed provider identity"
        )
    provider_symbol_id = provider_identity.removeprefix("provider:")
    provider_symbol = document.collection("symbols").get(provider_symbol_id)
    if (
        not isinstance(provider_symbol, Mapping)
        or _symbol_identity(provider_symbol_id, provider_symbol) != provider_identity
        or provider_symbol.get("pipeline_class") != "non-authored"
        or provider_symbol.get("kind")
        not in {"function", "provider-function", "compiler-function"}
        or normalize_address(
            str(provider_symbol.get("address", provider_symbol.get("start", "")))
        )
        != provider_address
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} target "
            f"{provider_identity!r} lacks one exact non-authored tracker function"
        )
    provider_end = normalize_address(str(provider_symbol.get("end_exclusive", "")))
    provider_size = address_value(provider_end) - address_value(provider_address)
    if provider_size <= 0 or provider_symbol.get("size") != provider_size:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} provider "
            f"{provider_address} lacks one exact known extent"
        )

    target = candidate.target
    provider_rows = [
        row
        for row in _target_function_rows(target)
        if normalize_address(str(getattr(row, "address", ""))) == provider_address
    ]
    if len(provider_rows) != 1:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} provider "
            f"{provider_address} must resolve to one exact selected-target row"
        )
    provider_row = provider_rows[0]
    provider_name = str(getattr(provider_row, "symbol", ""))
    if (
        MSVC_COMPLETE_DESTRUCTOR_RE.fullmatch(provider_name) is None
        or provider_name == candidate_name
        or getattr(provider_row, "provenance", "") != "provider-boundary"
        or getattr(provider_row, "pipeline_class", "") != "non-authored"
        or getattr(provider_row, "authored_order_role", "") != "non-authored"
        or not bool(getattr(provider_row, "required_presence", False))
        or not bool(getattr(provider_row, "full_order_gate", False))
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} target row at "
            f"{provider_address} is not an exact required provider destructor"
        )

    definition = candidate.complete_destructor_definitions.get(candidate_name)
    if definition is None:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} has no same-object "
            "complete-destructor definition"
        )
    if (
        not definition.section_is_comdat
        or definition.comdat_selection != 2
        or definition.section_external_functions != (candidate_name,)
        or len(definition.data) != definition.section_size
        or definition.section_size != provider_size
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} is not one exact "
            "full-section VC5 COMDAT SELECT_ANY definition"
        )
    if (
        not definition.relocations
        or any(
            relocation.type != IMAGE_REL_I386_REL32
            for relocation in definition.relocations
        )
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} must contain only "
            "non-empty REL32 invocation relocations"
        )
    expected_mask: set[int] = set()
    for relocation in definition.relocations:
        if relocation.offset < 0 or relocation.offset + 4 > len(definition.data):
            raise ValueError(
                f"compiler destructor bridge {candidate_name!r} has an "
                "out-of-range REL32 relocation"
            )
        expected_mask.update(range(relocation.offset, relocation.offset + 4))
    actual_mask = {
        index for index, masked in enumerate(definition.relocation_mask) if masked
    }
    if actual_mask != expected_mask:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} relocation mask "
            "does not exactly cover its REL32 fields"
        )

    retail_bytes = _hexdump_bytes(bridge.hexdump(provider_address, provider_size))
    if len(retail_bytes) != provider_size:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} retail target "
            f"{provider_address} returned an incomplete body"
        )
    mismatches = [
        index
        for index, (candidate_byte, retail_byte) in enumerate(
            zip(definition.data, retail_bytes)
        )
        if not definition.relocation_mask[index] and candidate_byte != retail_byte
    ]
    if mismatches:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} does not byte-match "
            f"provider {provider_address} outside REL32 fields"
        )

    retail_instructions = parse_assembly(
        bridge.assembly(provider_address),
        source="bn",
    )
    retail_switch_targets = retail_local_switch_targets(
        retail_instructions,
        caller_start=provider_address,
        caller_end_exclusive=provider_end,
        bridge=bridge,
    )
    retail_contract = extract_invocation_contract(
        retail_instructions,
        source="bn",
        caller_identity=provider_identity,
        caller_start=provider_address,
        caller_end_exclusive=provider_end,
        indexes=indexes,
        bridge_names=bridge_names,
        local_control_flow_indices=frozenset(retail_switch_targets),
        local_control_flow_targets=retail_switch_targets,
    )
    candidate_contract = extract_invocation_contract(
        definition.instructions,
        source="cod",
        caller_identity=provider_identity,
        caller_start=provider_address,
        caller_end_exclusive=provider_end,
        indexes=indexes,
        bridge_names=bridge_names,
        local_control_flow_indices=definition.local_control_flow_indices,
        local_control_flow_targets=definition.local_control_flow_targets,
    )
    if (
        len(candidate_contract) != len(definition.relocations)
        or any(row.get("dispatch") != "direct" for row in candidate_contract)
        or compare_call_contracts(retail_contract, candidate_contract)["passed"]
        is not True
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} relocation target "
            f"contract does not exactly match provider {provider_address}"
        )


def _complete_destructor_authored_target_names(
    candidate_name: str,
) -> tuple[str, str]:
    match = MSVC_COMPLETE_DESTRUCTOR_PARTS_RE.fullmatch(candidate_name)
    if match is None:
        return ()
    encoded_scope = match.group("class_name")
    if not encoded_scope.endswith("@@"):
        return ()
    scope_parts = encoded_scope[:-2].split("@")
    if not scope_parts or any(
        re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", part) is None
        for part in scope_parts
    ):
        # Template and otherwise complex scopes need separate reviewed
        # decoration handling; do not guess a source-level class identity.
        return ()
    qualifier = match.group("qualifier")
    target_symbol = f"?DestructorCore@{encoded_scope}{qualifier}XXZ"
    navigation_name = (
        f"{'::'.join(reversed(scope_parts))}::DestructorCore"
    )
    return target_symbol, navigation_name


def _prove_zsnd_wave_data_generated_destructor_ordinary_body_bridge(
    candidate_name: str,
    target_identity: str,
    *,
    expected: Sequence[Mapping[str, Any]],
    document: ProgressDocument,
    candidate: CandidateAssembly,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    invocation_row: Mapping[str, Any],
) -> bool:
    """Prove only the reviewed zSndWaveData compiler-destructor thunk.

    The immutable retail row supplies the expected 0x4a5440 identity.  Exact
    target/tracker/source authority and the independently compiled caller plus
    generated COMDAT establish only why the candidate ``??1`` edge names that
    already-reviewed ordinary body.  This intentionally does not provide a
    class-name-derived destructor mapping for any other candidate.
    """

    if candidate_name != ZSND_WAVE_DATA_DESTRUCTOR_CANDIDATE_SYMBOL:
        return False

    prefix = "zSnd wave-data generated destructor ordinary-body bridge"
    normalized_caller_start = normalize_address(caller_start)
    if (
        caller_identity != ZSND_WAVE_DATA_DESTRUCTOR_CALLER_IDENTITY
        or normalized_caller_start != ZSND_WAVE_DATA_DESTRUCTOR_CALLER_START
        or normalize_address(caller_end_exclusive)
        != ZSND_WAVE_DATA_DESTRUCTOR_CALLER_END_EXCLUSIVE
        or indexes.by_address.get(normalized_caller_start) != caller_identity
        or caller_identity in indexes.provider_ids
    ):
        raise ValueError(
            f"{prefix} requires the exact reviewed caller identity and extent"
        )

    expected_row = (
        expected[ZSND_WAVE_DATA_DESTRUCTOR_CALL_ORDINAL]
        if len(expected) > ZSND_WAVE_DATA_DESTRUCTOR_CALL_ORDINAL
        else None
    )
    exact_expected_row = {
        "ordinal": ZSND_WAVE_DATA_DESTRUCTOR_CALL_ORDINAL,
        "form": "call",
        "dispatch": "direct",
        "identity_kind": "direct",
        "target_identity": ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_IDENTITY,
        "storage_identity": "",
        "slot_displacement": None,
        "cleanup_bytes": None,
    }
    exact_candidate_row = {
        **exact_expected_row,
        "target_identity": (
            "compiler-candidate-destructor:"
            + ZSND_WAVE_DATA_DESTRUCTOR_CANDIDATE_SYMBOL
        ),
    }
    if (
        target_identity != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_IDENTITY
        or not isinstance(expected_row, Mapping)
        or dict(expected_row) != exact_expected_row
        or dict(invocation_row) != exact_candidate_row
    ):
        raise ValueError(
            f"{prefix} requires one exact immutable retail row and matching "
            "candidate invocation shape"
        )

    target = candidate.target
    caller = candidate.caller_definition
    target_rows = [
        row
        for row in getattr(target, "functions", ())
        if normalize_address(str(getattr(row, "address", "")))
        == ZSND_WAVE_DATA_DESTRUCTOR_CALLER_START
    ]
    if (
        target is None
        or getattr(target, "name", "")
        != ZSND_DESTROY_OWNED_DATA_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or Path(str(getattr(target, "manifest_path", ""))).resolve()
        != (
            REPO_ROOT / ZSND_WAVE_DATA_DESTRUCTOR_CALLER_TARGET_MANIFEST
        ).resolve()
        or getattr(target, "source_from", "")
        != ZSND_WAVE_DATA_DESTRUCTOR_CALLER_SOURCE_PATH
        or getattr(target, "check_translation_unit_function_order", False)
        is not True
        or len(target_rows) != 1
        or getattr(target_rows[0], "symbol", "")
        != ZSND_WAVE_DATA_DESTRUCTOR_CALLER_SYMBOL
        or getattr(target_rows[0], "symbol_regex", None) is not None
        or getattr(target_rows[0], "pipeline_class", "") != "authored"
        or getattr(target_rows[0], "authored_order_role", "")
        != "authored-body"
        or getattr(target_rows[0], "required_presence", None) is not True
        or getattr(target_rows[0], "full_order_gate", None) is not True
        or caller is None
        or caller.symbol != ZSND_WAVE_DATA_DESTRUCTOR_CALLER_SYMBOL
    ):
        raise ValueError(
            f"{prefix} requires the exact selected caller target, source, "
            "row, and candidate COFF symbol"
        )

    caller_target = document.collection("verification_targets").get(
        ZSND_WAVE_DATA_DESTRUCTOR_CALLER_TARGET_ID
    )
    caller_registration = (
        caller_target.get("registration")
        if isinstance(caller_target, Mapping)
        else None
    )
    caller_tracker_rows = [
        row
        for row in _mapping_target_function_rows(caller_target)
        if row.get("symbol") is not None
        and normalize_address(str(row.get("address", "")))
        == ZSND_WAVE_DATA_DESTRUCTOR_CALLER_START
    ]
    if (
        not isinstance(caller_target, Mapping)
        or caller_target.get("binary") != "recoil"
        or caller_target.get("kind") != "vc5"
        or caller_target.get("name") != ZSND_DESTROY_OWNED_DATA_TARGET_NAME
        or not isinstance(caller_registration, Mapping)
        or caller_registration.get("binary") != "recoil"
        or caller_registration.get("name")
        != ZSND_DESTROY_OWNED_DATA_TARGET_NAME
        or caller_registration.get("manifest_path")
        != ZSND_WAVE_DATA_DESTRUCTOR_CALLER_TARGET_MANIFEST
        or caller_registration.get("source_from")
        != ZSND_WAVE_DATA_DESTRUCTOR_CALLER_SOURCE_PATH
        or caller_registration.get("check_translation_unit_function_order")
        is not True
        or caller_registration.get("function_order_scope") != "authored"
        or len(caller_tracker_rows) != 2
        or any(
            row.get("symbol") != ZSND_WAVE_DATA_DESTRUCTOR_CALLER_SYMBOL
            or row.get("symbol_regex") is not None
            or row.get("name")
            != "zSndSample::CreateQueuedStreamingSample"
            or row.get("pipeline_class") != "authored"
            or row.get("authored_order_role") != "authored-body"
            or row.get("authored_order_gate") is not True
            or row.get("authored_relative_order_gate") is not True
            or row.get("required_presence") is not True
            or row.get("full_order_gate") is not True
            for row in caller_tracker_rows
        )
    ):
        raise ValueError(
            f"{prefix} requires one synchronized current caller target authority"
        )

    symbol_id = ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_IDENTITY.removeprefix(
        "symbol:"
    )
    symbol = document.collection("symbols").get(symbol_id)
    trace = (
        symbol.get("source_traceability")
        if isinstance(symbol, Mapping)
        else None
    )
    source_edges = (
        trace.get("source_edges") if isinstance(trace, Mapping) else None
    )
    verification_target_ids = (
        symbol.get("verification_target_ids")
        if isinstance(symbol, Mapping)
        else None
    )
    if (
        not isinstance(symbol, Mapping)
        or _symbol_identity(symbol_id, symbol)
        != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_IDENTITY
        or symbol.get("binary") != "recoil"
        or symbol.get("kind") != "function"
        or symbol.get("pipeline_class") != "authored"
        or symbol.get("ownership_state") != "primary-owned"
        or symbol.get("address")
        != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_ADDRESS
        or symbol.get("end_exclusive")
        != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_END_EXCLUSIVE
        or symbol.get("size") != 0x20
        or symbol.get("extent_state") != "known"
        or symbol.get("navigation_name")
        != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_NAVIGATION_NAME
        or symbol.get("output_section_id") != "recoil:section:.text"
        or symbol.get("physical_block_id") != "recoil:block:0x4a53f0"
        or not isinstance(verification_target_ids, list)
        or len(verification_target_ids) != len(set(verification_target_ids))
        or ZSND_WAVE_DATA_DESTRUCTOR_ORDER_TARGET_ID
        not in verification_target_ids
        or ZSND_WAVE_DATA_DESTRUCTOR_FOCUSED_TARGET_ID
        not in verification_target_ids
        or not isinstance(trace, Mapping)
        or trace.get("state") != "resolved"
        or trace.get("reason_code") not in {None, ""}
        or not isinstance(source_edges, list)
        or len(source_edges) != 1
        or not isinstance(source_edges[0], Mapping)
        or source_edges[0].get("relation") != "defines"
        or source_edges[0].get("anchor_id")
        != ZSND_WAVE_DATA_DESTRUCTOR_SOURCE_ANCHOR_ID
        or source_edges[0].get("emission_context")
        != {"translation_unit": ZSND_WAVE_DATA_DESTRUCTOR_SOURCE_PATH}
        or indexes.by_address.get(
            ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_ADDRESS
        )
        != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_IDENTITY
        or indexes.by_candidate_name.get(
            ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_SYMBOL
        )
        != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_IDENTITY
        or indexes.by_candidate_name.get(
            ZSND_WAVE_DATA_DESTRUCTOR_CORE_SYMBOL
        )
        is not None
    ):
        raise ValueError(
            f"{prefix} requires the exact reviewed ordinary-body tracker, "
            "source-anchor, and candidate-name identities"
        )

    order_target = document.collection("verification_targets").get(
        ZSND_WAVE_DATA_DESTRUCTOR_ORDER_TARGET_ID
    )
    order_registration = (
        order_target.get("registration")
        if isinstance(order_target, Mapping)
        else None
    )
    order_rows = [
        row
        for row in _mapping_target_function_rows(order_target)
        if row.get("symbol") is not None
        and normalize_address(str(row.get("address", "")))
        == ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_ADDRESS
    ]
    focused_target = document.collection("verification_targets").get(
        ZSND_WAVE_DATA_DESTRUCTOR_FOCUSED_TARGET_ID
    )
    focused_registration = (
        focused_target.get("registration")
        if isinstance(focused_target, Mapping)
        else None
    )
    if (
        not isinstance(order_target, Mapping)
        or order_target.get("binary") != "recoil"
        or order_target.get("kind") != "vc5"
        or order_target.get("name")
        != ZSND_WAVE_DATA_DESTRUCTOR_ORDER_TARGET_NAME
        or not isinstance(order_registration, Mapping)
        or order_registration.get("binary") != "recoil"
        or order_registration.get("name")
        != ZSND_WAVE_DATA_DESTRUCTOR_ORDER_TARGET_NAME
        or order_registration.get("manifest_path")
        != ZSND_WAVE_DATA_DESTRUCTOR_ORDER_TARGET_MANIFEST
        or order_registration.get("source_from")
        != ZSND_WAVE_DATA_DESTRUCTOR_SOURCE_PATH
        or order_registration.get("check_translation_unit_function_order")
        is not True
        or order_registration.get("function_order_scope") != "authored"
        or len(order_rows) != 2
        or any(
            row.get("symbol")
            != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_SYMBOL
            or row.get("symbol_regex") is not None
            or row.get("name")
            != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_NAVIGATION_NAME
            or row.get("pipeline_class") != "authored-lifecycle"
            or row.get("authored_order_role")
            != "authored-lifecycle-body"
            or row.get("authored_order_gate") is not True
            or row.get("authored_relative_order_gate") is not True
            or row.get("required_presence") is not True
            or row.get("full_order_gate") is not True
            or row.get("logical_identity_key") not in {None, ""}
            or row.get("icf_fold_status") not in {None, ""}
            for row in order_rows
        )
        or not isinstance(focused_target, Mapping)
        or focused_target.get("binary") != "recoil"
        or focused_target.get("kind") != "vc5"
        or focused_target.get("name")
        != ZSND_WAVE_DATA_DESTRUCTOR_FOCUSED_TARGET_NAME
        or focused_target.get("symbol_ids") != [symbol_id]
        or focused_target.get("unresolved_addresses") != []
        or not isinstance(focused_registration, Mapping)
        or focused_registration.get("binary") != "recoil"
        or focused_registration.get("name")
        != ZSND_WAVE_DATA_DESTRUCTOR_FOCUSED_TARGET_NAME
        or focused_registration.get("manifest_path")
        != ZSND_WAVE_DATA_DESTRUCTOR_FOCUSED_TARGET_MANIFEST
        or focused_registration.get("source_from")
        != ZSND_WAVE_DATA_DESTRUCTOR_SOURCE_PATH
        or focused_registration.get("function_addresses")
        != [ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_ADDRESS]
    ):
        raise ValueError(
            f"{prefix} requires synchronized authored-order and focused "
            "ordinary-body target authorities"
        )

    definition = candidate.complete_destructor_definitions.get(candidate_name)
    relocation = (
        definition.relocations[0]
        if definition is not None and len(definition.relocations) == 1
        else None
    )
    listing = (
        definition.instructions[0]
        if definition is not None and len(definition.instructions) == 1
        else None
    )
    associated = (
        definition.associated_sections[0]
        if definition is not None
        and len(definition.associated_sections) == 1
        else None
    )
    associated_relocation = (
        associated.relocations[0]
        if associated is not None and len(associated.relocations) == 1
        else None
    )
    if (
        definition is None
        or definition.symbol != candidate_name
        or not definition.section_is_comdat
        or definition.comdat_selection != 2
        or definition.section_external_functions != (candidate_name,)
        or definition.section_size != 0x10
        or definition.data
        != b"\xe9\x00\x00\x00\x00" + b"\x90" * 0x0B
        or definition.relocation_mask
        != (False, True, True, True, True) + (False,) * 0x0B
        or definition.local_control_flow_indices != frozenset()
        or bool(definition.local_control_flow_targets)
        or relocation is None
        or relocation.offset != 1
        or relocation.type != IMAGE_REL_I386_REL32
        or relocation.symbol_name
        != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_SYMBOL
        or listing is None
        or _source_instruction_address(listing) != "0x0"
        or _instruction_mnemonic(listing) != "jmp"
        or _instruction_operand(listing).strip()
        != ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_SYMBOL
        or tuple(value.lower() for value in listing.bytes)
        != ("e9", "00", "00", "00", "00")
        or associated is None
        or associated.section_index <= 0
        or associated.association_section_index <= 0
        or associated.section_index == associated.association_section_index
        or associated.name != ".debug$F"
        or associated.data
        != b"\x00\x00\x00\x00\x05" + b"\x00" * 0x0B
        or associated.relocation_mask
        != (True, True, True, True) + (False,) * 0x0C
        or associated.section_size != 0x10
        or not associated.section_is_comdat
        or associated.comdat_selection != 5
        or associated.section_external_symbols != ()
        or associated.symbols != ()
        or associated_relocation is None
        or associated_relocation.offset != 0
        or associated_relocation.type != 0x07
        or associated_relocation.symbol_name != candidate_name
    ):
        raise ValueError(
            f"{prefix} requires the exact padded VC5 SELECT_ANY COMDAT "
            "E9/REL32 thunk and associative debug section in synchronized "
            "COFF and COD"
        )

    _prove_compiler_destructor_authored_bridge(
        candidate_name,
        target_identity,
        document=document,
        candidate=candidate,
        indexes=indexes,
        invocation_row=invocation_row,
        zsnd_wave_data_ordinary_body_proven=True,
    )
    return True


def _prove_hud_ui_string_menu_generated_destructor_bridge(
    candidate_name: str,
    target_identity: str,
    *,
    expected: Sequence[Mapping[str, Any]],
    document: ProgressDocument,
    candidate: CandidateAssembly,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    invocation_row: Mapping[str, Any],
) -> bool:
    """Prove the one reviewed generated HudUiStringMenu ordinary destructor."""
    if candidate_name != HUD_UI_STRING_MENU_DESTRUCTOR_CANDIDATE_SYMBOL:
        return False
    if (
        normalize_address(caller_start) != HUD_UI_MGR_SHUTDOWN_CALLER_START
        or caller_identity != HUD_UI_MGR_SHUTDOWN_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != HUD_UI_MGR_SHUTDOWN_CALLER_END_EXCLUSIVE
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires the exact "
            "reviewed ShutdownResources caller and extent"
        )
    if (
        target_identity != HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_IDENTITY
        or invocation_row.get("ordinal")
        != HUD_UI_STRING_MENU_DESTRUCTOR_CALL_ORDINAL
        or invocation_row.get("form") != "call"
        or invocation_row.get("dispatch") != "direct"
        or invocation_row.get("cleanup_bytes") is not None
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires the exact "
            "retail target, ordinal, direct-call form, and cleanup"
        )
    if len(expected) <= HUD_UI_STRING_MENU_DELETE_CALL_ORDINAL:
        raise ValueError(
            "HUD string-menu generated destructor bridge requires the "
            "following retail global-delete invocation"
        )
    delete_row = expected[HUD_UI_STRING_MENU_DELETE_CALL_ORDINAL]
    delete_identity = str(delete_row.get("target_identity", ""))
    if (
        delete_row.get("ordinal") != HUD_UI_STRING_MENU_DELETE_CALL_ORDINAL
        or delete_row.get("form") != "call"
        or delete_row.get("dispatch") != "direct"
        or delete_row.get("identity_kind") != "provider"
        or delete_identity not in indexes.provider_ids
        or delete_row.get("storage_identity") != ""
        or delete_row.get("slot_displacement") is not None
        or delete_row.get("cleanup_bytes") != 4
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires the exact "
            "following retail global-delete call and four-byte caller cleanup"
        )

    target = candidate.target
    caller = candidate.caller_definition
    contribution_rows = [
        (entry, row)
        for entry in getattr(target, "translation_unit_function_order", ())
        for row in getattr(entry, "functions", ())
        if normalize_address(str(getattr(row, "address", "")))
        == HUD_UI_MGR_SHUTDOWN_CALLER_START
    ]
    if (
        caller is None
        or caller.symbol != HUD_UI_MGR_SHUTDOWN_CALLER_SYMBOL
        or len(caller.data)
        != address_value(HUD_UI_MGR_SHUTDOWN_CALLER_END_EXCLUSIVE)
        - address_value(HUD_UI_MGR_SHUTDOWN_CALLER_START)
        or len(caller.relocation_mask) != len(caller.data)
        or target is None
        or getattr(target, "name", "")
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or Path(str(getattr(target, "manifest_path", ""))).resolve()
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_MANIFEST.resolve()
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
        or tuple(getattr(target, "source_files", ())).count(
            HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        )
        != 1
        or len(contribution_rows) != 1
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires the exact "
            "registered HUD target, caller definition, and contribution"
        )
    contribution, contribution_row = contribution_rows[0]
    if (
        getattr(contribution, "source_from", "")
        != HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        or getattr(contribution, "order_scope", "") != "authored"
        or getattr(contribution_row, "symbol", "") != ""
        or getattr(contribution_row, "symbol_regex", None)
        != r"\?ShutdownResources@HudUiMgr@@.*"
        or re.fullmatch(
            r"\?ShutdownResources@HudUiMgr@@.*",
            caller.symbol,
        )
        is None
        or getattr(contribution_row, "name", "")
        != "HudUiMgr::ShutdownResources"
        or getattr(contribution_row, "pipeline_class", "") != "authored"
        or getattr(contribution_row, "authored_order_role", "")
        != "authored-body"
        or not bool(getattr(contribution_row, "required_presence", False))
        or not bool(getattr(contribution_row, "full_order_gate", False))
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires the exact "
            "authored ShutdownResources hud.cpp contribution identity"
        )

    target_addresses = sorted(
        address
        for address, identity in indexes.by_address.items()
        if identity == target_identity
    )
    target_symbol_id = target_identity.removeprefix("symbol:")
    target_symbol = document.collection("symbols").get(target_symbol_id)
    if (
        target_addresses != [HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_ADDRESS]
        or not isinstance(target_symbol, Mapping)
        or _symbol_identity(target_symbol_id, target_symbol) != target_identity
        or target_symbol.get("binary") != "recoil"
        or target_symbol.get("kind") != "function"
        or target_symbol.get("pipeline_class") != "authored-lifecycle"
        or target_symbol.get("authored_order_role")
        != "compiler-generated-implicit-cleanup"
        or target_symbol.get("extent_state") != "known"
        or normalize_address(str(target_symbol.get("address", "")))
        != HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_ADDRESS
        or normalize_address(str(target_symbol.get("end_exclusive", "")))
        != HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_END_EXCLUSIVE
        or target_symbol.get("size")
        != address_value(HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_END_EXCLUSIVE)
        - address_value(HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_ADDRESS)
        or target_symbol.get("logical_identity_key") not in {None, ""}
        or target_symbol.get("icf_fold_status") not in {None, ""}
        or bool(target_symbol.get("logical_aliases"))
        or bool(target_symbol.get("icf_address_group"))
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires one exact "
            "unaliased reviewed retail lifecycle target and extent"
        )

    source_function_symbols = {
        *caller.undefined_external_functions,
        *caller.defined_external_functions,
        *candidate.complete_destructor_definitions.keys(),
    }
    if (
        HUD_UI_STRING_MENU_SUPERSEDED_DESTRUCTOR_CORE_SYMBOL
        in source_function_symbols
        or any(
            HUD_UI_STRING_MENU_SUPERSEDED_DESTRUCTOR_CORE_SYMBOL
            in relocation.symbol_name
            for definition in candidate.complete_destructor_definitions.values()
            for relocation in definition.relocations
        )
        or any(
            HUD_UI_STRING_MENU_SUPERSEDED_DESTRUCTOR_CORE_SYMBOL
            in _instruction_operand(instruction)
            for instruction in candidate.instructions
        )
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge rejects the "
            "superseded authored DestructorCore source identity"
        )
    if (
        caller.undefined_external_functions.count(candidate_name) != 0
        or caller.defined_external_functions.count(candidate_name) != 1
        or caller.undefined_external_functions.count(
            HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        )
        != 1
        or caller.defined_external_functions.count(
            HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        )
        != 0
        or caller.undefined_external_data.count(
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        )
        != 1
        or HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        in caller.defined_external_data
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires one "
            "same-object destructor, one external global delete, and one "
            "external HUD aggregate"
        )

    expected_caller_sequence = bytes.fromhex(
        "8b 35 e0 0e 00 00 3b f7 74 16 8b ce "
        "e8 00 00 00 00 56 e8 00 00 00 00 83 c4 04 "
        "89 3d e0 0e 00 00"
    )
    if (
        caller.data[
            HUD_UI_STRING_MENU_CALLER_SEQUENCE_START :
            HUD_UI_STRING_MENU_CALLER_SEQUENCE_END_EXCLUSIVE
        ]
        != expected_caller_sequence
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires the exact "
            "bounded load/null-test/destruct/delete/cleanup/clear caller body"
        )
    caller_relocation_specs = (
        (
            HUD_UI_STRING_MENU_CALLER_SEQUENCE_START + 2,
            IMAGE_REL_I386_DIR32,
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
            HUD_UI_STRING_MENU_AGGREGATE_DISPLACEMENT,
        ),
        (
            HUD_UI_STRING_MENU_CALLER_DESTRUCTOR_RELOCATION_OFFSET,
            IMAGE_REL_I386_REL32,
            candidate_name,
            0,
        ),
        (
            HUD_UI_STRING_MENU_CALLER_DELETE_RELOCATION_OFFSET,
            IMAGE_REL_I386_REL32,
            HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL,
            0,
        ),
        (
            HUD_UI_STRING_MENU_CALLER_SEQUENCE_END_EXCLUSIVE - 4,
            IMAGE_REL_I386_DIR32,
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
            HUD_UI_STRING_MENU_AGGREGATE_DISPLACEMENT,
        ),
    )
    bounded_caller_relocations = tuple(
        relocation
        for relocation in caller.relocations
        if (
            HUD_UI_STRING_MENU_CALLER_SEQUENCE_START
            <= relocation.offset
            < HUD_UI_STRING_MENU_CALLER_SEQUENCE_END_EXCLUSIVE
        )
    )
    if len(bounded_caller_relocations) != len(caller_relocation_specs):
        raise ValueError(
            "HUD string-menu generated destructor bridge rejects missing, "
            "duplicate, or extra bounded caller relocations"
        )
    expected_caller_mask: set[int] = set()
    for relocation, (
        offset,
        relocation_type,
        symbol_name,
        addend,
    ) in zip(bounded_caller_relocations, caller_relocation_specs):
        if (
            relocation.offset != offset
            or relocation.type != relocation_type
            or relocation.symbol_name != symbol_name
            or struct.unpack_from("<I", caller.data, offset)[0] != addend
        ):
            raise ValueError(
                "HUD string-menu generated destructor bridge rejects wrong "
                "caller relocation offset, type, target, or addend"
            )
        expected_caller_mask.update(range(offset, offset + 4))
    actual_caller_mask = {
        index
        for index in range(
            HUD_UI_STRING_MENU_CALLER_SEQUENCE_START,
            HUD_UI_STRING_MENU_CALLER_SEQUENCE_END_EXCLUSIVE,
        )
        if caller.relocation_mask[index]
    }
    if actual_caller_mask != expected_caller_mask:
        raise ValueError(
            "HUD string-menu generated destructor bridge requires an exact "
            "bounded caller relocation mask"
        )

    instruction_offsets = [
        (
            address_value(address)
            if (address := _source_instruction_address(instruction))
            else None
        )
        for instruction in candidate.instructions
    ]
    offset_counts: dict[int, int] = {}
    for offset in instruction_offsets:
        if offset is not None:
            offset_counts[offset] = offset_counts.get(offset, 0) + 1
    index_by_offset = {
        offset: index
        for index, offset in enumerate(instruction_offsets)
        if offset is not None and offset_counts.get(offset) == 1
    }
    destructor_index = index_by_offset.get(
        HUD_UI_STRING_MENU_CALLER_DESTRUCTOR_RELOCATION_OFFSET - 1
    )
    delete_index = index_by_offset.get(
        HUD_UI_STRING_MENU_CALLER_DELETE_RELOCATION_OFFSET - 1
    )
    invocation_indices = _candidate_static_invocation_indices(
        candidate,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
    )
    ordinal_by_index = {
        index: ordinal for ordinal, index in enumerate(invocation_indices)
    }
    if (
        destructor_index is None
        or delete_index is None
        or ordinal_by_index.get(destructor_index)
        != HUD_UI_STRING_MENU_DESTRUCTOR_CALL_ORDINAL
        or ordinal_by_index.get(delete_index)
        != HUD_UI_STRING_MENU_DELETE_CALL_ORDINAL
        or destructor_index in candidate.local_control_flow_indices
        or delete_index in candidate.local_control_flow_indices
        or _instruction_mnemonic(candidate.instructions[destructor_index])
        != "call"
        or _instruction_operand(
            candidate.instructions[destructor_index]
        ).strip()
        != candidate_name
        or _cleanup_after(candidate.instructions, destructor_index) is not None
        or _instruction_mnemonic(candidate.instructions[delete_index])
        != "call"
        or _instruction_operand(candidate.instructions[delete_index]).strip()
        != HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        or _cleanup_after(candidate.instructions, delete_index) != 4
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge rejects wrong caller "
            "ordinal, call form, target, local-flow status, or cleanup"
        )

    delete_name_rows = bridge_names.get(
        HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL,
        (),
    )
    delete_name_rows = (
        list(delete_name_rows)
        if isinstance(
            delete_name_rows,
            (list, tuple, set, frozenset),
        )
        else [delete_name_rows]
    )
    if (
        len(delete_name_rows) != 1
        or normalize_address(
            str(getattr(delete_name_rows[0], "address", ""))
        )
        != HUD_UI_STRING_MENU_GLOBAL_DELETE_ADDRESS
        or HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        not in {
            str(getattr(delete_name_rows[0], "name", "")),
            str(getattr(delete_name_rows[0], "raw_name", "")),
            str(getattr(delete_name_rows[0], "full_name", "")),
        }
        or indexes.by_address.get(HUD_UI_STRING_MENU_GLOBAL_DELETE_ADDRESS)
        != delete_identity
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires one exact "
            "retail global operator-delete provider identity"
        )

    destructor = candidate.complete_destructor_definitions.get(candidate_name)
    target_size = (
        address_value(HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_END_EXCLUSIVE)
        - address_value(HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_ADDRESS)
    )
    if (
        destructor is None
        or not destructor.section_is_comdat
        or destructor.comdat_selection != 2
        or destructor.section_external_functions != (candidate_name,)
        or destructor.section_size != target_size
        or len(destructor.data) != target_size
        or len(destructor.relocation_mask) != target_size
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires one exact "
            "full-section VC5 COMDAT SELECT_ANY ordinary-destructor definition"
        )
    relocation_specs: tuple[
        tuple[int, int, str | re.Pattern[str]], ...
    ] = (
        (0x02, IMAGE_REL_I386_DIR32, "__except_list"),
        (0x09, IMAGE_REL_I386_DIR32, re.compile(r"\$L[0-9]+")),
        (0x11, IMAGE_REL_I386_DIR32, "__except_list"),
        (
            0x19,
            IMAGE_REL_I386_DIR32,
            HUD_UI_STRING_MENU_PANEL_DESTRUCTOR_SYMBOL,
        ),
        (0x31, IMAGE_REL_I386_REL32, MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL),
        (
            0x40,
            IMAGE_REL_I386_REL32,
            HUD_UI_STRING_MENU_CONTAINER_DESTRUCTOR_SYMBOL,
        ),
        (0x4C, IMAGE_REL_I386_DIR32, "__except_list"),
    )
    if len(destructor.relocations) != len(relocation_specs):
        raise ValueError(
            "HUD string-menu generated destructor bridge rejects missing, "
            "duplicate, or extra definition relocations"
        )
    expected_definition_mask: set[int] = set()
    for relocation, (offset, relocation_type, symbol_spec) in zip(
        destructor.relocations,
        relocation_specs,
    ):
        symbol_matches = (
            symbol_spec.fullmatch(relocation.symbol_name) is not None
            if isinstance(symbol_spec, re.Pattern)
            else relocation.symbol_name == symbol_spec
        )
        if (
            relocation.offset != offset
            or relocation.type != relocation_type
            or not symbol_matches
            or struct.unpack_from("<I", destructor.data, offset)[0] != 0
        ):
            raise ValueError(
                "HUD string-menu generated destructor bridge rejects wrong "
                "definition relocation offset, type, target, or addend"
            )
        expected_definition_mask.update(range(offset, offset + 4))
    actual_definition_mask = {
        index
        for index, masked in enumerate(destructor.relocation_mask)
        if masked
    }
    if actual_definition_mask != expected_definition_mask:
        raise ValueError(
            "HUD string-menu generated destructor bridge requires an exact "
            "definition relocation mask"
        )

    if (
        indexes.by_address.get(HUD_UI_STRING_MENU_PANEL_DESTRUCTOR_ADDRESS)
        != HUD_UI_STRING_MENU_PANEL_DESTRUCTOR_IDENTITY
        or indexes.by_address.get(
            HUD_UI_STRING_MENU_CONTAINER_DESTRUCTOR_ADDRESS
        )
        != HUD_UI_STRING_MENU_CONTAINER_DESTRUCTOR_IDENTITY
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires the exact "
            "retail panel callback and container cleanup identities"
        )
    retail_bytes = _hexdump_bytes(
        bridge.hexdump(
            HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_ADDRESS,
            target_size,
        )
    )
    if (
        len(retail_bytes) != target_size
        or struct.unpack_from("<I", retail_bytes, 0x19)[0]
        != address_value(HUD_UI_STRING_MENU_PANEL_DESTRUCTOR_ADDRESS)
        or any(
            candidate_byte != retail_byte
            for index, (candidate_byte, retail_byte) in enumerate(
                zip(destructor.data, retail_bytes)
            )
            if not destructor.relocation_mask[index]
        )
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires exact "
            "relocation-normalized retail body bytes without a vptr store"
        )

    retail_contract = extract_invocation_contract(
        parse_assembly(
            bridge.assembly(HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_ADDRESS),
            source="bn",
        ),
        source="bn",
        caller_identity=target_identity,
        caller_start=HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_ADDRESS,
        caller_end_exclusive=(
            HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_END_EXCLUSIVE
        ),
        indexes=_without_caller_scoped_retail_proofs(indexes),
        bridge_names=bridge_names,
    )
    if (
        len(retail_contract) != 2
        or retail_contract[0].get("ordinal") != 0
        or retail_contract[0].get("form") != "call"
        or retail_contract[0].get("dispatch") != "direct"
        or retail_contract[0].get("identity_kind") != "provider"
        or retail_contract[0].get("target_identity")
        not in indexes.provider_ids
        or retail_contract[0].get("cleanup_bytes") is not None
        or retail_contract[1]
        != {
            "ordinal": 1,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": (
                HUD_UI_STRING_MENU_CONTAINER_DESTRUCTOR_IDENTITY
            ),
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        }
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires the exact "
            "retail EH-array and container cleanup call topology"
        )
    candidate_contract = extract_invocation_contract(
        destructor.instructions,
        source="cod",
        caller_identity=target_identity,
        caller_start=HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_ADDRESS,
        caller_end_exclusive=(
            HUD_UI_STRING_MENU_DESTRUCTOR_TARGET_END_EXCLUSIVE
        ),
        indexes=indexes,
        bridge_names=bridge_names,
        compiler_generated_bridges={
            MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL: str(
                retail_contract[0]["target_identity"]
            ),
            HUD_UI_STRING_MENU_CONTAINER_DESTRUCTOR_SYMBOL: (
                HUD_UI_STRING_MENU_CONTAINER_DESTRUCTOR_IDENTITY
            ),
        },
        local_control_flow_indices=destructor.local_control_flow_indices,
        local_control_flow_targets=destructor.local_control_flow_targets,
    )
    if (
        len(candidate_contract) != 2
        or compare_call_contracts(retail_contract, candidate_contract)[
            "passed"
        ]
        is not True
    ):
        raise ValueError(
            "HUD string-menu generated destructor bridge requires an exact "
            "relocation-normalized candidate/retail call topology"
        )
    return True


def _prove_hud_ui_shield_message_generated_destructor_bridge(
    candidate_name: str,
    target_identity: str,
    *,
    expected: Sequence[Mapping[str, Any]],
    document: ProgressDocument,
    candidate: CandidateAssembly,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    invocation_row: Mapping[str, Any],
) -> bool:
    """Prove one reviewed VC5 HudUiShieldMessageWidget ordinary destructor."""
    if candidate_name != HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_CANDIDATE_SYMBOL:
        return False
    if (
        normalize_address(caller_start) != HUD_UI_MGR_SHUTDOWN_CALLER_START
        or caller_identity != HUD_UI_MGR_SHUTDOWN_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != HUD_UI_MGR_SHUTDOWN_CALLER_END_EXCLUSIVE
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires the "
            "exact reviewed ShutdownResources caller and extent"
        )
    if (
        target_identity != HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_IDENTITY
        or invocation_row.get("ordinal")
        != HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_CALL_ORDINAL
        or invocation_row.get("form") != "call"
        or invocation_row.get("dispatch") != "direct"
        or invocation_row.get("cleanup_bytes") is not None
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires the "
            "exact retail target, ordinal, direct-call form, and cleanup"
        )
    if len(expected) <= HUD_UI_SHIELD_MESSAGE_DELETE_CALL_ORDINAL:
        raise ValueError(
            "HUD shield-message generated destructor bridge requires the "
            "following retail global-delete invocation"
        )
    delete_row = expected[HUD_UI_SHIELD_MESSAGE_DELETE_CALL_ORDINAL]
    delete_identity = str(delete_row.get("target_identity", ""))
    if (
        delete_row.get("ordinal")
        != HUD_UI_SHIELD_MESSAGE_DELETE_CALL_ORDINAL
        or delete_row.get("form") != "call"
        or delete_row.get("dispatch") != "direct"
        or delete_row.get("identity_kind") != "provider"
        or delete_identity not in indexes.provider_ids
        or delete_row.get("storage_identity") != ""
        or delete_row.get("slot_displacement") is not None
        or delete_row.get("cleanup_bytes") != 4
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires the "
            "exact following retail global-delete call and caller cleanup"
        )

    target = candidate.target
    caller = candidate.caller_definition
    contribution_rows = [
        (entry, row)
        for entry in getattr(target, "translation_unit_function_order", ())
        for row in getattr(entry, "functions", ())
        if normalize_address(str(getattr(row, "address", "")))
        == HUD_UI_MGR_SHUTDOWN_CALLER_START
    ]
    if (
        caller is None
        or caller.symbol != HUD_UI_MGR_SHUTDOWN_CALLER_SYMBOL
        or len(caller.data)
        != address_value(HUD_UI_MGR_SHUTDOWN_CALLER_END_EXCLUSIVE)
        - address_value(HUD_UI_MGR_SHUTDOWN_CALLER_START)
        or len(caller.relocation_mask) != len(caller.data)
        or target is None
        or getattr(target, "name", "")
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or Path(str(getattr(target, "manifest_path", ""))).resolve()
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_MANIFEST.resolve()
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
        or tuple(getattr(target, "source_files", ())).count(
            HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        )
        != 1
        or len(contribution_rows) != 1
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires the "
            "exact registered HUD target, caller definition, and contribution"
        )
    contribution, contribution_row = contribution_rows[0]
    if (
        getattr(contribution, "source_from", "")
        != HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        or getattr(contribution, "order_scope", "") != "authored"
        or getattr(contribution_row, "symbol", "") != ""
        or getattr(contribution_row, "symbol_regex", None)
        != r"\?ShutdownResources@HudUiMgr@@.*"
        or re.fullmatch(
            r"\?ShutdownResources@HudUiMgr@@.*",
            caller.symbol,
        )
        is None
        or getattr(contribution_row, "name", "")
        != "HudUiMgr::ShutdownResources"
        or getattr(contribution_row, "pipeline_class", "") != "authored"
        or getattr(contribution_row, "authored_order_role", "")
        != "authored-body"
        or not bool(getattr(contribution_row, "required_presence", False))
        or not bool(getattr(contribution_row, "full_order_gate", False))
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires the "
            "exact authored ShutdownResources hud.cpp contribution identity"
        )

    target_addresses = sorted(
        address
        for address, identity in indexes.by_address.items()
        if identity == target_identity
    )
    target_symbol_id = target_identity.removeprefix("symbol:")
    target_symbol = document.collection("symbols").get(target_symbol_id)
    target_size = (
        address_value(HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_END_EXCLUSIVE)
        - address_value(HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_ADDRESS)
    )
    if (
        target_addresses != [HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_ADDRESS]
        or not isinstance(target_symbol, Mapping)
        or _symbol_identity(target_symbol_id, target_symbol) != target_identity
        or target_symbol.get("binary") != "recoil"
        or target_symbol.get("kind") != "function"
        or target_symbol.get("pipeline_class") != "authored-lifecycle"
        or target_symbol.get("authored_order_role")
        != "compiler-generated-implicit-cleanup"
        or target_symbol.get("extent_state") != "known"
        or normalize_address(str(target_symbol.get("address", "")))
        != HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_ADDRESS
        or normalize_address(str(target_symbol.get("end_exclusive", "")))
        != HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_END_EXCLUSIVE
        or target_symbol.get("size") != target_size
        or target_symbol.get("logical_identity_key") not in {None, ""}
        or target_symbol.get("icf_fold_status") not in {None, ""}
        or bool(target_symbol.get("logical_aliases"))
        or bool(target_symbol.get("icf_address_group"))
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires one "
            "exact unaliased reviewed retail lifecycle target and extent"
        )

    superseded_names = {
        HUD_UI_SHIELD_MESSAGE_SUPERSEDED_DESTRUCTOR_SYMBOL,
        HUD_UI_SHIELD_MESSAGE_SUPERSEDED_DESTRUCTOR_CORE_SYMBOL,
    }
    source_function_symbols = {
        *caller.undefined_external_functions,
        *caller.defined_external_functions,
        *candidate.complete_destructor_definitions.keys(),
    }
    if (
        source_function_symbols & superseded_names
        or any(
            any(name in relocation.symbol_name for name in superseded_names)
            for definition in candidate.complete_destructor_definitions.values()
            for relocation in definition.relocations
        )
        or any(
            any(
                name in relocation.symbol_name
                for name in superseded_names
            )
            for definition in candidate.complete_destructor_definitions.values()
            for section in definition.associated_sections
            for relocation in section.relocations
        )
        or any(
            any(name in _instruction_operand(instruction) for name in superseded_names)
            for instruction in candidate.instructions
        )
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge rejects the "
            "superseded authored Destructor/DestructorCore identities"
        )
    if (
        caller.undefined_external_functions.count(candidate_name) != 0
        or caller.defined_external_functions.count(candidate_name) != 1
        or caller.undefined_external_functions.count(
            HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        )
        != 1
        or caller.defined_external_functions.count(
            HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        )
        != 0
        or caller.undefined_external_data.count(
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        )
        != 1
        or HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL
        in caller.defined_external_data
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires one "
            "same-object destructor, one global delete, and one HUD aggregate"
        )

    expected_caller_sequence = bytes.fromhex(
        "8b 35 dc 0e 00 00 3b f7 74 16 8b ce "
        "e8 00 00 00 00 56 e8 00 00 00 00 83 c4 04 "
        "89 3d dc 0e 00 00"
    )
    if (
        caller.data[
            HUD_UI_SHIELD_MESSAGE_CALLER_SEQUENCE_START :
            HUD_UI_SHIELD_MESSAGE_CALLER_SEQUENCE_END_EXCLUSIVE
        ]
        != expected_caller_sequence
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires the "
            "exact bounded load/destruct/delete/cleanup/clear caller body"
        )
    caller_relocation_specs = (
        (
            HUD_UI_SHIELD_MESSAGE_CALLER_SEQUENCE_START + 2,
            IMAGE_REL_I386_DIR32,
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
            HUD_UI_SHIELD_MESSAGE_AGGREGATE_DISPLACEMENT,
        ),
        (
            HUD_UI_SHIELD_MESSAGE_CALLER_DESTRUCTOR_RELOCATION_OFFSET,
            IMAGE_REL_I386_REL32,
            candidate_name,
            0,
        ),
        (
            HUD_UI_SHIELD_MESSAGE_CALLER_DELETE_RELOCATION_OFFSET,
            IMAGE_REL_I386_REL32,
            HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL,
            0,
        ),
        (
            HUD_UI_SHIELD_MESSAGE_CALLER_SEQUENCE_END_EXCLUSIVE - 4,
            IMAGE_REL_I386_DIR32,
            HUD_UI_MGR_AGGREGATE_DECORATED_SYMBOL,
            HUD_UI_SHIELD_MESSAGE_AGGREGATE_DISPLACEMENT,
        ),
    )
    bounded_caller_relocations = tuple(
        relocation
        for relocation in caller.relocations
        if (
            HUD_UI_SHIELD_MESSAGE_CALLER_SEQUENCE_START
            <= relocation.offset
            < HUD_UI_SHIELD_MESSAGE_CALLER_SEQUENCE_END_EXCLUSIVE
        )
    )
    if len(bounded_caller_relocations) != len(caller_relocation_specs):
        raise ValueError(
            "HUD shield-message generated destructor bridge rejects missing, "
            "duplicate, or extra bounded caller relocations"
        )
    expected_caller_mask: set[int] = set()
    for relocation, (
        offset,
        relocation_type,
        symbol_name,
        addend,
    ) in zip(bounded_caller_relocations, caller_relocation_specs):
        if (
            relocation.offset != offset
            or relocation.type != relocation_type
            or relocation.symbol_name != symbol_name
            or struct.unpack_from("<I", caller.data, offset)[0] != addend
        ):
            raise ValueError(
                "HUD shield-message generated destructor bridge rejects wrong "
                "caller relocation offset, type, target, or addend"
            )
        expected_caller_mask.update(range(offset, offset + 4))
    actual_caller_mask = {
        index
        for index in range(
            HUD_UI_SHIELD_MESSAGE_CALLER_SEQUENCE_START,
            HUD_UI_SHIELD_MESSAGE_CALLER_SEQUENCE_END_EXCLUSIVE,
        )
        if caller.relocation_mask[index]
    }
    if actual_caller_mask != expected_caller_mask:
        raise ValueError(
            "HUD shield-message generated destructor bridge requires an exact "
            "bounded caller relocation mask"
        )

    instruction_offsets = [
        (
            address_value(address)
            if (address := _source_instruction_address(instruction))
            else None
        )
        for instruction in candidate.instructions
    ]
    offset_counts: dict[int, int] = {}
    for offset in instruction_offsets:
        if offset is not None:
            offset_counts[offset] = offset_counts.get(offset, 0) + 1
    index_by_offset = {
        offset: index
        for index, offset in enumerate(instruction_offsets)
        if offset is not None and offset_counts.get(offset) == 1
    }
    destructor_index = index_by_offset.get(
        HUD_UI_SHIELD_MESSAGE_CALLER_DESTRUCTOR_RELOCATION_OFFSET - 1
    )
    delete_index = index_by_offset.get(
        HUD_UI_SHIELD_MESSAGE_CALLER_DELETE_RELOCATION_OFFSET - 1
    )
    invocation_indices = _candidate_static_invocation_indices(
        candidate,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
    )
    ordinal_by_index = {
        index: ordinal for ordinal, index in enumerate(invocation_indices)
    }
    if (
        destructor_index is None
        or delete_index is None
        or ordinal_by_index.get(destructor_index)
        != HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_CALL_ORDINAL
        or ordinal_by_index.get(delete_index)
        != HUD_UI_SHIELD_MESSAGE_DELETE_CALL_ORDINAL
        or destructor_index in candidate.local_control_flow_indices
        or delete_index in candidate.local_control_flow_indices
        or _instruction_mnemonic(candidate.instructions[destructor_index])
        != "call"
        or _instruction_operand(
            candidate.instructions[destructor_index]
        ).strip()
        != candidate_name
        or _cleanup_after(candidate.instructions, destructor_index) is not None
        or _instruction_mnemonic(candidate.instructions[delete_index])
        != "call"
        or _instruction_operand(candidate.instructions[delete_index]).strip()
        != HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        or _cleanup_after(candidate.instructions, delete_index) != 4
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge rejects wrong "
            "caller ordinal, form, target, local-flow status, or cleanup"
        )

    delete_name_rows = bridge_names.get(
        HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL,
        (),
    )
    delete_name_rows = (
        list(delete_name_rows)
        if isinstance(delete_name_rows, (list, tuple, set, frozenset))
        else [delete_name_rows]
    )
    if (
        len(delete_name_rows) != 1
        or normalize_address(
            str(getattr(delete_name_rows[0], "address", ""))
        )
        != HUD_UI_STRING_MENU_GLOBAL_DELETE_ADDRESS
        or HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        not in {
            str(getattr(delete_name_rows[0], "name", "")),
            str(getattr(delete_name_rows[0], "raw_name", "")),
            str(getattr(delete_name_rows[0], "full_name", "")),
        }
        or indexes.by_address.get(HUD_UI_STRING_MENU_GLOBAL_DELETE_ADDRESS)
        != delete_identity
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires one "
            "exact retail global operator-delete provider identity"
        )

    destructor = candidate.complete_destructor_definitions.get(candidate_name)
    if (
        destructor is None
        or not destructor.section_is_comdat
        or destructor.comdat_selection != 2
        or destructor.section_external_functions != (candidate_name,)
        or destructor.section_size != target_size
        or len(destructor.data) != target_size
        or len(destructor.relocation_mask) != target_size
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires one "
            "exact full-section VC5 COMDAT SELECT_ANY destructor definition"
        )
    expected_definition_body = bytes.fromhex(
        "64 a1 00 00 00 00 6a ff 68 00 00 00 00 50 64 89 "
        "25 00 00 00 00 56 8b f1 8d 8e d8 00 00 00 c7 44 "
        "24 0c 00 00 00 00 c7 86 7c 03 00 00 00 00 00 00 "
        "e8 00 00 00 00 8d 4e 1c c7 44 24 0c ff ff ff ff "
        "e8 00 00 00 00 8b 4c 24 04 5e 64 89 0d 00 00 00 "
        "00 83 c4 0c c3 90 90 90 90 90 90 90 90 90 90 90"
    )
    if (
        destructor.data != expected_definition_body
        or destructor.data[HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_CODE_SIZE - 1]
        != 0xC3
        or set(
            destructor.data[
                HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_CODE_SIZE :
            ]
        )
        != {0x90}
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires the "
            "exact 0x55 code definition and VC5 section padding"
        )
    relocation_specs: tuple[
        tuple[int, int, str | re.Pattern[str]], ...
    ] = (
        (0x02, IMAGE_REL_I386_DIR32, "__except_list"),
        (0x09, IMAGE_REL_I386_DIR32, re.compile(r"\$L[0-9]+")),
        (0x11, IMAGE_REL_I386_DIR32, "__except_list"),
        (
            0x2C,
            IMAGE_REL_I386_DIR32,
            HUD_UI_SHIELD_MESSAGE_VFTABLE_SYMBOL,
        ),
        (
            0x31,
            IMAGE_REL_I386_REL32,
            HUD_UI_SHIELD_MESSAGE_PANEL_DESTRUCTOR_SYMBOL,
        ),
        (
            0x41,
            IMAGE_REL_I386_REL32,
            HUD_UI_SHIELD_MESSAGE_WIDGET_DESTRUCTOR_SYMBOL,
        ),
        (0x4D, IMAGE_REL_I386_DIR32, "__except_list"),
    )
    if len(destructor.relocations) != len(relocation_specs):
        raise ValueError(
            "HUD shield-message generated destructor bridge rejects missing, "
            "duplicate, or extra definition relocations"
        )
    expected_definition_mask: set[int] = set()
    for relocation, (offset, relocation_type, symbol_spec) in zip(
        destructor.relocations,
        relocation_specs,
    ):
        symbol_matches = (
            symbol_spec.fullmatch(relocation.symbol_name) is not None
            if isinstance(symbol_spec, re.Pattern)
            else relocation.symbol_name == symbol_spec
        )
        if (
            relocation.offset != offset
            or relocation.type != relocation_type
            or not symbol_matches
            or struct.unpack_from("<I", destructor.data, offset)[0] != 0
        ):
            raise ValueError(
                "HUD shield-message generated destructor bridge rejects wrong "
                "definition relocation offset, type, target, or addend"
            )
        expected_definition_mask.update(range(offset, offset + 4))
    if {
        index
        for index, masked in enumerate(destructor.relocation_mask)
        if masked
    } != expected_definition_mask:
        raise ValueError(
            "HUD shield-message generated destructor bridge requires an exact "
            "definition relocation mask"
        )

    if (
        indexes.by_address.get(HUD_UI_SHIELD_MESSAGE_PANEL_DESTRUCTOR_ADDRESS)
        != HUD_UI_SHIELD_MESSAGE_PANEL_DESTRUCTOR_IDENTITY
        or indexes.by_address.get(
            HUD_UI_SHIELD_MESSAGE_WIDGET_DESTRUCTOR_ADDRESS
        )
        != HUD_UI_SHIELD_MESSAGE_WIDGET_DESTRUCTOR_IDENTITY
        or indexes.by_address.get(HUD_UI_SHIELD_MESSAGE_FRAME_HANDLER_ADDRESS)
        not in indexes.provider_ids
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires exact "
            "panel, widget, and frame-handler retail identities"
        )
    retail_bytes = _hexdump_bytes(
        bridge.hexdump(
            HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_ADDRESS,
            target_size,
        )
    )
    if (
        len(retail_bytes) != target_size
        or struct.unpack_from("<I", retail_bytes, 0x09)[0]
        != address_value(HUD_UI_SHIELD_MESSAGE_FUNCLET_ADDRESS) + 0x0B
        or struct.unpack_from("<I", retail_bytes, 0x2C)[0]
        != address_value(HUD_UI_SHIELD_MESSAGE_VFTABLE_ADDRESS)
        or any(
            candidate_byte != retail_byte
            for index, (candidate_byte, retail_byte) in enumerate(
                zip(destructor.data, retail_bytes)
            )
            if not destructor.relocation_mask[index]
        )
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires exact "
            "relocation-normalized retail body, handler, and vptr reset"
        )

    runtime_associations = tuple(
        section
        for section in destructor.associated_sections
        if section.name.startswith(".text")
        or section.name.startswith(".xdata")
    )
    if (
        len(runtime_associations) != 2
        or sorted(section.name for section in runtime_associations)
        != [".text$x", ".xdata$x"]
        or any(
            not section.section_is_comdat
            or section.comdat_selection != 5
            or section.association_section_index <= 0
            or section.section_external_symbols
            for section in runtime_associations
        )
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires exactly "
            "one associative runtime funclet and one associative xdata section"
        )
    funclet = next(
        section for section in runtime_associations if section.name == ".text$x"
    )
    xdata = next(
        section for section in runtime_associations if section.name == ".xdata$x"
    )
    if (
        funclet.association_section_index != xdata.association_section_index
        or funclet.section_index == xdata.section_index
        or funclet.section_size != HUD_UI_SHIELD_MESSAGE_FUNCLET_SIZE
        or len(funclet.data) != HUD_UI_SHIELD_MESSAGE_FUNCLET_SIZE
        or xdata.section_size != HUD_UI_SHIELD_MESSAGE_XDATA_SIZE
        or len(xdata.data) != HUD_UI_SHIELD_MESSAGE_XDATA_SIZE
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge rejects wrong "
            "associative section identity, association, or extent"
        )
    expected_funclet_body = bytes.fromhex(
        "8b 4d e8 83 c1 1c e9 00 00 00 00 b8 00 00 00 00 "
        "e9 00 00 00 00"
    )
    expected_xdata_body = bytes.fromhex(
        "20 05 93 19 01 00 00 00 00 00 00 00 "
        "00 00 00 00 00 00 00 00 00 00 00 00 "
        "00 00 00 00 00 00 00 00 ff ff ff ff 00 00 00 00"
    )
    if funclet.data != expected_funclet_body or xdata.data != expected_xdata_body:
        raise ValueError(
            "HUD shield-message generated destructor bridge requires exact "
            "state0/state-1 funclet and xdata topology bytes"
        )
    funclet_relocation_specs = (
        (
            0x07,
            IMAGE_REL_I386_REL32,
            HUD_UI_SHIELD_MESSAGE_WIDGET_DESTRUCTOR_SYMBOL,
        ),
        (0x0C, IMAGE_REL_I386_DIR32, re.compile(r"\$T[0-9]+")),
        (
            0x11,
            IMAGE_REL_I386_REL32,
            HUD_UI_SHIELD_MESSAGE_FRAME_HANDLER_SYMBOL,
        ),
    )
    xdata_relocation_specs = (
        (0x08, IMAGE_REL_I386_DIR32, re.compile(r"\$T[0-9]+")),
        (0x24, IMAGE_REL_I386_DIR32, re.compile(r"\$L[0-9]+")),
    )

    def require_exact_relocations(
        section: CandidateAssociatedSection,
        specs: Sequence[tuple[int, int, str | re.Pattern[str]]],
    ) -> None:
        if len(section.relocations) != len(specs):
            raise ValueError(
                "HUD shield-message generated destructor bridge rejects "
                f"missing, duplicate, or extra {section.name} relocations"
            )
        expected_mask: set[int] = set()
        for relocation, (offset, relocation_type, symbol_spec) in zip(
            section.relocations,
            specs,
        ):
            symbol_matches = (
                symbol_spec.fullmatch(relocation.symbol_name) is not None
                if isinstance(symbol_spec, re.Pattern)
                else relocation.symbol_name == symbol_spec
            )
            if (
                relocation.offset != offset
                or relocation.type != relocation_type
                or not symbol_matches
                or struct.unpack_from("<I", section.data, offset)[0] != 0
            ):
                raise ValueError(
                    "HUD shield-message generated destructor bridge rejects "
                    f"wrong {section.name} relocation target/type/addend"
                )
            expected_mask.update(range(offset, offset + 4))
        if {
            index
            for index, masked in enumerate(section.relocation_mask)
            if masked
        } != expected_mask:
            raise ValueError(
                "HUD shield-message generated destructor bridge requires an "
                f"exact {section.name} relocation mask"
            )

    require_exact_relocations(funclet, funclet_relocation_specs)
    require_exact_relocations(xdata, xdata_relocation_specs)
    funclet_locals = {
        symbol.value: symbol.name
        for symbol in funclet.symbols
        if symbol.storage_class == 6
        and symbol.type == 0
        and re.fullmatch(r"\$L[0-9]+", symbol.name)
    }
    xdata_locals = {
        symbol.value: symbol.name
        for symbol in xdata.symbols
        if symbol.storage_class == 3
        and symbol.type == 0
        and re.fullmatch(r"\$T[0-9]+", symbol.name)
    }
    if (
        set(funclet_locals) != {0, 0x0B}
        or set(xdata_locals) != {0, 0x20}
        or destructor.relocations[1].symbol_name != funclet_locals[0x0B]
        or funclet.relocations[1].symbol_name != xdata_locals[0]
        or xdata.relocations[0].symbol_name != xdata_locals[0x20]
        or xdata.relocations[1].symbol_name != funclet_locals[0]
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires exact "
            "main/handler/state-table/funclet local-symbol linkage"
        )

    retail_funclet = _hexdump_bytes(
        bridge.hexdump(
            HUD_UI_SHIELD_MESSAGE_FUNCLET_ADDRESS,
            HUD_UI_SHIELD_MESSAGE_FUNCLET_SIZE,
        )
    )
    retail_xdata = _hexdump_bytes(
        bridge.hexdump(
            HUD_UI_SHIELD_MESSAGE_XDATA_ADDRESS,
            HUD_UI_SHIELD_MESSAGE_XDATA_SIZE,
        )
    )
    if (
        len(retail_funclet) != HUD_UI_SHIELD_MESSAGE_FUNCLET_SIZE
        or len(retail_xdata) != HUD_UI_SHIELD_MESSAGE_XDATA_SIZE
        or struct.unpack_from("<I", retail_funclet, 0x0C)[0]
        != address_value(HUD_UI_SHIELD_MESSAGE_XDATA_ADDRESS)
        or struct.unpack_from("<I", retail_xdata, 0x08)[0]
        != address_value(HUD_UI_SHIELD_MESSAGE_XDATA_ADDRESS) + 0x20
        or struct.unpack_from("<I", retail_xdata, 0x24)[0]
        != address_value(HUD_UI_SHIELD_MESSAGE_FUNCLET_ADDRESS)
        or any(
            candidate_byte != retail_byte
            for index, (candidate_byte, retail_byte) in enumerate(
                zip(funclet.data, retail_funclet)
            )
            if not funclet.relocation_mask[index]
        )
        or any(
            candidate_byte != retail_byte
            for index, (candidate_byte, retail_byte) in enumerate(
                zip(xdata.data, retail_xdata)
            )
            if not xdata.relocation_mask[index]
        )
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires exact "
            "relocation-normalized retail funclet and xdata state topology"
        )
    funclet_widget_target = (
        address_value(HUD_UI_SHIELD_MESSAGE_FUNCLET_ADDRESS)
        + 0x0B
        + struct.unpack_from("<i", retail_funclet, 0x07)[0]
    )
    funclet_handler_target = (
        address_value(HUD_UI_SHIELD_MESSAGE_FUNCLET_ADDRESS)
        + 0x15
        + struct.unpack_from("<i", retail_funclet, 0x11)[0]
    )
    if (
        funclet_widget_target
        != address_value(HUD_UI_SHIELD_MESSAGE_WIDGET_DESTRUCTOR_ADDRESS)
        or funclet_handler_target
        != address_value(HUD_UI_SHIELD_MESSAGE_FRAME_HANDLER_ADDRESS)
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires the "
            "exact this+0x1c unwind tail target and frame handler"
        )

    retail_contract = extract_invocation_contract(
        parse_assembly(
            bridge.assembly(
                HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_ADDRESS
            ),
            source="bn",
        ),
        source="bn",
        caller_identity=target_identity,
        caller_start=HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_ADDRESS,
        caller_end_exclusive=(
            HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_END_EXCLUSIVE
        ),
        indexes=_without_caller_scoped_retail_proofs(indexes),
        bridge_names=bridge_names,
    )
    expected_retail_contract = [
        {
            "ordinal": 0,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": HUD_UI_SHIELD_MESSAGE_PANEL_DESTRUCTOR_IDENTITY,
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        },
        {
            "ordinal": 1,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": HUD_UI_SHIELD_MESSAGE_WIDGET_DESTRUCTOR_IDENTITY,
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        },
    ]
    if retail_contract != expected_retail_contract:
        raise ValueError(
            "HUD shield-message generated destructor bridge requires exact "
            "panel-reset then widget-cleanup retail call topology"
        )
    candidate_contract = extract_invocation_contract(
        destructor.instructions,
        source="cod",
        caller_identity=target_identity,
        caller_start=HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_ADDRESS,
        caller_end_exclusive=(
            HUD_UI_SHIELD_MESSAGE_DESTRUCTOR_TARGET_END_EXCLUSIVE
        ),
        indexes=indexes,
        bridge_names=bridge_names,
        compiler_generated_bridges={
            HUD_UI_SHIELD_MESSAGE_PANEL_DESTRUCTOR_SYMBOL: (
                HUD_UI_SHIELD_MESSAGE_PANEL_DESTRUCTOR_IDENTITY
            ),
            HUD_UI_SHIELD_MESSAGE_WIDGET_DESTRUCTOR_SYMBOL: (
                HUD_UI_SHIELD_MESSAGE_WIDGET_DESTRUCTOR_IDENTITY
            ),
        },
        local_control_flow_indices=destructor.local_control_flow_indices,
        local_control_flow_targets=destructor.local_control_flow_targets,
    )
    if (
        len(candidate_contract) != 2
        or compare_call_contracts(retail_contract, candidate_contract)[
            "passed"
        ]
        is not True
    ):
        raise ValueError(
            "HUD shield-message generated destructor bridge requires exact "
            "relocation-normalized candidate/retail call topology"
        )
    return True


def _prove_hud_ui_message_stack_generated_destructor_bridge(
    candidate_name: str,
    target_identity: str,
    *,
    expected: Sequence[Mapping[str, Any]],
    document: ProgressDocument,
    candidate: CandidateAssembly,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    invocation_row: Mapping[str, Any],
) -> bool:
    """Prove only the two reviewed implicit HUD message-stack destructors."""
    spec = HUD_UI_MESSAGE_STACK_DESTRUCTOR_BRIDGES.get(candidate_name)
    if spec is None:
        return False
    label = str(spec["label"])
    prefix = f"HUD {label} message-stack generated destructor bridge"
    target_address = str(spec["target_address"])
    target_end = str(spec["target_end_exclusive"])
    call_ordinal = int(spec["call_ordinal"])
    delete_ordinal = int(spec["delete_ordinal"])
    sequence_start = int(spec["caller_sequence_start"])
    sequence_end = sequence_start + 0x20
    destructor_relocation_offset = int(
        spec["caller_destructor_relocation_offset"]
    )
    delete_relocation_offset = int(spec["caller_delete_relocation_offset"])
    global_symbol = str(spec["global_symbol"])
    global_symbol_id = str(spec["global_symbol_id"])
    global_storage_id = str(spec["global_storage_id"])
    global_address = str(spec["global_address"])
    anchor_id = str(spec["anchor_id"])
    complete_type = str(spec["complete_type"])
    forbidden_core = str(spec["forbidden_core"])

    if (
        normalize_address(caller_start) != HUD_UI_MGR_SHUTDOWN_CALLER_START
        or caller_identity != HUD_UI_MGR_SHUTDOWN_CALLER_IDENTITY
        or normalize_address(caller_end_exclusive)
        != HUD_UI_MGR_SHUTDOWN_CALLER_END_EXCLUSIVE
    ):
        raise ValueError(
            f"{prefix} requires the exact reviewed ShutdownResources caller "
            "and extent"
        )
    if (
        target_identity != spec["target_identity"]
        or invocation_row.get("ordinal") != call_ordinal
        or invocation_row.get("form") != "call"
        or invocation_row.get("dispatch") != "direct"
        or invocation_row.get("cleanup_bytes") is not None
    ):
        raise ValueError(
            f"{prefix} requires the exact retail target, ordinal, direct-call "
            "form, and cleanup"
        )
    if len(expected) <= delete_ordinal:
        raise ValueError(f"{prefix} requires the adjacent global-delete call")
    delete_row = expected[delete_ordinal]
    delete_identity = str(delete_row.get("target_identity", ""))
    if (
        delete_row.get("ordinal") != delete_ordinal
        or delete_row.get("form") != "call"
        or delete_row.get("dispatch") != "direct"
        or delete_row.get("identity_kind") != "provider"
        or delete_identity not in indexes.provider_ids
        or delete_row.get("storage_identity") != ""
        or delete_row.get("slot_displacement") is not None
        or delete_row.get("cleanup_bytes") != 4
    ):
        raise ValueError(
            f"{prefix} requires the exact adjacent operator-delete call and "
            "four-byte caller cleanup"
        )

    target = candidate.target
    caller = candidate.caller_definition
    contribution_rows = [
        (entry, row)
        for entry in getattr(target, "translation_unit_function_order", ())
        for row in getattr(entry, "functions", ())
        if normalize_address(str(getattr(row, "address", "")))
        == HUD_UI_MGR_SHUTDOWN_CALLER_START
    ]
    if (
        caller is None
        or caller.symbol != HUD_UI_MGR_SHUTDOWN_CALLER_SYMBOL
        or len(caller.data)
        != address_value(HUD_UI_MGR_SHUTDOWN_CALLER_END_EXCLUSIVE)
        - address_value(HUD_UI_MGR_SHUTDOWN_CALLER_START)
        or len(caller.relocation_mask) != len(caller.data)
        or target is None
        or getattr(target, "name", "")
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_NAME
        or getattr(target, "target_binary", "") != "recoil"
        or Path(str(getattr(target, "manifest_path", ""))).resolve()
        != HUD_UI_MGR_INIT_LAYOUTS_TARGET_MANIFEST.resolve()
        or not bool(
            getattr(target, "check_translation_unit_function_order", False)
        )
        or tuple(getattr(target, "source_files", ())).count(
            HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        )
        != 1
        or len(contribution_rows) != 1
    ):
        raise ValueError(
            f"{prefix} requires one exact current HUD compile authority, "
            "caller definition, and contribution"
        )
    contribution, contribution_row = contribution_rows[0]
    if (
        getattr(contribution, "source_from", "")
        != HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH
        or getattr(contribution, "order_scope", "") != "authored"
        or getattr(contribution_row, "symbol", "") != ""
        or getattr(contribution_row, "symbol_regex", None)
        != r"\?ShutdownResources@HudUiMgr@@.*"
        or re.fullmatch(
            r"\?ShutdownResources@HudUiMgr@@.*",
            caller.symbol,
        )
        is None
        or getattr(contribution_row, "name", "")
        != "HudUiMgr::ShutdownResources"
        or getattr(contribution_row, "pipeline_class", "") != "authored"
        or getattr(contribution_row, "authored_order_role", "")
        != "authored-body"
        or not bool(getattr(contribution_row, "required_presence", False))
        or not bool(getattr(contribution_row, "full_order_gate", False))
    ):
        raise ValueError(
            f"{prefix} requires the exact authored ShutdownResources hud.cpp "
            "contribution identity"
        )

    target_symbol_id = target_identity.removeprefix("symbol:")
    target_symbol = document.collection("symbols").get(target_symbol_id)
    target_size = address_value(target_end) - address_value(target_address)
    target_addresses = sorted(
        address
        for address, identity in indexes.by_address.items()
        if identity == target_identity
    )
    if (
        target_addresses != [target_address]
        or not isinstance(target_symbol, Mapping)
        or _symbol_identity(target_symbol_id, target_symbol) != target_identity
        or target_symbol.get("binary") != "recoil"
        or target_symbol.get("kind") != "function"
        or target_symbol.get("pipeline_class") != "authored-lifecycle"
        or target_symbol.get("authored_order_role")
        != "compiler-generated-implicit-cleanup"
        or target_symbol.get("extent_state") != "known"
        or normalize_address(str(target_symbol.get("address", "")))
        != target_address
        or normalize_address(str(target_symbol.get("end_exclusive", "")))
        != target_end
        or target_symbol.get("size") != target_size
        or target_symbol.get("logical_identity_key") not in {None, ""}
        or target_symbol.get("icf_fold_status") not in {None, ""}
        or bool(target_symbol.get("logical_aliases"))
        or bool(target_symbol.get("icf_address_group"))
    ):
        raise ValueError(
            f"{prefix} requires one exact unaliased reviewed lifecycle target "
            "and extent"
        )

    trace = target_symbol.get("source_traceability")
    source_edges = trace.get("source_edges") if isinstance(trace, Mapping) else None
    if (
        not isinstance(trace, Mapping)
        or trace.get("state") != "resolved"
        or trace.get("reason_code") not in {None, ""}
        or not isinstance(source_edges, list)
        or len(source_edges) != 1
        or not isinstance(source_edges[0], Mapping)
        or source_edges[0].get("relation") != "emits"
        or source_edges[0].get("anchor_id") != anchor_id
        or source_edges[0].get("emission_context")
        != {"translation_unit": HUD_UI_MGR_INIT_LAYOUTS_SOURCE_PATH}
    ):
        raise ValueError(
            f"{prefix} requires one exact resolved emits source-trace edge"
        )
    trace_document = parse_source_trace_path(
        REPO_ROOT / HUD_UI_MESSAGE_STACK_SOURCE_PATH,
        repo_root=REPO_ROOT,
    )
    trace_anchors = [
        row for row in trace_document.anchors if row.anchor_id == anchor_id
    ]
    trace_artifacts = [
        row
        for row in trace_document.artifacts
        if row.artifact_id == target_symbol_id
    ]
    if (
        len(trace_anchors) != 1
        or len(trace_artifacts) != 1
        or trace_anchors[0].construct is None
        or trace_anchors[0].construct.kind != "type"
        or trace_anchors[0].construct.name != complete_type
        or trace_anchors[0].comment_style != "doxygen"
        or trace_anchors[0].attachment_status != "attached"
        or trace_artifacts[0].anchor_id != anchor_id
        or trace_artifacts[0].relation != "emits"
        or trace_artifacts[0].section != ".text"
        or not trace_artifacts[0].direct
        or trace_artifacts[0].construct is None
        or trace_artifacts[0].construct.kind != "type"
        or trace_artifacts[0].construct.name != complete_type
        or any(
            finding.anchor_id == anchor_id
            or finding.artifact_id == target_symbol_id
            for finding in trace_document.findings
        )
    ):
        raise ValueError(
            f"{prefix} requires one matching attached complete-type anchor"
        )

    global_row = document.collection("symbols").get(global_symbol_id)
    storage_row = document.collection("storage_contributions").get(
        global_storage_id
    )
    if (
        not isinstance(global_row, Mapping)
        or global_row.get("binary") != "recoil"
        or global_row.get("kind") != "data"
        or normalize_address(str(global_row.get("address", "")))
        != global_address
        or global_row.get("navigation_name")
        != spec["global_navigation_name"]
        or global_row.get("output_section_id") != "recoil:section:.data"
        or global_row.get("storage_contribution_ids") != [global_storage_id]
        or not isinstance(storage_row, Mapping)
        or storage_row.get("binary") != "recoil"
        or storage_row.get("kind") != "data-symbol"
        or storage_row.get("output_section_id") != "recoil:section:.data"
        or storage_row.get("overlap") != "none"
        or storage_row.get("symbol_ids") != [global_symbol_id]
        or not isinstance(storage_row.get("reference"), Mapping)
        or normalize_address(
            str(storage_row["reference"].get("address", ""))
        )
        != global_address
        or indexes.storage_by_address.get(global_address)
        != f"storage:{global_symbol_id}"
    ):
        raise ValueError(
            f"{prefix} requires the exact typed global storage identity"
        )

    all_function_symbols = {
        *caller.undefined_external_functions,
        *caller.defined_external_functions,
        *candidate.complete_destructor_definitions.keys(),
    }
    if (
        forbidden_core in all_function_symbols
        or any(
            forbidden_core in relocation.symbol_name
            for definition in candidate.complete_destructor_definitions.values()
            for relocation in definition.relocations
        )
        or any(
            forbidden_core in relocation.symbol_name
            for definition in candidate.complete_destructor_definitions.values()
            for section in definition.associated_sections
            for relocation in section.relocations
        )
        or any(
            forbidden_core in _instruction_operand(instruction)
            for instruction in candidate.instructions
        )
    ):
        raise ValueError(
            f"{prefix} rejects the fake authored DestructorCore identity"
        )
    if (
        caller.undefined_external_functions.count(candidate_name) != 0
        or caller.defined_external_functions.count(candidate_name) != 1
        or caller.undefined_external_functions.count(
            HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        )
        != 1
        or caller.defined_external_functions.count(
            HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        )
        != 0
        or caller.undefined_external_data.count(global_symbol) != 1
        or global_symbol in caller.defined_external_data
    ):
        raise ValueError(
            f"{prefix} requires one same-object destructor, one external "
            "operator delete, and one external typed global"
        )

    expected_caller_sequence = bytes.fromhex(
        "8b 35 00 00 00 00 3b f7 74 16 8b ce "
        "e8 00 00 00 00 56 e8 00 00 00 00 83 c4 04 "
        "89 3d 00 00 00 00"
    )
    if caller.data[sequence_start:sequence_end] != expected_caller_sequence:
        raise ValueError(
            f"{prefix} requires the exact bounded global "
            "load/test/destruct/delete/cleanup/clear body"
        )
    caller_relocation_specs = (
        (sequence_start + 2, IMAGE_REL_I386_DIR32, global_symbol),
        (
            destructor_relocation_offset,
            IMAGE_REL_I386_REL32,
            candidate_name,
        ),
        (
            delete_relocation_offset,
            IMAGE_REL_I386_REL32,
            HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL,
        ),
        (sequence_end - 4, IMAGE_REL_I386_DIR32, global_symbol),
    )
    bounded_relocations = tuple(
        row
        for row in caller.relocations
        if sequence_start <= row.offset < sequence_end
    )
    expected_caller_mask: set[int] = set()
    if len(bounded_relocations) != len(caller_relocation_specs):
        raise ValueError(
            f"{prefix} rejects missing, duplicate, or extra caller relocations"
        )
    for relocation, (offset, relocation_type, symbol_name) in zip(
        bounded_relocations,
        caller_relocation_specs,
    ):
        if (
            relocation.offset != offset
            or relocation.type != relocation_type
            or relocation.symbol_name != symbol_name
            or struct.unpack_from("<I", caller.data, offset)[0] != 0
        ):
            raise ValueError(
                f"{prefix} rejects wrong caller relocation offset, type, "
                "target, or addend"
            )
        expected_caller_mask.update(range(offset, offset + 4))
    if {
        index
        for index in range(sequence_start, sequence_end)
        if caller.relocation_mask[index]
    } != expected_caller_mask:
        raise ValueError(f"{prefix} requires an exact caller relocation mask")

    instruction_offsets = [
        (
            address_value(address)
            if (address := _source_instruction_address(instruction))
            else None
        )
        for instruction in candidate.instructions
    ]
    offset_counts: dict[int, int] = {}
    for offset in instruction_offsets:
        if offset is not None:
            offset_counts[offset] = offset_counts.get(offset, 0) + 1
    index_by_offset = {
        offset: index
        for index, offset in enumerate(instruction_offsets)
        if offset is not None and offset_counts.get(offset) == 1
    }
    destructor_index = index_by_offset.get(destructor_relocation_offset - 1)
    delete_index = index_by_offset.get(delete_relocation_offset - 1)
    ordinal_by_index = {
        index: ordinal
        for ordinal, index in enumerate(
            _candidate_static_invocation_indices(
                candidate,
                caller_start=caller_start,
                caller_end_exclusive=caller_end_exclusive,
            )
        )
    }
    if (
        destructor_index is None
        or delete_index is None
        or ordinal_by_index.get(destructor_index) != call_ordinal
        or ordinal_by_index.get(delete_index) != delete_ordinal
        or destructor_index in candidate.local_control_flow_indices
        or delete_index in candidate.local_control_flow_indices
        or _instruction_mnemonic(candidate.instructions[destructor_index])
        != "call"
        or _instruction_operand(
            candidate.instructions[destructor_index]
        ).strip()
        != candidate_name
        or _cleanup_after(candidate.instructions, destructor_index) is not None
        or _instruction_mnemonic(candidate.instructions[delete_index])
        != "call"
        or _instruction_operand(candidate.instructions[delete_index]).strip()
        != HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL
        or _cleanup_after(candidate.instructions, delete_index) != 4
    ):
        raise ValueError(
            f"{prefix} rejects wrong caller ordinal, opcode offset, call "
            "target, local-flow status, or cleanup"
        )

    delete_name_rows = bridge_names.get(
        HUD_UI_STRING_MENU_GLOBAL_DELETE_SYMBOL,
        (),
    )
    delete_name_rows = (
        list(delete_name_rows)
        if isinstance(delete_name_rows, (list, tuple, set, frozenset))
        else [delete_name_rows]
    )
    if (
        len(delete_name_rows) != 1
        or normalize_address(
            str(getattr(delete_name_rows[0], "address", ""))
        )
        != HUD_UI_STRING_MENU_GLOBAL_DELETE_ADDRESS
        or indexes.by_address.get(HUD_UI_STRING_MENU_GLOBAL_DELETE_ADDRESS)
        != delete_identity
    ):
        raise ValueError(
            f"{prefix} requires one exact retail operator-delete provider"
        )

    destructor = candidate.complete_destructor_definitions.get(candidate_name)
    if (
        destructor is None
        or not destructor.section_is_comdat
        or destructor.comdat_selection != 2
        or destructor.section_external_functions != (candidate_name,)
        or destructor.section_size != target_size
        or len(destructor.data) != target_size
        or len(destructor.relocation_mask) != target_size
    ):
        raise ValueError(
            f"{prefix} requires one exact 0x60 VC5 SELECT_ANY COMDAT body"
        )
    relocation_specs: tuple[
        tuple[int, int, str | re.Pattern[str]], ...
    ] = (
        (0x02, IMAGE_REL_I386_DIR32, "__except_list"),
        (0x09, IMAGE_REL_I386_DIR32, re.compile(r"\$L[0-9]+")),
        (0x11, IMAGE_REL_I386_DIR32, "__except_list"),
        (
            0x19,
            IMAGE_REL_I386_DIR32,
            HUD_UI_MESSAGE_STACK_PANEL_DESTRUCTOR_SYMBOL,
        ),
        (0x31, IMAGE_REL_I386_REL32, MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL),
        (
            0x40,
            IMAGE_REL_I386_REL32,
            HUD_UI_MESSAGE_STACK_CONTAINER_DESTRUCTOR_SYMBOL,
        ),
        (0x4C, IMAGE_REL_I386_DIR32, "__except_list"),
    )
    if len(destructor.relocations) != len(relocation_specs):
        raise ValueError(
            f"{prefix} rejects missing, duplicate, or extra body relocations"
        )
    expected_definition_mask: set[int] = set()
    for relocation, (offset, relocation_type, symbol_spec) in zip(
        destructor.relocations,
        relocation_specs,
    ):
        symbol_matches = (
            symbol_spec.fullmatch(relocation.symbol_name) is not None
            if isinstance(symbol_spec, re.Pattern)
            else relocation.symbol_name == symbol_spec
        )
        if (
            relocation.offset != offset
            or relocation.type != relocation_type
            or not symbol_matches
            or struct.unpack_from("<I", destructor.data, offset)[0] != 0
        ):
            raise ValueError(
                f"{prefix} rejects wrong body relocation offset, type, "
                "target, or addend"
            )
        expected_definition_mask.update(range(offset, offset + 4))
    if {
        index
        for index, masked in enumerate(destructor.relocation_mask)
        if masked
    } != expected_definition_mask:
        raise ValueError(f"{prefix} requires an exact body relocation mask")
    if (
        destructor.data[0x1D:0x1F]
        != bytes((0x6A, HUD_UI_MESSAGE_STACK_ELEMENT_COUNT))
        or destructor.data[0x1F:0x22]
        != bytes((0x8D, 0x46, HUD_UI_MESSAGE_STACK_ELEMENT_OFFSET))
        or destructor.data[0x22] != 0x68
        or struct.unpack_from("<I", destructor.data, 0x23)[0]
        != HUD_UI_MESSAGE_STACK_ELEMENT_STRIDE
    ):
        raise ValueError(
            f"{prefix} requires four exact HudUiPanel elements at this+0x10 "
            "with stride 0x2a4"
        )
    if (
        indexes.by_address.get(
            HUD_UI_MESSAGE_STACK_PANEL_DESTRUCTOR_ADDRESS
        )
        != HUD_UI_MESSAGE_STACK_PANEL_DESTRUCTOR_IDENTITY
        or indexes.by_address.get(
            HUD_UI_MESSAGE_STACK_CONTAINER_DESTRUCTOR_ADDRESS
        )
        != HUD_UI_MESSAGE_STACK_CONTAINER_DESTRUCTOR_IDENTITY
        or indexes.by_address.get(HUD_UI_MESSAGE_STACK_FRAME_HANDLER_ADDRESS)
        not in indexes.provider_ids
    ):
        raise ValueError(
            f"{prefix} requires the exact panel, container, and frame-handler "
            "identities"
        )

    retail_body = _hexdump_bytes(bridge.hexdump(target_address, target_size))
    if (
        len(retail_body) != target_size
        or struct.unpack_from("<I", retail_body, 0x19)[0]
        != address_value(HUD_UI_MESSAGE_STACK_PANEL_DESTRUCTOR_ADDRESS)
        or any(
            candidate_byte != retail_byte
            for index, (candidate_byte, retail_byte) in enumerate(
                zip(destructor.data, retail_body)
            )
            if not destructor.relocation_mask[index]
        )
    ):
        raise ValueError(
            f"{prefix} requires exact relocation-normalized retail body bytes"
        )

    runtime_associations = tuple(
        section
        for section in destructor.associated_sections
        if section.name.startswith(".text")
        or section.name.startswith(".xdata")
    )
    if (
        len(runtime_associations) != 2
        or sorted(section.name for section in runtime_associations)
        != [".text$x", ".xdata$x"]
        or any(
            not section.section_is_comdat
            or section.comdat_selection != 5
            or section.association_section_index <= 0
            or section.section_external_symbols
            for section in runtime_associations
        )
    ):
        raise ValueError(
            f"{prefix} requires exact associative .text$x/.xdata$x topology"
        )
    funclet = next(
        section for section in runtime_associations if section.name == ".text$x"
    )
    xdata = next(
        section for section in runtime_associations if section.name == ".xdata$x"
    )
    if (
        funclet.association_section_index != xdata.association_section_index
        or funclet.section_size != 0x12
        or len(funclet.data) != 0x12
        or xdata.section_size != 0x28
        or len(xdata.data) != 0x28
        or funclet.data
        != bytes.fromhex(
            "8b 4d f0 e9 00 00 00 00 b8 00 00 00 00 "
            "e9 00 00 00 00"
        )
        or xdata.data
        != bytes.fromhex(
            "20 05 93 19 01 00 00 00 00 00 00 00 "
            "00 00 00 00 00 00 00 00 00 00 00 00 "
            "00 00 00 00 00 00 00 00 ff ff ff ff 00 00 00 00"
        )
    ):
        raise ValueError(
            f"{prefix} requires exact associative funclet/xdata body shape"
        )

    association_specs = (
        (
            funclet,
            (
                (
                    0x04,
                    IMAGE_REL_I386_REL32,
                    HUD_UI_MESSAGE_STACK_CONTAINER_DESTRUCTOR_SYMBOL,
                ),
                (0x09, IMAGE_REL_I386_DIR32, re.compile(r"\$T[0-9]+")),
                (
                    0x0E,
                    IMAGE_REL_I386_REL32,
                    HUD_UI_MESSAGE_STACK_FRAME_HANDLER_SYMBOL,
                ),
            ),
        ),
        (
            xdata,
            (
                (0x08, IMAGE_REL_I386_DIR32, re.compile(r"\$T[0-9]+")),
                (0x24, IMAGE_REL_I386_DIR32, re.compile(r"\$L[0-9]+")),
            ),
        ),
    )
    for section, specs in association_specs:
        expected_mask: set[int] = set()
        if len(section.relocations) != len(specs):
            raise ValueError(
                f"{prefix} rejects missing, duplicate, or extra "
                f"{section.name} relocations"
            )
        for relocation, (offset, relocation_type, symbol_spec) in zip(
            section.relocations,
            specs,
        ):
            symbol_matches = (
                symbol_spec.fullmatch(relocation.symbol_name) is not None
                if isinstance(symbol_spec, re.Pattern)
                else relocation.symbol_name == symbol_spec
            )
            if (
                relocation.offset != offset
                or relocation.type != relocation_type
                or not symbol_matches
                or struct.unpack_from("<I", section.data, offset)[0] != 0
            ):
                raise ValueError(
                    f"{prefix} rejects wrong {section.name} relocation "
                    "offset, type, target, or addend"
                )
            expected_mask.update(range(offset, offset + 4))
        if {
            index
            for index, masked in enumerate(section.relocation_mask)
            if masked
        } != expected_mask:
            raise ValueError(
                f"{prefix} requires an exact {section.name} relocation mask"
            )
    funclet_labels = {
        symbol.value: symbol.name
        for symbol in funclet.symbols
        if symbol.storage_class == 6
        and symbol.type == 0
        and re.fullmatch(r"\$L[0-9]+", symbol.name)
    }
    xdata_labels = {
        symbol.value: symbol.name
        for symbol in xdata.symbols
        if symbol.storage_class == 3
        and symbol.type == 0
        and re.fullmatch(r"\$T[0-9]+", symbol.name)
    }
    if (
        set(funclet_labels) != {0, 8}
        or set(xdata_labels) != {0, 0x20}
        or destructor.relocations[1].symbol_name != funclet_labels[8]
        or funclet.relocations[1].symbol_name != xdata_labels[0]
        or xdata.relocations[0].symbol_name != xdata_labels[0x20]
        or xdata.relocations[1].symbol_name != funclet_labels[0]
    ):
        raise ValueError(
            f"{prefix} requires exact main/funclet/xdata local-symbol linkage"
        )

    funclet_address = (
        struct.unpack_from("<I", retail_body, 0x09)[0] - 8
    )
    retail_funclet = _hexdump_bytes(
        bridge.hexdump(hex(funclet_address), funclet.section_size)
    )
    if len(retail_funclet) != funclet.section_size:
        raise ValueError(f"{prefix} retail funclet extent is incomplete")
    xdata_address = struct.unpack_from("<I", retail_funclet, 0x09)[0]
    retail_xdata = _hexdump_bytes(
        bridge.hexdump(hex(xdata_address), xdata.section_size)
    )
    if (
        len(retail_xdata) != xdata.section_size
        or struct.unpack_from("<I", retail_xdata, 0x08)[0]
        != xdata_address + 0x20
        or struct.unpack_from("<I", retail_xdata, 0x24)[0]
        != funclet_address
        or any(
            candidate_byte != retail_byte
            for index, (candidate_byte, retail_byte) in enumerate(
                zip(funclet.data, retail_funclet)
            )
            if not funclet.relocation_mask[index]
        )
        or any(
            candidate_byte != retail_byte
            for index, (candidate_byte, retail_byte) in enumerate(
                zip(xdata.data, retail_xdata)
            )
            if not xdata.relocation_mask[index]
        )
    ):
        raise ValueError(
            f"{prefix} requires exact relocation-normalized retail "
            "funclet/xdata topology"
        )
    funclet_container_target = (
        funclet_address
        + 0x08
        + struct.unpack_from("<i", retail_funclet, 0x04)[0]
    )
    funclet_handler_target = (
        funclet_address
        + 0x12
        + struct.unpack_from("<i", retail_funclet, 0x0E)[0]
    )
    if (
        funclet_container_target
        != address_value(HUD_UI_MESSAGE_STACK_CONTAINER_DESTRUCTOR_ADDRESS)
        or funclet_handler_target
        != address_value(HUD_UI_MESSAGE_STACK_FRAME_HANDLER_ADDRESS)
    ):
        raise ValueError(
            f"{prefix} requires the exact container unwind tail and frame "
            "handler"
        )

    retail_contract = extract_invocation_contract(
        parse_assembly(bridge.assembly(target_address), source="bn"),
        source="bn",
        caller_identity=target_identity,
        caller_start=target_address,
        caller_end_exclusive=target_end,
        # This is the separately reviewed compiler-generated destructor body,
        # not an instruction subset of the ShutdownResources caller whose
        # package is active while candidate bridges are resolved.  Keep the
        # extractor's foreign-row rejection intact and explicitly start a
        # child-body extraction context only after the exact lifecycle
        # identity, extent, retail bytes, COFF body, and EH topology above have
        # all been proved.  Caller-local IAT transfer facts cannot cross this
        # physical-body boundary.
        indexes=_without_caller_scoped_retail_proofs(indexes),
        bridge_names=bridge_names,
    )
    if (
        len(retail_contract) != 2
        or retail_contract[0].get("ordinal") != 0
        or retail_contract[0].get("form") != "call"
        or retail_contract[0].get("dispatch") != "direct"
        or retail_contract[0].get("identity_kind") != "provider"
        or retail_contract[0].get("target_identity")
        not in indexes.provider_ids
        or retail_contract[0].get("cleanup_bytes") is not None
        or retail_contract[1]
        != {
            "ordinal": 1,
            "form": "call",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": (
                HUD_UI_MESSAGE_STACK_CONTAINER_DESTRUCTOR_IDENTITY
            ),
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        }
    ):
        raise ValueError(
            f"{prefix} requires exact EH-vector then container retail calls"
        )
    candidate_contract = extract_invocation_contract(
        destructor.instructions,
        source="cod",
        caller_identity=target_identity,
        caller_start=target_address,
        caller_end_exclusive=target_end,
        indexes=indexes,
        bridge_names=bridge_names,
        compiler_generated_bridges={
            MSVC_EH_ARRAY_DESTRUCTOR_SYMBOL: str(
                retail_contract[0]["target_identity"]
            ),
            HUD_UI_MESSAGE_STACK_CONTAINER_DESTRUCTOR_SYMBOL: (
                HUD_UI_MESSAGE_STACK_CONTAINER_DESTRUCTOR_IDENTITY
            ),
        },
        local_control_flow_indices=destructor.local_control_flow_indices,
        local_control_flow_targets=destructor.local_control_flow_targets,
    )
    if (
        len(candidate_contract) != 2
        or compare_call_contracts(retail_contract, candidate_contract)[
            "passed"
        ]
        is not True
    ):
        raise ValueError(
            f"{prefix} requires exact relocation-normalized candidate/retail "
            "call topology"
        )
    return True


def _prove_compiler_destructor_authored_bridge(
    candidate_name: str,
    target_identity: str,
    *,
    document: ProgressDocument,
    candidate: CandidateAssembly,
    indexes: IdentityIndexes,
    invocation_row: Mapping[str, Any],
    zsnd_wave_data_ordinary_body_proven: bool = False,
) -> None:
    target_names = _complete_destructor_authored_target_names(candidate_name)
    if not target_names:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} has no exact "
            "simple VC5 class/destructor identity"
        )
    if zsnd_wave_data_ordinary_body_proven:
        if (
            candidate_name != ZSND_WAVE_DATA_DESTRUCTOR_CANDIDATE_SYMBOL
            or target_names
            != (
                ZSND_WAVE_DATA_DESTRUCTOR_CORE_SYMBOL,
                ZSND_WAVE_DATA_DESTRUCTOR_CORE_NAVIGATION_NAME,
            )
        ):
            raise ValueError(
                "zSnd wave-data destructor finite bridge rejects a nonexact "
                "compiler destructor/DestructorCore identity"
            )
        target_names = (
            ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_SYMBOL,
            ZSND_WAVE_DATA_ORDINARY_DESTRUCTOR_NAVIGATION_NAME,
        )
    elif candidate_name == ZSND_WAVE_DATA_DESTRUCTOR_CANDIDATE_SYMBOL:
        raise ValueError(
            "zSnd wave-data destructor requires its finite ordinary-body proof"
        )
    target_symbol, navigation_name = target_names
    if target_identity.startswith("provider:") or not target_identity.startswith(
        "symbol:"
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} target "
            f"{target_identity!r} is not one authored function identity"
        )
    target_addresses = sorted(
        address
        for address, identity in indexes.by_address.items()
        if identity == target_identity
    )
    if len(target_addresses) != 1:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} authored identity "
            f"{target_identity!r} must resolve to one retail address"
        )
    target_address = target_addresses[0]
    if indexes.by_candidate_name.get(target_symbol) != target_identity:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} exact ordinary "
            f"DestructorCore symbol {target_symbol!r} does not resolve to "
            f"{target_identity!r}"
        )

    symbol_id = target_identity.removeprefix("symbol:")
    symbol = document.collection("symbols").get(symbol_id)
    if (
        not isinstance(symbol, Mapping)
        or _symbol_identity(symbol_id, symbol) != target_identity
        or symbol.get("binary") != "recoil"
        or symbol.get("kind") != "function"
        or symbol.get("pipeline_class") != "authored"
        or symbol.get("extent_state") != "known"
        or symbol.get("navigation_name") != navigation_name
        or normalize_address(
            str(symbol.get("address", symbol.get("start", "")))
        )
        != target_address
        or indexes.by_address.get(target_address) != target_identity
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} target "
            f"{target_identity!r} lacks one exact reviewed authored "
            "DestructorCore tracker function"
        )
    target_end = normalize_address(str(symbol.get("end_exclusive", "")))
    target_size = address_value(target_end) - address_value(target_address)
    logical_aliases = symbol.get("logical_aliases")
    icf_group = symbol.get("icf_address_group")
    if (
        target_size <= 0
        or symbol.get("size") != target_size
        or symbol.get("logical_identity_key") not in {None, ""}
        or symbol.get("icf_fold_status") not in {None, ""}
        or isinstance(logical_aliases, Mapping)
        and bool(logical_aliases)
        or isinstance(icf_group, Mapping)
        and bool(icf_group)
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} authored target "
            f"{target_address} lacks one exact unaliased known extent"
        )

    verification_target_ids = symbol.get("verification_target_ids")
    if (
        not isinstance(verification_target_ids, list)
        or not verification_target_ids
        or any(
            not isinstance(target_id, str) or not target_id
            for target_id in verification_target_ids
        )
        or len(set(verification_target_ids)) != len(verification_target_ids)
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} authored target "
            f"{target_address} has missing or duplicate verification authority"
        )
    reviewed_verification_target_ids = (
        (ZSND_WAVE_DATA_DESTRUCTOR_ORDER_TARGET_ID,)
        if zsnd_wave_data_ordinary_body_proven
        else tuple(verification_target_ids)
    )
    qualifying_target_ids: set[str] = set()
    for target_id in reviewed_verification_target_ids:
        target = document.collection("verification_targets").get(target_id)
        if not isinstance(target, Mapping):
            continue
        selected_rows: list[Mapping[str, Any]] = []
        for row in _mapping_target_function_rows(target):
            raw_address = row.get("address")
            if not isinstance(raw_address, str):
                continue
            try:
                row_address = normalize_address(raw_address)
            except ProgressError:
                continue
            if row_address != target_address or (
                row.get("symbol") is None
                and row.get("symbol_regex") is None
            ):
                continue
            selected_rows.append(row)
        if not selected_rows:
            continue
        if any(
            row.get("symbol") != target_symbol
            or row.get("symbol_regex") not in {None, ""}
            or row.get("name") != navigation_name
            or row.get("pipeline_class") != "authored-lifecycle"
            or row.get("authored_order_role")
            != "authored-lifecycle-body"
            or row.get("authored_order_gate") is not True
            or row.get("authored_relative_order_gate") is not True
            or row.get("required_presence") is not True
            or row.get("full_order_gate") is not True
            or row.get("logical_identity_key") not in {None, ""}
            or row.get("icf_fold_status") not in {None, ""}
            for row in selected_rows
        ):
            raise ValueError(
                f"compiler destructor bridge {candidate_name!r} authored target "
                f"{target_address} has a conflicting selected destructor row"
            )
        qualifying_target_ids.add(target_id)
    if len(qualifying_target_ids) != 1:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} authored target "
            f"{target_address} must have one exact selected destructor authority"
        )

    caller = candidate.caller_definition
    exact_caller_symbol_counts = (
        (0, 1) if zsnd_wave_data_ordinary_body_proven else (1, 0)
    )
    if (
        caller is None
        or caller.undefined_external_functions.count(candidate_name)
        != exact_caller_symbol_counts[0]
        or caller.defined_external_functions.count(candidate_name)
        != exact_caller_symbol_counts[1]
    ):
        if not zsnd_wave_data_ordinary_body_proven:
            raise ValueError(
                f"compiler destructor bridge {candidate_name!r} requires "
                "exactly one undefined and no defined caller-object function "
                "symbol"
            )
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} requires its "
            "exact reviewed same-object defined compiler-destructor symbol"
        )
    references = tuple(
        relocation
        for relocation in caller.relocations
        if relocation.symbol_name == candidate_name
    )
    if len(references) != 1:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} requires exactly "
            "one caller-object relocation"
        )
    reference = references[0]
    if reference.type != IMAGE_REL_I386_REL32:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} caller-object "
            "relocation is not REL32"
        )
    if (
        len(caller.relocation_mask) != len(caller.data)
        or reference.offset < 1
        or reference.offset + 4 > len(caller.data)
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} caller-object "
            "REL32 relocation is out of range"
        )
    if not all(
        caller.relocation_mask[index]
        for index in range(reference.offset, reference.offset + 4)
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} caller-object "
            "REL32 relocation is not fully masked"
        )
    if struct.unpack_from("<I", caller.data, reference.offset)[0] != 0:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} caller-object "
            "REL32 relocation has a nonzero addend"
        )
    expected_opcode = {
        "call": 0xE8,
        "tail": 0xE9,
    }.get(str(invocation_row.get("form", "")))
    expected_mnemonic = {
        "call": "call",
        "tail": "jmp",
    }.get(str(invocation_row.get("form", "")))
    if (
        invocation_row.get("dispatch") != "direct"
        or expected_opcode is None
        or expected_mnemonic is None
        or caller.data[reference.offset - 1] != expected_opcode
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} caller-object "
            "opcode does not match its exact direct invocation form"
        )
    listing_matches: list[tuple[int, Instruction]] = []
    for index, instruction in enumerate(candidate.instructions):
        operand = _instruction_operand(instruction).strip()
        match = DECORATED_RE.search(operand)
        if match is not None and match.group(0) == candidate_name:
            listing_matches.append((index, instruction))
    if len(listing_matches) != 1:
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} requires one exact "
            "candidate-name COD invocation instruction"
        )
    listing_index, listing_instruction = listing_matches[0]
    listing_operand = _instruction_operand(listing_instruction).strip()
    listing_bytes = tuple(
        value.lower() for value in listing_instruction.bytes
    )
    if (
        listing_index in candidate.local_control_flow_indices
        or listing_operand != candidate_name
        or _instruction_mnemonic(listing_instruction) != expected_mnemonic
        or not listing_bytes
        or listing_bytes[0] != f"{expected_opcode:02x}"
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} COD instruction "
            "is not the exact nonlocal direct invocation form"
        )
    listing_address = _source_instruction_address(listing_instruction)
    if (
        not listing_address
        or address_value(listing_address) != reference.offset - 1
    ):
        raise ValueError(
            f"compiler destructor bridge {candidate_name!r} COD invocation "
            "offset does not match its caller-object REL32 relocation"
        )


def _prove_player_hud_ui_element_generated_destructor_bridge(
    candidate_name: str,
    target_identity: str,
    *,
    document: ProgressDocument,
    candidate: CandidateAssembly,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    invocation_row: Mapping[str, Any],
) -> bool:
    """Prove two exact Player inline HudUiElement vftable-reset destructors."""

    if candidate_name != "??1HudUiElement@@UAE@XZ":
        return False
    profiles = {
        (
            "symbol:recoil:function:0x41eb20",
            "0x41eb20",
            "0x41eb30",
        ): (
            "?ResetUnderwaterFxPass3UiSingleton@Player@@YAXXZ",
            "_g_Player_UnderwaterFxPass3Ui",
        ),
        (
            "symbol:recoil:function:0x41eb80",
            "0x41eb80",
            "0x41eb90",
        ): (
            "?ResetProjectileCameraFxPass3UiSingleton@Player@@YAXXZ",
            "_g_Player_State7FxPass3Ui",
        ),
    }
    profile = profiles.get(
        (
            caller_identity,
            normalize_address(caller_start),
            normalize_address(caller_end_exclusive),
        )
    )
    if profile is None:
        return False
    prefix = "Player HudUiElement generated-destructor bridge"
    caller_symbol, storage_symbol = profile
    target_symbol_id = "recoil:function:0x4b47a0"
    expected_target = f"symbol:{target_symbol_id}"
    target = document.collection("symbols").get(target_symbol_id)
    if (
        target_identity != expected_target
        or indexes.by_address.get("0x4b47a0") != expected_target
        or expected_target in indexes.provider_ids
        or not isinstance(target, Mapping)
        or _symbol_identity(target_symbol_id, target) != expected_target
        or target.get("binary") != "recoil"
        or target.get("kind") != "function"
        or target.get("address") != "0x4b47a0"
        or target.get("end_exclusive") != "0x4b47b0"
        or target.get("size") != 0x10
        or target.get("extent_state") != "known"
        or target.get("pipeline_class") != "authored-lifecycle"
        or target.get("authored_order_role")
        != "compiler-generated-implicit-cleanup"
        or target.get("ownership_state") != "primary-owned"
        or target.get("navigation_name")
        != "HudUiElement::ResetCommonFTable"
        or target.get("verification_target_ids")
        != [
            "recoil:functional-target:hud_ui_element_destructor",
            "recoil:vc5-target:hud_ui_element_destructor",
        ]
        or invocation_row
        != {
            "ordinal": 0,
            "form": "tail",
            "dispatch": "direct",
            "identity_kind": "direct",
            "target_identity": (
                "compiler-candidate-destructor:" + candidate_name
            ),
            "storage_identity": "",
            "slot_displacement": None,
            "cleanup_bytes": None,
        }
    ):
        raise ValueError(
            f"{prefix} rejects immutable target or invocation authority drift"
        )

    caller = candidate.caller_definition
    definition = candidate.complete_destructor_definitions.get(candidate_name)
    caller_relocations = (
        sorted(caller.relocations, key=lambda row: row.offset)
        if caller is not None else []
    )
    destructor_relocation = (
        definition.relocations[0]
        if definition is not None and len(definition.relocations) == 1
        else None
    )
    associated = (
        definition.associated_sections[0]
        if definition is not None
        and len(definition.associated_sections) == 1
        else None
    )
    associated_relocation = (
        associated.relocations[0]
        if associated is not None and len(associated.relocations) == 1
        else None
    )
    if (
        caller is None
        or caller.symbol != caller_symbol
        or caller.data
        != b"\xb9\x00\x00\x00\x00\xe9\x00\x00\x00\x00"
        + b"\x90" * 6
        or caller.relocation_mask
        != (False, True, True, True, True, False, True, True, True, True)
        + (False,) * 6
        or caller.undefined_external_functions.count(candidate_name) != 0
        or caller.defined_external_functions.count(candidate_name) != 1
        or len(caller_relocations) != 2
        or caller_relocations[0].offset != 1
        or caller_relocations[0].type != IMAGE_REL_I386_DIR32
        or caller_relocations[0].symbol_name != storage_symbol
        or caller_relocations[1].offset != 6
        or caller_relocations[1].type != IMAGE_REL_I386_REL32
        or caller_relocations[1].symbol_name != candidate_name
        or caller_relocations[0].symbol_index
        == caller_relocations[1].symbol_index
        or definition is None
        or definition.symbol != candidate_name
        or not definition.section_is_comdat
        or definition.comdat_selection != 2
        or definition.section_external_functions != (candidate_name,)
        or definition.section_size != 0x10
        or definition.data
        != b"\xc7\x01\x00\x00\x00\x00\xc3" + b"\x90" * 9
        or definition.relocation_mask
        != (False, False, True, True, True, True, False) + (False,) * 9
        or definition.local_control_flow_indices != frozenset()
        or bool(definition.local_control_flow_targets)
        or len(definition.instructions) != 2
        or _instruction_mnemonic(definition.instructions[0]) != "mov"
        or _instruction_operand(definition.instructions[0]).strip()
        != "dword [ecx], OFFSET FLAT:??_7HudUiElement@@6B@"
        or tuple(value.lower() for value in definition.instructions[0].bytes)
        != ("c7", "01", "00", "00", "00", "00")
        or not _exact_return_terminates(definition.instructions[1])
        or destructor_relocation is None
        or destructor_relocation.offset != 2
        or destructor_relocation.type != IMAGE_REL_I386_DIR32
        or destructor_relocation.symbol_name != "??_7HudUiElement@@6B@"
        or associated is None
        or associated.name != ".debug$F"
        or associated.data
        != b"\x00\x00\x00\x00\x07" + b"\x00" * 11
        or associated.relocation_mask
        != (True, True, True, True) + (False,) * 12
        or associated.section_size != 0x10
        or not associated.section_is_comdat
        or associated.comdat_selection != 5
        or associated.section_external_symbols != ()
        or associated.symbols != ()
        or associated_relocation is None
        or associated_relocation.offset != 0
        or associated_relocation.type != 0x07
        or associated_relocation.symbol_name != candidate_name
    ):
        raise ValueError(
            f"{prefix} requires the exact caller and SELECT_ANY vftable-reset "
            "COD/COFF packages"
        )
    return True


def _candidate_static_invocation_indices(
    candidate: CandidateAssembly,
    *,
    caller_start: str,
    caller_end_exclusive: str,
) -> tuple[int, ...]:
    """Count invocation sites without assigning unrelated indirect provenance."""
    start = address_value(caller_start)
    end = address_value(caller_end_exclusive)
    instructions = candidate.instructions
    instruction_addresses = _instruction_runtime_addresses(
        instructions,
        source="cod",
        caller_start=start,
    )
    address_counts: dict[int, int] = {}
    for address in instruction_addresses:
        if address is not None and start <= address < end:
            address_counts[address] = address_counts.get(address, 0) + 1
    instruction_index_by_address = {
        address: index
        for index, address in enumerate(instruction_addresses)
        if (
            address is not None
            and start <= address < end
            and address_counts.get(address) == 1
        )
    }
    result: list[int] = []
    for index, instruction in enumerate(instructions):
        mnemonic = _instruction_mnemonic(instruction)
        if mnemonic == "call":
            result.append(index)
            continue
        if mnemonic != "jmp" or index in candidate.local_control_flow_indices:
            continue
        exact_branch = _exact_local_direct_branch(
            instruction,
            instruction_index=index,
            instruction_addresses=instruction_addresses,
            instruction_index_by_address=instruction_index_by_address,
            source="cod",
            caller_start=start,
            caller_end=end,
        )
        if exact_branch is not None:
            continue
        operand = _instruction_operand(instruction)
        address_matches = ADDRESS_RE.findall(operand)
        if (
            address_matches
            and start <= address_value(address_matches[-1]) < end
        ):
            continue
        if (
            not address_matches
            and (
                operand.startswith("$")
                or operand.lower().startswith("short ")
                or DECORATED_RE.search(operand) is None
            )
        ):
            continue
        result.append(index)
    return tuple(result)


def _compiler_destructor_provider_bridges(
    expected: Sequence[Mapping[str, Any]],
    candidate: CandidateAssembly,
    *,
    retail_instructions: Sequence[Instruction] = (),
    document: ProgressDocument,
    caller_identity: str,
    caller_start: str,
    caller_end_exclusive: str,
    indexes: IdentityIndexes,
    bridge_names: Mapping[str, Any],
    bridge: BinaryNinjaBridge,
    compiler_generated_bridges: Mapping[str, str] | None = None,
    registered_regex_bridges: Mapping[str, str] | None = None,
    candidate_storage_bridges: Mapping[str, str] | None = None,
) -> dict[str, str]:
    base_bridges = dict(compiler_generated_bridges or {})
    exact_registered_bridges = dict(registered_regex_bridges or {})
    candidate_names = _candidate_unresolved_complete_destructors(
        candidate,
        indexes=indexes,
        bridge_names=bridge_names,
    )
    zsnd_vector_dtor_bridge = _zsnd_static_vector_dtor_candidate_bridge(
        expected,
        candidate,
        retail_instructions,
        caller_identity=caller_identity,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
        indexes=indexes,
        bridge=bridge,
    )
    if zsnd_vector_dtor_bridge:
        if set(candidate_names) != set(zsnd_vector_dtor_bridge):
            raise ValueError(
                "zSnd E4 vector-dtor bridge rejects extra or missing candidate destructor population"
            )
        return zsnd_vector_dtor_bridge
    if not candidate_names:
        return {}
    bridge_collisions = set(candidate_names) & set(base_bridges)
    generic_collisions = bridge_collisions - set(exact_registered_bridges)
    if generic_collisions:
        raise ValueError(
            "compiler destructor bridge collides with another reviewed bridge: "
            + ", ".join(repr(name) for name in sorted(generic_collisions))
        )
    if bridge_collisions:
        if any(
            base_bridges[name] != exact_registered_bridges.get(name)
            for name in bridge_collisions
        ):
            raise ValueError(
                "compiler destructor bridge registered-regex arbitration "
                "has conflicting supplied identities: "
                + ", ".join(
                    repr(name) for name in sorted(bridge_collisions)
                )
            )
        independently_proven = (
            _registered_target_symbol_regex_direct_candidate_bridges(
                candidate,
                document=document,
                indexes=indexes,
                bridge_names=bridge_names,
                compiler_generated_bridges={},
            )
        )
        if any(
            independently_proven.get(name)
            != exact_registered_bridges[name]
            for name in bridge_collisions
        ):
            raise ValueError(
                "compiler destructor bridge registered-regex arbitration "
                "lacks one independently proven identical lifecycle supplier: "
                + ", ".join(
                    repr(name) for name in sorted(bridge_collisions)
                )
            )
    provisional_identities = {
        name: f"compiler-candidate-destructor:{name}"
        for name in candidate_names
    }
    invocation_indices = _candidate_static_invocation_indices(
        candidate,
        caller_start=caller_start,
        caller_end_exclusive=caller_end_exclusive,
    )
    invocation_ordinals = {
        index: ordinal
        for ordinal, index in enumerate(invocation_indices)
    }
    provisional: list[dict[str, Any]] = []
    for candidate_name, provisional_identity in provisional_identities.items():
        listing_indices = [
            index
            for index, instruction in enumerate(candidate.instructions)
            if (
                (match := DECORATED_RE.search(
                    _instruction_operand(instruction).strip()
                ))
                is not None
                and match.group(0) == candidate_name
            )
        ]
        if (
            len(listing_indices) != 1
            or listing_indices[0] not in invocation_ordinals
        ):
            raise ValueError(
                f"compiler destructor bridge {candidate_name!r} requires one "
                "exact statically counted candidate invocation"
            )
        listing_index = listing_indices[0]
        instruction = candidate.instructions[listing_index]
        mnemonic = _instruction_mnemonic(instruction)
        provisional.append(
            {
                "ordinal": invocation_ordinals[listing_index],
                "form": "call" if mnemonic == "call" else "tail",
                "dispatch": "direct",
                "identity_kind": "direct",
                "target_identity": provisional_identity,
                "storage_identity": "",
                "slot_displacement": None,
                "cleanup_bytes": _cleanup_after(
                    candidate.instructions,
                    listing_index,
                ),
            }
        )
    resolved: dict[str, str] = {}
    for candidate_name, provisional_identity in provisional_identities.items():
        rows = [
            row
            for row in provisional
            if row.get("target_identity") == provisional_identity
        ]
        if not rows:
            raise ValueError(
                f"compiler destructor bridge {candidate_name!r} has no exact "
                "candidate invocation row"
            )
        if candidate_name in bridge_collisions:
            registered_identity = exact_registered_bridges[candidate_name]
            row = rows[0] if len(rows) == 1 else None
            if (
                row is None
                or _exact_zeroarg_destructor_row_name(candidate_name) is None
                or not registered_identity.startswith("symbol:")
                or registered_identity in indexes.provider_ids
                or row.get("form") not in {"call", "tail"}
                or row.get("dispatch") != "direct"
                or row.get("identity_kind") != "direct"
                or row.get("target_identity") != provisional_identity
                or row.get("storage_identity") != ""
                or row.get("slot_displacement") is not None
                or row.get("cleanup_bytes") is not None
            ):
                raise ValueError(
                    "compiler destructor bridge registered-regex arbitration "
                    f"rejects lifecycle decoration, direct authored identity, "
                    f"call/tail form, cleanup, or unique invocation for "
                    f"{candidate_name!r}"
                )
            resolved[candidate_name] = registered_identity
            continue
        target_identities: set[str] = set()
        target_modes: set[str] = set()
        for row in rows:
            ordinal = int(row["ordinal"])
            if ordinal >= len(expected):
                raise ValueError(
                    f"compiler destructor bridge {candidate_name!r} has no "
                    "retail invocation at the same ordinal"
                )
            expected_row = expected[ordinal]
            expected_identity = str(expected_row.get("target_identity", ""))
            is_provider = (
                expected_row.get("identity_kind") == "provider"
                and expected_identity in indexes.provider_ids
            )
            is_authored = (
                expected_row.get("identity_kind") == "direct"
                and expected_identity.startswith("symbol:")
                and expected_identity not in indexes.provider_ids
            )
            if (
                _contract_shape_without_target(expected_row)
                != _contract_shape_without_target(row)
                or not (is_provider or is_authored)
            ):
                raise ValueError(
                    f"compiler destructor bridge {candidate_name!r} is not the "
                    "same call form/dispatch/cleanup as one exact retail provider "
                    "or reviewed authored destructor"
                )
            target_identities.add(expected_identity)
            target_modes.add("provider" if is_provider else "authored")
        if len(target_identities) != 1 or len(target_modes) != 1:
            raise ValueError(
                f"compiler destructor bridge {candidate_name!r} maps to "
                "multiple or conflicting retail destructor identities"
            )
        target_identity = next(iter(target_identities))
        if target_modes == {"provider"}:
            _prove_compiler_destructor_provider_bridge(
                candidate_name,
                target_identity,
                document=document,
                candidate=candidate,
                indexes=indexes,
                bridge_names=bridge_names,
                bridge=bridge,
            )
        else:
            if target_identity in resolved.values():
                raise ValueError(
                    f"compiler destructor bridge authored target "
                    f"{target_identity!r} has duplicate candidate symbols"
                )
            if len(rows) != 1:
                raise ValueError(
                    f"compiler destructor bridge {candidate_name!r} authored "
                    "target requires one exact candidate invocation"
                )
            if not _prove_player_hud_ui_element_generated_destructor_bridge(
                candidate_name,
                target_identity,
                document=document,
                candidate=candidate,
                caller_identity=caller_identity,
                caller_start=caller_start,
                caller_end_exclusive=caller_end_exclusive,
                indexes=indexes,
                invocation_row=rows[0],
            ) and not _prove_zsnd_wave_data_generated_destructor_ordinary_body_bridge(
                candidate_name,
                target_identity,
                expected=expected,
                document=document,
                candidate=candidate,
                caller_identity=caller_identity,
                caller_start=caller_start,
                caller_end_exclusive=caller_end_exclusive,
                indexes=indexes,
                invocation_row=rows[0],
            ) and not _prove_hud_ui_string_menu_generated_destructor_bridge(
                candidate_name,
                target_identity,
                expected=expected,
                document=document,
                candidate=candidate,
                caller_identity=caller_identity,
                caller_start=caller_start,
                caller_end_exclusive=caller_end_exclusive,
                indexes=indexes,
                bridge_names=bridge_names,
                bridge=bridge,
                invocation_row=rows[0],
            ) and not _prove_hud_ui_shield_message_generated_destructor_bridge(
                candidate_name,
                target_identity,
                expected=expected,
                document=document,
                candidate=candidate,
                caller_identity=caller_identity,
                caller_start=caller_start,
                caller_end_exclusive=caller_end_exclusive,
                indexes=indexes,
                bridge_names=bridge_names,
                bridge=bridge,
                invocation_row=rows[0],
            ) and not _prove_hud_ui_message_stack_generated_destructor_bridge(
                candidate_name,
                target_identity,
                expected=expected,
                document=document,
                candidate=candidate,
                caller_identity=caller_identity,
                caller_start=caller_start,
                caller_end_exclusive=caller_end_exclusive,
                indexes=indexes,
                bridge_names=bridge_names,
                bridge=bridge,
                invocation_row=rows[0],
            ):
                _prove_compiler_destructor_authored_bridge(
                    candidate_name,
                    target_identity,
                    document=document,
                    candidate=candidate,
                    indexes=indexes,
                    invocation_row=rows[0],
                )
        resolved[candidate_name] = target_identity
    return resolved


def _coff_alias_rows_for_comparison(specs: Sequence[CoffAliasSource]) -> list[dict[str, object]]:
    inventory = load_repository_path_inventory(REPO_ROOT)
    try:
        manifest = resolve_repository_file(
            _call_contract_final_build_manifest_logical_path(),
            repository_root=inventory.repository_root,
            inventory=inventory,
            context="call-contract final-build manifest",
            allowed_suffixes={".json"},
        )
        raw = json.loads(manifest.physical_path.read_text(encoding="utf-8"))
    except (RepositoryPathError, OSError, json.JSONDecodeError) as exc:
        raise ValueError(
            f"call-contract COFF alias registry cannot be read: {exc}"
        ) from exc
    raw_rows = raw.get("coff_alias_sources") if isinstance(raw, Mapping) else None
    if not isinstance(raw_rows, list) or len(raw_rows) != len(specs):
        raise ValueError("call-contract COFF alias registry population mismatch")
    result: list[dict[str, object]] = []
    for index, (raw_row, spec) in enumerate(zip(raw_rows, specs)):
        if not isinstance(raw_row, Mapping):
            raise ValueError(
                f"call-contract COFF alias registry row {index} is malformed"
            )
        source_text = raw_row.get("source")
        link_after_text = raw_row.get("link_after_source")
        if not isinstance(source_text, str) or not isinstance(link_after_text, str):
            raise ValueError(
                f"call-contract COFF alias registry row {index} paths are malformed"
            )
        try:
            source = resolve_repository_file(
                source_text,
                repository_root=inventory.repository_root,
                inventory=inventory,
                context=f"call-contract COFF alias source[{index}]",
            )
            link_after = resolve_repository_file(
                link_after_text,
                repository_root=inventory.repository_root,
                inventory=inventory,
                context=f"call-contract COFF alias link-after source[{index}]",
                allowed_suffixes=CALL_CONTRACT_SOURCE_SUFFIXES,
            )
        except RepositoryPathError as exc:
            raise ValueError(str(exc)) from exc
        if (
            os.path.normcase(str(spec.source.resolve()))
            != os.path.normcase(str(source.physical_path))
            or os.path.normcase(str(spec.link_after_source.resolve()))
            != os.path.normcase(str(link_after.physical_path))
        ):
            raise ValueError(
                f"call-contract COFF alias registry row {index} physical path mismatch"
            )
        result.append(
            {
                "source": source.repository_path,
                "link_after_source": link_after.repository_path,
                "aliases": [
                    {"alias": item.alias, "target": item.target}
                    for item in spec.aliases
                ],
            }
        )
    return result


def _target_authorizes_final_build_coff_aliases(
    target: Any,
    *,
    specs: Sequence[CoffAliasSource],
) -> bool:
    context = str(getattr(target, "compile_context_from", "") or "")
    if context:
        context_path = Path(context)
        if not context_path.is_absolute():
            context_path = REPO_ROOT / context_path
        if context_path.resolve() == DEFAULT_FINAL_BUILD_MANIFEST.resolve():
            return True
    manifest_path = getattr(target, "manifest_path", None)
    if not isinstance(manifest_path, Path) or not manifest_path.is_file():
        return False
    raw = json.loads(manifest_path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        return False
    return raw.get("coff_alias_sources") == _coff_alias_rows_for_comparison(specs)


def _validated_final_build_coff_alias_bridges(
    candidates: Mapping[str, CandidateAssembly],
    *,
    indexes: IdentityIndexes,
    build_root: Path,
    active_targets: Iterable[Any] | None = None,
) -> dict[str, str]:
    config = load_final_build_config(DEFAULT_FINAL_BUILD_MANIFEST)
    specs = config.coff_alias_sources
    if not specs:
        return {}
    if active_targets is None:
        active_targets = {
            id(candidate.target): candidate.target
            for candidate in candidates.values()
            if candidate.target is not None
        }.values()
    if not any(
        _target_authorizes_final_build_coff_aliases(target, specs=specs)
        for target in active_targets
    ):
        return {}

    alias_config = replace(
        config,
        build_dir=(build_root / "validated-coff-alias-authority").resolve(),
        build_dir_explicit=True,
    )
    paths = final_build_paths(alias_config)
    paths.obj_dir.mkdir(parents=True, exist_ok=True)
    paths.logs_dir.mkdir(parents=True, exist_ok=True)
    paths.rsp_dir.mkdir(parents=True, exist_ok=True)
    llvm_ml = resolve_llvm_ml()
    validation_by_source: dict[str, Mapping[str, object]] = {}
    for spec in specs:
        validate_alias_source(spec)
        command = make_coff_alias_command(paths, spec, llvm_ml=llvm_ml)
        result = run_final_build_command(command)
        if result.returncode != 0:
            raise ValueError(
                f"validated COFF alias assembly failed for {spec.source} "
                f"with exit code {result.returncode}"
            )
        report = validate_alias_object(alias_object_path(paths, spec.source), spec)
        validation_by_source[str(spec.source.resolve())] = report
    return resolve_validated_coff_alias_identity_bridges(
        specs,
        validation_by_source=validation_by_source,
        indexes=indexes,
    )


def _validate_exact_zeroarg_abi_row_schema(
    raw: object,
    target: ZeroArgAbiTarget,
    *,
    index: int,
    manifest_path: Path,
) -> None:
    label = f"{manifest_path}: zeroarg_abi_equivalence[{index}]"
    if not isinstance(raw, Mapping):
        raise ValueError(f"{label} must be an object")
    expected_fields = set(ZEROARG_ABI_ROW_FIELDS)
    if "st0_policy" in raw:
        expected_fields.add("st0_policy")
    if set(raw) != expected_fields:
        raise ValueError(
            f"{label} must contain exactly "
            + ", ".join(sorted(expected_fields))
        )

    evidence = raw.get("retail_evidence")
    if (
        not isinstance(evidence, Mapping)
        or set(evidence) != ZEROARG_ABI_RETAIL_EVIDENCE_FIELDS
    ):
        raise ValueError(
            f"{label}.retail_evidence must contain the exact governed "
            "zero-argument evidence schema"
        )
    boolean_fields = ZEROARG_ABI_RETAIL_EVIDENCE_FIELDS - {
        "explicit_argument_count",
        "direct_calls",
    }
    if any(type(evidence.get(field)) is not bool for field in boolean_fields):
        raise ValueError(
            f"{label}.retail_evidence boolean fields must contain exact booleans"
        )
    if type(evidence.get("explicit_argument_count")) is not int:
        raise ValueError(
            f"{label}.retail_evidence.explicit_argument_count must be an integer"
        )
    direct_calls = evidence.get("direct_calls")
    if not isinstance(direct_calls, list) or not direct_calls:
        raise ValueError(
            f"{label}.retail_evidence.direct_calls must be a non-empty list"
        )
    direct_call_keys: set[tuple[object, ...]] = set()
    for call_index, call in enumerate(direct_calls):
        if (
            not isinstance(call, Mapping)
            or set(call) != ZEROARG_ABI_DIRECT_CALL_FIELDS
        ):
            raise ValueError(
                f"{label}.retail_evidence.direct_calls[{call_index}] must "
                "contain exactly address, dispatch, explicit_argument_count, "
                "and callee_return"
            )
        key = (
            call.get("address"),
            call.get("dispatch"),
            call.get("explicit_argument_count"),
            call.get("callee_return"),
        )
        if key in direct_call_keys:
            raise ValueError(
                f"{label}.retail_evidence.direct_calls contains a duplicate exact row"
            )
        direct_call_keys.add(key)

    eh_policy = raw.get("eh_policy")
    if not isinstance(eh_policy, Mapping):
        raise ValueError(f"{label}.eh_policy must be an object")
    expected_eh_fields = {"kind", "retail_proven"}
    if eh_policy.get("kind") == "paired-sections":
        expected_eh_fields.add("sections")
    if set(eh_policy) != expected_eh_fields:
        raise ValueError(
            f"{label}.eh_policy must contain the exact governed schema for "
            f"kind {eh_policy.get('kind')!r}"
        )
    if type(eh_policy.get("retail_proven")) is not bool:
        raise ValueError(f"{label}.eh_policy.retail_proven must be an exact boolean")

    st0_policy = raw.get("st0_policy")
    if target.return_category == "x87-float":
        if (
            not isinstance(st0_policy, Mapping)
            or set(st0_policy) != {"proven", "evidence"}
            or type(st0_policy.get("proven")) is not bool
            or not isinstance(st0_policy.get("evidence"), str)
            or not st0_policy["evidence"].strip()
        ):
            raise ValueError(
                f"{label}.st0_policy must contain exactly proven and evidence "
                "for an x87-float return"
            )
    elif "st0_policy" in raw:
        raise ValueError(
            f"{label}.st0_policy is only valid for an x87-float return"
        )


def _is_exact_zeroarg_cdecl_fastcall_pair(
    cdecl_symbol: str,
    fastcall_symbol: str,
) -> bool:
    """Recognize only exact VC5 /Gd-/Gr zero-explicit-argument decoration."""
    if cdecl_symbol.startswith("?"):
        match = re.fullmatch(
            r"(?P<prefix>\?.+@@[YS])A(?P<signature>.+XZ)",
            cdecl_symbol,
        )
        return bool(
            match is not None
            and fastcall_symbol
            == f"{match.group('prefix')}I{match.group('signature')}"
        )
    match = re.fullmatch(r"_([A-Za-z][A-Za-z0-9_?$]*)", cdecl_symbol)
    return bool(
        match is not None
        and fastcall_symbol == f"@{match.group(1)}@0"
    )


def resolve_manifest_zeroarg_abi_identity_bridges(
    document: ProgressDocument,
    *,
    indexes: IdentityIndexes,
    bridge_by_address: Mapping[str, Any],
    manifest_path: Path = DEFAULT_FINAL_BUILD_MANIFEST,
) -> dict[str, str]:
    """Resolve exact governed /Gd-/Gr no-argument names to retail identities.

    The manifest and candidate-independent tracker/retail symbol population are
    the only authorities.  The candidate object is deliberately not an input.
    """
    targets = load_zeroarg_targets(manifest_path)
    raw_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    raw_rows = (
        raw_manifest.get("zeroarg_abi_equivalence")
        if isinstance(raw_manifest, Mapping)
        else None
    )
    if not isinstance(raw_rows, list) or len(raw_rows) != len(targets):
        raise ValueError(
            f"{manifest_path}: zeroarg_abi_equivalence typed/raw row "
            "population is missing or inconsistent"
        )
    normalization = manifest_symbol_normalization(targets)

    retail_rows_by_address: dict[str, list[Any]] = {}
    retail_name_addresses: dict[str, set[str]] = {}
    for raw_address, retail_symbol in bridge_by_address.items():
        value = getattr(retail_symbol, "address", raw_address)
        try:
            address = normalize_address(str(value))
        except ProgressError:
            continue
        retail_rows_by_address.setdefault(address, []).append(retail_symbol)
        for name in {
            str(getattr(retail_symbol, "name", "") or ""),
            str(getattr(retail_symbol, "raw_name", "") or ""),
            str(getattr(retail_symbol, "full_name", "") or ""),
        }:
            if name:
                retail_name_addresses.setdefault(name, set()).add(address)

    symbols = document.collection("symbols")
    symbol_bindings: dict[str, str] = {}
    result: dict[str, str] = {}
    direct_call_bindings: dict[str, str] = {}
    for index, (raw, target) in enumerate(zip(raw_rows, targets)):
        _validate_exact_zeroarg_abi_row_schema(
            raw,
            target,
            index=index,
            manifest_path=manifest_path,
        )
        failed_gates = [
            str(gate.get("gate") or "")
            for gate in zeroarg_abi_eligibility_gates(target)
            if gate.get("passed") is not True
        ]
        if failed_gates:
            raise ValueError(
                f"{manifest_path}: zeroarg ABI row {target.target_id!r} is "
                "ineligible: "
                + ", ".join(failed_gates)
            )
        cdecl_symbol = target.callee.cdecl_symbol
        fastcall_symbol = target.callee.fastcall_symbol
        if not _is_exact_zeroarg_cdecl_fastcall_pair(
            cdecl_symbol,
            fastcall_symbol,
        ):
            raise ValueError(
                f"{manifest_path}: zeroarg ABI row {target.target_id!r} is not "
                "one exact VC5 /Gd-/Gr zero-argument decoration pair"
            )
        if (
            normalization.get(cdecl_symbol) != target.identity
            or normalization.get(fastcall_symbol) != target.identity
        ):
            raise ValueError(
                f"{manifest_path}: zeroarg ABI row {target.target_id!r} has "
                "ambiguous symbol-to-identity normalization"
            )
        for symbol_name in (cdecl_symbol, fastcall_symbol):
            prior_binding = symbol_bindings.get(symbol_name)
            if prior_binding not in {None, target.identity}:
                raise ValueError(
                    f"{manifest_path}: zeroarg ABI symbol {symbol_name!r} maps "
                    "to conflicting manifest identities"
                )
            symbol_bindings[symbol_name] = target.identity

        tracker_symbol = symbols.get(target.identity)
        raw_address = (
            tracker_symbol.get("address", tracker_symbol.get("start"))
            if isinstance(tracker_symbol, Mapping)
            else None
        )
        if (
            not isinstance(tracker_symbol, Mapping)
            or tracker_symbol.get("binary") != "recoil"
            or tracker_symbol.get("kind") != "function"
            or tracker_symbol.get("pipeline_class")
            not in {"authored", "authored-lifecycle"}
            or not isinstance(raw_address, str)
        ):
            raise ValueError(
                f"{manifest_path}: zeroarg ABI identity {target.identity!r} "
                "is not one exact authored tracker function"
            )
        address = normalize_address(raw_address)
        if target.identity != f"recoil:function:{address}":
            raise ValueError(
                f"{manifest_path}: zeroarg ABI identity {target.identity!r} "
                f"does not match tracker address {address}"
            )
        identity = f"symbol:{target.identity}"
        if indexes.by_address.get(address) != identity:
            raise ValueError(
                f"{manifest_path}: zeroarg ABI identity {target.identity!r} "
                "has ambiguous or conflicting tracker identity resolution"
            )

        retail_rows = retail_rows_by_address.get(address, [])
        cdecl_addresses = retail_name_addresses.get(cdecl_symbol, set())
        fastcall_addresses = retail_name_addresses.get(fastcall_symbol, set())
        if (
            len(retail_rows) != 1
            or getattr(retail_rows[0], "kind", "") != "function"
            or cdecl_addresses - {address}
            or fastcall_addresses - {address}
        ):
            raise ValueError(
                f"{manifest_path}: zeroarg ABI identity {target.identity!r} "
                "does not have one exact candidate-independent retail symbol mapping"
            )

        raw_evidence = raw["retail_evidence"]
        for call in raw_evidence["direct_calls"]:
            call_address = normalize_address(str(call["address"]))
            prior_target = direct_call_bindings.get(call_address)
            if prior_target not in {None, target.identity}:
                raise ValueError(
                    f"{manifest_path}: zeroarg ABI retail call evidence "
                    f"{call_address} maps to conflicting target identities"
                )
            direct_call_bindings[call_address] = target.identity

        for symbol_name in (cdecl_symbol, fastcall_symbol):
            prior = indexes.by_candidate_name.get(symbol_name)
            if prior not in {None, identity}:
                raise ValueError(
                    f"{manifest_path}: zeroarg ABI symbol {symbol_name!r} "
                    f"conflicts with current identity {prior!r}"
                )
            result[symbol_name] = identity
    return result


def _caller_isolated_diagnostic_census(
    *,
    symbol_ids: Sequence[str],
    addresses: Sequence[str],
    expected_contracts: Mapping[str, Sequence[Mapping[str, Any]]],
    candidate_contracts: Mapping[str, Sequence[Mapping[str, Any]]],
    caller_divergences: Sequence[Mapping[str, Any]],
    complete: bool,
) -> dict[str, Any]:
    """Build one fail-closed, strictly nonaccepting caller diagnostic census."""

    ordered_coordinates = list(zip(symbol_ids, addresses))
    if (
        len(ordered_coordinates) != len(symbol_ids)
        or len({symbol_id for symbol_id, _address in ordered_coordinates})
        != len(ordered_coordinates)
        or len({address for _symbol_id, address in ordered_coordinates})
        != len(ordered_coordinates)
    ):
        raise ValueError(
            "caller-isolated diagnostic census has colliding caller coordinates"
        )
    coordinate_by_symbol = dict(ordered_coordinates)
    ordinal_by_symbol = {
        symbol_id: ordinal
        for ordinal, (symbol_id, _address) in enumerate(ordered_coordinates)
    }
    divergence_rows: list[dict[str, Any]] = []
    prior_ordinal = -1
    seen: set[str] = set()
    for raw in caller_divergences:
        symbol_id = str(raw.get("symbol_id", ""))
        address = str(raw.get("address", ""))
        ordinal = ordinal_by_symbol.get(symbol_id, -1)
        if (
            ordinal < 0
            or symbol_id in seen
            or coordinate_by_symbol.get(symbol_id) != address
            or ordinal <= prior_ordinal
        ):
            raise ValueError(
                "caller-isolated diagnostic census divergence coordinates "
                "collide, drift, or are out of retail order"
            )
        seen.add(symbol_id)
        prior_ordinal = ordinal
        divergence_rows.append(deepcopy(dict(raw)))

    expected_symbols = set(expected_contracts)
    candidate_symbols = set(candidate_contracts)
    census_symbols = set(symbol_ids)
    if (
        not expected_symbols.issubset(census_symbols)
        or not candidate_symbols.issubset(census_symbols)
        or candidate_symbols != expected_symbols
    ):
        raise ValueError(
            "caller-isolated diagnostic census contract population drifted"
        )
    completed_symbols = expected_symbols | seen
    if complete and completed_symbols != census_symbols:
        raise ValueError(
            "complete caller-isolated diagnostic census omitted callers"
        )
    mismatch_count = sum(
        row.get("kind") == "mismatch" for row in divergence_rows
    )
    blocker_count = len(divergence_rows) - mismatch_count
    return {
        "kind": "authored-call-contract-caller-diagnostic-census",
        "contract_version": 1,
        "nonaccepting": True,
        "acceptance_eligible": False,
        "acceptance_route": None,
        "candidate_expected_truth": False,
        "complete": complete,
        "ordered_caller_count": len(ordered_coordinates),
        "evaluated_caller_count": len(completed_symbols),
        "passing_caller_count": len(expected_symbols - seen),
        "divergent_caller_count": len(divergence_rows),
        "semantic_mismatch_caller_count": mismatch_count,
        "verifier_blocked_caller_count": blocker_count,
        "later_divergence_count": max(0, len(divergence_rows) - 1),
        "divergences": divergence_rows,
    }


def live_call_contract_result(
    *,
    document: ProgressDocument,
    slice_id: str | None = None,
    target_id: str | None = None,
    all_authored_bodies: bool = False,
    build_root: Path,
    vc5_env: Path = DEFAULT_VC5_ENV,
    bridge_url: str = DEFAULT_BRIDGE_URL,
    bridge: BinaryNinjaBridge | None = None,
    collect_all_divergences: bool = False,
    compile_definition_closure: bool = True,
    precompiled_target_units: Mapping[
        str, tuple[Any, tuple[tuple[Any, Path, CoffObject], ...]]
    ] | None = None,
    numeric_constructor_authority: tuple[
        Any,
        dict[str, CandidateConstructorDefinition],
        dict[str, CandidateConstructorDefinition],
        dict[str, CandidateConstructorDefinition],
    ] | None = None,
    _diagnostic_comparison_context: dict[str, Any] | None = None,
    _memory_trace: _CallContractMemoryTrace | None = None,
) -> dict[str, Any]:
    memory_trace = _memory_trace or _CallContractMemoryTrace.from_environment()
    memory_trace.emit("verification-start")
    total_started = time.perf_counter()
    timings_ms = _empty_call_contract_timings_ms()
    setup_started = time.perf_counter()
    target_mode = target_id is not None
    if target_mode:
        if slice_id is not None or not all_authored_bodies:
            raise ProgressError(
                "target call-contract verification requires --target with --all-authored-bodies only"
            )
        slice_row = _resolve_target_all_authored_bodies(document, target_id)
        result_slice_id = str(slice_row["id"])
    else:
        if slice_id is None or all_authored_bodies:
            raise ProgressError(
                "slice call-contract verification requires exactly --slice"
            )
        slice_row = _resolve_slice(document, slice_id)
        result_slice_id = slice_id
    caller_total = int(slice_row["body_count"])
    memory_trace.emit(
        "selection-complete",
        caller_total=caller_total,
        selected_target_count=len(slice_row["target_ids"]),
    )
    repository_path_inventory = load_repository_path_inventory(REPO_ROOT)
    source_closure = call_contract_source_closure(
        document,
        slice_row,
        repository_path_inventory=repository_path_inventory,
    )
    target_source_edit_paths = _call_contract_target_source_edit_paths(
        slice_row,
        source_closure,
        require_explicit=False,
    )
    dependency_paths = source_dependency_paths(
        document,
        slice_row,
        source_write_paths=source_closure.source_edit_paths,
        source_closure=source_closure,
        repository_path_inventory=repository_path_inventory,
    )
    signatures_before = file_dependency_states(
        dependency_paths,
        repository_path_inventory=repository_path_inventory,
    )
    slice_targets = _call_contract_slice_targets(
        document,
        slice_row,
        repository_path_inventory=repository_path_inventory,
    )
    candidate_session = _LazyCallContractCandidateSession(
        document,
        slice_row,
        build_root=build_root,
        vc5_env=vc5_env,
        preloaded_targets=slice_targets,
        precompiled_target_units=precompiled_target_units,
        numeric_constructor_authority=numeric_constructor_authority,
    )
    memory_trace.emit(
        "source-closure-complete",
        caller_total=caller_total,
        source_edit_path_count=len(source_closure.source_edit_paths),
        header_path_count=len(source_closure.header_paths),
        definition_source_path_count=len(
            source_closure.definition_source_paths
        ),
        dependency_path_count=len(dependency_paths),
    )
    _add_elapsed_ms(
        timings_ms,
        "source_closure_dependency_setup",
        setup_started,
    )
    inventory_started = time.perf_counter()
    if bridge is None:
        bridge = _new_call_contract_bridge(
            bridge_url=bridge_url,
            body_count=int(slice_row["body_count"]),
        )
    by_address, by_name = bridge.symbols()
    bridge_data_rows = bridge.data_variables()
    # Immutable PE import truth is invocation-scoped.  Several independent
    # proof producers consume this same population; deriving it once avoids
    # rereading and reparsing the retail image for every selected caller while
    # preserving the live invocation's stat/race boundary.
    retail_import_targets = tuple(_retail_import_targets(DEFAULT_REFERENCE)[0])
    memory_trace.emit(
        "retail-inventory-complete",
        caller_total=caller_total,
        bridge_symbol_count=len(by_address),
        bridge_name_count=len(by_name),
        bridge_data_count=len(bridge_data_rows),
        retail_import_target_count=len(retail_import_targets),
    )
    _add_elapsed_ms(timings_ms, "binary_ninja_inventory", inventory_started)
    exact_bridge_names: dict[str, list[Any]] = {}
    for bridge_symbol in by_address.values():
        for name in {
            getattr(bridge_symbol, "name", ""),
            getattr(bridge_symbol, "raw_name", ""),
            getattr(bridge_symbol, "full_name", ""),
        }:
            if name:
                exact_bridge_names.setdefault(str(name), []).append(bridge_symbol)
    retail_provider_fact_transcript: list[dict[str, Any]] = []
    indexes = build_identity_indexes(
        document,
        bridge=bridge,
        retail_provider_fact_transcript=retail_provider_fact_transcript,
        bridge_by_address=by_address,
        bridge_data_rows=bridge_data_rows,
    )
    zeroarg_abi_bridges = resolve_manifest_zeroarg_abi_identity_bridges(
        document,
        indexes=indexes,
        bridge_by_address=by_address,
    )
    if zeroarg_abi_bridges:
        merged_candidate_names = dict(indexes.by_candidate_name)
        for symbol_name, identity in zeroarg_abi_bridges.items():
            prior = merged_candidate_names.get(symbol_name)
            if prior not in {None, identity}:
                raise ValueError(
                    f"validated zeroarg ABI symbol {symbol_name!r} conflicts "
                    "with current candidate identity"
                )
            merged_candidate_names[symbol_name] = identity
        indexes = replace(indexes, by_candidate_name=merged_candidate_names)
    alias_started = time.perf_counter()
    coff_alias_bridges = _validated_final_build_coff_alias_bridges(
        {},
        indexes=indexes,
        build_root=build_root,
        active_targets=slice_targets.values(),
    )
    _add_elapsed_ms(
        timings_ms,
        "target_candidate_compilation",
        alias_started,
    )
    if coff_alias_bridges:
        merged_candidate_names = dict(indexes.by_candidate_name)
        for alias, identity in coff_alias_bridges.items():
            prior = merged_candidate_names.get(alias)
            if prior is not None and prior != identity:
                raise ValueError(
                    f"validated COFF alias {alias!r} conflicts with current candidate identity"
                )
            merged_candidate_names[alias] = identity
        indexes = replace(indexes, by_candidate_name=merged_candidate_names)
    (
        ftol_provider_identity,
        ftol_retail_bridge_names,
    ) = _ftol_import_thunk_retail_bridge(
        document=document,
        indexes=indexes,
        bridge_by_address=by_address,
        bridge_by_name=by_name,
        bridge_data_rows=bridge_data_rows,
        bridge=bridge,
    )
    for name, symbols_for_name in ftol_retail_bridge_names.items():
        if name in exact_bridge_names:
            raise ValueError(
                f"MSVC _ftol import-thunk bridge name {name!r} already "
                "has a different ordinary bridge population"
            )
        exact_bridge_names[name] = symbols_for_name
    (
        gettickcount_named_import_thunk,
        gettickcount_retail_bridge_names,
    ) = _gettickcount_named_import_thunk_retail_bridge(
        document=document,
        indexes=indexes,
        bridge_by_address=by_address,
        bridge_by_name=by_name,
        bridge=bridge,
    )
    for name, symbols_for_name in gettickcount_retail_bridge_names.items():
        prior = exact_bridge_names.get(name)
        prior_addresses = {
            getattr(symbol, "address", "") for symbol in prior or ()
        }
        current_addresses = {
            getattr(symbol, "address", "") for symbol in symbols_for_name
        }
        if prior is not None and prior_addresses != current_addresses:
            raise ValueError(
                f"GetTickCount named import-thunk bridge name {name!r} "
                "collides with a different ordinary bridge population"
            )
        exact_bridge_names[name] = symbols_for_name
    preproven_named_packages: tuple[CurrentIatStoragePackage, ...] = ()
    if gettickcount_named_import_thunk is not None:
        indexes, preproven_named_packages = (
            _integrate_preproven_named_import_thunk_packages(
                indexes,
                (gettickcount_named_import_thunk,),
            )
            )
    (
        _provider_named_import_thunks,
        provider_named_import_thunk_names,
    ) = _provider_named_import_thunk_retail_bridges(
        document=document,
        indexes=indexes,
        bridge_by_address=by_address,
        bridge_by_name=by_name,
        bridge=bridge,
        additional_named_packages=preproven_named_packages,
        preproven_named_thunks=(
            (gettickcount_named_import_thunk,)
            if gettickcount_named_import_thunk is not None
            else ()
        ),
        retail_import_targets=retail_import_targets,
    )
